INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C1','kor',2,1,'u1',1,'잘 듣기(경청) — 말하는 사람을 바라보며 끼어들지 않고 끝까지 듣고, 고개를 끄덕이거나 끝난 뒤 박수로 들은 마음을 전하기',ARRAY['2국01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C2','kor',2,1,'u1',1,'소개하는 글이란 — 나를 잘 모르는 사람에게 누구인지·좋아하는 것·잘하는 것처럼 읽을 사람이 궁금해할 내용을 담아 나를 알려 주는 글임을 알기',ARRAY['2국03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C3','kor',2,1,'u1',3,'말차례의 뜻 — 대화에서 한 사람씩 차례대로 말하는 것이며, 한꺼번에 말하거나 끼어들면 알아듣기 어렵고 말하던 사람이 속상함을 알기',ARRAY['2국01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C4','kor',2,1,'u1',3,'말차례를 지키며 대화하기 — 손을 들고 기다리기·끝까지 듣기·내 차례에 또박또박 말하기, 묻는 말에 알맞게 답하고 되물어 대화를 이어 가며 모두가 고르게 말하게 하기',ARRAY['2국01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C5','kor',2,1,'u1',5,'글을 읽고 내용 파악하기 — 짧은 이야기에서 누가·무엇을·왜 했는지, 일이 일어난 차례를 글에서 찾아 말하기',ARRAY['2국01-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C6','kor',2,1,'u1',5,'인물의 마음을 짐작하고 생각 나누기 — 인물이 처한 일에서 마음과 그 까닭을 짐작하고, 「나라면?」 하고 떠올린 생각을 말차례를 지켜 나누며 다른 생각도 인정하기',ARRAY['2국01-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C7','kor',2,1,'u1',7,'소개할 내용 정리하기 — 이름·좋아하는 것·잘하는 것·꿈 같은 항목에서 읽을 사람이 궁금해할 내용을 고르고, 관계없는 내용과 개인 정보는 빼며 까닭을 더해 정리하기',ARRAY['2국03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C8','kor',2,1,'u1',9,'나를 소개하는 글 쓰기 — 「저는 ○○○입니다.」로 시작해 한 문장에 한 가지 내용씩 문장으로 이어 쓰고(끝에 마침표), 다시 읽으며 관계없는 문장을 빼고 까닭을 더해 다듬기',ARRAY['2국03-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C9','kor',2,1,'u1',11,'주변 사람 소개하기 — 「제 ○○ ○○○를 소개합니다.」로 누구인지 밝히고 잘하는 것·좋은 점·함께한 일을 존중하는 마음으로 전하며, 흉이나 전화번호·주소 같은 개인 정보는 넣지 않기',ARRAY['2국03-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u1-C10','kor',2,1,'u1',9,'발표하고 듣고 묻기 — 듣는 사람을 바라보며 알맞은 크기로 또박또박 발표하고, 들을 때는 끝까지 들은 뒤 손을 들어 내용과 관련 있는 것을 묻고 박수로 반응하기',ARRAY['2국01-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X01','kor',2,'u1',ARRAY['K2-1-u1-C1','K2-1-u1-C10']::text[],'귀로 소리만 들리면 잘 듣는 것이라고 여겨 딴 곳을 보거나 다른 일을 하며 듣는다','말하는 사람 쪽으로 몸과 눈을 돌리고, 들은 말을 한 가지 되말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X02','kor',2,'u1',ARRAY['K2-1-u1-C1','K2-1-u1-C3','K2-1-u1-C4','K2-1-u1-C10']::text[],'생각이 떠오르면 친구 말이 끝나기 전에 끼어들어 말하거나 묻는다','말하고 싶으면 손을 들고, 친구 말이 끝났는지 확인한 뒤 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X03','kor',2,'u1',ARRAY['K2-1-u1-C3','K2-1-u1-C4']::text[],'말차례를 「먼저·크게 말하는 사람이 말하는 것」으로 여긴다','「지금 누구 차례지?」 하고 차례를 먼저 살피기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X04','kor',2,'u1',ARRAY['K2-1-u1-C4','K2-1-u1-C10']::text[],'상대가 묻는 말이나 앞 사람 말과 관계없는 엉뚱한 말을 해 대화가 이어지지 않는다','앞 사람 말의 중심 낱말을 넣어 대답하거나 되묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X05','kor',2,'u1',ARRAY['K2-1-u1-C3','K2-1-u1-C4']::text[],'차례를 고르게 나누지 않는다 — 한 사람이 혼자 길게 말하거나, 내 차례에도 말하지 않고 듣기만 한다','한 번 말하면 다음 사람에게 「너는 어때?」 하고 차례 건네기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X06','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C7','K2-1-u1-C8']::text[],'소개하는 글에 나를 알려 주지 않는 내용(날씨·급식·어제 본 만화)을 넣는다','「이 문장이 나를 알려 주나?」 한 문장씩 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X07','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C7','K2-1-u1-C8','K2-1-u1-C9']::text[],'누구를 소개하는지 밝히지 않고 시작해 읽는 사람이 누구의 이야기인지 알 수 없게 쓴다','첫 문장에 「저는 ○○○입니다.」·「제 ○○ ○○○를 소개합니다.」 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X08','kor',2,'u1',ARRAY['K2-1-u1-C2','K2-1-u1-C8']::text[],'낱말만 늘어놓거나 문장 끝을 맺지 않아 문장이 되지 않게 쓴다(축구. 줄넘기. / 마침표 없음)','「누가 무엇을 어찌합니다.」로 끝까지 말해 보고 끝에 마침표 찍기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X09','kor',2,'u1',ARRAY['K2-1-u1-C8']::text[],'한 문장에 여러 내용을 몰아 써서 읽기 어렵게 만든다','「그리고」가 나오면 거기서 문장을 나누어 한 문장에 한 가지만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X10','kor',2,'u1',ARRAY['K2-1-u1-C7','K2-1-u1-C8']::text[],'소개 항목(이름·좋아하는 것·잘하는 것·꿈)을 서로 헷갈려 엉뚱한 칸에 넣는다','「좋아하는 것」은 즐기는 것, 「잘하는 것」은 솜씨, 「꿈」은 되고 싶은 것 — 항목 이름을 소리 내어 읽고 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X11','kor',2,'u1',ARRAY['K2-1-u1-C5','K2-1-u1-C9']::text[],'글을 끝까지 살피지 않아 인물이나 한 일을 바꾸어 말하거나 글에 없는 일을 말한다','「누가? 무엇을?」을 글에서 찾아 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X12','kor',2,'u1',ARRAY['K2-1-u1-C6']::text[],'인물의 마음을 일어난 일과 반대로, 또는 까닭 없이 짐작한다','「이런 일이 생기면 나는 어떤 마음일까?」를 일어난 일과 이어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X13','kor',2,'u1',ARRAY['K2-1-u1-C6','K2-1-u1-C10']::text[],'나와 다른 생각은 틀렸다고 여기거나 친구 생각을 깎아내린다','「그렇게 생각할 수도 있구나. 왜 그렇게 생각해?」 하고 되묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X14','kor',2,'u1',ARRAY['K2-1-u1-C7','K2-1-u1-C9']::text[],'소개에 흉(실수·단점)이나 전화번호·주소·비밀번호 같은 개인 정보를 넣는다','「이 사람이 들으면 기분 좋을까? 남이 알아도 괜찮을까?」 두 번 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X15','kor',2,'u1',ARRAY['K2-1-u1-C10']::text[],'발표할 때 듣는 사람을 보지 않고 종이만 보거나 작게·빠르게 말해도 된다고 여긴다','한 문장 읽고 고개 들어 친구들 보기 — 맨 뒤 친구에게 들리게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u1-X16','kor',2,'u1',ARRAY['K2-1-u1-C1','K2-1-u1-C2','K2-1-u1-C4','K2-1-u1-C8']::text[],'묻는 말을 거꾸로 읽는다 — 어긴 것↔지킨 것, 어울리지 않는 것↔어울리는 것, 빼야 할 것↔넣을 것','물음의 「않는·못한·빼야」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#1','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',1,'mc','auto','친구가 발표할 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],true,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"친구가 발표할 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"말하는 친구를 바라보며 끝까지 들어요","correct":true},{"t":"중간에 끼어들어 내 생각을 말해요","mis":"K2-1-u1-X02"},{"t":"옆 친구와 이야기하며 들어요","mis":"K2-1-u1-X01"}],"explanation":["잘 듣는 사람은 말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 떠들면 말하는 친구의 말이 끊겨요.","잘 들어 주면 말하는 친구도 기분이 좋아져요."],"variant_rule":{"alt":[{"stem":"선생님께서 이야기하실 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"선생님을 바라보며 끝까지 들어요","correct":true},{"t":"그림을 그리며 귀로만 들어요","mis":"K2-1-u1-X01"},{"t":"궁금한 것이 생기면 바로 끼어들어요","mis":"K2-1-u1-X02"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","다른 일을 하거나 끼어들면 잘 들을 수 없어요.","궁금한 것은 이야기가 끝난 뒤 손을 들고 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#2','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',1,'sa','auto','말하는 사람을 바라보며 끝까지 귀 기울여 잘 듣는 것을 두 글자로 무엇이라고 하나요?','{}'::text[],true,'{"seq":2,"concept":"K2-1-u1-C1","difficulty":1,"kind":"sa","stem":"말하는 사람을 바라보며 끝까지 귀 기울여 잘 듣는 것을 두 글자로 무엇이라고 하나요?","answer":["경청","경청하기"],"explanation":["귀 기울여 잘 듣는 것을 「경청」이라고 해요.","바라보며, 끼어들지 않고, 끝까지 들어요.","경청하면 말하는 사람의 마음까지 잘 알 수 있어요."],"variant_rule":{"alt":[{"stem":"친구 말에 귀 기울여 끝까지 잘 듣는 것을 무엇이라고 하나요?","answer":["경청","경청하기"],"explanation":["끝까지 귀 기울여 잘 듣는 것은 「경청」이에요.","말하는 친구를 바라보며 들어요.","들은 뒤에 반응을 해 주면 더 좋아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#3','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',1,'ox','auto','친구가 말할 때 딴 곳을 보아도 귀로 소리가 들리면 잘 듣는 것이에요.',ARRAY['K2-1-u1-X01']::text[],true,'{"seq":3,"concept":"K2-1-u1-C1","difficulty":1,"kind":"ox","stem":"친구가 말할 때 딴 곳을 보아도 귀로 소리가 들리면 잘 듣는 것이에요.","answer":"X","reason_options":[{"t":"말하는 사람을 바라보며 마음을 기울여 들어야 잘 듣는 것이니까","correct":true},{"t":"귀로 소리만 들리면 되니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["잘 듣기는 귀만이 아니라 눈과 마음으로 하는 거예요.","딴 곳을 보면 말하는 친구는 내 말을 안 듣는다고 느껴요.","말하는 사람을 바라보며 들어요."],"variant_rule":{"alt":[{"stem":"친구 말이 끝날 때까지 기다렸다가 내 생각을 말하는 것은 잘 듣는 태도예요.","answer":"O","reason_options":[{"t":"끼어들지 않고 끝까지 들었으니까","correct":true},{"t":"생각나면 바로 말해야 잊지 않으니까","mis":"K2-1-u1-X02"}],"explanation":["끝까지 기다렸다가 말하는 것이 잘 듣는 태도예요.","생각나는 대로 끼어들면 친구 말이 끊겨요.","잊을까 걱정되면 짧게 적어 두어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#4','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":4,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 좋아하는 것","correct":true},{"t":"어제 본 만화 줄거리","mis":"K2-1-u1-X06"},{"t":"내일 날씨","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글은 나를 알려 주는 글이에요.","좋아하는 것은 나를 잘 알려 줘요.","만화 줄거리나 날씨는 나를 알려 주지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 잘하는 것","correct":true},{"t":"오늘 급식 반찬","mis":"K2-1-u1-X06"},{"t":"버스가 오는 시간","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글에는 나를 알려 주는 내용을 담아요.","잘하는 것은 나를 잘 보여 줘요.","급식 반찬이나 버스 시간은 나와 관계가 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#5','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',2,'mc','auto','소개하는 글은 어떤 글인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":5,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"소개하는 글은 어떤 글인가요?","options":[{"t":"나를 잘 모르는 사람에게 나를 알려 주는 글","correct":true},{"t":"있었던 일을 날짜와 함께 적는 글","mis":"K2-1-u1-X06"},{"t":"물건을 쓰는 방법을 알려 주는 글","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글은 나를 알려 주는 글이에요.","이름, 좋아하는 것, 잘하는 것 같은 내용을 담아요.","읽는 사람이 나를 더 잘 알게 돼요."],"variant_rule":{"alt":[{"stem":"소개하는 글을 읽은 사람이 알 수 있는 것은 무엇인가요?","options":[{"t":"글쓴이가 누구이고 무엇을 좋아하는지","correct":true},{"t":"글쓴이가 어제 무엇을 먹었는지","mis":"K2-1-u1-X06"},{"t":"내일 날씨가 어떨지","mis":"K2-1-u1-X06"}],"explanation":["소개하는 글은 글쓴이를 알려 줘요.","누구인지, 무엇을 좋아하는지 알 수 있어요.","어제 먹은 것이나 날씨는 소개하는 글의 내용이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#6','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',2,'mc','auto','소개하는 글을 읽고 답해 보세요. 도윤이가 좋아하는 것은 무엇인가요?',ARRAY['K2-1-u1-X10','K2-1-u1-X11']::text[],true,'{"seq":6,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"소개하는 글을 읽고 답해 보세요. 도윤이가 좋아하는 것은 무엇인가요?","options":[{"t":"종이비행기 접기","correct":true},{"t":"줄넘기","mis":"K2-1-u1-X10"},{"t":"달리기","mis":"K2-1-u1-X11"}],"explanation":["「저는 종이비행기 접기를 좋아합니다.」라고 썼어요.","줄넘기는 도윤이가 잘하는 것이에요.","좋아하는 것과 잘하는 것을 가려 읽어요."],"asset":{"type":"passage","lines":["저는 한도윤입니다.","저는 종이비행기 접기를 좋아합니다.","제가 잘하는 것은 줄넘기입니다."],"title":"나를 소개합니다"},"variant_rule":{"alt":[{"stem":"소개하는 글을 읽고 답해 보세요. 다은이가 잘하는 것은 무엇인가요?","options":[{"t":"피아노 치기","correct":true},{"t":"고양이","mis":"K2-1-u1-X10"},{"t":"노래하기","mis":"K2-1-u1-X11"}],"explanation":["「제가 잘하는 것은 피아노 치기입니다.」라고 썼어요.","고양이는 다은이가 좋아하는 것이에요.","글에 나온 말을 찾아 답해요."],"asset":{"type":"passage","lines":["저는 윤다은입니다.","저는 고양이를 좋아합니다.","제가 잘하는 것은 피아노 치기입니다."],"title":"나를 소개합니다"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#7','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',2,'mc','auto','나를 소개할 때 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],true,'{"seq":7,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"나를 소개할 때 알맞은 말은 어느 것인가요?","options":[{"t":"저는 축구를 좋아합니다.","correct":true},{"t":"축구. 줄넘기.","mis":"K2-1-u1-X08"},{"t":"축구 좋아 나","mis":"K2-1-u1-X08"}],"explanation":["「저는 축구를 좋아합니다.」는 무엇을 좋아하는지 문장으로 전해요.","낱말만 늘어놓으면 무슨 뜻인지 알기 어려워요.","「저는 ~을 좋아합니다.」로 또박또박 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나를 소개할 때 알맞은 말은 어느 것인가요?","options":[{"t":"저는 그림 그리기를 잘합니다.","correct":true},{"t":"그림. 잘함.","mis":"K2-1-u1-X08"},{"t":"그림 나 잘해","mis":"K2-1-u1-X08"}],"explanation":["「저는 그림 그리기를 잘합니다.」는 문장으로 또렷하게 전해요.","낱말만 늘어놓으면 뜻이 흐려요.","문장으로 끝까지 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#8','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',2,'match','auto','듣는 사람의 모습과 알맞은 설명을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u1-C1","difficulty":2,"kind":"match","stem":"듣는 사람의 모습과 알맞은 설명을 이어 보세요.","pairs":[{"l":"친구를 바라보며 들어요","r":"잘 듣는 모습"},{"l":"친구 말을 자르고 말해요","r":"끼어드는 모습"},{"l":"옆 친구와 떠들어요","r":"듣지 않는 모습"}],"mis":"K2-1-u1-X02","explanation":["바라보며 끝까지 듣는 것이 잘 듣는 모습이에요.","말을 자르면 끼어드는 것이고, 떠들면 듣지 않는 거예요.","나는 어떤 모습인지 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 듣는 사람의 모습과 알맞은 설명을 이어 보세요.","pairs":[{"l":"고개를 끄덕이며 들어요","r":"잘 듣는 모습"},{"l":"말하는 중에 「내 말 좀!」 해요","r":"끼어드는 모습"},{"l":"엎드려 딴생각을 해요","r":"듣지 않는 모습"}],"explanation":["고개를 끄덕이면 잘 듣고 있다는 뜻이 전해져요.","말하는 중에 끼어들거나 딴생각을 하면 잘 듣지 못해요.","바라보고, 끄덕이고, 끝까지 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#9','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C2',2,'ox','auto','「어제는 비가 많이 왔습니다.」는 나를 소개하는 글에 어울리는 문장이에요.',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":9,"concept":"K2-1-u1-C2","difficulty":2,"kind":"ox","stem":"「어제는 비가 많이 왔습니다.」는 나를 소개하는 글에 어울리는 문장이에요.","answer":"X","reason_options":[{"t":"나를 알려 주는 내용이 아니니까","correct":true},{"t":"글에 문장이 많을수록 좋으니까","mis":"K2-1-u1-X06"}],"mis":"K2-1-u1-X06","explanation":["날씨는 나를 알려 주지 않아요.","소개하는 글에는 나에 대한 내용만 담아요.","문장이 많다고 좋은 소개가 되는 것이 아니에요."],"variant_rule":{"alt":[{"stem":"「제 꿈은 소방관입니다.」는 나를 소개하는 글에 어울리는 문장이에요.","answer":"O","reason_options":[{"t":"꿈은 나를 알려 주는 내용이니까","correct":true},{"t":"꿈은 아직 이루지 않은 일이라 소개할 수 없으니까","mis":"K2-1-u1-X06"}],"explanation":["꿈은 나를 잘 보여 주는 내용이에요.","아직 이루지 않았어도 소개할 수 있어요.","이름, 좋아하는 것, 잘하는 것, 꿈을 담아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_basic#10','kor',2,1,'u1','L01','g2_1_kor_u1_L01_basic','lesson_basic','K2-1-u1-C1',3,'error','auto','친구들이 발표를 들었어요. 잘 듣지 못한 친구는 누구인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C1","difficulty":3,"kind":"error","stem":"친구들이 발표를 들었어요. 잘 듣지 못한 친구는 누구인가요?","options":[{"t":"로아 — 발표 중에 「나도 그거 해 봤어!」 하고 끼어들었어요","correct":true,"mis_target":"K2-1-u1-X02"},{"t":"시우 — 발표하는 친구를 바라보며 들었어요","mis":"K2-1-u1-X16"},{"t":"예린 — 발표가 끝난 뒤 손을 들고 물었어요","mis":"K2-1-u1-X16"}],"explanation":["로아는 발표 중에 끼어들었어요.","하고 싶은 말이 있어도 발표가 끝날 때까지 기다려요.","시우와 예린이는 잘 들었어요."],"variant_rule":{"alt":[{"stem":"친구들이 이야기를 들었어요. 잘 듣지 못한 친구는 누구인가요?","options":[{"t":"준우 — 친구가 말하는 동안 창밖만 보았어요","correct":true,"mis_target":"K2-1-u1-X01"},{"t":"하린 — 고개를 끄덕이며 들었어요","mis":"K2-1-u1-X16"},{"t":"도윤 — 끝까지 듣고 박수를 쳤어요","mis":"K2-1-u1-X16"}],"explanation":["준우는 말하는 친구를 보지 않았어요.","바라보며 들어야 잘 듣는 거예요.","하린이와 도윤이는 잘 들었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#1','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',2,'mc','auto','친구가 내 말을 끝까지 잘 들어 주면 나는 어떤 마음이 들까요?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":2,"kind":"mc","stem":"친구가 내 말을 끝까지 잘 들어 주면 나는 어떤 마음이 들까요?","options":[{"t":"내 말을 소중히 여겨 주어 기분이 좋아요","correct":true},{"t":"아무도 안 듣는 것 같아 속상해요","mis":"K2-1-u1-X12"},{"t":"빨리 말을 끝내고 싶어요","mis":"K2-1-u1-X12"}],"explanation":["잘 들어 주면 말하는 사람은 존중받는다고 느껴요.","그래서 기분이 좋아지고 더 말하고 싶어져요.","나도 친구 말을 잘 들어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#2','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',2,'mc','auto','처음 만난 친구에게 나를 소개하는 글을 쓰려고 해요. 가장 먼저 쓸 내용은 무엇인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":2,"kind":"mc","stem":"처음 만난 친구에게 나를 소개하는 글을 쓰려고 해요. 가장 먼저 쓸 내용은 무엇인가요?","options":[{"t":"내 이름","correct":true},{"t":"어제 한 일","mis":"K2-1-u1-X06"},{"t":"친구의 이름","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 누구인지부터 알려요.","그래서 첫 문장에 내 이름을 써요.","어제 한 일이나 친구 이름으로 시작하면 누구 소개인지 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#3','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',3,'mc','auto','대화를 읽고 답해 보세요. 준우가 잘 듣지 못했다고 할 수 있는 까닭은 무엇인가요?',ARRAY['K2-1-u1-X16','K2-1-u1-X01']::text[],false,'{"seq":3,"concept":"K2-1-u1-C1","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 준우가 잘 듣지 못했다고 할 수 있는 까닭은 무엇인가요?","options":[{"t":"하린이를 보지 않고 하린이 말과 관계없는 말을 했어요","correct":true},{"t":"하린이가 너무 짧게 말해서예요","mis":"K2-1-u1-X16"},{"t":"「응.」 하고 대답했으니 잘 들은 거예요","mis":"K2-1-u1-X01"}],"explanation":["준우는 먼 곳을 보며 엉뚱한 말을 했어요.","대답을 했다고 잘 들은 것은 아니에요.","잘 들으면 친구 말과 이어지는 말을 할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"나 주말에 바다에 갔어."},{"who":"준우","text":"(먼 곳을 보며) 응…"},{"who":"하린","text":"파도가 정말 컸어!"},{"who":"준우","text":"아, 나 숙제 안 했다!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#4','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',3,'ox','auto','소개하는 글에는 읽을 사람이 궁금해할 내용을 골라 써요.',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":4,"concept":"K2-1-u1-C2","difficulty":3,"kind":"ox","stem":"소개하는 글에는 읽을 사람이 궁금해할 내용을 골라 써요.","answer":"O","reason_options":[{"t":"나를 잘 알려 주는 내용이어야 하니까","correct":true},{"t":"생각나는 것은 모두 써야 하니까","mis":"K2-1-u1-X06"}],"mis":"K2-1-u1-X06","explanation":["읽을 사람이 궁금해할 내용을 골라요.","생각나는 대로 다 쓰면 나와 관계없는 내용까지 섞여요.","좋아하는 것, 잘하는 것, 꿈처럼 나를 알려 주는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#5','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',3,'mc','auto','소개하는 글을 읽고 답해 보세요. 이 글에 어울리지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":5,"concept":"K2-1-u1-C2","difficulty":3,"kind":"mc","stem":"소개하는 글을 읽고 답해 보세요. 이 글에 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"오늘 아침에 버스가 늦게 왔습니다.","correct":true},{"t":"저는 곤충 관찰을 좋아합니다.","mis":"K2-1-u1-X16"},{"t":"제가 잘하는 것은 줄넘기입니다.","mis":"K2-1-u1-X16"}],"explanation":["버스가 늦게 온 일은 소율이를 알려 주지 않아요.","좋아하는 것과 잘하는 것은 소율이를 알려 주는 문장이에요.","소개하는 글에는 나를 알려 주는 문장만 넣어요."],"asset":{"type":"passage","lines":["저는 강소율입니다.","저는 곤충 관찰을 좋아합니다.","오늘 아침에 버스가 늦게 왔습니다.","제가 잘하는 것은 줄넘기입니다."],"title":"나를 소개합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#6','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',3,'error','auto','친구들이 소개하는 글에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X07','K2-1-u1-X16']::text[],false,'{"seq":6,"concept":"K2-1-u1-C2","difficulty":3,"kind":"error","stem":"친구들이 소개하는 글에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 소개하는 글은 이름 없이 좋아하는 것만 써도 돼요","correct":true,"mis_target":"K2-1-u1-X07"},{"t":"다은 — 누구의 글인지 알 수 있게 이름을 써요","mis":"K2-1-u1-X16"},{"t":"민호 — 좋아하는 것과 잘하는 것을 담아요","mis":"K2-1-u1-X16"}],"explanation":["이름이 없으면 누구를 소개하는지 알 수 없어요.","그래서 「저는 ○○○입니다.」로 시작해요.","다은이와 민호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#7','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',3,'mc','auto','발표하는 친구의 목소리가 작아 잘 들리지 않아요. 어떻게 하면 좋을까요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":7,"concept":"K2-1-u1-C1","difficulty":3,"kind":"mc","stem":"발표하는 친구의 목소리가 작아 잘 들리지 않아요. 어떻게 하면 좋을까요?","options":[{"t":"발표가 끝난 뒤 손을 들고 다시 말해 달라고 해요","correct":true},{"t":"발표 중에 「안 들려!」 하고 크게 외쳐요","mis":"K2-1-u1-X02"},{"t":"안 들리니까 그냥 다른 일을 해요","mis":"K2-1-u1-X01"}],"explanation":["발표 중에 외치면 친구 말이 끊기고 친구가 당황해요.","다른 일을 하면 더 들을 수 없어요.","끝난 뒤 정중하게 다시 말해 달라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#8','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',4,'mc','auto','두 친구가 자기를 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#9','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C2',4,'essay','teacher','처음 만난 친구에게 나를 소개하는 문장을 세 문장 써 보세요. 첫 문장은 내 이름으로 시작해요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C2","difficulty":4,"kind":"essay","stem":"처음 만난 친구에게 나를 소개하는 문장을 세 문장 써 보세요. 첫 문장은 내 이름으로 시작해요.","answer_guide":{"answer":"예: 저는 김하늘입니다. / 저는 공룡 책 읽기를 좋아합니다. / 제가 잘하는 것은 달리기입니다.","scoring_points":["「저는 ○○○입니다.」로 시작했는가","나를 알려 주는 내용(좋아하는 것·잘하는 것·꿈)을 담았는가","한 문장에 한 가지씩 문장으로 썼는가"]},"explanation":["이름으로 시작하기.","나를 알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L01_challenge#10','kor',2,1,'u1','L01','g2_1_kor_u1_L01_challenge','lesson_challenge','K2-1-u1-C1',4,'essay','teacher','친구의 말을 잘 들어야 하는 까닭을 쓰고, 내가 지킬 듣기 약속을 한 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C1","difficulty":4,"kind":"essay","stem":"친구의 말을 잘 들어야 하는 까닭을 쓰고, 내가 지킬 듣기 약속을 한 가지 써 보세요.","answer_guide":{"answer":"예: 잘 들어야 친구의 생각과 마음을 알 수 있기 때문입니다. 저는 친구가 말할 때 끝까지 바라보며 듣겠습니다.","scoring_points":["잘 들어야 하는 까닭을 썼는가","지킬 수 있는 듣기 약속을 썼는가","바라보기·끝까지·끼어들지 않기 가운데 하나가 드러났는가"]},"explanation":["까닭.","약속.","바라보며 끝까지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#1','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',1,'mc','auto','말차례란 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],true,'{"seq":1,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"말차례란 무엇인가요?","options":[{"t":"대화할 때 한 사람씩 차례대로 말하는 것","correct":true},{"t":"먼저 큰 소리로 말하는 사람이 말하는 것","mis":"K2-1-u1-X03"},{"t":"한 사람만 계속 말하는 것","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","목소리가 크거나 먼저 말한다고 차례가 되는 것이 아니에요.","모두가 돌아가며 말해요."],"variant_rule":{"alt":[{"stem":"여러 친구가 한꺼번에 말하면 어떻게 될까요?","options":[{"t":"무슨 말인지 알아듣기 어려워요","correct":true},{"t":"말이 더 잘 들려요","mis":"K2-1-u1-X03"},{"t":"이야기가 더 빨리 끝나서 좋아요","mis":"K2-1-u1-X03"}],"explanation":["한꺼번에 말하면 말소리가 섞여요.","그래서 서로의 말을 알아듣기 어려워요.","그래서 말차례가 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#2','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',1,'sa','auto','대화할 때 한 사람씩 차례대로 말하는 것을 무엇이라고 하나요?','{}'::text[],true,'{"seq":2,"concept":"K2-1-u1-C3","difficulty":1,"kind":"sa","stem":"대화할 때 한 사람씩 차례대로 말하는 것을 무엇이라고 하나요?","answer":["말차례","말 차례"],"explanation":["한 사람씩 차례대로 말하는 것을 「말차례」라고 해요.","내 차례가 올 때까지 기다려요.","다른 사람이 말할 때는 잘 들어요."],"variant_rule":{"alt":[{"stem":"내 차례가 올 때까지 기다렸다가 말하는 것은 무엇을 지키는 것인가요?","answer":["말차례","말 차례","말차례 지키기"],"explanation":["차례를 기다렸다 말하는 것은 「말차례」를 지키는 거예요.","끼어들지 않고 기다려요.","내 차례가 되면 또박또박 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#3','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',1,'mc','auto','말차례를 지키지 못한 행동은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],true,'{"seq":3,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 지키지 못한 행동은 어느 것인가요?","options":[{"t":"친구가 말하는데 끼어들기","correct":true},{"t":"손 들고 기다리기","mis":"K2-1-u1-X16"},{"t":"끝까지 잘 듣기","mis":"K2-1-u1-X16"}],"explanation":["끼어드는 것은 말차례를 어긴 거예요.","손 들고 기다리기, 끝까지 듣기는 말차례를 지킨 행동이에요.","묻는 말을 끝까지 읽어요 — 「지키지 못한」 행동을 찾아요."],"variant_rule":{"alt":[{"stem":"말차례를 잘 지킨 행동은 어느 것인가요?","options":[{"t":"친구 말이 끝난 뒤 내 차례에 말하기","correct":true},{"t":"생각나면 바로 끼어들기","mis":"K2-1-u1-X02"},{"t":"친구보다 먼저 크게 말하기","mis":"K2-1-u1-X03"}],"explanation":["친구 말이 끝나면 내 차례에 말해요.","끼어들거나 먼저 크게 말하면 말차례를 어긴 거예요.","차례를 기다리면 모두의 말이 잘 들려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#4','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',1,'ox','auto','말하고 싶을 때는 손을 들고 기다려요.',ARRAY['K2-1-u1-X02']::text[],true,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"ox","stem":"말하고 싶을 때는 손을 들고 기다려요.","answer":"O","reason_options":[{"t":"차례가 와서 말해야 모두의 말이 잘 들리니까","correct":true},{"t":"손을 들면 바로 말해도 되니까","mis":"K2-1-u1-X02"}],"mis":"K2-1-u1-X02","explanation":["손을 드는 것은 「말하고 싶어요.」라는 신호예요.","손을 들고 차례가 올 때까지 기다려요.","차례가 되면 또박또박 말해요."],"variant_rule":{"alt":[{"stem":"생각이 떠오르면 친구 말을 끊고 바로 말해도 돼요.","answer":"X","reason_options":[{"t":"친구 말을 끝까지 듣고 내 차례에 말해야 하니까","correct":true},{"t":"잊어버리기 전에 말하는 게 더 중요하니까","mis":"K2-1-u1-X02"}],"explanation":["친구 말을 끊으면 말차례를 어기는 거예요.","친구 말이 끝날 때까지 기다려요.","잊을까 걱정되면 짧게 적어 두어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#5','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',2,'mc','auto','대화를 읽고 답해 보세요. 두 친구의 대화에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u1-X05','K2-1-u1-X11']::text[],true,'{"seq":5,"concept":"K2-1-u1-C3","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 두 친구의 대화에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"한 사람씩 차례로 말해 이야기가 잘 이어져요","correct":true},{"t":"서아만 계속 말했어요","mis":"K2-1-u1-X05"},{"t":"두 친구가 동시에 말했어요","mis":"K2-1-u1-X11"}],"explanation":["서아가 묻고, 지우가 답하고, 다시 서아가 물었어요.","한 사람씩 차례로 말했어요.","그래서 이야기가 차근차근 이어졌어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"너는 어떤 동물을 키우고 싶어?"},{"who":"지우","text":"나는 강아지를 키우고 싶어."},{"who":"서아","text":"왜 강아지야?"},{"who":"지우","text":"같이 산책하고 싶어서."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 이 대화에서 아쉬운 점은 무엇인가요?","options":[{"t":"시우가 하람이 말을 끝까지 듣지 않고 끼어들었어요","correct":true},{"t":"하람이가 너무 천천히 말했어요","mis":"K2-1-u1-X16"},{"t":"아쉬운 점이 없어요","mis":"K2-1-u1-X02"}],"explanation":["하람이가 말하는 중에 시우가 끼어들었어요.","하람이는 하던 말을 끝내지 못했어요.","친구 말이 끝난 뒤 내 차례에 말해요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"어제 공원에 가서…"},{"who":"시우","text":"나도! 나도 공원 갔어!"},{"who":"하람","text":"내 말 좀 끝까지…"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#6','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',2,'mc','auto','짝이 「좋아하는 음식이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],true,'{"seq":6,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「좋아하는 음식이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「나는 떡볶이를 좋아해. 너는?」","correct":true},{"t":"「나 어제 축구했어!」","mis":"K2-1-u1-X04"},{"t":"「몰라. 그런데 오늘 비 온대.」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 「너는?」 하고 짝에게 차례를 건넸어요.","묻는 말과 관계없는 말을 하면 대화가 이어지지 않아요."],"variant_rule":{"alt":[{"stem":"짝이 「주말에 뭐 했어?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「할머니 댁에 갔어. 너는 뭐 했어?」","correct":true},{"t":"「나 연필 새로 샀다!」","mis":"K2-1-u1-X04"},{"t":"「응.」","mis":"K2-1-u1-X05"}],"explanation":["묻는 말에 맞게 대답하고 짝에게 되물었어요.","관계없는 말이나 「응.」만 하면 대화가 끊겨요.","대답하고 차례를 건네요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#7','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',2,'match','auto','말차례를 지키는 방법을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u1-C4","difficulty":2,"kind":"match","stem":"말차례를 지키는 방법을 알맞게 이어 보세요.","pairs":[{"l":"말하고 싶을 때","r":"손을 들고 기다려요"},{"l":"친구가 말할 때","r":"끝까지 들어요"},{"l":"내 차례가 되면","r":"또박또박 말해요"}],"mis":"K2-1-u1-X02","explanation":["말하고 싶으면 손을 들고 기다려요.","친구 말은 끝까지 들어요.","내 차례가 되면 또박또박 말해요."],"variant_rule":{"alt":[{"stem":"대화할 때 할 일을 알맞게 이어 보세요.","pairs":[{"l":"짝이 물어보면","r":"묻는 말에 맞게 대답해요"},{"l":"대답한 뒤에는","r":"짝에게도 물어봐요"},{"l":"친구 말이 안 끝났으면","r":"기다려요"}],"explanation":["묻는 말에 맞게 대답해요.","대답한 뒤에는 짝에게 되물어 차례를 건네요.","친구 말이 끝날 때까지 기다려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#8','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',2,'mc','auto','친구가 말하는데 끼어들면 말하던 친구는 어떤 마음이 들까요?',ARRAY['K2-1-u1-X03']::text[],true,'{"seq":8,"concept":"K2-1-u1-C3","difficulty":2,"kind":"mc","stem":"친구가 말하는데 끼어들면 말하던 친구는 어떤 마음이 들까요?","options":[{"t":"속상하고 더 말하기 싫어져요","correct":true},{"t":"기분이 좋아져요","mis":"K2-1-u1-X03"},{"t":"아무렇지 않아요","mis":"K2-1-u1-X03"}],"explanation":["말이 끊기면 하고 싶은 말을 다 못 해요.","그래서 속상하고 말할 기운이 없어져요.","친구 말이 끝날 때까지 기다려요."],"variant_rule":{"alt":[{"stem":"말차례를 지켜 대화하면 어떤 점이 좋을까요?","options":[{"t":"서로의 말이 잘 들리고 마음도 잘 통해요","correct":true},{"t":"목소리가 큰 사람만 말할 수 있어요","mis":"K2-1-u1-X03"},{"t":"대화가 금방 끝나요","mis":"K2-1-u1-X03"}],"explanation":["차례대로 말하면 말소리가 섞이지 않아요.","서로의 말을 잘 듣게 되어 마음도 잘 통해요.","모두가 돌아가며 말할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#9','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C3',2,'ox','auto','말차례를 지키면 한 사람이 혼자 오래 말해도 괜찮아요.',ARRAY['K2-1-u1-X05']::text[],true,'{"seq":9,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"말차례를 지키면 한 사람이 혼자 오래 말해도 괜찮아요.","answer":"X","reason_options":[{"t":"모두가 돌아가며 말할 수 있게 해야 하니까","correct":true},{"t":"먼저 말을 시작한 사람이 끝까지 말해야 하니까","mis":"K2-1-u1-X05"}],"mis":"K2-1-u1-X05","explanation":["말차례는 모두가 돌아가며 말하는 거예요.","한 사람이 오래 말하면 다른 친구는 말할 차례가 없어요.","내 말을 마치면 다음 친구에게 차례를 건네요."],"variant_rule":{"alt":[{"stem":"모둠에서 이야기할 때는 친구들도 말할 수 있게 돌아가며 말해요.","answer":"O","reason_options":[{"t":"말차례는 모두가 차례로 말하는 것이니까","correct":true},{"t":"말을 잘하는 친구만 말하면 되니까","mis":"K2-1-u1-X05"}],"explanation":["모두가 돌아가며 말해요.","말을 잘하는 친구만 말하면 다른 친구의 생각을 들을 수 없어요.","「너는 어때?」 하고 차례를 건네요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_basic#10','kor',2,1,'u1','L03','g2_1_kor_u1_L03_basic','lesson_basic','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 목소리가 큰 사람이 먼저 말하는 게 말차례예요","correct":true,"mis_target":"K2-1-u1-X03"},{"t":"소율 — 한 사람씩 차례대로 말해요","mis":"K2-1-u1-X16"},{"t":"예린 — 다른 사람 말을 끝까지 들어요","mis":"K2-1-u1-X16"}],"explanation":["목소리가 크다고 먼저 말하는 것이 아니에요.","말차례는 한 사람씩 차례대로 말하는 거예요.","소율이와 예린이는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 먼저 말하기 시작한 사람이 끝까지 혼자 말해요","correct":true,"mis_target":"K2-1-u1-X05"},{"t":"태민 — 말하고 싶으면 손을 들어요","mis":"K2-1-u1-X16"},{"t":"지호 — 내 차례에 또박또박 말해요","mis":"K2-1-u1-X16"}],"explanation":["한 사람이 혼자 말하면 다른 친구는 말할 수 없어요.","모두가 돌아가며 말해요.","태민이와 지호는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#1','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',2,'mc','auto','말차례가 필요한 까닭은 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":1,"concept":"K2-1-u1-C3","difficulty":2,"kind":"mc","stem":"말차례가 필요한 까닭은 무엇인가요?","options":[{"t":"서로의 말을 잘 듣고 이야기를 이어 가기 위해서","correct":true},{"t":"이야기를 빨리 끝내기 위해서","mis":"K2-1-u1-X03"},{"t":"말 잘하는 친구만 말하게 하려고","mis":"K2-1-u1-X05"}],"explanation":["차례대로 말하면 서로의 말이 잘 들려요.","그래서 이야기가 차근차근 이어져요.","모두가 말할 기회를 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#2','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',2,'mc','auto','친구와 동시에 말을 시작했어요. 어떻게 하면 좋을까요?',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":2,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"친구와 동시에 말을 시작했어요. 어떻게 하면 좋을까요?","options":[{"t":"「먼저 말해.」 하고 친구에게 차례를 양보해요","correct":true},{"t":"목소리를 더 크게 해서 끝까지 말해요","mis":"K2-1-u1-X03"},{"t":"친구 말을 막고 내가 먼저라고 말해요","mis":"K2-1-u1-X03"}],"explanation":["동시에 말하면 둘 다 들리지 않아요.","한 사람이 양보하고 끝까지 들은 뒤 말해요.","크게 말하거나 막는 것은 말차례를 어기는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#3','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',3,'mc','auto','대화를 읽고 답해 보세요. 도윤이가 이어서 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":3,"concept":"K2-1-u1-C4","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이가 이어서 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 과일을 가져갈래. 같이 나눠 먹자.」","correct":true},{"t":"「나 어제 게임에서 이겼어!」","mis":"K2-1-u1-X04"},{"t":"「김밥은 맛없어. 그런 걸 왜 가져가?」","mis":"K2-1-u1-X13"}],"explanation":["다은이는 「너는?」 하고 도윤이에게 차례를 건넸어요.","도윤이는 소풍에 무엇을 가져갈지 대답해야 해요.","친구 말을 깎아내리거나 관계없는 말을 하면 대화가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"이번 소풍 때 뭐 가져갈 거야?"},{"who":"다은","text":"나는 김밥을 가져갈 거야. 너는?"},{"who":"도윤","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#4','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',3,'ox','auto','말차례를 지키려면 아무 말도 하지 않고 듣기만 하면 돼요.',ARRAY['K2-1-u1-X05']::text[],false,'{"seq":4,"concept":"K2-1-u1-C3","difficulty":3,"kind":"ox","stem":"말차례를 지키려면 아무 말도 하지 않고 듣기만 하면 돼요.","answer":"X","reason_options":[{"t":"듣고 나서 내 차례에는 내 생각을 말해야 하니까","correct":true},{"t":"말을 안 하면 끼어들 일이 없으니까","mis":"K2-1-u1-X05"}],"mis":"K2-1-u1-X05","explanation":["말차례는 듣기와 말하기가 번갈아 이어지는 거예요.","내 차례가 오면 내 생각을 말해요.","듣기만 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#5','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',3,'mc','auto','대화를 읽고 답해 보세요. 이 대화에서 생긴 문제는 무엇인가요?',ARRAY['K2-1-u1-X16','K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C3","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 이 대화에서 생긴 문제는 무엇인가요?","options":[{"t":"두 친구가 서로 말을 끊어 무슨 말인지 알기 어려워요","correct":true},{"t":"민호가 질문을 해서 생긴 문제예요","mis":"K2-1-u1-X16"},{"t":"놀이 이름이 어려워서 생긴 문제예요","mis":"K2-1-u1-X11"}],"explanation":["로아와 지안이는 서로 말을 끊었어요.","그래서 둘 다 하고 싶은 말을 끝내지 못했어요.","한 사람씩 끝까지 말하고 들어요."],"asset":{"type":"speech","turns":[{"who":"민호","text":"우리 무슨 놀이 할까?"},{"who":"로아","text":"술래잡기!"},{"who":"지안","text":"아니야, 공놀이가…"},{"who":"로아","text":"술래잡기가 더 재밌…"},{"who":"지안","text":"공놀이가 더…"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#6','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',3,'error','auto','친구들이 말차례를 지키는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X16']::text[],false,'{"seq":6,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"친구들이 말차례를 지키는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 내 생각이 맞으면 친구 말을 끊어도 돼요","correct":true,"mis_target":"K2-1-u1-X02"},{"t":"서윤 — 말하고 싶으면 손을 들고 기다려요","mis":"K2-1-u1-X16"},{"t":"태민 — 친구 말이 끝나면 내 차례에 말해요","mis":"K2-1-u1-X16"}],"explanation":["내 생각이 맞아도 친구 말을 끊으면 안 돼요.","친구 말이 끝난 뒤 말해요.","서윤이와 태민이는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#7','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',3,'mc','auto','모둠에서 한 번도 말하지 못한 친구가 있어요. 어떻게 하면 좋을까요?',ARRAY['K2-1-u1-X05']::text[],false,'{"seq":7,"concept":"K2-1-u1-C4","difficulty":3,"kind":"mc","stem":"모둠에서 한 번도 말하지 못한 친구가 있어요. 어떻게 하면 좋을까요?","options":[{"t":"「너는 어떻게 생각해?」 하고 차례를 건네요","correct":true},{"t":"말하지 않는 친구는 그냥 두어요","mis":"K2-1-u1-X05"},{"t":"내가 대신 더 많이 말해요","mis":"K2-1-u1-X05"}],"explanation":["말차례는 모두가 돌아가며 말하는 거예요.","말하지 못한 친구에게 차례를 건네요.","그러면 모두의 생각을 들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#8','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',4,'mc','auto','세 모둠이 이야기를 나눴어요. 말차례를 가장 잘 지킨 모둠은 어디인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X03']::text[],false,'{"seq":8,"concept":"K2-1-u1-C3","difficulty":4,"kind":"mc","stem":"세 모둠이 이야기를 나눴어요. 말차례를 가장 잘 지킨 모둠은 어디인가요?","options":[{"t":"가 모둠 — 한 사람씩 돌아가며 말하고, 다른 친구는 끝까지 들었어요","correct":true},{"t":"나 모둠 — 하고 싶은 말이 있으면 누구든 바로 말했어요","mis":"K2-1-u1-X02"},{"t":"다 모둠 — 목소리가 큰 친구가 주로 말했어요","mis":"K2-1-u1-X03"}],"explanation":["가 모둠은 한 사람씩 돌아가며 말했어요.","나 모둠은 끼어들기, 다 모둠은 한 사람만 말하기가 생겨요.","차례대로, 끝까지 듣기, 고르게 말하기를 함께 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#9','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C3',4,'essay','teacher','말차례를 지키지 않아 생긴 일을 떠올리거나 상상해서 쓰고, 어떻게 하면 좋았을지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C3","difficulty":4,"kind":"essay","stem":"말차례를 지키지 않아 생긴 일을 떠올리거나 상상해서 쓰고, 어떻게 하면 좋았을지 써 보세요.","answer_guide":{"answer":"예: 모둠에서 모두 한꺼번에 말해서 무엇을 정했는지 아무도 몰랐습니다. 손을 들고 한 사람씩 말했으면 좋았을 것입니다.","scoring_points":["말차례를 지키지 않은 일을 썼는가","그 때문에 생긴 문제를 썼는가","말차례를 지키는 방법으로 고쳐 썼는가"]},"explanation":["일어난 일.","생긴 문제.","고치는 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L03_challenge#10','kor',2,1,'u1','L03','g2_1_kor_u1_L03_challenge','lesson_challenge','K2-1-u1-C4',4,'essay','teacher','짝에게 「좋아하는 놀이가 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「좋아하는 놀이가 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 좋아하는 놀이가 뭐야? / 짝: 나는 술래잡기를 좋아해. 너는? / 나: 나는 공기놀이를 좋아해. / 짝: 그럼 쉬는 시간에 같이 하자!","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#1','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 하람이는 무엇을 집에 두고 왔나요?',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":1,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 하람이는 무엇을 집에 두고 왔나요?","options":[{"t":"줄넘기 줄","correct":true},{"t":"공","mis":"K2-1-u1-X11"},{"t":"물통","mis":"K2-1-u1-X11"}],"explanation":["「줄넘기 줄을 집에 두고 와서」라고 나와 있어요.","공이나 물통은 이야기에 나오지 않아요.","글에서 찾아 답해요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우는 무엇을 안쪽으로 옮겼나요?","options":[{"t":"화분","correct":true},{"t":"우산","mis":"K2-1-u1-X11"},{"t":"책상","mis":"K2-1-u1-X11"}],"explanation":["「화분을 안쪽으로 옮겼어요」라고 나와 있어요.","우산이나 책상은 옮기지 않았어요.","글에서 찾아 답해요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#2','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 「내 줄로 같이 연습하자!」 하고 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":2,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 「내 줄로 같이 연습하자!」 하고 말한 친구는 누구인가요?","options":[{"t":"다은","correct":true},{"t":"하람","mis":"K2-1-u1-X11"},{"t":"선생님","mis":"K2-1-u1-X11"}],"explanation":["그 말을 한 친구는 다은이에요.","하람이는 줄을 두고 온 친구예요.","누가 한 말인지 글에서 짚어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우를 칭찬한 사람은 누구인가요?","options":[{"t":"선생님","correct":true},{"t":"시우","mis":"K2-1-u1-X11"},{"t":"친구들","mis":"K2-1-u1-X11"}],"explanation":["선생님께서 시우를 칭찬하셨어요.","칭찬을 들은 사람이 시우예요.","누가 한 말인지 글에서 짚어요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#3','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',1,'mc','auto','이야기를 읽고 답해 보세요. 줄을 함께 쓴 하람이는 어떤 마음이었을까요?',ARRAY['K2-1-u1-X12']::text[],true,'{"seq":3,"concept":"K2-1-u1-C6","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 줄을 함께 쓴 하람이는 어떤 마음이었을까요?","options":[{"t":"고맙고 기쁜 마음","correct":true},{"t":"화나는 마음","mis":"K2-1-u1-X12"},{"t":"심심한 마음","mis":"K2-1-u1-X12"}],"explanation":["하람이는 「고마워, 다은아!」 하고 활짝 웃었어요.","곤란할 때 도움을 받으면 고맙고 기뻐요.","인물이 한 말과 모습에서 마음을 찾아요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 칭찬을 들은 시우는 어떤 마음이었을까요?","options":[{"t":"쑥스럽지만 기쁜 마음","correct":true},{"t":"슬픈 마음","mis":"K2-1-u1-X12"},{"t":"무서운 마음","mis":"K2-1-u1-X12"}],"explanation":["「쑥스러웠지만 기분이 좋았어요」라고 나와 있어요.","칭찬을 들어서 기뻤어요.","글에 나온 마음을 찾아요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#4','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',1,'ox','auto','이야기를 읽고 답해 보세요. 하람이와 다은이는 한 번씩 번갈아 가며 줄을 넘었어요.',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":4,"concept":"K2-1-u1-C5","difficulty":1,"kind":"ox","stem":"이야기를 읽고 답해 보세요. 하람이와 다은이는 한 번씩 번갈아 가며 줄을 넘었어요.","answer":"O","reason_options":[{"t":"이야기에 번갈아 가며 줄을 넘었다고 나와 있으니까","correct":true},{"t":"줄이 하나뿐이라 다은이만 넘었을 테니까","mis":"K2-1-u1-X11"}],"mis":"K2-1-u1-X11","explanation":["「한 번씩 번갈아 가며 줄을 넘었어요」라고 나와 있어요.","줄이 하나여도 번갈아 쓸 수 있어요.","짐작보다 글을 먼저 살펴요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우는 비에 젖는 화분을 보고 그냥 지나갔어요.","answer":"X","reason_options":[{"t":"시우는 창문을 닫고 화분을 옮겼으니까","correct":true},{"t":"비 오는 날에는 화분을 그냥 두니까","mis":"K2-1-u1-X11"}],"explanation":["시우는 창문을 닫고 화분을 안쪽으로 옮겼어요.","그냥 지나가지 않았어요.","글에 나온 일을 찾아요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#5','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 다은이가 줄을 같이 쓰자고 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X12','K2-1-u1-X11']::text[],true,'{"seq":5,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 다은이가 줄을 같이 쓰자고 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하람이가 줄이 없어 곤란해 보였기 때문이에요","correct":true},{"t":"다은이가 줄넘기를 싫어해서예요","mis":"K2-1-u1-X12"},{"t":"선생님께서 시키셨기 때문이에요","mis":"K2-1-u1-X11"}],"explanation":["다은이는 발을 동동 구르는 하람이를 보았어요.","친구가 곤란해 보여서 돕고 싶었어요.","선생님이 시키셨다는 말은 이야기에 없어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우가 창문을 닫은 까닭은 무엇인가요?","options":[{"t":"화분이 비에 젖고 있었기 때문이에요","correct":true},{"t":"교실이 너무 더웠기 때문이에요","mis":"K2-1-u1-X11"},{"t":"선생님께서 시키셨기 때문이에요","mis":"K2-1-u1-X11"}],"explanation":["창가의 화분이 비에 흠뻑 젖고 있었어요.","그래서 시우가 창문을 닫았어요.","이야기에 나온 까닭을 찾아요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#6','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":6,"concept":"K2-1-u1-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"줄을 두고 옴 → 같이 하자고 함 → 번갈아 넘음","correct":true},{"t":"같이 하자고 함 → 줄을 두고 옴 → 번갈아 넘음","mis":"K2-1-u1-X11"},{"t":"번갈아 넘음 → 줄을 두고 옴 → 같이 하자고 함","mis":"K2-1-u1-X11"}],"explanation":["먼저 하람이가 줄을 두고 왔어요.","그다음 다은이가 같이 하자고 했고, 둘이 번갈아 넘었어요.","이야기의 앞에서부터 차례로 짚어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 내림 → 화분을 옮김 → 칭찬을 들음","correct":true},{"t":"칭찬을 들음 → 비가 내림 → 화분을 옮김","mis":"K2-1-u1-X11"},{"t":"화분을 옮김 → 칭찬을 들음 → 비가 내림","mis":"K2-1-u1-X11"}],"explanation":["먼저 비가 내렸어요.","그다음 시우가 화분을 옮겼고, 선생님께 칭찬을 들었어요.","이야기의 앞에서부터 차례로 짚어요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#7','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 친구들과 생각을 나눌 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X05']::text[],true,'{"seq":7,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 친구들과 생각을 나눌 때 바른 모습은 어느 것인가요?","options":[{"t":"내 생각을 말하고, 친구 생각도 끝까지 들어요","correct":true},{"t":"내 생각과 다르면 「틀렸어!」라고 말해요","mis":"K2-1-u1-X13"},{"t":"내 생각만 여러 번 말해요","mis":"K2-1-u1-X05"}],"explanation":["생각 나누기는 말하기와 듣기를 함께 하는 거예요.","다른 생각도 끝까지 들어요.","내 생각만 되풀이하면 다른 친구가 말할 수 없어요."],"variant_rule":{"alt":[{"stem":"친구가 나와 다른 생각을 말했어요. 알맞은 반응은 어느 것인가요?","options":[{"t":"「그렇게 생각할 수도 있구나.」","correct":true},{"t":"「아니야, 네 생각은 틀렸어.」","mis":"K2-1-u1-X13"},{"t":"못 들은 척 내 이야기를 해요","mis":"K2-1-u1-X04"}],"explanation":["같은 글을 읽어도 생각은 여러 가지일 수 있어요.","다른 생각을 인정해 주어요.","궁금하면 「왜 그렇게 생각해?」 하고 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#8','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',2,'match','auto','이야기를 읽고, 인물과 그때의 마음을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u1-C6","difficulty":2,"kind":"match","stem":"이야기를 읽고, 인물과 그때의 마음을 이어 보세요.","pairs":[{"l":"줄을 두고 와 발을 구르는 하람","r":"걱정되는 마음"},{"l":"줄을 빌려준 다은","r":"돕고 싶은 마음"},{"l":"같이 줄을 넘은 하람","r":"고맙고 기쁜 마음"}],"mis":"K2-1-u1-X12","explanation":["줄이 없어 발을 구를 때는 걱정되었어요.","다은이는 친구를 돕고 싶었어요.","같이 줄을 넘게 된 하람이는 고맙고 기뻤어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"일어난 일과 어울리는 마음을 이어 보세요.","pairs":[{"l":"친구가 우산을 씌워 주었을 때","r":"고마운 마음"},{"l":"아끼는 연필을 잃어버렸을 때","r":"속상한 마음"},{"l":"그림 대회에서 상을 받았을 때","r":"뿌듯한 마음"}],"explanation":["도움을 받으면 고마워요.","아끼는 것을 잃으면 속상해요.","애쓴 일이 잘되면 뿌듯해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#9','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C6',2,'ox','auto','같은 이야기를 읽고 친구와 생각이 다르면 둘 중 하나는 틀린 거예요.',ARRAY['K2-1-u1-X13']::text[],true,'{"seq":9,"concept":"K2-1-u1-C6","difficulty":2,"kind":"ox","stem":"같은 이야기를 읽고 친구와 생각이 다르면 둘 중 하나는 틀린 거예요.","answer":"X","reason_options":[{"t":"같은 글을 읽어도 생각은 여러 가지일 수 있으니까","correct":true},{"t":"정답은 언제나 하나뿐이니까","mis":"K2-1-u1-X13"}],"mis":"K2-1-u1-X13","explanation":["생각은 사람마다 다를 수 있어요.","까닭이 있으면 다른 생각도 귀하게 들어요.","「왜 그렇게 생각해?」 하고 물어봐요."],"variant_rule":{"alt":[{"stem":"이야기를 읽고 「나라면 어떻게 했을까?」 하고 생각해 보면 이야기를 나누기 쉬워져요.","answer":"O","reason_options":[{"t":"내 생각을 떠올려야 나눌 수 있으니까","correct":true},{"t":"이야기는 읽기만 하면 끝이니까","mis":"K2-1-u1-X13"}],"explanation":["「나라면?」 하고 떠올리면 내 생각이 생겨요.","떠올린 생각을 친구와 나눠요.","읽기만 하고 끝내지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_basic#10','kor',2,1,'u1','L05','g2_1_kor_u1_L05_basic','lesson_basic','K2-1-u1-C5',3,'error','auto','이야기를 읽고 친구들이 내용을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X11','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C5","difficulty":3,"kind":"error","stem":"이야기를 읽고 친구들이 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 다은이가 줄을 두고 와서 하람이가 빌려주었어요","correct":true,"mis_target":"K2-1-u1-X11"},{"t":"소율 — 하람이가 줄을 두고 왔어요","mis":"K2-1-u1-X16"},{"t":"도윤 — 두 친구가 번갈아 줄을 넘었어요","mis":"K2-1-u1-X16"}],"explanation":["줄을 두고 온 친구는 하람이에요.","민호는 두 인물을 바꾸어 말했어요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["체육 시간에 줄넘기를 했어요.","하람이는 줄넘기 줄을 집에 두고 와서 발을 동동 굴렀어요.","그 모습을 본 다은이가 「내 줄로 같이 연습하자!」 하고 말했어요.","두 친구는 한 번씩 번갈아 가며 줄을 넘었어요.","하람이는 「고마워, 다은아!」 하고 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 친구들이 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 선생님께서 창문을 닫고 화분을 옮기셨어요","correct":true,"mis_target":"K2-1-u1-X11"},{"t":"지호 — 비가 와서 화분이 젖고 있었어요","mis":"K2-1-u1-X16"},{"t":"서아 — 시우가 칭찬을 들었어요","mis":"K2-1-u1-X16"}],"explanation":["창문을 닫고 화분을 옮긴 사람은 시우예요.","예린이는 인물을 바꾸어 말했어요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","교실 창가의 화분이 비에 흠뻑 젖고 있었어요.","시우가 얼른 창문을 닫고 화분을 안쪽으로 옮겼어요.","선생님께서 「시우 덕분에 꽃이 무사하구나.」 하고 칭찬하셨어요.","시우는 쑥스러웠지만 기분이 좋았어요."],"title":"빗속의 화분"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#1','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 모래성이 무너진 까닭은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":1,"concept":"K2-1-u1-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 모래성이 무너진 까닭은 무엇인가요?","options":[{"t":"큰 파도가 밀려와서","correct":true},{"t":"로아가 밟아서","mis":"K2-1-u1-X11"},{"t":"바람이 세게 불어서","mis":"K2-1-u1-X11"}],"explanation":["「큰 파도가 밀려와 모래성 한쪽이 무너졌어요」라고 나와 있어요.","로아가 밟았다거나 바람이 불었다는 말은 없어요.","까닭도 글에서 찾아요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#2','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 모래성이 무너졌을 때 로아는 어떤 마음이었을까요?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":2,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 모래성이 무너졌을 때 로아는 어떤 마음이었을까요?","options":[{"t":"속상해서 울고 싶은 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u1-X12"},{"t":"졸린 마음","mis":"K2-1-u1-X12"}],"explanation":["로아는 울먹였어요.","애써 쌓은 모래성이 무너지면 속상해요.","인물의 모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#3','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 답해 보세요. 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」라고 말한 까닭은 무엇일까요?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":3,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」라고 말한 까닭은 무엇일까요?","options":[{"t":"속상한 동생을 달래 주고 싶어서","correct":true},{"t":"모래성이 싫어져서","mis":"K2-1-u1-X12"},{"t":"집에 빨리 가고 싶어서","mis":"K2-1-u1-X12"}],"explanation":["로아가 울먹이자 지안이가 이 말을 했어요.","동생의 속상한 마음을 달래 주려는 말이에요.","말한 때와 상황을 함께 살펴요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#4','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 두 사람이 마지막에 한 일은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":4,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 두 사람이 마지막에 한 일은 무엇인가요?","options":[{"t":"무너진 곳에 조개껍데기를 꽂아 모래성을 다시 만들었어요","correct":true},{"t":"모래성을 그대로 두고 집에 갔어요","mis":"K2-1-u1-X11"},{"t":"다른 바닷가로 옮겨 갔어요","mis":"K2-1-u1-X11"}],"explanation":["마지막 문장에 조개껍데기를 꽂아 더 멋진 모래성을 만들었다고 나와요.","집에 가거나 옮겨 갔다는 말은 없어요.","이야기의 끝까지 읽어요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#5','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',3,'error','auto','이야기를 읽고 친구들이 생각을 나눴어요. 이야기와 맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X12','K2-1-u1-X16']::text[],false,'{"seq":5,"concept":"K2-1-u1-C6","difficulty":3,"kind":"error","stem":"이야기를 읽고 친구들이 생각을 나눴어요. 이야기와 맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태민 — 지안이는 동생이 울어서 짜증이 났을 것 같아","correct":true,"mis_target":"K2-1-u1-X12"},{"t":"예린 — 지안이는 동생을 아끼는 것 같아","mis":"K2-1-u1-X16"},{"t":"하린 — 나라도 다시 쌓자고 했을 거야","mis":"K2-1-u1-X16"}],"explanation":["지안이는 동생을 따뜻하게 달래 주었어요.","짜증이 났다는 짐작은 지안이의 말과 맞지 않아요.","인물이 한 말과 행동에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#6','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',3,'ox','auto','「나라면 파도가 닿지 않는 곳에 쌓았을 거야.」는 이야기를 읽고 든 내 생각으로 나눌 수 있어요.',ARRAY['K2-1-u1-X13']::text[],false,'{"seq":6,"concept":"K2-1-u1-C6","difficulty":3,"kind":"ox","stem":"「나라면 파도가 닿지 않는 곳에 쌓았을 거야.」는 이야기를 읽고 든 내 생각으로 나눌 수 있어요.","answer":"O","reason_options":[{"t":"이야기를 읽고 「나라면?」 하고 떠올린 생각이니까","correct":true},{"t":"이야기에 나온 말만 말해야 하니까","mis":"K2-1-u1-X13"}],"mis":"K2-1-u1-X13","explanation":["이야기를 읽고 떠올린 내 생각도 나눌 수 있어요.","「나라면?」은 좋은 생각 나누기예요.","친구들의 다른 생각도 들어 봐요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#7','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 서윤이가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":7,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 서윤이가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그렇구나. 왜 그렇게 생각해?」","correct":true},{"t":"「그건 틀린 생각이야.」","mis":"K2-1-u1-X13"},{"t":"「나 배고파.」","mis":"K2-1-u1-X04"}],"explanation":["준우는 서윤이와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 지안이가 참 다정한 것 같아."},{"who":"준우","text":"나는 로아가 울지 않고 다시 쌓자고 했으면 좋았을 것 같아."},{"who":"서윤","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#8','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C5',4,'mc','auto','이야기를 읽고 답해 보세요. 이야기의 차례에 맞게 늘어놓은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":8,"concept":"K2-1-u1-C5","difficulty":4,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 이야기의 차례에 맞게 늘어놓은 것은 어느 것인가요?","options":[{"t":"모래성 쌓기 → 파도에 무너짐 → 동생 달래기 → 다시 만들기","correct":true},{"t":"파도에 무너짐 → 모래성 쌓기 → 다시 만들기 → 동생 달래기","mis":"K2-1-u1-X11"},{"t":"동생 달래기 → 모래성 쌓기 → 파도에 무너짐 → 다시 만들기","mis":"K2-1-u1-X11"}],"explanation":["먼저 모래성을 쌓았고, 파도에 무너졌어요.","지안이가 동생을 달랜 뒤 둘이 다시 만들었어요.","일이 일어난 까닭과 결과를 이어 차례를 정해요."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#9','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',4,'essay','teacher','이야기를 읽고 로아에게 해 주고 싶은 말을 쓰고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C6","difficulty":4,"kind":"essay","stem":"이야기를 읽고 로아에게 해 주고 싶은 말을 쓰고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 로아야, 모래성이 무너져서 속상했지? 다시 만든 모래성이 더 멋지니까 힘내! — 애써 쌓은 것이 무너지면 누구나 속상하기 때문입니다.","scoring_points":["로아의 마음을 짐작해 말을 썼는가","그렇게 생각한 까닭을 썼는가","이야기 내용과 맞게 썼는가"]},"explanation":["하고 싶은 말.","까닭.","이야기와 맞게."],"asset":{"type":"passage","lines":["토요일에 지안이와 동생 로아가 바닷가에 갔어요.","둘은 커다란 모래성을 쌓았어요.","그런데 큰 파도가 밀려와 모래성 한쪽이 무너졌어요.","로아가 울먹이자 지안이가 「괜찮아, 다시 쌓으면 더 멋질 거야.」 하고 말했어요.","둘은 무너진 곳에 조개껍데기를 꽂아 더 멋진 모래성을 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L05_challenge#10','kor',2,1,'u1','L05','g2_1_kor_u1_L05_challenge','lesson_challenge','K2-1-u1-C6',4,'essay','teacher','이야기를 읽고 친구들과 생각을 나눌 때 지킬 약속 두 가지를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C6","difficulty":4,"kind":"essay","stem":"이야기를 읽고 친구들과 생각을 나눌 때 지킬 약속 두 가지를 써 보세요.","answer_guide":{"answer":"예: 한 사람씩 차례대로 말합니다. / 나와 생각이 달라도 끝까지 듣고 「그렇게 생각할 수도 있구나.」라고 말합니다.","scoring_points":["말차례에 관한 약속을 썼는가","다른 생각을 존중하는 약속을 썼는가","지킬 수 있게 구체적으로 썼는가"]},"explanation":["말차례.","다른 생각 존중.","구체적으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#1','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',1,'mc','auto','소개하는 글에 넣을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":1,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"소개하는 글에 넣을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 잘하는 것","correct":true},{"t":"지금 몇 시인지","mis":"K2-1-u1-X06"},{"t":"버스 도착 시간","mis":"K2-1-u1-X06"}],"explanation":["잘하는 것은 나를 잘 보여 줘요.","시간이나 버스 도착 시간은 나와 관계가 없어요.","나를 알려 주는 내용을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개하는 글에 넣을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"나의 꿈","correct":true},{"t":"오늘 날씨","mis":"K2-1-u1-X06"},{"t":"어제 본 뉴스","mis":"K2-1-u1-X06"}],"explanation":["꿈은 나를 잘 보여 줘요.","날씨나 뉴스는 나를 알려 주지 않아요.","나를 알려 주는 내용을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#2','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',1,'match','auto','소개 항목과 알맞은 예를 이어 보세요.','{}'::text[],true,'{"seq":2,"concept":"K2-1-u1-C7","difficulty":1,"kind":"match","stem":"소개 항목과 알맞은 예를 이어 보세요.","pairs":[{"l":"좋아하는 것","r":"저는 딸기를 좋아합니다."},{"l":"잘하는 것","r":"제가 잘하는 것은 달리기입니다."},{"l":"꿈","r":"제 꿈은 우주 비행사입니다."}],"mis":"K2-1-u1-X10","explanation":["좋아하는 것은 「~을 좋아합니다」로 써요.","잘하는 것은 「제가 잘하는 것은 ~입니다」로 써요.","꿈은 「제 꿈은 ~입니다」로 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개 항목과 알맞은 예를 이어 보세요.","pairs":[{"l":"이름","r":"저는 정하람입니다."},{"l":"좋아하는 것","r":"저는 공룡 책을 좋아합니다."},{"l":"잘하는 것","r":"제가 잘하는 것은 종이접기입니다."}],"explanation":["이름은 「저는 ○○○입니다」로 써요.","좋아하는 것은 「~을 좋아합니다」로 써요.","잘하는 것은 「제가 잘하는 것은 ~입니다」로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#3','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',1,'mc','auto','「제 꿈은 수의사입니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],true,'{"seq":3,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「제 꿈은 수의사입니다.」는 어떤 소개 항목인가요?","options":[{"t":"꿈","correct":true},{"t":"좋아하는 것","mis":"K2-1-u1-X10"},{"t":"잘하는 것","mis":"K2-1-u1-X10"}],"explanation":["「제 꿈은 ~입니다」는 꿈을 소개하는 문장이에요.","되고 싶은 것을 말하고 있어요.","항목 이름을 문장에서 찾아요."],"variant_rule":{"alt":[{"stem":"「제가 잘하는 것은 수영입니다.」는 어떤 소개 항목인가요?","options":[{"t":"잘하는 것","correct":true},{"t":"꿈","mis":"K2-1-u1-X10"},{"t":"이름","mis":"K2-1-u1-X10"}],"explanation":["「제가 잘하는 것은 ~입니다」는 잘하는 것을 소개해요.","솜씨를 말하고 있어요.","항목 이름을 문장에서 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#4','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',1,'ox','auto','소개할 내용을 먼저 정리하면 소개하는 글을 쓰기 쉬워요.',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":4,"concept":"K2-1-u1-C7","difficulty":1,"kind":"ox","stem":"소개할 내용을 먼저 정리하면 소개하는 글을 쓰기 쉬워요.","answer":"O","reason_options":[{"t":"무엇을 쓸지 정하고 쓰니까","correct":true},{"t":"생각나는 대로 쓰는 게 더 빠르니까","mis":"K2-1-u1-X06"}],"mis":"K2-1-u1-X06","explanation":["무엇을 쓸지 먼저 정리해요.","그러면 관계없는 내용이 섞이지 않아요.","이름·좋아하는 것·잘하는 것·꿈 차례로 정리해요."],"variant_rule":{"alt":[{"stem":"소개하는 글에는 생각나는 일을 모두 써야 해요.","answer":"X","reason_options":[{"t":"나를 알려 주는 내용만 골라 써야 하니까","correct":true},{"t":"많이 쓸수록 좋은 글이니까","mis":"K2-1-u1-X06"}],"explanation":["생각나는 일을 다 쓰면 나와 관계없는 내용도 섞여요.","나를 알려 주는 내용만 골라요.","읽을 사람이 궁금해할 것을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#5','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','처음 만난 친구가 더 궁금해할 소개는 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":5,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"처음 만난 친구가 더 궁금해할 소개는 어느 것인가요?","options":[{"t":"제가 좋아하는 놀이는 숨바꼭질입니다.","correct":true},{"t":"저는 어제 일찍 잤습니다.","mis":"K2-1-u1-X06"},{"t":"오늘은 월요일입니다.","mis":"K2-1-u1-X06"}],"explanation":["좋아하는 놀이를 알면 같이 놀 수 있어 친구가 궁금해해요.","어제 잔 시간이나 요일은 나를 알려 주지 않아요.","읽을 사람 입장에서 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 처음 만난 친구가 더 궁금해할 소개는 어느 것인가요?","options":[{"t":"제가 아끼는 물건은 할머니께서 주신 필통입니다.","correct":true},{"t":"지금 창밖에 비가 옵니다.","mis":"K2-1-u1-X06"},{"t":"저는 오늘 아침밥을 먹었습니다.","mis":"K2-1-u1-X06"}],"explanation":["아끼는 물건은 나를 잘 알려 줘요.","날씨나 아침밥은 친구가 궁금해할 내용이 아니에요.","읽을 사람 입장에서 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#6','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','「저는 그림 그리기를 좋아합니다.」에 까닭을 더한 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],true,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「저는 그림 그리기를 좋아합니다.」에 까닭을 더한 것은 어느 것인가요?","options":[{"t":"저는 그림 그리기를 좋아합니다. 생각한 것을 마음대로 그릴 수 있기 때문입니다.","correct":true},{"t":"저는 그림 그리기를 좋아합니다. 오늘은 비가 옵니다.","mis":"K2-1-u1-X06"},{"t":"저는 그림 그리기를 좋아합니다. 저는 키가 큽니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 좋아하는 까닭을 더했어요.","날씨나 키는 좋아하는 까닭이 아니에요.","까닭을 더하면 나를 더 잘 알려 줘요."],"variant_rule":{"alt":[{"stem":"「저는 축구를 좋아합니다.」에 까닭을 더한 것은 어느 것인가요?","options":[{"t":"저는 축구를 좋아합니다. 친구들과 함께 뛰면 신나기 때문입니다.","correct":true},{"t":"저는 축구를 좋아합니다. 우리 집은 3층입니다.","mis":"K2-1-u1-X06"},{"t":"저는 축구를 좋아합니다. 어제 늦잠을 잤습니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 좋아하는 까닭을 더했어요.","집 층수나 늦잠은 까닭이 아니에요.","까닭은 앞 문장과 이어져야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#7','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','소개할 내용을 정리할 때 소개하기 쉬운 차례는 어느 것인가요?',ARRAY['K2-1-u1-X07','K2-1-u1-X06']::text[],true,'{"seq":7,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"소개할 내용을 정리할 때 소개하기 쉬운 차례는 어느 것인가요?","options":[{"t":"이름 → 좋아하는 것 → 잘하는 것 → 꿈","correct":true},{"t":"잘하는 것 → 꿈 → 좋아하는 것 → 이름","mis":"K2-1-u1-X07"},{"t":"날씨 → 이름 → 급식 → 꿈","mis":"K2-1-u1-X06"}],"explanation":["누구인지 알 수 있게 이름부터 정리해요.","그다음 좋아하는 것, 잘하는 것, 꿈을 이어요.","이름이 끝에 오면 누구 이야기인지 늦게 알게 돼요."],"variant_rule":{"alt":[{"stem":"소개할 내용을 정리할 때 가장 먼저 쓸 항목은 무엇인가요?","options":[{"t":"이름","correct":true},{"t":"꿈","mis":"K2-1-u1-X07"},{"t":"오늘 한 일","mis":"K2-1-u1-X06"}],"explanation":["누구를 소개하는지 이름부터 써요.","꿈은 뒤에 이어 써요.","오늘 한 일은 소개 항목이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#8','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'mc','auto','예린이가 정리한 내용을 보고 답해 보세요. 이 정리를 보고 잘못 쓴 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],true,'{"seq":8,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"예린이가 정리한 내용을 보고 답해 보세요. 이 정리를 보고 잘못 쓴 문장은 어느 것인가요?","options":[{"t":"제가 잘하는 것은 고양이입니다.","correct":true},{"t":"저는 오예린입니다.","mis":"K2-1-u1-X16"},{"t":"제 꿈은 동물원 사육사입니다.","mis":"K2-1-u1-X16"}],"explanation":["고양이는 예린이가 좋아하는 것이에요.","잘하는 것은 줄넘기예요.","항목과 내용을 맞추어 문장으로 써요."],"asset":{"type":"passage","lines":["이름: 오예린","좋아하는 것: 고양이","잘하는 것: 줄넘기","꿈: 동물원 사육사"],"title":"소개할 내용 정리"},"variant_rule":{"alt":[{"stem":"태민이가 정리한 내용을 보고 답해 보세요. 이 정리를 보고 잘못 쓴 문장은 어느 것인가요?","options":[{"t":"제 꿈은 수영입니다.","correct":true},{"t":"저는 문태민입니다.","mis":"K2-1-u1-X16"},{"t":"저는 레고 만들기를 좋아합니다.","mis":"K2-1-u1-X16"}],"explanation":["수영은 태민이가 잘하는 것이에요.","태민이의 꿈은 건축가예요.","항목과 내용을 맞추어 문장으로 써요."],"asset":{"type":"passage","lines":["이름: 문태민","좋아하는 것: 레고 만들기","잘하는 것: 수영","꿈: 건축가"],"title":"소개할 내용 정리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#9','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',2,'ox','auto','소개하는 글에는 우리 집 주소도 꼭 넣어야 해요.',ARRAY['K2-1-u1-X14']::text[],true,'{"seq":9,"concept":"K2-1-u1-C7","difficulty":2,"kind":"ox","stem":"소개하는 글에는 우리 집 주소도 꼭 넣어야 해요.","answer":"X","reason_options":[{"t":"주소 같은 개인 정보는 소개하는 글에 넣지 않으니까","correct":true},{"t":"자세하게 쓸수록 좋은 소개니까","mis":"K2-1-u1-X14"}],"mis":"K2-1-u1-X14","explanation":["주소는 남에게 함부로 알리면 안 되는 개인 정보예요.","소개하는 글에는 넣지 않아요.","좋아하는 것, 잘하는 것처럼 나를 알려 주는 내용을 담아요."],"variant_rule":{"alt":[{"stem":"소개하는 글에 내 전화번호를 써야 친구가 나를 잘 알 수 있어요.","answer":"X","reason_options":[{"t":"전화번호는 개인 정보라서 소개하는 글에 넣지 않으니까","correct":true},{"t":"자세하게 쓸수록 좋은 소개니까","mis":"K2-1-u1-X14"}],"explanation":["전화번호는 개인 정보예요.","소개하는 글에는 넣지 않아요.","나를 알려 주는 다른 내용을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_basic#10','kor',2,1,'u1','L07','g2_1_kor_u1_L07_basic','lesson_basic','K2-1-u1-C7',3,'error','auto','친구들이 소개할 내용을 골랐어요. 알맞지 않게 고른 친구는 누구인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C7","difficulty":3,"kind":"error","stem":"친구들이 소개할 내용을 골랐어요. 알맞지 않게 고른 친구는 누구인가요?","options":[{"t":"시우 — 「오늘 급식 반찬」을 소개할 내용으로 골랐어요","correct":true,"mis_target":"K2-1-u1-X06"},{"t":"다은 — 「좋아하는 동물」을 골랐어요","mis":"K2-1-u1-X16"},{"t":"지호 — 「잘하는 운동」을 골랐어요","mis":"K2-1-u1-X16"}],"explanation":["오늘 급식 반찬은 시우를 알려 주지 않아요.","좋아하는 동물과 잘하는 운동은 나를 알려 줘요.","나를 알려 주는 내용을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 소개할 내용을 골랐어요. 알맞지 않게 고른 친구는 누구인가요?","options":[{"t":"로아 — 「어제 본 영화 줄거리」를 골랐어요","correct":true,"mis_target":"K2-1-u1-X06"},{"t":"준우 — 「내 꿈」을 골랐어요","mis":"K2-1-u1-X16"},{"t":"하린 — 「아끼는 물건」을 골랐어요","mis":"K2-1-u1-X16"}],"explanation":["영화 줄거리는 로아를 알려 주지 않아요.","꿈과 아끼는 물건은 나를 알려 줘요.","나를 알려 주는 내용을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#1','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',2,'mc','auto','소개할 내용을 고를 때 생각할 점은 무엇인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":1,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"소개할 내용을 고를 때 생각할 점은 무엇인가요?","options":[{"t":"읽을 사람이 궁금해하고 나를 잘 알려 주는 내용인가","correct":true},{"t":"글이 길어지는 내용인가","mis":"K2-1-u1-X06"},{"t":"어려운 낱말이 들어가는 내용인가","mis":"K2-1-u1-X06"}],"explanation":["읽을 사람이 궁금해할지 생각해요.","나를 잘 알려 주는지 생각해요.","길이나 어려운 낱말은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#2','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',2,'mc','auto','「제 꿈은 요리사입니다.」에 까닭을 더하려고 해요. 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「제 꿈은 요리사입니다.」에 까닭을 더하려고 해요. 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"가족에게 맛있는 음식을 만들어 주고 싶기 때문입니다.","correct":true},{"t":"어제 저녁에 라면을 먹었기 때문입니다.","mis":"K2-1-u1-X06"},{"t":"요리사는 하얀 모자를 씁니다.","mis":"K2-1-u1-X06"}],"explanation":["요리사가 되고 싶은 까닭을 더했어요.","어제 먹은 라면이나 요리사의 모자는 꿈의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#3','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'mc','auto','도윤이가 정리한 내용을 보고 답해 보세요. 고쳐야 할 곳은 어디인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":3,"concept":"K2-1-u1-C7","difficulty":3,"kind":"mc","stem":"도윤이가 정리한 내용을 보고 답해 보세요. 고쳐야 할 곳은 어디인가요?","options":[{"t":"「잘하는 것」 칸에 꿈을 썼어요","correct":true},{"t":"이름 칸에 이름을 썼어요","mis":"K2-1-u1-X16"},{"t":"좋아하는 것 칸에 놀이를 썼어요","mis":"K2-1-u1-X16"}],"explanation":["「경찰관」은 되고 싶은 것, 곧 꿈이에요.","그래서 꿈 칸으로 옮기고, 잘하는 것 칸에는 솜씨를 써요.","항목 이름과 내용이 맞는지 살펴요."],"asset":{"type":"passage","lines":["이름: 한도윤","좋아하는 것: 레고 만들기","잘하는 것: 경찰관","꿈: (비어 있음)"],"title":"소개할 내용 정리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#4','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'error','auto','친구들이 소개할 내용에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X10','K2-1-u1-X16']::text[],false,'{"seq":4,"concept":"K2-1-u1-C7","difficulty":3,"kind":"error","stem":"친구들이 소개할 내용에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 좋아하는 것과 잘하는 것은 언제나 같은 거예요","correct":true,"mis_target":"K2-1-u1-X10"},{"t":"소율 — 좋아하는 것에 까닭을 더하면 나를 더 잘 알려 줘요","mis":"K2-1-u1-X16"},{"t":"민호 — 읽을 사람이 궁금해할 것을 골라요","mis":"K2-1-u1-X16"}],"explanation":["좋아하는 것과 잘하는 것은 다를 수 있어요.","노래를 좋아해도 잘하는 것은 달리기일 수 있어요.","항목을 나누어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#5','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'ox','auto','좋아하는 것과 잘하는 것은 다를 수 있어요.',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":5,"concept":"K2-1-u1-C7","difficulty":3,"kind":"ox","stem":"좋아하는 것과 잘하는 것은 다를 수 있어요.","answer":"O","reason_options":[{"t":"좋아해도 아직 잘 못할 수 있고, 잘해도 덜 좋아할 수 있으니까","correct":true},{"t":"좋아하면 언제나 잘하게 되니까","mis":"K2-1-u1-X10"}],"mis":"K2-1-u1-X10","explanation":["좋아하는 것과 잘하는 것은 서로 다른 항목이에요.","둘이 같을 때도 있지만 다를 때도 있어요.","그래서 따로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#6','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'mc','auto','새 짝에게 나를 소개하려고 해요. 빼는 것이 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":3,"kind":"mc","stem":"새 짝에게 나를 소개하려고 해요. 빼는 것이 좋은 내용은 어느 것인가요?","options":[{"t":"우리 집 현관 비밀번호","correct":true},{"t":"좋아하는 놀이","mis":"K2-1-u1-X16"},{"t":"잘하는 운동","mis":"K2-1-u1-X16"}],"explanation":["비밀번호는 남에게 알리면 안 되는 개인 정보예요.","좋아하는 놀이와 잘하는 운동은 소개에 넣어요.","묻는 말 「빼는 것」을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#7','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',3,'mc','auto','「저는 책 읽기를 좋아합니다.」 뒤에 이어 쓰기 가장 알맞은 문장은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":7,"concept":"K2-1-u1-C7","difficulty":3,"kind":"mc","stem":"「저는 책 읽기를 좋아합니다.」 뒤에 이어 쓰기 가장 알맞은 문장은 어느 것인가요?","options":[{"t":"특히 공룡이 나오는 책을 좋아합니다.","correct":true},{"t":"어제는 늦잠을 잤습니다.","mis":"K2-1-u1-X06"},{"t":"제 동생은 우유를 싫어합니다.","mis":"K2-1-u1-X06"}],"explanation":["좋아하는 책을 더 자세히 알려 주는 문장이에요.","늦잠이나 동생 이야기는 앞 문장과 이어지지 않아요.","앞 문장의 내용을 더 자세히 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#8','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',4,'mc','auto','두 친구가 소개할 내용을 정리했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#9','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',4,'essay','teacher','나를 소개할 내용을 이름·좋아하는 것·잘하는 것·꿈으로 정리해 쓰고, 그중 하나에 까닭을 더해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C7","difficulty":4,"kind":"essay","stem":"나를 소개할 내용을 이름·좋아하는 것·잘하는 것·꿈으로 정리해 쓰고, 그중 하나에 까닭을 더해 보세요.","answer_guide":{"answer":"예: 이름 — 김하늘 / 좋아하는 것 — 별 보기(밤하늘이 반짝여서 보고 있으면 마음이 편하기 때문입니다) / 잘하는 것 — 줄넘기 / 꿈 — 천문학자","scoring_points":["네 항목을 알맞게 나누어 썼는가","나를 알려 주는 내용을 골랐는가","까닭을 하나 더했는가"]},"explanation":["네 항목.","나를 알려 주는 내용.","까닭 더하기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L07_challenge#10','kor',2,1,'u1','L07','g2_1_kor_u1_L07_challenge','lesson_challenge','K2-1-u1-C7',4,'essay','teacher','처음 만난 친구가 나에 대해 가장 궁금해할 것 같은 내용 두 가지와 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C7","difficulty":4,"kind":"essay","stem":"처음 만난 친구가 나에 대해 가장 궁금해할 것 같은 내용 두 가지와 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 좋아하는 놀이와 잘하는 운동이 궁금할 것 같습니다. 같이 놀 수 있는지 알고 싶을 것이기 때문입니다.","scoring_points":["궁금해할 내용 두 가지를 썼는가","나를 알려 주는 내용인가","그렇게 생각한 까닭을 썼는가"]},"explanation":["두 가지.","나를 알려 주는 내용.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#1','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],true,'{"seq":1,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 이하준입니다.","correct":true},{"t":"오늘은 날씨가 맑습니다.","mis":"K2-1-u1-X06"},{"t":"제가 잘하는 것은 줄넘기입니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","잘하는 것은 이름 다음에 이어 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 박서아입니다.","correct":true},{"t":"어제 학교에 일찍 왔습니다.","mis":"K2-1-u1-X06"},{"t":"제 꿈은 화가입니다.","mis":"K2-1-u1-X07"}],"explanation":["첫 문장에는 내 이름을 써요.","누구의 글인지 바로 알 수 있어요.","꿈은 뒤에 이어 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#2','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',1,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#3','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',1,'ox','auto','소개하는 글은 한 문장에 한 가지 내용만 담으면 읽기 쉬워요.',ARRAY['K2-1-u1-X09']::text[],true,'{"seq":3,"concept":"K2-1-u1-C8","difficulty":1,"kind":"ox","stem":"소개하는 글은 한 문장에 한 가지 내용만 담으면 읽기 쉬워요.","answer":"O","reason_options":[{"t":"내용이 섞이지 않아 알아보기 쉬우니까","correct":true},{"t":"한 문장에 모두 넣어야 짧아지니까","mis":"K2-1-u1-X09"}],"mis":"K2-1-u1-X09","explanation":["한 문장에 한 가지 내용을 담아요.","내용이 섞이지 않아 읽기 쉬워요.","좋아하는 것, 잘하는 것, 꿈을 문장마다 나누어 써요."],"variant_rule":{"alt":[{"stem":"「저는 서아이고 그림을 좋아하고 수영을 잘하고 꿈은 화가입니다.」처럼 한 문장에 모두 쓰는 것이 좋아요.","answer":"X","reason_options":[{"t":"한 문장에 한 가지씩 나누어 써야 읽기 쉬우니까","correct":true},{"t":"문장 수가 적을수록 좋은 글이니까","mis":"K2-1-u1-X09"}],"explanation":["한 문장에 여러 내용을 몰아 쓰면 읽기 어려워요.","「그리고」가 나오는 곳에서 문장을 나누어요.","한 문장에 한 가지 내용을 담아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#4','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C10',1,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],true,'{"seq":4,"concept":"K2-1-u1-C10","difficulty":1,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"친구들을 바라보며 또박또박 말해요","correct":true},{"t":"종이만 보며 작은 목소리로 읽어요","mis":"K2-1-u1-X15"},{"t":"빨리 끝내려고 서둘러 말해요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 빠르기와 크기로 또박또박 말해요.","작게, 빨리 말하면 친구들이 알아듣기 어려워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"바른 자세로 서서 알맞은 크기로 말해요","correct":true},{"t":"몸을 흔들며 혼잣말처럼 말해요","mis":"K2-1-u1-X15"},{"t":"고개를 숙이고 웅얼거려요","mis":"K2-1-u1-X15"}],"explanation":["바른 자세로 서서 말해요.","맨 뒤 친구에게도 들리게 알맞은 크기로 말해요.","고개를 들고 친구들을 바라봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#5','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',2,'mc','auto','나를 소개하는 글에 어울리는 문장은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X08']::text[],true,'{"seq":5,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"나를 소개하는 글에 어울리는 문장은 어느 것인가요?","options":[{"t":"제가 좋아하는 것은 수영입니다.","correct":true},{"t":"오늘 급식은 카레였습니다.","mis":"K2-1-u1-X06"},{"t":"수영. 달리기.","mis":"K2-1-u1-X08"}],"explanation":["좋아하는 것을 문장으로 썼어요.","급식 이야기는 나를 알려 주지 않아요.","낱말만 늘어놓으면 문장이 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나를 소개하는 글에 어울리는 문장은 어느 것인가요?","options":[{"t":"제 꿈은 소방관입니다.","correct":true},{"t":"어제는 비가 많이 왔습니다.","mis":"K2-1-u1-X06"},{"t":"소방관. 불.","mis":"K2-1-u1-X08"}],"explanation":["꿈을 문장으로 썼어요.","날씨는 나를 알려 주지 않아요.","낱말만 늘어놓으면 문장이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#6','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',2,'mc','auto','소개하는 글을 쓰고 다시 읽으며 확인할 것이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],true,'{"seq":6,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"소개하는 글을 쓰고 다시 읽으며 확인할 것이 아닌 것은 어느 것인가요?","options":[{"t":"친구 글보다 내 글이 더 긴가요?","correct":true},{"t":"내 이름으로 시작했나요?","mis":"K2-1-u1-X16"},{"t":"한 문장에 한 가지 내용을 담았나요?","mis":"K2-1-u1-X16"}],"explanation":["이름으로 시작했는지, 한 문장에 한 가지를 담았는지 확인해요.","글의 길이를 친구와 견줄 필요는 없어요.","묻는 말 「아닌 것」을 확인해요."],"variant_rule":{"alt":[{"stem":"소개하는 글을 쓰고 다시 읽으며 확인할 것은 어느 것인가요?","options":[{"t":"나를 알려 주지 않는 문장이 섞이지 않았나요?","correct":true},{"t":"글씨를 다른 색으로 썼나요?","mis":"K2-1-u1-X16"},{"t":"친구 글보다 더 긴가요?","mis":"K2-1-u1-X16"}],"explanation":["나와 관계없는 문장이 있으면 빼요.","글씨 색이나 길이는 확인할 점이 아니에요.","이름·내용·문장을 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#7','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],true,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"저는 강아지를 좋아합니다.","correct":true},{"t":"저는 강아지를 좋아합니다","mis":"K2-1-u1-X08"},{"t":"저는, 강아지를, 좋아합니다","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없으면 문장이 끝났는지 알기 어려워요.","쉼표를 낱말마다 찍지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"제 꿈은 경찰관입니다.","correct":true},{"t":"제 꿈은 경찰관입니다","mis":"K2-1-u1-X08"},{"t":"제 꿈은, 경찰관","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 마침표(.)를 찍어요.","「제 꿈은, 경찰관」은 문장이 끝나지 않았어요.","문장을 끝까지 쓰고 마침표를 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#8','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',2,'match','auto','소개하는 글의 문장과 담긴 내용을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u1-C8","difficulty":2,"kind":"match","stem":"소개하는 글의 문장과 담긴 내용을 이어 보세요.","pairs":[{"l":"저는 오지안입니다.","r":"이름"},{"l":"저는 별 보기를 좋아합니다.","r":"좋아하는 것"},{"l":"제 꿈은 천문학자입니다.","r":"꿈"}],"mis":"K2-1-u1-X10","explanation":["「저는 ○○○입니다」는 이름이에요.","「~을 좋아합니다」는 좋아하는 것이에요.","「제 꿈은 ~입니다」는 꿈이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개하는 글의 문장과 담긴 내용을 이어 보세요.","pairs":[{"l":"저는 문태민입니다.","r":"이름"},{"l":"제가 잘하는 것은 축구입니다.","r":"잘하는 것"},{"l":"제 꿈은 축구 선수입니다.","r":"꿈"}],"explanation":["「저는 ○○○입니다」는 이름이에요.","「제가 잘하는 것은 ~입니다」는 잘하는 것이에요.","「제 꿈은 ~입니다」는 꿈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#9','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C10',2,'ox','auto','친구의 소개 발표가 끝나면 박수를 치고, 궁금한 것은 손을 들고 물어요.',ARRAY['K2-1-u1-X02']::text[],true,'{"seq":9,"concept":"K2-1-u1-C10","difficulty":2,"kind":"ox","stem":"친구의 소개 발표가 끝나면 박수를 치고, 궁금한 것은 손을 들고 물어요.","answer":"O","reason_options":[{"t":"끝까지 듣고 고마움과 관심을 전하는 것이니까","correct":true},{"t":"궁금하면 발표 중에 바로 물어야 하니까","mis":"K2-1-u1-X02"}],"mis":"K2-1-u1-X02","explanation":["발표가 끝난 뒤 박수로 고마움을 전해요.","궁금한 것은 손을 들고 물어요.","발표 중에 끼어들어 묻지 않아요."],"variant_rule":{"alt":[{"stem":"발표를 들을 때 궁금한 점이 생기면 발표 중간에 바로 물어봐요.","answer":"X","reason_options":[{"t":"발표가 끝난 뒤 손을 들고 물어야 하니까","correct":true},{"t":"궁금할 때 바로 물어야 잊지 않으니까","mis":"K2-1-u1-X02"}],"explanation":["발표 중에 물으면 발표가 끊겨요.","끝난 뒤 손을 들고 물어요.","잊을까 걱정되면 짧게 적어 두어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_basic#10','kor',2,1,'u1','L09','g2_1_kor_u1_L09_basic','lesson_basic','K2-1-u1-C8',3,'error','auto','친구들이 하람이가 쓴 소개 글을 읽고 말했어요. 잘못 말한 친구는 누구인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#1','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',2,'mc','auto','소개하는 글을 「저는 ○○○입니다.」로 시작하는 까닭은 무엇인가요?',ARRAY['K2-1-u1-X07']::text[],false,'{"seq":1,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"소개하는 글을 「저는 ○○○입니다.」로 시작하는 까닭은 무엇인가요?","options":[{"t":"읽는 사람이 누구의 글인지 바로 알 수 있어서","correct":true},{"t":"글이 더 길어 보여서","mis":"K2-1-u1-X07"},{"t":"이름을 쓰면 글씨 연습이 되어서","mis":"K2-1-u1-X07"}],"explanation":["첫 문장에 이름을 쓰면 누구의 글인지 바로 알아요.","길어 보이게 하거나 글씨 연습을 하려는 것이 아니에요.","읽는 사람을 생각해 이름부터 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#2','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표하기 전에 하면 좋은 것은 무엇인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":2,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표하기 전에 하면 좋은 것은 무엇인가요?","options":[{"t":"쓴 글을 소리 내어 읽으며 연습해요","correct":true},{"t":"연습 없이 바로 발표해요","mis":"K2-1-u1-X15"},{"t":"글을 다 외우지 못하면 발표하지 않아요","mis":"K2-1-u1-X15"}],"explanation":["소리 내어 읽어 보면 어디서 쉴지, 어떻게 말할지 알 수 있어요.","다 외우지 못해도 글을 보며 발표할 수 있어요.","연습하면 또박또박 말하기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#3','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',3,'mc','auto','서윤이가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":3,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"서윤이가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"어제는 엄마와 마트에 갔습니다.","correct":true},{"t":"저는 문서윤입니다.","mis":"K2-1-u1-X16"},{"t":"제 꿈은 수의사입니다.","mis":"K2-1-u1-X16"}],"explanation":["마트에 간 일은 서윤이를 알려 주는 내용이 아니에요.","이름과 꿈은 소개하는 글에 꼭 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 문서윤입니다.","저는 고양이를 좋아합니다.","어제는 엄마와 마트에 갔습니다.","제 꿈은 수의사입니다."],"title":"서윤이가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#4','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',3,'mc','auto','서윤이가 쓴 소개 글을 보고 답해 보세요. 「저는 고양이를 좋아합니다.」에 까닭을 더해 다듬은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X08']::text[],false,'{"seq":4,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"서윤이가 쓴 소개 글을 보고 답해 보세요. 「저는 고양이를 좋아합니다.」에 까닭을 더해 다듬은 것은 어느 것인가요?","options":[{"t":"저는 고양이를 좋아합니다. 부드러운 털을 쓰다듬으면 기분이 좋기 때문입니다.","correct":true},{"t":"저는 고양이를 좋아합니다. 마트는 크기 때문입니다.","mis":"K2-1-u1-X06"},{"t":"저는 고양이 좋아","mis":"K2-1-u1-X08"}],"explanation":["고양이를 좋아하는 까닭을 더했어요.","마트가 크다는 것은 까닭이 아니에요.","문장을 끝까지 쓰고 마침표를 찍어요."],"asset":{"type":"passage","lines":["저는 문서윤입니다.","저는 고양이를 좋아합니다.","어제는 엄마와 마트에 갔습니다.","제 꿈은 수의사입니다."],"title":"서윤이가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#5','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',3,'ox','auto','「저는 강아지를 좋아합니다」처럼 마침표를 찍지 않아도 문장이 끝난 것을 알 수 있으니 괜찮아요.',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":5,"concept":"K2-1-u1-C8","difficulty":3,"kind":"ox","stem":"「저는 강아지를 좋아합니다」처럼 마침표를 찍지 않아도 문장이 끝난 것을 알 수 있으니 괜찮아요.","answer":"X","reason_options":[{"t":"문장이 끝나면 마침표(.)를 찍어야 하니까","correct":true},{"t":"소리 내어 읽으면 다 알 수 있으니까","mis":"K2-1-u1-X08"}],"mis":"K2-1-u1-X08","explanation":["글로 쓸 때는 문장이 끝나면 마침표를 찍어요.","마침표가 있어야 읽는 사람이 문장의 끝을 알아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#6','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',3,'error','auto','친구들이 소개 글 발표에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X15','K2-1-u1-X16']::text[],false,'{"seq":6,"concept":"K2-1-u1-C10","difficulty":3,"kind":"error","stem":"친구들이 소개 글 발표에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 부끄러우면 종이로 얼굴을 가리고 작게 읽어요","correct":true,"mis_target":"K2-1-u1-X15"},{"t":"지호 — 듣는 친구들을 바라보며 말해요","mis":"K2-1-u1-X16"},{"t":"서아 — 끝까지 또박또박 말해요","mis":"K2-1-u1-X16"}],"explanation":["얼굴을 가리고 작게 읽으면 친구들이 알아듣기 어려워요.","부끄러워도 고개를 들고 또박또박 말해요.","지호와 서아는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#7','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',3,'mc','auto','「달리기. 잘함. 꿈 체육 선생님.」을 소개하는 글의 문장으로 바르게 고친 것은 어느 것인가요?',ARRAY['K2-1-u1-X08','K2-1-u1-X09']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"「달리기. 잘함. 꿈 체육 선생님.」을 소개하는 글의 문장으로 바르게 고친 것은 어느 것인가요?","options":[{"t":"제가 잘하는 것은 달리기입니다. 제 꿈은 체육 선생님입니다.","correct":true},{"t":"달리기, 잘함, 꿈은 체육 선생님.","mis":"K2-1-u1-X08"},{"t":"저는 달리기를 잘하고 꿈은 체육 선생님이고 축구도 좋아합니다","mis":"K2-1-u1-X09"}],"explanation":["낱말을 이어 문장으로 썼어요.","한 문장에 한 가지 내용을 담고 마침표를 찍었어요.","낱말만 늘어놓거나 한 문장에 몰아 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#8','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#9','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C8',4,'essay','teacher','「저는 ○○○입니다.」로 시작해 나를 소개하는 글을 네 문장으로 써 보세요. 한 문장에는 한 가지 내용만 담아요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"「저는 ○○○입니다.」로 시작해 나를 소개하는 글을 네 문장으로 써 보세요. 한 문장에는 한 가지 내용만 담아요.","answer_guide":{"answer":"예: 저는 김하늘입니다. / 저는 별 보기를 좋아합니다. / 제가 잘하는 것은 줄넘기입니다. / 제 꿈은 천문학자입니다.","scoring_points":["이름으로 시작했는가","한 문장에 한 가지 내용을 담았는가","나를 알려 주는 내용을 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["이름으로 시작.","한 문장에 한 가지.","문장과 마침표."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L09_challenge#10','kor',2,1,'u1','L09','g2_1_kor_u1_L09_challenge','lesson_challenge','K2-1-u1-C10',4,'essay','teacher','소개하는 글을 발표할 때 지킬 점 두 가지와, 친구 발표를 들을 때 지킬 점 한 가지를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C10","difficulty":4,"kind":"essay","stem":"소개하는 글을 발표할 때 지킬 점 두 가지와, 친구 발표를 들을 때 지킬 점 한 가지를 써 보세요.","answer_guide":{"answer":"예: 발표할 때 — 친구들을 바라보며 말합니다. / 또박또박 알맞은 크기로 말합니다. 들을 때 — 끝까지 듣고 궁금한 것은 손을 들고 묻습니다.","scoring_points":["발표할 때 지킬 점 두 가지를 썼는가","들을 때 지킬 점 한 가지를 썼는가","바라보기·또박또박·끝까지 듣기 같은 실천할 수 있는 말로 썼는가"]},"explanation":["발표 두 가지.","듣기 한 가지.","실천할 수 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#1','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',1,'mc','auto','주변 사람을 소개하는 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X07']::text[],true,'{"seq":1,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람을 소개하는 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"제 친구 도윤이를 소개합니다.","correct":true},{"t":"도윤이는 어제 늦잠을 잤습니다.","mis":"K2-1-u1-X14"},{"t":"그 친구는 우리 반에 있습니다.","mis":"K2-1-u1-X07"}],"explanation":["「제 ○○ ○○○를 소개합니다.」로 누구를 소개하는지 밝혀요.","늦잠 이야기는 흉이 될 수 있어요.","「그 친구」라고만 하면 누구인지 알 수 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주변 사람을 소개하는 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"제 동생 지우를 소개합니다.","correct":true},{"t":"지우는 자주 웁니다.","mis":"K2-1-u1-X14"},{"t":"그 아이는 우리 집에 삽니다.","mis":"K2-1-u1-X07"}],"explanation":["누구를 소개하는지 첫 문장에서 밝혀요.","자주 운다는 말은 흉이 될 수 있어요.","「그 아이」라고만 하면 누구인지 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#2','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],true,'{"seq":2,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람이 잘하는 것","correct":true},{"t":"그 사람의 전화번호","mis":"K2-1-u1-X14"},{"t":"그 사람 집 비밀번호","mis":"K2-1-u1-X14"}],"explanation":["잘하는 것은 그 사람을 잘 보여 줘요.","전화번호나 비밀번호는 알리면 안 되는 개인 정보예요.","좋은 점, 잘하는 것, 함께한 일을 넣어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람의 좋은 점","correct":true},{"t":"그 사람의 집 주소","mis":"K2-1-u1-X14"},{"t":"그 사람이 실수한 일","mis":"K2-1-u1-X14"}],"explanation":["좋은 점은 그 사람을 따뜻하게 알려 줘요.","주소는 개인 정보, 실수한 일은 흉이 될 수 있어요.","존중하는 마음으로 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#3','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',1,'ox','auto','주변 사람을 소개할 때는 아끼고 존중하는 마음으로 좋은 점을 전해요.',ARRAY['K2-1-u1-X14']::text[],true,'{"seq":3,"concept":"K2-1-u1-C9","difficulty":1,"kind":"ox","stem":"주변 사람을 소개할 때는 아끼고 존중하는 마음으로 좋은 점을 전해요.","answer":"O","reason_options":[{"t":"좋은 점을 따뜻하게 전하면 소개받는 사람도 듣는 사람도 기분이 좋으니까","correct":true},{"t":"재미있게 하려면 흉을 보아도 되니까","mis":"K2-1-u1-X14"}],"mis":"K2-1-u1-X14","explanation":["소개하는 사람을 아끼는 마음으로 소개해요.","좋은 점을 따뜻하게 전해요.","흉을 보면 그 사람이 속상해요."],"variant_rule":{"alt":[{"stem":"친구를 소개할 때 친구가 부끄러워하는 일을 재미로 말해도 돼요.","answer":"X","reason_options":[{"t":"소개하는 사람을 존중해야 하니까","correct":true},{"t":"모두 웃으면 좋은 소개니까","mis":"K2-1-u1-X14"}],"explanation":["부끄러워하는 일을 말하면 친구가 속상해요.","소개는 그 사람을 존중하는 마음으로 해요.","좋은 점을 골라 전해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#4','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',1,'mc','auto','주변 사람을 잘 소개한 것은 어느 것인가요?',ARRAY['K2-1-u1-X07','K2-1-u1-X14']::text[],true,'{"seq":4,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람을 잘 소개한 것은 어느 것인가요?","options":[{"t":"제 짝 소율이는 노래를 잘 부릅니다.","correct":true},{"t":"그 사람은 그냥 옆 반에 있습니다.","mis":"K2-1-u1-X07"},{"t":"우리 형은 방을 안 치웁니다.","mis":"K2-1-u1-X14"}],"explanation":["누구인지 밝히고 잘하는 것을 소개했어요.","「그 사람」만으로는 누구인지 알 수 없어요.","방을 안 치운다는 말은 흉이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주변 사람을 잘 소개한 것은 어느 것인가요?","options":[{"t":"저희 할머니께서는 맛있는 떡을 잘 만드십니다.","correct":true},{"t":"그분은 그냥 우리 동네에 사십니다.","mis":"K2-1-u1-X07"},{"t":"저희 할머니께서는 자주 깜빡하십니다.","mis":"K2-1-u1-X14"}],"explanation":["누구인지 밝히고 잘하시는 것을 소개했어요.","「그분」만으로는 누구인지 알 수 없어요.","깜빡하신다는 말은 흉이 될 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#5','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C10',2,'mc','auto','친구가 「제 친구 하린이는 종이접기를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],true,'{"seq":5,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"친구가 「제 친구 하린이는 종이접기를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「하린이는 무엇을 가장 잘 접나요?」","correct":true},{"t":"「너 어제 뭐 먹었어?」","mis":"K2-1-u1-X04"},{"t":"「종이접기는 재미없어.」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","손을 들고 정중하게 물어요."],"variant_rule":{"alt":[{"stem":"친구가 「저희 형은 축구를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「형은 축구를 언제부터 했나요?」","correct":true},{"t":"「오늘 급식 뭐야?」","mis":"K2-1-u1-X04"},{"t":"「축구 잘하는 게 뭐가 대단해?」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","손을 들고 정중하게 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#6','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',2,'mc','auto','친구 소개를 읽고 답해 보세요. 민호의 좋은 점으로 소개한 것은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],true,'{"seq":6,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"친구 소개를 읽고 답해 보세요. 민호의 좋은 점으로 소개한 것은 무엇인가요?","options":[{"t":"넘어진 친구를 먼저 일으켜 줘요","correct":true},{"t":"그림을 잘 그려요","mis":"K2-1-u1-X11"},{"t":"노래를 잘 불러요","mis":"K2-1-u1-X11"}],"explanation":["「친구가 넘어지면 먼저 달려가 일으켜 줍니다.」라고 했어요.","그림이나 노래는 글에 나오지 않아요.","글에서 찾아 답해요."],"asset":{"type":"passage","lines":["제 친구 민호를 소개합니다.","민호는 달리기를 잘합니다.","민호는 친구가 넘어지면 먼저 달려가 일으켜 줍니다."],"title":"우리 반 친구 소개"},"variant_rule":{"alt":[{"stem":"친구 소개를 읽고 답해 보세요. 민호가 잘하는 것은 무엇인가요?","options":[{"t":"달리기","correct":true},{"t":"그림 그리기","mis":"K2-1-u1-X11"},{"t":"종이접기","mis":"K2-1-u1-X11"}],"explanation":["「민호는 달리기를 잘합니다.」라고 했어요.","그림 그리기나 종이접기는 글에 나오지 않아요.","글에서 찾아 답해요."],"asset":{"type":"passage","lines":["제 친구 민호를 소개합니다.","민호는 달리기를 잘합니다.","민호는 친구가 넘어지면 먼저 달려가 일으켜 줍니다."],"title":"우리 반 친구 소개"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#7','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',2,'match','auto','소개할 사람과 어울리는 소개 문장을 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u1-C9","difficulty":2,"kind":"match","stem":"소개할 사람과 어울리는 소개 문장을 이어 보세요.","pairs":[{"l":"우리 선생님","r":"저희 선생님께서는 재미있는 이야기를 잘 들려주십니다."},{"l":"내 짝","r":"제 짝 예린이는 웃는 모습이 환합니다."},{"l":"우리 할아버지","r":"저희 할아버지께서는 텃밭에서 채소를 잘 기르십니다."}],"mis":"K2-1-u1-X07","explanation":["누구를 소개하는지 문장 앞에 밝혀요.","선생님, 짝, 할아버지에 맞게 이어요.","어른을 소개할 때는 「-께서는, -십니다」처럼 높여 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소개할 사람과 어울리는 소개 문장을 이어 보세요.","pairs":[{"l":"우리 언니","r":"저희 언니는 피아노를 잘 칩니다."},{"l":"옆집 아기","r":"옆집 아기 하늘이는 잘 웃습니다."},{"l":"우리 반 친구","r":"우리 반 시우는 친구를 잘 도와줍니다."}],"explanation":["누구를 소개하는지 문장 앞에 밝혀요.","언니, 옆집 아기, 우리 반 친구에 맞게 이어요.","좋은 점을 따뜻하게 전해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#8','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],true,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"친구를 잘 도와줍니다.","correct":true},{"t":"자주 늦잠을 잡니다.","mis":"K2-1-u1-X14"},{"t":"밥을 늦게 먹습니다.","mis":"K2-1-u1-X14"}],"explanation":["친구를 잘 도와준다는 것은 좋은 점이에요.","늦잠이나 늦게 먹는 것은 흉이 될 수 있어요.","듣는 사람이 기분 좋은 말을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"웃는 모습이 환합니다.","correct":true},{"t":"숙제를 자주 잊습니다.","mis":"K2-1-u1-X14"},{"t":"목소리가 너무 큽니다.","mis":"K2-1-u1-X14"}],"explanation":["웃는 모습이 환하다는 것은 좋은 점이에요.","숙제를 잊거나 목소리가 크다는 것은 흉이 될 수 있어요.","좋은 점을 골라 전해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#9','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C10',2,'ox','auto','친구가 주변 사람을 소개할 때는 말하는 친구를 바라보며 끝까지 들어요.',ARRAY['K2-1-u1-X01']::text[],true,'{"seq":9,"concept":"K2-1-u1-C10","difficulty":2,"kind":"ox","stem":"친구가 주변 사람을 소개할 때는 말하는 친구를 바라보며 끝까지 들어요.","answer":"O","reason_options":[{"t":"잘 들어야 소개한 사람을 알 수 있으니까","correct":true},{"t":"내 차례 준비만 하면 되니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["친구를 바라보며 끝까지 들어요.","내 차례 준비만 하면 친구 소개를 놓쳐요.","들은 뒤 박수로 반응해요."],"variant_rule":{"alt":[{"stem":"친구 소개가 끝나면 박수를 쳐 고마움을 전해요.","answer":"O","reason_options":[{"t":"끝까지 들었다는 마음을 전하는 것이니까","correct":true},{"t":"박수는 상을 받을 때만 치니까","mis":"K2-1-u1-X01"}],"explanation":["박수는 「잘 들었어요.」라는 마음이에요.","소개한 친구의 용기에 고마움을 전해요.","궁금한 것은 손을 들고 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_basic#10','kor',2,1,'u1','L11','g2_1_kor_u1_L11_basic','lesson_basic','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],true,'{"seq":10,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"준우 — 「제 형의 전화번호는 공일공…입니다.」 하고 전화번호를 말했어요","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"다은 — 「저희 엄마께서는 요리를 잘하십니다.」","mis":"K2-1-u1-X16"},{"t":"태민 — 「제 짝 로아는 책을 많이 읽습니다.」","mis":"K2-1-u1-X16"}],"explanation":["전화번호는 남에게 알리면 안 되는 개인 정보예요.","다은이와 태민이는 잘하는 것을 소개했어요.","개인 정보는 소개에 넣지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"하린 — 「제 동생은 아직도 밤에 이불에 실수를 합니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"지호 — 「제 동생은 블록 쌓기를 잘합니다.」","mis":"K2-1-u1-X16"},{"t":"서아 — 「저희 아빠께서는 노래를 잘 부르십니다.」","mis":"K2-1-u1-X16"}],"explanation":["동생이 부끄러워할 일을 말했어요.","소개는 존중하는 마음으로 좋은 점을 전해요.","지호와 서아는 알맞게 소개했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#1','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 전화번호나 집 주소를 넣지 않는 까닭은 무엇인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":1,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 전화번호나 집 주소를 넣지 않는 까닭은 무엇인가요?","options":[{"t":"그 사람이 원하지 않는데 알려지면 위험할 수 있어서","correct":true},{"t":"전화번호는 너무 길어서","mis":"K2-1-u1-X14"},{"t":"주소는 쓰기 어려워서","mis":"K2-1-u1-X14"}],"explanation":["전화번호와 주소는 개인 정보예요.","함부로 알려지면 위험할 수 있어요.","그래서 소개에 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#2','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C10',2,'mc','auto','소개를 들은 뒤 질문할 때 알맞은 모습은 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X04']::text[],false,'{"seq":2,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개를 들은 뒤 질문할 때 알맞은 모습은 어느 것인가요?","options":[{"t":"손을 들고, 소개한 내용과 관련 있는 것을 물어요","correct":true},{"t":"발표 중에 끼어들어 물어요","mis":"K2-1-u1-X02"},{"t":"소개와 상관없는 것을 물어요","mis":"K2-1-u1-X04"}],"explanation":["소개가 끝난 뒤 손을 들고 물어요.","소개한 내용과 관련 있는 것을 물어요.","관련 없는 질문은 대화를 끊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#3','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',3,'mc','auto','태민이가 쓴 친구 소개를 보고 답해 보세요. 빼는 것이 좋은 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":3,"concept":"K2-1-u1-C9","difficulty":3,"kind":"mc","stem":"태민이가 쓴 친구 소개를 보고 답해 보세요. 빼는 것이 좋은 문장은 어느 것인가요?","options":[{"t":"지안이는 지난번에 받아쓰기를 틀려서 울었습니다.","correct":true},{"t":"지안이는 줄넘기를 잘합니다.","mis":"K2-1-u1-X16"},{"t":"지안이는 친구들에게 늘 먼저 인사를 합니다.","mis":"K2-1-u1-X16"}],"explanation":["받아쓰기를 틀려 운 일은 지안이가 부끄러워할 수 있어요.","줄넘기와 인사는 지안이의 좋은 점이에요.","존중하는 마음으로 골라요."],"asset":{"type":"passage","lines":["제 친구 지안이를 소개합니다.","지안이는 줄넘기를 잘합니다.","지안이는 지난번에 받아쓰기를 틀려서 울었습니다.","지안이는 친구들에게 늘 먼저 인사를 합니다."],"title":"태민이가 쓴 친구 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#4','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',3,'mc','auto','태민이가 쓴 친구 소개를 보고 답해 보세요. 더하면 좋은 문장은 어느 것인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X06']::text[],false,'{"seq":4,"concept":"K2-1-u1-C9","difficulty":3,"kind":"mc","stem":"태민이가 쓴 친구 소개를 보고 답해 보세요. 더하면 좋은 문장은 어느 것인가요?","options":[{"t":"지안이와 저는 쉬는 시간마다 함께 줄넘기를 합니다.","correct":true},{"t":"지안이네 집은 행복아파트 5동입니다.","mis":"K2-1-u1-X14"},{"t":"오늘은 비가 옵니다.","mis":"K2-1-u1-X06"}],"explanation":["함께한 일을 더하면 소개가 생생해져요.","집 주소는 개인 정보예요.","날씨는 지안이를 알려 주지 않아요."],"asset":{"type":"passage","lines":["제 친구 지안이를 소개합니다.","지안이는 줄넘기를 잘합니다.","지안이는 지난번에 받아쓰기를 틀려서 울었습니다.","지안이는 친구들에게 늘 먼저 인사를 합니다."],"title":"태민이가 쓴 친구 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#5','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":5,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 재미있게 하려면 그 사람의 흉을 말해도 돼요","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"서윤 — 누구를 소개하는지 처음에 말해요","mis":"K2-1-u1-X16"},{"t":"민호 — 그 사람이 잘하는 것이나 함께한 일을 말해요","mis":"K2-1-u1-X16"}],"explanation":["흉을 말하면 소개받는 사람이 속상해요.","존중하는 마음으로 좋은 점을 전해요.","서윤이와 민호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#6','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C10',3,'mc','auto','대화를 읽고 답해 보세요. 시우의 대답으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":6,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 시우의 대답으로 알맞은 것은 어느 것인가요?","options":[{"t":"「아린이는 우리 가족 얼굴을 즐겨 그려요.」","correct":true},{"t":"「나는 어제 축구를 했어요.」","mis":"K2-1-u1-X04"},{"t":"「몰라요. 그건 안 알려 줄래요.」","mis":"K2-1-u1-X04"}],"explanation":["다은이는 아린이가 무엇을 그리는지 물었어요.","묻는 말에 맞게 대답해요.","관계없는 말이나 대답하지 않는 말은 대화를 끊어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"제 동생 아린이를 소개합니다. 아린이는 그림을 잘 그립니다."},{"who":"다은","text":"아린이는 무엇을 즐겨 그려요?"},{"who":"시우","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#7','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',3,'ox','auto','주변 사람을 소개할 때 내가 그 사람과 함께한 일을 넣으면 소개가 더 생생해져요.',ARRAY['K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C9","difficulty":3,"kind":"ox","stem":"주변 사람을 소개할 때 내가 그 사람과 함께한 일을 넣으면 소개가 더 생생해져요.","answer":"O","reason_options":[{"t":"함께한 일로 그 사람을 더 잘 보여 줄 수 있으니까","correct":true},{"t":"소개에는 이름만 있으면 되니까","mis":"K2-1-u1-X07"}],"mis":"K2-1-u1-X07","explanation":["함께한 일을 넣으면 그 사람이 더 잘 보여요.","이름만으로는 어떤 사람인지 알 수 없어요.","좋은 점과 함께한 일을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#8','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',4,'mc','auto','두 친구가 현우를 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#9','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C9',4,'essay','teacher','내 주변 사람 한 명을 골라 「제 ○○ ○○○를 소개합니다.」로 시작해 세 문장으로 소개하는 글을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u1-C9","difficulty":4,"kind":"essay","stem":"내 주변 사람 한 명을 골라 「제 ○○ ○○○를 소개합니다.」로 시작해 세 문장으로 소개하는 글을 써 보세요.","answer_guide":{"answer":"예: 제 짝 이서윤을 소개합니다. / 서윤이는 그림을 잘 그립니다. / 서윤이는 제가 아플 때 보건실에 함께 가 주었습니다.","scoring_points":["누구를 소개하는지 첫 문장에서 밝혔는가","잘하는 것·좋은 점·함께한 일을 담았는가","흉이나 개인 정보 없이 존중하는 마음으로 썼는가"]},"explanation":["누구인지 밝히기.","좋은 점·함께한 일.","존중하는 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_L11_challenge#10','kor',2,1,'u1','L11','g2_1_kor_u1_L11_challenge','lesson_challenge','K2-1-u1-C10',4,'essay','teacher','친구가 주변 사람을 소개했을 때 해 줄 질문 두 가지를 쓰고, 왜 그것이 궁금한지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u1-C10","difficulty":4,"kind":"essay","stem":"친구가 주변 사람을 소개했을 때 해 줄 질문 두 가지를 쓰고, 왜 그것이 궁금한지 써 보세요.","answer_guide":{"answer":"예: 「동생은 그림을 언제부터 그렸나요?」 「가장 좋아하는 그림은 무엇인가요?」 — 동생이 그림을 얼마나 좋아하는지 알고 싶기 때문입니다.","scoring_points":["소개 내용과 관련 있는 질문 두 가지를 썼는가","정중한 말로 썼는가","궁금한 까닭을 썼는가"]},"explanation":["관련 있는 질문.","정중한 말.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#1','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C1',1,'mc','auto','친구가 발표할 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"친구가 발표할 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"친구를 바라보며 끝까지 들어요","correct":true},{"t":"중간에 끼어들어 내 말을 해요","mis":"K2-1-u1-X02"},{"t":"옆 친구와 떠들며 들어요","mis":"K2-1-u1-X01"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 다른 일을 하면 잘 들을 수 없어요.","잘 들어 주면 말하는 사람도 기분이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#2','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 좋아하는 것","correct":true},{"t":"어제 본 만화 줄거리","mis":"K2-1-u1-X06"},{"t":"내일 날씨","mis":"K2-1-u1-X06"}],"explanation":["내가 좋아하는 것은 나를 알려 주는 내용이에요.","다른 둘은 나와 관계가 없어요.","소개하는 글에는 나를 알려 주는 내용을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#3','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C3',1,'mc','auto','말차례란 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"말차례란 무엇인가요?","options":[{"t":"대화할 때 한 사람씩 차례대로 말하는 것","correct":true},{"t":"먼저 큰 소리로 말하는 사람이 말하는 것","mis":"K2-1-u1-X03"},{"t":"한 사람만 계속 말하는 것","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","먼저·크게 말하거나 혼자 계속 말하는 것은 말차례가 아니에요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#4','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',1,'mc','auto','말차례를 지키지 못한 행동은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 지키지 못한 행동은 어느 것인가요?","options":[{"t":"친구가 말하는데 끼어들기","correct":true},{"t":"손 들고 기다리기","mis":"K2-1-u1-X16"},{"t":"끝까지 잘 듣기","mis":"K2-1-u1-X16"}],"explanation":["끼어드는 것은 말차례를 어긴 거예요.","말하고 싶으면 손을 들고 기다려요.","친구 말이 끝나면 내 차례에 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#5','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 바닥을 함께 닦은 친구는 누구인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 바닥을 함께 닦은 친구는 누구인가요?","options":[{"t":"준우","correct":true},{"t":"예린","mis":"K2-1-u1-X11"},{"t":"선생님","mis":"K2-1-u1-X11"}],"explanation":["글에 「준우가 휴지로 바닥을 함께 닦았어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 사람이 한 일이에요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["쉬는 시간에 예린이가 물통을 쏟았어요.","옆에 있던 준우가 휴지로 바닥을 함께 닦았어요.","예린이는 「고마워.」 하고 웃었어요."],"title":"쏟아진 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#6','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C7',1,'mc','auto','「제 꿈은 수의사입니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「제 꿈은 수의사입니다.」는 어떤 소개 항목인가요?","options":[{"t":"꿈","correct":true},{"t":"좋아하는 것","mis":"K2-1-u1-X10"},{"t":"잘하는 것","mis":"K2-1-u1-X10"}],"explanation":["「제 꿈은 수의사입니다.」는 꿈을 소개하는 문장이에요.","항목 이름이 문장에 들어 있어요.","이름·좋아하는 것·잘하는 것·꿈을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#7','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 이하준입니다.","correct":true},{"t":"오늘은 날씨가 맑습니다.","mis":"K2-1-u1-X06"},{"t":"제가 잘하는 것은 줄넘기입니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","나머지 내용은 이름 다음에 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#8','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람이 잘하는 것","correct":true},{"t":"그 사람의 전화번호","mis":"K2-1-u1-X14"},{"t":"그 사람 집 비밀번호","mis":"K2-1-u1-X14"}],"explanation":["그 사람이 잘하는 것은 그 사람을 따뜻하게 알려 줘요.","개인 정보나 흉은 넣지 않아요.","존중하는 마음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#9','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C1',2,'ox','auto','친구가 말할 때 딴 곳을 보아도 귀로 들리면 잘 듣는 것이에요.',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":2,"kind":"ox","stem":"친구가 말할 때 딴 곳을 보아도 귀로 들리면 잘 듣는 것이에요.","answer":"X","reason_options":[{"t":"말하는 사람을 바라보며 마음을 기울여 들어야 하니까","correct":true},{"t":"귀로 소리만 들리면 되니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["잘 듣기는 눈과 마음으로도 해요.","딴 곳을 보면 친구는 내가 안 듣는다고 느껴요.","말하는 사람을 바라보며 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#10','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',2,'mc','auto','짝이 「좋아하는 음식이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「좋아하는 음식이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「나는 떡볶이를 좋아해. 너는?」","correct":true},{"t":"「나 어제 축구했어!」","mis":"K2-1-u1-X04"},{"t":"「몰라. 그런데 오늘 비 온대.」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 짝에게 되물어 차례를 건넸어요.","관계없는 말을 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#11','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 줄을 함께 쓰게 된 하람이의 마음은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":11,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 줄을 함께 쓰게 된 하람이의 마음은?","options":[{"t":"고맙고 기쁜 마음","correct":true},{"t":"화나는 마음","mis":"K2-1-u1-X12"},{"t":"심심한 마음","mis":"K2-1-u1-X12"}],"explanation":["하람이는 「고마워!」 하며 웃었어요.","곤란할 때 도움을 받으면 고맙고 기뻐요.","일어난 일과 인물의 말·모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["하람이가 줄넘기 줄을 집에 두고 왔어요.","다은이가 「내 줄로 같이 하자!」 하고 말했어요.","하람이는 「고마워!」 하며 활짝 웃었어요."],"title":"나눠 쓴 줄넘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#12','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C7',2,'mc','auto','「저는 그림 그리기를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「저는 그림 그리기를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"생각한 것을 마음대로 그릴 수 있기 때문입니다.","correct":true},{"t":"오늘은 비가 옵니다.","mis":"K2-1-u1-X06"},{"t":"저는 키가 큽니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 까닭을 더했어요.","다른 문장은 앞 문장의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#13','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":13,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"저는 강아지를 좋아합니다.","correct":true},{"t":"저는 강아지를 좋아합니다","mis":"K2-1-u1-X08"},{"t":"저는, 강아지를, 좋아합니다","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없거나 낱말만 늘어놓으면 문장이 끝나지 않아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#14','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"친구들을 바라보며 또박또박 말해요","correct":true},{"t":"종이만 보며 작은 목소리로 읽어요","mis":"K2-1-u1-X15"},{"t":"빨리 끝내려고 서둘러 말해요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 크기와 빠르기로 또박또박 말해요.","작게, 빨리, 고개 숙여 말하면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#15','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C3',2,'ox','auto','말차례를 지키면 한 사람이 혼자 오래 말해도 괜찮아요.',ARRAY['K2-1-u1-X05']::text[],false,'{"seq":15,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"말차례를 지키면 한 사람이 혼자 오래 말해도 괜찮아요.","answer":"X","reason_options":[{"t":"모두가 돌아가며 말할 수 있게 해야 하니까","correct":true},{"t":"먼저 말을 시작한 사람이 끝까지 말해야 하니까","mis":"K2-1-u1-X05"}],"mis":"K2-1-u1-X05","explanation":["한 사람이 오래 말하면 다른 친구는 말할 수 없어요.","내 말을 마치면 차례를 건네요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#16','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":16,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"친구를 잘 도와줍니다.","correct":true},{"t":"자주 늦잠을 잡니다.","mis":"K2-1-u1-X14"},{"t":"밥을 늦게 먹습니다.","mis":"K2-1-u1-X14"}],"explanation":["「는 좋은 점을 전하는 말이에요.친구를 잘 도와줍니다.」","다른 둘은 흉이 될 수 있어요.","존중하는 마음으로 좋은 점을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#17','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X16']::text[],false,'{"seq":17,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 목소리가 큰 사람이 먼저 말하는 게 말차례예요","correct":true,"mis_target":"K2-1-u1-X03"},{"t":"소율 — 한 사람씩 차례대로 말해요","mis":"K2-1-u1-X16"},{"t":"예린 — 다른 사람 말을 끝까지 들어요","mis":"K2-1-u1-X16"}],"explanation":["목소리가 크다고 먼저 말하는 것이 아니에요.","말차례는 한 사람씩 차례대로 말하는 거예요.","다른 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#18','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 서윤이가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":18,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 서윤이가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그렇구나. 왜 그렇게 생각해?」","correct":true},{"t":"「그건 틀린 생각이야.」","mis":"K2-1-u1-X13"},{"t":"「나 배고파.」","mis":"K2-1-u1-X04"}],"explanation":["친구가 나와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 지안이가 참 다정한 것 같아."},{"who":"준우","text":"나는 로아가 다시 쌓자고 먼저 말했으면 좋았을 것 같아."},{"who":"서윤","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#19','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',3,'mc','auto','친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"어제는 엄마와 마트에 갔습니다.","correct":true},{"t":"저는 문서윤입니다.","mis":"K2-1-u1-X16"},{"t":"제 꿈은 수의사입니다.","mis":"K2-1-u1-X16"}],"explanation":["「어제는 엄마와 마트에 갔습니다」는 글쓴이를 알려 주는 내용이 아니에요.","이름과 꿈·좋아하는 것은 소개하는 글에 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 문서윤입니다.","저는 고양이를 좋아합니다.","어제는 엄마와 마트에 갔습니다.","제 꿈은 수의사입니다."],"title":"친구가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#20','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"준우 — 「제 형의 전화번호는 공일공…입니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"다은 — 「저희 엄마께서는 요리를 잘하십니다.」","mis":"K2-1-u1-X16"},{"t":"태민 — 「제 짝 로아는 책을 많이 읽습니다.」","mis":"K2-1-u1-X16"}],"explanation":["전화번호는 알리면 안 되는 개인 정보예요.","소개는 존중하는 마음으로 좋은 점을 전해요.","다른 두 친구는 알맞게 소개했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#21','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"줄을 두고 옴 → 같이 하자고 함 → 번갈아 넘음","correct":true},{"t":"같이 하자고 함 → 줄을 두고 옴 → 번갈아 넘음","mis":"K2-1-u1-X11"},{"t":"번갈아 넘음 → 줄을 두고 옴 → 같이 하자고 함","mis":"K2-1-u1-X11"}],"explanation":["이야기의 앞에서부터 차례로 짚어요.","줄을 두고 옴 → 같이 하자고 함 → 번갈아 넘음 차례예요.","까닭이 먼저, 결과가 나중에 와요."],"asset":{"type":"passage","lines":["하람이가 줄넘기 줄을 집에 두고 왔어요.","다은이가 같이 하자고 했어요.","둘은 번갈아 줄을 넘었어요."],"title":"나눠 쓴 줄넘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#22','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C10',3,'mc','auto','친구가 「제 친구 하린이는 종이접기를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":22,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 「제 친구 하린이는 종이접기를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「하린이는 무엇을 가장 잘 접나요?」","correct":true},{"t":"「너 어제 뭐 먹었어?」","mis":"K2-1-u1-X04"},{"t":"「종이접기는 재미없어.」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","소개가 끝난 뒤 손을 들고 정중하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#23','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#24','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C4',4,'essay','teacher','짝에게 「좋아하는 놀이가 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「좋아하는 놀이가 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 좋아하는 놀이가 뭐야? / 짝: 나는 술래잡기를 좋아해. 너는? / 나: 나는 공기놀이를 좋아해. / 짝: 그럼 쉬는 시간에 같이 하자!","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_a#25','kor',2,1,'u1','','g2_1_kor_u1_review_a','unit_review','K2-1-u1-C8',4,'essay','teacher','「저는 ○○○입니다.」로 시작해 나를 소개하는 글을 네 문장으로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"「저는 ○○○입니다.」로 시작해 나를 소개하는 글을 네 문장으로 써 보세요.","answer_guide":{"answer":"예: 저는 김하늘입니다. / 저는 별 보기를 좋아합니다. / 제가 잘하는 것은 줄넘기입니다. / 제 꿈은 천문학자입니다.","scoring_points":["이름으로 시작했는가","나(그 사람)를 알려 주는 내용을 담았는가","한 문장에 한 가지씩 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["첫 문장.","알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#1','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C1',1,'mc','auto','선생님께서 설명하실 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"선생님께서 설명하실 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"선생님을 바라보며 끝까지 들어요","correct":true},{"t":"궁금한 것이 생기면 바로 끼어들어요","mis":"K2-1-u1-X02"},{"t":"공책에 낙서하며 들어요","mis":"K2-1-u1-X01"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 다른 일을 하면 잘 들을 수 없어요.","잘 들어 주면 말하는 사람도 기분이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#2','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 잘하는 것","correct":true},{"t":"오늘 급식 반찬","mis":"K2-1-u1-X06"},{"t":"버스 도착 시간","mis":"K2-1-u1-X06"}],"explanation":["내가 잘하는 것은 나를 알려 주는 내용이에요.","다른 둘은 나와 관계가 없어요.","소개하는 글에는 나를 알려 주는 내용을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#3','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C3',1,'mc','auto','「말차례를 지킨다」는 것은 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"「말차례를 지킨다」는 것은 무엇인가요?","options":[{"t":"한 사람씩 돌아가며 차례대로 말하는 것","correct":true},{"t":"목소리가 큰 사람부터 말하는 것","mis":"K2-1-u1-X03"},{"t":"말을 시작한 사람이 끝까지 혼자 말하는 것","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","먼저·크게 말하거나 혼자 계속 말하는 것은 말차례가 아니에요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#4','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',1,'mc','auto','말차례를 잘 지킨 행동은 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X03']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 잘 지킨 행동은 어느 것인가요?","options":[{"t":"친구 말이 끝난 뒤 내 차례에 말하기","correct":true},{"t":"생각나면 바로 끼어들기","mis":"K2-1-u1-X02"},{"t":"친구보다 먼저 크게 말하기","mis":"K2-1-u1-X03"}],"explanation":["친구 말이 끝난 뒤 말하는 것이 말차례를 지킨 거예요.","말하고 싶으면 손을 들고 기다려요.","친구 말이 끝나면 내 차례에 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#5','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 소율이가 물고기에게 준 것은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 소율이가 물고기에게 준 것은 무엇인가요?","options":[{"t":"먹이","correct":true},{"t":"물","mis":"K2-1-u1-X11"},{"t":"장난감","mis":"K2-1-u1-X11"}],"explanation":["글에 「소율이는 먹이를 조금 주었어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 사람이 한 일이에요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["아침에 소율이가 교실에 들어왔어요.","칠판 옆 어항의 물고기가 배고파 보였어요.","소율이는 먹이를 조금 주었어요."],"title":"어항 당번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#6','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C7',1,'mc','auto','「제가 잘하는 것은 수영입니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「제가 잘하는 것은 수영입니다.」는 어떤 소개 항목인가요?","options":[{"t":"잘하는 것","correct":true},{"t":"꿈","mis":"K2-1-u1-X10"},{"t":"이름","mis":"K2-1-u1-X10"}],"explanation":["「제가 잘하는 것은 수영입니다.」는 잘하는 것을 소개하는 문장이에요.","항목 이름이 문장에 들어 있어요.","이름·좋아하는 것·잘하는 것·꿈을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#7','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 박서아입니다.","correct":true},{"t":"어제 학교에 일찍 왔습니다.","mis":"K2-1-u1-X06"},{"t":"제 꿈은 화가입니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","나머지 내용은 이름 다음에 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#8','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람의 좋은 점","correct":true},{"t":"그 사람의 집 주소","mis":"K2-1-u1-X14"},{"t":"그 사람이 실수한 일","mis":"K2-1-u1-X14"}],"explanation":["그 사람의 좋은 점은 그 사람을 따뜻하게 알려 줘요.","개인 정보나 흉은 넣지 않아요.","존중하는 마음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#9','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C1',2,'ox','auto','친구 말이 끝날 때까지 기다렸다가 내 생각을 말하는 것은 잘 듣는 태도예요.',ARRAY['K2-1-u1-X02']::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":2,"kind":"ox","stem":"친구 말이 끝날 때까지 기다렸다가 내 생각을 말하는 것은 잘 듣는 태도예요.","answer":"O","reason_options":[{"t":"끼어들지 않고 끝까지 들었으니까","correct":true},{"t":"생각나면 바로 말해야 잊지 않으니까","mis":"K2-1-u1-X02"}],"mis":"K2-1-u1-X02","explanation":["끝까지 기다리는 것이 잘 듣는 태도예요.","끼어들면 친구 말이 끊겨요.","말하는 사람을 바라보며 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#10','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',2,'mc','auto','짝이 「주말에 뭐 했어?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「주말에 뭐 했어?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「할머니 댁에 갔어. 너는 뭐 했어?」","correct":true},{"t":"「나 연필 새로 샀다!」","mis":"K2-1-u1-X04"},{"t":"「배고프다.」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 짝에게 되물어 차례를 건넸어요.","관계없는 말을 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#11','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 모래성이 무너졌을 때 로아의 마음은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":11,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 모래성이 무너졌을 때 로아의 마음은?","options":[{"t":"속상한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u1-X12"},{"t":"졸린 마음","mis":"K2-1-u1-X12"}],"explanation":["로아는 울먹였어요.","애써 쌓은 것이 무너지면 속상해요.","일어난 일과 인물의 말·모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["지안이와 로아가 모래성을 쌓았어요.","큰 파도가 와서 모래성이 무너졌어요.","로아는 울먹였어요."],"title":"무너진 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#12','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C7',2,'mc','auto','「제 꿈은 요리사입니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「제 꿈은 요리사입니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"가족에게 맛있는 음식을 만들어 주고 싶기 때문입니다.","correct":true},{"t":"어제 라면을 먹었습니다.","mis":"K2-1-u1-X06"},{"t":"요리사는 하얀 모자를 씁니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 까닭을 더했어요.","다른 문장은 앞 문장의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#13','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":13,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"제 꿈은 경찰관입니다.","correct":true},{"t":"제 꿈은 경찰관입니다","mis":"K2-1-u1-X08"},{"t":"제 꿈은, 경찰관","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없거나 낱말만 늘어놓으면 문장이 끝나지 않아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#14','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"바른 자세로 서서 알맞은 크기로 말해요","correct":true},{"t":"몸을 흔들며 혼잣말처럼 말해요","mis":"K2-1-u1-X15"},{"t":"고개를 숙이고 웅얼거려요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 크기와 빠르기로 또박또박 말해요.","작게, 빨리, 고개 숙여 말하면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#15','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C3',2,'ox','auto','여러 친구가 한꺼번에 말하면 서로의 말을 알아듣기 어려워요.',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":15,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"여러 친구가 한꺼번에 말하면 서로의 말을 알아듣기 어려워요.","answer":"O","reason_options":[{"t":"말소리가 섞여 무슨 말인지 알 수 없으니까","correct":true},{"t":"한꺼번에 말해야 이야기가 빨리 끝나니까","mis":"K2-1-u1-X03"}],"mis":"K2-1-u1-X03","explanation":["한꺼번에 말하면 말소리가 섞여요.","그래서 말차례가 필요해요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#16','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":16,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"웃는 모습이 환합니다.","correct":true},{"t":"숙제를 자주 잊습니다.","mis":"K2-1-u1-X14"},{"t":"목소리가 너무 큽니다.","mis":"K2-1-u1-X14"}],"explanation":["「는 좋은 점을 전하는 말이에요.웃는 모습이 환합니다.」","다른 둘은 흉이 될 수 있어요.","존중하는 마음으로 좋은 점을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#17','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X16']::text[],false,'{"seq":17,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 내 생각이 맞으면 친구 말을 끊어도 돼요","correct":true,"mis_target":"K2-1-u1-X02"},{"t":"서윤 — 말하고 싶으면 손을 들고 기다려요","mis":"K2-1-u1-X16"},{"t":"태민 — 친구 말이 끝나면 내 차례에 말해요","mis":"K2-1-u1-X16"}],"explanation":["생각이 맞아도 친구 말을 끊으면 안 돼요.","말차례는 한 사람씩 차례대로 말하는 거예요.","다른 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#18','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 예린이가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":18,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 예린이가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그런 방법도 있구나!」","correct":true},{"t":"「아니야, 빌려주는 게 맞아.」","mis":"K2-1-u1-X13"},{"t":"「오늘 급식 뭐야?」","mis":"K2-1-u1-X04"}],"explanation":["친구가 나와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"나라면 줄을 빌려주었을 거야."},{"who":"도윤","text":"나는 선생님께 줄을 빌려 달라고 했을 것 같아."},{"who":"예린","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#19','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',3,'mc','auto','친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"오늘 아침에 버스가 늦게 왔습니다.","correct":true},{"t":"저는 강소율입니다.","mis":"K2-1-u1-X16"},{"t":"제가 잘하는 것은 줄넘기입니다.","mis":"K2-1-u1-X16"}],"explanation":["「오늘 아침에 버스가 늦게 왔습니다」는 글쓴이를 알려 주는 내용이 아니에요.","이름과 꿈·좋아하는 것은 소개하는 글에 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 강소율입니다.","저는 곤충 관찰을 좋아합니다.","오늘 아침에 버스가 늦게 왔습니다.","제가 잘하는 것은 줄넘기입니다."],"title":"친구가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#20','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"하린 — 「제 동생은 아직도 밤에 이불에 실수를 합니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"지호 — 「제 동생은 블록 쌓기를 잘합니다.」","mis":"K2-1-u1-X16"},{"t":"서아 — 「저희 아빠께서는 노래를 잘 부르십니다.」","mis":"K2-1-u1-X16"}],"explanation":["동생이 부끄러워할 일을 말했어요.","소개는 존중하는 마음으로 좋은 점을 전해요.","다른 두 친구는 알맞게 소개했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#21','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 내림 → 화분을 옮김 → 칭찬을 들음","correct":true},{"t":"칭찬을 들음 → 비가 내림 → 화분을 옮김","mis":"K2-1-u1-X11"},{"t":"화분을 옮김 → 칭찬을 들음 → 비가 내림","mis":"K2-1-u1-X11"}],"explanation":["이야기의 앞에서부터 차례로 짚어요.","비가 내림 → 화분을 옮김 → 칭찬을 들음 차례예요.","까닭이 먼저, 결과가 나중에 와요."],"asset":{"type":"passage","lines":["아침부터 비가 내렸어요.","시우가 젖는 화분을 안으로 옮겼어요.","선생님께서 시우를 칭찬하셨어요."],"title":"빗속의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#22','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C10',3,'mc','auto','친구가 「저희 형은 축구를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":22,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 「저희 형은 축구를 잘합니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「형은 축구를 언제부터 했나요?」","correct":true},{"t":"「오늘 급식 뭐야?」","mis":"K2-1-u1-X04"},{"t":"「축구 잘하는 게 뭐가 대단해?」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","소개가 끝난 뒤 손을 들고 정중하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#23','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#24','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C4',4,'essay','teacher','짝에게 「좋아하는 계절이 언제야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「좋아하는 계절이 언제야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 좋아하는 계절이 언제야? / 짝: 나는 여름이 좋아. 너는? / 나: 나는 눈이 와서 겨울이 좋아. / 짝: 겨울에 같이 눈사람 만들자!","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_b#25','kor',2,1,'u1','','g2_1_kor_u1_review_b','unit_review','K2-1-u1-C8',4,'essay','teacher','나를 소개하는 글을 세 문장으로 쓰고, 좋아하는 것에는 까닭을 더해 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"나를 소개하는 글을 세 문장으로 쓰고, 좋아하는 것에는 까닭을 더해 보세요.","answer_guide":{"answer":"예: 저는 이도담입니다. / 저는 그림 그리기를 좋아합니다. 생각한 것을 마음대로 그릴 수 있기 때문입니다. / 제 꿈은 화가입니다.","scoring_points":["이름으로 시작했는가","나(그 사람)를 알려 주는 내용을 담았는가","한 문장에 한 가지씩 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["첫 문장.","알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#1','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C1',1,'mc','auto','짝이 주말 이야기를 할 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"짝이 주말 이야기를 할 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"짝을 바라보며 고개를 끄덕여요","correct":true},{"t":"짝 말을 자르고 내 주말 이야기를 해요","mis":"K2-1-u1-X02"},{"t":"딴 곳을 보며 들어요","mis":"K2-1-u1-X01"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 다른 일을 하면 잘 들을 수 없어요.","잘 들어 주면 말하는 사람도 기분이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#2','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"나의 꿈","correct":true},{"t":"지금 몇 시인지","mis":"K2-1-u1-X06"},{"t":"어제 본 뉴스","mis":"K2-1-u1-X06"}],"explanation":["나의 꿈은 나를 알려 주는 내용이에요.","다른 둘은 나와 관계가 없어요.","소개하는 글에는 나를 알려 주는 내용을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#3','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C3',1,'mc','auto','여럿이 이야기할 때 꼭 지켜야 할 것은 무엇인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"여럿이 이야기할 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"한 사람씩 차례대로 말하기","correct":true},{"t":"먼저 말하려고 크게 외치기","mis":"K2-1-u1-X03"},{"t":"말 잘하는 친구 혼자 말하기","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","먼저·크게 말하거나 혼자 계속 말하는 것은 말차례가 아니에요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#4','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',1,'mc','auto','말차례를 지키지 못한 행동은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 지키지 못한 행동은 어느 것인가요?","options":[{"t":"친구 말을 자르고 「내 말 들어 봐!」 하기","correct":true},{"t":"손을 들고 차례 기다리기","mis":"K2-1-u1-X16"},{"t":"고개를 끄덕이며 듣기","mis":"K2-1-u1-X16"}],"explanation":["친구 말을 자르는 것은 말차례를 어긴 거예요.","말하고 싶으면 손을 들고 기다려요.","친구 말이 끝나면 내 차례에 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#5','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 나무에 걸린 것은 무엇인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 나무에 걸린 것은 무엇인가요?","options":[{"t":"공","correct":true},{"t":"연","mis":"K2-1-u1-X11"},{"t":"모자","mis":"K2-1-u1-X11"}],"explanation":["글에 「태민이의 공이 나무에 걸렸어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 사람이 한 일이에요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["운동장에서 태민이의 공이 나무에 걸렸어요.","키가 큰 지호가 나뭇가지를 흔들어 공을 떨어뜨렸어요.","둘은 다시 공놀이를 했어요."],"title":"나무에 걸린 공"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#6','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C7',1,'mc','auto','「저는 공룡 책을 좋아합니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「저는 공룡 책을 좋아합니다.」는 어떤 소개 항목인가요?","options":[{"t":"좋아하는 것","correct":true},{"t":"잘하는 것","mis":"K2-1-u1-X10"},{"t":"꿈","mis":"K2-1-u1-X10"}],"explanation":["「저는 공룡 책을 좋아합니다.」는 좋아하는 것을 소개하는 문장이에요.","항목 이름이 문장에 들어 있어요.","이름·좋아하는 것·잘하는 것·꿈을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#7','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 최도윤입니다.","correct":true},{"t":"급식에 카레가 나왔습니다.","mis":"K2-1-u1-X06"},{"t":"저는 축구를 좋아합니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","나머지 내용은 이름 다음에 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#8','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람과 함께한 일","correct":true},{"t":"그 사람의 전화번호","mis":"K2-1-u1-X14"},{"t":"그 사람이 부끄러워하는 일","mis":"K2-1-u1-X14"}],"explanation":["그 사람과 함께한 일은 그 사람을 따뜻하게 알려 줘요.","개인 정보나 흉은 넣지 않아요.","존중하는 마음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#9','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C1',2,'ox','auto','고개를 끄덕이며 들으면 말하는 친구가 내가 잘 듣고 있다는 것을 알 수 있어요.',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":2,"kind":"ox","stem":"고개를 끄덕이며 들으면 말하는 친구가 내가 잘 듣고 있다는 것을 알 수 있어요.","answer":"O","reason_options":[{"t":"끄덕임은 잘 듣고 있다는 신호이니까","correct":true},{"t":"듣는 사람은 아무 반응도 하지 않아야 하니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["고개를 끄덕이면 잘 듣고 있다는 마음이 전해져요.","반응을 하면 말하는 친구도 힘이 나요.","말하는 사람을 바라보며 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#10','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',2,'mc','auto','짝이 「좋아하는 동물이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「좋아하는 동물이 뭐야?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「나는 펭귄이 좋아. 너는 어떤 동물이 좋아?」","correct":true},{"t":"「오늘 급식은 카레래.」","mis":"K2-1-u1-X04"},{"t":"「내 가방 예쁘지?」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 짝에게 되물어 차례를 건넸어요.","관계없는 말을 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#11','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 칭찬을 들은 시우의 마음은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":11,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 칭찬을 들은 시우의 마음은?","options":[{"t":"쑥스럽지만 기쁜 마음","correct":true},{"t":"슬픈 마음","mis":"K2-1-u1-X12"},{"t":"무서운 마음","mis":"K2-1-u1-X12"}],"explanation":["시우는 얼굴이 빨개졌지만 웃었어요.","칭찬을 들으면 쑥스러워도 기뻐요.","일어난 일과 인물의 말·모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["비에 젖는 화분을 시우가 안으로 옮겼어요.","선생님께서 시우를 칭찬하셨어요.","시우는 얼굴이 빨개졌지만 싱긋 웃었어요."],"title":"빗속의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#12','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C7',2,'mc','auto','「저는 축구를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「저는 축구를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구들과 함께 뛰면 신나기 때문입니다.","correct":true},{"t":"우리 집은 3층입니다.","mis":"K2-1-u1-X06"},{"t":"어제 늦잠을 잤습니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 까닭을 더했어요.","다른 문장은 앞 문장의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#13','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":13,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"제가 잘하는 것은 달리기입니다.","correct":true},{"t":"제가 잘하는 것은 달리기입니다","mis":"K2-1-u1-X08"},{"t":"달리기, 잘함","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없거나 낱말만 늘어놓으면 문장이 끝나지 않아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#14','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"한 문장 읽고 고개를 들어 친구들을 봐요","correct":true},{"t":"칠판만 보며 말해요","mis":"K2-1-u1-X15"},{"t":"종이로 얼굴을 가리고 읽어요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 크기와 빠르기로 또박또박 말해요.","작게, 빨리, 고개 숙여 말하면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#15','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C3',2,'ox','auto','목소리가 큰 사람이 먼저 말하는 것이 말차례예요.',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":15,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"목소리가 큰 사람이 먼저 말하는 것이 말차례예요.","answer":"X","reason_options":[{"t":"말차례는 한 사람씩 차례대로 말하는 것이니까","correct":true},{"t":"크게 말해야 잘 들리니까","mis":"K2-1-u1-X03"}],"mis":"K2-1-u1-X03","explanation":["목소리 크기로 차례가 정해지지 않아요.","손을 들고 차례를 기다려요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#16','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":16,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"인사를 밝게 잘합니다.","correct":true},{"t":"신발을 거꾸로 신은 적이 있습니다.","mis":"K2-1-u1-X14"},{"t":"받아쓰기를 자주 틀립니다.","mis":"K2-1-u1-X14"}],"explanation":["「는 좋은 점을 전하는 말이에요.인사를 밝게 잘합니다.」","다른 둘은 흉이 될 수 있어요.","존중하는 마음으로 좋은 점을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#17','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X05','K2-1-u1-X16']::text[],false,'{"seq":17,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 먼저 말하기 시작한 사람이 끝까지 혼자 말해요","correct":true,"mis_target":"K2-1-u1-X05"},{"t":"지호 — 내 차례에 또박또박 말해요","mis":"K2-1-u1-X16"},{"t":"다은 — 말하지 못한 친구에게 차례를 건네요","mis":"K2-1-u1-X16"}],"explanation":["한 사람이 혼자 말하면 다른 친구는 말할 수 없어요.","말차례는 한 사람씩 차례대로 말하는 거예요.","다른 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#18','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 지호가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":18,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 지호가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그럴 수도 있겠다. 어디서 그렇게 느꼈어?」","correct":true},{"t":"「틀렸어. 신났을 거야.」","mis":"K2-1-u1-X13"},{"t":"「나 어제 게임 했어.」","mis":"K2-1-u1-X04"}],"explanation":["친구가 나와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"시우는 칭찬받아서 신났을 것 같아."},{"who":"하린","text":"나는 시우가 좀 부끄러웠을 것 같아."},{"who":"지호","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#19','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',3,'mc','auto','친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"급식에 카레가 나왔습니다.","correct":true},{"t":"저는 최도윤입니다.","mis":"K2-1-u1-X16"},{"t":"제 꿈은 건축가입니다.","mis":"K2-1-u1-X16"}],"explanation":["「급식에 카레가 나왔습니다」는 글쓴이를 알려 주는 내용이 아니에요.","이름과 꿈·좋아하는 것은 소개하는 글에 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 최도윤입니다.","저는 레고 만들기를 좋아합니다.","급식에 카레가 나왔습니다.","제 꿈은 건축가입니다."],"title":"친구가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#20','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"민호 — 「제 친구 시우네 집 비밀번호는 1234입니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"소율 — 「제 친구 시우는 친구를 잘 도와줍니다.」","mis":"K2-1-u1-X16"},{"t":"예린 — 「저희 할머니께서는 떡을 잘 만드십니다.」","mis":"K2-1-u1-X16"}],"explanation":["비밀번호는 알리면 안 되는 개인 정보예요.","소개는 존중하는 마음으로 좋은 점을 전해요.","다른 두 친구는 알맞게 소개했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#21','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"모래성을 쌓음 → 파도에 무너짐 → 다시 만듦","correct":true},{"t":"파도에 무너짐 → 모래성을 쌓음 → 다시 만듦","mis":"K2-1-u1-X11"},{"t":"다시 만듦 → 모래성을 쌓음 → 파도에 무너짐","mis":"K2-1-u1-X11"}],"explanation":["이야기의 앞에서부터 차례로 짚어요.","모래성을 쌓음 → 파도에 무너짐 → 다시 만듦 차례예요.","까닭이 먼저, 결과가 나중에 와요."],"asset":{"type":"passage","lines":["지안이와 로아가 모래성을 쌓았어요.","파도에 모래성이 무너졌어요.","둘은 조개껍데기를 꽂아 다시 만들었어요."],"title":"함께 만든 모래성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#22','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C10',3,'mc','auto','친구가 「제 동생 아린이는 그림을 잘 그립니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":22,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 「제 동생 아린이는 그림을 잘 그립니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「아린이는 무엇을 즐겨 그리나요?」","correct":true},{"t":"「너 가방 새로 샀어?」","mis":"K2-1-u1-X04"},{"t":"「그림은 나도 잘 그려. 별거 아니야.」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","소개가 끝난 뒤 손을 들고 정중하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#23','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#24','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C4',4,'essay','teacher','짝에게 「주말에 뭐 하고 싶어?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「주말에 뭐 하고 싶어?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 주말에 뭐 하고 싶어? / 짝: 나는 자전거를 타고 싶어. 너는? / 나: 나는 도서관에 가고 싶어. / 짝: 다음 주말에는 둘 다 해 보자!","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_c#25','kor',2,1,'u1','','g2_1_kor_u1_review_c','unit_review','K2-1-u1-C8',4,'essay','teacher','「제 ○○ ○○○를 소개합니다.」로 시작해 주변 사람을 소개하는 글을 세 문장으로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"「제 ○○ ○○○를 소개합니다.」로 시작해 주변 사람을 소개하는 글을 세 문장으로 써 보세요.","answer_guide":{"answer":"예: 제 짝 이서윤을 소개합니다. / 서윤이는 그림을 잘 그립니다. / 서윤이는 제가 아플 때 보건실에 함께 가 주었습니다.","scoring_points":["소개할 사람을 밝히며 시작했는가","나(그 사람)를 알려 주는 내용을 담았는가","한 문장에 한 가지씩 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["첫 문장.","알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#1','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C1',1,'mc','auto','모둠 친구가 의견을 말할 때 바른 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u1-X02','K2-1-u1-X01']::text[],false,'{"seq":1,"concept":"K2-1-u1-C1","difficulty":1,"kind":"mc","stem":"모둠 친구가 의견을 말할 때 바른 듣기 태도는 어느 것인가요?","options":[{"t":"친구 말이 끝날 때까지 바라보며 들어요","correct":true},{"t":"「아니야!」 하고 바로 끼어들어요","mis":"K2-1-u1-X02"},{"t":"책상 위 물건을 만지작거려요","mis":"K2-1-u1-X01"}],"explanation":["말하는 사람을 바라보며 끝까지 들어요.","끼어들거나 다른 일을 하면 잘 들을 수 없어요.","잘 들어 주면 말하는 사람도 기분이 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#2','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C2',1,'mc','auto','나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":2,"concept":"K2-1-u1-C2","difficulty":1,"kind":"mc","stem":"나를 소개하는 글에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"내가 아끼는 물건","correct":true},{"t":"우리 동네 날씨","mis":"K2-1-u1-X06"},{"t":"텔레비전 광고","mis":"K2-1-u1-X06"}],"explanation":["내가 아끼는 물건은 나를 알려 주는 내용이에요.","다른 둘은 나와 관계가 없어요.","소개하는 글에는 나를 알려 주는 내용을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#3','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C3',1,'mc','auto','말차례를 바르게 설명한 것은 어느 것인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X05']::text[],false,'{"seq":3,"concept":"K2-1-u1-C3","difficulty":1,"kind":"mc","stem":"말차례를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"내 차례를 기다렸다가 한 사람씩 말해요","correct":true},{"t":"생각나는 사람이 먼저 크게 말해요","mis":"K2-1-u1-X03"},{"t":"한 사람이 오래오래 말해요","mis":"K2-1-u1-X05"}],"explanation":["말차례는 한 사람씩 차례대로 말하는 거예요.","먼저·크게 말하거나 혼자 계속 말하는 것은 말차례가 아니에요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#4','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C4',1,'mc','auto','말차례를 잘 지킨 행동은 어느 것인가요?',ARRAY['K2-1-u1-X03','K2-1-u1-X02']::text[],false,'{"seq":4,"concept":"K2-1-u1-C4","difficulty":1,"kind":"mc","stem":"말차례를 잘 지킨 행동은 어느 것인가요?","options":[{"t":"손을 들고 내 차례를 기다리기","correct":true},{"t":"친구와 동시에 큰 소리로 말하기","mis":"K2-1-u1-X03"},{"t":"친구 말 중간에 「아니야!」 하기","mis":"K2-1-u1-X02"}],"explanation":["손을 들고 기다리는 것이 말차례를 지킨 거예요.","말하고 싶으면 손을 들고 기다려요.","친구 말이 끝나면 내 차례에 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#5','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 크레파스를 함께 쓰자고 한 친구는 누구인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":5,"concept":"K2-1-u1-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 크레파스를 함께 쓰자고 한 친구는 누구인가요?","options":[{"t":"서아","correct":true},{"t":"하린","mis":"K2-1-u1-X11"},{"t":"민호","mis":"K2-1-u1-X11"}],"explanation":["글에 「짝 서아가 자기 크레파스를 함께 쓰자고 했어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 사람이 한 일이에요.","누가 무엇을 했는지 글에서 짚어요."],"asset":{"type":"passage","lines":["미술 시간에 하린이의 크레파스가 부러졌어요.","짝 서아가 자기 크레파스를 함께 쓰자고 했어요.","둘은 나란히 앉아 그림을 완성했어요."],"title":"부러진 크레파스"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#6','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C7',1,'mc','auto','「저는 김나래입니다.」는 어떤 소개 항목인가요?',ARRAY['K2-1-u1-X10']::text[],false,'{"seq":6,"concept":"K2-1-u1-C7","difficulty":1,"kind":"mc","stem":"「저는 김나래입니다.」는 어떤 소개 항목인가요?","options":[{"t":"이름","correct":true},{"t":"꿈","mis":"K2-1-u1-X10"},{"t":"좋아하는 것","mis":"K2-1-u1-X10"}],"explanation":["「저는 김나래입니다.」는 이름을 소개하는 문장이에요.","항목 이름이 문장에 들어 있어요.","이름·좋아하는 것·잘하는 것·꿈을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#7','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',1,'mc','auto','나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06','K2-1-u1-X07']::text[],false,'{"seq":7,"concept":"K2-1-u1-C8","difficulty":1,"kind":"mc","stem":"나를 소개하는 글의 첫 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"저는 강소율입니다.","correct":true},{"t":"버스가 늦게 왔습니다.","mis":"K2-1-u1-X06"},{"t":"제가 잘하는 것은 그림 그리기입니다.","mis":"K2-1-u1-X07"}],"explanation":["소개하는 글은 「저는 ○○○입니다.」로 시작해요.","그래야 누구의 글인지 바로 알 수 있어요.","나머지 내용은 이름 다음에 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#8','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C9',1,'mc','auto','주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":8,"concept":"K2-1-u1-C9","difficulty":1,"kind":"mc","stem":"주변 사람 소개에 넣으면 좋은 내용은 어느 것인가요?","options":[{"t":"그 사람이 잘하는 것","correct":true},{"t":"그 사람이 사는 아파트 동 호수","mis":"K2-1-u1-X14"},{"t":"그 사람이 혼난 일","mis":"K2-1-u1-X14"}],"explanation":["그 사람이 잘하는 것은 그 사람을 따뜻하게 알려 줘요.","개인 정보나 흉은 넣지 않아요.","존중하는 마음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#9','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C1',2,'ox','auto','발표를 들으며 그림을 그려도 귀만 열려 있으면 잘 듣는 거예요.',ARRAY['K2-1-u1-X01']::text[],false,'{"seq":9,"concept":"K2-1-u1-C1","difficulty":2,"kind":"ox","stem":"발표를 들으며 그림을 그려도 귀만 열려 있으면 잘 듣는 거예요.","answer":"X","reason_options":[{"t":"다른 일을 하면 말을 놓치고 친구도 속상하니까","correct":true},{"t":"귀로 소리만 들리면 되니까","mis":"K2-1-u1-X01"}],"mis":"K2-1-u1-X01","explanation":["다른 일을 하면서는 잘 들을 수 없어요.","발표하는 친구를 바라보며 들어요.","말하는 사람을 바라보며 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#10','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C4',2,'mc','auto','짝이 「쉬는 시간에 뭐 하고 놀까?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?',ARRAY['K2-1-u1-X04']::text[],false,'{"seq":10,"concept":"K2-1-u1-C4","difficulty":2,"kind":"mc","stem":"짝이 「쉬는 시간에 뭐 하고 놀까?」 하고 물었어요. 말차례를 지켜 알맞게 대답한 것은 어느 것인가요?","options":[{"t":"「공기놀이 어때? 너는 하고 싶은 놀이 있어?」","correct":true},{"t":"「어제 만화 진짜 재밌었어.」","mis":"K2-1-u1-X04"},{"t":"「나 숙제 다 했다!」","mis":"K2-1-u1-X04"}],"explanation":["묻는 말에 맞게 대답했어요.","그리고 짝에게 되물어 차례를 건넸어요.","관계없는 말을 하면 대화가 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#11','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C6',2,'mc','auto','이야기를 읽고 답해 보세요. 머리핀을 찾지 못한 예린이의 마음은?',ARRAY['K2-1-u1-X12']::text[],false,'{"seq":11,"concept":"K2-1-u1-C6","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 머리핀을 찾지 못한 예린이의 마음은?","options":[{"t":"속상하고 아쉬운 마음","correct":true},{"t":"뿌듯한 마음","mis":"K2-1-u1-X12"},{"t":"설레는 마음","mis":"K2-1-u1-X12"}],"explanation":["예린이는 고개를 푹 숙였어요.","아끼던 것을 잃어버리면 속상해요.","일어난 일과 인물의 말·모습에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["예린이가 아끼던 머리핀을 잃어버렸어요.","하루 종일 교실 구석구석을 찾았지만 없었어요.","예린이는 고개를 푹 숙였어요."],"title":"잃어버린 머리핀"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#12','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C7',2,'mc','auto','「저는 고양이를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X06']::text[],false,'{"seq":12,"concept":"K2-1-u1-C7","difficulty":2,"kind":"mc","stem":"「저는 고양이를 좋아합니다.」에 까닭을 더해 이어 쓸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"부드러운 털을 쓰다듬으면 기분이 좋기 때문입니다.","correct":true},{"t":"마트는 크기 때문입니다.","mis":"K2-1-u1-X06"},{"t":"동생은 우유를 싫어합니다.","mis":"K2-1-u1-X06"}],"explanation":["「~기 때문입니다」로 까닭을 더했어요.","다른 문장은 앞 문장의 까닭이 아니에요.","까닭은 「왜?」에 대한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#13','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',2,'mc','auto','문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u1-X08']::text[],false,'{"seq":13,"concept":"K2-1-u1-C8","difficulty":2,"kind":"mc","stem":"문장의 끝을 바르게 맺어 쓴 것은 어느 것인가요?","options":[{"t":"저는 오지안입니다.","correct":true},{"t":"저는 오지안입니다","mis":"K2-1-u1-X08"},{"t":"저는, 지안","mis":"K2-1-u1-X08"}],"explanation":["문장이 끝나면 끝에 마침표(.)를 찍어요.","마침표가 없거나 낱말만 늘어놓으면 문장이 끝나지 않아요.","다 쓴 뒤 문장 끝을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#14','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C10',2,'mc','auto','소개하는 글을 발표할 때 바른 모습은 어느 것인가요?',ARRAY['K2-1-u1-X15']::text[],false,'{"seq":14,"concept":"K2-1-u1-C10","difficulty":2,"kind":"mc","stem":"소개하는 글을 발표할 때 바른 모습은 어느 것인가요?","options":[{"t":"맨 뒤 친구에게도 들리게 또박또박 말해요","correct":true},{"t":"앞자리 친구에게만 들리게 속삭여요","mis":"K2-1-u1-X15"},{"t":"한 번에 몰아서 빠르게 읽어요","mis":"K2-1-u1-X15"}],"explanation":["듣는 친구들을 바라보며 말해요.","알맞은 크기와 빠르기로 또박또박 말해요.","작게, 빨리, 고개 숙여 말하면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#15','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C3',2,'ox','auto','친구 말에 끼어들면 말하던 친구가 속상할 수 있어요.',ARRAY['K2-1-u1-X03']::text[],false,'{"seq":15,"concept":"K2-1-u1-C3","difficulty":2,"kind":"ox","stem":"친구 말에 끼어들면 말하던 친구가 속상할 수 있어요.","answer":"O","reason_options":[{"t":"하고 싶은 말을 끝내지 못하니까","correct":true},{"t":"끼어들면 대화가 더 재미있어지니까","mis":"K2-1-u1-X03"}],"mis":"K2-1-u1-X03","explanation":["말이 끊긴 친구는 속상해요.","친구 말이 끝날 때까지 기다려요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#16','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C9',2,'mc','auto','주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?',ARRAY['K2-1-u1-X14']::text[],false,'{"seq":16,"concept":"K2-1-u1-C9","difficulty":2,"kind":"mc","stem":"주변 사람을 소개할 때 따뜻한 소개말은 어느 것인가요?","options":[{"t":"동생을 잘 돌봐 줍니다.","correct":true},{"t":"방을 잘 안 치웁니다.","mis":"K2-1-u1-X14"},{"t":"편식을 합니다.","mis":"K2-1-u1-X14"}],"explanation":["「는 좋은 점을 전하는 말이에요.동생을 잘 돌봐 줍니다.」","다른 둘은 흉이 될 수 있어요.","존중하는 마음으로 좋은 점을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#17','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C4',3,'error','auto','모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X16']::text[],false,'{"seq":17,"concept":"K2-1-u1-C4","difficulty":3,"kind":"error","stem":"모둠 친구들이 말차례에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 짝이 물으면 내가 하고 싶은 말만 하면 돼요","correct":true,"mis_target":"K2-1-u1-X04"},{"t":"민호 — 묻는 말에 맞게 대답해요","mis":"K2-1-u1-X16"},{"t":"서아 — 대답한 뒤 짝에게도 물어봐요","mis":"K2-1-u1-X16"}],"explanation":["묻는 말과 관계없는 말을 하면 대화가 끊겨요.","말차례는 한 사람씩 차례대로 말하는 거예요.","다른 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#18','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C6',3,'mc','auto','이야기를 읽고 생각을 나누고 있어요. 소율이가 이어서 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X13','K2-1-u1-X04']::text[],false,'{"seq":18,"concept":"K2-1-u1-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 생각을 나누고 있어요. 소율이가 이어서 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「좋은 생각이다. 어떤 머리핀을 줄 거야?」","correct":true},{"t":"「그런 건 쓸데없어.」","mis":"K2-1-u1-X13"},{"t":"「나 지금 졸려.」","mis":"K2-1-u1-X04"}],"explanation":["친구가 나와 다른 생각을 말했어요.","다른 생각을 인정하고 까닭을 물으면 이야기가 이어져요.","틀렸다고 하거나 관계없는 말을 하면 나누기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"나는 예린이가 머리핀을 꼭 찾았으면 좋겠어."},{"who":"태민","text":"나는 예린이에게 새 머리핀을 선물해 주고 싶어."},{"who":"소율","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#19','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',3,'mc','auto','친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?',ARRAY['K2-1-u1-X16']::text[],false,'{"seq":19,"concept":"K2-1-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 쓴 소개 글을 보고 답해 보세요. 다듬을 때 빼야 할 문장은 어느 것인가요?","options":[{"t":"지금 창밖에 비가 옵니다.","correct":true},{"t":"저는 오예린입니다.","mis":"K2-1-u1-X16"},{"t":"제가 잘하는 것은 피아노 치기입니다.","mis":"K2-1-u1-X16"}],"explanation":["「지금 창밖에 비가 옵니다」는 글쓴이를 알려 주는 내용이 아니에요.","이름과 꿈·좋아하는 것은 소개하는 글에 맞는 문장이에요.","다시 읽으며 관계없는 문장을 빼요."],"asset":{"type":"passage","lines":["저는 오예린입니다.","저는 노래 부르기를 좋아합니다.","지금 창밖에 비가 옵니다.","제가 잘하는 것은 피아노 치기입니다."],"title":"친구가 쓴 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#20','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C9',3,'error','auto','친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u1-X14','K2-1-u1-X16']::text[],false,'{"seq":20,"concept":"K2-1-u1-C9","difficulty":3,"kind":"error","stem":"친구들이 주변 사람을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"로아 — 「제 짝 하람이는 지난번에 넘어져서 엉엉 울었습니다.」","correct":true,"mis_target":"K2-1-u1-X14"},{"t":"도윤 — 「제 짝 하람이는 그림을 잘 그립니다.」","mis":"K2-1-u1-X16"},{"t":"서윤 — 「저희 언니는 동생을 잘 돌봐 줍니다.」","mis":"K2-1-u1-X16"}],"explanation":["짝이 부끄러워할 일을 말했어요.","소개는 존중하는 마음으로 좋은 점을 전해요.","다른 두 친구는 알맞게 소개했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#21','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X11']::text[],false,'{"seq":21,"concept":"K2-1-u1-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"물통을 쏟음 → 함께 닦음 → 고맙다고 함","correct":true},{"t":"함께 닦음 → 물통을 쏟음 → 고맙다고 함","mis":"K2-1-u1-X11"},{"t":"고맙다고 함 → 함께 닦음 → 물통을 쏟음","mis":"K2-1-u1-X11"}],"explanation":["이야기의 앞에서부터 차례로 짚어요.","물통을 쏟음 → 함께 닦음 → 고맙다고 함 차례예요.","까닭이 먼저, 결과가 나중에 와요."],"asset":{"type":"passage","lines":["예린이가 물통을 쏟았어요.","준우가 휴지로 바닥을 함께 닦았어요.","예린이가 「고마워.」 하고 웃었어요."],"title":"쏟아진 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#22','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C10',3,'mc','auto','친구가 「저희 할아버지께서는 텃밭에서 채소를 잘 기르십니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u1-X04','K2-1-u1-X13']::text[],false,'{"seq":22,"concept":"K2-1-u1-C10","difficulty":3,"kind":"mc","stem":"친구가 「저희 할아버지께서는 텃밭에서 채소를 잘 기르십니다.」 하고 소개했어요. 소개를 듣고 할 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「할아버지께서는 어떤 채소를 기르시나요?」","correct":true},{"t":"「주말에 뭐 할 거야?」","mis":"K2-1-u1-X04"},{"t":"「채소는 맛없어.」","mis":"K2-1-u1-X13"}],"explanation":["소개한 내용과 관련 있는 것을 물어요.","관계없는 질문이나 깎아내리는 말은 하지 않아요.","소개가 끝난 뒤 손을 들고 정중하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#23','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',4,'mc','auto','두 친구가 쓴 소개 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#24','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C4',4,'essay','teacher','짝에게 「좋아하는 책이 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u1-C4","difficulty":4,"kind":"essay","stem":"짝에게 「좋아하는 책이 뭐야?」 하고 물었을 때 이어질 대화를 말차례를 지켜 네 마디로 써 보세요.","answer_guide":{"answer":"예: 나: 좋아하는 책이 뭐야? / 짝: 나는 공룡 책을 좋아해. 너는? / 나: 나는 동물 이야기책을 좋아해. / 짝: 우리 서로 바꿔 읽어 볼래?","scoring_points":["한 사람씩 번갈아 네 마디를 썼는가","묻는 말에 알맞게 대답했는가","되묻거나 이어 말해 대화가 이어졌는가"]},"explanation":["번갈아 말하기.","알맞은 대답.","대화 잇기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u1_review_d#25','kor',2,1,'u1','','g2_1_kor_u1_review_d','unit_review','K2-1-u1-C8',4,'essay','teacher','처음 만난 친구에게 나를 소개하는 글을 네 문장으로 써 보세요. 친구가 궁금해할 내용을 골라요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u1-C8","difficulty":4,"kind":"essay","stem":"처음 만난 친구에게 나를 소개하는 글을 네 문장으로 써 보세요. 친구가 궁금해할 내용을 골라요.","answer_guide":{"answer":"예: 저는 박지후입니다. / 제가 좋아하는 놀이는 숨바꼭질입니다. / 제가 잘하는 것은 달리기입니다. / 쉬는 시간에 같이 놀아요.","scoring_points":["이름으로 시작했는가","나(그 사람)를 알려 주는 내용을 담았는가","한 문장에 한 가지씩 문장으로 쓰고 마침표를 찍었는가"]},"explanation":["첫 문장.","알려 주는 내용.","한 문장에 한 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C1','kor',2,1,'u2',1,'낱말의 이름과 특징 잇기 — 가랑비·이슬비·장대비·단비처럼 같은 것도 모습·쓰임(특징)에 따라 이름이 다르고, 이름에는 그렇게 붙은 까닭이 있음을 알기',ARRAY['2국05-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C2','kor',2,1,'u2',1,'첫 글자가 같은 낱말 모으기 — 낱말의 맨 앞 글자를 살펴 같은 글자로 시작하는 낱말을 모으고(비누·비행기·비빔밥), 모은 낱말로 짧은 말을 만들며 말의 재미를 느끼기',ARRAY['2국05-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C3','kor',2,1,'u2',3,'꼬리따기 말놀이 — 「사과는 빨개, 빨가면 딸기」처럼 바로 앞말에서 떠오르는 것을 이어 말해 말이 꼬리에 꼬리를 물게 하기',ARRAY['2국05-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C4','kor',2,1,'u2',3,'다섯 글자 말놀이·말 덧붙이기 — 하고 싶은 말을 글자 수(띄어쓰기 빼고)를 세어 다섯 글자로 만들고, 앞 사람 말을 그대로 되풀이한 뒤 한 가지씩 더해 말하기',ARRAY['2국05-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C5','kor',2,1,'u2',3,'말놀이 규칙과 좋은 점 — 차례를 기다리고 친구 말을 끝까지 듣고 놀리지 않으며 함께 즐기기, 말놀이로 여러 낱말을 익히고 친구와 함께 웃을 수 있음을 알기',ARRAY['2국05-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C6','kor',2,1,'u2',6,'주변에서 낱말 찾기 — 교실·부엌·공원 같은 장소를 떠올려 그곳에서 볼 수 있는 낱말을 찾고, 뒤섞인 글자를 바르게 맞추어 숨은 낱말 찾기',ARRAY['2국03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C7','kor',2,1,'u2',6,'낱말로 문장·줄줄이 이야기 만들기 — 낱말을 「누가 무엇을 어찌해요」로 이어 문장을 만들고, 친구 문장을 잘 듣고 앞 문장과 이어지게 한 문장씩 더해 이야기 만들기',ARRAY['2국03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C8','kor',2,1,'u2',8,'글 읽고 내용·흉내 내는 말 찾기 — 글에서 누가·무엇을·어떻게 했는지 찾고, 소리를 흉내 낸 말(맴맴·지글지글)과 모양을 흉내 낸 말(깡충깡충·데굴데굴)을 찾아 글을 생생하게 만드는 재미를 느끼기',ARRAY['2국02-05']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C9','kor',2,1,'u2',8,'글 읽고 생각·느낌 표현하기 — 재미있는 장면·문장을 골라 떠오른 내 경험과 까닭을 들어 생각이나 느낌을 말하고, 친구의 다른 느낌도 인정하기',ARRAY['2국02-05']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C10','kor',2,1,'u2',10,'좋아하는 문장 소개하기·책갈피 — 책 제목 → 좋아하는 문장 → 좋아하는 까닭 차례로 소개하고, 마음에 드는 짧은 문장 한 줄을 적어 책갈피 만들기',ARRAY['2국03-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C11','kor',2,1,'u2',12,'낱말로 재미있는 이름 짓기 — 소리·모양 흉내 말을 넣거나 같은 소리를 되풀이하고 무엇의 특징(맛·모양)을 살려 재미있는 이름을 짓고, 친구를 놀리는 말은 쓰지 않기',ARRAY['2국05-01']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X01','kor',2,'u2',ARRAY['K2-1-u2-C1']::text[],'이름과 특징을 거꾸로 잇는다 — 가랑비를 굵은 비로, 장대비를 가는 비로 여기거나 이름에 까닭이 없다고 여긴다','이름 속 낱말(장대·이슬·단)이 무엇을 닮았는지 먼저 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X02','kor',2,'u2',ARRAY['K2-1-u2-C2']::text[],'첫 글자 대신 끝 글자나 가운데 글자가 같은 낱말을 고른다(「비」로 시작 → 나비·제비)','낱말의 맨 앞 글자에 손가락을 대고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X03','kor',2,'u2',ARRAY['K2-1-u2-C2']::text[],'자음자만 같으면 같은 글자로 여긴다(바·버·보를 같은 첫 글자로)','첫 글자를 통째로 소리 내어 견주기 — 바, 버, 보는 다른 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X04','kor',2,'u2',ARRAY['K2-1-u2-C3']::text[],'꼬리따기에서 앞말에서 떠오르지 않는 엉뚱한 말을 붙인다(빨가면 바나나)','「빨가면?」 하고 앞말을 한 번 더 말한 뒤 떠오르는 것 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X05','kor',2,'u2',ARRAY['K2-1-u2-C3']::text[],'꼬리따기에서 바로 앞말이 아니라 맨 처음 낱말로 돌아가거나 같은 말을 되풀이한다','꼬리는 늘 바로 앞 친구의 마지막 말에서 이어 가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X06','kor',2,'u2',ARRAY['K2-1-u2-C4']::text[],'글자 수를 셀 때 낱말 수로 세거나 띄어 쓴 칸·문장 부호까지 센다','글자 하나에 손가락 하나씩 접으며 세기 — 빈칸은 세지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X07','kor',2,'u2',ARRAY['K2-1-u2-C4']::text[],'말 덧붙이기에서 앞 사람 말을 빠뜨리거나 차례를 바꾸고 새것만 말한다','앞 사람 말을 처음부터 그대로 한 번 말하고 끝에 하나 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X08','kor',2,'u2',ARRAY['K2-1-u2-C5','K2-1-u2-C11']::text[],'말놀이는 이기는 것이 가장 중요하다고 여겨 차례를 무시하고 끼어들거나 혼자 정한다','「지금 누구 차례지? 다 같이 즐겁나?」 먼저 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X09','kor',2,'u2',ARRAY['K2-1-u2-C5','K2-1-u2-C10','K2-1-u2-C11']::text[],'친구 말이 틀리거나 우스우면 놀리고, 친구를 놀리는 말로 말놀이·이름 짓기를 한다','「이 말을 들으면 친구가 기분 좋을까?」 한 번 묻고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X10','kor',2,'u2',ARRAY['K2-1-u2-C6']::text[],'장소와 어울리지 않는 낱말을 그 장소의 낱말로 고른다(부엌 — 칠판)','그 장소에 서 있다고 떠올리고 눈앞에 보이는 것만 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X11','kor',2,'u2',ARRAY['K2-1-u2-C6']::text[],'뒤섞인 글자를 맞출 때 놓인 순서대로 읽거나 글자를 빠뜨리고 더한다','글자 카드를 모두 한 번씩 썼는지 하나씩 지우며 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X12','kor',2,'u2',ARRAY['K2-1-u2-C7']::text[],'낱말만 늘어놓아 문장이 되지 않게 말한다(토끼 당근 먹어)','「누가? 무엇을? 어찌해요?」로 이어 끝까지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X13','kor',2,'u2',ARRAY['K2-1-u2-C7']::text[],'줄줄이 이야기에 앞 문장·인물과 관계없는 문장을 이어 이야기가 끊긴다','앞 친구 문장의 인물 이름을 넣어 다음 문장 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X14','kor',2,'u2',ARRAY['K2-1-u2-C8','K2-1-u2-C9','K2-1-u2-C10']::text[],'글에 없는 내용을 있다고 하거나 글의 인물·일을 바꾸어 말한다','답을 고르기 전에 글에서 그 말을 찾아 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X15','kor',2,'u2',ARRAY['K2-1-u2-C8','K2-1-u2-C11']::text[],'흉내 내는 말이 아닌 낱말(여름날·시원하다·강아지)을 흉내 내는 말로 여기거나 무엇의 소리·모양인지 헷갈린다','소리 내어 따라 했을 때 소리나 모습이 들리고 보이면 흉내 내는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X16','kor',2,'u2',ARRAY['K2-1-u2-C9']::text[],'느낌을 까닭 없이 말하거나 글과 반대로 짐작하고, 나와 다른 느낌은 틀렸다고 여긴다','「어느 장면에서? 왜?」를 붙여 말하고 친구 느낌은 「그럴 수 있구나」로 받기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X17','kor',2,'u2',ARRAY['K2-1-u2-C10']::text[],'책을 소개할 때 제목·좋아하는 문장·까닭을 빠뜨리거나, 책갈피에 책을 통째로 옮겨 적는다','「제목 → 문장 → 까닭」 세 손가락을 접으며 소개하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X18','kor',2,'u2',ARRAY['K2-1-u2-C11']::text[],'무엇을 파는지도, 소리의 재미도 드러나지 않는 이름(가게1호·음식 파는 곳)도 재미있는 이름이라고 여긴다','이름만 듣고 무엇인지 떠오르는지, 소리 내어 읽으면 재미있는지 두 번 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X19','kor',2,'u2',ARRAY['K2-1-u2-C2','K2-1-u2-C5','K2-1-u2-C6','K2-1-u2-C7','K2-1-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 다른 것↔같은 것, 어울리지 않는 것↔어울리는 것, 지키지 못한↔지킨','물음의 「다른·않는·못한」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#1','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',1,'mc','auto','가늘게 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],true,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"가늘게 내리는 비를 무엇이라고 하나요?","options":[{"t":"가랑비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"단비","mis":"K2-1-u2-X01"}],"explanation":["가늘게 내리는 비는 가랑비예요.","장대비는 굵고 세차게, 단비는 꼭 필요할 때 내리는 비예요.","비가 내리는 모습을 보고 이름을 떠올려요."],"variant_rule":{"alt":[{"stem":"굵고 세차게 내리는 비를 무엇이라고 하나요?","options":[{"t":"장대비","correct":true},{"t":"이슬비","mis":"K2-1-u2-X01"},{"t":"가랑비","mis":"K2-1-u2-X01"}],"explanation":["굵고 세차게 내리는 비는 장대비예요.","이슬비와 가랑비는 가늘게 내리는 비예요.","긴 장대처럼 굵은 빗줄기를 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#2','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',1,'mc','auto','메마른 땅에 꼭 필요할 때 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],true,'{"seq":2,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"메마른 땅에 꼭 필요할 때 내리는 비를 무엇이라고 하나요?","options":[{"t":"단비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"이슬비","mis":"K2-1-u2-X01"}],"explanation":["꼭 필요할 때 내려 반가운 비는 단비예요.","장대비는 굵게, 이슬비는 아주 가늘게 내리는 비예요.","이름에는 그렇게 부르는 까닭이 있어요."],"variant_rule":{"alt":[{"stem":"이슬처럼 아주 가늘게 내리는 비를 무엇이라고 하나요?","options":[{"t":"이슬비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"단비","mis":"K2-1-u2-X01"}],"explanation":["이슬처럼 가늘게 내리는 비는 이슬비예요.","장대비는 굵고 세차게 내리고, 단비는 꼭 필요할 때 내려요.","이름 속 「이슬」이 특징을 알려 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#3','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',1,'mc','auto','「비」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],true,'{"seq":3,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「비」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"비누","correct":true},{"t":"나비","mis":"K2-1-u2-X02"},{"t":"버스","mis":"K2-1-u2-X03"}],"explanation":["비누는 첫 글자가 「비」예요.","나비는 「비」가 끝에 있고, 버스는 「버」로 시작해요.","낱말의 맨 앞 글자를 살펴요."],"variant_rule":{"alt":[{"stem":"「가」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"가방","correct":true},{"t":"아가","mis":"K2-1-u2-X02"},{"t":"고래","mis":"K2-1-u2-X03"}],"explanation":["가방은 첫 글자가 「가」예요.","아가는 「가」가 끝에 있고, 고래는 「고」로 시작해요.","낱말의 맨 앞 글자를 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#4','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',1,'ox','auto','「나비」는 「비」로 시작하는 낱말이에요.',ARRAY['K2-1-u2-X02']::text[],true,'{"seq":4,"concept":"K2-1-u2-C2","difficulty":1,"kind":"ox","stem":"「나비」는 「비」로 시작하는 낱말이에요.","answer":"X","reason_options":[{"t":"첫 글자가 「나」이고 「비」는 끝 글자이니까","correct":true},{"t":"「비」가 들어 있으니까","mis":"K2-1-u2-X02"}],"mis":"K2-1-u2-X02","explanation":["나비의 첫 글자는 「나」예요.","글자가 들어 있다고 그 글자로 시작하는 것은 아니에요.","맨 앞 글자를 손가락으로 짚어 봐요."],"variant_rule":{"alt":[{"stem":"「바나나」는 「바」로 시작하는 낱말이에요.","answer":"O","reason_options":[{"t":"맨 앞 글자가 「바」이니까","correct":true},{"t":"「나」가 두 번 나오니까","mis":"K2-1-u2-X02"}],"explanation":["바나나의 맨 앞 글자는 「바」예요.","몇 번 나오는지가 아니라 맨 앞 글자를 봐요.","그래서 「바」로 시작하는 낱말이 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#5','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',2,'match','auto','비의 이름과 특징을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C1","difficulty":2,"kind":"match","stem":"비의 이름과 특징을 알맞게 이어 보세요.","pairs":[{"l":"가랑비","r":"가늘게 내려요"},{"l":"장대비","r":"굵고 세차게 내려요"},{"l":"단비","r":"꼭 필요할 때 내려요"}],"mis":"K2-1-u2-X01","explanation":["가랑비는 가늘게 내리는 비예요.","장대비는 굵고 세차게 내리는 비예요.","단비는 꼭 필요할 때 내리는 반가운 비예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비의 이름과 특징을 알맞게 이어 보세요.","pairs":[{"l":"이슬비","r":"이슬처럼 아주 가늘게 내려요"},{"l":"장대비","r":"장대처럼 굵게 쏟아져요"},{"l":"단비","r":"가뭄 끝에 반갑게 내려요"}],"explanation":["이슬비는 이슬처럼 아주 가늘게 내려요.","장대비는 장대처럼 굵게 쏟아져요.","단비는 꼭 필요할 때 내려 반가운 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#6','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],true,'{"seq":6,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"사과 · 사자 · 사탕","correct":true},{"t":"사과 · 과자 · 자두","mis":"K2-1-u2-X02"},{"t":"사과 · 소금 · 수박","mis":"K2-1-u2-X03"}],"explanation":["사과·사자·사탕은 모두 「사」로 시작해요.","사과·과자·자두는 끝 글자를 이은 것이고, 소금·수박은 「소」·「수」로 시작해요.","맨 앞 글자가 모두 같아야 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"고래 · 고구마 · 고양이","correct":true},{"t":"고구마 · 마늘 · 늘보","mis":"K2-1-u2-X02"},{"t":"고래 · 기차 · 구두","mis":"K2-1-u2-X03"}],"explanation":["고래·고구마·고양이는 모두 「고」로 시작해요.","고구마·마늘·늘보는 끝 글자를 이은 것이고, 기차·구두는 「기」·「구」로 시작해요.","맨 앞 글자가 모두 같아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#7','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',2,'sa','auto','비누, 비행기, 비빔밥은 모두 어떤 글자로 시작하나요? 한 글자로 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u2-C2","difficulty":2,"kind":"sa","stem":"비누, 비행기, 비빔밥은 모두 어떤 글자로 시작하나요? 한 글자로 써 보세요.","answer":["비"],"explanation":["세 낱말은 모두 「비」로 시작해요.","맨 앞 글자만 보면 돼요.","첫 글자가 같은 낱말을 모으는 것도 말놀이예요."],"variant_rule":{"alt":[{"stem":"가방, 가위, 가지는 모두 어떤 글자로 시작하나요? 한 글자로 써 보세요.","answer":["가"],"explanation":["세 낱말은 모두 「가」로 시작해요.","맨 앞 글자만 보면 돼요.","같은 글자로 시작하는 낱말을 더 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#8','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',2,'mc','auto','「단비」라는 이름이 붙은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X01']::text[],true,'{"seq":8,"concept":"K2-1-u2-C1","difficulty":2,"kind":"mc","stem":"「단비」라는 이름이 붙은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"꼭 필요할 때 내려 반가운 비라서","correct":true},{"t":"굵고 세차게 쏟아지는 비라서","mis":"K2-1-u2-X01"},{"t":"이슬처럼 아주 가늘게 내리는 비라서","mis":"K2-1-u2-X01"}],"explanation":["단비는 메마른 땅에 꼭 필요할 때 내리는 비예요.","굵게 쏟아지는 비는 장대비, 아주 가는 비는 이슬비예요.","이름에는 특징이 담겨 있어요."],"variant_rule":{"alt":[{"stem":"「장대비」라는 이름이 붙은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"긴 장대처럼 굵고 세차게 내리는 비라서","correct":true},{"t":"가늘게 조용히 내리는 비라서","mis":"K2-1-u2-X01"},{"t":"꼭 필요할 때 내리는 비라서","mis":"K2-1-u2-X01"}],"explanation":["장대비는 굵고 세차게 쏟아지는 비예요.","가늘게 내리는 비는 가랑비, 꼭 필요할 때 내리는 비는 단비예요.","이름 속 「장대」가 특징을 알려 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#9','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',2,'ox','auto','「장대비」는 가늘고 조용히 내리는 비예요.',ARRAY['K2-1-u2-X01']::text[],true,'{"seq":9,"concept":"K2-1-u2-C1","difficulty":2,"kind":"ox","stem":"「장대비」는 가늘고 조용히 내리는 비예요.","answer":"X","reason_options":[{"t":"장대비는 굵고 세차게 내리는 비이니까","correct":true},{"t":"비는 이름만 다르고 모두 똑같으니까","mis":"K2-1-u2-X01"}],"mis":"K2-1-u2-X01","explanation":["장대비는 굵고 세차게 쏟아지는 비예요.","가늘게 내리는 비는 가랑비나 이슬비예요.","이름마다 특징이 달라요."],"variant_rule":{"alt":[{"stem":"같은 비라도 내리는 모습에 따라 이름이 달라요.","answer":"O","reason_options":[{"t":"특징을 보고 이름을 붙이니까","correct":true},{"t":"이름은 아무렇게나 붙이니까","mis":"K2-1-u2-X01"}],"explanation":["비가 내리는 모습이 다르면 이름도 달라요.","이름에는 그렇게 부르는 까닭이 있어요.","특징을 보면 이름을 떠올릴 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#10','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',3,'error','auto','「바」로 시작하는 낱말을 말하는 놀이를 했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X03','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C2","difficulty":3,"kind":"error","stem":"「바」로 시작하는 낱말을 말하는 놀이를 했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「보물!」","correct":true,"mis_target":"K2-1-u2-X03"},{"t":"다은 — 「바지!」","mis":"K2-1-u2-X19"},{"t":"서윤 — 「바다!」","mis":"K2-1-u2-X19"}],"explanation":["보물은 「보」로 시작해요.","「바」와 「보」는 자음자는 같아도 다른 글자예요.","다은이와 서윤이는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"「구」로 시작하는 낱말을 말하는 놀이를 했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「야구!」","correct":true,"mis_target":"K2-1-u2-X02"},{"t":"하린 — 「구름!」","mis":"K2-1-u2-X19"},{"t":"민호 — 「구두!」","mis":"K2-1-u2-X19"}],"explanation":["야구는 「야」로 시작하고 「구」는 끝 글자예요.","맨 앞 글자가 「구」여야 해요.","하린이와 민호는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#1','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',2,'mc','auto','「보슬비」라는 이름에 어울리는 특징은 어느 것인가요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":2,"kind":"mc","stem":"「보슬비」라는 이름에 어울리는 특징은 어느 것인가요?","options":[{"t":"보슬보슬 가늘고 부드럽게 내려요","correct":true},{"t":"우르르 쾅쾅 세차게 쏟아져요","mis":"K2-1-u2-X01"},{"t":"굵은 우박이 섞여 떨어져요","mis":"K2-1-u2-X01"}],"explanation":["「보슬보슬」은 가늘고 부드럽게 내리는 모양이에요.","세차게 쏟아지는 비는 장대비에 가까워요.","이름 속 흉내 내는 말이 특징을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#2','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',2,'mc','auto','첫 글자가 다른 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 다른 낱말은 어느 것인가요?","options":[{"t":"노루","correct":true},{"t":"나비","mis":"K2-1-u2-X19"},{"t":"나팔","mis":"K2-1-u2-X19"}],"explanation":["노루만 「노」로 시작해요.","나비와 나팔은 「나」로 시작해요.","「다른 것」을 묻는지 물음을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#3','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',3,'mc','auto','「비」로 시작하는 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":3,"concept":"K2-1-u2-C2","difficulty":3,"kind":"mc","stem":"「비」로 시작하는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"비누 · 비옷 · 비둘기","correct":true},{"t":"나비 · 제비 · 비누","mis":"K2-1-u2-X02"},{"t":"비누 · 부채 · 바다","mis":"K2-1-u2-X03"}],"explanation":["비누·비옷·비둘기는 모두 맨 앞 글자가 「비」예요.","나비·제비는 「비」가 끝에 있고, 부채·바다는 「부」·「바」로 시작해요.","세 낱말 모두 맨 앞 글자를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#4','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',3,'mc','auto','창밖에 빗방울이 「톡톡」 작게 떨어져요. 이 모습에 어울리게 새로 지은 비 이름은 어느 것인가요?',ARRAY['K2-1-u2-X01','K2-1-u2-X18']::text[],false,'{"seq":4,"concept":"K2-1-u2-C1","difficulty":3,"kind":"mc","stem":"창밖에 빗방울이 「톡톡」 작게 떨어져요. 이 모습에 어울리게 새로 지은 비 이름은 어느 것인가요?","options":[{"t":"톡톡비","correct":true},{"t":"콸콸비","mis":"K2-1-u2-X01"},{"t":"첫째비","mis":"K2-1-u2-X18"}],"explanation":["톡톡 떨어지는 모습이 이름에 드러나요.","콸콸비는 세차게 쏟아지는 모습이고, 첫째비는 모습이 드러나지 않아요.","특징이 드러나게 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#5','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',3,'ox','auto','첫 글자 말놀이는 맨 앞 글자가 같은 낱말을 모으는 놀이예요.',ARRAY['K2-1-u2-X02']::text[],false,'{"seq":5,"concept":"K2-1-u2-C2","difficulty":3,"kind":"ox","stem":"첫 글자 말놀이는 맨 앞 글자가 같은 낱말을 모으는 놀이예요.","answer":"O","reason_options":[{"t":"낱말의 맨 앞 글자를 보고 모으니까","correct":true},{"t":"어느 자리든 같은 글자가 하나라도 있으면 되니까","mis":"K2-1-u2-X02"}],"mis":"K2-1-u2-X02","explanation":["첫 글자 말놀이는 맨 앞 글자를 봐요.","가운데나 끝 글자가 같은 것은 첫 글자 말놀이가 아니에요.","비누·비행기·비빔밥처럼 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#6','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',3,'error','auto','친구들이 비 이름의 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X01','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C1","difficulty":3,"kind":"error","stem":"친구들이 비 이름의 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지후 — 「이슬비는 굵고 세차게 내려서 붙은 이름이야.」","correct":true,"mis_target":"K2-1-u2-X01"},{"t":"서윤 — 「단비는 꼭 필요할 때 내려서 붙은 이름이야.」","mis":"K2-1-u2-X19"},{"t":"시우 — 「장대비는 장대처럼 굵게 내려서 붙은 이름이야.」","mis":"K2-1-u2-X19"}],"explanation":["이슬비는 이슬처럼 아주 가늘게 내리는 비예요.","굵고 세차게 내리는 비는 장대비예요.","서윤이와 시우는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#7','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',3,'mc','auto','「바」로 시작하는 낱말을 모두 바르게 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X03','K2-1-u2-X02']::text[],false,'{"seq":7,"concept":"K2-1-u2-C2","difficulty":3,"kind":"mc","stem":"「바」로 시작하는 낱말을 모두 바르게 모은 것은 어느 것인가요?","options":[{"t":"바람 · 바위 · 바늘","correct":true},{"t":"바람 · 버섯 · 보리","mis":"K2-1-u2-X03"},{"t":"바람 · 가방 · 나방","mis":"K2-1-u2-X02"}],"explanation":["바람·바위·바늘은 모두 「바」로 시작해요.","버섯·보리는 「버」·「보」로, 가방·나방은 「가」·「나」로 시작해요.","첫 글자를 통째로 소리 내어 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#8','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',4,'mc','auto','두 친구가 햇빛이 날 때 잠깐 내리는 비에 이름을 지었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#9','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',4,'essay','teacher','「사」로 시작하는 낱말을 세 개 모아 쓰고, 그 낱말을 넣어 짧은 문장을 하나 만들어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C2","difficulty":4,"kind":"essay","stem":"「사」로 시작하는 낱말을 세 개 모아 쓰고, 그 낱말을 넣어 짧은 문장을 하나 만들어 보세요.","answer_guide":{"answer":"예: 사과, 사자, 사탕 / 사자가 사과와 사탕을 먹어요.","scoring_points":["맨 앞 글자가 「사」인 낱말을 세 개 썼는가","모은 낱말을 넣어 문장으로 썼는가","문장 끝에 마침표를 찍었는가"]},"explanation":["첫 글자 「사」.","낱말 넣어 문장.","마침표."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#10','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',4,'essay','teacher','비가 내리는 모습을 떠올려 새로운 비 이름을 짓고, 그렇게 지은 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C1","difficulty":4,"kind":"essay","stem":"비가 내리는 모습을 떠올려 새로운 비 이름을 짓고, 그렇게 지은 까닭을 써 보세요.","answer_guide":{"answer":"예: 「또르르비」 — 빗방울이 창문을 또르르 굴러 내려가는 모습이 떠올라서 지었어요.","scoring_points":["비 이름을 새로 지었는가","비가 내리는 모습(특징)이 이름에 드러나는가","지은 까닭을 썼는가"]},"explanation":["새 이름.","특징이 드러남.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#1','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#2','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],true,'{"seq":2,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"오늘참좋다","correct":true},{"t":"안녕","mis":"K2-1-u2-X06"},{"t":"고마워","mis":"K2-1-u2-X06"}],"explanation":["오·늘·참·좋·다, 다섯 글자예요.","「안녕」은 두 글자, 「고마워」는 세 글자예요.","글자 하나에 손가락 하나씩 접어 세요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"참잘했어요","correct":true},{"t":"좋아","mis":"K2-1-u2-X06"},{"t":"반가워친구야","mis":"K2-1-u2-X06"}],"explanation":["참·잘·했·어·요, 다섯 글자예요.","「좋아」는 두 글자, 「반가워친구야」는 여섯 글자예요.","글자 하나에 손가락 하나씩 접어 세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#3','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 방법은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],true,'{"seq":3,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 방법은 어느 것인가요?","options":[{"t":"내 차례를 기다려요","correct":true},{"t":"먼저 말하려고 친구 말을 끊어요","mis":"K2-1-u2-X08"},{"t":"틀린 친구를 놀려요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지켜야 모두 즐겁게 놀 수 있어요.","친구 말을 끊거나 놀리면 놀이가 즐겁지 않아요.","말놀이는 함께 즐기는 놀이예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 말놀이를 바르게 하는 방법은 어느 것인가요?","options":[{"t":"친구 말을 끝까지 들어요","correct":true},{"t":"이기려고 혼자 계속 말해요","mis":"K2-1-u2-X08"},{"t":"친구 말이 틀리면 깔깔 비웃어요","mis":"K2-1-u2-X09"}],"explanation":["친구 말을 끝까지 들어야 이어서 말할 수 있어요.","혼자 말하거나 비웃으면 놀이가 즐겁지 않아요.","함께 즐기는 마음이 가장 중요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#4','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C3',1,'ox','auto','꼬리따기는 바로 앞말에서 떠오르는 것을 이어 말하는 놀이예요.',ARRAY['K2-1-u2-X04']::text[],true,'{"seq":4,"concept":"K2-1-u2-C3","difficulty":1,"kind":"ox","stem":"꼬리따기는 바로 앞말에서 떠오르는 것을 이어 말하는 놀이예요.","answer":"O","reason_options":[{"t":"앞말에 꼬리를 물듯 이어 가니까","correct":true},{"t":"아무 낱말이나 말하면 되니까","mis":"K2-1-u2-X04"}],"mis":"K2-1-u2-X04","explanation":["꼬리따기는 앞말에서 떠오르는 것을 이어요.","「사과는 빨개, 빨가면 딸기」처럼 이어 가요.","아무 말이나 하면 말이 이어지지 않아요."],"variant_rule":{"alt":[{"stem":"꼬리따기에서는 앞말과 관계없는 말을 해도 돼요.","answer":"X","reason_options":[{"t":"앞말에서 떠오르는 말을 이어야 하니까","correct":true},{"t":"재미만 있으면 되니까","mis":"K2-1-u2-X04"}],"explanation":["꼬리따기는 앞말에 이어 말하는 놀이예요.","관계없는 말을 하면 꼬리가 끊겨요.","앞말을 한 번 더 말하고 떠오르는 것을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#5','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C4',2,'match','auto','말놀이 이름과 알맞은 설명을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C4","difficulty":2,"kind":"match","stem":"말놀이 이름과 알맞은 설명을 이어 보세요.","pairs":[{"l":"꼬리따기","r":"앞말에서 떠오르는 말을 이어요"},{"l":"다섯 글자 말놀이","r":"다섯 글자로만 말해요"},{"l":"말 덧붙이기","r":"앞 사람 말에 하나씩 더해요"}],"mis":"K2-1-u2-X07","explanation":["꼬리따기는 떠오르는 말을 이어요.","다섯 글자 말놀이는 글자 수를 맞춰요.","말 덧붙이기는 앞 사람 말에 하나씩 더해요."],"variant_rule":{"alt":[{"stem":"말놀이 예와 알맞은 말놀이 이름을 이어 보세요.","pairs":[{"l":"「하늘은 파래, 파라면 바다」","r":"꼬리따기"},{"l":"「안녕친구야」","r":"다섯 글자 말놀이"},{"l":"「시장에 가면 사과도 있고, 배도 있고」","r":"말 덧붙이기"}],"explanation":["파래 → 바다로 이어 가는 것은 꼬리따기예요.","다섯 글자로 맞춘 말은 다섯 글자 말놀이예요.","앞말에 하나씩 더하는 것은 말 덧붙이기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#6','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「시장에 가면 사과도 있고, 배도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],true,'{"seq":6,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「시장에 가면 사과도 있고, 배도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「시장에 가면 사과도 있고, 배도 있고, 감도 있고」","correct":true},{"t":"「시장에 가면 감도 있고」","mis":"K2-1-u2-X07"},{"t":"「시장에 가면 배도 있고, 사과도 있고, 감도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기의 재미예요."],"variant_rule":{"alt":[{"stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「동물원에 가면 사자도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「동물원에 가면 사자도 있고, 기린도 있고」","correct":true},{"t":"「동물원에 가면 기린도 있고」","mis":"K2-1-u2-X07"},{"t":"「동물원에 가면 기린도 있고, 사자도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","기억해서 이어 말하는 재미가 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#7','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C4',2,'sa','auto','「고마워친구」는 몇 글자인가요? 숫자로 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u2-C4","difficulty":2,"kind":"sa","stem":"「고마워친구」는 몇 글자인가요? 숫자로 써 보세요.","answer":["5","5글자","다섯","다섯 글자"],"explanation":["고·마·워·친·구, 다섯 글자예요.","글자 하나에 손가락 하나씩 접어 세요.","다섯 글자 말놀이에 쓸 수 있는 말이에요."],"variant_rule":{"alt":[{"stem":"「사랑해요」는 몇 글자인가요? 숫자로 써 보세요.","answer":["4","4글자","네","네 글자"],"explanation":["사·랑·해·요, 네 글자예요.","글자 하나에 손가락 하나씩 접어 세요.","다섯 글자로 만들려면 한 글자를 더해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#8','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C5',2,'mc','auto','말놀이를 하면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],true,'{"seq":8,"concept":"K2-1-u2-C5","difficulty":2,"kind":"mc","stem":"말놀이를 하면 좋은 점은 어느 것인가요?","options":[{"t":"여러 낱말을 자연스럽게 익혀요","correct":true},{"t":"친구를 이겨서 으쓱해져요","mis":"K2-1-u2-X08"},{"t":"틀린 친구를 놀릴 수 있어요","mis":"K2-1-u2-X09"}],"explanation":["말놀이를 하면 낱말을 많이 만나고 익혀요.","이기거나 놀리는 것이 말놀이의 좋은 점은 아니에요.","친구와 함께 웃으며 말의 재미를 느껴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 말놀이를 하면 좋은 점은 어느 것인가요?","options":[{"t":"친구와 함께 웃으며 놀 수 있어요","correct":true},{"t":"혼자 오래 말할 수 있어요","mis":"K2-1-u2-X08"},{"t":"친구 말을 흉내 내며 놀릴 수 있어요","mis":"K2-1-u2-X09"}],"explanation":["말놀이는 친구와 함께 즐기는 놀이예요.","혼자 말하거나 놀리면 함께 즐길 수 없어요.","함께 웃으며 여러 낱말도 익혀요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#9','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C5',2,'ox','auto','말놀이에서 이기려면 친구 말을 끊고 먼저 말해도 돼요.',ARRAY['K2-1-u2-X08']::text[],true,'{"seq":9,"concept":"K2-1-u2-C5","difficulty":2,"kind":"ox","stem":"말놀이에서 이기려면 친구 말을 끊고 먼저 말해도 돼요.","answer":"X","reason_options":[{"t":"차례를 지켜야 모두 즐겁게 놀 수 있으니까","correct":true},{"t":"이기는 것이 가장 중요하니까","mis":"K2-1-u2-X08"}],"mis":"K2-1-u2-X08","explanation":["친구 말을 끊으면 놀이가 엉망이 돼요.","말놀이는 이기기보다 함께 즐기는 놀이예요.","내 차례를 기다려요."],"variant_rule":{"alt":[{"stem":"친구가 꼬리따기를 잘 잇지 못하면 기다려 주거나 도와줘요.","answer":"O","reason_options":[{"t":"함께 즐기는 놀이이니까","correct":true},{"t":"틀렸으니 놀려야 하니까","mis":"K2-1-u2-X09"}],"explanation":["친구가 막히면 기다려 주는 것이 좋아요.","놀리면 친구가 다시 말하고 싶지 않아져요.","「천천히 해.」 하고 말해 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#10','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C3',3,'error','auto','「하늘은 파래, 파라면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「하늘은 파래, 파라면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"준우 — 「파라면 사과」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"다은 — 「파라면 바다」","mis":"K2-1-u2-X19"},{"t":"서아 — 「파라면 청바지」","mis":"K2-1-u2-X19"}],"explanation":["사과는 파랗지 않아요.","바다와 청바지는 파란 것이라 잘 이어졌어요.","바로 앞말 「파라면」에서 떠오르는 것을 이어요."],"variant_rule":{"alt":[{"stem":"「눈은 하얘, 하야면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"도윤 — 「하야면 토마토」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"하린 — 「하야면 구름」","mis":"K2-1-u2-X19"},{"t":"예린 — 「하야면 우유」","mis":"K2-1-u2-X19"}],"explanation":["토마토는 하얗지 않아요.","구름과 우유는 하얀 것이라 잘 이어졌어요.","바로 앞말 「하야면」에서 떠오르는 것을 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#1','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C3',2,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#2','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C4',2,'mc','auto','친구에게 고마운 마음을 다섯 글자로 말한 것은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":2,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"친구에게 고마운 마음을 다섯 글자로 말한 것은 어느 것인가요?","options":[{"t":"정말고마워","correct":true},{"t":"고마워","mis":"K2-1-u2-X06"},{"t":"정말정말고마워","mis":"K2-1-u2-X06"}],"explanation":["정·말·고·마·워, 다섯 글자예요.","「고마워」는 세 글자, 「정말정말고마워」는 일곱 글자예요.","하고 싶은 말을 다섯 글자에 맞추는 재미가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#3','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C4',3,'mc','auto','말 덧붙이기 놀이를 하고 있어요. 넷째 차례인 시우가 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":3,"concept":"K2-1-u2-C4","difficulty":3,"kind":"mc","stem":"말 덧붙이기 놀이를 하고 있어요. 넷째 차례인 시우가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「바닷가에 가면 조개도 있고, 게도 있고, 모래도 있고, 갈매기도 있고」","correct":true},{"t":"「바닷가에 가면 갈매기도 있고」","mis":"K2-1-u2-X07"},{"t":"「바닷가에 가면 조개도 있고, 모래도 있고, 갈매기도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말 세 가지를 그대로 말해요.","그다음 끝에 한 가지를 더해요.","하나라도 빠뜨리면 덧붙이기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"지안","text":"바닷가에 가면 조개도 있고"},{"who":"태민","text":"바닷가에 가면 조개도 있고, 게도 있고"},{"who":"소율","text":"바닷가에 가면 조개도 있고, 게도 있고, 모래도 있고"},{"who":"시우","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#4','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C3',3,'mc','auto','꼬리따기가 바르게 이어진 것은 어느 것인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X05']::text[],false,'{"seq":4,"concept":"K2-1-u2-C3","difficulty":3,"kind":"mc","stem":"꼬리따기가 바르게 이어진 것은 어느 것인가요?","options":[{"t":"바나나는 노래 → 노라면 병아리 → 병아리는 작아 → 작으면 개미","correct":true},{"t":"바나나는 노래 → 노라면 바다 → 바다는 넓어","mis":"K2-1-u2-X04"},{"t":"바나나는 노래 → 노라면 바나나 → 바나나는 노래","mis":"K2-1-u2-X05"}],"explanation":["노란 것 병아리, 작은 것 개미로 꼬리를 물었어요.","바다는 노랗지 않고, 바나나로 돌아가면 꼬리가 맴돌아요.","바로 앞말에서 떠오르는 새것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#5','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C4',3,'ox','auto','「안녕 친구야」는 띄어 쓴 칸까지 세어 여섯 글자예요.',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":5,"concept":"K2-1-u2-C4","difficulty":3,"kind":"ox","stem":"「안녕 친구야」는 띄어 쓴 칸까지 세어 여섯 글자예요.","answer":"X","reason_options":[{"t":"띄어 쓴 칸은 글자가 아니라서 다섯 글자이니까","correct":true},{"t":"빈칸도 한 글자로 세니까","mis":"K2-1-u2-X06"}],"mis":"K2-1-u2-X06","explanation":["안·녕·친·구·야, 다섯 글자예요.","띄어 쓴 칸은 세지 않아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#6','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C5',3,'error','auto','친구들이 말놀이를 했어요. 약속을 지키지 못한 친구는 누구인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C5","difficulty":3,"kind":"error","stem":"친구들이 말놀이를 했어요. 약속을 지키지 못한 친구는 누구인가요?","options":[{"t":"지호 — 친구가 생각하는 동안 「빨리 해! 너 졌어!」 하고 놀렸어요","correct":true,"mis_target":"K2-1-u2-X09"},{"t":"하린 — 차례를 기다렸다가 말했어요","mis":"K2-1-u2-X19"},{"t":"도담 — 친구가 막히자 「천천히 해.」 하고 기다렸어요","mis":"K2-1-u2-X19"}],"explanation":["지호는 생각하는 친구를 재촉하고 놀렸어요.","말놀이는 이기기보다 함께 즐기는 놀이예요.","하린이와 도담이는 약속을 잘 지켰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#7','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C5',3,'mc','auto','꼬리따기를 하는데 친구가 앞말과 관계없는 말을 했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":7,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"꼬리따기를 하는데 친구가 앞말과 관계없는 말을 했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「앞말에서 떠오르는 걸 다시 생각해 볼까?」","correct":true},{"t":"「그것도 몰라? 바보야.」","mis":"K2-1-u2-X09"},{"t":"「넌 빠져. 우리끼리 할게.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#8','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C3',4,'blank','auto','꼬리따기를 이어 가요. 빈칸에 들어갈 말로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#9','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C3',4,'essay','teacher','「하늘은 파래」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「하늘은 파래」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 하늘은 파래 → 파라면 바다 → 바다는 넓어 → 넓으면 운동장","scoring_points":["「하늘은 파래」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#10','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C5',4,'essay','teacher','친구와 말놀이를 할 때 지킬 약속을 두 가지 쓰고, 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C5","difficulty":4,"kind":"essay","stem":"친구와 말놀이를 할 때 지킬 약속을 두 가지 쓰고, 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 내 차례를 기다리겠습니다. 친구가 틀려도 놀리지 않겠습니다. 그래야 모두가 즐겁게 놀 수 있기 때문입니다.","scoring_points":["지킬 약속을 두 가지 썼는가","차례·듣기·놀리지 않기 같은 말놀이 약속인가","까닭을 썼는가"]},"explanation":["약속 두 가지.","말놀이 약속.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#1','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',1,'mc','auto','부엌에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],true,'{"seq":1,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"부엌에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"냄비","correct":true},{"t":"칠판","mis":"K2-1-u2-X10"},{"t":"미끄럼틀","mis":"K2-1-u2-X10"}],"explanation":["냄비는 부엌에서 음식을 할 때 써요.","칠판은 교실, 미끄럼틀은 놀이터에 있어요.","그 장소에 서 있다고 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"교실에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"책상","correct":true},{"t":"국자","mis":"K2-1-u2-X10"},{"t":"그네","mis":"K2-1-u2-X10"}],"explanation":["책상은 교실에서 볼 수 있어요.","국자는 부엌, 그네는 놀이터에 있어요.","그 장소에 서 있다고 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#2','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',1,'mc','auto','뒤섞인 글자 「방 · 가」를 바르게 맞춘 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],true,'{"seq":2,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"뒤섞인 글자 「방 · 가」를 바르게 맞춘 낱말은 어느 것인가요?","options":[{"t":"가방","correct":true},{"t":"방가","mis":"K2-1-u2-X11"},{"t":"바가","mis":"K2-1-u2-X11"}],"explanation":["글자를 바꾸어 놓으면 「가방」이 돼요.","놓인 차례대로 읽거나 글자를 바꾸면 낱말이 안 돼요.","두 글자를 모두 한 번씩 써요."],"variant_rule":{"alt":[{"stem":"뒤섞인 글자 「끼 · 토」를 바르게 맞춘 낱말은 어느 것인가요?","options":[{"t":"토끼","correct":true},{"t":"끼토","mis":"K2-1-u2-X11"},{"t":"토기","mis":"K2-1-u2-X11"}],"explanation":["글자를 바꾸어 놓으면 「토끼」가 돼요.","놓인 차례대로 읽거나 글자를 바꾸면 안 돼요.","두 글자를 모두 한 번씩 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#3','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C7',1,'mc','auto','「토끼」와 「당근」으로 만든 문장은 어느 것인가요?',ARRAY['K2-1-u2-X12']::text[],true,'{"seq":3,"concept":"K2-1-u2-C7","difficulty":1,"kind":"mc","stem":"「토끼」와 「당근」으로 만든 문장은 어느 것인가요?","options":[{"t":"토끼가 당근을 먹어요.","correct":true},{"t":"토끼 당근.","mis":"K2-1-u2-X12"},{"t":"당근 토끼 먹어.","mis":"K2-1-u2-X12"}],"explanation":["「누가 무엇을 어찌해요」로 이어 문장을 만들어요.","낱말만 늘어놓으면 문장이 되지 않아요.","토끼가, 당근을처럼 이어 주는 말을 붙여요."],"variant_rule":{"alt":[{"stem":"「강아지」와 「공」으로 만든 문장은 어느 것인가요?","options":[{"t":"강아지가 공을 물어 와요.","correct":true},{"t":"강아지 공.","mis":"K2-1-u2-X12"},{"t":"공 강아지 물어.","mis":"K2-1-u2-X12"}],"explanation":["「누가 무엇을 어찌해요」로 이어 문장을 만들어요.","낱말만 늘어놓으면 문장이 되지 않아요.","강아지가, 공을처럼 이어 주는 말을 붙여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#4','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',1,'ox','auto','놀이터에서 볼 수 있는 낱말에는 「그네」와 「미끄럼틀」이 있어요.',ARRAY['K2-1-u2-X10']::text[],true,'{"seq":4,"concept":"K2-1-u2-C6","difficulty":1,"kind":"ox","stem":"놀이터에서 볼 수 있는 낱말에는 「그네」와 「미끄럼틀」이 있어요.","answer":"O","reason_options":[{"t":"그네와 미끄럼틀은 놀이터에 있으니까","correct":true},{"t":"놀이터에는 냄비와 국자가 있으니까","mis":"K2-1-u2-X10"}],"mis":"K2-1-u2-X10","explanation":["그네와 미끄럼틀은 놀이터에서 볼 수 있어요.","냄비와 국자는 부엌에서 볼 수 있어요.","장소마다 어울리는 낱말이 달라요."],"variant_rule":{"alt":[{"stem":"「냄비」와 「국자」는 교실에서 볼 수 있는 낱말이에요.","answer":"X","reason_options":[{"t":"냄비와 국자는 부엌에서 볼 수 있으니까","correct":true},{"t":"낱말은 어느 장소에서나 똑같으니까","mis":"K2-1-u2-X10"}],"explanation":["냄비와 국자는 부엌에서 써요.","교실에서는 칠판, 책상 같은 낱말을 볼 수 있어요.","장소마다 어울리는 낱말이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#5','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',2,'match','auto','낱말과 그 낱말을 볼 수 있는 장소를 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C6","difficulty":2,"kind":"match","stem":"낱말과 그 낱말을 볼 수 있는 장소를 이어 보세요.","pairs":[{"l":"칠판","r":"교실"},{"l":"냄비","r":"부엌"},{"l":"미끄럼틀","r":"놀이터"}],"mis":"K2-1-u2-X10","explanation":["칠판은 교실에 있어요.","냄비는 부엌에 있어요.","미끄럼틀은 놀이터에 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말을 볼 수 있는 장소를 이어 보세요.","pairs":[{"l":"비둘기","r":"공원"},{"l":"칫솔","r":"화장실"},{"l":"장바구니","r":"시장"}],"explanation":["비둘기는 공원에서 볼 수 있어요.","칫솔은 화장실에 있어요.","장바구니는 시장에 들고 가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#6','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C7',2,'mc','auto','친구가 「옛날에 곰이 살았어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],true,'{"seq":6,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「옛날에 곰이 살았어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「곰은 꿀을 좋아했어요.」","correct":true},{"t":"「자동차가 빵빵 울려요.」","mis":"K2-1-u2-X13"},{"t":"「곰 꿀 나무.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 곰 이야기를 이어 가요.","자동차 이야기는 곰과 관계가 없고, 낱말만 늘어놓으면 문장이 아니에요.","앞 문장의 인물을 넣어 이어 말해요."],"variant_rule":{"alt":[{"stem":"친구가 「어느 날 다람쥐가 도토리를 주웠어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「다람쥐는 도토리를 나무 구멍에 숨겼어요.」","correct":true},{"t":"「비행기가 하늘을 날아요.」","mis":"K2-1-u2-X13"},{"t":"「다람쥐 도토리 구멍.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 다람쥐 이야기를 이어 가요.","비행기 이야기는 관계가 없고, 낱말만 늘어놓으면 문장이 아니에요.","앞 문장의 인물을 넣어 이어 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#7','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',2,'sa','auto','뒤섞인 글자 「자 · 피」를 바르게 맞춘 낱말을 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u2-C6","difficulty":2,"kind":"sa","stem":"뒤섞인 글자 「자 · 피」를 바르게 맞춘 낱말을 써 보세요.","answer":["피자"],"explanation":["「피」와 「자」를 바꾸면 「피자」가 돼요.","두 글자를 모두 한 번씩 썼어요.","숨은 낱말을 찾는 것도 말놀이예요."],"variant_rule":{"alt":[{"stem":"뒤섞인 글자 「차 · 기」를 바르게 맞춘 낱말을 써 보세요.","answer":["기차"],"explanation":["「기」와 「차」를 바꾸면 「기차」가 돼요.","두 글자를 모두 한 번씩 썼어요.","숨은 낱말을 찾는 것도 말놀이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#8','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',2,'mc','auto','공원에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],true,'{"seq":8,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"공원에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"나무 · 의자 · 비둘기","correct":true},{"t":"냄비 · 그릇 · 국자","mis":"K2-1-u2-X10"},{"t":"칠판 · 책상 · 분필","mis":"K2-1-u2-X10"}],"explanation":["나무·의자·비둘기는 공원에서 볼 수 있어요.","냄비·그릇·국자는 부엌, 칠판·책상·분필은 교실에 있어요.","공원에 서 있다고 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"바닷가에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"모래 · 조개 · 파도","correct":true},{"t":"그네 · 시소 · 미끄럼틀","mis":"K2-1-u2-X10"},{"t":"칠판 · 책상 · 필통","mis":"K2-1-u2-X10"}],"explanation":["모래·조개·파도는 바닷가에서 볼 수 있어요.","그네·시소는 놀이터, 칠판·필통은 교실에 있어요.","바닷가에 서 있다고 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#9','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C7',2,'ox','auto','줄줄이 이야기는 앞 친구의 문장을 잘 듣고 이어지게 말해야 해요.',ARRAY['K2-1-u2-X13']::text[],true,'{"seq":9,"concept":"K2-1-u2-C7","difficulty":2,"kind":"ox","stem":"줄줄이 이야기는 앞 친구의 문장을 잘 듣고 이어지게 말해야 해요.","answer":"O","reason_options":[{"t":"그래야 이야기가 자연스럽게 이어지니까","correct":true},{"t":"아무 문장이나 말해도 이야기가 되니까","mis":"K2-1-u2-X13"}],"mis":"K2-1-u2-X13","explanation":["앞 문장과 이어져야 이야기가 돼요.","관계없는 문장을 말하면 이야기가 끊겨요.","친구 문장을 끝까지 잘 들어요."],"variant_rule":{"alt":[{"stem":"「토끼 당근 밭」처럼 낱말만 늘어놓아도 문장이 돼요.","answer":"X","reason_options":[{"t":"「토끼가 당근 밭에 가요.」처럼 이어야 문장이니까","correct":true},{"t":"낱말이 들어 있으면 문장이니까","mis":"K2-1-u2-X12"}],"explanation":["낱말만 늘어놓으면 뜻이 잘 전해지지 않아요.","「누가 무엇을 어찌해요」로 이어야 문장이에요.","이어 주는 말을 붙여 끝까지 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#10','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C7',3,'error','auto','친구들이 토끼 이야기를 줄줄이 만들었어요. 이야기와 어울리지 않는 문장을 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C7","difficulty":3,"kind":"error","stem":"친구들이 토끼 이야기를 줄줄이 만들었어요. 이야기와 어울리지 않는 문장을 말한 친구는 누구인가요?","options":[{"t":"시우 — 「자동차가 빵빵 울렸어요.」","correct":true,"mis_target":"K2-1-u2-X13"},{"t":"다은 — 「토끼가 깡충깡충 뛰어갔어요.」","mis":"K2-1-u2-X19"},{"t":"로아 — 「토끼는 당근 밭에 도착했어요.」","mis":"K2-1-u2-X19"}],"explanation":["자동차 이야기는 토끼 이야기와 관계가 없어요.","다은이와 로아는 토끼 이야기를 이어 갔어요.","앞 문장의 인물을 넣어 이어 말해요."],"variant_rule":{"alt":[{"stem":"친구들이 고양이 이야기를 줄줄이 만들었어요. 이야기와 어울리지 않는 문장을 말한 친구는 누구인가요?","options":[{"t":"하람 — 「비행기가 구름 위로 날아갔어요.」","correct":true,"mis_target":"K2-1-u2-X13"},{"t":"은솔 — 「고양이가 털실을 굴리며 놀았어요.」","mis":"K2-1-u2-X19"},{"t":"지안 — 「고양이는 털실을 안고 잠이 들었어요.」","mis":"K2-1-u2-X19"}],"explanation":["비행기 이야기는 고양이 이야기와 관계가 없어요.","은솔이와 지안이는 고양이 이야기를 이어 갔어요.","앞 문장의 인물을 넣어 이어 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#1','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「크 · 스 · 림 · 아 · 이」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":1,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「크 · 스 · 림 · 아 · 이」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"아이스크림","correct":true},{"t":"아이스림크","mis":"K2-1-u2-X11"},{"t":"아이크림","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「아이스크림」이 돼요.","차례를 잘못 놓거나 「스」를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#2','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',2,'mc','auto','「아기」, 「우유」, 「엄마」로 만든 문장은 어느 것인가요?',ARRAY['K2-1-u2-X12']::text[],false,'{"seq":2,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"「아기」, 「우유」, 「엄마」로 만든 문장은 어느 것인가요?","options":[{"t":"엄마가 아기에게 우유를 줘요.","correct":true},{"t":"아기 우유 엄마.","mis":"K2-1-u2-X12"},{"t":"엄마가 우유.","mis":"K2-1-u2-X12"}],"explanation":["세 낱말을 모두 넣어 「누가 누구에게 무엇을 어찌해요」로 이었어요.","낱말만 늘어놓거나 끝을 맺지 않으면 문장이 아니에요.","이어 주는 말을 붙여 끝까지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#3','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',3,'mc','auto','칠판, 필통, 냄비, 책상 가운데 교실과 어울리지 않는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":3,"concept":"K2-1-u2-C6","difficulty":3,"kind":"mc","stem":"칠판, 필통, 냄비, 책상 가운데 교실과 어울리지 않는 낱말은 어느 것인가요?","options":[{"t":"냄비","correct":true},{"t":"칠판","mis":"K2-1-u2-X19"},{"t":"필통","mis":"K2-1-u2-X19"}],"explanation":["냄비는 부엌에서 쓰는 물건이에요.","칠판, 필통, 책상은 교실에서 볼 수 있어요.","「어울리지 않는」을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#4','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":4,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"기차가 칙칙폭폭 달렸어요.","correct":true},{"t":"다람쥐는 가을마다 도토리를 모았어요.","mis":"K2-1-u2-X19"},{"t":"겨울이 되자 다람쥐는 모은 도토리를 먹었어요.","mis":"K2-1-u2-X19"}],"explanation":["기차 이야기는 다람쥐 이야기와 관계가 없어요.","다른 문장은 모두 다람쥐가 한 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["옛날에 다람쥐가 살았어요.","다람쥐는 가을마다 도토리를 모았어요.","기차가 칙칙폭폭 달렸어요.","겨울이 되자 다람쥐는 모은 도토리를 먹었어요."],"title":"친구들과 만든 줄줄이 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#5','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',3,'ox','auto','「곰이 꿀을 먹어요.」와 「곰 꿀 먹어.」는 똑같이 잘 만든 문장이에요.',ARRAY['K2-1-u2-X12']::text[],false,'{"seq":5,"concept":"K2-1-u2-C7","difficulty":3,"kind":"ox","stem":"「곰이 꿀을 먹어요.」와 「곰 꿀 먹어.」는 똑같이 잘 만든 문장이에요.","answer":"X","reason_options":[{"t":"「곰이」, 「꿀을」처럼 이어 주는 말이 있어야 뜻이 잘 전해지니까","correct":true},{"t":"같은 낱말을 썼으니까","mis":"K2-1-u2-X12"}],"mis":"K2-1-u2-X12","explanation":["「곰이 꿀을 먹어요.」는 누가 무엇을 하는지 잘 보여요.","「곰 꿀 먹어.」는 낱말만 늘어놓은 말이에요.","이어 주는 말을 붙이고 끝까지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#6','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',3,'error','auto','친구들이 장소와 낱말을 이어 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X10','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":3,"kind":"error","stem":"친구들이 장소와 낱말을 이어 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「부엌에는 미끄럼틀이 있어요.」","correct":true,"mis_target":"K2-1-u2-X10"},{"t":"지안 — 「교실에는 칠판이 있어요.」","mis":"K2-1-u2-X19"},{"t":"소율 — 「공원에는 비둘기가 있어요.」","mis":"K2-1-u2-X19"}],"explanation":["미끄럼틀은 놀이터에 있어요.","칠판은 교실, 비둘기는 공원에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#7','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',3,'mc','auto','친구들이 줄줄이 이야기를 만들고 있어요. 도윤이가 이어 말할 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":7,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들이 줄줄이 이야기를 만들고 있어요. 도윤이가 이어 말할 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「그래서 엄마 펭귄에게 헤엄을 배웠어요.」","correct":true},{"t":"「사과는 빨개요.」","mis":"K2-1-u2-X13"},{"t":"「펭귄 바다 물.」","mis":"K2-1-u2-X12"}],"explanation":["헤엄을 못 치는 아기 펭귄 이야기를 이어 가요.","사과 이야기는 관계가 없고, 낱말만 늘어놓으면 문장이 아니에요.","앞 문장과 이어지게 말해요."],"asset":{"type":"speech","turns":[{"who":"지후","text":"옛날에 아기 펭귄이 살았어요."},{"who":"서윤","text":"아기 펭귄은 헤엄을 못 쳤어요."},{"who":"도윤","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#8','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',4,'mc','auto','글자 카드 「자 · 사 · 과 · 사」 네 장을 모두 한 번씩 써서 낱말 두 개를 만들었어요. 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":8,"concept":"K2-1-u2-C6","difficulty":4,"kind":"mc","stem":"글자 카드 「자 · 사 · 과 · 사」 네 장을 모두 한 번씩 써서 낱말 두 개를 만들었어요. 알맞은 것은 어느 것인가요?","options":[{"t":"사자, 사과","correct":true},{"t":"사과, 자사","mis":"K2-1-u2-X11"},{"t":"사자, 과자","mis":"K2-1-u2-X11"}],"explanation":["사·자와 사·과로 카드 네 장을 모두 한 번씩 썼어요.","「자사」는 낱말이 아니고, 과자를 만들려면 「자」가 한 장 더 있어야 해요.","카드를 하나씩 지우며 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#9','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',4,'essay','teacher','「바닷가」, 「조개」, 「파도」를 모두 넣어 이어지는 이야기를 세 문장으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C7","difficulty":4,"kind":"essay","stem":"「바닷가」, 「조개」, 「파도」를 모두 넣어 이어지는 이야기를 세 문장으로 써 보세요.","answer_guide":{"answer":"예: 지우는 바닷가에 놀러 갔어요. / 모래 속에서 예쁜 조개를 주웠어요. / 그때 파도가 철썩 밀려와 발을 적셨어요.","scoring_points":["세 낱말을 모두 넣었는가","문장마다 「누가 무엇을 어찌해요」로 썼는가","세 문장이 이어지는 이야기가 되었는가"]},"explanation":["세 낱말.","문장으로.","이어지는 이야기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#10','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',4,'essay','teacher','우리 집 부엌이나 우리 교실에서 볼 수 있는 낱말을 세 개 쓰고, 그 가운데 두 낱말을 넣어 문장을 하나 만들어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C6","difficulty":4,"kind":"essay","stem":"우리 집 부엌이나 우리 교실에서 볼 수 있는 낱말을 세 개 쓰고, 그 가운데 두 낱말을 넣어 문장을 하나 만들어 보세요.","answer_guide":{"answer":"예: (부엌) 냄비, 국자, 숟가락 / 엄마가 국자로 냄비 속 국을 떠요.","scoring_points":["한 장소에서 볼 수 있는 낱말을 세 개 썼는가","두 낱말을 넣어 문장으로 썼는가","문장 끝에 마침표를 찍었는가"]},"explanation":["한 장소의 낱말.","두 낱말로 문장.","마침표."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#1','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',1,'mc','auto','글을 읽고 답해 보세요. 지우는 무엇을 쓰고 걸었나요?',ARRAY['K2-1-u2-X14']::text[],true,'{"seq":1,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 지우는 무엇을 쓰고 걸었나요?","options":[{"t":"노란 우산","correct":true},{"t":"빨간 모자","mis":"K2-1-u2-X14"},{"t":"파란 비옷","mis":"K2-1-u2-X14"}],"explanation":["글에 「노란 우산을 쓰고」라고 나와 있어요.","모자나 비옷은 글에 나오지 않아요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 눈사람의 코에 붙인 것은 무엇인가요?","options":[{"t":"당근","correct":true},{"t":"단추","mis":"K2-1-u2-X14"},{"t":"솔방울","mis":"K2-1-u2-X14"}],"explanation":["글에 「코에는 당근을」이라고 나와 있어요.","단추는 눈에 붙였고, 솔방울은 나오지 않아요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#2','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],true,'{"seq":2,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"맴맴","correct":true},{"t":"시원하다","mis":"K2-1-u2-X15"},{"t":"여름날","mis":"K2-1-u2-X15"}],"explanation":["「맴맴」은 매미 소리를 흉내 낸 말이에요.","「시원하다」와 「여름날」은 소리를 흉내 낸 말이 아니에요.","소리 내어 따라 하면 소리가 들리는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"멍멍","correct":true},{"t":"강아지","mis":"K2-1-u2-X15"},{"t":"짖다","mis":"K2-1-u2-X15"}],"explanation":["「멍멍」은 강아지가 짖는 소리를 흉내 낸 말이에요.","「강아지」는 동물 이름, 「짖다」는 하는 일이에요.","소리 내어 따라 하면 소리가 들리는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#3','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],true,'{"seq":3,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"깡충깡충","correct":true},{"t":"토끼","mis":"K2-1-u2-X15"},{"t":"빠르다","mis":"K2-1-u2-X15"}],"explanation":["「깡충깡충」은 토끼가 뛰는 모양을 흉내 낸 말이에요.","「토끼」는 동물 이름, 「빠르다」는 흉내 낸 말이 아니에요.","따라 하면 모습이 떠오르는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"데굴데굴","correct":true},{"t":"공","mis":"K2-1-u2-X15"},{"t":"굴리다","mis":"K2-1-u2-X15"}],"explanation":["「데굴데굴」은 굴러가는 모양을 흉내 낸 말이에요.","「공」은 물건 이름, 「굴리다」는 하는 일이에요.","따라 하면 모습이 떠오르는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#4','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',1,'ox','auto','같은 글을 읽어도 사람마다 느낌이 다를 수 있어요.',ARRAY['K2-1-u2-X16']::text[],true,'{"seq":4,"concept":"K2-1-u2-C9","difficulty":1,"kind":"ox","stem":"같은 글을 읽어도 사람마다 느낌이 다를 수 있어요.","answer":"O","reason_options":[{"t":"저마다 겪은 일과 생각이 다르니까","correct":true},{"t":"정답인 느낌은 하나뿐이니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["읽는 사람마다 떠오르는 경험이 달라요.","그래서 느낌도 다를 수 있어요.","친구의 다른 느낌도 「그럴 수 있구나」 하고 들어요."],"variant_rule":{"alt":[{"stem":"내 느낌을 말할 때는 그렇게 느낀 까닭을 함께 말하면 좋아요.","answer":"O","reason_options":[{"t":"왜 그렇게 느꼈는지 친구가 알 수 있으니까","correct":true},{"t":"느낌만 말하면 충분하니까","mis":"K2-1-u2-X16"}],"explanation":["까닭을 말하면 내 느낌이 잘 전해져요.","「재미있었어.」보다 「~해서 재미있었어.」가 좋아요.","어느 장면에서, 왜 그런지 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#5','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',2,'match','auto','흉내 내는 말과 알맞은 것을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C8","difficulty":2,"kind":"match","stem":"흉내 내는 말과 알맞은 것을 이어 보세요.","pairs":[{"l":"꿀꿀","r":"돼지가 우는 소리"},{"l":"째깍째깍","r":"시계가 가는 소리"},{"l":"엉금엉금","r":"거북이가 기어가는 모양"}],"mis":"K2-1-u2-X15","explanation":["「꿀꿀」은 돼지 소리예요.","「째깍째깍」은 시계 소리예요.","「엉금엉금」은 거북이가 느리게 기는 모양이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 흉내 내는 말과 알맞은 것을 이어 보세요.","pairs":[{"l":"개굴개굴","r":"개구리가 우는 소리"},{"l":"주룩주룩","r":"비가 쏟아지는 소리"},{"l":"살금살금","r":"몰래 걷는 모양"}],"explanation":["「개굴개굴」은 개구리 소리예요.","「주룩주룩」은 비가 쏟아지는 소리예요.","「살금살금」은 몰래 걷는 모양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#6','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 빗방울이 떨어지는 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X14']::text[],true,'{"seq":6,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 빗방울이 떨어지는 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"후드득","correct":true},{"t":"우르르 쾅쾅","mis":"K2-1-u2-X14"},{"t":"찰랑찰랑","mis":"K2-1-u2-X14"}],"explanation":["「빗방울이 후드득 떨어지기」라고 나와 있어요.","「우르르 쾅쾅」은 하늘, 「찰랑찰랑」은 웅덩이 물이에요.","무엇의 소리인지 글에서 짚어요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 눈을 굴리는 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"데굴데굴","correct":true},{"t":"펑펑","mis":"K2-1-u2-X14"},{"t":"쌩쌩","mis":"K2-1-u2-X14"}],"explanation":["「눈을 데굴데굴 굴려」라고 나와 있어요.","「펑펑」은 눈이 내리는 모양, 「쌩쌩」은 바람이에요.","무엇의 모양인지 글에서 짚어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#7','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',2,'sa','auto','빈칸에 알맞은 흉내 내는 말을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#8','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',2,'mc','auto','「첨벙첨벙 빗길」을 읽고 느낌을 알맞게 말한 것은 어느 것인가요?',ARRAY['K2-1-u2-X16','K2-1-u2-X14']::text[],true,'{"seq":8,"concept":"K2-1-u2-C9","difficulty":2,"kind":"mc","stem":"「첨벙첨벙 빗길」을 읽고 느낌을 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「첨벙첨벙 걷는 장면이 재미있었어. 나도 장화 신고 웅덩이를 밟은 적이 있거든.」","correct":true},{"t":"「재미있었어.」","mis":"K2-1-u2-X16"},{"t":"「지우가 비를 맞아서 슬펐어.」","mis":"K2-1-u2-X14"}],"explanation":["장면과 내 경험(까닭)을 함께 말했어요.","까닭 없는 말은 느낌이 잘 전해지지 않아요.","지우는 우산을 썼고 재미있어했어요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"},"variant_rule":{"alt":[{"stem":"「데굴데굴 눈사람」을 읽고 느낌을 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「눈사람에 단추를 붙이는 장면이 재미있었어. 나도 동생이랑 눈사람을 만들고 싶어.」","correct":true},{"t":"「좋았어.」","mis":"K2-1-u2-X16"},{"t":"「도윤이가 눈사람을 부숴서 속상했어.」","mis":"K2-1-u2-X14"}],"explanation":["장면과 내 바람(까닭)을 함께 말했어요.","까닭 없는 말은 느낌이 잘 전해지지 않아요.","글에서 도윤이는 눈사람을 부수지 않았어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#9','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',2,'ox','auto','「쌩쌩」은 바람이 세게 부는 소리를 흉내 낸 말이에요.',ARRAY['K2-1-u2-X15']::text[],true,'{"seq":9,"concept":"K2-1-u2-C8","difficulty":2,"kind":"ox","stem":"「쌩쌩」은 바람이 세게 부는 소리를 흉내 낸 말이에요.","answer":"O","reason_options":[{"t":"바람 소리를 따라 한 말이니까","correct":true},{"t":"바람의 이름이니까","mis":"K2-1-u2-X15"}],"mis":"K2-1-u2-X15","explanation":["「쌩쌩」은 바람이 세게 부는 소리예요.","흉내 내는 말은 이름이 아니라 소리나 모양을 따라 한 말이에요.","따라 하면 바람 소리가 들리는 듯해요."],"variant_rule":{"alt":[{"stem":"「여름날」은 소리를 흉내 낸 말이에요.","answer":"X","reason_options":[{"t":"때를 나타내는 낱말이니까","correct":true},{"t":"여름에 들리는 말이니까","mis":"K2-1-u2-X15"}],"explanation":["「여름날」은 때를 나타내는 낱말이에요.","소리를 흉내 낸 말은 「맴맴」, 「윙윙」 같은 말이에요.","따라 했을 때 소리가 나는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#10','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',3,'error','auto','「찰박찰박 시냇가」를 읽고 느낌을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X14','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C9","difficulty":3,"kind":"error","stem":"「찰박찰박 시냇가」를 읽고 느낌을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"민호 — 「하준이가 물에 빠져서 무서웠어.」","correct":true,"mis_target":"K2-1-u2-X14"},{"t":"다은 — 「차가운 물에 발을 담그는 장면에서 나도 시원했어.」","mis":"K2-1-u2-X19"},{"t":"시우 — 「물고기가 발가락 사이로 지나갈 때 간지러울 것 같았어.」","mis":"K2-1-u2-X19"}],"explanation":["하준이가 물에 빠졌다는 이야기는 글에 없어요.","다은이와 시우는 글의 장면을 들어 느낌을 말했어요.","느낌도 글에 나온 장면에서 출발해요."],"asset":{"type":"passage","lines":["여름 방학에 하준이는 시냇가에 갔어요.","차가운 물에 발을 담그자 「앗, 차가워!」 소리가 절로 났어요.","작은 물고기들이 발가락 사이로 쏙쏙 지나갔어요.","하준이는 깔깔 웃으며 물을 찰박찰박 찼어요."],"title":"찰박찰박 시냇가"},"variant_rule":{"alt":[{"stem":"「데굴데굴 눈사람」을 읽고 느낌을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태민 — 「두 볼이 꽁꽁 얼어서 슬펐을 것 같아.」","correct":true,"mis_target":"K2-1-u2-X16"},{"t":"하린 — 「눈을 굴리는 장면이 신나 보였어.」","mis":"K2-1-u2-X19"},{"t":"지안 — 「단추를 붙이는 장면에서 웃음이 났어.」","mis":"K2-1-u2-X19"}],"explanation":["글에는 두 볼이 따끈따끈했다고 나와 있어요.","태민이는 글과 반대로 짐작했어요.","하린이와 지안이는 글의 장면을 들어 느낌을 말했어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#1','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 부침개를 부칠 때 난 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":1,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 부침개를 부칠 때 난 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"지글지글","correct":true},{"t":"호호","mis":"K2-1-u2-X14"},{"t":"후드득","mis":"K2-1-u2-X14"}],"explanation":["「팬에서 지글지글 소리가 났어요」라고 나와 있어요.","「호호」는 서아가 부는 소리이고, 「후드득」은 글에 없어요.","무엇의 소리인지 글에서 짚어요."],"asset":{"type":"passage","lines":["비 오는 저녁, 아빠가 부침개를 부치셨어요.","팬에서 지글지글 소리가 났어요.","서아는 바삭바삭한 끝부분을 호호 불어 먹었어요.","「아빠, 빗소리랑 부침개 소리가 똑같아요!」"],"title":"지글지글 부침개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#2','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',2,'mc','auto','글을 읽고 답해 보세요. 서아가 빗소리와 부침개 소리가 똑같다고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":2,"concept":"K2-1-u2-C9","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 서아가 빗소리와 부침개 소리가 똑같다고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"지글지글 소리가 빗소리처럼 들려서","correct":true},{"t":"부침개가 비에 젖어서","mis":"K2-1-u2-X14"},{"t":"아빠가 비를 좋아하셔서","mis":"K2-1-u2-X14"}],"explanation":["부침개 부치는 소리가 빗소리와 비슷하게 들렸어요.","부침개가 젖었다거나 아빠가 비를 좋아한다는 말은 글에 없어요.","글 속 소리를 떠올려 까닭을 찾아요."],"asset":{"type":"passage","lines":["비 오는 저녁, 아빠가 부침개를 부치셨어요.","팬에서 지글지글 소리가 났어요.","서아는 바삭바삭한 끝부분을 호호 불어 먹었어요.","「아빠, 빗소리랑 부침개 소리가 똑같아요!」"],"title":"지글지글 부침개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#3','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":3,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"쏙쏙","correct":true},{"t":"깔깔","mis":"K2-1-u2-X15"},{"t":"찰박찰박","mis":"K2-1-u2-X15"}],"explanation":["「쏙쏙」은 물고기가 빠르게 지나가는 모양이에요.","「깔깔」은 웃음소리, 「찰박찰박」은 물을 차는 소리예요.","소리인지 모양인지 따라 해 보며 가려요."],"asset":{"type":"passage","lines":["여름 방학에 하준이는 시냇가에 갔어요.","차가운 물에 발을 담그자 「앗, 차가워!」 소리가 절로 났어요.","작은 물고기들이 발가락 사이로 쏙쏙 지나갔어요.","하준이는 깔깔 웃으며 물을 찰박찰박 찼어요."],"title":"찰박찰박 시냇가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#4','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 지우의 마음을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":4,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 지우의 마음을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"비 오는 날이 즐거워요","correct":true},{"t":"천둥이 무서워 울고 싶어요","mis":"K2-1-u2-X16"},{"t":"비가 와서 심심해요","mis":"K2-1-u2-X16"}],"explanation":["지우는 「비 오는 날도 참 재미있다!」라고 말했어요.","첨벙첨벙 걷는 모습에서도 즐거움이 느껴져요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#5','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',3,'ox','auto','흉내 내는 말을 넣으면 글이 더 생생하게 느껴져요.',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":5,"concept":"K2-1-u2-C8","difficulty":3,"kind":"ox","stem":"흉내 내는 말을 넣으면 글이 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"소리와 모습이 눈앞에 그려지니까","correct":true},{"t":"글자 수가 늘어나니까","mis":"K2-1-u2-X15"}],"mis":"K2-1-u2-X15","explanation":["「눈이 내렸어요.」보다 「눈이 펑펑 내렸어요.」가 생생해요.","글이 길어져서가 아니라 모습이 떠올라서 좋아요.","흉내 내는 말을 찾으며 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#6','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',3,'error','auto','흉내 내는 말을 넣어 문장을 만들었어요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K2-1-u2-X15','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C8","difficulty":3,"kind":"error","stem":"흉내 내는 말을 넣어 문장을 만들었어요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"서아 — 「고양이가 꿀꿀 울어요.」","correct":true,"mis_target":"K2-1-u2-X15"},{"t":"준우 — 「병아리가 삐악삐악 울어요.」","mis":"K2-1-u2-X19"},{"t":"하린 — 「거북이가 엉금엉금 기어가요.」","mis":"K2-1-u2-X19"}],"explanation":["「꿀꿀」은 돼지 소리예요.","고양이 소리는 「야옹」이에요.","준우와 하린이는 알맞게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#7','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 「두 볼은 따끈따끈했어요」에서 짐작할 수 있는 도윤이의 마음은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":7,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「두 볼은 따끈따끈했어요」에서 짐작할 수 있는 도윤이의 마음은 어느 것인가요?","options":[{"t":"신나게 놀아서 즐거워요","correct":true},{"t":"추워서 집에 가고 싶어요","mis":"K2-1-u2-X16"},{"t":"동생에게 화가 났어요","mis":"K2-1-u2-X16"}],"explanation":["찬 바람에도 볼이 따끈할 만큼 신나게 놀았어요.","춥다거나 화가 났다는 말은 글에 없어요.","글의 표현에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#8','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',4,'mc','auto','「데굴데굴 눈사람」을 읽고 두 친구가 느낌을 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#9','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',4,'essay','teacher','「첨벙첨벙 빗길」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「첨벙첨벙 빗길」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.」 — 나도 비 오는 날 장화를 신고 웅덩이를 밟으며 놀았던 일이 떠올라서 재미있었어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#10','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',4,'essay','teacher','흉내 내는 말을 두 개 넣어 비 오는 날이나 놀이터의 모습을 두 문장으로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C8","difficulty":4,"kind":"essay","stem":"흉내 내는 말을 두 개 넣어 비 오는 날이나 놀이터의 모습을 두 문장으로 써 보세요.","answer_guide":{"answer":"예: 빗방울이 창문에 톡톡 부딪혀요. / 우산을 쓴 친구들이 첨벙첨벙 뛰어가요.","scoring_points":["흉내 내는 말을 두 개 넣었는가","흉내 내는 말이 그 장면에 어울리는가","두 문장을 썼는가"]},"explanation":["흉내 내는 말 둘.","장면에 어울림.","두 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#1','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',1,'mc','auto','책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":1,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?","options":[{"t":"책 제목","correct":true},{"t":"책의 값","mis":"K2-1-u2-X17"},{"t":"책을 산 날짜","mis":"K2-1-u2-X17"}],"explanation":["제목을 알아야 친구가 그 책을 찾아 읽을 수 있어요.","값이나 산 날짜는 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭을 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?","options":[{"t":"내가 좋아하는 문장","correct":true},{"t":"책의 쪽수","mis":"K2-1-u2-X17"},{"t":"책의 무게","mis":"K2-1-u2-X17"}],"explanation":["좋아하는 문장을 말하면 책의 맛이 전해져요.","쪽수나 무게는 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭을 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#2','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',1,'mc','auto','책갈피에 적기 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X09']::text[],true,'{"seq":2,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책갈피에 적기 좋은 것은 어느 것인가요?","options":[{"t":"마음에 드는 문장 한 줄","correct":true},{"t":"책 한 쪽을 통째로","mis":"K2-1-u2-X17"},{"t":"친구를 흉보는 말","mis":"K2-1-u2-X09"}],"explanation":["책갈피에는 마음에 쏙 든 짧은 문장이 어울려요.","책을 통째로 옮기면 너무 길고, 흉보는 말은 쓰지 않아요.","짧은 문장 한 줄을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책갈피에 적기 좋은 것은 어느 것인가요?","options":[{"t":"힘이 나는 짧은 문장","correct":true},{"t":"책 첫 장부터 끝 장까지","mis":"K2-1-u2-X17"},{"t":"짝꿍 놀리는 별명","mis":"K2-1-u2-X09"}],"explanation":["책갈피에는 마음에 드는 짧은 문장이 어울려요.","책을 통째로 옮기거나 놀리는 말을 쓰면 안 돼요.","짧은 문장 한 줄을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#3','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',1,'mc','auto','책갈피는 무엇인가요?',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":3,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책갈피는 무엇인가요?","options":[{"t":"읽던 곳을 표시해 두는 작은 종이","correct":true},{"t":"책의 겉을 싸는 종이","mis":"K2-1-u2-X17"},{"t":"책을 담는 가방","mis":"K2-1-u2-X17"}],"explanation":["책갈피는 읽던 곳에 끼워 표시해요.","책을 싸는 종이나 가방은 책갈피가 아니에요.","좋아하는 문장을 적으면 나만의 책갈피가 돼요."],"variant_rule":{"alt":[{"stem":"책갈피를 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽던 곳을 쉽게 다시 찾으려고","correct":true},{"t":"책을 빨리 다 읽으려고","mis":"K2-1-u2-X17"},{"t":"책값을 적어 두려고","mis":"K2-1-u2-X17"}],"explanation":["책갈피를 끼워 두면 읽던 곳을 쉽게 찾아요.","빨리 읽거나 값을 적으려고 쓰는 것이 아니에요.","좋아하는 문장을 적어 두면 더 좋아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#4','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',1,'ox','auto','좋아하는 문장을 소개할 때 좋아하는 까닭을 함께 말하면 좋아요.',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":4,"concept":"K2-1-u2-C10","difficulty":1,"kind":"ox","stem":"좋아하는 문장을 소개할 때 좋아하는 까닭을 함께 말하면 좋아요.","answer":"O","reason_options":[{"t":"친구가 내 마음을 알고 책을 읽고 싶어지니까","correct":true},{"t":"문장만 말하면 충분하니까","mis":"K2-1-u2-X17"}],"mis":"K2-1-u2-X17","explanation":["까닭을 들으면 친구도 그 문장이 좋아질 수 있어요.","문장만 말하면 왜 좋은지 알기 어려워요.","「~해서 좋아요.」 하고 까닭을 말해요."],"variant_rule":{"alt":[{"stem":"책을 소개할 때 책 제목은 말하지 않아도 돼요.","answer":"X","reason_options":[{"t":"제목을 알아야 친구가 그 책을 찾아 읽을 수 있으니까","correct":true},{"t":"좋아하는 문장만 좋으면 되니까","mis":"K2-1-u2-X17"}],"explanation":["제목을 모르면 친구가 그 책을 찾을 수 없어요.","소개할 때 제목을 먼저 말해요.","제목 → 좋아하는 문장 → 까닭 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#5','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'match','auto','책 소개의 부분과 알맞은 말을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C10","difficulty":2,"kind":"match","stem":"책 소개의 부분과 알맞은 말을 이어 보세요.","pairs":[{"l":"책 제목","r":"「제가 좋아하는 책은 『달팽이 우체부』예요.」"},{"l":"좋아하는 문장","r":"「좋아하는 문장은 ‘느려도 꼭 도착할 거야.’예요.」"},{"l":"까닭","r":"「포기하지 않는 마음이 멋져서 좋아요.」"}],"mis":"K2-1-u2-X17","explanation":["먼저 책 제목을 말해요.","다음에 좋아하는 문장을 말해요.","마지막으로 좋아하는 까닭을 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책 소개의 부분과 알맞은 말을 이어 보세요.","pairs":[{"l":"책 제목","r":"「제가 좋아하는 책은 『겁쟁이 고양이 뭉치』예요.」"},{"l":"좋아하는 문장","r":"「좋아하는 문장은 ‘천천히 해도 괜찮아.’예요.」"},{"l":"까닭","r":"「읽으면 마음이 편해져서 좋아요.」"}],"explanation":["먼저 책 제목을 말해요.","다음에 좋아하는 문장을 말해요.","마지막으로 좋아하는 까닭을 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#6','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'mc','auto','책을 소개하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":6,"concept":"K2-1-u2-C10","difficulty":2,"kind":"mc","stem":"책을 소개하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"책 제목 → 좋아하는 문장 → 좋아하는 까닭","correct":true},{"t":"좋아하는 까닭 → 책 제목 → 좋아하는 문장","mis":"K2-1-u2-X17"},{"t":"좋아하는 문장 → 좋아하는 까닭 (제목은 빼요)","mis":"K2-1-u2-X17"}],"explanation":["제목을 먼저 말해야 어떤 책인지 알아요.","그다음 문장과 까닭을 말하면 깔끔해요.","제목을 빼면 친구가 책을 찾을 수 없어요."],"variant_rule":{"alt":[{"stem":"책을 소개할 때 가장 먼저 말하면 좋은 것은 어느 것인가요?","options":[{"t":"책 제목","correct":true},{"t":"좋아하는 까닭","mis":"K2-1-u2-X17"},{"t":"책을 다 읽은 날짜","mis":"K2-1-u2-X17"}],"explanation":["제목을 먼저 말해야 어떤 책인지 알아요.","까닭은 좋아하는 문장 다음에 말해요.","읽은 날짜는 꼭 말하지 않아도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#7','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'sa','auto','읽던 곳에 끼워 표시해 두는 작은 종이를 무엇이라고 하나요?','{}'::text[],true,'{"seq":7,"concept":"K2-1-u2-C10","difficulty":2,"kind":"sa","stem":"읽던 곳에 끼워 표시해 두는 작은 종이를 무엇이라고 하나요?","answer":["책갈피"],"explanation":["읽던 곳을 표시하는 종이는 책갈피예요.","좋아하는 문장을 적어 꾸밀 수 있어요.","나만의 책갈피를 만들어 봐요."],"variant_rule":{"alt":[{"stem":"책의 이름을 무엇이라고 하나요? 두 글자로 써 보세요.","answer":["제목"],"explanation":["책의 이름은 「제목」이에요.","책을 소개할 때 제목을 먼저 말해요.","제목을 알아야 그 책을 찾을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#8','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'mc','auto','책 소개로 가장 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":2,"kind":"mc","stem":"책 소개로 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「이 문장을 읽으면 힘이 나서 좋아요.」","correct":true},{"t":"「그냥 아무거나요.」","mis":"K2-1-u2-X17"},{"t":"「책 이름은 몰라요.」","mis":"K2-1-u2-X17"}],"explanation":["좋아하는 까닭을 함께 말했어요.","「아무거나」나 「몰라요」로는 책이 소개되지 않아요.","제목, 문장, 까닭을 담아 말해요."],"variant_rule":{"alt":[{"stem":"친구의 책 소개를 듣고 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그 문장 나도 마음에 들어. 나도 읽어 볼래.」","correct":true},{"t":"「그 책 재미없어.」","mis":"K2-1-u2-X09"},{"t":"(친구가 말하는 중에) 「내 책이 더 좋아!」","mis":"K2-1-u2-X08"}],"explanation":["친구 소개에서 좋은 점을 찾아 말해요.","깎아내리거나 끼어들면 친구가 속상해요.","끝까지 듣고 마음에 든 점을 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#9','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'ox','auto','책갈피에는 책 한 쪽을 통째로 옮겨 써요.',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":9,"concept":"K2-1-u2-C10","difficulty":2,"kind":"ox","stem":"책갈피에는 책 한 쪽을 통째로 옮겨 써요.","answer":"X","reason_options":[{"t":"마음에 드는 짧은 문장 한 줄이 알맞으니까","correct":true},{"t":"많이 쓸수록 좋으니까","mis":"K2-1-u2-X17"}],"mis":"K2-1-u2-X17","explanation":["책갈피는 작아서 짧은 문장이 어울려요.","마음에 쏙 든 한 줄을 골라요.","고른 까닭도 생각해 두어요."],"variant_rule":{"alt":[{"stem":"좋아하는 문장은 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"마음에 와닿는 문장이 저마다 다르니까","correct":true},{"t":"정답인 문장이 하나 정해져 있으니까","mis":"K2-1-u2-X16"}],"explanation":["같은 책을 읽어도 좋아하는 문장은 다를 수 있어요.","친구가 고른 문장도 소중해요.","왜 그 문장을 골랐는지 물어봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#10','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"예린 — 「제 책은… 제목은 몰라요. 그냥 재미있어요.」","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"하준 — 「제가 좋아하는 책은 『작은 씨앗의 여행』이에요. 씨앗이 용감해서 좋아요.」","mis":"K2-1-u2-X19"},{"t":"지안 — 「좋아하는 문장은 ‘천천히 해도 괜찮아.’예요. 마음이 편해져서 좋아요.」","mis":"K2-1-u2-X19"}],"explanation":["예린이는 제목도, 좋아하는 문장도, 까닭도 말하지 않았어요.","하준이와 지안이는 제목이나 문장과 까닭을 말했어요.","제목 → 문장 → 까닭을 담아 소개해요."],"variant_rule":{"alt":[{"stem":"친구들이 책갈피를 보여 주며 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"현우 — 책 세 쪽을 그대로 옮겨 적은 책갈피를 보여 주었어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"소율 — 「힘내, 너는 할 수 있어.」 한 줄을 적었어요","mis":"K2-1-u2-X19"},{"t":"서아 — 좋아하는 문장 한 줄과 작은 그림을 그렸어요","mis":"K2-1-u2-X19"}],"explanation":["책 세 쪽을 옮기면 책갈피에 너무 길어요.","책갈피에는 마음에 드는 짧은 문장 한 줄이 알맞아요.","소율이와 서아는 알맞게 만들었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#1','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',2,'mc','auto','책 소개를 읽고 답해 보세요. 도윤이가 좋아하는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":1,"concept":"K2-1-u2-C10","difficulty":2,"kind":"mc","stem":"책 소개를 읽고 답해 보세요. 도윤이가 좋아하는 문장은 어느 것인가요?","options":[{"t":"느려도 꼭 도착할 거야.","correct":true},{"t":"달팽이 우체부","mis":"K2-1-u2-X17"},{"t":"포기하지 않는 달팽이의 마음이 멋져요.","mis":"K2-1-u2-X17"}],"explanation":["「좋아하는 문장은 ~예요.」에 나와 있어요.","『달팽이 우체부』는 제목, 마지막 줄은 까닭이에요.","제목, 문장, 까닭을 가려 읽어요."],"asset":{"type":"passage","lines":["제가 좋아하는 책은 『달팽이 우체부』예요.","좋아하는 문장은 「느려도 꼭 도착할 거야.」예요.","포기하지 않는 달팽이의 마음이 멋져서 좋아요."],"title":"도윤이의 책 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#2','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',2,'mc','auto','책 소개를 읽고 답해 보세요. 도윤이가 그 문장을 좋아하는 까닭은 무엇인가요?',ARRAY['K2-1-u2-X14','K2-1-u2-X17']::text[],false,'{"seq":2,"concept":"K2-1-u2-C10","difficulty":2,"kind":"mc","stem":"책 소개를 읽고 답해 보세요. 도윤이가 그 문장을 좋아하는 까닭은 무엇인가요?","options":[{"t":"포기하지 않는 달팽이의 마음이 멋져서","correct":true},{"t":"달팽이가 빨리 달려서","mis":"K2-1-u2-X14"},{"t":"책이 얇아서","mis":"K2-1-u2-X17"}],"explanation":["마지막 줄에 까닭이 나와 있어요.","달팽이가 빨리 달린다는 말은 글에 없어요.","까닭은 「~해서 좋아요」 부분에서 찾아요."],"asset":{"type":"passage","lines":["제가 좋아하는 책은 『달팽이 우체부』예요.","좋아하는 문장은 「느려도 꼭 도착할 거야.」예요.","포기하지 않는 달팽이의 마음이 멋져서 좋아요."],"title":"도윤이의 책 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#3','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'mc','auto','친구들이 만든 책갈피예요. 가장 알맞게 만든 것은 어느 것인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X09']::text[],false,'{"seq":3,"concept":"K2-1-u2-C10","difficulty":3,"kind":"mc","stem":"친구들이 만든 책갈피예요. 가장 알맞게 만든 것은 어느 것인가요?","options":[{"t":"『겁쟁이 고양이 뭉치』 — 천천히 해도 괜찮아.","correct":true},{"t":"책 1쪽부터 5쪽까지를 그대로 옮겨 적은 책갈피","mis":"K2-1-u2-X17"},{"t":"「짝꿍 바보」라고 적은 책갈피","mis":"K2-1-u2-X09"}],"explanation":["책 제목과 마음에 드는 문장 한 줄을 적었어요.","책을 통째로 옮기면 너무 길어요.","친구를 놀리는 말은 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#4','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'mc','auto','좋아하는 문장과 까닭이 잘 어울리게 소개한 것은 어느 것인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X14']::text[],false,'{"seq":4,"concept":"K2-1-u2-C10","difficulty":3,"kind":"mc","stem":"좋아하는 문장과 까닭이 잘 어울리게 소개한 것은 어느 것인가요?","options":[{"t":"「나는 할 수 있어!」 — 읽으면 힘이 나는 말이라서 좋아요","correct":true},{"t":"「나는 할 수 있어!」 — 책 표지가 초록색이라서 좋아요","mis":"K2-1-u2-X17"},{"t":"「천천히 해도 괜찮아.」 — 빨리빨리 하라는 말이라서 좋아요","mis":"K2-1-u2-X14"}],"explanation":["힘이 나는 문장에 힘이 난다는 까닭이 어울려요.","표지 색은 문장을 좋아하는 까닭이 아니에요.","「천천히 해도 괜찮아.」는 빨리하라는 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#5','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'ox','auto','친구가 소개한 문장이 내 마음에 들지 않으면 「그 문장은 별로야.」 하고 말해요.',ARRAY['K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C10","difficulty":3,"kind":"ox","stem":"친구가 소개한 문장이 내 마음에 들지 않으면 「그 문장은 별로야.」 하고 말해요.","answer":"X","reason_options":[{"t":"친구가 고른 까닭을 듣고 좋은 점을 찾아 말하는 것이 좋으니까","correct":true},{"t":"솔직하게 깎아내려야 하니까","mis":"K2-1-u2-X09"}],"mis":"K2-1-u2-X09","explanation":["좋아하는 문장은 사람마다 달라요.","깎아내리면 친구가 속상해요.","「왜 그 문장이 좋아?」 하고 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#6','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'error','auto','친구들이 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"태민 — 「재밌어요.」라고만 말하고 들어갔어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"은솔 — 제목, 좋아하는 문장, 까닭을 차례로 말했어요","mis":"K2-1-u2-X19"},{"t":"하람 — 친구들을 보며 좋아하는 문장을 또박또박 읽었어요","mis":"K2-1-u2-X19"}],"explanation":["태민이는 제목도 문장도 까닭도 말하지 않았어요.","은솔이와 하람이는 알맞게 소개했어요.","제목 → 문장 → 까닭을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#7','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'mc','auto','친구가 책을 설명했어요. 「겁 많은 토끼가 용기를 내어 모험을 떠나는 책이에요. 좋아하는 문장은 ‘나는 할 수 있어!’예요.」 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":7,"concept":"K2-1-u2-C10","difficulty":3,"kind":"mc","stem":"친구가 책을 설명했어요. 「겁 많은 토끼가 용기를 내어 모험을 떠나는 책이에요. 좋아하는 문장은 ‘나는 할 수 있어!’예요.」 어울리는 제목은 어느 것인가요?","options":[{"t":"『용감한 토끼』","correct":true},{"t":"『겁쟁이 고양이 뭉치』","mis":"K2-1-u2-X14"},{"t":"『달팽이 우체부』","mis":"K2-1-u2-X14"}],"explanation":["토끼가 용기를 내는 책이니 『용감한 토끼』가 어울려요.","고양이나 달팽이는 설명에 나오지 않아요.","설명 속 인물과 일을 짚어 제목을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#8','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#9','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',4,'essay','teacher','좋아하는 책 한 권을 소개하는 말을 세 문장으로 써 보세요. 제목, 좋아하는 문장, 좋아하는 까닭을 차례로 담아요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C10","difficulty":4,"kind":"essay","stem":"좋아하는 책 한 권을 소개하는 말을 세 문장으로 써 보세요. 제목, 좋아하는 문장, 좋아하는 까닭을 차례로 담아요.","answer_guide":{"answer":"예: 제가 좋아하는 책은 『달팽이 우체부』예요. / 좋아하는 문장은 「느려도 꼭 도착할 거야.」예요. / 포기하지 않는 마음이 멋져서 좋아요.","scoring_points":["책 제목을 썼는가","좋아하는 문장을 썼는가","좋아하는 까닭을 썼는가"]},"explanation":["제목.","좋아하는 문장.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#10','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',4,'essay','teacher','내가 책갈피를 만든다면 어떤 문장을 적고 싶은지 쓰고, 그 문장을 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C10","difficulty":4,"kind":"essay","stem":"내가 책갈피를 만든다면 어떤 문장을 적고 싶은지 쓰고, 그 문장을 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 「천천히 해도 괜찮아.」 — 급해서 속상할 때 보면 마음이 편해질 것 같아서 골랐어요.","scoring_points":["책갈피에 적을 짧은 문장을 썼는가","그 문장을 고른 까닭을 썼는가","까닭이 문장의 뜻과 어울리는가"]},"explanation":["짧은 문장.","고른 까닭.","뜻과 어울림."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#1','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',1,'mc','auto','떡볶이 가게에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],true,'{"seq":1,"concept":"K2-1-u2-C11","difficulty":1,"kind":"mc","stem":"떡볶이 가게에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"매콤달콤 떡볶이","correct":true},{"t":"가게1호","mis":"K2-1-u2-X18"},{"t":"음식 파는 곳","mis":"K2-1-u2-X18"}],"explanation":["「매콤달콤」은 떡볶이 맛이 떠오르는 재미있는 말이에요.","「가게1호」, 「음식 파는 곳」은 무엇을 파는지도 재미도 드러나지 않아요.","맛이나 모양을 살려 이름을 지어요."],"variant_rule":{"alt":[{"stem":"국숫집에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"후루룩 국수","correct":true},{"t":"가게 2번","mis":"K2-1-u2-X18"},{"t":"밥 먹는 집","mis":"K2-1-u2-X18"}],"explanation":["「후루룩」은 국수 먹는 소리가 떠오르는 말이에요.","「가게 2번」, 「밥 먹는 집」은 국숫집인지 알기 어려워요.","소리 흉내 말을 넣으면 이름이 재미있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#2','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',1,'mc','auto','소리를 흉내 낸 말을 넣어 지은 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],true,'{"seq":2,"concept":"K2-1-u2-C11","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말을 넣어 지은 이름은 어느 것인가요?","options":[{"t":"보글보글 찌개집","correct":true},{"t":"맛있는 찌개집","mis":"K2-1-u2-X18"},{"t":"큰 찌개집","mis":"K2-1-u2-X18"}],"explanation":["「보글보글」은 찌개가 끓는 소리예요.","「맛있는」, 「큰」은 소리를 흉내 낸 말이 아니에요.","소리 흉내 말을 넣으면 이름이 통통 튀어요."],"variant_rule":{"alt":[{"stem":"같은 소리를 되풀이해 지은 이름은 어느 것인가요?","options":[{"t":"콩콩 두부집","correct":true},{"t":"두부 파는 집","mis":"K2-1-u2-X18"},{"t":"하얀 두부집","mis":"K2-1-u2-X18"}],"explanation":["「콩콩」은 같은 소리를 되풀이했어요.","되풀이하면 리듬이 생겨 기억에 잘 남아요.","다른 두 이름에는 되풀이한 소리가 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#3','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C5',1,'mc','auto','이름 짓기 놀이를 할 때 지킬 약속은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],true,'{"seq":3,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"이름 짓기 놀이를 할 때 지킬 약속은 어느 것인가요?","options":[{"t":"친구를 놀리는 말은 쓰지 않아요","correct":true},{"t":"친구 이름을 바꿔 놀리는 이름을 지어요","mis":"K2-1-u2-X09"},{"t":"내 생각대로만 정해요","mis":"K2-1-u2-X08"}],"explanation":["놀리는 말은 친구를 속상하게 해요.","혼자 정하면 함께 즐길 수 없어요.","모두가 즐거운 이름을 지어요."],"variant_rule":{"alt":[{"stem":"모둠에서 함께 이름 짓기 활동을 정할 때 알맞은 것은 어느 것인가요?","options":[{"t":"모두의 생각을 모아요","correct":true},{"t":"목소리 큰 친구 생각대로 해요","mis":"K2-1-u2-X08"},{"t":"싫은 생각에는 「그건 바보 같아.」 하고 말해요","mis":"K2-1-u2-X09"}],"explanation":["모두의 생각을 모으면 더 재미있는 생각이 나와요.","한 사람이 정하거나 깎아내리면 함께 즐길 수 없어요.","친구 생각을 끝까지 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#4','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',1,'ox','auto','음식의 특징을 살려 이름을 지으면 무엇을 파는지 알기 쉬워요.',ARRAY['K2-1-u2-X18']::text[],true,'{"seq":4,"concept":"K2-1-u2-C11","difficulty":1,"kind":"ox","stem":"음식의 특징을 살려 이름을 지으면 무엇을 파는지 알기 쉬워요.","answer":"O","reason_options":[{"t":"이름만 들어도 맛이나 모양이 떠오르니까","correct":true},{"t":"이름은 짧을수록 좋으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「뜨끈한 국수집」처럼 특징을 살리면 무엇을 파는지 알아요.","짧기만 한 이름은 무엇인지 알기 어려워요.","특징을 살리고 소리의 재미를 더해요."],"variant_rule":{"alt":[{"stem":"「가게1호」는 무엇을 파는지 잘 드러나는 재미있는 이름이에요.","answer":"X","reason_options":[{"t":"무엇을 파는지도, 소리의 재미도 없으니까","correct":true},{"t":"숫자가 들어가 기억하기 쉬우니까","mis":"K2-1-u2-X18"}],"explanation":["「가게1호」만 들어서는 무엇을 파는지 몰라요.","소리의 재미도 느껴지지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#5','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',2,'match','auto','가게와 어울리는 재미있는 이름을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C11","difficulty":2,"kind":"match","stem":"가게와 어울리는 재미있는 이름을 이어 보세요.","pairs":[{"l":"빵집","r":"폭신폭신 빵집"},{"l":"김밥집","r":"돌돌 말이 김밥"},{"l":"튀김집","r":"바삭바삭 튀김"}],"mis":"K2-1-u2-X18","explanation":["「폭신폭신」은 부드러운 빵이 떠올라요.","「돌돌」은 김밥을 마는 모양이에요.","「바삭바삭」은 튀김 씹는 소리예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 가게와 어울리는 재미있는 이름을 이어 보세요.","pairs":[{"l":"과일 가게","r":"새콤달콤 과일"},{"l":"꽃집","r":"방긋방긋 꽃집"},{"l":"신발 가게","r":"폴짝폴짝 신발"}],"explanation":["「새콤달콤」은 과일 맛이 떠올라요.","「방긋방긋」은 웃는 꽃이 떠올라요.","「폴짝폴짝」은 신발 신고 뛰는 모습이 떠올라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#6','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',2,'mc','auto','「지글지글 고기집」에서 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],true,'{"seq":6,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"「지글지글 고기집」에서 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"지글지글","correct":true},{"t":"고기","mis":"K2-1-u2-X15"},{"t":"집","mis":"K2-1-u2-X15"}],"explanation":["「지글지글」은 고기 굽는 소리예요.","「고기」, 「집」은 이름에 들어간 낱말이지만 흉내 내는 말은 아니에요.","소리 내어 따라 하면 소리가 들리는지 봐요."],"variant_rule":{"alt":[{"stem":"「바삭바삭 튀김」에서 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"바삭바삭","correct":true},{"t":"튀김","mis":"K2-1-u2-X15"},{"t":"튀기다","mis":"K2-1-u2-X15"}],"explanation":["「바삭바삭」은 튀김을 씹는 소리예요.","「튀김」은 음식 이름, 「튀기다」는 하는 일이에요.","소리 내어 따라 하면 소리가 들리는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#7','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',2,'sa','auto','국수를 먹는 소리를 흉내 낸 말을 넣어 이름을 완성해 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#8','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',2,'mc','auto','재미있는 이름을 짓는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X18','K2-1-u2-X09']::text[],true,'{"seq":8,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"재미있는 이름을 짓는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 소리를 되풀이해 리듬을 살려요","correct":true},{"t":"아무 글자나 막 붙여요","mis":"K2-1-u2-X18"},{"t":"친구 별명을 놀리듯 넣어요","mis":"K2-1-u2-X09"}],"explanation":["「콩콩」, 「폴짝폴짝」처럼 되풀이하면 리듬이 생겨요.","아무 글자나 붙이면 뜻도 재미도 없어요.","친구를 놀리는 말은 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 재미있는 이름을 짓는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식의 맛이나 모양을 살려요","correct":true},{"t":"숫자만 붙여요","mis":"K2-1-u2-X18"},{"t":"친구가 싫어하는 별명을 넣어요","mis":"K2-1-u2-X09"}],"explanation":["「매콤달콤 떡볶이」처럼 특징을 살려요.","숫자만 붙이면 무엇인지 알 수 없어요.","친구를 놀리는 말은 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#9','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C5',2,'ox','auto','친구가 지은 이름이 우스우면 「이상해!」 하고 놀려도 돼요.',ARRAY['K2-1-u2-X09']::text[],true,'{"seq":9,"concept":"K2-1-u2-C5","difficulty":2,"kind":"ox","stem":"친구가 지은 이름이 우스우면 「이상해!」 하고 놀려도 돼요.","answer":"X","reason_options":[{"t":"친구 마음이 상하고 함께 즐길 수 없으니까","correct":true},{"t":"솔직하게 말하는 것이니까","mis":"K2-1-u2-X09"}],"mis":"K2-1-u2-X09","explanation":["놀리면 친구가 다시 생각을 말하고 싶지 않아져요.","좋은 점을 먼저 찾아 말해요.","「거기에 흉내 내는 말을 붙여 볼까?」 하고 도와요."],"variant_rule":{"alt":[{"stem":"친구 이름을 바꿔 부르며 놀리는 것도 재미있는 말놀이예요.","answer":"X","reason_options":[{"t":"놀리는 말은 친구를 속상하게 하니까","correct":true},{"t":"다 같이 웃으니까","mis":"K2-1-u2-X09"}],"explanation":["말놀이는 모두가 즐거워야 해요.","한 친구가 속상하면 즐거운 놀이가 아니에요.","놀리는 말은 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#10','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',3,'error','auto','아이스크림 가게 이름을 지었어요. 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u2-X18','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C11","difficulty":3,"kind":"error","stem":"아이스크림 가게 이름을 지었어요. 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"도담 — 「가게 3번」","correct":true,"mis_target":"K2-1-u2-X18"},{"t":"서윤 — 「시원달콤 아이스」","mis":"K2-1-u2-X19"},{"t":"하늘 — 「사르르 녹는 아이스크림」","mis":"K2-1-u2-X19"}],"explanation":["「가게 3번」은 무엇을 파는지도, 재미도 드러나지 않아요.","서윤이와 하늘이는 맛과 모양을 살려 지었어요.","특징과 흉내 내는 말을 살려요."],"variant_rule":{"alt":[{"stem":"빵집 이름을 지었어요. 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"지후 — 「먹보 민호네 빵집」","correct":true,"mis_target":"K2-1-u2-X09"},{"t":"아린 — 「몽실몽실 구름빵」","mis":"K2-1-u2-X19"},{"t":"준우 — 「고소고소 소보로」","mis":"K2-1-u2-X19"}],"explanation":["「먹보 민호」는 친구를 놀리는 말이에요.","아린이와 준우는 빵의 모양과 맛을 살려 지었어요.","친구를 놀리는 말은 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#1','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',2,'mc','auto','「폭신폭신 구름빵」에서 「폭신폭신」은 무엇을 살린 말인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":1,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"「폭신폭신 구름빵」에서 「폭신폭신」은 무엇을 살린 말인가요?","options":[{"t":"빵이 부드러운 모양","correct":true},{"t":"빵의 값","mis":"K2-1-u2-X18"},{"t":"가게 주인의 이름","mis":"K2-1-u2-X18"}],"explanation":["「폭신폭신」은 부드럽고 푹신한 모양을 흉내 낸 말이에요.","값이나 주인 이름은 드러나지 않아요.","특징을 살린 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#2','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',2,'mc','auto','「냠냠 김밥」과 「김밥집」 가운데 더 재미있는 이름과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":2,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"「냠냠 김밥」과 「김밥집」 가운데 더 재미있는 이름과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「냠냠 김밥」 — 먹는 소리를 흉내 내어 재미있어서","correct":true},{"t":"「김밥집」 — 짧아서","mis":"K2-1-u2-X18"},{"t":"둘 다 똑같이 재미있어요","mis":"K2-1-u2-X18"}],"explanation":["「냠냠」은 맛있게 먹는 소리예요.","「김밥집」은 무엇을 파는지는 알지만 재미는 없어요.","소리 흉내 말을 넣으면 이름이 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#3','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',3,'mc','auto','붕어빵 가게의 특징을 살린 이름으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":3,"concept":"K2-1-u2-C11","difficulty":3,"kind":"mc","stem":"붕어빵 가게의 특징을 살린 이름으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바삭 말랑 붕어빵","correct":true},{"t":"붕어 낚시터","mis":"K2-1-u2-X18"},{"t":"빵빵빵빵","mis":"K2-1-u2-X18"}],"explanation":["겉은 바삭, 속은 말랑한 붕어빵의 특징을 살렸어요.","「붕어 낚시터」는 빵 가게가 아니고, 「빵빵빵빵」은 무엇인지 알 수 없어요.","무엇을 파는지와 특징이 함께 드러나게 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#4','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',3,'mc','auto','수박 주스 가게 이름으로 같은 소리를 되풀이하면서 특징도 살린 것은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":4,"concept":"K2-1-u2-C11","difficulty":3,"kind":"mc","stem":"수박 주스 가게 이름으로 같은 소리를 되풀이하면서 특징도 살린 것은 어느 것인가요?","options":[{"t":"시원시원 수박 주스","correct":true},{"t":"주스 주스 가게","mis":"K2-1-u2-X18"},{"t":"수박 1번","mis":"K2-1-u2-X18"}],"explanation":["「시원시원」은 되풀이한 소리이고 시원한 맛도 살렸어요.","「주스 주스」는 특징이 없고, 「수박 1번」은 재미가 없어요.","되풀이와 특징을 함께 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#5','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',3,'ox','auto','「또르르 굴러온 눈사람 빙수」처럼 흉내 내는 말을 넣으면 이름이 기억에 더 잘 남아요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":5,"concept":"K2-1-u2-C11","difficulty":3,"kind":"ox","stem":"「또르르 굴러온 눈사람 빙수」처럼 흉내 내는 말을 넣으면 이름이 기억에 더 잘 남아요.","answer":"O","reason_options":[{"t":"소리와 모양이 떠올라 재미있으니까","correct":true},{"t":"이름은 길기만 하면 좋으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["흉내 내는 말은 모습을 떠올리게 해요.","길다고 좋은 이름은 아니에요.","특징과 재미가 담겨야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#6','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C5',3,'error','auto','모둠에서 이름을 정하고 있어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C5","difficulty":3,"kind":"error","stem":"모둠에서 이름을 정하고 있어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"현우 — 「내가 정한 이름으로 해! 다른 건 안 돼.」","correct":true,"mis_target":"K2-1-u2-X08"},{"t":"아린 — 「다 같이 생각을 하나씩 말해 보자.」","mis":"K2-1-u2-X19"},{"t":"소율 — 「그 이름 재미있다. 흉내 내는 말을 붙여 볼까?」","mis":"K2-1-u2-X19"}],"explanation":["현우는 혼자 정하고 다른 생각을 막았어요.","아린이와 소율이는 함께 정하려고 했어요.","모두의 생각을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#7','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',3,'mc','auto','떡집 주인이 말했어요. 「우리 떡은 쫀득쫀득하고 색깔이 알록달록해요.」 이 떡집에 어울리는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18','K2-1-u2-X14']::text[],false,'{"seq":7,"concept":"K2-1-u2-C11","difficulty":3,"kind":"mc","stem":"떡집 주인이 말했어요. 「우리 떡은 쫀득쫀득하고 색깔이 알록달록해요.」 이 떡집에 어울리는 이름은 어느 것인가요?","options":[{"t":"쫀득쫀득 알록 떡집","correct":true},{"t":"떡 파는 집","mis":"K2-1-u2-X18"},{"t":"바삭바삭 떡집","mis":"K2-1-u2-X14"}],"explanation":["주인이 말한 특징 「쫀득쫀득」, 「알록달록」을 살렸어요.","「떡 파는 집」은 재미가 없어요.","떡은 바삭바삭하다고 하지 않았어요."],"asset":{"type":"speech","turns":[{"who":"떡집 주인","text":"우리 떡은 쫀득쫀득하고 색깔이 알록달록해요."},{"who":"나","text":"그럼 이름에 그 특징을 넣어 볼까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#8','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',4,'mc','auto','처음에 지은 「과자 가게」라는 이름을 「바삭바삭 오독오독 과자 가게」로 고쳤어요. 고친 이름이 더 좋아진 까닭은 무엇인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":8,"concept":"K2-1-u2-C11","difficulty":4,"kind":"mc","stem":"처음에 지은 「과자 가게」라는 이름을 「바삭바삭 오독오독 과자 가게」로 고쳤어요. 고친 이름이 더 좋아진 까닭은 무엇인가요?","options":[{"t":"과자 먹는 소리가 떠올라 재미있고 무엇을 파는지도 알 수 있어서","correct":true},{"t":"글자 수가 늘어 더 어려워져서","mis":"K2-1-u2-X18"},{"t":"과자 값을 알 수 있어서","mis":"K2-1-u2-X18"}],"explanation":["흉내 내는 말을 넣어 소리의 재미를 살렸어요.","「과자 가게」를 남겨 무엇을 파는지도 알 수 있어요.","글자 수나 값 때문에 좋아진 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#9','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',4,'essay','teacher','내가 가게를 연다면 무엇을 팔지 정하고, 배운 방법으로 재미있는 이름을 지어 그 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":4,"kind":"essay","stem":"내가 가게를 연다면 무엇을 팔지 정하고, 배운 방법으로 재미있는 이름을 지어 그 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 붕어빵을 팔 거예요. 이름은 「바삭 말랑 붕어빵」이에요. 겉은 바삭하고 속은 말랑한 맛을 살렸어요.","scoring_points":["무엇을 팔지 썼는가","흉내 내는 말·되풀이·특징 가운데 하나 이상을 살려 이름을 지었는가","이름을 그렇게 지은 까닭을 썼는가"]},"explanation":["파는 것.","배운 방법.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#10','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',4,'essay','teacher','흉내 내는 말을 넣어 우리 모둠의 이름을 짓고, 그렇게 지은 까닭을 두 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C11","difficulty":4,"kind":"essay","stem":"흉내 내는 말을 넣어 우리 모둠의 이름을 짓고, 그렇게 지은 까닭을 두 가지 써 보세요.","answer_guide":{"answer":"예: 「깡충깡충 토끼 모둠」 — 우리 모둠은 뛰어놀기를 좋아하고, 토끼처럼 서로 잘 도와주기 때문이에요.","scoring_points":["흉내 내는 말을 넣어 이름을 지었는가","까닭을 두 가지 썼는가","친구를 놀리는 말 없이 모두가 기분 좋은 이름인가"]},"explanation":["흉내 내는 말.","까닭 둘.","모두가 기분 좋은 이름."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#1','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C1',1,'mc','auto','가늘게 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"가늘게 내리는 비를 무엇이라고 하나요?","options":[{"t":"가랑비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"단비","mis":"K2-1-u2-X01"}],"explanation":["가늘게 내리는 비는 가랑비예요.","비가 내리는 모습에 따라 이름이 달라요.","이름에는 그렇게 부르는 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#2','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C2',1,'mc','auto','「비」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「비」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"비행기","correct":true},{"t":"제비","mis":"K2-1-u2-X02"},{"t":"버섯","mis":"K2-1-u2-X03"}],"explanation":["비행기는 첫 글자가 「비」예요.","다른 낱말은 「비」가 끝에 있거나 다른 글자로 시작해요.","맨 앞 글자를 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#3','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#4','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":4,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"오늘참좋다","correct":true},{"t":"안녕","mis":"K2-1-u2-X06"},{"t":"반가워친구야","mis":"K2-1-u2-X06"}],"explanation":["오·늘·참·좋·다, 다섯 글자예요.","다른 말은 다섯 글자보다 적거나 많아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#5','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 모습은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 모습은 어느 것인가요?","options":[{"t":"내 차례를 기다려요","correct":true},{"t":"친구 말을 끊고 먼저 말해요","mis":"K2-1-u2-X08"},{"t":"틀린 친구를 놀려요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지키고 함께 즐겨야 말놀이가 재미있어요.","끼어들거나 놀리면 놀이가 즐겁지 않아요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#6','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C6',1,'mc','auto','부엌에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"부엌에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"국자","correct":true},{"t":"칠판","mis":"K2-1-u2-X10"},{"t":"그네","mis":"K2-1-u2-X10"}],"explanation":["국자는 부엌에서 볼 수 있어요.","다른 낱말은 다른 장소에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#7','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C8',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":7,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"맴맴","correct":true},{"t":"매미","mis":"K2-1-u2-X15"},{"t":"여름","mis":"K2-1-u2-X15"}],"explanation":["「맴맴」은 매미 소리를 흉내 낸 말이에요.","다른 두 낱말은 흉내 내는 말이 아니에요.","따라 했을 때 소리나 모습이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#8','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C10',1,'mc','auto','책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?","options":[{"t":"책 제목","correct":true},{"t":"책의 값","mis":"K2-1-u2-X17"},{"t":"책을 산 가게","mis":"K2-1-u2-X17"}],"explanation":["제목을 알아야 친구가 그 책을 찾을 수 있어요.","다른 것은 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#9','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C11',2,'ox','auto','「가게1호」는 무엇을 파는지 잘 드러나는 재미있는 이름이에요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":2,"kind":"ox","stem":"「가게1호」는 무엇을 파는지 잘 드러나는 재미있는 이름이에요.","answer":"X","reason_options":[{"t":"무엇을 파는지도 소리의 재미도 없으니까","correct":true},{"t":"숫자가 들어가 기억하기 쉬우니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「가게1호」만 들어서는 무엇을 파는지 몰라요.","소리의 재미도 느껴지지 않아요.","특징과 흉내 내는 말을 살려 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#10','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「시장에 가면 사과도 있고, 배도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":10,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「시장에 가면 사과도 있고, 배도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「시장에 가면 사과도 있고, 배도 있고, 감도 있고」","correct":true},{"t":"「시장에 가면 감도 있고」","mis":"K2-1-u2-X07"},{"t":"「시장에 가면 배도 있고, 사과도 있고, 감도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#11','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C7',2,'mc','auto','친구가 「옛날에 곰이 살았어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":11,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「옛날에 곰이 살았어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「곰은 꿀을 좋아했어요.」","correct":true},{"t":"「자동차가 빵빵 울려요.」","mis":"K2-1-u2-X13"},{"t":"「곰 꿀 나무.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 인물 이야기를 이어 가요.","관계없는 문장이나 낱말만 늘어놓은 말은 이야기를 끊어요.","앞 문장의 인물을 넣어 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#12','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「리 · 구 · 개」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":12,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「리 · 구 · 개」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"개구리","correct":true},{"t":"구리개","mis":"K2-1-u2-X11"},{"t":"개리","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「개구리」가 돼요.","차례를 잘못 놓거나 글자를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#13','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 지우는 무엇을 쓰고 걸었나요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":13,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지우는 무엇을 쓰고 걸었나요?","options":[{"t":"노란 우산","correct":true},{"t":"빨간 모자","mis":"K2-1-u2-X14"},{"t":"파란 비옷","mis":"K2-1-u2-X14"}],"explanation":["글에 「노란 우산을 쓰고」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 것이에요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#14','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C9',2,'ox','auto','같은 글을 읽어도 사람마다 느낌이 다를 수 있어요.',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":14,"concept":"K2-1-u2-C9","difficulty":2,"kind":"ox","stem":"같은 글을 읽어도 사람마다 느낌이 다를 수 있어요.","answer":"O","reason_options":[{"t":"저마다 겪은 일과 생각이 다르니까","correct":true},{"t":"정답인 느낌은 하나뿐이니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["읽는 사람마다 떠오르는 경험이 달라요.","그래서 느낌도 다를 수 있어요.","까닭을 들어 느낌을 말하고 친구 느낌도 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#15','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":15,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"사과 · 사자 · 사탕","correct":true},{"t":"사과 · 과자 · 자두","mis":"K2-1-u2-X02"},{"t":"사과 · 소금 · 수박","mis":"K2-1-u2-X03"}],"explanation":["사과 · 사자 · 사탕은 모두 첫 글자가 같아요.","끝 글자를 이은 것이나 자음자만 같은 것은 첫 글자가 같은 것이 아니에요.","맨 앞 글자를 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#16','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C11',2,'mc','auto','빵집에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":16,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"빵집에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"폭신폭신 빵집","correct":true},{"t":"빵집 1호","mis":"K2-1-u2-X18"},{"t":"먹는 곳","mis":"K2-1-u2-X18"}],"explanation":["「폭신폭신 빵집」은 부드러운 빵이 떠올라요.","다른 이름은 무엇을 파는지나 재미가 드러나지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#17','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C3',3,'error','auto','「하늘은 파래, 파라면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],false,'{"seq":17,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「하늘은 파래, 파라면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"준우 — 「파라면 사과」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"다은 — 「파라면 바다」","mis":"K2-1-u2-X19"},{"t":"서아 — 「파라면 청바지」","mis":"K2-1-u2-X19"}],"explanation":["사과는 파랗지 않아요.","다른 두 친구는 앞말에서 떠오르는 것을 이었어요.","바로 앞말에서 떠오르는 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#18','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":18,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"냉장고에서 우유를 꺼냈어요.","correct":true},{"t":"아기 곰은 꿀을 정말 좋아했어요.","mis":"K2-1-u2-X19"},{"t":"어느 날 아기 곰은 커다란 벌집을 찾았어요.","mis":"K2-1-u2-X19"}],"explanation":["「냉장고에서 우유를 꺼냈어요」는 이야기와 관계가 없어요.","다른 문장은 모두 같은 인물의 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["옛날에 아기 곰이 살았어요.","아기 곰은 꿀을 정말 좋아했어요.","냉장고에서 우유를 꺼냈어요.","어느 날 아기 곰은 커다란 벌집을 찾았어요."],"title":"아기 곰 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#19','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":19,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"데굴데굴","correct":true},{"t":"쌩쌩","mis":"K2-1-u2-X15"},{"t":"눈사람","mis":"K2-1-u2-X15"}],"explanation":["「데굴데굴」은 눈을 굴리는 모양이에요. 「쌩쌩」은 바람 소리, 「눈사람」은 이름이에요.","흉내 내는 말이 무엇의 소리인지, 모양인지 따라 해 보며 가려요.","흉내 내는 말은 글을 생생하게 만들어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#20','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":20,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"예린 — 「제목은 몰라요. 그냥 재미있어요.」","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"하준 — 「제가 좋아하는 책은 『작은 씨앗의 여행』이에요. 씨앗이 용감해서 좋아요.」","mis":"K2-1-u2-X19"},{"t":"지안 — 「좋아하는 문장은 ‘천천히 해도 괜찮아.’예요. 마음이 편해져서 좋아요.」","mis":"K2-1-u2-X19"}],"explanation":["예린이는 제목도 문장도 까닭도 말하지 않았어요.","다른 두 친구는 알맞게 소개했어요.","제목 → 좋아하는 문장 → 까닭을 담아 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#21','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 지우의 마음을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 지우의 마음을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"비 오는 날이 즐거워요","correct":true},{"t":"천둥이 무서워 울고 싶어요","mis":"K2-1-u2-X16"},{"t":"비가 와서 심심해요","mis":"K2-1-u2-X16"}],"explanation":["지우는 「비 오는 날도 참 재미있다!」라고 말했어요.","일과 반대되거나 글에 없는 마음은 알맞지 않아요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#22','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C5',3,'mc','auto','꼬리따기를 하는데 친구가 앞말과 관계없는 말을 했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":22,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"꼬리따기를 하는데 친구가 앞말과 관계없는 말을 했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「앞말에서 떠오르는 걸 다시 생각해 볼까?」","correct":true},{"t":"「그것도 몰라? 바보야.」","mis":"K2-1-u2-X09"},{"t":"「넌 빠져. 우리끼리 할게.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#23','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#24','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C3',4,'essay','teacher','「하늘은 파래」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「하늘은 파래」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 하늘은 파래 → 파라면 바다 → 바다는 넓어 → 넓으면 운동장","scoring_points":["「하늘은 파래」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#25','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C9',4,'essay','teacher','「첨벙첨벙 빗길」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「첨벙첨벙 빗길」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.」 — 나도 장화를 신고 웅덩이를 밟으며 놀았던 일이 떠올라 재미있었어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#1','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C1',1,'mc','auto','굵고 세차게 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"굵고 세차게 내리는 비를 무엇이라고 하나요?","options":[{"t":"장대비","correct":true},{"t":"이슬비","mis":"K2-1-u2-X01"},{"t":"가랑비","mis":"K2-1-u2-X01"}],"explanation":["굵고 세차게 내리는 비는 장대비예요.","비가 내리는 모습에 따라 이름이 달라요.","이름에는 그렇게 부르는 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#2','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C2',1,'mc','auto','「사」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「사」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"사다리","correct":true},{"t":"감사","mis":"K2-1-u2-X02"},{"t":"소풍","mis":"K2-1-u2-X03"}],"explanation":["사다리는 첫 글자가 「사」예요.","다른 낱말은 「사」가 끝에 있거나 다른 글자로 시작해요.","맨 앞 글자를 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#3','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#4','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":4,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"같이놀아요","correct":true},{"t":"놀자","mis":"K2-1-u2-X06"},{"t":"우리같이놀래요","mis":"K2-1-u2-X06"}],"explanation":["같·이·놀·아·요, 다섯 글자예요.","다른 말은 다섯 글자보다 적거나 많아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#5','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 모습은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 모습은 어느 것인가요?","options":[{"t":"친구 말을 끝까지 들어요","correct":true},{"t":"이기려고 혼자 계속 말해요","mis":"K2-1-u2-X08"},{"t":"친구 말을 따라 하며 비웃어요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지키고 함께 즐겨야 말놀이가 재미있어요.","끼어들거나 놀리면 놀이가 즐겁지 않아요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#6','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C6',1,'mc','auto','교실에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"교실에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"칠판","correct":true},{"t":"냄비","mis":"K2-1-u2-X10"},{"t":"시소","mis":"K2-1-u2-X10"}],"explanation":["칠판은 교실에서 볼 수 있어요.","다른 낱말은 다른 장소에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#7','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C8',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":7,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"깡충깡충","correct":true},{"t":"토끼","mis":"K2-1-u2-X15"},{"t":"뛰다","mis":"K2-1-u2-X15"}],"explanation":["「깡충깡충」은 토끼가 뛰는 모양을 흉내 낸 말이에요.","다른 두 낱말은 흉내 내는 말이 아니에요.","따라 했을 때 소리나 모습이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#8','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C10',1,'mc','auto','책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?","options":[{"t":"좋아하는 문장","correct":true},{"t":"책의 쪽수","mis":"K2-1-u2-X17"},{"t":"책의 무게","mis":"K2-1-u2-X17"}],"explanation":["좋아하는 문장을 말하면 책의 맛이 전해져요.","다른 것은 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#9','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C11',2,'ox','auto','「후루룩 국수」는 먹는 소리를 살린 재미있는 이름이에요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":2,"kind":"ox","stem":"「후루룩 국수」는 먹는 소리를 살린 재미있는 이름이에요.","answer":"O","reason_options":[{"t":"국수 먹는 소리가 떠오르니까","correct":true},{"t":"이름이 짧으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「후루룩」은 국수 먹는 소리예요.","소리를 살리면 이름이 재미있어요.","특징과 흉내 내는 말을 살려 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#10','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「동물원에 가면 사자도 있고, 기린도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":10,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「동물원에 가면 사자도 있고, 기린도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「동물원에 가면 사자도 있고, 기린도 있고, 코끼리도 있고」","correct":true},{"t":"「동물원에 가면 코끼리도 있고」","mis":"K2-1-u2-X07"},{"t":"「동물원에 가면 기린도 있고, 코끼리도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#11','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C7',2,'mc','auto','친구가 「어느 날 다람쥐가 도토리를 주웠어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":11,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「어느 날 다람쥐가 도토리를 주웠어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「다람쥐는 도토리를 나무 구멍에 숨겼어요.」","correct":true},{"t":"「비행기가 하늘을 날아요.」","mis":"K2-1-u2-X13"},{"t":"「다람쥐 도토리 구멍.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 인물 이야기를 이어 가요.","관계없는 문장이나 낱말만 늘어놓은 말은 이야기를 끊어요.","앞 문장의 인물을 넣어 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#12','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「끼 · 코 · 리」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":12,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「끼 · 코 · 리」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"코끼리","correct":true},{"t":"끼코리","mis":"K2-1-u2-X11"},{"t":"코리","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「코끼리」가 돼요.","차례를 잘못 놓거나 글자를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#13','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 민지는 누구와 연을 날렸나요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":13,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 민지는 누구와 연을 날렸나요?","options":[{"t":"아빠","correct":true},{"t":"엄마","mis":"K2-1-u2-X14"},{"t":"동생","mis":"K2-1-u2-X14"}],"explanation":["글에 「민지는 아빠와 연을 날렸어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 것이에요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["바람이 쌩쌩 부는 날, 민지는 아빠와 연을 날렸어요.","연은 하늘 높이 훨훨 날아올랐어요.","그런데 갑자기 연줄이 툭 끊어졌어요.","연은 빙글빙글 돌며 멀리 날아갔어요.","민지는 「안녕, 내 연아!」 하고 손을 흔들었어요."],"title":"훨훨 날아간 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#14','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C9',2,'ox','auto','느낌을 말할 때 「재미있었어.」라고만 말하면 충분해요.',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":14,"concept":"K2-1-u2-C9","difficulty":2,"kind":"ox","stem":"느낌을 말할 때 「재미있었어.」라고만 말하면 충분해요.","answer":"X","reason_options":[{"t":"어느 장면이 왜 재미있었는지 말해야 잘 전해지니까","correct":true},{"t":"느낌은 짧을수록 좋으니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["까닭이 없으면 느낌이 잘 전해지지 않아요.","「~해서 재미있었어.」처럼 말해요.","까닭을 들어 느낌을 말하고 친구 느낌도 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#15','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":15,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"고래 · 고구마 · 고양이","correct":true},{"t":"고구마 · 마늘 · 늘보","mis":"K2-1-u2-X02"},{"t":"고래 · 기차 · 구두","mis":"K2-1-u2-X03"}],"explanation":["고래 · 고구마 · 고양이는 모두 첫 글자가 같아요.","끝 글자를 이은 것이나 자음자만 같은 것은 첫 글자가 같은 것이 아니에요.","맨 앞 글자를 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#16','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C11',2,'mc','auto','튀김 가게에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":16,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"튀김 가게에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"바삭바삭 튀김","correct":true},{"t":"튀김 가게 2번","mis":"K2-1-u2-X18"},{"t":"파는 곳","mis":"K2-1-u2-X18"}],"explanation":["「바삭바삭 튀김」은 튀김 씹는 소리가 떠올라요.","다른 이름은 무엇을 파는지나 재미가 드러나지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#17','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C3',3,'error','auto','「눈은 하얘, 하야면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],false,'{"seq":17,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「눈은 하얘, 하야면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"도윤 — 「하야면 토마토」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"하린 — 「하야면 구름」","mis":"K2-1-u2-X19"},{"t":"예린 — 「하야면 우유」","mis":"K2-1-u2-X19"}],"explanation":["토마토는 하얗지 않아요.","다른 두 친구는 앞말에서 떠오르는 것을 이었어요.","바로 앞말에서 떠오르는 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#18','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":18,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"버스가 정류장에 멈췄어요.","correct":true},{"t":"거북이는 엉금엉금 바다로 걸어갔어요.","mis":"K2-1-u2-X19"},{"t":"파도를 만난 거북이는 신나게 헤엄쳤어요.","mis":"K2-1-u2-X19"}],"explanation":["「버스가 정류장에 멈췄어요」는 이야기와 관계가 없어요.","다른 문장은 모두 같은 인물의 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["작은 거북이가 바닷가에서 태어났어요.","거북이는 엉금엉금 바다로 걸어갔어요.","버스가 정류장에 멈췄어요.","파도를 만난 거북이는 신나게 헤엄쳤어요."],"title":"작은 거북이 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#19','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":19,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"쏙쏙","correct":true},{"t":"깔깔","mis":"K2-1-u2-X15"},{"t":"찰박찰박","mis":"K2-1-u2-X15"}],"explanation":["「쏙쏙」은 물고기가 빠르게 지나가는 모양이에요. 「깔깔」·「찰박찰박」은 소리예요.","흉내 내는 말이 무엇의 소리인지, 모양인지 따라 해 보며 가려요.","흉내 내는 말은 글을 생생하게 만들어요."],"asset":{"type":"passage","lines":["여름 방학에 하준이는 시냇가에 갔어요.","차가운 물에 발을 담그자 「앗, 차가워!」 소리가 절로 났어요.","작은 물고기들이 발가락 사이로 쏙쏙 지나갔어요.","하준이는 깔깔 웃으며 물을 찰박찰박 찼어요."],"title":"찰박찰박 시냇가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#20','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":20,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"현우 — 책 세 쪽을 그대로 옮겨 적은 책갈피를 보여 주었어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"소율 — 좋아하는 문장 한 줄을 적은 책갈피를 보여 주었어요","mis":"K2-1-u2-X19"},{"t":"서아 — 문장 한 줄과 작은 그림을 그린 책갈피를 보여 주었어요","mis":"K2-1-u2-X19"}],"explanation":["책갈피에는 짧은 문장 한 줄이 알맞아요.","다른 두 친구는 알맞게 소개했어요.","제목 → 좋아하는 문장 → 까닭을 담아 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#21','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 연이 날아갈 때 민지의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 연이 날아갈 때 민지의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"아쉽지만 연에게 인사할 만큼 씩씩해요","correct":true},{"t":"아빠에게 화가 났어요","mis":"K2-1-u2-X16"},{"t":"연이 날아가서 신이 나 춤을 춰요","mis":"K2-1-u2-X16"}],"explanation":["민지는 「안녕, 내 연아!」 하고 손을 흔들었어요.","일과 반대되거나 글에 없는 마음은 알맞지 않아요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["바람이 쌩쌩 부는 날, 민지는 아빠와 연을 날렸어요.","연은 하늘 높이 훨훨 날아올랐어요.","그런데 갑자기 연줄이 툭 끊어졌어요.","연은 빙글빙글 돌며 멀리 날아갔어요.","민지는 「안녕, 내 연아!」 하고 손을 흔들었어요."],"title":"훨훨 날아간 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#22','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C5',3,'mc','auto','말 덧붙이기를 하는데 친구가 앞말 하나를 빠뜨렸어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":22,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"말 덧붙이기를 하는데 친구가 앞말 하나를 빠뜨렸어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「배도 있었어. 같이 다시 말해 보자.」","correct":true},{"t":"「하하, 또 틀렸다!」","mis":"K2-1-u2-X09"},{"t":"「너 때문에 졌잖아. 이제 내가 다 할게.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#23','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#24','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C3',4,'essay','teacher','「사과는 빨개」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「사과는 빨개」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 사과는 빨개 → 빨가면 딸기 → 딸기는 달아 → 달면 사탕","scoring_points":["「사과는 빨개」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#25','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C9',4,'essay','teacher','「훨훨 날아간 연」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「훨훨 날아간 연」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「연은 빙글빙글 돌며 멀리 날아갔어요.」 — 연이 춤추듯 날아가는 모습이 떠올라 재미있었지만 조금 아쉬웠어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["바람이 쌩쌩 부는 날, 민지는 아빠와 연을 날렸어요.","연은 하늘 높이 훨훨 날아올랐어요.","그런데 갑자기 연줄이 툭 끊어졌어요.","연은 빙글빙글 돌며 멀리 날아갔어요.","민지는 「안녕, 내 연아!」 하고 손을 흔들었어요."],"title":"훨훨 날아간 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#1','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C1',1,'mc','auto','꼭 필요할 때 내려 반가운 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"꼭 필요할 때 내려 반가운 비를 무엇이라고 하나요?","options":[{"t":"단비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"이슬비","mis":"K2-1-u2-X01"}],"explanation":["꼭 필요할 때 내리는 비는 단비예요.","비가 내리는 모습에 따라 이름이 달라요.","이름에는 그렇게 부르는 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#2','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C2',1,'mc','auto','「나」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「나」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"나무","correct":true},{"t":"바나나","mis":"K2-1-u2-X02"},{"t":"너구리","mis":"K2-1-u2-X03"}],"explanation":["나무는 첫 글자가 「나」예요.","다른 낱말은 「나」가 끝에 있거나 다른 글자로 시작해요.","맨 앞 글자를 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#3','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#4','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":4,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"사랑해친구","correct":true},{"t":"사랑해","mis":"K2-1-u2-X06"},{"t":"정말정말사랑해","mis":"K2-1-u2-X06"}],"explanation":["사·랑·해·친·구, 다섯 글자예요.","다른 말은 다섯 글자보다 적거나 많아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#5','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 모습은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 모습은 어느 것인가요?","options":[{"t":"친구가 막히면 기다려 줘요","correct":true},{"t":"「빨리 해!」 하고 재촉하며 끼어들어요","mis":"K2-1-u2-X08"},{"t":"「그것도 못 해?」 하고 놀려요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지키고 함께 즐겨야 말놀이가 재미있어요.","끼어들거나 놀리면 놀이가 즐겁지 않아요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#6','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C6',1,'mc','auto','놀이터에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"놀이터에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"미끄럼틀","correct":true},{"t":"도마","mis":"K2-1-u2-X10"},{"t":"분필","mis":"K2-1-u2-X10"}],"explanation":["미끄럼틀은 놀이터에서 볼 수 있어요.","다른 낱말은 다른 장소에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#7','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C8',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":7,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"멍멍","correct":true},{"t":"강아지","mis":"K2-1-u2-X15"},{"t":"짖다","mis":"K2-1-u2-X15"}],"explanation":["「멍멍」은 강아지 소리를 흉내 낸 말이에요.","다른 두 낱말은 흉내 내는 말이 아니에요.","따라 했을 때 소리나 모습이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#8','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C10',1,'mc','auto','책갈피에 적기 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책갈피에 적기 좋은 것은 어느 것인가요?","options":[{"t":"마음에 드는 문장 한 줄","correct":true},{"t":"책 한 쪽 전체","mis":"K2-1-u2-X17"},{"t":"책값과 날짜","mis":"K2-1-u2-X17"}],"explanation":["책갈피에는 짧은 문장 한 줄이 어울려요.","다른 것은 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#9','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C11',2,'ox','auto','「음식 파는 곳」은 특징을 잘 살린 재미있는 이름이에요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":2,"kind":"ox","stem":"「음식 파는 곳」은 특징을 잘 살린 재미있는 이름이에요.","answer":"X","reason_options":[{"t":"어떤 음식인지 특징이 드러나지 않으니까","correct":true},{"t":"음식을 판다고 말했으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「음식 파는 곳」은 무엇을 파는지 알 수 없어요.","맛이나 모양이 드러나야 해요.","특징과 흉내 내는 말을 살려 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#10','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「바닷가에 가면 조개도 있고, 게도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":10,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「바닷가에 가면 조개도 있고, 게도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「바닷가에 가면 조개도 있고, 게도 있고, 모래도 있고」","correct":true},{"t":"「바닷가에 가면 모래도 있고」","mis":"K2-1-u2-X07"},{"t":"「바닷가에 가면 게도 있고, 조개도 있고, 모래도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#11','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C7',2,'mc','auto','친구가 「아기 펭귄은 헤엄을 못 쳤어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":11,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「아기 펭귄은 헤엄을 못 쳤어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「그래서 엄마 펭귄에게 헤엄을 배웠어요.」","correct":true},{"t":"「사과는 빨개요.」","mis":"K2-1-u2-X13"},{"t":"「펭귄 바다 물.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 인물 이야기를 이어 가요.","관계없는 문장이나 낱말만 늘어놓은 말은 이야기를 끊어요.","앞 문장의 인물을 넣어 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#12','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「나 · 바 · 나」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":12,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「나 · 바 · 나」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"바나나","correct":true},{"t":"나바나","mis":"K2-1-u2-X11"},{"t":"바나","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「바나나」가 돼요.","차례를 잘못 놓거나 글자를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#13','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 할머니 댁 마당에 병아리가 몇 마리 있나요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":13,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 할머니 댁 마당에 병아리가 몇 마리 있나요?","options":[{"t":"다섯 마리","correct":true},{"t":"세 마리","mis":"K2-1-u2-X14"},{"t":"열 마리","mis":"K2-1-u2-X14"}],"explanation":["글에 「병아리 다섯 마리가 있어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 것이에요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["할머니 댁 마당에 병아리 다섯 마리가 있어요.","병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.","아린이가 모이를 뿌리자 병아리들이 콕콕 쪼아 먹었어요.","아린이는 병아리들이 귀여워 방긋 웃었어요."],"title":"졸졸 병아리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#14','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C9',2,'ox','auto','친구가 나와 다른 느낌을 말하면 틀렸다고 알려 줘요.',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":14,"concept":"K2-1-u2-C9","difficulty":2,"kind":"ox","stem":"친구가 나와 다른 느낌을 말하면 틀렸다고 알려 줘요.","answer":"X","reason_options":[{"t":"느낌은 사람마다 다를 수 있으니까","correct":true},{"t":"내 느낌이 정답이니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["다른 느낌은 틀린 것이 아니에요.","「그렇게 느낄 수도 있구나.」 하고 들어요.","까닭을 들어 느낌을 말하고 친구 느낌도 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#15','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":15,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"바다 · 바지 · 바람","correct":true},{"t":"바지 · 지구 · 구두","mis":"K2-1-u2-X02"},{"t":"바다 · 버섯 · 보리","mis":"K2-1-u2-X03"}],"explanation":["바다 · 바지 · 바람은 모두 첫 글자가 같아요.","끝 글자를 이은 것이나 자음자만 같은 것은 첫 글자가 같은 것이 아니에요.","맨 앞 글자를 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#16','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C11',2,'mc','auto','찌개 가게에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":16,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"찌개 가게에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"보글보글 찌개","correct":true},{"t":"찌개 3호","mis":"K2-1-u2-X18"},{"t":"음식점","mis":"K2-1-u2-X18"}],"explanation":["「보글보글 찌개」는 찌개 끓는 소리가 떠올라요.","다른 이름은 무엇을 파는지나 재미가 드러나지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#17','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C3',3,'error','auto','「기차는 길어, 길면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],false,'{"seq":17,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「기차는 길어, 길면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"민호 — 「길면 동전」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"지안 — 「길면 뱀」","mis":"K2-1-u2-X19"},{"t":"소율 — 「길면 기린 목」","mis":"K2-1-u2-X19"}],"explanation":["동전은 길지 않아요.","다른 두 친구는 앞말에서 떠오르는 것을 이었어요.","바로 앞말에서 떠오르는 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#18','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":18,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"연필을 깎아 필통에 넣었어요.","correct":true},{"t":"꼬마 여우는 친구를 사귀고 싶었어요.","mis":"K2-1-u2-X19"},{"t":"꼬마 여우는 다람쥐에게 「같이 놀자!」 하고 말했어요.","mis":"K2-1-u2-X19"}],"explanation":["「연필을 깎아 필통에 넣었어요」는 이야기와 관계가 없어요.","다른 문장은 모두 같은 인물의 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["숲속에 꼬마 여우가 살았어요.","꼬마 여우는 친구를 사귀고 싶었어요.","연필을 깎아 필통에 넣었어요.","꼬마 여우는 다람쥐에게 「같이 놀자!」 하고 말했어요."],"title":"꼬마 여우 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#19','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":19,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"쌩쌩","correct":true},{"t":"훨훨","mis":"K2-1-u2-X15"},{"t":"빙글빙글","mis":"K2-1-u2-X15"}],"explanation":["「쌩쌩」은 바람 소리예요. 「훨훨」·「빙글빙글」은 모양이에요.","흉내 내는 말이 무엇의 소리인지, 모양인지 따라 해 보며 가려요.","흉내 내는 말은 글을 생생하게 만들어요."],"asset":{"type":"passage","lines":["바람이 쌩쌩 부는 날, 민지는 아빠와 연을 날렸어요.","연은 하늘 높이 훨훨 날아올랐어요.","그런데 갑자기 연줄이 툭 끊어졌어요.","연은 빙글빙글 돌며 멀리 날아갔어요.","민지는 「안녕, 내 연아!」 하고 손을 흔들었어요."],"title":"훨훨 날아간 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#20','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":20,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"태민 — 「재밌어요.」라고만 말하고 들어갔어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"은솔 — 제목, 좋아하는 문장, 까닭을 차례로 말했어요","mis":"K2-1-u2-X19"},{"t":"하람 — 친구들을 보며 좋아하는 문장을 또박또박 읽었어요","mis":"K2-1-u2-X19"}],"explanation":["태민이는 제목도 문장도 까닭도 말하지 않았어요.","다른 두 친구는 알맞게 소개했어요.","제목 → 좋아하는 문장 → 까닭을 담아 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#21','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 아린이의 마음을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 아린이의 마음을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"병아리가 귀여워 기뻐요","correct":true},{"t":"병아리가 무서워요","mis":"K2-1-u2-X16"},{"t":"병아리가 미워요","mis":"K2-1-u2-X16"}],"explanation":["아린이는 병아리가 귀여워 방긋 웃었어요.","일과 반대되거나 글에 없는 마음은 알맞지 않아요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["할머니 댁 마당에 병아리 다섯 마리가 있어요.","병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.","아린이가 모이를 뿌리자 병아리들이 콕콕 쪼아 먹었어요.","아린이는 병아리들이 귀여워 방긋 웃었어요."],"title":"졸졸 병아리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#22','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C5',3,'mc','auto','다섯 글자 말놀이에서 친구가 여섯 글자로 말했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":22,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"다섯 글자 말놀이에서 친구가 여섯 글자로 말했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「한 글자만 빼면 딱 맞겠다!」","correct":true},{"t":"「글자도 못 세냐?」","mis":"K2-1-u2-X09"},{"t":"「이번엔 내가 대신 말할게. 넌 듣기만 해.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#23','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#24','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C3',4,'essay','teacher','「눈은 하얘」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「눈은 하얘」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 눈은 하얘 → 하야면 우유 → 우유는 고소해 → 고소하면 참깨","scoring_points":["「눈은 하얘」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#25','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C9',4,'essay','teacher','「졸졸 병아리」를 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「졸졸 병아리」를 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.」 — 동생이 나를 졸졸 따라다니는 모습이 떠올라 웃음이 났어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["할머니 댁 마당에 병아리 다섯 마리가 있어요.","병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.","아린이가 모이를 뿌리자 병아리들이 콕콕 쪼아 먹었어요.","아린이는 병아리들이 귀여워 방긋 웃었어요."],"title":"졸졸 병아리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#1','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C1',1,'mc','auto','이슬처럼 아주 가늘게 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"이슬처럼 아주 가늘게 내리는 비를 무엇이라고 하나요?","options":[{"t":"이슬비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"단비","mis":"K2-1-u2-X01"}],"explanation":["이슬처럼 아주 가늘게 내리는 비는 이슬비예요.","비가 내리는 모습에 따라 이름이 달라요.","이름에는 그렇게 부르는 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#2','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C2',1,'mc','auto','「고」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「고」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"고양이","correct":true},{"t":"사고","mis":"K2-1-u2-X02"},{"t":"구름","mis":"K2-1-u2-X03"}],"explanation":["고양이는 첫 글자가 「고」예요.","다른 낱말은 「고」가 끝에 있거나 다른 글자로 시작해요.","맨 앞 글자를 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#3','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#4','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":4,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"힘내우리반","correct":true},{"t":"힘내","mis":"K2-1-u2-X06"},{"t":"우리반모두힘내자","mis":"K2-1-u2-X06"}],"explanation":["힘·내·우·리·반, 다섯 글자예요.","다른 말은 다섯 글자보다 적거나 많아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#5','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 모습은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 모습은 어느 것인가요?","options":[{"t":"이기기보다 함께 즐겨요","correct":true},{"t":"내 차례가 아닌데 큰 소리로 말해요","mis":"K2-1-u2-X08"},{"t":"친구 말에 「틀렸지롱!」 하고 놀려요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지키고 함께 즐겨야 말놀이가 재미있어요.","끼어들거나 놀리면 놀이가 즐겁지 않아요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#6','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C6',1,'mc','auto','공원에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"공원에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"비둘기","correct":true},{"t":"칫솔","mis":"K2-1-u2-X10"},{"t":"책상","mis":"K2-1-u2-X10"}],"explanation":["비둘기는 공원에서 볼 수 있어요.","다른 낱말은 다른 장소에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#7','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C8',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":7,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"엉금엉금","correct":true},{"t":"거북이","mis":"K2-1-u2-X15"},{"t":"느리다","mis":"K2-1-u2-X15"}],"explanation":["「엉금엉금」은 거북이가 기는 모양을 흉내 낸 말이에요.","다른 두 낱말은 흉내 내는 말이 아니에요.","따라 했을 때 소리나 모습이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#8','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C10',1,'mc','auto','좋아하는 문장을 소개한 뒤 덧붙이면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"좋아하는 문장을 소개한 뒤 덧붙이면 좋은 것은 어느 것인가요?","options":[{"t":"그 문장을 좋아하는 까닭","correct":true},{"t":"책 표지의 색깔","mis":"K2-1-u2-X17"},{"t":"책을 읽은 시간","mis":"K2-1-u2-X17"}],"explanation":["까닭을 말하면 친구가 내 마음을 알 수 있어요.","다른 것은 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#9','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C11',2,'ox','auto','「매콤달콤 떡볶이」는 맛이 떠오르는 재미있는 이름이에요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":2,"kind":"ox","stem":"「매콤달콤 떡볶이」는 맛이 떠오르는 재미있는 이름이에요.","answer":"O","reason_options":[{"t":"떡볶이의 맛을 살렸으니까","correct":true},{"t":"글자가 많으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「매콤달콤」은 떡볶이 맛을 떠올리게 해요.","특징을 살리면 이름이 재미있어요.","특징과 흉내 내는 말을 살려 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#10','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「교실에 가면 칠판도 있고, 책상도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":10,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「교실에 가면 칠판도 있고, 책상도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「교실에 가면 칠판도 있고, 책상도 있고, 필통도 있고」","correct":true},{"t":"「교실에 가면 필통도 있고」","mis":"K2-1-u2-X07"},{"t":"「교실에 가면 책상도 있고, 필통도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#11','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C7',2,'mc','auto','친구가 「꼬마 토끼가 길을 잃었어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":11,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「꼬마 토끼가 길을 잃었어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「꼬마 토끼는 부엉이에게 길을 물었어요.」","correct":true},{"t":"「냄비에서 물이 끓어요.」","mis":"K2-1-u2-X13"},{"t":"「토끼 길 부엉이.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 인물 이야기를 이어 가요.","관계없는 문장이나 낱말만 늘어놓은 말은 이야기를 끊어요.","앞 문장의 인물을 넣어 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#12','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「기 · 행 · 비」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":12,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「기 · 행 · 비」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"비행기","correct":true},{"t":"행비기","mis":"K2-1-u2-X11"},{"t":"비기","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「비행기」가 돼요.","차례를 잘못 놓거나 글자를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#13','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 하준이는 어디에 갔나요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":13,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 하준이는 어디에 갔나요?","options":[{"t":"시냇가","correct":true},{"t":"바닷가","mis":"K2-1-u2-X14"},{"t":"수영장","mis":"K2-1-u2-X14"}],"explanation":["글에 「하준이는 시냇가에 갔어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 것이에요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["여름 방학에 하준이는 시냇가에 갔어요.","차가운 물에 발을 담그자 「앗, 차가워!」 소리가 절로 났어요.","작은 물고기들이 발가락 사이로 쏙쏙 지나갔어요.","하준이는 깔깔 웃으며 물을 찰박찰박 찼어요."],"title":"찰박찰박 시냇가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#14','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C9',2,'ox','auto','글을 읽고 떠오른 내 경험을 까닭으로 들어 느낌을 말하면 좋아요.',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":14,"concept":"K2-1-u2-C9","difficulty":2,"kind":"ox","stem":"글을 읽고 떠오른 내 경험을 까닭으로 들어 느낌을 말하면 좋아요.","answer":"O","reason_options":[{"t":"왜 그렇게 느꼈는지 친구가 알 수 있으니까","correct":true},{"t":"경험은 글과 관계없으니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["내 경험을 까닭으로 들면 느낌이 잘 전해져요.","「나도 ~한 적이 있어서」처럼 말해요.","까닭을 들어 느낌을 말하고 친구 느낌도 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#15','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":15,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"가방 · 가위 · 가지","correct":true},{"t":"가지 · 지도 · 도토리","mis":"K2-1-u2-X02"},{"t":"가방 · 거미 · 고추","mis":"K2-1-u2-X03"}],"explanation":["가방 · 가위 · 가지는 모두 첫 글자가 같아요.","끝 글자를 이은 것이나 자음자만 같은 것은 첫 글자가 같은 것이 아니에요.","맨 앞 글자를 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#16','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C11',2,'mc','auto','과일 가게에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":16,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"과일 가게에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"새콤달콤 과일","correct":true},{"t":"과일 4번","mis":"K2-1-u2-X18"},{"t":"물건 파는 곳","mis":"K2-1-u2-X18"}],"explanation":["「새콤달콤 과일」은 과일 맛이 떠올라요.","다른 이름은 무엇을 파는지나 재미가 드러나지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#17','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C3',3,'error','auto','「얼음은 차가워, 차가우면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],false,'{"seq":17,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「얼음은 차가워, 차가우면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"태민 — 「차가우면 난로」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"서윤 — 「차가우면 눈사람」","mis":"K2-1-u2-X19"},{"t":"시우 — 「차가우면 아이스크림」","mis":"K2-1-u2-X19"}],"explanation":["난로는 차갑지 않아요.","다른 두 친구는 앞말에서 떠오르는 것을 이었어요.","바로 앞말에서 떠오르는 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#18','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":18,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"운동장에서 축구 시합이 열렸어요.","correct":true},{"t":"처음에는 자꾸 떨어질 뻔했어요.","mis":"K2-1-u2-X19"},{"t":"드디어 아기 새가 하늘을 훨훨 날았어요.","mis":"K2-1-u2-X19"}],"explanation":["「운동장에서 축구 시합이 열렸어요」는 이야기와 관계가 없어요.","다른 문장은 모두 같은 인물의 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["아기 새가 둥지에서 날갯짓을 연습했어요.","처음에는 자꾸 떨어질 뻔했어요.","운동장에서 축구 시합이 열렸어요.","드디어 아기 새가 하늘을 훨훨 날았어요."],"title":"아기 새 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#19','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":19,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"삐악삐악","correct":true},{"t":"졸졸","mis":"K2-1-u2-X15"},{"t":"방긋","mis":"K2-1-u2-X15"}],"explanation":["「삐악삐악」은 병아리 소리예요. 「졸졸」·「방긋」은 모양이에요.","흉내 내는 말이 무엇의 소리인지, 모양인지 따라 해 보며 가려요.","흉내 내는 말은 글을 생생하게 만들어요."],"asset":{"type":"passage","lines":["할머니 댁 마당에 병아리 다섯 마리가 있어요.","병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.","아린이가 모이를 뿌리자 병아리들이 콕콕 쪼아 먹었어요.","아린이는 병아리들이 귀여워 방긋 웃었어요."],"title":"졸졸 병아리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#20','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":20,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"도담 — 「좋아하는 문장은 ‘나는 할 수 있어!’예요.」 하고 까닭 없이 들어갔어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"아린 — 「‘나는 할 수 있어!’를 읽으면 힘이 나서 좋아요.」","mis":"K2-1-u2-X19"},{"t":"지후 — 「제가 좋아하는 책은 『용감한 토끼』예요.」로 시작했어요","mis":"K2-1-u2-X19"}],"explanation":["도담이는 그 문장을 좋아하는 까닭을 말하지 않았어요.","다른 두 친구는 알맞게 소개했어요.","제목 → 좋아하는 문장 → 까닭을 담아 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#21','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 도윤이의 마음을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 도윤이의 마음을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"눈사람을 만들며 신나요","correct":true},{"t":"추워서 집에 가고 싶어요","mis":"K2-1-u2-X16"},{"t":"동생에게 화가 났어요","mis":"K2-1-u2-X16"}],"explanation":["찬 바람에도 두 볼이 따끈따끈할 만큼 신나게 놀았어요.","일과 반대되거나 글에 없는 마음은 알맞지 않아요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#22','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C5',3,'mc','auto','첫 글자 말놀이에서 친구가 한참 생각하고 있어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":22,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"첫 글자 말놀이에서 친구가 한참 생각하고 있어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「천천히 생각해. 기다릴게.」","correct":true},{"t":"「너무 느려! 거북이냐?」","mis":"K2-1-u2-X09"},{"t":"「시간 끝! 내 차례야.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#23','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#24','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C3',4,'essay','teacher','「기차는 길어」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「기차는 길어」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 기차는 길어 → 길면 뱀 → 뱀은 무서워 → 무서우면 호랑이","scoring_points":["「기차는 길어」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#25','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C9',4,'essay','teacher','「지글지글 부침개」를 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「지글지글 부침개」를 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「아빠, 빗소리랑 부침개 소리가 똑같아요!」 — 정말 그런지 다음에 비 오는 날 들어 보고 싶어졌어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["비 오는 저녁, 아빠가 부침개를 부치셨어요.","팬에서 지글지글 소리가 났어요.","서아는 바삭바삭한 끝부분을 호호 불어 먹었어요.","「아빠, 빗소리랑 부침개 소리가 똑같아요!」"],"title":"지글지글 부침개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C1','kor',2,1,'u3',1,'꾸며 주는 말 알기 — 「넓은 밭」·「활짝 웃다」처럼 뒤에 오는 말이 어떤지·어떻게 하는지 자세하게 해 주는 말을 알고 문장에서 찾기',ARRAY['2국04-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C2','kor',2,1,'u3',1,'꾸며 주는 말과 꾸미는 말 잇기 — 꾸며 주는 말이 문장에서 어느 말을 꾸미는지(넓은 → 옥수수밭, 활짝 → 웃으셨다) 찾아 잇기',ARRAY['2국04-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C3','kor',2,1,'u3',1,'꾸며 주는 말을 쓰면 좋은 점 — 생각이나 느낌을 더 자세하고 생생하게 나타낼 수 있고, 읽는 사람도 모습을 또렷하게 떠올리며 재미있게 읽음을 알기',ARRAY['2국03-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C4','kor',2,1,'u3',3,'대상에 어울리는 꾸며 주는 말 고르기 — 그림·사진의 대상을 살펴 색(노란·붉은)·모양(둥근·예쁜)·움직임(빠르게·힘차게)에 맞는 꾸며 주는 말 고르기',ARRAY['2국03-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C5','kor',2,1,'u3',3,'꾸며 주는 말을 넣어 문장 쓰기 — 꾸며 주는 말을 알맞은 자리에 넣어 끝까지 문장을 쓰고, 한 문장에 여러 개를 넣되 뜻이 어긋나지 않게 하기',ARRAY['2국03-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C6','kor',2,1,'u3',5,'꾸며 주는 말이 들어간 글 읽기 — 식물이 자라는 글에서 자라는 차례(씨앗 → 새싹 → 꽃 → 열매)와 모양을 나타내는 낱말(조롱조롱·올록볼록·무럭무럭)의 뜻을 알고 모습을 떠올리기',ARRAY['2국03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C7','kor',2,1,'u3',1,'일기의 뜻과 짜임 — 일기는 그날 겪은 일 가운데 기억하고 싶은 일을 골라 생각이나 느낌을 담아 쓰는 글이며, 날짜·요일·날씨 → 제목 → 겪은 일 → 생각이나 느낌 차례로 씀을 알기',ARRAY['2국03-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C8','kor',2,1,'u3',7,'겪은 일에서 글감 정하기 — 하루에 한 것·본 것·들은 것을 떠올리고, 그 가운데 마음이 움직인 인상 깊은 일 하나를 골라 일기 글감으로 정하기',ARRAY['2국03-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C9','kor',2,1,'u3',7,'일기 제목 붙이기 — 글감을 정한 뒤 무슨 일이 있었는지 한눈에 알 수 있게 내용을 잘 나타내는 제목 붙이기',ARRAY['2국03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C10','kor',2,1,'u3',9,'겪은 일과 생각·느낌을 자세하고 솔직하게 쓰기 — 언제·어디서·누구와 무슨 일이 있었는지 자세하게, 그때 든 생각이나 느낌은 솔직하게 쓰고, 다 쓴 일기를 스스로 점검해 고치기',ARRAY['2국03-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C11','kor',2,1,'u3',12,'여러 가지 일기·관찰하기 — 관찰 일기·요리 일기·그림 일기의 쓰는 내용을 알고, 관찰할 때 색·모양·냄새·촉감을 살펴 꾸며 주는 말로 나타내기',ARRAY['2국03-04']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C12','kor',2,1,'u3',14,'흉내 내는 말 — 빙글빙글(모양)·톡톡(소리)·보들보들(느낌)처럼 모양·소리·느낌을 흉내 내는 말을 알고, 흉내 내는 말도 뒤의 말을 생생하게 꾸며 줌을 알기',ARRAY['2국04-03']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X01','kor',2,'u3',ARRAY['K2-1-u3-C1']::text[],'꾸밈을 받는 이름 낱말(꽃·들판·강아지)을 꾸며 주는 말로 고른다','「어떤?」 「어떻게?」에 대답하는 말에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X02','kor',2,'u3',ARRAY['K2-1-u3-C2']::text[],'꾸며 주는 말이 꾸미는 말을 엉뚱하게 잇는다(넓은 → 웃었다, 활짝 → 밭)','꾸며 주는 말 바로 뒤의 말에 붙여 소리 내어 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X03','kor',2,'u3',ARRAY['K2-1-u3-C3','K2-1-u3-C5']::text[],'꾸며 주는 말이 없는 밋밋한 문장이 더 생생하다고 여기거나, 좋은 점을 「글이 길어져서」로만 안다','두 문장을 읽고 어느 쪽 그림이 더 또렷하게 떠오르는지 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X04','kor',2,'u3',ARRAY['K2-1-u3-C4','K2-1-u3-C11']::text[],'대상과 어울리지 않는 꾸며 주는 말을 붙인다(시끄러운 사과·네모난 강아지)','대상을 눈앞에 그리고 색·모양·움직임 가운데 무엇이 보이는지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X05','kor',2,'u3',ARRAY['K2-1-u3-C5']::text[],'꾸며 주는 말은 많을수록 좋다고 여겨 뜻이 어긋나거나 겹치는 말을 넣고, 한 문장에 하나만 넣을 수 있다고 여긴다','넣은 말이 모두 그 모습에 맞는지 하나씩 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X06','kor',2,'u3',ARRAY['K2-1-u3-C5']::text[],'꾸며 주는 말을 넣으며 문장을 끝맺지 않거나 낱말만 늘어놓는다(노란 우산.)','「누가 어찌한다.」 끝까지 말했는지 마침표 앞을 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X07','kor',2,'u3',ARRAY['K2-1-u3-C6','K2-1-u3-C10']::text[],'글에 없는 내용을 있다고 하거나 일어난 차례를 뒤바꾼다(꽃이 핀 뒤 새싹이 돋음)','글에서 그 문장을 찾아 손가락으로 짚고 앞뒤 차례 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X08','kor',2,'u3',ARRAY['K2-1-u3-C6','K2-1-u3-C12']::text[],'모양을 나타내는 낱말의 뜻을 서로 바꾼다(조롱조롱 ↔ 올록볼록, 무럭무럭 ↔ 시들시들)','낱말을 소리 내어 읽으며 손으로 그 모양을 흉내 내 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X09','kor',2,'u3',ARRAY['K2-1-u3-C7','K2-1-u3-C10']::text[],'일기를 하루에 한 일을 모두 적는 글이나 생각·느낌은 없어도 되는 글로 알고, 날짜·날씨·느낌을 빠뜨린다','날짜·날씨, 제목, 겪은 일, 느낌 — 네 손가락을 접으며 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X10','kor',2,'u3',ARRAY['K2-1-u3-C7']::text[],'일기 차례를 뒤바꾼다(제목을 맨 위에 두고 날짜를 맨 끝에, 느낌을 겪은 일보다 먼저)','「날짜·날씨 → 제목 → 겪은 일 → 느낌」 차례를 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X11','kor',2,'u3',ARRAY['K2-1-u3-C7','K2-1-u3-C11']::text[],'일기와 관계없는 것(전화번호·시간표·가격)을 일기에 꼭 들어갈 내용이나 살펴볼 점으로 고른다','「이것이 그날을 돌아보는 데 꼭 필요할까?」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X12','kor',2,'u3',ARRAY['K2-1-u3-C8']::text[],'물건·느낌을 나타내는 낱말(연필·즐거움)을 겪은 일로 여긴다','「내가 ~했다·봤다·들었다」로 말이 되는지 붙여 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X13','kor',2,'u3',ARRAY['K2-1-u3-C8']::text[],'인상 깊은 일 대신 날마다 똑같은 일이나 하루 일을 모두 글감으로 고른다','「오늘 가장 마음이 움직인 일 하나는?」 하고 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X14','kor',2,'u3',ARRAY['K2-1-u3-C9']::text[],'무슨 일이 있었는지 드러나지 않는 제목(오늘 날씨·그냥 하루·일기)을 고른다','제목만 듣고 무슨 일인지 떠오르는지 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X15','kor',2,'u3',ARRAY['K2-1-u3-C10']::text[],'한 일만 늘어놓고 생각·느낌을 빼거나, 겪은 일과 맞지 않는 느낌·남의 느낌을 쓴다','「그때 내 마음은 어땠지? 왜?」를 한 줄 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X16','kor',2,'u3',ARRAY['K2-1-u3-C10']::text[],'언제·어디서·누구와를 빠뜨려 무슨 일인지 자세하게 드러나지 않게 쓴다','「언제? 어디서? 누구와?」 세 물음에 답이 있는지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X17','kor',2,'u3',ARRAY['K2-1-u3-C11']::text[],'관찰할 수 없는 것(가격·만든 사람)을 관찰할 점으로 고르거나, 일기 종류와 쓰는 내용을 바꾸어 잇는다','눈·코·손으로 알 수 있는 것인지 먼저 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X18','kor',2,'u3',ARRAY['K2-1-u3-C12']::text[],'흉내 내는 말이 아닌 낱말(바람개비·돌다·예쁜)을 흉내 내는 말로 여기거나 모양·소리·느낌 흉내를 헷갈린다','따라 했을 때 모습·소리·느낌이 떠오르는지 소리 내어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X19','kor',2,'u3',ARRAY['K2-1-u3-C1','K2-1-u3-C2','K2-1-u3-C4','K2-1-u3-C5','K2-1-u3-C6','K2-1-u3-C7','K2-1-u3-C8','K2-1-u3-C9','K2-1-u3-C10','K2-1-u3-C11','K2-1-u3-C12']::text[],'묻는 말을 거꾸로 읽는다 — 아닌↔맞는, 어울리지 않는↔어울리는, 빠진↔들어간','물음의 「아닌·않는·빠진」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#1','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C1',1,'mc','auto','「넓은 운동장」에서 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X01']::text[],true,'{"seq":1,"concept":"K2-1-u3-C1","difficulty":1,"kind":"mc","stem":"「넓은 운동장」에서 꾸며 주는 말은 어느 것인가요?","options":[{"t":"넓은","correct":true},{"t":"운동장","mis":"K2-1-u3-X01"},{"t":"넓은 운동장","mis":"K2-1-u3-X01"}],"explanation":["「넓은」이 운동장이 어떤지 알려 줘요.","「운동장」은 꾸밈을 받는 말이에요.","「어떤 운동장?」에 대답하는 말을 찾아요."],"variant_rule":{"alt":[{"stem":"「예쁜 꽃」에서 꾸며 주는 말은 어느 것인가요?","options":[{"t":"예쁜","correct":true},{"t":"꽃","mis":"K2-1-u3-X01"},{"t":"예쁜 꽃","mis":"K2-1-u3-X01"}],"explanation":["「예쁜」이 꽃이 어떤지 알려 줘요.","「꽃」은 꾸밈을 받는 말이에요.","「어떤 꽃?」에 대답하는 말을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#2','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#3','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C7',1,'mc','auto','일기는 어떤 글인가요?',ARRAY['K2-1-u3-X09']::text[],true,'{"seq":3,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기는 어떤 글인가요?","options":[{"t":"그날 겪은 일 가운데 기억하고 싶은 일과 생각이나 느낌을 쓴 글","correct":true},{"t":"하루에 한 일을 모두 차례대로 적은 글","mis":"K2-1-u3-X09"},{"t":"내일 할 일을 미리 적어 두는 글","mis":"K2-1-u3-X09"}],"explanation":["일기는 겪은 일 가운데 기억하고 싶은 일을 골라 써요.","한 일을 모두 적거나 내일 할 일을 쓰는 글이 아니에요.","그 일에 대한 생각이나 느낌도 함께 써요."],"variant_rule":{"alt":[{"stem":"일기에 꼭 함께 쓰는 것은 어느 것인가요?","options":[{"t":"겪은 일에 대한 생각이나 느낌","correct":true},{"t":"친구의 전화번호","mis":"K2-1-u3-X11"},{"t":"내일 시간표","mis":"K2-1-u3-X11"}],"explanation":["일기에는 겪은 일과 그때의 생각이나 느낌을 써요.","전화번호나 시간표는 그날을 돌아보는 내용이 아니에요.","그래서 일기를 읽으면 그날 마음이 떠올라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#4','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C3',1,'ox','auto','「비가 내린다.」보다 「비가 주룩주룩 세차게 내린다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],true,'{"seq":4,"concept":"K2-1-u3-C3","difficulty":1,"kind":"ox","stem":"「비가 내린다.」보다 「비가 주룩주룩 세차게 내린다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 비 내리는 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「주룩주룩」·「세차게」가 비 내리는 모습을 또렷하게 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."],"variant_rule":{"alt":[{"stem":"「꽃이 피었다.」가 「예쁜 꽃이 활짝 피었다.」보다 더 생생해요.","answer":"X","reason_options":[{"t":"꾸며 주는 말이 있는 쪽이 모습을 더 잘 그려 주니까","correct":true},{"t":"짧은 문장이 언제나 더 좋으니까","mis":"K2-1-u3-X03"}],"explanation":["「예쁜」·「활짝」이 꽃의 모습을 보여 줘요.","꾸며 주는 말이 없으면 어떤 꽃인지 알 수 없어요.","그래서 꾸며 주는 말이 있는 쪽이 더 생생해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#5','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C2',2,'match','auto','꾸며 주는 말과 꾸밈을 받는 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C2","difficulty":2,"kind":"match","stem":"꾸며 주는 말과 꾸밈을 받는 말을 알맞게 이어 보세요.","pairs":[{"l":"넓은","r":"옥수수밭"},{"l":"활짝","r":"웃으셨다"},{"l":"예쁜","r":"꽃"}],"mis":"K2-1-u3-X02","explanation":["「넓은」은 옥수수밭이 어떤지 꾸며요.","「활짝」은 어떻게 웃으셨는지 꾸며요.","「예쁜」은 꽃이 어떤지 꾸며요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 꾸며 주는 말과 꾸밈을 받는 말을 알맞게 이어 보세요.","pairs":[{"l":"빠르게","r":"달린다"},{"l":"커다란","r":"코끼리"},{"l":"맛있게","r":"먹었다"}],"explanation":["「빠르게」는 어떻게 달리는지 꾸며요.","「커다란」은 코끼리가 어떤지 꾸며요.","「맛있게」는 어떻게 먹었는지 꾸며요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#6','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C2',2,'mc','auto','「나는 맛있게 딸기를 먹었다.」에서 「맛있게」가 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],true,'{"seq":6,"concept":"K2-1-u3-C2","difficulty":2,"kind":"mc","stem":"「나는 맛있게 딸기를 먹었다.」에서 「맛있게」가 꾸며 주는 말은 어느 것인가요?","options":[{"t":"먹었다","correct":true},{"t":"나는","mis":"K2-1-u3-X02"},{"t":"딸기를","mis":"K2-1-u3-X02"}],"explanation":["「맛있게」는 어떻게 먹었는지 알려 줘요.","「맛있게 나는」, 「맛있게 딸기」는 어색해요.","꾸며 주는 말을 붙여 읽어 보면 짝이 보여요."],"variant_rule":{"alt":[{"stem":"「동생이 큰 소리로 노래를 불렀다.」에서 「큰」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"소리","correct":true},{"t":"동생이","mis":"K2-1-u3-X02"},{"t":"불렀다","mis":"K2-1-u3-X02"}],"explanation":["「큰」은 소리가 어떤지 알려 줘요.","「큰 동생」, 「큰 불렀다」가 아니라 「큰 소리」예요.","바로 뒤의 말에 붙여 읽어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#7','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C1',2,'sa','auto','「하얀 구름이 둥실둥실 떠간다.」에서 「구름」을 꾸며 주는 말을 찾아 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u3-C1","difficulty":2,"kind":"sa","stem":"「하얀 구름이 둥실둥실 떠간다.」에서 「구름」을 꾸며 주는 말을 찾아 써 보세요.","answer":["하얀"],"explanation":["「하얀」이 구름이 어떤지 알려 줘요.","「둥실둥실」은 어떻게 떠가는지 꾸며요.","무엇을 꾸미는지 바로 뒤의 말을 봐요."],"variant_rule":{"alt":[{"stem":"「작은 새가 높이 날아간다.」에서 「새」를 꾸며 주는 말을 찾아 써 보세요.","answer":["작은"],"explanation":["「작은」이 새가 어떤지 알려 줘요.","「높이」는 어떻게 날아가는지 꾸며요.","무엇을 꾸미는지 바로 뒤의 말을 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#8','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C3',2,'mc','auto','꾸며 주는 말을 쓰면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u3-X03']::text[],true,'{"seq":8,"concept":"K2-1-u3-C3","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 쓰면 좋은 점은 어느 것인가요?","options":[{"t":"생각이나 느낌을 더 자세하고 생생하게 나타낼 수 있어요","correct":true},{"t":"글자 수가 많아져 공책이 금방 채워져요","mis":"K2-1-u3-X03"},{"t":"어려운 말을 써서 멋있어 보여요","mis":"K2-1-u3-X03"}],"explanation":["꾸며 주는 말은 모습과 느낌을 자세하게 보여 줘요.","길어지거나 어려워 보이는 것이 좋은 점은 아니에요.","읽는 사람도 더 재미있게 느껴요."],"variant_rule":{"alt":[{"stem":"꾸며 주는 말을 넣은 글을 읽으면 어떤 점이 좋을까요?","options":[{"t":"그 모습이 눈앞에 그려지듯 떠올라요","correct":true},{"t":"읽는 시간이 오래 걸려요","mis":"K2-1-u3-X03"},{"t":"무슨 뜻인지 알 수 없어져요","mis":"K2-1-u3-X03"}],"explanation":["꾸며 주는 말이 있으면 모습이 또렷해져요.","읽는 시간이 늘어나는 것이 좋은 점은 아니에요.","그래서 글이 더 재미있게 느껴져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#9','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C7',2,'ox','auto','일기에는 그날 있었던 일을 하나도 빠짐없이 모두 써야 해요.',ARRAY['K2-1-u3-X09']::text[],true,'{"seq":9,"concept":"K2-1-u3-C7","difficulty":2,"kind":"ox","stem":"일기에는 그날 있었던 일을 하나도 빠짐없이 모두 써야 해요.","answer":"X","reason_options":[{"t":"기억하고 싶은 일을 골라 쓰는 글이니까","correct":true},{"t":"일어난 일은 모두 중요하니까","mis":"K2-1-u3-X09"}],"mis":"K2-1-u3-X09","explanation":["일기는 하루 가운데 기억하고 싶은 일을 골라 써요.","모두 쓰면 무엇이 마음에 남았는지 드러나지 않아요.","고른 일에 생각이나 느낌을 담아요."],"variant_rule":{"alt":[{"stem":"일기에는 겪은 일에 대한 나의 생각이나 느낌을 써요.","answer":"O","reason_options":[{"t":"일기는 겪은 일과 생각·느낌을 담는 글이니까","correct":true},{"t":"생각이나 느낌은 없어도 되니까","mis":"K2-1-u3-X09"}],"explanation":["일기에는 겪은 일과 생각이나 느낌을 함께 써요.","느낌이 빠지면 그날의 내 마음이 남지 않아요.","그래서 일기를 다시 읽으면 그날이 떠올라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#10','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C1',3,'error','auto','「활짝 핀 예쁜 꽃이 넓은 들판에 가득해요.」에서 꾸며 주는 말을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K2-1-u3-X01','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C1","difficulty":3,"kind":"error","stem":"「활짝 핀 예쁜 꽃이 넓은 들판에 가득해요.」에서 꾸며 주는 말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"하린 — 「들판」","correct":true,"mis_target":"K2-1-u3-X01"},{"t":"도윤 — 「활짝」","mis":"K2-1-u3-X19"},{"t":"서아 — 「넓은」","mis":"K2-1-u3-X19"}],"explanation":["「들판」은 꾸밈을 받는 말이에요.","「활짝」·「예쁜」·「넓은」이 꾸며 주는 말이에요.","도윤이와 서아는 바르게 찾았어요."],"variant_rule":{"alt":[{"stem":"「귀여운 강아지가 푸른 잔디밭을 신나게 뛰어요.」에서 꾸며 주는 말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"민호 — 「강아지」","correct":true,"mis_target":"K2-1-u3-X01"},{"t":"지안 — 「푸른」","mis":"K2-1-u3-X19"},{"t":"예린 — 「신나게」","mis":"K2-1-u3-X19"}],"explanation":["「강아지」는 꾸밈을 받는 말이에요.","「귀여운」·「푸른」·「신나게」가 꾸며 주는 말이에요.","지안이와 예린이는 바르게 찾았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#1','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C1',2,'mc','auto','다음 문장에서 꾸며 주는 말만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#2','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C7',2,'mc','auto','일기에 들어가는 것을 바르게 모은 것은 어느 것인가요?',ARRAY['K2-1-u3-X09','K2-1-u3-X11']::text[],false,'{"seq":2,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기에 들어가는 것을 바르게 모은 것은 어느 것인가요?","options":[{"t":"날짜와 날씨 · 제목 · 겪은 일 · 생각이나 느낌","correct":true},{"t":"날짜와 날씨 · 제목 · 겪은 일","mis":"K2-1-u3-X09"},{"t":"제목 · 겪은 일 · 친구 전화번호","mis":"K2-1-u3-X11"}],"explanation":["일기에는 날짜와 날씨, 제목, 겪은 일, 생각이나 느낌이 들어가요.","생각이나 느낌이 빠지면 일기가 아쉬워요.","전화번호는 일기 내용이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#3','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C2',3,'mc','auto','「키 큰 해바라기가 노랗게 활짝 피었다.」에서 「노랗게」가 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":3,"concept":"K2-1-u3-C2","difficulty":3,"kind":"mc","stem":"「키 큰 해바라기가 노랗게 활짝 피었다.」에서 「노랗게」가 꾸며 주는 말은 어느 것인가요?","options":[{"t":"피었다","correct":true},{"t":"해바라기가","mis":"K2-1-u3-X02"},{"t":"활짝","mis":"K2-1-u3-X02"}],"explanation":["「노랗게」는 어떻게 피었는지 알려 줘요.","「노랗게 해바라기」는 어색해요.","꾸며 주는 말을 붙여 읽어 보면 짝이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#4','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C2',3,'error','auto','「귀여운 동생이 새 신발을 신고 깡충깡충 뛰었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":4,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「귀여운 동생이 새 신발을 신고 깡충깡충 뛰었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"시우 — 「귀여운 → 신발」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"다은 — 「새 → 신발」","mis":"K2-1-u3-X19"},{"t":"로아 — 「깡충깡충 → 뛰었다」","mis":"K2-1-u3-X19"}],"explanation":["「귀여운」은 동생을 꾸며요.","「새」는 신발을, 「깡충깡충」은 뛰었다를 꾸며요.","다은이와 로아는 바르게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#5','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C3',3,'mc','auto','두 문장 가운데 그날 모습이 더 잘 떠오르는 문장과 그 까닭을 바르게 말한 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#6','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C1',3,'ox','auto','「코끼리」와 「커다란 하얀 코끼리」를 견주면, 「커다란」과 「하얀」은 모두 코끼리를 꾸며 주는 말이에요.',ARRAY['K2-1-u3-X01']::text[],false,'{"seq":6,"concept":"K2-1-u3-C1","difficulty":3,"kind":"ox","stem":"「코끼리」와 「커다란 하얀 코끼리」를 견주면, 「커다란」과 「하얀」은 모두 코끼리를 꾸며 주는 말이에요.","answer":"O","reason_options":[{"t":"두 말 모두 코끼리가 어떤지 알려 주니까","correct":true},{"t":"「코끼리」만 꾸며 주는 말이니까","mis":"K2-1-u3-X01"}],"mis":"K2-1-u3-X01","explanation":["「커다란」은 크기를, 「하얀」은 색을 알려 줘요.","두 말이 모두 코끼리를 꾸며요.","꾸며 주는 말은 여러 개 붙을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#7','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C7',3,'mc','auto','친구들이 일기에 대해 말했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u3-X13','K2-1-u3-X09']::text[],false,'{"seq":7,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"친구들이 일기에 대해 말했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"「작은 일이라도 마음이 움직였다면 일기로 쓸 수 있어.」","correct":true},{"t":"「특별한 여행을 간 날에만 일기를 쓸 수 있어.」","mis":"K2-1-u3-X13"},{"t":"「느낌은 빼고 한 일만 쓰면 돼.」","mis":"K2-1-u3-X09"}],"explanation":["작은 일이라도 기억하고 싶은 일이면 좋은 글감이에요.","특별한 날만 쓰는 글이 아니에요.","생각이나 느낌도 꼭 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#8','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C3',4,'mc','auto','준우가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#9','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C1',4,'essay','teacher','「강아지가 달린다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말에 밑줄을 그어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C1","difficulty":4,"kind":"essay","stem":"「강아지가 달린다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말에 밑줄을 그어 보세요.","answer_guide":{"answer":"예: 귀여운 강아지가 빠르게 달린다. (밑줄: 귀여운, 빠르게)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 강아지나 달리는 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울리는 말.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#10','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C7',4,'essay','teacher','일기가 어떤 글인지 쓰고, 일기에 꼭 들어가야 할 것을 두 가지 이상 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C7","difficulty":4,"kind":"essay","stem":"일기가 어떤 글인지 쓰고, 일기에 꼭 들어가야 할 것을 두 가지 이상 써 보세요.","answer_guide":{"answer":"예: 일기는 그날 겪은 일 가운데 기억하고 싶은 일을 골라 생각이나 느낌을 쓴 글이에요. 날짜와 날씨, 제목, 겪은 일, 생각이나 느낌이 들어가요.","scoring_points":["일기가 겪은 일 가운데 고른 일을 쓰는 글임을 썼는가","생각이나 느낌을 담는다는 것을 썼는가","일기에 들어갈 것을 두 가지 이상 썼는가"]},"explanation":["일기의 뜻.","생각이나 느낌.","들어갈 것 두 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#1','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',1,'mc','auto','사과 그림을 보고 꾸며 주는 말을 넣으려고 해요. 사과에 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],true,'{"seq":1,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"사과 그림을 보고 꾸며 주는 말을 넣으려고 해요. 사과에 어울리는 말은 어느 것인가요?","options":[{"t":"붉은","correct":true},{"t":"시끄러운","mis":"K2-1-u3-X04"},{"t":"졸린","mis":"K2-1-u3-X04"}],"explanation":["사과의 색을 보면 「붉은」이 어울려요.","사과는 시끄럽거나 졸리지 않아요.","대상의 색·모양을 살펴 어울리는 말을 골라요."],"asset":{"type":"scene","icon":"🍎"},"variant_rule":{"alt":[{"stem":"바나나 그림을 보고 꾸며 주는 말을 넣으려고 해요. 바나나에 어울리는 말은 어느 것인가요?","options":[{"t":"노란","correct":true},{"t":"파란","mis":"K2-1-u3-X04"},{"t":"네모난","mis":"K2-1-u3-X04"}],"explanation":["바나나의 색을 보면 「노란」이 어울려요.","바나나는 파랗거나 네모나지 않아요.","대상을 잘 살펴 어울리는 말을 골라요."],"asset":{"type":"scene","icon":"🍌"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#2','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',1,'mc','auto','「(     ) 우산을 쓴다.」에서 우산의 색을 나타내는 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],true,'{"seq":2,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"「(     ) 우산을 쓴다.」에서 우산의 색을 나타내는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"노란","correct":true},{"t":"예쁜","mis":"K2-1-u3-X04"},{"t":"빠르게","mis":"K2-1-u3-X04"}],"explanation":["「노란」은 우산의 색을 나타내요.","「예쁜」은 모양, 「빠르게」는 움직임을 나타내요.","무엇에 초점을 두는지에 따라 고르는 말이 달라요."],"variant_rule":{"alt":[{"stem":"「(     ) 공이 굴러간다.」에서 공의 모양을 나타내는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"둥근","correct":true},{"t":"빨간","mis":"K2-1-u3-X04"},{"t":"천천히","mis":"K2-1-u3-X04"}],"explanation":["「둥근」은 공의 모양을 나타내요.","「빨간」은 색, 「천천히」는 움직임을 나타내요.","무엇에 초점을 두는지에 따라 고르는 말이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#3','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',1,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X03']::text[],true,'{"seq":3,"concept":"K2-1-u3-C5","difficulty":1,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"커다란 배가 빠르게 나아간다.","correct":true},{"t":"커다란 배.","mis":"K2-1-u3-X06"},{"t":"배가 나아간다.","mis":"K2-1-u3-X03"}],"explanation":["「커다란」·「빠르게」를 넣어 끝까지 쓴 문장이에요.","「커다란 배.」는 무엇을 하는지 끝맺지 않았어요.","「배가 나아간다.」에는 꾸며 주는 말이 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"예쁜 나비가 훨훨 날아간다.","correct":true},{"t":"예쁜 나비.","mis":"K2-1-u3-X06"},{"t":"나비가 날아간다.","mis":"K2-1-u3-X03"}],"explanation":["「예쁜」·「훨훨」을 넣어 끝까지 쓴 문장이에요.","「예쁜 나비.」는 무엇을 하는지 끝맺지 않았어요.","「나비가 날아간다.」에는 꾸며 주는 말이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#4','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',1,'ox','auto','꾸며 주는 말은 한 문장에 여러 개 넣을 수 있어요.',ARRAY['K2-1-u3-X05']::text[],true,'{"seq":4,"concept":"K2-1-u3-C5","difficulty":1,"kind":"ox","stem":"꾸며 주는 말은 한 문장에 여러 개 넣을 수 있어요.","answer":"O","reason_options":[{"t":"「멋있는 말이 힘차게 달려온다.」처럼 넣을 수 있으니까","correct":true},{"t":"한 문장에는 하나만 넣어야 하니까","mis":"K2-1-u3-X05"}],"mis":"K2-1-u3-X05","explanation":["「멋있는」은 말을, 「힘차게」는 달려온다를 꾸며요.","한 문장에 꾸며 주는 말이 여러 개 들어갈 수 있어요.","어울리게 넣는 것이 중요해요."],"variant_rule":{"alt":[{"stem":"꾸며 주는 말은 한 문장에 하나만 넣어야 해요.","answer":"X","reason_options":[{"t":"어울리면 여러 개를 넣어도 되니까","correct":true},{"t":"두 개를 넣으면 틀린 문장이니까","mis":"K2-1-u3-X05"}],"explanation":["「두 명의 아이가 종이비행기를 힘껏 멀리 날린다.」처럼 여러 개를 넣을 수 있어요.","「힘껏」·「멀리」가 함께 날리는 모습을 꾸며요.","어울리게 넣으면 더 생생해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#5','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',2,'match','auto','모습과 어울리는 꾸며 주는 말을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C4","difficulty":2,"kind":"match","stem":"모습과 어울리는 꾸며 주는 말을 이어 보세요.","pairs":[{"l":"달리는 말","r":"힘차게"},{"l":"치는 파도","r":"거센"},{"l":"피는 꽃","r":"활짝"}],"mis":"K2-1-u3-X04","explanation":["말이 달리는 모습에는 「힘차게」가 어울려요.","파도에는 「거센」이 어울려요.","꽃이 피는 모습에는 「활짝」이 어울려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모습과 어울리는 꾸며 주는 말을 이어 보세요.","pairs":[{"l":"떠가는 구름","r":"둥실둥실"},{"l":"내리는 눈","r":"펑펑"},{"l":"빛나는 별","r":"반짝반짝"}],"explanation":["구름이 떠가는 모습에는 「둥실둥실」이 어울려요.","눈이 많이 내리는 모습에는 「펑펑」이 어울려요.","별이 빛나는 모습에는 「반짝반짝」이 어울려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#6','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',2,'blank','auto','달리는 강아지를 설명하는 문장이에요. 빈칸에 들어갈 말로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#7','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',2,'sa','auto','「(     ) 사과를 먹었다.」 빈칸에 사과의 모양을 나타내는 꾸며 주는 말을 한 낱말로 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u3-C5","difficulty":2,"kind":"sa","stem":"「(     ) 사과를 먹었다.」 빈칸에 사과의 모양을 나타내는 꾸며 주는 말을 한 낱말로 써 보세요.","answer":["둥근","동그란","둥그런","동글동글한"],"explanation":["사과의 모양은 「둥근」, 「동그란」 같은 말로 나타내요.","「붉은」은 색을 나타내는 말이에요.","모양을 살펴 어울리는 말을 넣어요."],"variant_rule":{"alt":[{"stem":"「(     ) 하늘을 보았다.」 빈칸에 하늘의 색을 나타내는 꾸며 주는 말을 한 낱말로 써 보세요.","answer":["파란","푸른","새파란","파아란"],"explanation":["하늘의 색은 「파란」, 「푸른」 같은 말로 나타내요.","색에 초점을 두고 떠올려요.","어울리는 꾸며 주는 말을 넣으면 문장이 생생해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#8','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',2,'mc','auto','「두 명의 아이가 종이비행기를 날린다.」에 꾸며 주는 말을 넣어 더 생생하게 고친 것은 어느 것인가요?',ARRAY['K2-1-u3-X05','K2-1-u3-X06']::text[],true,'{"seq":8,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"「두 명의 아이가 종이비행기를 날린다.」에 꾸며 주는 말을 넣어 더 생생하게 고친 것은 어느 것인가요?","options":[{"t":"두 명의 아이가 종이비행기를 힘껏 멀리 날린다.","correct":true},{"t":"두 명의 아이가 종이비행기를 슬프게 시끄럽게 날린다.","mis":"K2-1-u3-X05"},{"t":"힘껏 멀리 종이비행기.","mis":"K2-1-u3-X06"}],"explanation":["「힘껏」·「멀리」가 날리는 모습을 생생하게 해요.","뜻이 어긋나는 말을 넣거나 문장을 끝맺지 않으면 안 돼요.","어울리는 말을 넣고 끝까지 써요."],"variant_rule":{"alt":[{"stem":"「아이들이 공을 찬다.」에 꾸며 주는 말을 넣어 더 생생하게 고친 것은 어느 것인가요?","options":[{"t":"아이들이 커다란 공을 힘차게 찬다.","correct":true},{"t":"아이들이 졸린 공을 맛있게 찬다.","mis":"K2-1-u3-X05"},{"t":"커다란 공 힘차게.","mis":"K2-1-u3-X06"}],"explanation":["「커다란」·「힘차게」가 공과 차는 모습을 보여 줘요.","공에 「졸린」, 차는 모습에 「맛있게」는 어울리지 않아요.","문장은 끝까지 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#9','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',2,'ox','auto','「시끄러운 사과」는 사과의 모습에 어울리는 꾸며 주는 말이에요.',ARRAY['K2-1-u3-X04']::text[],true,'{"seq":9,"concept":"K2-1-u3-C4","difficulty":2,"kind":"ox","stem":"「시끄러운 사과」는 사과의 모습에 어울리는 꾸며 주는 말이에요.","answer":"X","reason_options":[{"t":"사과는 소리를 내지 않아 색이나 모양을 나타내는 말이 어울리니까","correct":true},{"t":"꾸며 주는 말은 아무것이나 붙여도 되니까","mis":"K2-1-u3-X04"}],"mis":"K2-1-u3-X04","explanation":["사과에는 「붉은」, 「둥근」 같은 말이 어울려요.","대상과 어울리지 않는 말을 붙이면 모습이 떠오르지 않아요.","대상을 잘 살펴 골라요."],"variant_rule":{"alt":[{"stem":"「반짝반짝 빛나는 별」은 별의 모습에 어울리는 표현이에요.","answer":"O","reason_options":[{"t":"별이 빛나는 모습이 떠오르니까","correct":true},{"t":"별은 소리를 내니까","mis":"K2-1-u3-X04"}],"explanation":["「반짝반짝」은 별이 빛나는 모습을 잘 나타내요.","대상에 어울리는 말이라서 생생해요.","별은 소리를 내지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#10','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',3,'error','auto','「우산을 쓴다.」에 꾸며 주는 말을 넣어 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":3,"kind":"error","stem":"「우산을 쓴다.」에 꾸며 주는 말을 넣어 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"지후 — 「노란 우산.」","correct":true,"mis_target":"K2-1-u3-X06"},{"t":"하늘 — 「노란 우산을 쓴다.」","mis":"K2-1-u3-X19"},{"t":"서윤 — 「커다란 우산을 쓰고 천천히 걷는다.」","mis":"K2-1-u3-X19"}],"explanation":["지후는 꾸며 주는 말을 넣었지만 문장을 끝까지 쓰지 않았어요.","하늘이와 서윤이는 꾸며 주는 말을 넣어 끝까지 썼어요.","「누가 어찌한다.」까지 써야 문장이에요."],"variant_rule":{"alt":[{"stem":"「새가 난다.」에 꾸며 주는 말을 넣어 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"준우 — 「새가 네모나게 맛있게 난다.」","correct":true,"mis_target":"K2-1-u3-X05"},{"t":"소율 — 「작은 새가 높이 난다.」","mis":"K2-1-u3-X19"},{"t":"태민 — 「파란 새가 하늘을 훨훨 난다.」","mis":"K2-1-u3-X19"}],"explanation":["「네모나게」·「맛있게」는 나는 모습과 어울리지 않아요.","소율이와 태민이는 어울리는 말을 넣었어요.","많이 넣는 것보다 어울리게 넣는 것이 중요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#1','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',2,'mc','auto','붉게 익은 사과를 「모양」에 초점을 두어 꾸민 말은 어느 것인가요?',ARRAY['K2-1-u3-X04','K2-1-u3-X06']::text[],false,'{"seq":1,"concept":"K2-1-u3-C4","difficulty":2,"kind":"mc","stem":"붉게 익은 사과를 「모양」에 초점을 두어 꾸민 말은 어느 것인가요?","options":[{"t":"둥근 사과","correct":true},{"t":"붉은 사과","mis":"K2-1-u3-X04"},{"t":"빠르게 사과","mis":"K2-1-u3-X06"}],"explanation":["「둥근」은 사과의 모양을 나타내요.","「붉은」은 색을 나타내는 말이에요.","「빠르게 사과」는 말이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#2','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',2,'mc','auto','「멋있는 말이 힘차게 달려온다.」에서 「힘차게」가 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"「멋있는 말이 힘차게 달려온다.」에서 「힘차게」가 꾸며 주는 말은 어느 것인가요?","options":[{"t":"달려온다","correct":true},{"t":"멋있는","mis":"K2-1-u3-X02"},{"t":"말이","mis":"K2-1-u3-X02"}],"explanation":["「힘차게」는 어떻게 달려오는지 꾸며요.","「멋있는」은 말을 꾸미는 꾸며 주는 말이에요.","한 문장에 꾸며 주는 말이 둘 들어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#3','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',3,'mc','auto','바닷가 사진을 보고 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"바닷가 사진을 보고 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「달콤한 파도가 철썩 친다.」","correct":true},{"t":"「하얀 갈매기가 높이 난다.」","mis":"K2-1-u3-X19"},{"t":"「뜨거운 모래가 반짝인다.」","mis":"K2-1-u3-X19"}],"explanation":["파도는 맛이 없어 「달콤한」이 어울리지 않아요.","「하얀 갈매기」, 「뜨거운 모래」는 바닷가 모습에 어울려요.","「어울리지 않는」을 묻는 물음이에요."],"asset":{"type":"scene","icon":"🏖️🌊"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#4','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',3,'error','auto','공원 사진을 보고 꾸며 주는 말을 넣었어요. 어울리지 않는 말을 넣은 친구는 누구인가요?',ARRAY['K2-1-u3-X04','K2-1-u3-X19']::text[],false,'{"seq":4,"concept":"K2-1-u3-C4","difficulty":3,"kind":"error","stem":"공원 사진을 보고 꾸며 주는 말을 넣었어요. 어울리지 않는 말을 넣은 친구는 누구인가요?","options":[{"t":"은솔 — 「네모난 비둘기가 걸어간다.」","correct":true,"mis_target":"K2-1-u3-X04"},{"t":"민지 — 「푸른 나무가 우뚝 서 있다.」","mis":"K2-1-u3-X19"},{"t":"아린 — 「알록달록한 꽃이 활짝 피었다.」","mis":"K2-1-u3-X19"}],"explanation":["비둘기는 네모나지 않아요.","「푸른 나무」, 「알록달록한 꽃」은 공원 모습에 어울려요.","대상을 눈앞에 그리고 어울리는 말을 골라요."],"asset":{"type":"scene","icon":"🌳🕊️🌷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#5','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',3,'mc','auto','「(     ) 별이 (     ) 빛난다.」 두 빈칸에 차례로 넣기에 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X04']::text[],false,'{"seq":5,"concept":"K2-1-u3-C5","difficulty":3,"kind":"mc","stem":"「(     ) 별이 (     ) 빛난다.」 두 빈칸에 차례로 넣기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작은 — 반짝반짝","correct":true},{"t":"반짝반짝 — 작은","mis":"K2-1-u3-X02"},{"t":"시끄러운 — 맛있게","mis":"K2-1-u3-X04"}],"explanation":["「작은」은 별을, 「반짝반짝」은 빛나는 모습을 꾸며요.","차례를 바꾸면 「반짝반짝 별이 작은 빛난다」가 되어 어색해요.","어울리는 말을 알맞은 자리에 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#6','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',3,'ox','auto','「키가 큰 커다란 큰 나무」처럼 같은 뜻의 꾸며 주는 말을 많이 넣을수록 더 잘 쓴 문장이에요.',ARRAY['K2-1-u3-X05']::text[],false,'{"seq":6,"concept":"K2-1-u3-C5","difficulty":3,"kind":"ox","stem":"「키가 큰 커다란 큰 나무」처럼 같은 뜻의 꾸며 주는 말을 많이 넣을수록 더 잘 쓴 문장이에요.","answer":"X","reason_options":[{"t":"같은 뜻을 되풀이하면 오히려 어색해지니까","correct":true},{"t":"꾸며 주는 말은 많을수록 좋으니까","mis":"K2-1-u3-X05"}],"mis":"K2-1-u3-X05","explanation":["「큰」과 「커다란」은 뜻이 같아 겹쳐요.","많이 넣는 것보다 어울리게 넣는 것이 중요해요.","「키 큰 푸른 나무」처럼 다른 점을 나타내면 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#7','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',3,'mc','auto','「아기가 웃는다.」를 아기의 모습이 잘 떠오르게 고친 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":7,"concept":"K2-1-u3-C5","difficulty":3,"kind":"mc","stem":"「아기가 웃는다.」를 아기의 모습이 잘 떠오르게 고친 것은 어느 것인가요?","options":[{"t":"「작은 아기가 방긋방긋 웃는다.」","correct":true},{"t":"「작은 아기.」","mis":"K2-1-u3-X06"},{"t":"「작은 아기가 무섭게 화나게 웃는다.」","mis":"K2-1-u3-X05"}],"explanation":["「작은」·「방긋방긋」이 아기와 웃는 모습을 보여 줘요.","「작은 아기.」는 끝맺지 않았어요.","「무섭게」·「화나게」는 웃는 모습과 어울리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#8','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',4,'mc','auto','두 친구가 수박 그림을 보고 문장을 만들었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#9','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',4,'essay','teacher','바다·산·우리 집 가운데 하나를 떠올려, 그 모습을 꾸며 주는 말을 두 개 이상 넣은 문장으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"바다·산·우리 집 가운데 하나를 떠올려, 그 모습을 꾸며 주는 말을 두 개 이상 넣은 문장으로 써 보세요.","answer_guide":{"answer":"예: 넓고 푸른 바다에서 하얀 배가 천천히 나아간다.","scoring_points":["떠올린 장소의 모습을 썼는가","꾸며 주는 말을 두 개 이상 넣었는가","넣은 말이 대상과 어울리고 문장을 끝까지 썼는가"]},"explanation":["장소의 모습.","꾸며 주는 말 두 개 이상.","어울림·끝맺음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#10','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',4,'essay','teacher','「고양이」를 색·모양·움직임 가운데 두 가지에 초점을 두어 꾸며 주는 말을 넣은 문장으로 쓰고, 무엇에 초점을 두었는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C4","difficulty":4,"kind":"essay","stem":"「고양이」를 색·모양·움직임 가운데 두 가지에 초점을 두어 꾸며 주는 말을 넣은 문장으로 쓰고, 무엇에 초점을 두었는지 써 보세요.","answer_guide":{"answer":"예: 하얀 고양이가 살금살금 걸어간다. — 색(하얀)과 움직임(살금살금)에 초점을 두었어요.","scoring_points":["고양이를 꾸미는 문장을 썼는가","꾸며 주는 말이 두 가지 초점(색·모양·움직임)에 맞는가","무엇에 초점을 두었는지 썼는가"]},"explanation":["고양이 문장.","두 가지 초점.","초점 밝히기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#1','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C6',1,'mc','auto','글을 읽고 답해 보세요. 흙 속에서 잠을 자던 것은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":1,"concept":"K2-1-u3-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 흙 속에서 잠을 자던 것은 무엇인가요?","options":[{"t":"작은 씨앗","correct":true},{"t":"커다란 해바라기","mis":"K2-1-u3-X07"},{"t":"까만 흙","mis":"K2-1-u3-X07"}],"explanation":["글 첫 문장에 「작은 씨앗이 흙 속에서 잠을 자요.」라고 했어요.","해바라기는 나중에 핀 꽃이에요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 봄비가 내리자 돋아난 것은 무엇인가요?","options":[{"t":"조그만 새싹","correct":true},{"t":"까만 씨앗","mis":"K2-1-u3-X07"},{"t":"커다란 꽃","mis":"K2-1-u3-X07"}],"explanation":["봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","꽃은 여름에, 까만 씨앗은 가을에 생겼어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#2','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C1',1,'mc','auto','글을 읽고 답해 보세요. 「커다란 해바라기」에서 해바라기를 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X01']::text[],true,'{"seq":2,"concept":"K2-1-u3-C1","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 「커다란 해바라기」에서 해바라기를 꾸며 주는 말은 어느 것인가요?","options":[{"t":"커다란","correct":true},{"t":"해바라기","mis":"K2-1-u3-X01"},{"t":"여름","mis":"K2-1-u3-X01"}],"explanation":["「커다란」이 해바라기가 어떤지 알려 줘요.","「해바라기」는 꾸밈을 받는 말이에요.","「어떤 해바라기?」에 대답하는 말을 찾아요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 「조그만 새싹」에서 새싹을 꾸며 주는 말은 어느 것인가요?","options":[{"t":"조그만","correct":true},{"t":"새싹","mis":"K2-1-u3-X01"},{"t":"봄비","mis":"K2-1-u3-X01"}],"explanation":["「조그만」이 새싹이 어떤지 알려 줘요.","「새싹」은 꾸밈을 받는 말이에요.","「어떤 새싹?」에 대답하는 말을 찾아요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#3','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C8',1,'mc','auto','작은 열매가 많이 매달린 모양을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],true,'{"seq":3,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"작은 열매가 많이 매달린 모양을 나타내는 말은 어느 것인가요?","options":[{"t":"조롱조롱","correct":true},{"t":"올록볼록","mis":"K2-1-u3-X08"},{"t":"활짝","mis":"K2-1-u3-X08"}],"explanation":["「조롱조롱」은 작은 열매가 많이 매달린 모양이에요.","「올록볼록」은 겉이 높고 낮은 모양, 「활짝」은 꽃잎이 한껏 핀 모양이에요.","소리 내어 읽으며 모양을 떠올려요."],"variant_rule":{"alt":[{"stem":"겉면이 고르지 않게 높고 낮은 모양을 나타내는 말은 어느 것인가요?","options":[{"t":"올록볼록","correct":true},{"t":"조롱조롱","mis":"K2-1-u3-X08"},{"t":"활짝","mis":"K2-1-u3-X08"}],"explanation":["「올록볼록」은 겉이 높고 낮은 모양이에요.","「조롱조롱」은 열매가 많이 매달린 모양이에요.","손으로 모양을 흉내 내며 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#4','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C6',1,'ox','auto','글을 읽고 답해 보세요. 해바라기는 여름이 되자 꽃이 활짝 피었어요.',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":4,"concept":"K2-1-u3-C6","difficulty":1,"kind":"ox","stem":"글을 읽고 답해 보세요. 해바라기는 여름이 되자 꽃이 활짝 피었어요.","answer":"O","reason_options":[{"t":"글에 「여름이 되자 커다란 해바라기가 활짝 피었어요.」라고 했으니까","correct":true},{"t":"해바라기는 언제나 봄에 피니까","mis":"K2-1-u3-X07"}],"mis":"K2-1-u3-X07","explanation":["글에서 여름에 꽃이 피었다고 했어요.","글에 없는 내용으로 답하면 안 돼요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 새싹이 돋아난 뒤에 씨앗을 심었어요.","answer":"X","reason_options":[{"t":"씨앗에서 새싹이 돋아났으니 씨앗이 먼저이니까","correct":true},{"t":"새싹이 먼저 나와야 씨앗이 생기니까","mis":"K2-1-u3-X07"}],"explanation":["씨앗이 흙 속에서 잠을 자다 새싹이 돋았어요.","자라는 차례를 바꾸면 안 돼요.","씨앗 → 새싹 → 꽃 → 씨앗 차례예요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#5','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C8',2,'match','auto','낱말과 알맞은 뜻을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":2,"kind":"match","stem":"낱말과 알맞은 뜻을 이어 보세요.","pairs":[{"l":"조롱조롱","r":"열매가 많이 매달린 모양"},{"l":"올록볼록","r":"겉면이 높고 낮은 모양"},{"l":"활짝","r":"꽃잎이 한껏 핀 모양"}],"mis":"K2-1-u3-X08","explanation":["「조롱조롱」은 열매가 많이 매달린 모양이에요.","「올록볼록」은 겉면이 높고 낮은 모양이에요.","「활짝」은 꽃잎이 한껏 핀 모양이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 알맞은 뜻을 이어 보세요.","pairs":[{"l":"무럭무럭","r":"힘차게 잘 자라는 모양"},{"l":"빙글빙글","r":"둥글게 감거나 도는 모양"},{"l":"쏙","r":"조그맣게 내미는 모양"}],"explanation":["「무럭무럭」은 힘차게 잘 자라는 모양이에요.","「빙글빙글」은 둥글게 감거나 도는 모양이에요.","「쏙」은 조그맣게 내미는 모양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#6','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 해바라기가 자란 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":6,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 해바라기가 자란 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"씨앗 → 새싹 → 꽃 → 씨앗","correct":true},{"t":"새싹 → 씨앗 → 꽃 → 씨앗","mis":"K2-1-u3-X07"},{"t":"꽃 → 새싹 → 씨앗 → 꽃","mis":"K2-1-u3-X07"}],"explanation":["작은 씨앗에서 새싹이 돋고, 꽃이 핀 뒤 다시 씨앗이 생겼어요.","차례를 뒤바꾸면 글과 달라져요.","봄·여름·가을 낱말을 따라가 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 토마토가 자란 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"모종 → 노란 꽃 → 초록 열매 → 빨간 열매","correct":true},{"t":"모종 → 빨간 열매 → 노란 꽃 → 초록 열매","mis":"K2-1-u3-X07"},{"t":"노란 꽃 → 모종 → 빨간 열매 → 초록 열매","mis":"K2-1-u3-X07"}],"explanation":["모종을 심고, 꽃이 피고, 초록 열매가 빨갛게 익었어요.","차례를 뒤바꾸면 글과 달라져요.","글의 문장 차례대로 따라가요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#7','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C3',2,'mc','auto','글을 읽고 답해 보세요. 「줄기는 하루하루 무럭무럭 자랐어요.」에서 「무럭무럭」을 빼면 어떻게 될까요?',ARRAY['K2-1-u3-X03','K2-1-u3-X07']::text[],true,'{"seq":7,"concept":"K2-1-u3-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「줄기는 하루하루 무럭무럭 자랐어요.」에서 「무럭무럭」을 빼면 어떻게 될까요?","options":[{"t":"줄기가 어떻게 자랐는지 모습이 잘 떠오르지 않아요","correct":true},{"t":"문장이 더 생생해져요","mis":"K2-1-u3-X03"},{"t":"줄기가 자라지 않은 것이 돼요","mis":"K2-1-u3-X07"}],"explanation":["「무럭무럭」이 자라는 모습을 그려 줘요.","빼도 줄기는 자라지만 모습이 덜 생생해요.","꾸며 주는 말이 모습을 보여 줘요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 「노란 꽃이 피었어요.」에서 「노란」을 빼면 어떻게 될까요?","options":[{"t":"꽃이 무슨 색인지 알 수 없어요","correct":true},{"t":"꽃이 더 또렷하게 떠올라요","mis":"K2-1-u3-X03"},{"t":"꽃이 피지 않은 것이 돼요","mis":"K2-1-u3-X07"}],"explanation":["「노란」이 꽃의 색을 알려 줘요.","빼면 꽃의 모습이 덜 또렷해요.","꾸며 주는 말이 모습을 보여 줘요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#8','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C6',2,'sa','auto','글을 읽고 답해 보세요. 꽃이 진 자리에 매달린 열매는 처음에 무슨 색이었나요? 한 낱말로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u3-C6","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 꽃이 진 자리에 매달린 열매는 처음에 무슨 색이었나요? 한 낱말로 써 보세요.","answer":["초록","초록색","초록 색"],"explanation":["「꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.」라고 했어요.","빨갛게 된 것은 햇볕을 받고 익은 뒤예요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 토마토 줄기가 자랄 때 핀 꽃은 무슨 색이었나요? 한 낱말로 써 보세요.","answer":["노란","노랑","노란색","노랑색"],"explanation":["「줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.」라고 했어요.","빨간 것은 익은 열매예요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#9','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C3',2,'mc','auto','덩굴손이 자라는 모습을 더 잘 나타낸 문장은 어느 것인가요?',ARRAY['K2-1-u3-X03','K2-1-u3-X06']::text[],true,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"mc","stem":"덩굴손이 자라는 모습을 더 잘 나타낸 문장은 어느 것인가요?","options":[{"t":"덩굴손이 빙글빙글 감으며 쭉쭉 뻗어 간다.","correct":true},{"t":"덩굴손이 자란다.","mis":"K2-1-u3-X03"},{"t":"덩굴손.","mis":"K2-1-u3-X06"}],"explanation":["「빙글빙글」·「쭉쭉」이 뻗어 가는 모습을 보여 줘요.","「덩굴손이 자란다.」로는 어떻게 자라는지 알 수 없어요.","「덩굴손.」은 문장이 아니에요."],"variant_rule":{"alt":[{"stem":"새싹이 돋는 모습을 더 잘 나타낸 문장은 어느 것인가요?","options":[{"t":"조그만 새싹이 흙을 밀고 쏙 돋아났다.","correct":true},{"t":"새싹이 났다.","mis":"K2-1-u3-X03"},{"t":"조그만 새싹.","mis":"K2-1-u3-X06"}],"explanation":["「조그만」·「쏙」이 돋는 모습을 보여 줘요.","「새싹이 났다.」로는 모습이 떠오르지 않아요.","「조그만 새싹.」은 끝맺지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#10','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C8',3,'error','auto','글을 읽고 낱말의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X08','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C8","difficulty":3,"kind":"error","stem":"글을 읽고 낱말의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「‘올록볼록’은 열매가 많이 매달린 모양이야.」","correct":true,"mis_target":"K2-1-u3-X08"},{"t":"지안 — 「‘빙글빙글’은 막대를 둥글게 감는 모양이야.」","mis":"K2-1-u3-X19"},{"t":"도담 — 「‘동글동글’은 콩이 둥근 모양이야.」","mis":"K2-1-u3-X19"}],"explanation":["「올록볼록」은 겉이 높고 낮은 모양이에요.","열매가 많이 매달린 모양은 「조롱조롱」이에요.","지안이와 도담이는 바르게 말했어요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 낱말의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「‘쭉쭉’은 아주 느리게 뒤로 물러나는 모양이야.」","correct":true,"mis_target":"K2-1-u3-X08"},{"t":"하준 — 「‘쭉쭉’은 길게 곧게 뻗는 모양이야.」","mis":"K2-1-u3-X19"},{"t":"서아 — 「‘올록볼록’은 겉이 울퉁불퉁한 모양이야.」","mis":"K2-1-u3-X19"}],"explanation":["「쭉쭉」은 길게 곧게 뻗어 가는 모양이에요.","느리게 물러나는 모양이 아니에요.","하준이와 서아는 바르게 말했어요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#1','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 땅콩 껍데기를 만지면 어떤 느낌일까요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":1,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 땅콩 껍데기를 만지면 어떤 느낌일까요?","options":[{"t":"울퉁불퉁해요","correct":true},{"t":"매끈매끈해요","mis":"K2-1-u3-X07"},{"t":"말랑말랑해요","mis":"K2-1-u3-X07"}],"explanation":["겉이 올록볼록해서 만지면 울퉁불퉁하다고 했어요.","매끈하거나 말랑하다는 말은 글에 없어요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#2','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C1',2,'mc','auto','글을 읽고 답해 보세요. 이 글에서 꾸며 주는 말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u3-X01']::text[],false,'{"seq":2,"concept":"K2-1-u3-C1","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 꾸며 주는 말만 모은 것은 어느 것인가요?","options":[{"t":"빙글빙글 · 동글동글한 · 올록볼록","correct":true},{"t":"덩굴손 · 꼬투리 · 땅콩","mis":"K2-1-u3-X01"},{"t":"완두 · 막대 · 껍데기","mis":"K2-1-u3-X01"}],"explanation":["「빙글빙글」·「동글동글한」·「올록볼록」은 모습을 꾸며요.","덩굴손·꼬투리·땅콩·막대는 꾸밈을 받는 이름 낱말이에요.","「어떤? 어떻게?」에 대답하는 말을 모아요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#3','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 열매가 빨갛게 익을 수 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":3,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 열매가 빨갛게 익을 수 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"햇볕을 듬뿍 받았기 때문이에요","correct":true},{"t":"노란 꽃이 다시 피었기 때문이에요","mis":"K2-1-u3-X07"},{"t":"줄기를 잘라 주었기 때문이에요","mis":"K2-1-u3-X07"}],"explanation":["「햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요.」라고 했어요.","다른 까닭은 글에 없어요.","글에 쓰인 까닭을 찾아요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#4','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',3,'ox','auto','글을 읽고 답해 보세요. 덩굴손은 막대를 감지 않고 아래로 축 늘어져 자라요.',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":4,"concept":"K2-1-u3-C6","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 덩굴손은 막대를 감지 않고 아래로 축 늘어져 자라요.","answer":"X","reason_options":[{"t":"글에 막대를 빙글빙글 감으며 쭉쭉 뻗어 간다고 했으니까","correct":true},{"t":"덩굴손은 원래 아무것도 감지 않으니까","mis":"K2-1-u3-X07"}],"mis":"K2-1-u3-X07","explanation":["덩굴손은 막대를 빙글빙글 감으며 뻗어 가요.","글에 없는 내용으로 답하면 안 돼요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#5','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',3,'error','auto','글을 읽고 해바라기가 자라는 모습을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X07','K2-1-u3-X19']::text[],false,'{"seq":5,"concept":"K2-1-u3-C6","difficulty":3,"kind":"error","stem":"글을 읽고 해바라기가 자라는 모습을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"민호 — 「겨울에 해바라기 꽃이 활짝 피었어.」","correct":true,"mis_target":"K2-1-u3-X07"},{"t":"소율 — 「봄비가 내리자 새싹이 돋았어.」","mis":"K2-1-u3-X19"},{"t":"지우 — 「가을에 꽃 가운데에 씨앗이 박혔어.」","mis":"K2-1-u3-X19"}],"explanation":["글에서는 여름에 꽃이 피었다고 했어요.","겨울에 피었다는 말은 글에 없어요.","소율이와 지우는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#6','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C8',3,'mc','auto','「꽃이 진 자리에 초록 열매가 (     ) 매달렸어요.」에 들어갈 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08','K2-1-u3-X04']::text[],false,'{"seq":6,"concept":"K2-1-u3-C8","difficulty":3,"kind":"mc","stem":"「꽃이 진 자리에 초록 열매가 (     ) 매달렸어요.」에 들어갈 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조롱조롱","correct":true},{"t":"올록볼록","mis":"K2-1-u3-X08"},{"t":"펑펑","mis":"K2-1-u3-X04"}],"explanation":["작은 열매가 많이 매달린 모양은 「조롱조롱」이에요.","「올록볼록」은 겉면의 모양, 「펑펑」은 눈이 많이 내리는 모양이에요.","매달린 모습에 어울리는 말을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#7','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C3',3,'mc','auto','글쓴이가 「작은 씨앗」, 「커다란 해바라기」처럼 꾸며 주는 말을 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":7,"concept":"K2-1-u3-C3","difficulty":3,"kind":"mc","stem":"글쓴이가 「작은 씨앗」, 「커다란 해바라기」처럼 꾸며 주는 말을 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"씨앗이 큰 꽃으로 자라는 모습을 생생하게 보여 주려고","correct":true},{"t":"글을 길게 만들려고","mis":"K2-1-u3-X03"},{"t":"해바라기 이름을 바꾸려고","mis":"K2-1-u3-X03"}],"explanation":["「작은」과 「커다란」을 견주니 자라는 모습이 또렷해요.","글을 길게 하려는 것이 아니에요.","꾸며 주는 말로 모습을 그려 보여 준 거예요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#8','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C8',4,'mc','auto','두 친구가 화단의 식물을 설명했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#9','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',4,'essay','teacher','「해바라기가 자라요」를 읽고, 해바라기가 자라는 차례를 꾸며 주는 말을 넣어 두 문장으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C6","difficulty":4,"kind":"essay","stem":"「해바라기가 자라요」를 읽고, 해바라기가 자라는 차례를 꾸며 주는 말을 넣어 두 문장으로 써 보세요.","answer_guide":{"answer":"예: 작은 씨앗에서 조그만 새싹이 쏙 돋았어요. 새싹은 무럭무럭 자라 커다란 해바라기가 되었어요.","scoring_points":["씨앗 → 새싹 → 꽃 차례가 글과 맞는가","꾸며 주는 말을 넣었는가","두 문장으로 끝까지 썼는가"]},"explanation":["자라는 차례.","꾸며 주는 말.","두 문장."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#10','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C8',4,'essay','teacher','집이나 학교에서 본 식물·과일을 하나 골라, 모양을 흉내 내거나 꾸며 주는 말(예: 동글동글, 올록볼록)을 넣어 설명하는 문장을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C8","difficulty":4,"kind":"essay","stem":"집이나 학교에서 본 식물·과일을 하나 골라, 모양을 흉내 내거나 꾸며 주는 말(예: 동글동글, 올록볼록)을 넣어 설명하는 문장을 써 보세요.","answer_guide":{"answer":"예: 귤 껍질은 오톨도톨하고, 속은 동글동글한 조각으로 나뉘어 있어요.","scoring_points":["식물이나 과일 하나를 골랐는가","모양을 나타내는 말을 넣었는가","그 말이 대상의 모습과 어울리는가"]},"explanation":["대상 고르기.","모양 낱말.","어울림."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#1','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',1,'mc','auto','일기로 쓸 이야깃거리를 무엇이라고 하나요?',ARRAY['K2-1-u3-X14','K2-1-u3-X09']::text[],true,'{"seq":1,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"일기로 쓸 이야깃거리를 무엇이라고 하나요?","options":[{"t":"글감","correct":true},{"t":"제목","mis":"K2-1-u3-X14"},{"t":"날씨","mis":"K2-1-u3-X09"}],"explanation":["일기로 쓸 이야깃거리를 글감이라고 해요.","제목은 글감을 정한 뒤 붙이는 이름이에요.","날씨는 일기 맨 처음에 쓰는 것이에요."],"variant_rule":{"alt":[{"stem":"평소와 다르게 보였거나 마음에 오래 남는 일을 무엇이라고 하나요?","options":[{"t":"인상 깊은 일","correct":true},{"t":"날마다 하는 일","mis":"K2-1-u3-X13"},{"t":"내일 할 일","mis":"K2-1-u3-X13"}],"explanation":["마음에 오래 남는 일을 인상 깊은 일이라고 해요.","날마다 하는 일이나 내일 할 일은 아니에요.","인상 깊은 일이 좋은 글감이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#2','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],true,'{"seq":2,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"텃밭에서 상추를 땄다","correct":true},{"t":"연필","mis":"K2-1-u3-X12"},{"t":"즐거움","mis":"K2-1-u3-X12"}],"explanation":["「상추를 땄다」는 내가 한 일이에요.","「연필」은 물건, 「즐거움」은 느낌이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"도서관에서 책을 읽었다","correct":true},{"t":"책상","mis":"K2-1-u3-X12"},{"t":"기쁨","mis":"K2-1-u3-X12"}],"explanation":["「책을 읽었다」는 내가 한 일이에요.","「책상」은 물건, 「기쁨」은 느낌이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#3','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',1,'ox','auto','일기 글감은 하루에 겪은 일 가운데 가장 인상 깊은 일 하나를 골라 정해요.',ARRAY['K2-1-u3-X13']::text[],true,'{"seq":3,"concept":"K2-1-u3-C8","difficulty":1,"kind":"ox","stem":"일기 글감은 하루에 겪은 일 가운데 가장 인상 깊은 일 하나를 골라 정해요.","answer":"O","reason_options":[{"t":"기억에 남는 일을 골라야 그날이 잘 드러나니까","correct":true},{"t":"하루 일을 모두 써야 하니까","mis":"K2-1-u3-X13"}],"mis":"K2-1-u3-X13","explanation":["글감은 가장 인상 깊은 일 하나를 골라요.","모두 쓰면 무엇이 마음에 남았는지 흐려져요.","고른 일을 자세히 써요."],"variant_rule":{"alt":[{"stem":"날마다 똑같이 하는 이 닦기가 가장 좋은 일기 글감이에요.","answer":"X","reason_options":[{"t":"마음이 움직인 인상 깊은 일이 좋은 글감이니까","correct":true},{"t":"날마다 하는 일이 가장 중요하니까","mis":"K2-1-u3-X13"}],"explanation":["날마다 똑같은 일은 그날만의 이야기가 되기 어려워요.","마음이 움직인 일을 골라요.","같은 일이라도 특별했다면 글감이 될 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#4','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C9',1,'mc','auto','줄넘기를 처음 성공한 날의 일기 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],true,'{"seq":4,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"줄넘기를 처음 성공한 날의 일기 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄넘기를 처음 성공한 날","correct":true},{"t":"오늘 날씨","mis":"K2-1-u3-X14"},{"t":"그냥 하루","mis":"K2-1-u3-X14"}],"explanation":["제목만 보아도 무슨 일인지 알 수 있어요.","「오늘 날씨」, 「그냥 하루」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."],"variant_rule":{"alt":[{"stem":"텃밭에서 처음 상추를 딴 날의 일기 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 딴 첫 상추","correct":true},{"t":"일기","mis":"K2-1-u3-X14"},{"t":"수요일","mis":"K2-1-u3-X14"}],"explanation":["제목만 보아도 무슨 일인지 알 수 있어요.","「일기」, 「수요일」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#5','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C10',2,'match','auto','겪은 일과 그때의 느낌을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C10","difficulty":2,"kind":"match","stem":"겪은 일과 그때의 느낌을 알맞게 이어 보세요.","pairs":[{"l":"줄넘기 처음 성공","r":"뿌듯했어요"},{"l":"친구들 앞에서 노래","r":"긴장됐어요"},{"l":"동생과 책 읽기","r":"즐거웠어요"}],"mis":"K2-1-u3-X15","explanation":["처음 성공했을 때는 뿌듯했어요.","친구들 앞에 서면 긴장이 돼요.","동생과 책을 읽으니 즐거웠어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 겪은 일과 그때의 느낌을 알맞게 이어 보세요.","pairs":[{"l":"아끼던 연필을 잃어버림","r":"속상했어요"},{"l":"생일 선물을 받음","r":"기뻤어요"},{"l":"갑자기 천둥이 침","r":"깜짝 놀랐어요"}],"explanation":["아끼던 것을 잃어버리면 속상해요.","선물을 받으면 기뻐요.","갑자기 천둥이 치면 놀라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#6','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',2,'mc','auto','글을 읽고 답해 보세요. 하준이가 일기 글감으로 고르기에 가장 알맞은 일은 어느 것인가요?',ARRAY['K2-1-u3-X13']::text[],true,'{"seq":6,"concept":"K2-1-u3-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 하준이가 일기 글감으로 고르기에 가장 알맞은 일은 어느 것인가요?","options":[{"t":"처음으로 줄넘기 열 번을 넘은 일","correct":true},{"t":"자기 전에 이를 닦은 일","mis":"K2-1-u3-X13"},{"t":"아침부터 저녁까지 한 일 모두","mis":"K2-1-u3-X13"}],"explanation":["처음 해낸 일이라 마음에 남는 일이에요.","이 닦기는 날마다 하는 일이에요.","하루 일을 모두 쓰면 글감이 흐려져요."],"asset":{"type":"passage","lines":["아침 — 창밖으로 맑은 하늘을 보았다.","낮 — 운동장에서 처음으로 줄넘기 열 번을 넘었다.","저녁 — 동생과 그림책을 읽었다.","자기 전 — 이를 닦았다."],"title":"하준이의 하루"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 서윤이가 일기 글감으로 고르기에 가장 알맞은 일은 어느 것인가요?","options":[{"t":"텃밭에서 처음으로 상추를 딴 일","correct":true},{"t":"숙제를 한 일","mis":"K2-1-u3-X13"},{"t":"아침부터 저녁까지 한 일 모두","mis":"K2-1-u3-X13"}],"explanation":["처음 해 본 일이라 마음에 남는 일이에요.","숙제는 날마다 하는 일이에요.","하루 일을 모두 쓰면 글감이 흐려져요."],"asset":{"type":"passage","lines":["아침 — 엄마가 차려 주신 밥을 먹었다.","낮 — 텃밭에서 처음으로 상추를 땄다.","오후 — 친구에게 「고마워.」라는 말을 들었다.","저녁 — 숙제를 했다."],"title":"서윤이의 하루"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#7','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',2,'mc','auto','하루에 「들은 것」에 해당하는 겪은 일은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],true,'{"seq":7,"concept":"K2-1-u3-C8","difficulty":2,"kind":"mc","stem":"하루에 「들은 것」에 해당하는 겪은 일은 어느 것인가요?","options":[{"t":"선생님께 「잘했어.」라는 칭찬을 들었다","correct":true},{"t":"운동장에서 줄넘기를 했다","mis":"K2-1-u3-X19"},{"t":"창밖으로 맑은 하늘을 보았다","mis":"K2-1-u3-X19"}],"explanation":["칭찬을 들은 것은 「들은 것」이에요.","줄넘기는 「한 것」, 하늘은 「본 것」이에요.","한 것·본 것·들은 것을 나누어 떠올려요."],"variant_rule":{"alt":[{"stem":"하루에 「본 것」에 해당하는 겪은 일은 어느 것인가요?","options":[{"t":"공원에서 무지개를 보았다","correct":true},{"t":"친구와 술래잡기를 했다","mis":"K2-1-u3-X19"},{"t":"엄마의 노랫소리를 들었다","mis":"K2-1-u3-X19"}],"explanation":["무지개를 본 것은 「본 것」이에요.","술래잡기는 「한 것」, 노랫소리는 「들은 것」이에요.","한 것·본 것·들은 것을 나누어 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#8','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C9',2,'sa','auto','「할머니 댁에서 처음으로 송편을 빚었다.」가 글감인 일기의 제목을 짧게 지어 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u3-C9","difficulty":2,"kind":"sa","stem":"「할머니 댁에서 처음으로 송편을 빚었다.」가 글감인 일기의 제목을 짧게 지어 써 보세요.","answer":["송편","송편을 빚은 날","처음 빚은 송편","할머니 댁에서 빚은 송편","내가 빚은 송편"],"explanation":["제목에는 「송편」처럼 무슨 일인지 드러나는 낱말이 들어가요.","「오늘」, 「일기」만으로는 내용을 알 수 없어요.","제목만 보고도 무슨 일인지 알 수 있게 지어요."],"variant_rule":{"alt":[{"stem":"「처음으로 두발자전거를 혼자 탔다.」가 글감인 일기의 제목을 짧게 지어 써 보세요.","answer":["자전거","두발자전거","처음 탄 두발자전거","자전거를 혼자 탄 날","혼자 탄 자전거"],"explanation":["제목에는 「자전거」처럼 무슨 일인지 드러나는 낱말이 들어가요.","「오늘」, 「일기」만으로는 내용을 알 수 없어요.","제목만 보고도 무슨 일인지 알 수 있게 지어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#9','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C9',2,'ox','auto','일기 제목은 「일기」라고만 써도 내용이 잘 드러나요.',ARRAY['K2-1-u3-X14']::text[],true,'{"seq":9,"concept":"K2-1-u3-C9","difficulty":2,"kind":"ox","stem":"일기 제목은 「일기」라고만 써도 내용이 잘 드러나요.","answer":"X","reason_options":[{"t":"제목만 보고 무슨 일인지 알 수 있어야 하니까","correct":true},{"t":"모든 일기는 같은 제목을 쓰니까","mis":"K2-1-u3-X14"}],"mis":"K2-1-u3-X14","explanation":["「일기」라는 제목으로는 무슨 일인지 알 수 없어요.","제목은 내용을 한눈에 보여 줘야 해요.","「처음 딴 상추」처럼 지어요."],"variant_rule":{"alt":[{"stem":"「동생과 만든 눈사람」은 내용이 잘 드러나는 일기 제목이에요.","answer":"O","reason_options":[{"t":"무슨 일이 있었는지 제목만 보아도 알 수 있으니까","correct":true},{"t":"제목이 길면 무조건 좋으니까","mis":"K2-1-u3-X14"}],"explanation":["제목만 보고도 동생과 눈사람을 만든 일임을 알 수 있어요.","길이가 아니라 내용이 드러나는지가 중요해요.","좋은 제목이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#10','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',3,'error','auto','친구들이 하루에 겪은 일을 말했어요. 겪은 일이 아닌 것을 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X12','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 하루에 겪은 일을 말했어요. 겪은 일이 아닌 것을 말한 친구는 누구인가요?","options":[{"t":"태민 — 「즐거움」","correct":true,"mis_target":"K2-1-u3-X12"},{"t":"하린 — 「친구와 줄넘기를 했어.」","mis":"K2-1-u3-X19"},{"t":"지안 — 「도서관에서 책을 읽었어.」","mis":"K2-1-u3-X19"}],"explanation":["「즐거움」은 느낌을 나타내는 낱말이에요.","줄넘기를 한 일, 책을 읽은 일은 겪은 일이에요.","「~했다·봤다·들었다」를 붙여 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 하루에 겪은 일을 말했어요. 겪은 일이 아닌 것을 말한 친구는 누구인가요?","options":[{"t":"로아 — 「지우개」","correct":true,"mis_target":"K2-1-u3-X12"},{"t":"시우 — 「할머니께 전화를 드렸어.」","mis":"K2-1-u3-X19"},{"t":"은솔 — 「길에서 고양이를 봤어.」","mis":"K2-1-u3-X19"}],"explanation":["「지우개」는 물건이에요.","전화를 드린 일, 고양이를 본 일은 겪은 일이에요.","「~했다·봤다·들었다」를 붙여 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#1','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',2,'mc','auto','글감을 정하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10','K2-1-u3-X14']::text[],false,'{"seq":1,"concept":"K2-1-u3-C8","difficulty":2,"kind":"mc","stem":"글감을 정하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"한 것·본 것·들은 것 떠올리기 → 마음이 움직인 일 생각하기 → 가장 인상 깊은 일 고르기","correct":true},{"t":"가장 인상 깊은 일 고르기 → 한 것·본 것·들은 것 떠올리기 → 제목 쓰기","mis":"K2-1-u3-X10"},{"t":"제목 먼저 쓰기 → 아무 일이나 고르기","mis":"K2-1-u3-X14"}],"explanation":["먼저 하루를 떠올리고, 마음이 움직인 일을 찾아요.","그다음 가장 인상 깊은 일 하나를 골라요.","제목은 글감을 정한 뒤 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#2','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C9',2,'mc','auto','두 제목 가운데 내용이 더 잘 드러나는 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":2,"concept":"K2-1-u3-C9","difficulty":2,"kind":"mc","stem":"두 제목 가운데 내용이 더 잘 드러나는 것은 어느 것인가요?","options":[{"t":"「비 오는 날 무지개를 본 날」","correct":true},{"t":"「즐거운 날」","mis":"K2-1-u3-X14"},{"t":"「5월 3일」","mis":"K2-1-u3-X14"}],"explanation":["무슨 일이 있었는지 제목에서 알 수 있어요.","「즐거운 날」은 느낌만, 「5월 3일」은 날짜만 알려 줘요.","제목에는 겪은 일이 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#3','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',3,'mc','auto','글을 읽고 답해 보세요. 서윤이가 「고마워.」라는 말을 들은 일을 글감으로 고른다면, 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X13']::text[],false,'{"seq":3,"concept":"K2-1-u3-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 서윤이가 「고마워.」라는 말을 들은 일을 글감으로 고른다면, 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 말을 듣고 마음이 따뜻해져서 오래 기억하고 싶었기 때문이에요","correct":true},{"t":"오후에 있었던 일이기 때문이에요","mis":"K2-1-u3-X13"},{"t":"날마다 듣는 말이기 때문이에요","mis":"K2-1-u3-X13"}],"explanation":["마음이 움직여 기억하고 싶은 일이 좋은 글감이에요.","몇 시에 있었는지는 까닭이 되지 않아요.","날마다 듣는 말이라면 특별하지 않아요."],"asset":{"type":"passage","lines":["아침 — 엄마가 차려 주신 밥을 먹었다.","낮 — 텃밭에서 처음으로 상추를 땄다.","오후 — 친구에게 「고마워.」라는 말을 들었다.","저녁 — 숙제를 했다."],"title":"서윤이의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#4','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C9',3,'error','auto','「처음으로 바다에서 수영한 날」이 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":4,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「처음으로 바다에서 수영한 날」이 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"민지 — 「여름」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"아린 — 「바다에서 처음 수영한 날」","mis":"K2-1-u3-X19"},{"t":"지호 — 「파도와 첫 수영」","mis":"K2-1-u3-X19"}],"explanation":["「여름」만으로는 무슨 일인지 알 수 없어요.","바다·수영이 드러나야 내용을 알 수 있어요.","아린이와 지호는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#5','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C10',3,'mc','auto','「친구들 앞에서 처음 발표를 했다.」를 겪었을 때 들 수 있는 느낌으로 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":5,"concept":"K2-1-u3-C10","difficulty":3,"kind":"mc","stem":"「친구들 앞에서 처음 발표를 했다.」를 겪었을 때 들 수 있는 느낌으로 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「배가 불러 졸렸다.」","correct":true},{"t":"「떨렸지만 끝까지 해서 뿌듯했다.」","mis":"K2-1-u3-X19"},{"t":"「긴장돼서 목소리가 작아졌다.」","mis":"K2-1-u3-X19"}],"explanation":["「배가 불러 졸렸다」는 발표와 어울리지 않는 느낌이에요.","떨림·뿌듯함·긴장은 발표할 때 들 수 있는 느낌이에요.","「알맞지 않은」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#6','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',3,'ox','auto','「연필」, 「운동장」처럼 물건이나 장소 이름만 써도 겪은 일이 돼요.',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":6,"concept":"K2-1-u3-C8","difficulty":3,"kind":"ox","stem":"「연필」, 「운동장」처럼 물건이나 장소 이름만 써도 겪은 일이 돼요.","answer":"X","reason_options":[{"t":"무엇을 했는지·보았는지·들었는지가 있어야 겪은 일이니까","correct":true},{"t":"이름만 써도 무슨 일인지 다 알 수 있으니까","mis":"K2-1-u3-X12"}],"mis":"K2-1-u3-X12","explanation":["「운동장에서 줄넘기를 했다」처럼 써야 겪은 일이에요.","이름만으로는 무슨 일이 있었는지 알 수 없어요.","「~했다·봤다·들었다」를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#7','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',3,'mc','auto','글을 읽고 답해 보세요. 하준이의 하루를 「한 것·본 것」으로 나눌 때 「본 것」은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":7,"concept":"K2-1-u3-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 하준이의 하루를 「한 것·본 것」으로 나눌 때 「본 것」은 어느 것인가요?","options":[{"t":"맑은 하늘","correct":true},{"t":"줄넘기 열 번","mis":"K2-1-u3-X19"},{"t":"이 닦기","mis":"K2-1-u3-X19"}],"explanation":["창밖으로 맑은 하늘을 「보았다」고 했어요.","줄넘기와 이 닦기는 「한 것」이에요.","어떤 낱말로 끝나는지 보면 나눌 수 있어요."],"asset":{"type":"passage","lines":["아침 — 창밖으로 맑은 하늘을 보았다.","낮 — 운동장에서 처음으로 줄넘기 열 번을 넘었다.","저녁 — 동생과 그림책을 읽었다.","자기 전 — 이를 닦았다."],"title":"하준이의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#8','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',4,'mc','auto','두 친구가 글감을 정했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#9','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',4,'essay','teacher','어제 하루를 떠올려 한 것·본 것·들은 것을 하나씩 쓰고, 그 가운데 일기 글감으로 고를 일과 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C8","difficulty":4,"kind":"essay","stem":"어제 하루를 떠올려 한 것·본 것·들은 것을 하나씩 쓰고, 그 가운데 일기 글감으로 고를 일과 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 것 — 공원 산책, 본 것 — 무지개, 들은 것 — 새소리. 글감: 무지개를 본 일. 까닭: 처음 본 커다란 무지개가 정말 신기했기 때문이에요.","scoring_points":["한 것·본 것·들은 것을 하나씩 썼는가","글감으로 고를 일 하나를 정했는가","그 일을 고른 까닭(마음이 움직인 점)을 썼는가"]},"explanation":["하루 떠올리기.","글감 하나.","고른 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#10','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C9',4,'essay','teacher','「동생과 함께 처음으로 김밥을 만들었다.」가 글감인 일기의 제목을 짓고, 그렇게 지은 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C9","difficulty":4,"kind":"essay","stem":"「동생과 함께 처음으로 김밥을 만들었다.」가 글감인 일기의 제목을 짓고, 그렇게 지은 까닭을 써 보세요.","answer_guide":{"answer":"예: 「동생과 만든 첫 김밥」 — 누구와 무엇을 처음 했는지 제목만 보아도 알 수 있게 지었어요.","scoring_points":["제목을 지었는가","제목에 겪은 일(김밥 만들기)이 드러나는가","지은 까닭을 썼는가"]},"explanation":["제목.","내용이 드러남.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#1','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',1,'mc','auto','일기에서 맨 처음에 쓰는 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],true,'{"seq":1,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에서 맨 처음에 쓰는 것은 어느 것인가요?","options":[{"t":"날짜·요일·날씨","correct":true},{"t":"생각이나 느낌","mis":"K2-1-u3-X10"},{"t":"제목","mis":"K2-1-u3-X10"}],"explanation":["일기는 날짜·요일·날씨부터 써요.","그다음 제목, 이어서 겪은 일과 생각이나 느낌을 써요.","차례를 지켜 쓰면 읽기 쉬워요."],"variant_rule":{"alt":[{"stem":"일기에서 맨 마지막 부분에 담는 것은 어느 것인가요?","options":[{"t":"겪은 일에 대한 생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X10"},{"t":"제목","mis":"K2-1-u3-X10"}],"explanation":["겪은 일을 쓰고 그때의 생각이나 느낌으로 마무리해요.","날짜·날씨와 제목은 앞부분에 써요.","차례: 날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#2','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C10',1,'mc','auto','일기에 생각이나 느낌을 쓸 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u3-X15']::text[],true,'{"seq":2,"concept":"K2-1-u3-C10","difficulty":1,"kind":"mc","stem":"일기에 생각이나 느낌을 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"그때 든 마음을 솔직하게 써요","correct":true},{"t":"친구가 느꼈을 마음을 대신 써요","mis":"K2-1-u3-X15"},{"t":"느낌은 빼고 한 일만 써요","mis":"K2-1-u3-X15"}],"explanation":["일기에는 내 마음을 솔직하게 써요.","남의 느낌을 쓰거나 느낌을 빼면 그날의 내가 드러나지 않아요.","작은 일이라도 솔직하게 쓰면 좋은 일기예요."],"variant_rule":{"alt":[{"stem":"일기에 겪은 일을 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"언제·어디서·누구와 무슨 일이 있었는지 자세하게 써요","correct":true},{"t":"「놀았다.」처럼 짧게만 써요","mis":"K2-1-u3-X16"},{"t":"겪지 않은 일도 지어서 써요","mis":"K2-1-u3-X15"}],"explanation":["언제·어디서·누구와를 쓰면 그날이 자세하게 드러나요.","짧게만 쓰면 무슨 일인지 잘 알 수 없어요.","일기는 내가 겪은 일을 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#3','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',1,'mc','auto','일기에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],true,'{"seq":3,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?","options":[{"t":"친구 전화번호","correct":true},{"t":"겪은 일","mis":"K2-1-u3-X19"},{"t":"생각이나 느낌","mis":"K2-1-u3-X19"}],"explanation":["전화번호는 그날을 돌아보는 내용이 아니에요.","겪은 일과 생각이나 느낌은 꼭 들어가요.","「아닌 것」을 묻는 물음이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 일기에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?","options":[{"t":"내일 시간표","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X19"},{"t":"겪은 일","mis":"K2-1-u3-X19"}],"explanation":["내일 시간표는 그날을 돌아보는 내용이 아니에요.","날짜와 날씨, 겪은 일은 꼭 들어가요.","「아닌 것」을 묻는 물음이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#4','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C10',1,'ox','auto','일기는 작은 일이라도 마음이 움직였다면 좋은 일기가 될 수 있어요.',ARRAY['K2-1-u3-X13']::text[],true,'{"seq":4,"concept":"K2-1-u3-C10","difficulty":1,"kind":"ox","stem":"일기는 작은 일이라도 마음이 움직였다면 좋은 일기가 될 수 있어요.","answer":"O","reason_options":[{"t":"마음이 움직인 일을 솔직하게 쓰면 되니까","correct":true},{"t":"큰일이 있었던 날에만 쓸 수 있으니까","mis":"K2-1-u3-X13"}],"mis":"K2-1-u3-X13","explanation":["작은 일도 마음이 움직였다면 좋은 글감이에요.","특별한 날에만 쓰는 글이 아니에요.","솔직한 생각이나 느낌을 담아요."],"variant_rule":{"alt":[{"stem":"일기에는 겪은 일만 쓰고 생각이나 느낌은 쓰지 않아요.","answer":"X","reason_options":[{"t":"겪은 일에 대한 생각이나 느낌도 함께 써야 하니까","correct":true},{"t":"느낌은 쓰면 안 되니까","mis":"K2-1-u3-X15"}],"explanation":["일기에는 생각이나 느낌을 꼭 함께 써요.","느낌이 빠지면 그날의 내 마음이 남지 않아요.","솔직하게 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#5','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',2,'match','auto','일기 요소와 알맞은 설명을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C7","difficulty":2,"kind":"match","stem":"일기 요소와 알맞은 설명을 이어 보세요.","pairs":[{"l":"날짜와 날씨","r":"맨 처음에 써요"},{"l":"제목","r":"내용을 잘 나타내요"},{"l":"생각이나 느낌","r":"솔직하게 써요"}],"mis":"K2-1-u3-X10","explanation":["날짜와 날씨는 맨 처음에 써요.","제목은 내용을 잘 나타내요.","생각이나 느낌은 솔직하게 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 일기 요소와 알맞은 설명을 이어 보세요.","pairs":[{"l":"겪은 일","r":"언제·어디서 무슨 일인지 자세히 써요"},{"l":"날씨","r":"「포근하게 맑은 날」처럼 생생하게 써요"},{"l":"제목","r":"날짜 다음에 써요"}],"explanation":["겪은 일은 언제·어디서 무슨 일인지 자세히 써요.","날씨도 꾸며 주는 말로 생생하게 쓸 수 있어요.","제목은 날짜·날씨 다음에 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#6','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C10',2,'mc','auto','일기에 쓰면 더 좋은 문장은 어느 것인가요?',ARRAY['K2-1-u3-X03','K2-1-u3-X06']::text[],true,'{"seq":6,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"일기에 쓰면 더 좋은 문장은 어느 것인가요?","options":[{"t":"넓은 운동장에서 줄넘기를 신나게 했다.","correct":true},{"t":"운동장에서 줄넘기를 했다.","mis":"K2-1-u3-X03"},{"t":"줄넘기.","mis":"K2-1-u3-X06"}],"explanation":["「넓은」·「신나게」가 그날 모습을 생생하게 해요.","꾸며 주는 말이 없으면 덜 생생해요.","「줄넘기.」는 문장이 아니에요."],"variant_rule":{"alt":[{"stem":"일기에 쓰면 더 좋은 날씨 표현은 어느 것인가요?","options":[{"t":"포근하게 맑은 날","correct":true},{"t":"맑음","mis":"K2-1-u3-X03"},{"t":"날씨","mis":"K2-1-u3-X09"}],"explanation":["「포근하게」를 넣으니 그날 날씨가 느껴져요.","「맑음」도 되지만 덜 생생해요.","날씨도 꾸며 주는 말로 써 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#7','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',2,'mc','auto','글을 읽고 답해 보세요. 지호의 일기에서 「드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다.」는 일기의 어느 부분인가요?',ARRAY['K2-1-u3-X10']::text[],true,'{"seq":7,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지호의 일기에서 「드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다.」는 일기의 어느 부분인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X10"},{"t":"제목","mis":"K2-1-u3-X10"}],"explanation":["「뿌듯했다」는 지호의 느낌이에요.","날짜·날씨와 제목은 맨 위에 있어요.","일기는 생각이나 느낌으로 마무리해요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 지호의 일기에서 「바람이 살랑살랑 부는 날」은 일기의 어느 부분인가요?","options":[{"t":"날씨","correct":true},{"t":"제목","mis":"K2-1-u3-X10"},{"t":"생각이나 느낌","mis":"K2-1-u3-X10"}],"explanation":["「바람이 살랑살랑 부는 날」은 그날의 날씨예요.","제목은 「처음 탄 두발자전거」예요.","날씨도 꾸며 주는 말로 생생하게 썼어요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#8','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',2,'sa','auto','글을 읽고 답해 보세요. 지호의 일기 제목을 그대로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u3-C7","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 지호의 일기 제목을 그대로 써 보세요.","answer":["처음 탄 두발자전거"],"explanation":["제목은 「처음 탄 두발자전거」예요.","제목은 날짜·날씨 다음에 있어요.","제목만 보아도 무슨 일인지 알 수 있어요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 지호가 자전거 타기를 연습한 곳은 어디인가요? 한 낱말로 써 보세요.","answer":["공원","공원에서"],"explanation":["「공원에서 아빠와 두발자전거 타기를 연습했다.」라고 했어요.","어디서 했는지 써 두어 일기가 자세해요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#9','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C10',2,'ox','auto','글을 읽고 답해 보세요. 다은이의 일기는 겪은 일과 생각이나 느낌이 잘 드러난 일기예요.',ARRAY['K2-1-u3-X15']::text[],true,'{"seq":9,"concept":"K2-1-u3-C10","difficulty":2,"kind":"ox","stem":"글을 읽고 답해 보세요. 다은이의 일기는 겪은 일과 생각이나 느낌이 잘 드러난 일기예요.","answer":"X","reason_options":[{"t":"한 일만 짧게 늘어놓고 생각이나 느낌이 없으니까","correct":true},{"t":"날짜와 날씨가 있으면 좋은 일기니까","mis":"K2-1-u3-X15"}],"mis":"K2-1-u3-X15","explanation":["다은이는 한 일만 짧게 썼어요.","어떤 떡을 왜 샀는지, 그때 마음이 어땠는지 없어요.","생각이나 느낌을 솔직하게 더하면 좋아요."],"asset":{"type":"passage","lines":["6월 2일 월요일, 맑음","제목: 시장","시장에 갔다. 떡을 샀다. 집에 왔다."],"title":"다은이의 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 지호의 일기는 겪은 일과 느낌이 잘 드러난 일기예요.","answer":"O","reason_options":[{"t":"어디서 누구와 무엇을 했는지와 뿌듯한 느낌이 있으니까","correct":true},{"t":"제목이 길어서 좋은 일기니까","mis":"K2-1-u3-X15"}],"explanation":["공원에서 아빠와 연습한 일이 자세해요.","「뿌듯했다」로 느낌을 솔직하게 썼어요.","그래서 그날이 잘 드러나요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#10','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',3,'error','auto','일기를 쓰는 차례를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X10','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C7","difficulty":3,"kind":"error","stem":"일기를 쓰는 차례를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「제목을 맨 먼저 쓰고, 날짜는 맨 끝에 써.」","correct":true,"mis_target":"K2-1-u3-X10"},{"t":"하람 — 「날짜와 날씨를 쓰고 그다음 제목을 써.」","mis":"K2-1-u3-X19"},{"t":"준우 — 「겪은 일을 쓰고 생각이나 느낌을 써.」","mis":"K2-1-u3-X19"}],"explanation":["날짜·날씨가 맨 처음, 그다음이 제목이에요.","날짜를 맨 끝에 쓰지 않아요.","하람이와 준우는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 일기를 쓰는 차례를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「느낌을 먼저 쓰고, 겪은 일은 맨 끝에 날짜와 함께 써.」","correct":true,"mis_target":"K2-1-u3-X10"},{"t":"은솔 — 「맨 처음에 날짜·요일·날씨를 써.」","mis":"K2-1-u3-X19"},{"t":"다은 — 「제목 다음에 겪은 일을 자세히 써.」","mis":"K2-1-u3-X19"}],"explanation":["겪은 일을 쓴 뒤 그에 대한 느낌을 써요.","날짜는 맨 처음에 써요.","은솔이와 다은이는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#1','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C9',2,'mc','auto','글을 읽고 답해 보세요. 다은이의 일기 제목 「시장」을 내용이 잘 드러나게 고친 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":1,"concept":"K2-1-u3-C9","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 다은이의 일기 제목 「시장」을 내용이 잘 드러나게 고친 것은 어느 것인가요?","options":[{"t":"「시장에서 산 떡」","correct":true},{"t":"「월요일」","mis":"K2-1-u3-X14"},{"t":"「일기」","mis":"K2-1-u3-X14"}],"explanation":["무엇을 했는지 제목에서 알 수 있어요.","「월요일」, 「일기」로는 내용을 알 수 없어요.","제목에 겪은 일이 드러나야 해요."],"asset":{"type":"passage","lines":["6월 2일 월요일, 맑음","제목: 시장","시장에 갔다. 떡을 샀다. 집에 왔다."],"title":"다은이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#2','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',2,'mc','auto','글을 읽고 답해 보세요. 다은이의 일기에 덧붙이면 가장 좋은 문장은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X11']::text[],false,'{"seq":2,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 다은이의 일기에 덧붙이면 가장 좋은 문장은 어느 것인가요?","options":[{"t":"「갓 쪄서 말랑말랑한 떡을 먹으니 입안이 따뜻해져 행복했다.」","correct":true},{"t":"「시장에 갔다.」","mis":"K2-1-u3-X15"},{"t":"「내일 시간표: 국어, 수학」","mis":"K2-1-u3-X11"}],"explanation":["떡의 모습과 그때의 느낌이 생생하게 드러나요.","이미 쓴 말을 되풀이하면 나아지지 않아요.","시간표는 일기와 관계없어요."],"asset":{"type":"passage","lines":["6월 2일 월요일, 맑음","제목: 시장","시장에 갔다. 떡을 샀다. 집에 왔다."],"title":"다은이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#3','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 도윤이의 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":3,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 도윤이의 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X09"},{"t":"제목","mis":"K2-1-u3-X09"}],"explanation":["송편을 빚은 일은 썼지만 그때 마음이 없어요.","날짜·날씨와 제목은 맨 위에 있어요.","「빠진 것」을 묻는 물음이에요."],"asset":{"type":"passage","lines":["4월 18일 금요일, 구름 조금","제목: 할머니와 만든 송편","저녁에 할머니 댁 부엌에서 송편을 빚었다.","할머니께서 반죽을 동글동글 굴리는 방법을 알려 주셨다."],"title":"도윤이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#4','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 시우의 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 시우의 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"날짜·요일·날씨","correct":true},{"t":"생각이나 느낌","mis":"K2-1-u3-X09"},{"t":"겪은 일","mis":"K2-1-u3-X09"}],"explanation":["시우는 맨 처음에 쓸 날짜·요일·날씨를 빠뜨렸어요.","「무척 신기했다」는 느낌이 있어요.","무지개를 본 겪은 일도 있어요."],"asset":{"type":"passage","lines":["제목: 운동장의 무지개","점심시간에 운동장에서 커다란 무지개를 보았다.","일곱 빛깔이 또렷해서 친구들과 와 하고 소리쳤다.","무지개를 처음 가까이 본 것 같아 무척 신기했다."],"title":"시우의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#5','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',3,'error','auto','친구들이 지호의 일기를 읽고 잘된 점을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X07','K2-1-u3-X19']::text[],false,'{"seq":5,"concept":"K2-1-u3-C10","difficulty":3,"kind":"error","stem":"친구들이 지호의 일기를 읽고 잘된 점을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도담 — 「엄마랑 자전거를 탄 일을 썼어.」","correct":true,"mis_target":"K2-1-u3-X07"},{"t":"하늘 — 「어디서 누구와 했는지 자세히 썼어.」","mis":"K2-1-u3-X19"},{"t":"로아 — 「뿌듯한 마음을 솔직하게 썼어.」","mis":"K2-1-u3-X19"}],"explanation":["지호는 아빠와 연습했어요.","글에 없는 내용을 말하면 안 돼요.","하늘이와 로아는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#6','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',3,'ox','auto','글을 읽고 답해 보세요. 도윤이의 일기에 「할머니처럼 반죽을 동글동글 굴리니 송편이 예쁘게 빚어져서 무척 뿌듯했다.」를 덧붙이면 더 좋은 일기가 돼요.',ARRAY['K2-1-u3-X15']::text[],false,'{"seq":6,"concept":"K2-1-u3-C10","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 도윤이의 일기에 「할머니처럼 반죽을 동글동글 굴리니 송편이 예쁘게 빚어져서 무척 뿌듯했다.」를 덧붙이면 더 좋은 일기가 돼요.","answer":"O","reason_options":[{"t":"빠졌던 생각이나 느낌이 생겨 그날 마음이 드러나니까","correct":true},{"t":"글자가 많아질수록 좋은 일기니까","mis":"K2-1-u3-X15"}],"mis":"K2-1-u3-X15","explanation":["도윤이의 일기에는 느낌이 빠져 있었어요.","덧붙인 문장에 뿌듯한 마음이 담겨요.","길이가 아니라 느낌이 생겨서 좋아진 거예요."],"asset":{"type":"passage","lines":["4월 18일 금요일, 구름 조금","제목: 할머니와 만든 송편","저녁에 할머니 댁 부엌에서 송편을 빚었다.","할머니께서 반죽을 동글동글 굴리는 방법을 알려 주셨다."],"title":"도윤이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#7','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',3,'mc','auto','일기를 다 쓰고 스스로 점검할 때 살펴볼 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":7,"concept":"K2-1-u3-C10","difficulty":3,"kind":"mc","stem":"일기를 다 쓰고 스스로 점검할 때 살펴볼 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글씨를 가장 크게 썼나요?","correct":true},{"t":"날짜와 요일을 정확하게 썼나요?","mis":"K2-1-u3-X19"},{"t":"겪은 일에 대한 생각이나 느낌을 솔직하게 썼나요?","mis":"K2-1-u3-X19"}],"explanation":["글씨 크기는 점검할 내용이 아니에요.","날짜·요일과 생각이나 느낌은 꼭 점검해요.","「알맞지 않은」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#8','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 운동회 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#9','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',4,'essay','teacher','다은이의 일기 「시장에 갔다. 떡을 샀다. 집에 왔다.」를 언제·누구와·어떤 떡이었는지, 그리고 그때의 느낌이 드러나게 고쳐 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C10","difficulty":4,"kind":"essay","stem":"다은이의 일기 「시장에 갔다. 떡을 샀다. 집에 왔다.」를 언제·누구와·어떤 떡이었는지, 그리고 그때의 느낌이 드러나게 고쳐 써 보세요.","answer_guide":{"answer":"예: 아침에 엄마와 시장에 갔다. 김이 모락모락 나는 말랑말랑한 꿀떡을 샀다. 집에 와서 먹으니 달콤해서 기분이 정말 좋았다.","scoring_points":["언제·누구와 같은 내용을 더했는가","꾸며 주는 말로 떡이나 장면을 생생하게 나타냈는가","그때의 생각이나 느낌을 솔직하게 썼는가"]},"explanation":["언제·누구와.","꾸며 주는 말.","느낌."],"asset":{"type":"passage","lines":["6월 2일 월요일, 맑음","제목: 시장","시장에 갔다. 떡을 샀다. 집에 왔다."],"title":"다은이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#10','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C7',4,'essay','teacher','최근에 겪은 인상 깊은 일로 짧은 일기를 써 보세요. 날짜·요일·날씨, 제목, 겪은 일, 생각이나 느낌을 모두 넣어요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C7","difficulty":4,"kind":"essay","stem":"최근에 겪은 인상 깊은 일로 짧은 일기를 써 보세요. 날짜·요일·날씨, 제목, 겪은 일, 생각이나 느낌을 모두 넣어요.","answer_guide":{"answer":"예: 10월 9일 금요일, 하늘이 높고 파란 날 / 제목: 처음 따 본 밤 / 할아버지와 뒷산에서 밤을 주웠다. 가시가 뾰족뾰족해서 조심조심 껍질을 벌렸다. 반짝반짝 윤이 나는 밤을 보니 무척 신기했다.","scoring_points":["날짜·요일·날씨와 제목을 차례대로 썼는가","언제·어디서·누구와 무슨 일인지 자세히 썼는가","생각이나 느낌을 솔직하게 썼는가"]},"explanation":["날짜·날씨·제목.","자세한 겪은 일.","솔직한 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#1','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',1,'mc','auto','식물이나 물건을 자세히 살펴보고 쓰는 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],true,'{"seq":1,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"식물이나 물건을 자세히 살펴보고 쓰는 일기는 어느 것인가요?","options":[{"t":"관찰 일기","correct":true},{"t":"요리 일기","mis":"K2-1-u3-X17"},{"t":"그림 일기","mis":"K2-1-u3-X17"}],"explanation":["자세히 살펴본 모습을 쓰는 일기는 관찰 일기예요.","요리 일기는 음식을 만든 차례를 써요.","그림 일기는 그림과 글로 함께 나타내요."],"variant_rule":{"alt":[{"stem":"음식을 만든 차례를 쓰는 일기는 어느 것인가요?","options":[{"t":"요리 일기","correct":true},{"t":"관찰 일기","mis":"K2-1-u3-X17"},{"t":"그림 일기","mis":"K2-1-u3-X17"}],"explanation":["음식을 만든 차례를 쓰는 일기는 요리 일기예요.","관찰 일기는 자세히 살핀 모습을 써요.","그림 일기는 그림과 글로 함께 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#2','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C4',1,'mc','auto','방울토마토를 관찰하고 쓰려고 해요. 방울토마토에 어울리는 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],true,'{"seq":2,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"방울토마토를 관찰하고 쓰려고 해요. 방울토마토에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"동그란","correct":true},{"t":"시끄러운","mis":"K2-1-u3-X04"},{"t":"졸린","mis":"K2-1-u3-X04"}],"explanation":["방울토마토의 모양에는 「동그란」이 어울려요.","방울토마토는 시끄럽거나 졸리지 않아요.","관찰한 모습에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🍅"},"variant_rule":{"alt":[{"stem":"상추 잎을 관찰하고 쓰려고 해요. 상추 잎에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"넓적한","correct":true},{"t":"뾰족한 가시가 난","mis":"K2-1-u3-X04"},{"t":"달리는","mis":"K2-1-u3-X04"}],"explanation":["상추 잎의 모양에는 「넓적한」이 어울려요.","상추 잎에는 가시가 없고, 달리지도 않아요.","관찰한 모습에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🥬"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#3','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',1,'mc','auto','식물을 관찰할 때 살펴볼 점은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],true,'{"seq":3,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"식물을 관찰할 때 살펴볼 점은 어느 것인가요?","options":[{"t":"잎의 색과 모양","correct":true},{"t":"식물의 가격","mis":"K2-1-u3-X17"},{"t":"화분을 만든 사람","mis":"K2-1-u3-X17"}],"explanation":["색과 모양은 눈으로 살펴 알 수 있어요.","가격이나 만든 사람은 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 식물을 관찰할 때 살펴볼 점은 어느 것인가요?","options":[{"t":"꽃의 냄새","correct":true},{"t":"화분을 산 가게 이름","mis":"K2-1-u3-X17"},{"t":"식물의 값","mis":"K2-1-u3-X17"}],"explanation":["꽃의 냄새는 코로 맡아 알 수 있어요.","가게 이름이나 값은 관찰해서 알 수 없어요.","여러 감각으로 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#4','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',1,'ox','auto','관찰할 때는 눈뿐 아니라 코와 손으로도 살펴볼 수 있어요.',ARRAY['K2-1-u3-X17']::text[],true,'{"seq":4,"concept":"K2-1-u3-C11","difficulty":1,"kind":"ox","stem":"관찰할 때는 눈뿐 아니라 코와 손으로도 살펴볼 수 있어요.","answer":"O","reason_options":[{"t":"냄새와 촉감도 관찰한 모습이니까","correct":true},{"t":"관찰은 눈으로만 하는 것이니까","mis":"K2-1-u3-X17"}],"mis":"K2-1-u3-X17","explanation":["색·모양은 눈으로, 냄새는 코로, 촉감은 손으로 살펴요.","여러 감각을 쓰면 더 자세히 쓸 수 있어요.","그래서 관찰 일기가 생생해져요."],"variant_rule":{"alt":[{"stem":"관찰 일기에는 관찰한 모습만 쓰고 생각이나 느낌은 쓰지 않아요.","answer":"X","reason_options":[{"t":"관찰한 모습에 생각이나 느낌을 더하면 더 좋은 일기니까","correct":true},{"t":"일기에 느낌을 쓰면 안 되니까","mis":"K2-1-u3-X09"}],"explanation":["관찰 일기에도 생각이나 느낌을 써요.","「무척 신기했다」처럼 마음을 더해요.","그래야 일기가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#5','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',2,'match','auto','일기 종류와 쓰는 내용을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C11","difficulty":2,"kind":"match","stem":"일기 종류와 쓰는 내용을 알맞게 이어 보세요.","pairs":[{"l":"관찰 일기","r":"자세히 살핀 모습"},{"l":"요리 일기","r":"음식을 만든 차례"},{"l":"그림 일기","r":"그림과 글"}],"mis":"K2-1-u3-X17","explanation":["관찰 일기는 자세히 살핀 모습을 써요.","요리 일기는 음식을 만든 차례를 써요.","그림 일기는 그림과 글로 함께 나타내요."],"variant_rule":{"alt":[{"stem":"관찰할 것과 알 수 있는 감각을 알맞게 이어 보세요.","pairs":[{"l":"잎의 색","r":"눈으로 봐요"},{"l":"꽃의 향기","r":"코로 맡아요"},{"l":"잎의 보들보들함","r":"손으로 만져요"}],"explanation":["색은 눈으로 봐서 알아요.","향기는 코로 맡아서 알아요.","보들보들한 촉감은 손으로 만져서 알아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#6','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',2,'mc','auto','글을 읽고 답해 보세요. 이 관찰 일기에서 「냄새」를 살펴본 문장은 어느 것인가요?',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":6,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 관찰 일기에서 「냄새」를 살펴본 문장은 어느 것인가요?","options":[{"t":"코를 대 보니 풀 냄새가 살짝 났다.","correct":true},{"t":"사흘 만에 하얀 뿌리가 쏙 나왔다.","mis":"K2-1-u3-X07"},{"t":"내일은 얼마나 자랄지 무척 궁금하다.","mis":"K2-1-u3-X07"}],"explanation":["코를 대어 냄새를 맡았어요.","뿌리 문장은 눈으로 본 모습이에요.","「궁금하다」는 느낌이에요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 이 관찰 일기에서 「생각이나 느낌」이 드러난 문장은 어느 것인가요?","options":[{"t":"내일은 얼마나 자랄지 무척 궁금하다.","correct":true},{"t":"물에 적신 솜 위에 콩을 올려 두었다.","mis":"K2-1-u3-X07"},{"t":"사흘 만에 하얀 뿌리가 쏙 나왔다.","mis":"K2-1-u3-X07"}],"explanation":["「궁금하다」는 글쓴이의 마음이에요.","다른 두 문장은 한 일과 본 모습이에요.","관찰 일기에도 느낌을 써요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#7','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',2,'mc','auto','글을 읽고 답해 보세요. 요리 일기에서 가장 먼저 한 일은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":7,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 요리 일기에서 가장 먼저 한 일은 무엇인가요?","options":[{"t":"손을 깨끗이 씻었다","correct":true},{"t":"밥을 동글동글 뭉쳤다","mis":"K2-1-u3-X07"},{"t":"가족이 맛있게 먹었다","mis":"K2-1-u3-X07"}],"explanation":["「먼저 손을 깨끗이 씻었다.」라고 했어요.","밥을 뭉친 것은 그다음이에요.","요리 일기는 만든 차례대로 써요."],"asset":{"type":"passage","lines":["제목: 내가 만든 주먹밥","먼저 손을 깨끗이 씻었다.","따뜻한 밥에 김 가루와 깨를 솔솔 뿌려 섞었다.","손에 물을 묻히고 밥을 동글동글 뭉쳤다.","내가 만든 주먹밥을 가족이 맛있게 먹어서 뿌듯했다."],"title":"요리 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 요리 일기에서 김 가루와 깨를 뿌린 다음에 한 일은 무엇인가요?","options":[{"t":"손에 물을 묻히고 밥을 뭉쳤다","correct":true},{"t":"손을 깨끗이 씻었다","mis":"K2-1-u3-X07"},{"t":"콩을 솜 위에 올렸다","mis":"K2-1-u3-X07"}],"explanation":["섞은 다음 밥을 동글동글 뭉쳤어요.","손 씻기는 맨 처음이에요.","콩 이야기는 이 글에 없어요."],"asset":{"type":"passage","lines":["제목: 내가 만든 주먹밥","먼저 손을 깨끗이 씻었다.","따뜻한 밥에 김 가루와 깨를 솔솔 뿌려 섞었다.","손에 물을 묻히고 밥을 동글동글 뭉쳤다.","내가 만든 주먹밥을 가족이 맛있게 먹어서 뿌듯했다."],"title":"요리 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#8','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',2,'sa','auto','글을 읽고 답해 보세요. 오늘 벌어진 떡잎은 몇 장인가요? 숫자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 오늘 벌어진 떡잎은 몇 장인가요? 숫자로 써 보세요.","answer":["2","2장","두","두 장"],"explanation":["「연두색 떡잎 두 장이 동그랗게 벌어졌다.」라고 했어요.","몇 장인지 세어 쓰면 관찰이 자세해져요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 콩을 올려 두고 며칠 만에 뿌리가 나왔나요? 숫자로 써 보세요.","answer":["3","3일","사흘","삼"],"explanation":["「사흘 만에 하얀 뿌리가 쏙 나왔다.」라고 했어요.","사흘은 3일이에요.","날짜를 세어 쓰면 관찰이 자세해져요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#9','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C4',2,'ox','auto','관찰 일기에 「길쭉한 잎이 바람에 살랑살랑 흔들린다.」처럼 꾸며 주는 말을 넣으면 모습이 더 생생해져요.',ARRAY['K2-1-u3-X03']::text[],true,'{"seq":9,"concept":"K2-1-u3-C4","difficulty":2,"kind":"ox","stem":"관찰 일기에 「길쭉한 잎이 바람에 살랑살랑 흔들린다.」처럼 꾸며 주는 말을 넣으면 모습이 더 생생해져요.","answer":"O","reason_options":[{"t":"잎의 모양과 움직임이 떠오르니까","correct":true},{"t":"꾸며 주는 말은 관찰 일기에 쓰면 안 되니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「길쭉한」·「살랑살랑」이 잎의 모습을 보여 줘요.","관찰 일기에도 꾸며 주는 말을 넣어요.","그래서 읽는 사람도 모습을 떠올려요."],"variant_rule":{"alt":[{"stem":"관찰 일기에는 「잎이 있다.」처럼 짧게만 쓰는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"모양·색을 꾸며 주는 말로 자세히 써야 모습이 드러나니까","correct":true},{"t":"짧을수록 관찰을 잘한 것이니까","mis":"K2-1-u3-X03"}],"explanation":["「잎이 있다.」로는 어떤 잎인지 알 수 없어요.","「넓적한 초록 잎」처럼 자세히 써요.","꾸며 주는 말이 관찰한 모습을 살려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#10','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',3,'error','auto','친구들이 관찰할 점을 말했어요. 관찰할 점이 아닌 것을 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X17','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C11","difficulty":3,"kind":"error","stem":"친구들이 관찰할 점을 말했어요. 관찰할 점이 아닌 것을 말한 친구는 누구인가요?","options":[{"t":"지우 — 「화분 값이 얼마인지 볼래.」","correct":true,"mis_target":"K2-1-u3-X17"},{"t":"태민 — 「잎을 만져서 촉감을 알아볼래.」","mis":"K2-1-u3-X19"},{"t":"하린 — 「꽃에 코를 대 보고 냄새를 맡을래.」","mis":"K2-1-u3-X19"}],"explanation":["화분 값은 관찰해서 알 수 없어요.","촉감과 냄새는 손과 코로 관찰해요.","태민이와 하린이는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 관찰할 점을 말했어요. 관찰할 점이 아닌 것을 말한 친구는 누구인가요?","options":[{"t":"예린 — 「이 씨앗을 판 사람 이름을 쓸래.」","correct":true,"mis_target":"K2-1-u3-X17"},{"t":"아린 — 「뿌리가 몇 개인지 세어 볼래.」","mis":"K2-1-u3-X19"},{"t":"도윤 — 「줄기 색을 살펴볼래.」","mis":"K2-1-u3-X19"}],"explanation":["판 사람 이름은 관찰해서 알 수 없어요.","뿌리 수와 줄기 색은 눈으로 살펴요.","아린이와 도윤이는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#1','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',2,'mc','auto','「동그란 방울토마토가 조롱조롱 열렸다.」는 무엇을 살펴보고 쓴 문장인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":1,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"「동그란 방울토마토가 조롱조롱 열렸다.」는 무엇을 살펴보고 쓴 문장인가요?","options":[{"t":"방울토마토의 모양과 열린 모습","correct":true},{"t":"방울토마토의 맛","mis":"K2-1-u3-X17"},{"t":"방울토마토를 산 곳","mis":"K2-1-u3-X17"}],"explanation":["「동그란」은 모양, 「조롱조롱」은 열린 모습이에요.","맛이나 산 곳은 이 문장에 없어요.","눈으로 관찰한 모습을 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#2','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',2,'mc','auto','글을 읽고 답해 보세요. 이 글이 요리 일기인 까닭은 무엇인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":2,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글이 요리 일기인 까닭은 무엇인가요?","options":[{"t":"주먹밥을 만든 차례를 썼기 때문이에요","correct":true},{"t":"식물이 자라는 모습을 살폈기 때문이에요","mis":"K2-1-u3-X17"},{"t":"그림을 함께 그렸기 때문이에요","mis":"K2-1-u3-X17"}],"explanation":["손 씻기 → 섞기 → 뭉치기, 만든 차례가 있어요.","식물을 살핀 것은 관찰 일기예요.","그림과 글은 그림 일기예요."],"asset":{"type":"passage","lines":["제목: 내가 만든 주먹밥","먼저 손을 깨끗이 씻었다.","따뜻한 밥에 김 가루와 깨를 솔솔 뿌려 섞었다.","손에 물을 묻히고 밥을 동글동글 뭉쳤다.","내가 만든 주먹밥을 가족이 맛있게 먹어서 뿌듯했다."],"title":"요리 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#3','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',3,'mc','auto','글을 읽고 답해 보세요. 관찰 일기에서 눈으로 살펴본 것만 모은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":3,"concept":"K2-1-u3-C11","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 관찰 일기에서 눈으로 살펴본 것만 모은 것은 어느 것인가요?","options":[{"t":"하얀 뿌리 · 연두색 떡잎 · 동그랗게 벌어짐","correct":true},{"t":"풀 냄새 · 하얀 뿌리","mis":"K2-1-u3-X17"},{"t":"궁금함 · 떡잎","mis":"K2-1-u3-X17"}],"explanation":["색과 모양은 눈으로 살펴본 거예요.","풀 냄새는 코로 맡은 거예요.","「궁금하다」는 느낌이에요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#4','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',3,'error','auto','친구들이 일기 종류와 쓸 내용을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X17','K2-1-u3-X19']::text[],false,'{"seq":4,"concept":"K2-1-u3-C11","difficulty":3,"kind":"error","stem":"친구들이 일기 종류와 쓸 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「요리 일기에는 강낭콩이 자란 모습을 날마다 써.」","correct":true,"mis_target":"K2-1-u3-X17"},{"t":"하준 — 「관찰 일기에는 자세히 살핀 모습을 써.」","mis":"K2-1-u3-X19"},{"t":"서아 — 「그림 일기에는 그림과 글을 함께 써.」","mis":"K2-1-u3-X19"}],"explanation":["식물이 자란 모습은 관찰 일기에 써요.","요리 일기에는 음식을 만든 차례를 써요.","하준이와 서아는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#5','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',3,'ox','auto','글을 읽고 답해 보세요. 요리 일기에서 「밥을 동글동글 뭉쳤다」를 「손을 깨끗이 씻었다」보다 먼저 쓰면 차례가 더 잘 드러나요.',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":5,"concept":"K2-1-u3-C11","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 요리 일기에서 「밥을 동글동글 뭉쳤다」를 「손을 깨끗이 씻었다」보다 먼저 쓰면 차례가 더 잘 드러나요.","answer":"X","reason_options":[{"t":"손을 먼저 씻고 밥을 뭉쳤으니 한 차례대로 써야 하니까","correct":true},{"t":"요리 일기는 차례가 상관없으니까","mis":"K2-1-u3-X07"}],"mis":"K2-1-u3-X07","explanation":["요리 일기는 만든 차례대로 써요.","순서를 바꾸면 읽는 사람이 따라 하기 어려워요.","손 씻기가 맨 처음이에요."],"asset":{"type":"passage","lines":["제목: 내가 만든 주먹밥","먼저 손을 깨끗이 씻었다.","따뜻한 밥에 김 가루와 깨를 솔솔 뿌려 섞었다.","손에 물을 묻히고 밥을 동글동글 뭉쳤다.","내가 만든 주먹밥을 가족이 맛있게 먹어서 뿌듯했다."],"title":"요리 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#6','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C4',3,'mc','auto','보들보들한 강아지풀을 손으로 만져 본 느낌에 가장 어울리는 문장은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":6,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"보들보들한 강아지풀을 손으로 만져 본 느낌에 가장 어울리는 문장은 어느 것인가요?","options":[{"t":"「복슬복슬한 이삭이 손바닥을 간질간질 간질였다.」","correct":true},{"t":"「딱딱한 이삭이 손바닥을 찔렀다.」","mis":"K2-1-u3-X04"},{"t":"「시끄러운 이삭이 손을 간질였다.」","mis":"K2-1-u3-X04"}],"explanation":["「복슬복슬한」·「간질간질」이 부드러운 촉감을 살려요.","강아지풀은 딱딱하지 않아요.","이삭은 소리를 내지 않아요."],"asset":{"type":"scene","icon":"🌾✋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#7','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',3,'mc','auto','관찰 일기를 쓸 때 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":7,"concept":"K2-1-u3-C11","difficulty":3,"kind":"mc","stem":"관찰 일기를 쓸 때 알맞지 않은 것은 어느 것인가요?","options":[{"t":"관찰하지 않은 모습을 지어내어 써요","correct":true},{"t":"날마다 달라진 점을 비교해 써요","mis":"K2-1-u3-X19"},{"t":"색·모양·냄새를 꾸며 주는 말로 써요","mis":"K2-1-u3-X19"}],"explanation":["관찰 일기는 직접 살펴본 것을 써요.","달라진 점을 비교하면 자라는 모습이 드러나요.","「알맞지 않은」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#8','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',4,'mc','auto','두 친구가 같은 화분의 상추를 관찰하고 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#9','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',4,'essay','teacher','교실이나 집에 있는 식물·물건 하나를 골라 관찰 일기를 써 보세요. 제목, 관찰한 모습 두 가지(색·모양·냄새·촉감 가운데), 생각이나 느낌을 넣어요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C11","difficulty":4,"kind":"essay","stem":"교실이나 집에 있는 식물·물건 하나를 골라 관찰 일기를 써 보세요. 제목, 관찰한 모습 두 가지(색·모양·냄새·촉감 가운데), 생각이나 느낌을 넣어요.","answer_guide":{"answer":"예: 제목: 반짝이는 어항 / 어항 속 금붕어는 주황색 비늘이 반짝반짝 빛났다. 꼬리를 살랑살랑 흔들며 헤엄쳤다. 금붕어가 내 손가락을 따라올 때 무척 신기했다.","scoring_points":["제목을 썼는가","관찰한 모습을 두 가지 감각(색·모양·냄새·촉감)으로 꾸며 주는 말을 넣어 썼는가","생각이나 느낌을 썼는가"]},"explanation":["제목.","두 가지 감각 + 꾸며 주는 말.","느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#10','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',4,'essay','teacher','좋아하는 간단한 음식(예: 샌드위치·과일 꼬치)을 만든 요리 일기를 써 보세요. 만든 차례를 세 단계 이상 쓰고, 만들고 난 느낌을 써요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C11","difficulty":4,"kind":"essay","stem":"좋아하는 간단한 음식(예: 샌드위치·과일 꼬치)을 만든 요리 일기를 써 보세요. 만든 차례를 세 단계 이상 쓰고, 만들고 난 느낌을 써요.","answer_guide":{"answer":"예: 제목: 알록달록 과일 꼬치 / 먼저 손을 씻었다. 딸기와 바나나를 먹기 좋게 잘랐다. 꼬치에 빨강, 노랑 차례로 꽂았다. 알록달록한 꼬치를 보니 먹기 아까울 만큼 예뻐서 뿌듯했다.","scoring_points":["만든 음식이 드러나는 제목을 썼는가","만든 차례를 세 단계 이상 차례대로 썼는가","만들고 난 생각이나 느낌을 썼는가"]},"explanation":["제목.","차례 세 단계.","느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#1','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#2','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C2',1,'mc','auto','「예쁜 꽃이 활짝 피었다.」에서 「활짝」이 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C2","difficulty":1,"kind":"mc","stem":"「예쁜 꽃이 활짝 피었다.」에서 「활짝」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"피었다","correct":true},{"t":"예쁜","mis":"K2-1-u3-X02"},{"t":"꽃이","mis":"K2-1-u3-X02"}],"explanation":["「활짝」은 어떻게 피었는지 알려 줘요.","꾸며 주는 말을 뒤의 말에 붙여 읽어 보면 짝이 보여요.","「활짝 피었다」처럼 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#3','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C4',1,'mc','auto','사과 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"사과 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?","options":[{"t":"붉은","correct":true},{"t":"시끄러운","mis":"K2-1-u3-X04"},{"t":"졸린","mis":"K2-1-u3-X04"}],"explanation":["사과의 색에는 「붉은」이 어울려요.","다른 말은 사과의 모습과 어울리지 않아요.","대상을 잘 살펴 색·모양·움직임에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🍎"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#4','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C7',1,'mc','auto','일기는 어떤 글인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기는 어떤 글인가요?","options":[{"t":"그날 겪은 일 가운데 기억하고 싶은 일과 생각이나 느낌을 쓴 글","correct":true},{"t":"하루에 한 일을 모두 적는 글","mis":"K2-1-u3-X09"},{"t":"내일 할 일을 적는 글","mis":"K2-1-u3-X09"}],"explanation":["일기는 기억하고 싶은 일을 골라 써요.","다른 것은 일기에 맞지 않아요.","일기는 겪은 일과 생각이나 느낌을 담는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#5','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"운동장에서 줄넘기를 했다","correct":true},{"t":"줄넘기","mis":"K2-1-u3-X12"},{"t":"기쁨","mis":"K2-1-u3-X12"}],"explanation":["「운동장에서 줄넘기를 했다」는 내가 겪은 일이에요.","줄넘기는 물건, 기쁨은 느낌을 나타내는 낱말이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#6','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C9',1,'mc','auto','「처음 줄넘기를 성공한」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":6,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"「처음 줄넘기를 성공한」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄넘기를 처음 성공한 날","correct":true},{"t":"오늘 날씨","mis":"K2-1-u3-X14"},{"t":"그냥 하루","mis":"K2-1-u3-X14"}],"explanation":["「줄넘기를 처음 성공한 날」만 보아도 무슨 일인지 알 수 있어요.","「오늘 날씨」, 「그냥 하루」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#7','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C12',1,'mc','auto','바람개비가 돌아가는 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u3-X18']::text[],false,'{"seq":7,"concept":"K2-1-u3-C12","difficulty":1,"kind":"mc","stem":"바람개비가 돌아가는 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"빙글빙글","correct":true},{"t":"바람개비","mis":"K2-1-u3-X18"},{"t":"돌아간다","mis":"K2-1-u3-X18"}],"explanation":["「빙글빙글」은 둥글게 도는 모양을 흉내 낸 말이에요.","바람개비·돌아간다는 흉내 내는 말이 아니에요.","따라 했을 때 모습·소리·느낌이 떠오르면 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#8','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C11',1,'mc','auto','식물이나 물건을 자세히 살펴보고 쓰는 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"식물이나 물건을 자세히 살펴보고 쓰는 일기는 어느 것인가요?","options":[{"t":"관찰 일기","correct":true},{"t":"요리 일기","mis":"K2-1-u3-X17"},{"t":"그림 일기","mis":"K2-1-u3-X17"}],"explanation":["자세히 살핀 모습을 쓰는 일기는 관찰 일기예요.","다른 일기는 쓰는 내용이 달라요.","관찰 일기·요리 일기·그림 일기의 쓰는 내용을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#9','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C3',2,'ox','auto','「비가 내린다.」보다 「비가 주룩주룩 세차게 내린다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"ox","stem":"「비가 내린다.」보다 「비가 주룩주룩 세차게 내린다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「주룩주룩」·「세차게」가 비 내리는 모습을 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#10','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C5',2,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"노란 우산을 쓰고 천천히 걷는다.","correct":true},{"t":"노란 우산.","mis":"K2-1-u3-X06"},{"t":"노란 우산을 맛있게 시끄럽게 쓴다.","mis":"K2-1-u3-X05"}],"explanation":["「노란 우산을 쓰고 천천히 걷는다.」는 어울리는 꾸며 주는 말을 넣어 끝까지 쓴 문장이에요.","「노란 우산.」은 끝맺지 않았어요.","「노란 우산을 맛있게 시끄럽게 쓴다.」는 어울리지 않는 말이 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#11','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 여름이 되자 일어난 일은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":11,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 여름이 되자 일어난 일은 무엇인가요?","options":[{"t":"커다란 해바라기가 활짝 피었어요","correct":true},{"t":"새싹이 쏙 돋아났어요","mis":"K2-1-u3-X07"},{"t":"씨앗이 흙 속에서 잠을 잤어요","mis":"K2-1-u3-X07"}],"explanation":["「여름이 되자 커다란 해바라기가 활짝 피었어요.」라고 했어요.","다른 것은 글에 없거나 차례가 달라요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#12','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C7',2,'mc','auto','일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":12,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌","correct":true},{"t":"제목 → 겪은 일 → 생각이나 느낌 → 날짜·날씨","mis":"K2-1-u3-X10"},{"t":"생각이나 느낌 → 겪은 일 → 날짜·날씨 → 제목","mis":"K2-1-u3-X10"}],"explanation":["날짜·날씨가 맨 처음, 그다음 제목을 써요.","이어서 겪은 일, 마지막에 생각이나 느낌을 써요.","차례를 지키면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#13','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C10',2,'mc','auto','「처음 줄넘기 성공」을 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X16']::text[],false,'{"seq":13,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"「처음 줄넘기 성공」을 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?","options":[{"t":"처음으로 줄넘기를 넘어서 정말 뿌듯했다.","correct":true},{"t":"줄넘기를 했다.","mis":"K2-1-u3-X15"},{"t":"했다.","mis":"K2-1-u3-X16"}],"explanation":["「처음으로 줄넘기를 넘어서 정말 뿌듯했다」에 그때의 마음이 담겨 있어요.","다른 문장은 한 일만 쓰거나 무슨 일인지 드러나지 않아요.","겪은 일에 솔직한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#14','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C12',2,'match','auto','흉내 내는 말과 어울리는 모습을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u3-C12","difficulty":2,"kind":"match","stem":"흉내 내는 말과 어울리는 모습을 이어 보세요.","pairs":[{"l":"빙글빙글","r":"바람개비가 돈다"},{"l":"톡톡","r":"감꽃이 떨어진다"},{"l":"반짝반짝","r":"별이 빛난다"}],"mis":"K2-1-u3-X18","explanation":["「빙글빙글」은 「바람개비가 돈다」에 어울려요.","「톡톡」은 「감꽃이 떨어진다」에 어울려요.","「반짝반짝」은 「별이 빛난다」에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#15','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C11',2,'mc','auto','상추를 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":15,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"상추를 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"잎의 색과 모양","correct":true},{"t":"상추의 값","mis":"K2-1-u3-X17"},{"t":"상추를 판 가게","mis":"K2-1-u3-X17"}],"explanation":["색과 모양은 눈으로 살펴 알 수 있어요.","상추의 값·상추를 판 가게는 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#16','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C8',2,'mc','auto','하준이의 하루예요. 일기 글감으로 가장 알맞은 일은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#17','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C2',3,'error','auto','「귀여운 동생이 새 신발을 신고 깡충깡충 뛰었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":17,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「귀여운 동생이 새 신발을 신고 깡충깡충 뛰었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"시우 — 「귀여운 → 신발」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"다은 — 「새 → 신발」","mis":"K2-1-u3-X19"},{"t":"로아 — 「깡충깡충 → 뛰었다」","mis":"K2-1-u3-X19"}],"explanation":["「귀여운」은 동생을 꾸며요.","다른 두 친구는 바르게 이었어요.","꾸며 주는 말을 바로 뒤의 말에 붙여 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#18','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":18,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"날짜·요일·날씨","correct":true},{"t":"생각이나 느낌","mis":"K2-1-u3-X09"},{"t":"제목","mis":"K2-1-u3-X09"}],"explanation":["하람이는 맨 처음에 쓸 날짜·요일·날씨를 빠뜨렸어요.","다른 두 가지는 일기에 들어 있어요.","「빠진 것」을 묻는 물음 — 네 손가락을 접으며 확인해요."],"asset":{"type":"passage","lines":["제목: 처음 끓인 라면","저녁에 아빠와 부엌에서 라면을 끓였다.","보글보글 끓는 물에 면을 넣고 젓가락으로 살살 저었다.","내가 끓인 라면이라 더 맛있게 느껴졌다."],"title":"하람이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#19','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C4',3,'mc','auto','바닷가 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":19,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"바닷가 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「달콤한 파도가 철썩 친다.」","correct":true},{"t":"「하얀 갈매기가 높이 난다.」","mis":"K2-1-u3-X19"},{"t":"「뜨거운 모래가 반짝인다.」","mis":"K2-1-u3-X19"}],"explanation":["파도는 맛이 없어 「달콤한」이 어울리지 않아요.","다른 두 문장은 모습에 어울리는 말을 넣었어요.","「어울리지 않는」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#20','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C9',3,'error','auto','「처음으로 바다에서 수영한 날」이 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":20,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「처음으로 바다에서 수영한 날」이 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"민지 — 「여름」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"아린 — 「바다에서 처음 수영한 날」","mis":"K2-1-u3-X19"},{"t":"지호 — 「파도와 첫 수영」","mis":"K2-1-u3-X19"}],"explanation":["「여름」만으로는 무슨 일인지 알 수 없어요.","제목에 겪은 일이 드러나야 내용을 알 수 있어요.","다른 두 친구는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#21','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 「무럭무럭」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":21,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「무럭무럭」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"힘차게 잘 자라는 모양","correct":true},{"t":"시들시들 마르는 모양","mis":"K2-1-u3-X08"},{"t":"작은 열매가 많이 매달린 모양","mis":"K2-1-u3-X08"}],"explanation":["줄기가 무럭무럭 자랐다는 것은 힘차게 잘 자랐다는 뜻이에요.","다른 뜻은 다른 낱말의 뜻이에요.","낱말을 소리 내어 읽으며 모양을 떠올려요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#22','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C12',3,'mc','auto','흉내 내는 말 가운데 모양을 흉내 낸 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":22,"concept":"K2-1-u3-C12","difficulty":3,"kind":"mc","stem":"흉내 내는 말 가운데 모양을 흉내 낸 말이 아닌 것은 어느 것인가요?","options":[{"t":"졸졸","correct":true},{"t":"빙글빙글","mis":"K2-1-u3-X19"},{"t":"둥실둥실","mis":"K2-1-u3-X19"}],"explanation":["「졸졸」은 물이 흐르는 소리를 흉내 낸 말이에요.","다른 두 말은 모양을 흉내 낸 말이에요.","「아닌 것」을 묻는 물음 — 따라 하며 무엇이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#23','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 「운동회」 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#24','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C5',4,'essay','teacher','「고양이가 걷는다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"「고양이가 걷는다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.","answer_guide":{"answer":"예: 하얀 고양이가 살금살금 걷는다. (하얀, 살금살금)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 대상과 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울림.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#25','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C10',4,'essay','teacher','다음 일기를 언제·어디서·누구와, 그리고 그때의 생각이나 느낌이 드러나게 꾸며 주는 말을 넣어 고쳐 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#1','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#2','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C2',1,'mc','auto','「작은 새가 높이 날았다.」에서 「작은」이 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C2","difficulty":1,"kind":"mc","stem":"「작은 새가 높이 날았다.」에서 「작은」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"새가","correct":true},{"t":"높이","mis":"K2-1-u3-X02"},{"t":"날았다","mis":"K2-1-u3-X02"}],"explanation":["「작은」은 새가 어떤지 알려 줘요.","꾸며 주는 말을 뒤의 말에 붙여 읽어 보면 짝이 보여요.","「작은 새가」처럼 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#3','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C4',1,'mc','auto','수박 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"수박 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?","options":[{"t":"커다란","correct":true},{"t":"네모난","mis":"K2-1-u3-X04"},{"t":"파란","mis":"K2-1-u3-X04"}],"explanation":["수박의 크기에는 「커다란」이 어울려요.","다른 말은 수박의 모습과 어울리지 않아요.","대상을 잘 살펴 색·모양·움직임에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🍉"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#4','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C7',1,'mc','auto','일기에 꼭 들어가는 것은 어느 것인가요?',ARRAY['K2-1-u3-X11']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에 꼭 들어가는 것은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"친구 전화번호","mis":"K2-1-u3-X11"},{"t":"내일 시간표","mis":"K2-1-u3-X11"}],"explanation":["일기에는 겪은 일에 대한 생각이나 느낌을 써요.","다른 것은 일기에 맞지 않아요.","일기는 겪은 일과 생각이나 느낌을 담는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#5','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"공원에서 무지개를 봤다","correct":true},{"t":"우산","mis":"K2-1-u3-X12"},{"t":"놀라움","mis":"K2-1-u3-X12"}],"explanation":["「공원에서 무지개를 봤다」는 내가 겪은 일이에요.","우산은 물건, 놀라움은 느낌을 나타내는 낱말이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#6','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C9',1,'mc','auto','「동생과 눈사람을 만든」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":6,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"「동생과 눈사람을 만든」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"동생과 만든 눈사람","correct":true},{"t":"일기","mis":"K2-1-u3-X14"},{"t":"겨울","mis":"K2-1-u3-X14"}],"explanation":["「동생과 만든 눈사람」만 보아도 무슨 일인지 알 수 있어요.","「일기」, 「겨울」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#7','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C12',1,'mc','auto','감꽃이 떨어지는 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u3-X18']::text[],false,'{"seq":7,"concept":"K2-1-u3-C12","difficulty":1,"kind":"mc","stem":"감꽃이 떨어지는 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"톡톡","correct":true},{"t":"감꽃","mis":"K2-1-u3-X18"},{"t":"떨어진다","mis":"K2-1-u3-X18"}],"explanation":["「톡톡」은 가볍게 떨어지는 소리를 흉내 낸 말이에요.","감꽃·떨어진다는 흉내 내는 말이 아니에요.","따라 했을 때 모습·소리·느낌이 떠오르면 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#8','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C11',1,'mc','auto','음식을 만든 차례를 쓰는 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"음식을 만든 차례를 쓰는 일기는 어느 것인가요?","options":[{"t":"요리 일기","correct":true},{"t":"관찰 일기","mis":"K2-1-u3-X17"},{"t":"그림 일기","mis":"K2-1-u3-X17"}],"explanation":["음식을 만든 차례는 요리 일기에 써요.","다른 일기는 쓰는 내용이 달라요.","관찰 일기·요리 일기·그림 일기의 쓰는 내용을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#9','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C3',2,'ox','auto','「옥수수밭에 갔다.」보다 「넓은 옥수수밭에 갔다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"ox","stem":"「옥수수밭에 갔다.」보다 「넓은 옥수수밭에 갔다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「넓은」이 옥수수밭의 모습을 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#10','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C5',2,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"작은 새가 하늘을 높이 난다.","correct":true},{"t":"작은 새.","mis":"K2-1-u3-X06"},{"t":"작은 새가 하늘을 짭짤하게 네모나게 난다.","mis":"K2-1-u3-X05"}],"explanation":["「작은 새가 하늘을 높이 난다.」는 어울리는 꾸며 주는 말을 넣어 끝까지 쓴 문장이에요.","「작은 새.」는 끝맺지 않았어요.","「작은 새가 하늘을 짭짤하게 네모나게 난다.」는 어울리지 않는 말이 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#11','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 노란 꽃이 진 자리에 생긴 것은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":11,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 노란 꽃이 진 자리에 생긴 것은 무엇인가요?","options":[{"t":"초록 열매","correct":true},{"t":"빨간 꽃","mis":"K2-1-u3-X07"},{"t":"새 모종","mis":"K2-1-u3-X07"}],"explanation":["「꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.」라고 했어요.","다른 것은 글에 없거나 차례가 달라요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#12','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C7',2,'mc','auto','일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":12,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌","correct":true},{"t":"겪은 일 → 날짜·날씨 → 제목 → 생각이나 느낌","mis":"K2-1-u3-X10"},{"t":"제목 → 날짜·날씨 → 생각이나 느낌 → 겪은 일","mis":"K2-1-u3-X10"}],"explanation":["날짜·날씨가 맨 처음, 그다음 제목을 써요.","이어서 겪은 일, 마지막에 생각이나 느낌을 써요.","차례를 지키면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#13','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C10',2,'mc','auto','「동생과 눈사람 만들기」를 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X16']::text[],false,'{"seq":13,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"「동생과 눈사람 만들기」를 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?","options":[{"t":"동생과 만든 눈사람이 웃는 것 같아 마음이 따뜻했다.","correct":true},{"t":"눈사람을 만들었다.","mis":"K2-1-u3-X15"},{"t":"만들었다.","mis":"K2-1-u3-X16"}],"explanation":["「동생과 만든 눈사람이 웃는 것 같아 마음이 따뜻했다」에 그때의 마음이 담겨 있어요.","다른 문장은 한 일만 쓰거나 무슨 일인지 드러나지 않아요.","겪은 일에 솔직한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#14','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C12',2,'match','auto','흉내 내는 말과 어울리는 모습을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u3-C12","difficulty":2,"kind":"match","stem":"흉내 내는 말과 어울리는 모습을 이어 보세요.","pairs":[{"l":"졸졸","r":"시냇물이 흐른다"},{"l":"둥실둥실","r":"구름이 떠간다"},{"l":"새근새근","r":"아기가 잔다"}],"mis":"K2-1-u3-X18","explanation":["「졸졸」은 「시냇물이 흐른다」에 어울려요.","「둥실둥실」은 「구름이 떠간다」에 어울려요.","「새근새근」은 「아기가 잔다」에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#15','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C11',2,'mc','auto','장미꽃을 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":15,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"장미꽃을 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"꽃의 향기","correct":true},{"t":"꽃을 산 날짜","mis":"K2-1-u3-X17"},{"t":"꽃집 이름","mis":"K2-1-u3-X17"}],"explanation":["향기는 코로 맡아 알 수 있어요.","꽃을 산 날짜·꽃집 이름은 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#16','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C8',2,'mc','auto','서윤이의 하루예요. 일기 글감으로 가장 알맞은 일은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#17','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C2',3,'error','auto','「넓은 옥수수밭에서 할머니가 활짝 웃으셨다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":17,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「넓은 옥수수밭에서 할머니가 활짝 웃으셨다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"준우 — 「넓은 → 웃으셨다」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"하린 — 「넓은 → 옥수수밭」","mis":"K2-1-u3-X19"},{"t":"지안 — 「활짝 → 웃으셨다」","mis":"K2-1-u3-X19"}],"explanation":["「넓은」은 옥수수밭을 꾸며요.","다른 두 친구는 바르게 이었어요.","꾸며 주는 말을 바로 뒤의 말에 붙여 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#18','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":18,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"날짜·요일·날씨","mis":"K2-1-u3-X09"},{"t":"제목","mis":"K2-1-u3-X09"}],"explanation":["민지는 겪은 일은 자세히 썼지만 그때의 마음을 쓰지 않았어요.","다른 두 가지는 일기에 들어 있어요.","「빠진 것」을 묻는 물음 — 네 손가락을 접으며 확인해요."],"asset":{"type":"passage","lines":["9월 14일 토요일, 선선한 바람이 부는 날","제목: 할아버지와 고구마 캐기","오전에 할아버지 밭에서 고구마를 캤다.","흙을 살살 파내니 커다란 고구마가 줄줄이 딸려 나왔다."],"title":"민지의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#19','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C4',3,'mc','auto','공원 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":19,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"공원 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「네모난 비둘기가 걸어간다.」","correct":true},{"t":"「푸른 나무가 우뚝 서 있다.」","mis":"K2-1-u3-X19"},{"t":"「알록달록한 꽃이 활짝 피었다.」","mis":"K2-1-u3-X19"}],"explanation":["비둘기는 네모나지 않아요.","다른 두 문장은 모습에 어울리는 말을 넣었어요.","「어울리지 않는」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#20','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C9',3,'error','auto','「동생과 함께 김밥 만들기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":20,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「동생과 함께 김밥 만들기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"현우 — 「일요일」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"도담 — 「동생과 만든 김밥」","mis":"K2-1-u3-X19"},{"t":"하늘 — 「김밥 만들기 대작전」","mis":"K2-1-u3-X19"}],"explanation":["「일요일」만으로는 무슨 일인지 알 수 없어요.","제목에 겪은 일이 드러나야 내용을 알 수 있어요.","다른 두 친구는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#21','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 「조롱조롱」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":21,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「조롱조롱」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"작은 열매가 많이 매달린 모양","correct":true},{"t":"겉면이 높고 낮은 모양","mis":"K2-1-u3-X08"},{"t":"꽃잎이 한껏 핀 모양","mis":"K2-1-u3-X08"}],"explanation":["초록 열매가 조롱조롱 매달렸다는 것은 작은 열매가 많이 달렸다는 뜻이에요.","다른 뜻은 다른 낱말의 뜻이에요.","낱말을 소리 내어 읽으며 모양을 떠올려요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#22','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C12',3,'mc','auto','흉내 내는 말 가운데 소리를 흉내 낸 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":22,"concept":"K2-1-u3-C12","difficulty":3,"kind":"mc","stem":"흉내 내는 말 가운데 소리를 흉내 낸 말이 아닌 것은 어느 것인가요?","options":[{"t":"반짝반짝","correct":true},{"t":"톡톡","mis":"K2-1-u3-X19"},{"t":"쨍그랑","mis":"K2-1-u3-X19"}],"explanation":["「반짝반짝」은 빛나는 모양을 흉내 낸 말이에요.","다른 두 말은 소리를 흉내 낸 말이에요.","「아닌 것」을 묻는 물음 — 따라 하며 무엇이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#23','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 「소풍」 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#24','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C5',4,'essay','teacher','「바람이 분다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"「바람이 분다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.","answer_guide":{"answer":"예: 시원한 바람이 살랑살랑 분다. (시원한, 살랑살랑)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 대상과 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울림.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#25','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C10',4,'essay','teacher','다음 일기를 언제·어디서·누구와, 그리고 그때의 생각이나 느낌이 드러나게 꾸며 주는 말을 넣어 고쳐 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#1','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#2','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C2',1,'mc','auto','「예쁜 아기가 새근새근 잔다.」에서 「새근새근」이 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C2","difficulty":1,"kind":"mc","stem":"「예쁜 아기가 새근새근 잔다.」에서 「새근새근」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"잔다","correct":true},{"t":"아기가","mis":"K2-1-u3-X02"},{"t":"예쁜","mis":"K2-1-u3-X02"}],"explanation":["「새근새근」은 어떻게 자는지 알려 줘요.","꾸며 주는 말을 뒤의 말에 붙여 읽어 보면 짝이 보여요.","「새근새근 잔다」처럼 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#3','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C4',1,'mc','auto','달팽이 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"달팽이 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?","options":[{"t":"느릿느릿","correct":true},{"t":"쌩쌩","mis":"K2-1-u3-X04"},{"t":"깡충깡충","mis":"K2-1-u3-X04"}],"explanation":["달팽이가 기는 모습에는 「느릿느릿」이 어울려요.","다른 말은 달팽이의 모습과 어울리지 않아요.","대상을 잘 살펴 색·모양·움직임에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🐌"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#4','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C7',1,'mc','auto','일기에서 맨 처음에 쓰는 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에서 맨 처음에 쓰는 것은 어느 것인가요?","options":[{"t":"날짜·요일·날씨","correct":true},{"t":"생각이나 느낌","mis":"K2-1-u3-X10"},{"t":"겪은 일","mis":"K2-1-u3-X10"}],"explanation":["일기는 날짜·요일·날씨부터 써요.","다른 것은 일기에 맞지 않아요.","일기는 겪은 일과 생각이나 느낌을 담는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#5','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"선생님께 칭찬을 들었다","correct":true},{"t":"칠판","mis":"K2-1-u3-X12"},{"t":"뿌듯함","mis":"K2-1-u3-X12"}],"explanation":["「선생님께 칭찬을 들었다」는 내가 겪은 일이에요.","칠판은 물건, 뿌듯함은 느낌을 나타내는 낱말이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#6','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C9',1,'mc','auto','「할머니와 송편을 빚은」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":6,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"「할머니와 송편을 빚은」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"할머니와 빚은 송편","correct":true},{"t":"토요일","mis":"K2-1-u3-X14"},{"t":"재미","mis":"K2-1-u3-X14"}],"explanation":["「할머니와 빚은 송편」만 보아도 무슨 일인지 알 수 있어요.","「토요일」, 「재미」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#7','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C12',1,'mc','auto','별이 빛나는 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u3-X18']::text[],false,'{"seq":7,"concept":"K2-1-u3-C12","difficulty":1,"kind":"mc","stem":"별이 빛나는 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"반짝반짝","correct":true},{"t":"별","mis":"K2-1-u3-X18"},{"t":"밤하늘","mis":"K2-1-u3-X18"}],"explanation":["「반짝반짝」은 별이 빛나는 모양을 흉내 낸 말이에요.","별·밤하늘은 흉내 내는 말이 아니에요.","따라 했을 때 모습·소리·느낌이 떠오르면 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#8','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C11',1,'mc','auto','그림과 글로 함께 나타내는 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"그림과 글로 함께 나타내는 일기는 어느 것인가요?","options":[{"t":"그림 일기","correct":true},{"t":"요리 일기","mis":"K2-1-u3-X17"},{"t":"관찰 일기","mis":"K2-1-u3-X17"}],"explanation":["그림과 글을 함께 쓰는 일기는 그림 일기예요.","다른 일기는 쓰는 내용이 달라요.","관찰 일기·요리 일기·그림 일기의 쓰는 내용을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#9','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C3',2,'ox','auto','「코끼리가 있다.」보다 「커다란 하얀 코끼리가 있다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"ox","stem":"「코끼리가 있다.」보다 「커다란 하얀 코끼리가 있다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「커다란」·「하얀」이 코끼리의 모습을 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#10','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C5',2,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"커다란 배가 바다를 빠르게 나아간다.","correct":true},{"t":"커다란 배.","mis":"K2-1-u3-X06"},{"t":"커다란 배가 바다를 졸리게 달콤하게 나아간다.","mis":"K2-1-u3-X05"}],"explanation":["「커다란 배가 바다를 빠르게 나아간다.」는 어울리는 꾸며 주는 말을 넣어 끝까지 쓴 문장이에요.","「커다란 배.」는 끝맺지 않았어요.","「커다란 배가 바다를 졸리게 달콤하게 나아간다.」는 어울리지 않는 말이 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#11','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 덩굴손은 무엇을 감으며 뻗어 가나요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":11,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 덩굴손은 무엇을 감으며 뻗어 가나요?","options":[{"t":"막대","correct":true},{"t":"땅콩","mis":"K2-1-u3-X07"},{"t":"꼬투리","mis":"K2-1-u3-X07"}],"explanation":["「덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.」라고 했어요.","다른 것은 글에 없거나 차례가 달라요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#12','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C7',2,'mc','auto','일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":12,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌","correct":true},{"t":"날짜·날씨 → 생각이나 느낌 → 제목 → 겪은 일","mis":"K2-1-u3-X10"},{"t":"겪은 일 → 생각이나 느낌 → 제목 → 날짜·날씨","mis":"K2-1-u3-X10"}],"explanation":["날짜·날씨가 맨 처음, 그다음 제목을 써요.","이어서 겪은 일, 마지막에 생각이나 느낌을 써요.","차례를 지키면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#13','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C10',2,'mc','auto','「발표하기」를 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X16']::text[],false,'{"seq":13,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"「발표하기」를 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?","options":[{"t":"떨렸지만 끝까지 말해서 스스로가 대견했다.","correct":true},{"t":"발표를 했다.","mis":"K2-1-u3-X15"},{"t":"말했다.","mis":"K2-1-u3-X16"}],"explanation":["「떨렸지만 끝까지 말해서 스스로가 대견했다」에 그때의 마음이 담겨 있어요.","다른 문장은 한 일만 쓰거나 무슨 일인지 드러나지 않아요.","겪은 일에 솔직한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#14','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C12',2,'match','auto','흉내 내는 말과 어울리는 모습을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u3-C12","difficulty":2,"kind":"match","stem":"흉내 내는 말과 어울리는 모습을 이어 보세요.","pairs":[{"l":"보들보들","r":"강아지 털을 만진다"},{"l":"쨍그랑","r":"유리컵이 깨진다"},{"l":"엉금엉금","r":"거북이가 긴다"}],"mis":"K2-1-u3-X18","explanation":["「보들보들」은 「강아지 털을 만진다」에 어울려요.","「쨍그랑」은 「유리컵이 깨진다」에 어울려요.","「엉금엉금」은 「거북이가 긴다」에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#15','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C11',2,'mc','auto','솔방울을 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":15,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"솔방울을 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"겉면의 촉감","correct":true},{"t":"솔방울의 가격","mis":"K2-1-u3-X17"},{"t":"주운 사람 이름","mis":"K2-1-u3-X17"}],"explanation":["촉감은 손으로 만져 알 수 있어요.","솔방울의 가격·주운 사람 이름은 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#16','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C8',2,'mc','auto','도윤이의 하루예요. 일기 글감으로 가장 알맞은 일은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#17','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C2',3,'error','auto','「작은 다람쥐가 빨간 도토리를 냠냠 먹었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":17,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「작은 다람쥐가 빨간 도토리를 냠냠 먹었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"민호 — 「빨간 → 다람쥐」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"서아 — 「작은 → 다람쥐」","mis":"K2-1-u3-X19"},{"t":"은솔 — 「냠냠 → 먹었다」","mis":"K2-1-u3-X19"}],"explanation":["「빨간」은 도토리를 꾸며요.","다른 두 친구는 바르게 이었어요.","꾸며 주는 말을 바로 뒤의 말에 붙여 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#18','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":18,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"제목","correct":true},{"t":"날짜·요일·날씨","mis":"K2-1-u3-X09"},{"t":"생각이나 느낌","mis":"K2-1-u3-X09"}],"explanation":["지후는 날짜 다음에 쓸 제목을 빠뜨렸어요.","다른 두 가지는 일기에 들어 있어요.","「빠진 것」을 묻는 물음 — 네 손가락을 접으며 확인해요."],"asset":{"type":"passage","lines":["7월 3일 수요일, 후덥지근하게 흐린 날","오후에 동생과 놀이터에서 물총놀이를 했다.","시원한 물줄기가 쏴 하고 뿜어져 나왔다.","옷이 흠뻑 젖었지만 깔깔 웃을 만큼 신났다."],"title":"지후의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#19','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C4',3,'mc','auto','겨울 아침 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":19,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"겨울 아침 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「뜨거운 눈이 펑펑 내린다.」","correct":true},{"t":"「하얀 눈이 소복소복 쌓였다.」","mis":"K2-1-u3-X19"},{"t":"「차가운 바람이 쌩쌩 분다.」","mis":"K2-1-u3-X19"}],"explanation":["눈은 뜨겁지 않아요.","다른 두 문장은 모습에 어울리는 말을 넣었어요.","「어울리지 않는」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#20','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C9',3,'error','auto','「운동회에서 이어달리기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":20,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「운동회에서 이어달리기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"지우 — 「재미」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"하준 — 「운동회 이어달리기」","mis":"K2-1-u3-X19"},{"t":"다은 — 「바통을 넘겨라」","mis":"K2-1-u3-X19"}],"explanation":["「재미」만으로는 무슨 일인지 알 수 없어요.","제목에 겪은 일이 드러나야 내용을 알 수 있어요.","다른 두 친구는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#21','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 「올록볼록」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":21,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「올록볼록」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"겉면이 고르지 않게 높고 낮은 모양","correct":true},{"t":"둥글게 감으며 도는 모양","mis":"K2-1-u3-X08"},{"t":"길게 곧게 뻗는 모양","mis":"K2-1-u3-X08"}],"explanation":["땅콩 껍데기가 올록볼록해서 만지면 울퉁불퉁하다고 했어요.","다른 뜻은 다른 낱말의 뜻이에요.","낱말을 소리 내어 읽으며 모양을 떠올려요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#22','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C12',3,'mc','auto','흉내 내는 말 가운데 느낌을 흉내 낸 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":22,"concept":"K2-1-u3-C12","difficulty":3,"kind":"mc","stem":"흉내 내는 말 가운데 느낌을 흉내 낸 말이 아닌 것은 어느 것인가요?","options":[{"t":"빙글빙글","correct":true},{"t":"보들보들","mis":"K2-1-u3-X19"},{"t":"찐득찐득","mis":"K2-1-u3-X19"}],"explanation":["「빙글빙글」은 도는 모양을 흉내 낸 말이에요.","다른 두 말은 느낌을 흉내 낸 말이에요.","「아닌 것」을 묻는 물음 — 따라 하며 무엇이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#23','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 「눈 오는 날」 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#24','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C5',4,'essay','teacher','「아이가 웃는다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"「아이가 웃는다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.","answer_guide":{"answer":"예: 작은 아이가 방긋방긋 웃는다. (작은, 방긋방긋)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 대상과 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울림.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#25','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C10',4,'essay','teacher','다음 일기를 언제·어디서·누구와, 그리고 그때의 생각이나 느낌이 드러나게 꾸며 주는 말을 넣어 고쳐 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#1','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#2','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C2',1,'mc','auto','「커다란 배가 천천히 간다.」에서 「커다란」이 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C2","difficulty":1,"kind":"mc","stem":"「커다란 배가 천천히 간다.」에서 「커다란」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"배가","correct":true},{"t":"천천히","mis":"K2-1-u3-X02"},{"t":"간다","mis":"K2-1-u3-X02"}],"explanation":["「커다란」은 배가 어떤지 알려 줘요.","꾸며 주는 말을 뒤의 말에 붙여 읽어 보면 짝이 보여요.","「커다란 배가」처럼 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#3','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C4',1,'mc','auto','눈사람 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"눈사람 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?","options":[{"t":"하얀","correct":true},{"t":"뜨거운","mis":"K2-1-u3-X04"},{"t":"빨간","mis":"K2-1-u3-X04"}],"explanation":["눈사람의 색에는 「하얀」이 어울려요.","다른 말은 눈사람의 모습과 어울리지 않아요.","대상을 잘 살펴 색·모양·움직임에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"⛄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#4','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C7',1,'mc','auto','일기에 겪은 일을 쓴 다음에 쓰는 것은 어느 것인가요?',ARRAY['K2-1-u3-X10','K2-1-u3-X11']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에 겪은 일을 쓴 다음에 쓰는 것은 어느 것인가요?","options":[{"t":"그 일에 대한 생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X10"},{"t":"준비물 목록","mis":"K2-1-u3-X11"}],"explanation":["겪은 일 다음에 생각이나 느낌을 써요.","다른 것은 일기에 맞지 않아요.","일기는 겪은 일과 생각이나 느낌을 담는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#5','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"텃밭에서 상추를 땄다","correct":true},{"t":"바구니","mis":"K2-1-u3-X12"},{"t":"즐거움","mis":"K2-1-u3-X12"}],"explanation":["「텃밭에서 상추를 땄다」는 내가 겪은 일이에요.","바구니는 물건, 즐거움은 느낌을 나타내는 낱말이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#6','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C9',1,'mc','auto','「처음 바다에서 수영한」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":6,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"「처음 바다에서 수영한」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"바다에서 처음 수영한 날","correct":true},{"t":"여름 방학","mis":"K2-1-u3-X14"},{"t":"물","mis":"K2-1-u3-X14"}],"explanation":["「바다에서 처음 수영한 날」만 보아도 무슨 일인지 알 수 있어요.","「여름 방학」, 「물」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#7','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C12',1,'mc','auto','시냇물이 흐르는 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u3-X18']::text[],false,'{"seq":7,"concept":"K2-1-u3-C12","difficulty":1,"kind":"mc","stem":"시냇물이 흐르는 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"졸졸","correct":true},{"t":"시냇물","mis":"K2-1-u3-X18"},{"t":"흐른다","mis":"K2-1-u3-X18"}],"explanation":["「졸졸」은 물이 흐르는 소리를 흉내 낸 말이에요.","시냇물·흐른다는 흉내 내는 말이 아니에요.","따라 했을 때 모습·소리·느낌이 떠오르면 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#8','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C11',1,'mc','auto','강낭콩이 자라는 모습을 날마다 살펴 쓰기에 알맞은 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"강낭콩이 자라는 모습을 날마다 살펴 쓰기에 알맞은 일기는 어느 것인가요?","options":[{"t":"관찰 일기","correct":true},{"t":"요리 일기","mis":"K2-1-u3-X17"},{"t":"그림 없는 편지","mis":"K2-1-u3-X17"}],"explanation":["자라는 모습을 살펴 쓰는 일기는 관찰 일기예요.","다른 일기는 쓰는 내용이 달라요.","관찰 일기·요리 일기·그림 일기의 쓰는 내용을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#9','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C3',2,'ox','auto','「꽃이 피었다.」보다 「예쁜 꽃이 활짝 피었다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"ox","stem":"「꽃이 피었다.」보다 「예쁜 꽃이 활짝 피었다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「예쁜」·「활짝」이 꽃의 모습을 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#10','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C5',2,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"귀여운 강아지가 신나게 달린다.","correct":true},{"t":"귀여운 강아지.","mis":"K2-1-u3-X06"},{"t":"귀여운 강아지가 딱딱하게 새콤하게 달린다.","mis":"K2-1-u3-X05"}],"explanation":["「귀여운 강아지가 신나게 달린다.」는 어울리는 꾸며 주는 말을 넣어 끝까지 쓴 문장이에요.","「귀여운 강아지.」는 끝맺지 않았어요.","「귀여운 강아지가 딱딱하게 새콤하게 달린다.」는 어울리지 않는 말이 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#11','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 봄비가 내리자 일어난 일은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":11,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 봄비가 내리자 일어난 일은 무엇인가요?","options":[{"t":"조그만 새싹이 쏙 돋아났어요","correct":true},{"t":"까만 씨앗이 박혔어요","mis":"K2-1-u3-X07"},{"t":"꽃이 활짝 피었어요","mis":"K2-1-u3-X07"}],"explanation":["「봄비가 내리자 조그만 새싹이 쏙 돋아났어요.」라고 했어요.","다른 것은 글에 없거나 차례가 달라요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#12','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C7',2,'mc','auto','일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":12,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌","correct":true},{"t":"제목 → 생각이나 느낌 → 날짜·날씨 → 겪은 일","mis":"K2-1-u3-X10"},{"t":"날짜·날씨 → 겪은 일 → 제목 → 생각이나 느낌","mis":"K2-1-u3-X10"}],"explanation":["날짜·날씨가 맨 처음, 그다음 제목을 써요.","이어서 겪은 일, 마지막에 생각이나 느낌을 써요.","차례를 지키면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#13','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C10',2,'mc','auto','「강아지 산책」을 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X16']::text[],false,'{"seq":13,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"「강아지 산책」을 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?","options":[{"t":"강아지가 꼬리를 흔들며 따라와서 무척 행복했다.","correct":true},{"t":"강아지와 산책했다.","mis":"K2-1-u3-X15"},{"t":"걸었다.","mis":"K2-1-u3-X16"}],"explanation":["「강아지가 꼬리를 흔들며 따라와서 무척 행복했다」에 그때의 마음이 담겨 있어요.","다른 문장은 한 일만 쓰거나 무슨 일인지 드러나지 않아요.","겪은 일에 솔직한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#14','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C12',2,'match','auto','흉내 내는 말과 어울리는 모습을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u3-C12","difficulty":2,"kind":"match","stem":"흉내 내는 말과 어울리는 모습을 이어 보세요.","pairs":[{"l":"펑펑","r":"함박눈이 내린다"},{"l":"살랑살랑","r":"잎이 흔들린다"},{"l":"보글보글","r":"찌개가 끓는다"}],"mis":"K2-1-u3-X18","explanation":["「펑펑」은 「함박눈이 내린다」에 어울려요.","「살랑살랑」은 「잎이 흔들린다」에 어울려요.","「보글보글」은 「찌개가 끓는다」에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#15','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C11',2,'mc','auto','방울토마토를 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":15,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"방울토마토를 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"열매의 색과 개수","correct":true},{"t":"토마토를 키운 회사","mis":"K2-1-u3-X17"},{"t":"화분의 값","mis":"K2-1-u3-X17"}],"explanation":["색과 개수는 눈으로 살펴 알 수 있어요.","토마토를 키운 회사·화분의 값은 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#16','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C8',2,'mc','auto','예린이의 하루예요. 일기 글감으로 가장 알맞은 일은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#17','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C2',3,'error','auto','「하얀 구름이 파란 하늘에 둥실둥실 떠간다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":17,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「하얀 구름이 파란 하늘에 둥실둥실 떠간다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"태민 — 「둥실둥실 → 하늘」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"아린 — 「하얀 → 구름」","mis":"K2-1-u3-X19"},{"t":"소율 — 「파란 → 하늘」","mis":"K2-1-u3-X19"}],"explanation":["「둥실둥실」은 떠간다를 꾸며요.","다른 두 친구는 바르게 이었어요.","꾸며 주는 말을 바로 뒤의 말에 붙여 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#18','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":18,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"제목","mis":"K2-1-u3-X09"},{"t":"날짜·요일·날씨","mis":"K2-1-u3-X09"}],"explanation":["아린이는 공원의 모습은 생생하게 썼지만 그때의 마음을 쓰지 않았어요.","다른 두 가지는 일기에 들어 있어요.","「빠진 것」을 묻는 물음 — 네 손가락을 접으며 확인해요."],"asset":{"type":"passage","lines":["11월 2일 일요일, 하늘이 높고 파란 날","제목: 가을 소풍","아침에 가족과 공원에 갔다.","노랗게 물든 은행잎이 바람에 팔랑팔랑 떨어졌다."],"title":"아린이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#19','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C4',3,'mc','auto','부엌 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":19,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"부엌 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「시끄러운 사과가 놓여 있다.」","correct":true},{"t":"「보글보글 찌개가 끓는다.」","mis":"K2-1-u3-X19"},{"t":"「고소한 냄새가 솔솔 난다.」","mis":"K2-1-u3-X19"}],"explanation":["사과는 소리를 내지 않아요.","다른 두 문장은 모습에 어울리는 말을 넣었어요.","「어울리지 않는」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#20','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C9',3,'error','auto','「할아버지와 밤 줍기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":20,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「할아버지와 밤 줍기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"시우 — 「가을 일기」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"예린 — 「할아버지와 주운 밤」","mis":"K2-1-u3-X19"},{"t":"로아 — 「뾰족뾰족 밤송이」","mis":"K2-1-u3-X19"}],"explanation":["「가을 일기」만으로는 무슨 일인지 알 수 없어요.","제목에 겪은 일이 드러나야 내용을 알 수 있어요.","다른 두 친구는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#21','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 「빙글빙글」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":21,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「빙글빙글」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"둥글게 감거나 도는 모양","correct":true},{"t":"겉면이 높고 낮은 모양","mis":"K2-1-u3-X08"},{"t":"힘차게 잘 자라는 모양","mis":"K2-1-u3-X08"}],"explanation":["덩굴손이 막대를 빙글빙글 감으며 뻗어 간다고 했어요.","다른 뜻은 다른 낱말의 뜻이에요.","낱말을 소리 내어 읽으며 모양을 떠올려요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#22','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C12',3,'mc','auto','흉내 내는 말 가운데 소리를 흉내 낸 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":22,"concept":"K2-1-u3-C12","difficulty":3,"kind":"mc","stem":"흉내 내는 말 가운데 소리를 흉내 낸 말이 아닌 것은 어느 것인가요?","options":[{"t":"엉금엉금","correct":true},{"t":"멍멍","mis":"K2-1-u3-X19"},{"t":"보글보글","mis":"K2-1-u3-X19"}],"explanation":["「엉금엉금」은 기어가는 모양을 흉내 낸 말이에요.","다른 두 말은 소리를 흉내 낸 말이에요.","「아닌 것」을 묻는 물음 — 따라 하며 무엇이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#23','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 「텃밭」 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#24','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C5',4,'essay','teacher','「배가 간다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"「배가 간다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.","answer_guide":{"answer":"예: 커다란 배가 바다 위를 천천히 간다. (커다란, 천천히)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 대상과 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울림.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#25','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C10',4,'essay','teacher','다음 일기를 언제·어디서·누구와, 그리고 그때의 생각이나 느낌이 드러나게 꾸며 주는 말을 넣어 고쳐 써 보세요.
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C1','kor',2,1,'u4',1,'겹받침 알기 — 닭(ㄺ)·값(ㅄ)·앉다(ㄵ)처럼 받침 자리에 서로 다른 글자가 두 개 있는 받침을 알고, 홑받침·쌍받침 낱말과 가려 겹받침 낱말 찾기',ARRAY['2국04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C2','kor',2,1,'u4',3,'겹받침 낱말 바르게 읽기 — 겹받침은 두 글자 가운데 한 글자의 소리로 읽고(ㄺ·ㄳ → [ㄱ], ㄵ → [ㄴ], ㄼ → [ㄹ], ㄻ → [ㅁ], ㅄ → [ㅂ]), 뒤 글자 소리가 바뀌는 것(앉다[안따]·많다[만타])까지 살려 읽기',ARRAY['2국04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C3','kor',2,1,'u4',3,'겹받침 낱말 바르게 쓰기 — 읽는 소리와 쓰는 글자가 다를 수 있음을 알고, [닥]·[갑]으로 들려도 「닭」·「값」처럼 받침 두 글자를 모두 살려 쓰기(앉다↔않다처럼 받침 짝 가리기)',ARRAY['2국04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C4','kor',2,1,'u4',6,'글 속 겹받침 낱말 읽기 — 글을 읽다가 겹받침 낱말이 나오면 잠깐 멈춰 바른 소리를 떠올려 읽고, 바르게 읽으며 글의 내용도 함께 이해하기',ARRAY['2국04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C5','kor',2,1,'u4',1,'분위기의 뜻 — 분위기는 글이나 시를 읽을 때 느껴지는 기분(신나는·조용한·포근한·씩씩한)이며, 분위기를 살려 읽으면 작품이 더 재미있게 전해짐을 알기',ARRAY['2국05-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C6','kor',2,1,'u4',8,'말과 장면으로 시의 분위기 찾기 — 시에 나오는 말(통통·콩콩·살며시·소복소복)과 장면(운동장·달밤·봄볕)을 살펴 분위기를 찾고, 그렇게 느낀 까닭을 말하기',ARRAY['2국05-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C7','kor',2,1,'u4',10,'분위기에 알맞게 소리 내어 읽기 — 신나는 시는 밝고 빠르게, 조용한 시는 천천히 부드럽게, 씩씩한 시는 또렷하고 힘차게, 포근한 시는 다정하고 따뜻하게 — 목소리 크기와 빠르기를 분위기에 맞추기',ARRAY['2국05-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C8','kor',2,1,'u4',10,'알맞게 띄어 읽기 — 뜻이 이어지는 말끼리 묶어 한 덩어리씩 읽고, 「/」에서는 조금 쉬고 「//」에서는 조금 더 쉬어 뜻이 잘 드러나게 읽기',ARRAY['2국02-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C9','kor',2,1,'u4',12,'시 낭송하기 — 마음에 드는 시 고르기 → 분위기를 살펴 읽는 방법 정해 연습하기 → 친구들 앞에서 또렷하게 분위기를 살려 낭송하기',ARRAY['2국05-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C10','kor',2,1,'u4',12,'시를 나누며 듣기 — 친구가 낭송할 때 조용히 끝까지 들으며 장면을 떠올리고, 끝나면 박수와 칭찬으로 반응하며, 시를 나누면 여러 분위기와 친구 마음을 만날 수 있음을 알기',ARRAY['2국05-01']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X01','kor',2,'u4',ARRAY['K2-1-u4-C3']::text[],'들리는 소리대로 받침을 하나만 쓴다([닥] → 닥, [갑] → 갑, [안따] → 안따)','받침 자리에 글자가 두 개 다 있는지 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X02','kor',2,'u4',ARRAY['K2-1-u4-C2','K2-1-u4-C4']::text[],'겹받침 두 글자를 모두 소리 내거나 글자 그대로 읽는다(닭 → [달ㄱ], 값 → [갑ㅅ])','겹받침은 「둘 중 하나」 — 한 소리만 내는지 다시 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X03','kor',2,'u4',ARRAY['K2-1-u4-C2','K2-1-u4-C4']::text[],'겹받침 두 글자 가운데 다른 쪽 글자의 소리로 읽는다(닭 → [달], 넓다 → [넙따], 값 → [갓])','ㄺ은 [ㄱ], ㄼ은 [ㄹ], ㅄ은 [ㅂ] — 받침 소리 짝을 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X04','kor',2,'u4',ARRAY['K2-1-u4-C2']::text[],'겹받침 뒤 글자의 소리가 바뀌는 것을 놓친다(앉다 → [안다], 넓다 → [널다], 많다 → [만다])','「따·타」처럼 뒤 글자가 세게 나는지 귀 기울여 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X05','kor',2,'u4',ARRAY['K2-1-u4-C1','K2-1-u4-C4']::text[],'겹받침과 홑받침·쌍받침을 가리지 못한다(산·손·있다·밖을 겹받침으로 여기거나, 닭의 받침을 ㄱ 하나로 안다)','받침 자리에 「서로 다른」 글자가 두 개인지 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X06','kor',2,'u4',ARRAY['K2-1-u4-C3']::text[],'겹받침의 글자 짝을 잘못 쓴다(닭 → 닯, 앉다 → 않다, 값 → 갋)','뜻을 떠올리고 받침 두 글자를 하나씩 소리 내며 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X07','kor',2,'u4',ARRAY['K2-1-u4-C4','K2-1-u4-C6']::text[],'글에 없는 내용을 있다고 하거나, 겹받침 낱말에만 매달려 글의 내용을 놓친다','글에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X08','kor',2,'u4',ARRAY['K2-1-u4-C5']::text[],'분위기를 글의 줄거리·등장인물·글자 수·제목으로 여긴다','「읽고 나서 어떤 기분이 들었지?」 하고 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X09','kor',2,'u4',ARRAY['K2-1-u4-C6']::text[],'시에 나오는 말과 장면을 살피지 않고 분위기를 엉뚱하게 고르거나, 소재만 보고 분위기를 정한다(눈 → 언제나 조용함)','시에서 기분을 만드는 말에 동그라미 치고 장면을 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X10','kor',2,'u4',ARRAY['K2-1-u4-C6']::text[],'분위기를 나타내는 말의 느낌을 바꿔 안다(살며시·소복소복 → 신나는, 통통·콩콩 → 조용한)','그 말을 소리 내어 따라 하며 몸이 어떤 기분이 드는지 느끼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X11','kor',2,'u4',ARRAY['K2-1-u4-C7','K2-1-u4-C9']::text[],'모든 글을 한 가지 목소리로 읽거나, 분위기와 맞지 않는 목소리로 읽는다(조용한 시를 크게 소리 지르며)','「이 시의 기분에 어울리는 목소리는?」 먼저 정하고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X12','kor',2,'u4',ARRAY['K2-1-u4-C7']::text[],'빠르고 크게 읽으면 언제나 잘 읽은 것으로 여긴다','빠르기도 분위기에 맞추는 것 — 천천히 읽어야 할 곳 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X13','kor',2,'u4',ARRAY['K2-1-u4-C8']::text[],'한 글자씩 끊거나 아무 데서나 띄어 읽어 뜻이 드러나지 않는다(달 / 님이살 / 며시)','뜻이 이어지는 말끼리 손으로 묶어 보고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X14','kor',2,'u4',ARRAY['K2-1-u4-C8']::text[],'띄어 읽기 표시의 뜻을 바꿔 안다(「//」를 덜 쉬거나 「/」에서 쉬지 않음)','「/」 한 번 쉬고, 「//」 한 번 더 쉬기 — 손뼉으로 쉬는 길이 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X15','kor',2,'u4',ARRAY['K2-1-u4-C9']::text[],'낭송 차례를 뒤바꾸거나(연습 없이 낭송), 장난치며·작게 우물우물·외우기만 하며 낭송한다','「고르기 → 연습하기 → 낭송하기」 차례와 「또렷하게·분위기 살려」 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X16','kor',2,'u4',ARRAY['K2-1-u4-C10']::text[],'친구가 낭송할 때 떠들거나 딴짓하고, 중간에 끼어들거나 놀린다','「내가 낭송할 때 친구가 어떻게 들어 주면 좋을까?」 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X17','kor',2,'u4',ARRAY['K2-1-u4-C1','K2-1-u4-C2','K2-1-u4-C3','K2-1-u4-C4','K2-1-u4-C6','K2-1-u4-C7','K2-1-u4-C8','K2-1-u4-C9','K2-1-u4-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌↔맞는, 알맞지 않은↔알맞은, 잘못↔바르게','물음의 「아닌·않은·잘못」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#1','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"산","mis":"K2-1-u4-X05"},{"t":"손","mis":"K2-1-u4-X05"}],"explanation":["「닭」은 받침 자리에 ㄹ과 ㄱ, 두 글자가 있어요.","「산」·「손」은 받침이 ㄴ 하나뿐이에요.","이런 받침을 겹받침이라고 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"감","mis":"K2-1-u4-X05"},{"t":"강","mis":"K2-1-u4-X05"}],"explanation":["「값」은 받침 자리에 ㅂ과 ㅅ, 두 글자가 있어요.","「감」·「강」은 받침이 하나뿐이에요.","이런 받침을 겹받침이라고 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#2','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',1,'mc','auto','「흙」의 받침은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":2,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"「흙」의 받침은 어느 것인가요?","options":[{"t":"ㄺ","correct":true},{"t":"ㄱ","mis":"K2-1-u4-X05"},{"t":"ㄹ","mis":"K2-1-u4-X05"}],"explanation":["「흙」의 받침 자리에는 ㄹ과 ㄱ이 함께 있어요.","ㄱ이나 ㄹ 하나만 고르면 받침 글자 하나를 빠뜨린 거예요.","받침 자리의 글자를 모두 짚어 봐요."],"variant_rule":{"alt":[{"stem":"「앉다」의 「앉」 받침은 어느 것인가요?","options":[{"t":"ㄵ","correct":true},{"t":"ㄴ","mis":"K2-1-u4-X05"},{"t":"ㅈ","mis":"K2-1-u4-X05"}],"explanation":["「앉」의 받침 자리에는 ㄴ과 ㅈ이 함께 있어요.","ㄴ이나 ㅈ 하나만 고르면 받침 글자 하나를 빠뜨린 거예요.","받침 자리의 글자를 모두 짚어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#3','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C5',1,'mc','auto','글이나 시를 읽을 때 느껴지는 기분을 무엇이라고 하나요?',ARRAY['K2-1-u4-X08']::text[],true,'{"seq":3,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"글이나 시를 읽을 때 느껴지는 기분을 무엇이라고 하나요?","options":[{"t":"분위기","correct":true},{"t":"제목","mis":"K2-1-u4-X08"},{"t":"겹받침","mis":"K2-1-u4-X08"}],"explanation":["글이나 시에서 느껴지는 기분을 분위기라고 해요.","제목은 글의 이름, 겹받침은 받침의 한 가지예요.","신나는 분위기, 조용한 분위기처럼 말해요."],"variant_rule":{"alt":[{"stem":"「분위기」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글이나 시를 읽을 때 느껴지는 기분","correct":true},{"t":"글에 나오는 사람의 이름","mis":"K2-1-u4-X08"},{"t":"글에 있는 글자의 수","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시에서 느껴지는 기분이에요.","사람 이름이나 글자 수는 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#4','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C2',1,'ox','auto','「닭」은 받침 글자 두 개를 모두 소리 내어 [달ㄱ]처럼 읽어요.',ARRAY['K2-1-u4-X02']::text[],true,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":1,"kind":"ox","stem":"「닭」은 받침 글자 두 개를 모두 소리 내어 [달ㄱ]처럼 읽어요.","answer":"X","reason_options":[{"t":"겹받침은 둘 중 한 소리로 [닥]이라고 읽으니까","correct":true},{"t":"받침 글자는 모두 소리 내야 하니까","mis":"K2-1-u4-X02"}],"mis":"K2-1-u4-X02","explanation":["「닭」은 [닥]이라고 읽어요.","겹받침은 두 글자 가운데 한 글자의 소리만 나요.","글자와 소리가 다를 수 있어요."],"variant_rule":{"alt":[{"stem":"「값」은 [갑]이라고 읽어요.","answer":"O","reason_options":[{"t":"ㅄ 받침은 [ㅂ] 소리로 읽으니까","correct":true},{"t":"받침 글자 두 개를 모두 소리 내니까","mis":"K2-1-u4-X02"}],"explanation":["「값」은 [갑]이라고 읽어요.","겹받침은 두 글자 가운데 한 글자의 소리만 나요.","글자와 소리가 다를 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#5','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"닭","r":"[닥]"},{"l":"값","r":"[갑]"},{"l":"흙","r":"[흑]"}],"mis":"K2-1-u4-X03","explanation":["「닭」은 [닥]이라고 읽어요.","「값」은 [갑]이라고 읽어요.","「흙」은 [흑]이라고 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"앉다","r":"[안따]"},{"l":"넓다","r":"[널따]"},{"l":"맑다","r":"[막따]"}],"explanation":["「앉다」는 [안따]라고 읽어요.","「넓다」는 [널따]라고 읽어요.","「맑다」는 [막따]라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#6','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',2,'mc','auto','겹받침이 있는 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":6,"concept":"K2-1-u4-C1","difficulty":2,"kind":"mc","stem":"겹받침이 있는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"닭 · 값 · 흙","correct":true},{"t":"닭 · 산 · 흙","mis":"K2-1-u4-X05"},{"t":"손 · 강 · 밤","mis":"K2-1-u4-X05"}],"explanation":["「닭」·「값」·「흙」은 모두 받침 자리에 글자가 두 개 있어요.","「산」·「손」·「강」·「밤」은 받침이 하나예요.","받침 자리의 글자 수를 세어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 겹받침이 있는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"앉다 · 짧다 · 읽다","correct":true},{"t":"앉다 · 바다 · 읽다","mis":"K2-1-u4-X05"},{"t":"구름 · 바다 · 나무","mis":"K2-1-u4-X05"}],"explanation":["「앉다」·「짧다」·「읽다」의 첫 글자는 모두 겹받침이 있어요.","「바다」·「나무」는 받침이 없고, 「구름」은 받침이 하나예요.","받침 자리의 글자 수를 세어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#7','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C5',2,'mc','auto','시를 읽고 답해 보세요. 이 시에서 느껴지는 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],true,'{"seq":7,"concept":"K2-1-u4-C5","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시에서 느껴지는 분위기는 어느 것인가요?","options":[{"t":"신나는","correct":true},{"t":"무서운","mis":"K2-1-u4-X09"},{"t":"슬픈","mis":"K2-1-u4-X09"}],"explanation":["「톡톡」·「첨벙첨벙」·「랄랄라」가 신나는 기분을 줘요.","무섭거나 슬픈 말은 시에 없어요.","시에 나오는 말에서 기분을 느껴 봐요."],"asset":{"type":"passage","lines":["톡톡 빗방울이","우산 위에서 춤을 춰요","첨벙첨벙 웅덩이","랄랄라 노래해요"],"title":"비 오는 날"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 이 시에서 느껴지는 분위기는 어느 것인가요?","options":[{"t":"조용한","correct":true},{"t":"시끄러운","mis":"K2-1-u4-X09"},{"t":"화난","mis":"K2-1-u4-X09"}],"explanation":["「살며시」·「쉿」·「새근새근」이 조용한 기분을 줘요.","시끄럽거나 화난 말은 시에 없어요.","시에 나오는 말에서 기분을 느껴 봐요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#8','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',2,'sa','auto','받침 자리에 서로 다른 글자가 두 개 있는 받침을 무엇이라고 하나요? 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u4-C1","difficulty":2,"kind":"sa","stem":"받침 자리에 서로 다른 글자가 두 개 있는 받침을 무엇이라고 하나요? 세 글자로 써 보세요.","answer":["겹받침"],"explanation":["「닭」의 ㄺ, 「값」의 ㅄ 같은 받침을 겹받침이라고 해요.","받침 글자가 하나인 받침과 달라요.","읽을 때는 한 소리로 읽어요."],"variant_rule":{"alt":[{"stem":"「앉다」의 ㄵ, 「짧다」의 ㄼ처럼 받침 자리에 서로 다른 글자가 두 개 있는 받침을 무엇이라고 하나요? 세 글자로 써 보세요.","answer":["겹받침"],"explanation":["ㄵ·ㄼ처럼 두 글자가 함께 있는 받침을 겹받침이라고 해요.","받침 글자가 하나인 받침과 달라요.","읽을 때는 한 소리로 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#9','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C5',2,'mc','auto','분위기를 살려 읽으면 어떤 점이 좋을까요?',ARRAY['K2-1-u4-X12','K2-1-u4-X08']::text[],true,'{"seq":9,"concept":"K2-1-u4-C5","difficulty":2,"kind":"mc","stem":"분위기를 살려 읽으면 어떤 점이 좋을까요?","options":[{"t":"글의 기분이 살아나 더 재미있게 느껴져요","correct":true},{"t":"글자를 더 빨리 읽을 수 있어요","mis":"K2-1-u4-X12"},{"t":"글의 내용이 다른 이야기로 바뀌어요","mis":"K2-1-u4-X08"}],"explanation":["분위기를 살려 읽으면 글의 기분이 잘 전해져요.","빨리 읽거나 내용을 바꾸는 것이 아니에요.","듣는 사람도 더 재미있게 느껴요."],"variant_rule":{"alt":[{"stem":"같은 시라도 분위기를 살려 읽으면 어떻게 될까요?","options":[{"t":"시의 기분이 듣는 사람에게 더 잘 전해져요","correct":true},{"t":"시의 글자가 바뀌어요","mis":"K2-1-u4-X08"},{"t":"시가 더 짧아져요","mis":"K2-1-u4-X08"}],"explanation":["분위기를 살려 읽으면 시의 기분이 잘 전해져요.","글자나 길이가 바뀌는 것이 아니에요.","그래서 시가 더 재미있게 느껴져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#10','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',3,'error','auto','「마당에 닭이 앉아 흙을 쪼아요.」에서 겹받침이 있는 글자를 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K2-1-u4-X05','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C1","difficulty":3,"kind":"error","stem":"「마당에 닭이 앉아 흙을 쪼아요.」에서 겹받침이 있는 글자를 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"하린 — 「당」","correct":true,"mis_target":"K2-1-u4-X05"},{"t":"도윤 — 「닭」","mis":"K2-1-u4-X17"},{"t":"서아 — 「흙」","mis":"K2-1-u4-X17"}],"explanation":["「당」은 받침이 ㅇ 하나뿐이에요.","「닭」·「앉」·「흙」이 겹받침이 있는 글자예요.","도윤이와 서아는 바르게 찾았어요."],"variant_rule":{"alt":[{"stem":"「하늘이 맑아 넓은 들판에 앉았어요.」에서 겹받침이 있는 글자를 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"준우 — 「늘」","correct":true,"mis_target":"K2-1-u4-X05"},{"t":"지안 — 「맑」","mis":"K2-1-u4-X17"},{"t":"예린 — 「넓」","mis":"K2-1-u4-X17"}],"explanation":["「늘」은 받침이 ㄹ 하나뿐이에요.","「맑」·「넓」·「앉」이 겹받침이 있는 글자예요.","지안이와 예린이는 바르게 찾았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#1','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C1',2,'mc','auto','ㄲ·ㅆ처럼 같은 글자가 두 개인 받침은 겹받침이 아니에요. 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":2,"kind":"mc","stem":"ㄲ·ㅆ처럼 같은 글자가 두 개인 받침은 겹받침이 아니에요. 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"읽다","correct":true},{"t":"있다","mis":"K2-1-u4-X05"},{"t":"밖","mis":"K2-1-u4-X05"}],"explanation":["「읽다」의 받침 ㄺ은 서로 다른 두 글자예요.","「있다」의 ㅆ, 「밖」의 ㄲ은 같은 글자가 두 개예요.","겹받침은 서로 다른 두 글자가 함께 있는 받침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#2','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C5',2,'mc','auto','분위기에 대해 바르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":2,"concept":"K2-1-u4-C5","difficulty":2,"kind":"mc","stem":"분위기에 대해 바르게 말한 친구는 누구인가요?","options":[{"t":"지호 — 「시에 나오는 말과 장면에서 분위기를 느낄 수 있어.」","correct":true},{"t":"민지 — 「분위기는 시에 나오는 사람 이름이야.」","mis":"K2-1-u4-X08"},{"t":"하준 — 「분위기는 글자가 많을수록 신나.」","mis":"K2-1-u4-X08"}],"explanation":["시의 말과 장면이 기분을 만들어요.","사람 이름이나 글자 수는 분위기가 아니에요.","지호가 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#3','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C2',3,'mc','auto','겹받침 낱말을 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X02','K2-1-u4-X03']::text[],false,'{"seq":3,"concept":"K2-1-u4-C2","difficulty":3,"kind":"mc","stem":"겹받침 낱말을 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"받침 두 글자 가운데 한 글자의 소리로 읽어요","correct":true},{"t":"받침 두 글자를 모두 소리 내어 읽어요","mis":"K2-1-u4-X02"},{"t":"받침 두 글자 가운데 아무 쪽이나 골라 읽어요","mis":"K2-1-u4-X03"}],"explanation":["겹받침은 정해진 한 글자의 소리로 읽어요.","두 글자를 다 소리 내면 틀려요.","아무 쪽이나가 아니라 ㄺ은 [ㄱ], ㄼ은 [ㄹ]처럼 정해져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#4','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C2',3,'error','auto','낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"시우 — 「흙 → [흘]」","correct":true,"mis_target":"K2-1-u4-X03"},{"t":"다은 — 「닭 → [닥]」","mis":"K2-1-u4-X17"},{"t":"로아 — 「값 → [갑]」","mis":"K2-1-u4-X17"}],"explanation":["「흙」은 [흑]이라고 읽어요.","ㄺ 받침은 [ㄱ] 소리가 나요.","다은이와 로아는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#5','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C1',3,'ox','auto','「손」과 「산」에는 겹받침이 있어요.',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":5,"concept":"K2-1-u4-C1","difficulty":3,"kind":"ox","stem":"「손」과 「산」에는 겹받침이 있어요.","answer":"X","reason_options":[{"t":"받침이 ㄴ 하나뿐이니까","correct":true},{"t":"받침이 있으면 모두 겹받침이니까","mis":"K2-1-u4-X05"}],"mis":"K2-1-u4-X05","explanation":["「손」·「산」의 받침은 ㄴ 하나예요.","받침 자리에 서로 다른 글자가 두 개 있어야 겹받침이에요.","「닭」·「값」과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#6','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C5',3,'mc','auto','두 시를 읽고 분위기를 바르게 짝지은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#7','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C1',3,'mc','auto','「여덟 개의 사과가 바구니에 많이 있어요.」에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":7,"concept":"K2-1-u4-C1","difficulty":3,"kind":"mc","stem":"「여덟 개의 사과가 바구니에 많이 있어요.」에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?","options":[{"t":"덟 · 많","correct":true},{"t":"덟 · 많 · 있","mis":"K2-1-u4-X05"},{"t":"사 · 과","mis":"K2-1-u4-X05"}],"explanation":["「덟」은 ㄼ, 「많」은 ㄶ 받침이에요.","「있」의 ㅆ은 같은 글자가 두 개라 겹받침이 아니에요.","「사」·「과」는 받침이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#8','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C2',4,'mc','auto','「짧다」를 [짭따]라고 읽은 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X02','K2-1-u4-X04']::text[],false,'{"seq":8,"concept":"K2-1-u4-C2","difficulty":4,"kind":"mc","stem":"「짧다」를 [짭따]라고 읽은 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「ㄼ 받침은 [ㄹ] 소리가 나서 [짤따]라고 읽어.」","correct":true},{"t":"「받침 두 글자를 다 살려 [짤ㅂ다]라고 읽어.」","mis":"K2-1-u4-X02"},{"t":"「뒤 글자는 그대로 두고 [짤다]라고 읽어.」","mis":"K2-1-u4-X04"}],"explanation":["「짧다」는 [짤따]라고 읽어요.","두 글자를 다 소리 내면 안 돼요.","뒤 글자 「다」는 [따]로 세게 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#9','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C1',4,'essay','teacher','겹받침이 무엇인지 쓰고, 겹받침이 있는 낱말을 두 개 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C1","difficulty":4,"kind":"essay","stem":"겹받침이 무엇인지 쓰고, 겹받침이 있는 낱말을 두 개 써 보세요.","answer_guide":{"answer":"예: 겹받침은 받침 자리에 서로 다른 글자가 두 개 있는 받침이에요. 닭, 값.","scoring_points":["받침 자리에 서로 다른 글자가 두 개라고 썼는가","겹받침 낱말을 두 개 썼는가","쓴 낱말이 홑받침·쌍받침 낱말이 아닌가"]},"explanation":["겹받침의 뜻.","겹받침 낱말 두 개.","홑받침·쌍받침과 가리기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#10','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C5',4,'essay','teacher','분위기가 무엇인지 쓰고, 신나는 분위기와 조용한 분위기가 느껴지는 장면을 하나씩 떠올려 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C5","difficulty":4,"kind":"essay","stem":"분위기가 무엇인지 쓰고, 신나는 분위기와 조용한 분위기가 느껴지는 장면을 하나씩 떠올려 써 보세요.","answer_guide":{"answer":"예: 분위기는 글이나 시에서 느껴지는 기분이에요. 신나는 분위기 — 운동장에서 친구들과 공을 차는 장면. 조용한 분위기 — 아기가 새근새근 자는 밤.","scoring_points":["분위기의 뜻을 썼는가","신나는 장면을 알맞게 썼는가","조용한 장면을 알맞게 썼는가"]},"explanation":["분위기의 뜻.","신나는 장면.","조용한 장면."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#1','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',1,'mc','auto','「앉다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X04','K2-1-u4-X03']::text[],true,'{"seq":1,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「앉다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[안따]","correct":true},{"t":"[안다]","mis":"K2-1-u4-X04"},{"t":"[앚따]","mis":"K2-1-u4-X03"}],"explanation":["ㄵ 받침은 [ㄴ] 소리가 나고, 뒤의 「다」는 [따]로 소리 나요.","[안다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요.","[앚따]는 다른 쪽 글자 소리로 읽었어요."],"variant_rule":{"alt":[{"stem":"「넓다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[널따]","correct":true},{"t":"[넙따]","mis":"K2-1-u4-X03"},{"t":"[널다]","mis":"K2-1-u4-X04"}],"explanation":["ㄼ 받침은 [ㄹ] 소리가 나고, 뒤의 「다」는 [따]로 소리 나요.","[넙따]는 다른 쪽 글자 소리로 읽었어요.","[널다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#2','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',1,'mc','auto','[갑]이라고 소리 나는, 물건을 살 때 치르는 돈을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],true,'{"seq":2,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[갑]이라고 소리 나는, 물건을 살 때 치르는 돈을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"갑","mis":"K2-1-u4-X01"},{"t":"갋","mis":"K2-1-u4-X06"}],"explanation":["[갑]으로 들려도 받침 두 글자를 살려 「값」이라고 써요.","「갑」은 소리 나는 대로 받침을 하나만 썼어요.","「갋」은 받침 짝을 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"[닥]이라고 소리 나는, 「꼬끼오」 하고 우는 동물을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"닥","mis":"K2-1-u4-X01"},{"t":"닯","mis":"K2-1-u4-X06"}],"explanation":["[닥]으로 들려도 받침 두 글자를 살려 「닭」이라고 써요.","「닥」은 소리 나는 대로 받침을 하나만 썼어요.","「닯」은 받침 짝을 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#3','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',1,'ox','auto','「흙」은 [흑]이라고 소리 나니까 「흑」이라고 써요.',ARRAY['K2-1-u4-X01']::text[],true,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"ox","stem":"「흙」은 [흑]이라고 소리 나니까 「흑」이라고 써요.","answer":"X","reason_options":[{"t":"소리는 하나여도 쓸 때는 받침 두 글자를 모두 살려 쓰니까","correct":true},{"t":"들리는 소리대로 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「흙」은 [흑]으로 읽지만 「흙」이라고 써요.","소리대로 쓰면 다른 글자가 돼요.","읽을 때와 쓸 때를 가려 기억해요."],"variant_rule":{"alt":[{"stem":"「닭」은 [닥]이라고 읽지만 쓸 때는 「닭」이라고 써요.","answer":"O","reason_options":[{"t":"읽는 소리와 쓰는 글자가 다를 수 있으니까","correct":true},{"t":"쓸 때도 소리대로 「닥」이라고 써야 하니까","mis":"K2-1-u4-X01"}],"explanation":["「닭」은 [닥]으로 읽고 「닭」으로 써요.","받침 두 글자를 모두 살려 써요.","읽을 때와 쓸 때를 가려 기억해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#4','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',1,'mc','auto','「맑다」의 ㄺ 받침은 어떤 소리로 읽나요?',ARRAY['K2-1-u4-X03','K2-1-u4-X02']::text[],true,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「맑다」의 ㄺ 받침은 어떤 소리로 읽나요?","options":[{"t":"[ㄱ] 소리","correct":true},{"t":"[ㄹ] 소리","mis":"K2-1-u4-X03"},{"t":"[ㄹ]과 [ㄱ] 소리 모두","mis":"K2-1-u4-X02"}],"explanation":["「맑다」는 [막따]라고 읽어요.","ㄺ 받침은 [ㄱ] 소리가 나요.","두 소리를 모두 내지 않아요."],"variant_rule":{"alt":[{"stem":"「짧다」의 ㄼ 받침은 어떤 소리로 읽나요?","options":[{"t":"[ㄹ] 소리","correct":true},{"t":"[ㅂ] 소리","mis":"K2-1-u4-X03"},{"t":"[ㄹ]과 [ㅂ] 소리 모두","mis":"K2-1-u4-X02"}],"explanation":["「짧다」는 [짤따]라고 읽어요.","ㄼ 받침은 [ㄹ] 소리가 나요.","두 소리를 모두 내지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#5','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"많다","r":"[만타]"},{"l":"읽다","r":"[익따]"},{"l":"짧다","r":"[짤따]"}],"mis":"K2-1-u4-X03","explanation":["「많다」는 [만타]라고 읽어요.","「읽다」는 [익따]라고 읽어요.","「짧다」는 [짤따]라고 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"없다","r":"[업따]"},{"l":"젊다","r":"[점따]"},{"l":"맑다","r":"[막따]"}],"explanation":["「없다」는 [업따]라고 읽어요.","「젊다」는 [점따]라고 읽어요.","「맑다」는 [막따]라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#6','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',2,'blank','auto','「의자에 (     ) 이야기를 들어요.」 [안자]라고 소리 나는 말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],true,'{"seq":6,"concept":"K2-1-u4-C3","difficulty":2,"kind":"blank","stem":"「의자에 (     ) 이야기를 들어요.」 [안자]라고 소리 나는 말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"앉아","correct":true},{"t":"안자","mis":"K2-1-u4-X01"},{"t":"않아","mis":"K2-1-u4-X06"}],"explanation":["엉덩이를 대고 몸을 올려놓는 것은 「앉아」라고 써요.","「안자」는 소리 나는 대로 썼어요.","「않아」는 받침 짝이 달라 뜻이 다른 말이 돼요."],"variant_rule":{"alt":[{"stem":"「동생 바지가 조금 (     ).」 [짤바요]라고 소리 나는 말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"짧아요","correct":true},{"t":"짤바요","mis":"K2-1-u4-X01"},{"t":"짭아요","mis":"K2-1-u4-X06"}],"explanation":["길이가 길지 않은 것은 「짧아요」라고 써요.","「짤바요」는 소리 나는 대로 썼어요.","「짭아요」는 받침 글자를 하나 빠뜨리고 다르게 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#7','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',2,'sa','auto','[흑]이라고 소리 나는, 식물을 심는 땅의 겉 부분을 바르게 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u4-C3","difficulty":2,"kind":"sa","stem":"[흑]이라고 소리 나는, 식물을 심는 땅의 겉 부분을 바르게 써 보세요.","answer":["흙"],"explanation":["[흑]으로 들려도 「흙」이라고 써요.","받침 자리에 ㄹ과 ㄱ을 모두 써요.","「흑」이라고 쓰면 틀려요."],"variant_rule":{"alt":[{"stem":"[갑]이라고 소리 나는 말이에요. 「이 연필의 (     )은 얼마예요?」 빈칸에 들어갈 말을 바르게 써 보세요.","answer":["값"],"explanation":["[갑]으로 들려도 「값」이라고 써요.","받침 자리에 ㅂ과 ㅅ을 모두 써요.","「갑」이라고 쓰면 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#8','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',2,'mc','auto','「읽다」를 [일따]라고 읽은 친구가 있어요. 바르게 고친 것은 어느 것인가요?',ARRAY['K2-1-u4-X02','K2-1-u4-X04']::text[],true,'{"seq":8,"concept":"K2-1-u4-C2","difficulty":2,"kind":"mc","stem":"「읽다」를 [일따]라고 읽은 친구가 있어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"[익따]","correct":true},{"t":"[읽따]","mis":"K2-1-u4-X02"},{"t":"[익다]","mis":"K2-1-u4-X04"}],"explanation":["ㄺ 받침은 [ㄱ] 소리가 나서 [익따]예요.","[읽따]는 두 글자를 다 살리려 한 거예요.","[익다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."],"variant_rule":{"alt":[{"stem":"「없다」를 [엇따]라고 읽은 친구가 있어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"[업따]","correct":true},{"t":"[없따]","mis":"K2-1-u4-X02"},{"t":"[업다]","mis":"K2-1-u4-X04"}],"explanation":["ㅄ 받침은 [ㅂ] 소리가 나서 [업따]예요.","[없따]는 두 글자를 다 살리려 한 거예요.","[업다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#9','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',2,'ox','auto','「넓다」와 「짧다」는 받침이 똑같이 [ㄹ] 소리로 나요.',ARRAY['K2-1-u4-X02']::text[],true,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"ox","stem":"「넓다」와 「짧다」는 받침이 똑같이 [ㄹ] 소리로 나요.","answer":"O","reason_options":[{"t":"두 낱말 모두 ㄼ 받침이라 [널따]·[짤따]로 읽으니까","correct":true},{"t":"받침 글자가 같으면 두 소리를 모두 내니까","mis":"K2-1-u4-X02"}],"mis":"K2-1-u4-X02","explanation":["「넓다」는 [널따], 「짧다」는 [짤따]예요.","ㄼ 받침은 [ㄹ] 소리가 나요.","받침이 같으면 소리 나는 방법도 같아요."],"variant_rule":{"alt":[{"stem":"「닭」과 「흙」은 받침이 [ㄹ] 소리로 나요.","answer":"X","reason_options":[{"t":"ㄺ 받침은 [ㄱ] 소리라 [닥]·[흑]으로 읽으니까","correct":true},{"t":"ㄺ의 앞 글자가 ㄹ이니까","mis":"K2-1-u4-X03"}],"explanation":["「닭」은 [닥], 「흙」은 [흑]이에요.","ㄺ 받침은 [ㄱ] 소리가 나요.","앞 글자라고 그 소리가 나는 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#10','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"하준 — 「흑 위에 꽃씨를 심었다.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"다은 — 「연필 값이 비싸다.」","mis":"K2-1-u4-X17"},{"t":"시우 — 「의자에 앉았다.」","mis":"K2-1-u4-X17"}],"explanation":["「흑」은 소리대로 쓴 거예요. 「흙」이라고 써야 해요.","다은이와 시우는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호 — 「사과가 여덜 개 있다.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"예린 — 「동화책을 읽었다.」","mis":"K2-1-u4-X17"},{"t":"소율 — 「운동장이 넓다.」","mis":"K2-1-u4-X17"}],"explanation":["「여덜」은 소리대로 쓴 거예요. 「여덟」이라고 써야 해요.","예린이와 소율이는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#1','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',2,'mc','auto','「사과가 (     ) 개 있어요.」 [여덜]이라고 소리 나는 수를 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":1,"concept":"K2-1-u4-C3","difficulty":2,"kind":"mc","stem":"「사과가 (     ) 개 있어요.」 [여덜]이라고 소리 나는 수를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"여덟","correct":true},{"t":"여덜","mis":"K2-1-u4-X01"},{"t":"여덥","mis":"K2-1-u4-X06"}],"explanation":["일곱 다음의 수는 「여덟」이라고 써요.","「여덜」은 소리 나는 대로 썼어요.","「여덥」은 받침 글자를 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#2','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',2,'mc','auto','받침이 [ㄱ] 소리로 나는 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":2,"kind":"mc","stem":"받침이 [ㄱ] 소리로 나는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"닭 · 흙 · 읽다","correct":true},{"t":"닭 · 넓다 · 읽다","mis":"K2-1-u4-X03"},{"t":"값 · 앉다 · 흙","mis":"K2-1-u4-X03"}],"explanation":["ㄺ 받침인 「닭」·「흙」·「읽다」는 [ㄱ] 소리가 나요.","「넓다」는 [ㄹ], 「값」은 [ㅂ], 「앉다」는 [ㄴ] 소리가 나요.","받침 짝마다 나는 소리가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#3','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',3,'mc','auto','「젊다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X04']::text[],false,'{"seq":3,"concept":"K2-1-u4-C2","difficulty":3,"kind":"mc","stem":"「젊다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[점따]","correct":true},{"t":"[절따]","mis":"K2-1-u4-X03"},{"t":"[점다]","mis":"K2-1-u4-X04"}],"explanation":["ㄻ 받침은 [ㅁ] 소리가 나고, 뒤의 「다」는 [따]로 소리 나요.","[절따]는 다른 쪽 글자 소리로 읽었어요.","[점다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#4','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X04','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"은솔 — 「앉다 → [안다]」","correct":true,"mis_target":"K2-1-u4-X04"},{"t":"태민 — 「많다 → [만타]」","mis":"K2-1-u4-X17"},{"t":"아린 — 「맑다 → [막따]」","mis":"K2-1-u4-X17"}],"explanation":["「앉다」는 [안따]라고 읽어요.","뒤의 「다」가 [따]로 세게 소리 나요.","태민이와 아린이는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#5','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',3,'mc','auto','받아쓰기에서 바르게 쓴 문장은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":5,"concept":"K2-1-u4-C3","difficulty":3,"kind":"mc","stem":"받아쓰기에서 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「닭이 모이를 먹는다.」","correct":true},{"t":"「닥이 모이를 먹는다.」","mis":"K2-1-u4-X01"},{"t":"「닯이 모이를 먹는다.」","mis":"K2-1-u4-X06"}],"explanation":["「닭」은 받침 ㄹ과 ㄱ을 모두 써요.","「닥」은 소리 나는 대로 썼어요.","「닯」은 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#6','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',3,'ox','auto','[안따]로 소리 나는 「앉다」와 [안타]로 소리 나는 「않다」는 받침 글자가 서로 달라요.',ARRAY['K2-1-u4-X06']::text[],false,'{"seq":6,"concept":"K2-1-u4-C3","difficulty":3,"kind":"ox","stem":"[안따]로 소리 나는 「앉다」와 [안타]로 소리 나는 「않다」는 받침 글자가 서로 달라요.","answer":"O","reason_options":[{"t":"「앉다」는 ㄵ, 「않다」는 ㄶ 받침이니까","correct":true},{"t":"소리가 비슷하면 글자도 같으니까","mis":"K2-1-u4-X06"}],"mis":"K2-1-u4-X06","explanation":["「앉다」는 ㄵ, 「않다」는 ㄶ 받침이에요.","소리가 비슷해도 받침 짝이 다르면 뜻이 다른 말이에요.","뜻을 떠올리며 받침을 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#7','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',3,'mc','auto','받침이 나머지와 다른 소리로 나는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X03']::text[],false,'{"seq":7,"concept":"K2-1-u4-C2","difficulty":3,"kind":"mc","stem":"받침이 나머지와 다른 소리로 나는 낱말은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"넓다","mis":"K2-1-u4-X03"},{"t":"짧다","mis":"K2-1-u4-X03"}],"explanation":["「값」의 ㅄ은 [ㅂ] 소리가 나요.","「넓다」·「짧다」의 ㄼ은 둘 다 [ㄹ] 소리가 나요.","받침 짝마다 나는 소리를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#8','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',4,'mc','auto','[흑]·[닥]·[갑]처럼 들리는 낱말을 쓸 때 기억할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":8,"concept":"K2-1-u4-C3","difficulty":4,"kind":"mc","stem":"[흑]·[닥]·[갑]처럼 들리는 낱말을 쓸 때 기억할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"소리는 하나여도 받침 두 글자를 모두 살려 써요","correct":true},{"t":"들리는 소리 그대로 받침을 하나만 써요","mis":"K2-1-u4-X01"},{"t":"받침 두 글자를 아무것이나 골라 써요","mis":"K2-1-u4-X06"}],"explanation":["「흙」·「닭」·「값」처럼 받침 두 글자를 모두 써요.","소리대로 받침을 하나만 쓰면 틀려요.","받침 짝은 낱말마다 정해져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#9','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',4,'essay','teacher','받아쓰기 공책에 「값」을 「갑」이라고 쓴 친구가 있어요. 바르게 쓰는 방법과 그렇게 써야 하는 까닭을 친구에게 알려 주는 말로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C3","difficulty":4,"kind":"essay","stem":"받아쓰기 공책에 「값」을 「갑」이라고 쓴 친구가 있어요. 바르게 쓰는 방법과 그렇게 써야 하는 까닭을 친구에게 알려 주는 말로 써 보세요.","answer_guide":{"answer":"예: 「값」은 [갑]으로 소리 나지만 받침 ㅂ과 ㅅ을 모두 살려 「값」이라고 써야 해. 겹받침은 읽을 때 한 소리만 나도 쓸 때는 두 글자를 다 쓰거든.","scoring_points":["「값」으로 바르게 고쳐 썼는가","받침 두 글자(ㅂ·ㅅ)를 모두 살려 써야 함을 썼는가","읽는 소리와 쓰는 글자가 다를 수 있다는 까닭을 썼는가"]},"explanation":["바르게 고치기.","받침 두 글자.","소리와 글자의 차이."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#10','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',4,'essay','teacher','「닭」, 「앉다」, 「넓다」를 바르게 읽는 소리를 쓰고, 겹받침 낱말을 바르게 읽는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C2","difficulty":4,"kind":"essay","stem":"「닭」, 「앉다」, 「넓다」를 바르게 읽는 소리를 쓰고, 겹받침 낱말을 바르게 읽는 방법을 써 보세요.","answer_guide":{"answer":"예: [닥], [안따], [널따]. 겹받침은 받침 두 글자 가운데 한 글자의 소리로 읽어요.","scoring_points":["세 낱말의 소리를 바르게 썼는가","뒤 글자가 세게 나는 소리([따])까지 살렸는가","겹받침은 한 글자 소리로 읽는다는 방법을 썼는가"]},"explanation":["바른 소리 셋.","뒤 글자 소리.","읽는 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#1','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',1,'mc','auto','글을 읽고 답해 보세요. 할머니와 텃밭에 가서 고른 것은 무엇인가요?',ARRAY['K2-1-u4-X07']::text[],true,'{"seq":1,"concept":"K2-1-u4-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 할머니와 텃밭에 가서 고른 것은 무엇인가요?","options":[{"t":"흙","correct":true},{"t":"닭","mis":"K2-1-u4-X07"},{"t":"바구니","mis":"K2-1-u4-X07"}],"explanation":["「할머니와 텃밭에 가서 흙을 골랐어요.」라고 했어요.","닭은 흙을 밟고 지나갔고, 바구니에는 채소를 담았어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 토요일에 언니와 간 곳은 어디인가요?","options":[{"t":"도서관","correct":true},{"t":"시장","mis":"K2-1-u4-X07"},{"t":"텃밭","mis":"K2-1-u4-X07"}],"explanation":["「토요일에 언니와 도서관에 갔어요.」라고 했어요.","시장이나 텃밭은 글에 나오지 않아요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#2','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',1,'mc','auto','글을 읽고 답해 보세요. 글에 나온 낱말 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":2,"concept":"K2-1-u4-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 낱말 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"하늘이","mis":"K2-1-u4-X05"},{"t":"상추","mis":"K2-1-u4-X05"}],"explanation":["「닭」은 받침 자리에 ㄹ과 ㄱ이 있어요.","「하늘이」의 「늘」은 받침이 하나, 「상추」의 「상」도 받침이 하나예요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 글에 나온 낱말 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"읽었어요","correct":true},{"t":"언니와","mis":"K2-1-u4-X05"},{"t":"그림책을","mis":"K2-1-u4-X05"}],"explanation":["「읽었어요」의 「읽」은 받침이 ㄺ이에요.","「언니와」·「그림책을」에는 겹받침이 없어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#3','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C2',1,'mc','auto','글을 읽고 답해 보세요. 글에 나온 「흙」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X02']::text[],true,'{"seq":3,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 「흙」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[흑]","correct":true},{"t":"[흘]","mis":"K2-1-u4-X03"},{"t":"[흘ㄱ]","mis":"K2-1-u4-X02"}],"explanation":["ㄺ 받침은 [ㄱ] 소리가 나서 [흑]이에요.","[흘]은 다른 쪽 글자 소리로 읽었어요.","두 글자를 모두 소리 내지 않아요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 글에 나온 「값」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[갑]","correct":true},{"t":"[갓]","mis":"K2-1-u4-X03"},{"t":"[갑ㅅ]","mis":"K2-1-u4-X02"}],"explanation":["ㅄ 받침은 [ㅂ] 소리가 나서 [갑]이에요.","[갓]은 다른 쪽 글자 소리로 읽었어요.","두 글자를 모두 소리 내지 않아요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#4','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',1,'ox','auto','글을 읽고 답해 보세요. 상추 잎은 넓고 고추는 짧아요.',ARRAY['K2-1-u4-X07']::text[],true,'{"seq":4,"concept":"K2-1-u4-C4","difficulty":1,"kind":"ox","stem":"글을 읽고 답해 보세요. 상추 잎은 넓고 고추는 짧아요.","answer":"O","reason_options":[{"t":"글에 그렇게 쓰여 있으니까","correct":true},{"t":"고추가 상추보다 크니까","mis":"K2-1-u4-X07"}],"mis":"K2-1-u4-X07","explanation":["「상추 잎은 넓고 고추는 짧아요.」라고 했어요.","글에 쓰인 내용으로 답해요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 도서관에서 책을 한 권만 빌렸어요.","answer":"X","reason_options":[{"t":"읽고 싶은 책이 많아서 두 권을 빌렸다고 했으니까","correct":true},{"t":"도서관에서는 한 권만 빌릴 수 있으니까","mis":"K2-1-u4-X07"}],"explanation":["「두 권을 빌렸어요.」라고 했어요.","글에 없는 내용으로 답하면 안 돼요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#5','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C2',2,'match','auto','글에 나온 낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"글에 나온 낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"흙","r":"[흑]"},{"l":"밟고","r":"[밥꼬]"},{"l":"닭","r":"[닥]"}],"mis":"K2-1-u4-X03","explanation":["「흙」은 [흑]이라고 읽어요.","「밟고」는 [밥꼬]라고 읽어요.","「닭」은 [닥]이라고 읽어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글에 나온 낱말의 기본 모양과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"값","r":"[갑]"},{"l":"많다","r":"[만타]"},{"l":"없다","r":"[업따]"}],"explanation":["「값」은 [갑]이라고 읽어요.","「많다」는 [만타]라고 읽어요.","「없다」는 [업따]라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#6','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":6,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"맑은 · 닭 · 넓고","correct":true},{"t":"하늘이 · 닭 · 넓고","mis":"K2-1-u4-X05"},{"t":"텃밭에 · 상추 · 고추는","mis":"K2-1-u4-X05"}],"explanation":["「맑은」·「닭」·「넓고」는 모두 겹받침이 있어요.","「하늘이」·「텃밭에」·「상추」·「고추는」에는 겹받침이 없어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"앉아 · 읽고 · 많아서","correct":true},{"t":"언니와 · 읽고 · 많아서","mis":"K2-1-u4-X05"},{"t":"의자에 · 바닷가는 · 두","mis":"K2-1-u4-X05"}],"explanation":["「앉아」·「읽고」·「많아서」는 모두 겹받침이 있어요.","「언니와」·「의자에」·「바닷가는」에는 겹받침이 없어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#7','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 바구니가 묵직했던 까닭은 무엇인가요?',ARRAY['K2-1-u4-X07']::text[],true,'{"seq":7,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 바구니가 묵직했던 까닭은 무엇인가요?","options":[{"t":"채소가 많아서","correct":true},{"t":"닭이 들어가서","mis":"K2-1-u4-X07"},{"t":"흙을 가득 담아서","mis":"K2-1-u4-X07"}],"explanation":["「바구니에 채소가 많아서 묵직했어요.」라고 했어요.","닭이나 흙을 담았다는 말은 글에 없어요.","글에 쓰인 까닭을 찾아요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 떡이 하나도 남지 않은 까닭은 무엇인가요?","options":[{"t":"동생과 나누어 먹어서","correct":true},{"t":"값이 비싸서","mis":"K2-1-u4-X07"},{"t":"떡집에 사람이 많아서","mis":"K2-1-u4-X07"}],"explanation":["「동생과 나누어 먹으니 남은 떡이 없었어요.」라고 했어요.","다른 까닭은 글에 없어요.","글에 쓰인 까닭을 찾아요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#8','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',2,'sa','auto','글을 읽고 답해 보세요. 흙을 밟고 지나간 동물의 이름을 글에서 찾아 바르게 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u4-C4","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 흙을 밟고 지나간 동물의 이름을 글에서 찾아 바르게 써 보세요.","answer":["닭"],"explanation":["「닭 한 마리가 흙을 밟고 지나갔어요.」라고 했어요.","[닥]으로 읽지만 「닭」이라고 써요.","받침 ㄹ과 ㄱ을 모두 써요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 엄마가 물어보신 것은 꿀떡의 무엇인가요? 글에서 찾아 바르게 써 보세요.","answer":["값"],"explanation":["「엄마가 꿀떡 값을 물어보셨어요.」라고 했어요.","[갑]으로 읽지만 「값」이라고 써요.","받침 ㅂ과 ㅅ을 모두 써요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#9','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',2,'mc','auto','글을 읽다가 겹받침 낱말이 나오면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u4-X07','K2-1-u4-X02']::text[],true,'{"seq":9,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽다가 겹받침 낱말이 나오면 어떻게 읽으면 좋을까요?","options":[{"t":"잠깐 멈추고 바른 소리를 떠올려 읽어요","correct":true},{"t":"겹받침 낱말은 건너뛰고 읽어요","mis":"K2-1-u4-X07"},{"t":"받침 두 글자를 모두 소리 내어 읽어요","mis":"K2-1-u4-X02"}],"explanation":["겹받침 낱말에서 잠깐 멈추면 바른 소리로 읽을 수 있어요.","건너뛰면 글의 뜻을 놓쳐요.","두 글자를 다 소리 내면 틀려요."],"variant_rule":{"alt":[{"stem":"글 속 겹받침 낱말을 바르게 읽으면서 함께 생각할 것은 무엇인가요?","options":[{"t":"글이 무슨 내용인지","correct":true},{"t":"글에 글자가 몇 개인지","mis":"K2-1-u4-X07"},{"t":"받침 글자 모양이 예쁜지","mis":"K2-1-u4-X07"}],"explanation":["바르게 읽으면서 글의 내용도 함께 떠올려요.","글자 수나 글자 모양은 글의 내용이 아니에요.","그래야 글을 잘 읽은 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#10','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',3,'error','auto','글을 읽고 겹받침 낱말을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K2-1-u4-X05','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 겹받침 낱말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"현우 — 「텃밭에」","correct":true,"mis_target":"K2-1-u4-X05"},{"t":"지안 — 「밟고」","mis":"K2-1-u4-X17"},{"t":"도담 — 「많아서」","mis":"K2-1-u4-X17"}],"explanation":["「텃」과 「밭」은 받침이 하나씩뿐이라 겹받침이 아니에요.","「밟고」·「많아서」는 겹받침 낱말이에요.","지안이와 도담이는 바르게 찾았어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 겹받침 낱말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"예린 — 「바닷가는」","correct":true,"mis_target":"K2-1-u4-X05"},{"t":"하준 — 「앉아」","mis":"K2-1-u4-X17"},{"t":"서아 — 「넓었어요」","mis":"K2-1-u4-X17"}],"explanation":["「바닷가는」에는 겹받침이 없어요.","「앉아」·「넓었어요」는 겹받침 낱말이에요.","하준이와 서아는 바르게 찾았어요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#1','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말을 모두 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말을 모두 모은 것은 어느 것인가요?","options":[{"t":"많았어요 · 값 · 없었어요","correct":true},{"t":"많았어요 · 값 · 떡집","mis":"K2-1-u4-X05"},{"t":"시장에 · 값 · 없었어요","mis":"K2-1-u4-X05"}],"explanation":["「많았어요」·「값」·「없었어요」에 겹받침이 있어요.","「떡집」·「시장에」에는 겹받침이 없어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#2','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 「나」는 도서관에서 어디에 앉았나요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":2,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「나」는 도서관에서 어디에 앉았나요?","options":[{"t":"창가 의자","correct":true},{"t":"바닷가 모래밭","mis":"K2-1-u4-X07"},{"t":"언니 옆 바닥","mis":"K2-1-u4-X07"}],"explanation":["「창가 의자에 앉아 그림책을 읽었어요.」라고 했어요.","바닷가 모래밭은 책 속 장면이에요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#3','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C2',3,'mc','auto','글을 읽고 답해 보세요. 글에 나온 「맑은」의 기본 모양 「맑다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X04']::text[],false,'{"seq":3,"concept":"K2-1-u4-C2","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 「맑은」의 기본 모양 「맑다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[막따]","correct":true},{"t":"[말따]","mis":"K2-1-u4-X03"},{"t":"[막다]","mis":"K2-1-u4-X04"}],"explanation":["ㄺ 받침은 [ㄱ] 소리가 나고, 뒤의 「다」는 [따]로 소리 나요.","[말따]는 다른 쪽 글자 소리로 읽었어요.","[막다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#4','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C2',3,'error','auto','글에 나온 낱말의 기본 모양을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"글에 나온 낱말의 기본 모양을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"민호 — 「값 → [갓]」","correct":true,"mis_target":"K2-1-u4-X03"},{"t":"하린 — 「없다 → [업따]」","mis":"K2-1-u4-X17"},{"t":"지후 — 「많다 → [만타]」","mis":"K2-1-u4-X17"}],"explanation":["「값」은 [갑]이라고 읽어요.","ㅄ 받침은 [ㅂ] 소리가 나요.","하린이와 지후는 바르게 읽었어요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#5','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',3,'ox','auto','글을 읽고 답해 보세요. 책 속 바닷가는 모래밭이 짧았어요.',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":5,"concept":"K2-1-u4-C4","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 책 속 바닷가는 모래밭이 짧았어요.","answer":"X","reason_options":[{"t":"글에 모래밭이 넓었다고 했으니까","correct":true},{"t":"바닷가 모래밭은 원래 짧으니까","mis":"K2-1-u4-X07"}],"mis":"K2-1-u4-X07","explanation":["「책 속 바닷가는 모래밭이 넓었어요.」라고 했어요.","글에 없는 내용으로 답하면 안 돼요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#6','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글을 소리 내어 읽을 때 잠깐 멈추어 바른 소리를 떠올려야 할 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":6,"concept":"K2-1-u4-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글을 소리 내어 읽을 때 잠깐 멈추어 바른 소리를 떠올려야 할 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"흙 · 닭 · 밟고","correct":true},{"t":"할머니 · 텃밭 · 바구니","mis":"K2-1-u4-X05"},{"t":"상추 · 고추 · 채소","mis":"K2-1-u4-X05"}],"explanation":["「흙」·「닭」·「밟고」는 겹받침 낱말이에요.","다른 낱말에는 겹받침이 없어요.","겹받침 낱말에서 멈추어 바르게 읽어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#7','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',3,'mc','auto','글을 읽고 답해 보세요. 글쓴이의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":7,"concept":"K2-1-u4-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 글쓴이의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 싶은 책이 많아 신나는 마음","correct":true},{"t":"책이 없어서 속상한 마음","mis":"K2-1-u4-X07"},{"t":"바닷가에 못 가서 서운한 마음","mis":"K2-1-u4-X07"}],"explanation":["읽고 싶은 책이 많아서 두 권을 빌렸다고 했어요.","책이 없거나 바닷가에 못 갔다는 말은 글에 없어요.","글의 내용에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#8','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',4,'mc','auto','글 속 겹받침 낱말을 바르게 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X12','K2-1-u4-X07']::text[],false,'{"seq":8,"concept":"K2-1-u4-C4","difficulty":4,"kind":"mc","stem":"글 속 겹받침 낱말을 바르게 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"낱말의 뜻이 바르게 전해져 글 내용을 잘 알 수 있어요","correct":true},{"t":"글을 더 빨리 끝낼 수 있어요","mis":"K2-1-u4-X12"},{"t":"겹받침 낱말을 건너뛰어도 돼요","mis":"K2-1-u4-X07"}],"explanation":["바르게 읽어야 듣는 사람도 뜻을 바르게 알아들어요.","빨리 읽는 것이 목적이 아니에요.","겹받침 낱말을 건너뛰면 내용을 놓쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#9','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',4,'essay','teacher','「할머니의 텃밭」에서 겹받침 낱말을 세 개 찾아 쓰고, 그 가운데 하나를 바르게 읽는 소리를 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C4","difficulty":4,"kind":"essay","stem":"「할머니의 텃밭」에서 겹받침 낱말을 세 개 찾아 쓰고, 그 가운데 하나를 바르게 읽는 소리를 써 보세요.","answer_guide":{"answer":"예: 닭, 흙, 넓고 — 「닭」은 [닥]이라고 읽어요.","scoring_points":["글에 나온 겹받침 낱말을 세 개 찾았는가","겹받침이 없는 낱말을 섞지 않았는가","고른 낱말의 바른 소리를 썼는가"]},"explanation":["겹받침 낱말 셋.","섞지 않기.","바른 소리."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#10','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',4,'essay','teacher','닭·흙·앉다·많다 가운데 두 개 이상을 넣어 내가 겪은 일을 두 문장으로 쓰고, 넣은 겹받침 낱말에 밑줄을 그어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C4","difficulty":4,"kind":"essay","stem":"닭·흙·앉다·많다 가운데 두 개 이상을 넣어 내가 겪은 일을 두 문장으로 쓰고, 넣은 겹받침 낱말에 밑줄을 그어 보세요.","answer_guide":{"answer":"예: 할머니 댁 마당에서 닭이 흙을 파고 있었다. 나는 마루에 앉아 한참 동안 구경했다.","scoring_points":["겹받침 낱말을 두 개 이상 넣었는가","겹받침 낱말을 받침 두 글자를 살려 바르게 썼는가","겪은 일이 드러나게 두 문장으로 썼는가"]},"explanation":["겹받침 낱말 두 개 이상.","바르게 쓰기.","두 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#1','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],true,'{"seq":1,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"신나는","correct":true},{"t":"슬픈","mis":"K2-1-u4-X09"},{"t":"무서운","mis":"K2-1-u4-X09"}],"explanation":["「통통」·「콩콩」·「와아」가 신나는 기분을 줘요.","슬프거나 무서운 말은 시에 없어요.","시에 나오는 말에서 분위기를 느껴요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"조용한","correct":true},{"t":"시끄러운","mis":"K2-1-u4-X09"},{"t":"화난","mis":"K2-1-u4-X09"}],"explanation":["「살며시」·「쉿」·「새근새근」이 조용한 기분을 줘요.","시끄럽거나 화난 말은 시에 없어요.","시에 나오는 말에서 분위기를 느껴요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#2','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',1,'mc','auto','신나는 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],true,'{"seq":2,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"신나는 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"콩콩","correct":true},{"t":"살며시","mis":"K2-1-u4-X10"},{"t":"가만히","mis":"K2-1-u4-X10"}],"explanation":["「콩콩」은 힘차게 뛰는 신나는 느낌을 줘요.","「살며시」·「가만히」는 조용한 느낌을 줘요.","소리 내어 따라 하며 느껴 봐요."],"variant_rule":{"alt":[{"stem":"조용한 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"살며시","correct":true},{"t":"통통","mis":"K2-1-u4-X10"},{"t":"와아","mis":"K2-1-u4-X10"}],"explanation":["「살며시」는 소리 없이 가만가만 움직이는 느낌을 줘요.","「통통」·「와아」는 신나는 느낌을 줘요.","소리 내어 따라 하며 느껴 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#3','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',1,'ox','auto','시를 읽고 답해 보세요. 이 시에서는 포근한 분위기가 느껴져요.',ARRAY['K2-1-u4-X08']::text[],true,'{"seq":3,"concept":"K2-1-u4-C6","difficulty":1,"kind":"ox","stem":"시를 읽고 답해 보세요. 이 시에서는 포근한 분위기가 느껴져요.","answer":"O","reason_options":[{"t":"「따스한 햇살」·「엄마 품」 같은 말이 포근하게 느껴지니까","correct":true},{"t":"시가 짧으면 언제나 포근하니까","mis":"K2-1-u4-X08"}],"mis":"K2-1-u4-X08","explanation":["따스한 햇살과 엄마 품이 포근한 기분을 줘요.","시의 길이로 분위기가 정해지지 않아요.","시의 말과 장면을 살펴요."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 이 시에서는 시끌벅적하고 신나는 분위기가 느껴져요.","answer":"X","reason_options":[{"t":"「살며시」·「쉿」·「새근새근」이 조용한 느낌을 주니까","correct":true},{"t":"달이 나오는 시는 모두 신나니까","mis":"K2-1-u4-X09"}],"explanation":["이 시는 조용한 분위기예요.","달이 나온다고 분위기가 정해지지 않아요.","시에 나오는 말을 살펴요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#4','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',1,'mc','auto','시의 분위기를 찾을 때 살펴보면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u4-X08']::text[],true,'{"seq":4,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시의 분위기를 찾을 때 살펴보면 좋은 것은 어느 것인가요?","options":[{"t":"시에 나오는 말과 장면","correct":true},{"t":"시의 글자 수","mis":"K2-1-u4-X08"},{"t":"시를 쓴 종이의 색깔","mis":"K2-1-u4-X08"}],"explanation":["시에 나오는 말과 장면이 기분을 만들어요.","글자 수나 종이 색깔은 분위기와 상관없어요.","소리 내어 읽으며 장면을 떠올려요."],"variant_rule":{"alt":[{"stem":"시의 분위기를 느끼는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"소리 내어 읽으며 장면을 떠올려요","correct":true},{"t":"글자 수를 세어 봐요","mis":"K2-1-u4-X08"},{"t":"제목만 읽고 넘어가요","mis":"K2-1-u4-X09"}],"explanation":["소리 내어 읽고 장면을 떠올리면 기분이 느껴져요.","글자 수를 세는 것은 분위기와 상관없어요.","제목만 읽으면 시의 말과 장면을 놓쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#5','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'match','auto','시의 장면과 어울리는 분위기를 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":2,"kind":"match","stem":"시의 장면과 어울리는 분위기를 이어 보세요.","pairs":[{"l":"콩콩 뛰는 운동장","r":"신나는"},{"l":"소복소복 눈 오는 밤","r":"조용한"},{"l":"따스한 봄 햇살","r":"포근한"}],"mis":"K2-1-u4-X09","explanation":["콩콩 뛰는 운동장은 신나는 분위기예요.","소복소복 눈 오는 밤은 조용한 분위기예요.","따스한 봄 햇살은 포근한 분위기예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시의 장면과 어울리는 분위기를 이어 보세요.","pairs":[{"l":"하나 둘 발맞추는 아이들","r":"씩씩한"},{"l":"톡톡 춤추는 빗방울","r":"신나는"},{"l":"새근새근 잠든 아기","r":"조용한"}],"explanation":["하나 둘 발맞추는 아이들은 씩씩한 분위기예요.","톡톡 춤추는 빗방울은 신나는 분위기예요.","새근새근 잠든 아기는 조용한 분위기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#6','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기가 조용하게 느껴지는 까닭은 무엇인가요?',ARRAY['K2-1-u4-X09','K2-1-u4-X08']::text[],true,'{"seq":6,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기가 조용하게 느껴지는 까닭은 무엇인가요?","options":[{"t":"「소리 없이」·「잠들어요」 같은 말이 고요한 장면을 보여 주니까","correct":true},{"t":"눈이 나오는 시는 언제나 조용하니까","mis":"K2-1-u4-X09"},{"t":"시가 네 줄이니까","mis":"K2-1-u4-X08"}],"explanation":["시의 말이 고요한 장면을 그려 줘요.","눈이 나와도 「펑펑, 눈싸움하자」처럼 신날 수 있어요.","줄 수는 분위기와 상관없어요."],"asset":{"type":"passage","lines":["소복소복 눈이","소리 없이 내려요","온 마을이","하얗게 잠들어요"],"title":"첫눈"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 이 시의 분위기가 신나게 느껴지는 까닭은 무엇인가요?","options":[{"t":"「통통」·「콩콩」·「와아」 같은 말이 뛰노는 장면을 보여 주니까","correct":true},{"t":"공은 언제나 신나는 물건이니까","mis":"K2-1-u4-X09"},{"t":"시가 네 줄이니까","mis":"K2-1-u4-X08"}],"explanation":["시의 말이 신나게 뛰노는 장면을 그려 줘요.","공이 나와도 시의 말에 따라 분위기는 달라져요.","줄 수는 분위기와 상관없어요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#7','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'blank','auto','신나는 분위기가 나도록 빈칸에 들어갈 말로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#8','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'mc','auto','같은 시를 읽고 느낀 분위기를 친구에게 말할 때 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X09','K2-1-u4-X08']::text[],true,'{"seq":8,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"같은 시를 읽고 느낀 분위기를 친구에게 말할 때 알맞은 것은 어느 것인가요?","options":[{"t":"느낀 분위기와 그렇게 느낀 까닭을 함께 말해요","correct":true},{"t":"까닭 없이 「그냥」이라고만 말해요","mis":"K2-1-u4-X09"},{"t":"시에 나온 사람 이름을 말해요","mis":"K2-1-u4-X08"}],"explanation":["시의 말이나 장면을 까닭으로 들어 말해요.","까닭이 있어야 친구도 고개를 끄덕여요.","사람 이름은 분위기가 아니에요."],"variant_rule":{"alt":[{"stem":"친구가 「달밤」을 읽고 「포근한 분위기야」라고 말했어요. 알맞은 생각은 어느 것인가요?","options":[{"t":"까닭을 들어 보면 그렇게 느낄 수도 있어요","correct":true},{"t":"시의 분위기는 꼭 하나라서 틀렸어요","mis":"K2-1-u4-X09"},{"t":"분위기는 아무렇게나 말해도 돼요","mis":"K2-1-u4-X09"}],"explanation":["느낀 분위기는 친구마다 조금 다를 수 있어요.","시의 말과 장면으로 까닭을 말하면 돼요.","아무렇게나가 아니라 까닭이 있어야 해요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#9','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'sa','auto','시를 읽고 답해 보세요. 이 시에서 힘차게 걷는 씩씩한 모습이 느껴지는 말을 하나 찾아 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u4-C6","difficulty":2,"kind":"sa","stem":"시를 읽고 답해 보세요. 이 시에서 힘차게 걷는 씩씩한 모습이 느껴지는 말을 하나 찾아 써 보세요.","answer":["힘차게","발맞춰","씩씩해요","가슴 펴고","하나 둘"],"explanation":["「힘차게」·「발맞춰」·「씩씩해요」 같은 말이 씩씩한 기분을 줘요.","시에 나오는 말에서 찾아요.","찾은 말을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["하나 둘 하나 둘","발맞춰 걸어요","가슴 펴고 힘차게","우리는 씩씩해요"],"title":"발맞춰 걸어요"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 이 시에서 빗방울이 신나게 노는 모습이 느껴지는 말을 하나 찾아 써 보세요.","answer":["톡톡","첨벙첨벙","랄랄라","춤을 춰요","노래해요"],"explanation":["「톡톡」·「첨벙첨벙」·「랄랄라」 같은 말이 신나는 기분을 줘요.","시에 나오는 말에서 찾아요.","찾은 말을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["톡톡 빗방울이","우산 위에서 춤을 춰요","첨벙첨벙 웅덩이","랄랄라 노래해요"],"title":"비 오는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#10','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',3,'error','auto','시를 읽고 분위기를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X09','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시를 읽고 분위기를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"시우 — 「와글와글 시끄러운 분위기야.」","correct":true,"mis_target":"K2-1-u4-X09"},{"t":"다은 — 「고요하고 조용한 분위기야.」","mis":"K2-1-u4-X17"},{"t":"로아 — 「하얗고 차분한 분위기야.」","mis":"K2-1-u4-X17"}],"explanation":["「소리 없이」·「잠들어요」는 조용한 느낌이에요.","시끄러운 말은 시에 없어요.","다은이와 로아는 알맞게 말했어요."],"asset":{"type":"passage","lines":["소복소복 눈이","소리 없이 내려요","온 마을이","하얗게 잠들어요"],"title":"첫눈"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 분위기를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"준우 — 「쓸쓸하고 슬픈 분위기야.」","correct":true,"mis_target":"K2-1-u4-X09"},{"t":"하린 — 「밝고 신나는 분위기야.」","mis":"K2-1-u4-X17"},{"t":"지안 — 「즐겁고 들뜬 분위기야.」","mis":"K2-1-u4-X17"}],"explanation":["「통통」·「콩콩」·「와아」는 신나는 느낌이에요.","슬픈 말은 시에 없어요.","하린이와 지안이는 알맞게 말했어요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#1','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',2,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X09']::text[],false,'{"seq":1,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"신나는","correct":true},{"t":"조용한","mis":"K2-1-u4-X10"},{"t":"무서운","mis":"K2-1-u4-X09"}],"explanation":["「톡톡」·「첨벙첨벙」·「랄랄라」가 신나는 기분을 줘요.","조용하거나 무서운 장면은 없어요.","시의 말과 장면을 살펴요."],"asset":{"type":"passage","lines":["톡톡 빗방울이","우산 위에서 춤을 춰요","첨벙첨벙 웅덩이","랄랄라 노래해요"],"title":"비 오는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#2','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',2,'mc','auto','조용한 분위기가 느껴지는 말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":2,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"조용한 분위기가 느껴지는 말만 모은 것은 어느 것인가요?","options":[{"t":"살며시 · 가만히 · 소복소복","correct":true},{"t":"살며시 · 콩콩 · 소복소복","mis":"K2-1-u4-X10"},{"t":"와아 · 통통 · 들썩들썩","mis":"K2-1-u4-X10"}],"explanation":["「살며시」·「가만히」·「소복소복」은 조용한 느낌을 줘요.","「콩콩」·「와아」·「통통」·「들썩들썩」은 신나는 느낌이에요.","따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#3','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',3,'mc','auto','두 시를 읽고 분위기를 바르게 짝지은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#4','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"은솔 — 「쉿, 새근새근 잠든 아기 → 신나는」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"태민 — 「와아 와아 들썩이는 운동장 → 신나는」","mis":"K2-1-u4-X17"},{"t":"아린 — 「하나 둘 발맞추는 아이들 → 씩씩한」","mis":"K2-1-u4-X17"}],"explanation":["「쉿」·「새근새근」은 조용한 느낌이에요.","잠든 아기 장면은 조용한 분위기와 어울려요.","태민이와 아린이는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#5','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',3,'ox','auto','시를 읽고 답해 보세요. 이 시의 「쉿」을 「야호」로 바꾸면 시의 분위기도 달라져요.',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":3,"kind":"ox","stem":"시를 읽고 답해 보세요. 이 시의 「쉿」을 「야호」로 바꾸면 시의 분위기도 달라져요.","answer":"O","reason_options":[{"t":"시에 나오는 말에 따라 느껴지는 기분이 달라지니까","correct":true},{"t":"낱말 하나로는 분위기가 바뀌지 않으니까","mis":"K2-1-u4-X09"}],"mis":"K2-1-u4-X09","explanation":["「야호」는 신나는 느낌이라 조용한 분위기가 흔들려요.","낱말 하나도 분위기를 바꿀 수 있어요.","그래서 시의 말을 잘 살펴요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#6','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',3,'mc','auto','시를 읽고 답해 보세요. 이 시에서 포근한 느낌을 가장 잘 주는 장면은 어느 것인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":6,"concept":"K2-1-u4-C6","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시에서 포근한 느낌을 가장 잘 주는 장면은 어느 것인가요?","options":[{"t":"햇살이 꽃잎을 살살 쓰다듬는 장면","correct":true},{"t":"공이 통통 튀는 장면","mis":"K2-1-u4-X07"},{"t":"친구들이 와아 소리치는 장면","mis":"K2-1-u4-X07"}],"explanation":["햇살이 꽃잎을 살살 쓰다듬는 장면이 포근해요.","공이 튀거나 소리치는 장면은 이 시에 없어요.","시에 있는 장면에서 찾아요."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#7','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C5',3,'mc','auto','분위기에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u4-X09','K2-1-u4-X08']::text[],false,'{"seq":7,"concept":"K2-1-u4-C5","difficulty":3,"kind":"mc","stem":"분위기에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"「같은 눈 내리는 장면도 쓴 말에 따라 신나게도, 조용하게도 느껴질 수 있어.」","correct":true},{"t":"「눈이 나오는 시는 언제나 조용한 분위기야.」","mis":"K2-1-u4-X09"},{"t":"「분위기는 시의 제목 글자 수로 정해져.」","mis":"K2-1-u4-X08"}],"explanation":["어떤 말을 썼는지에 따라 분위기가 달라져요.","소재 하나로 분위기가 정해지지 않아요.","글자 수는 분위기와 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#8','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',4,'mc','auto','시를 읽고 답해 보세요. 이 시를 신나는 분위기로 바꾸려고 해요. 바꾼 줄로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":8,"concept":"K2-1-u4-C6","difficulty":4,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 신나는 분위기로 바꾸려고 해요. 바꾼 줄로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「펑펑 눈이 와요 / 와아, 눈싸움하자」","correct":true},{"t":"「소복소복 눈이 / 소리 없이 내려요」","mis":"K2-1-u4-X10"},{"t":"「쉿, 눈이 / 살며시 잠들어요」","mis":"K2-1-u4-X10"}],"explanation":["「펑펑」·「와아」·「눈싸움」이 신나는 기분을 줘요.","다른 두 줄은 여전히 조용한 느낌이에요.","바꿀 말을 고를 때 분위기를 먼저 정해요."],"asset":{"type":"passage","lines":["소복소복 눈이","소리 없이 내려요","온 마을이","하얗게 잠들어요"],"title":"첫눈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#9','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',4,'essay','teacher','「공놀이」의 분위기를 쓰고, 그렇게 느낀 까닭을 시에 나오는 말을 들어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C6","difficulty":4,"kind":"essay","stem":"「공놀이」의 분위기를 쓰고, 그렇게 느낀 까닭을 시에 나오는 말을 들어 써 보세요.","answer_guide":{"answer":"예: 신나는 분위기예요. 「통통」·「콩콩」·「와아 와아」 같은 말에서 친구들이 신나게 뛰노는 모습이 떠오르기 때문이에요.","scoring_points":["분위기를 알맞게 썼는가","시에 나오는 말을 까닭으로 들었는가","그 말에서 떠오른 장면이나 기분을 썼는가"]},"explanation":["분위기.","시의 말.","장면·기분."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#10','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',4,'essay','teacher','조용한 분위기가 느껴지는 짧은 시를 두 줄로 지어 보고, 어떤 말 때문에 조용하게 느껴지는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C6","difficulty":4,"kind":"essay","stem":"조용한 분위기가 느껴지는 짧은 시를 두 줄로 지어 보고, 어떤 말 때문에 조용하게 느껴지는지 써 보세요.","answer_guide":{"answer":"예: 「가만가만 고양이가 / 햇볕에 졸고 있어요」 — 「가만가만」·「졸고」 때문에 조용하게 느껴져요.","scoring_points":["두 줄로 시를 지었는가","조용한 느낌을 주는 말을 넣었는가","조용하게 느껴지는 까닭을 시의 말로 썼는가"]},"explanation":["두 줄 시.","조용한 말.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#1','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',1,'mc','auto','시를 읽고 답해 보세요. 이 시는 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u4-X11']::text[],true,'{"seq":1,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시는 어떻게 읽으면 좋을까요?","options":[{"t":"밝고 빠르게","correct":true},{"t":"작고 느릿느릿하게","mis":"K2-1-u4-X11"},{"t":"화내며 세게","mis":"K2-1-u4-X11"}],"explanation":["신나는 시는 밝고 빠르게 읽으면 분위기가 살아나요.","작고 느리게 읽으면 신나는 느낌이 사라져요.","화내며 읽는 것은 이 시와 어울리지 않아요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 이 시는 어떻게 읽으면 좋을까요?","options":[{"t":"천천히 부드럽게","correct":true},{"t":"빠르고 크게","mis":"K2-1-u4-X11"},{"t":"화내며 세게","mis":"K2-1-u4-X11"}],"explanation":["조용한 시는 천천히 부드럽게 읽으면 분위기가 살아나요.","빠르고 크게 읽으면 조용한 느낌이 사라져요.","화내며 읽는 것은 이 시와 어울리지 않아요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#2','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C8',1,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],true,'{"seq":2,"concept":"K2-1-u4-C8","difficulty":1,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「달님이 / 살며시 // 창문을 / 들여다봐요」","correct":true},{"t":"「달 / 님이 / 살 / 며시 창문을 들여다봐요」","mis":"K2-1-u4-X13"},{"t":"「달님이살며시창문을들여다봐요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","한 글자씩 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「강아지가 / 꼬리를 // 흔들어요」","correct":true},{"t":"「강 / 아지가꼬 / 리를 흔들어요」","mis":"K2-1-u4-X13"},{"t":"「강아지가꼬리를흔들어요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#3','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C8',1,'ox','auto','「//」 표시에서는 「/」 표시보다 조금 더 쉬어 읽어요.',ARRAY['K2-1-u4-X14']::text[],true,'{"seq":3,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"「//」 표시에서는 「/」 표시보다 조금 더 쉬어 읽어요.","answer":"O","reason_options":[{"t":"「//」는 조금 더 쉬라는 표시이니까","correct":true},{"t":"「//」는 쉬지 말고 붙여 읽으라는 표시이니까","mis":"K2-1-u4-X14"}],"mis":"K2-1-u4-X14","explanation":["「/」에서는 조금 쉬고, 「//」에서는 조금 더 쉬어요.","쉬는 길이를 표시로 알려 줘요.","표시를 따라 읽으면 뜻이 잘 드러나요."],"variant_rule":{"alt":[{"stem":"「/」 표시에서는 쉬지 않고 붙여 읽어요.","answer":"X","reason_options":[{"t":"「/」는 조금 쉬어 읽으라는 표시이니까","correct":true},{"t":"「/」는 빠르게 읽으라는 표시이니까","mis":"K2-1-u4-X14"}],"explanation":["「/」에서는 조금 쉬어 읽어요.","「//」에서는 조금 더 쉬어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#4','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',1,'mc','auto','모든 시를 한 가지 목소리로 똑같이 읽으면 어떻게 될까요?',ARRAY['K2-1-u4-X11']::text[],true,'{"seq":4,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"모든 시를 한 가지 목소리로 똑같이 읽으면 어떻게 될까요?","options":[{"t":"시마다 다른 분위기가 잘 살아나지 않아요","correct":true},{"t":"모든 시가 더 신나게 느껴져요","mis":"K2-1-u4-X11"},{"t":"시의 뜻이 저절로 잘 드러나요","mis":"K2-1-u4-X11"}],"explanation":["시마다 분위기가 달라서 읽는 목소리도 달라야 해요.","같은 목소리로 읽으면 분위기가 비슷해져요.","분위기에 맞게 목소리를 바꾸어요."],"variant_rule":{"alt":[{"stem":"시를 소리 내어 읽기 전에 분위기에 맞게 정해야 할 것은 어느 것인가요?","options":[{"t":"목소리 크기와 빠르기","correct":true},{"t":"시의 제목 글자","mis":"K2-1-u4-X08"},{"t":"읽을 종이의 크기","mis":"K2-1-u4-X08"}],"explanation":["분위기에 맞게 목소리 크기와 빠르기를 정해요.","제목 글자나 종이 크기는 읽는 방법이 아니에요.","그러면 시의 분위기가 살아나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#5','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',2,'match','auto','분위기와 어울리는 읽는 방법을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C7","difficulty":2,"kind":"match","stem":"분위기와 어울리는 읽는 방법을 이어 보세요.","pairs":[{"l":"신나는","r":"밝고 빠르게"},{"l":"조용한","r":"천천히 부드럽게"},{"l":"씩씩한","r":"또렷하고 힘차게"}],"mis":"K2-1-u4-X11","explanation":["신나는 시는 밝고 빠르게 읽어요.","조용한 시는 천천히 부드럽게 읽어요.","씩씩한 시는 또렷하고 힘차게 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 분위기와 어울리는 읽는 방법을 이어 보세요.","pairs":[{"l":"포근한","r":"다정하고 따뜻하게"},{"l":"신나는","r":"밝고 빠르게"},{"l":"조용한","r":"작고 천천히"}],"explanation":["포근한 시는 다정하고 따뜻하게 읽어요.","신나는 시는 밝고 빠르게 읽어요.","조용한 시는 작고 천천히 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#6','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',2,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기를 살려 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],true,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기를 살려 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"또렷하고 힘차게","correct":true},{"t":"졸린 듯 작게","mis":"K2-1-u4-X11"},{"t":"울먹이며 느리게","mis":"K2-1-u4-X11"}],"explanation":["씩씩한 시는 또렷하고 힘차게 읽어요.","졸리거나 울먹이는 목소리는 씩씩한 느낌과 맞지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."],"asset":{"type":"passage","lines":["하나 둘 하나 둘","발맞춰 걸어요","가슴 펴고 힘차게","우리는 씩씩해요"],"title":"발맞춰 걸어요"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 이 시의 분위기를 살려 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"다정하고 따뜻하게","correct":true},{"t":"크게 소리 지르며","mis":"K2-1-u4-X11"},{"t":"빠르고 거칠게","mis":"K2-1-u4-X11"}],"explanation":["포근한 시는 다정하고 따뜻하게 읽어요.","소리 지르거나 거칠게 읽으면 포근한 느낌이 사라져요.","분위기를 먼저 떠올리고 목소리를 정해요."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#7','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C8',2,'mc','auto','「쉿, 아기가 새근새근 자요」를 알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],true,'{"seq":7,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"「쉿, 아기가 새근새근 자요」를 알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「쉿, // 아기가 / 새근새근 자요」","correct":true},{"t":"「쉿아 / 기가새 / 근새근 자요」","mis":"K2-1-u4-X13"},{"t":"「쉿, 아 / 기가 / 새근 / 새근자요」","mis":"K2-1-u4-X13"}],"explanation":["「쉿,」 뒤에서 조금 더 쉬고, 뜻 덩어리로 묶어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","뜻이 이어지는 말끼리 묶어 읽어요."],"variant_rule":{"alt":[{"stem":"「우리는 씩씩한 어린이」를 알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「우리는 / 씩씩한 어린이」","correct":true},{"t":"「우 / 리는씩 / 씩한 어린이」","mis":"K2-1-u4-X13"},{"t":"「우리는씩씩한어린이」","mis":"K2-1-u4-X13"}],"explanation":["「우리는」과 「씩씩한 어린이」를 한 덩어리씩 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#8','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',2,'ox','auto','시는 빠르게 읽을수록 언제나 잘 읽은 거예요.',ARRAY['K2-1-u4-X12']::text[],true,'{"seq":8,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"시는 빠르게 읽을수록 언제나 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"분위기에 맞는 빠르기로 읽어야 하니까","correct":true},{"t":"빨리 읽으면 무조건 잘 읽은 것이니까","mis":"K2-1-u4-X12"}],"mis":"K2-1-u4-X12","explanation":["조용한 시는 천천히 읽어야 분위기가 살아나요.","빠르기도 분위기에 맞추어요.","빨리 읽는 것과 잘 읽는 것은 달라요."],"variant_rule":{"alt":[{"stem":"조용한 시는 천천히, 신나는 시는 조금 빠르게 읽으면 분위기가 살아나요.","answer":"O","reason_options":[{"t":"분위기에 따라 알맞은 빠르기가 다르니까","correct":true},{"t":"모든 시는 같은 빠르기로 읽어야 하니까","mis":"K2-1-u4-X11"}],"explanation":["분위기에 따라 빠르기를 바꾸어 읽어요.","같은 빠르기로 읽으면 분위기가 살지 않아요.","시에 맞는 빠르기를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#9','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',2,'blank','auto','「살며시 눈이 내려요」처럼 조용한 시를 읽을 때는 목소리를 (     ) 해요.',ARRAY['K2-1-u4-X11','K2-1-u4-X12']::text[],true,'{"seq":9,"concept":"K2-1-u4-C7","difficulty":2,"kind":"blank","stem":"「살며시 눈이 내려요」처럼 조용한 시를 읽을 때는 목소리를 (     ) 해요.","options":[{"t":"부드럽고 작게","correct":true},{"t":"크고 거칠게","mis":"K2-1-u4-X11"},{"t":"빠르고 세게","mis":"K2-1-u4-X12"}],"explanation":["조용한 시는 부드럽고 작은 목소리가 어울려요.","크고 거친 목소리는 조용한 느낌을 깨요.","빠르고 세게 읽으면 고요함이 사라져요."],"variant_rule":{"alt":[{"stem":"「와아 와아 운동장이」처럼 신나는 시를 읽을 때는 목소리를 (     ) 해요.","options":[{"t":"밝고 힘 있게","correct":true},{"t":"작고 졸리게","mis":"K2-1-u4-X11"},{"t":"울먹이듯 느리게","mis":"K2-1-u4-X11"}],"explanation":["신나는 시는 밝고 힘 있는 목소리가 어울려요.","작고 졸린 목소리는 신나는 느낌을 지워요.","울먹이는 목소리는 슬픈 느낌을 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#10','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C8',3,'error','auto','「달님이 살며시 창가에 앉아요」를 띄어 읽었어요. 알맞지 않게 띄어 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X13','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C8","difficulty":3,"kind":"error","stem":"「달님이 살며시 창가에 앉아요」를 띄어 읽었어요. 알맞지 않게 띄어 읽은 친구는 누구인가요?","options":[{"t":"지호 — 「달 / 님이살 / 며시 창가에 앉아요」","correct":true,"mis_target":"K2-1-u4-X13"},{"t":"예린 — 「달님이 / 살며시 // 창가에 / 앉아요」","mis":"K2-1-u4-X17"},{"t":"소율 — 「달님이 살며시 / 창가에 앉아요」","mis":"K2-1-u4-X17"}],"explanation":["지호는 낱말 가운데에서 끊어 읽어 뜻이 드러나지 않아요.","예린이와 소율이는 뜻 덩어리로 띄어 읽었어요.","띄어 읽는 곳은 조금 달라도 뜻이 드러나면 괜찮아요."],"variant_rule":{"alt":[{"stem":"「작은 새가 나뭇가지에 앉아 노래해요」를 띄어 읽었어요. 알맞지 않게 띄어 읽은 친구는 누구인가요?","options":[{"t":"민지 — 「작 / 은새가 / 나뭇가 / 지에 앉아 노래해요」","correct":true,"mis_target":"K2-1-u4-X13"},{"t":"하늘 — 「작은 새가 / 나뭇가지에 앉아 // 노래해요」","mis":"K2-1-u4-X17"},{"t":"도윤 — 「작은 새가 / 나뭇가지에 / 앉아 노래해요」","mis":"K2-1-u4-X17"}],"explanation":["민지는 낱말 가운데에서 끊어 읽어 뜻이 드러나지 않아요.","하늘이와 도윤이는 뜻 덩어리로 띄어 읽었어요.","띄어 읽는 곳은 조금 달라도 뜻이 드러나면 괜찮아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#1','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',2,'mc','auto','시를 읽고 답해 보세요. 친구가 이 시를 크고 빠르게 읽었어요. 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X12','K2-1-u4-X11']::text[],false,'{"seq":1,"concept":"K2-1-u4-C7","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 친구가 이 시를 크고 빠르게 읽었어요. 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「조용한 시니까 천천히 부드럽게 읽어 보자.」","correct":true},{"t":"「더 크고 더 빠르게 읽으면 좋겠어.」","mis":"K2-1-u4-X12"},{"t":"「소리치며 읽으면 더 잘 들려.」","mis":"K2-1-u4-X11"}],"explanation":["「달밤」은 조용한 시예요.","크고 빠르게 읽으면 조용한 분위기가 사라져요.","분위기에 맞는 목소리를 알려 줘요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#2','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽으면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u4-X13','K2-1-u4-X12']::text[],false,'{"seq":2,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽으면 좋은 점은 어느 것인가요?","options":[{"t":"뜻이 잘 드러나고 듣는 사람이 알아듣기 쉬워요","correct":true},{"t":"글자를 하나씩 끊어 읽을 수 있어요","mis":"K2-1-u4-X13"},{"t":"쉬는 곳 없이 빨리 읽을 수 있어요","mis":"K2-1-u4-X12"}],"explanation":["뜻 덩어리로 띄어 읽으면 뜻이 잘 전해져요.","한 글자씩 끊는 것은 알맞게 띄어 읽기가 아니에요.","쉬지 않고 빨리 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#3','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',3,'mc','auto','「와아, 눈이 온다」를 두 가지 방법으로 읽었어요. 신나는 분위기가 더 잘 살아나는 방법은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X13']::text[],false,'{"seq":3,"concept":"K2-1-u4-C7","difficulty":3,"kind":"mc","stem":"「와아, 눈이 온다」를 두 가지 방법으로 읽었어요. 신나는 분위기가 더 잘 살아나는 방법은 어느 것인가요?","options":[{"t":"밝고 들뜬 목소리로 조금 빠르게 읽기","correct":true},{"t":"작고 낮은 목소리로 아주 느리게 읽기","mis":"K2-1-u4-X11"},{"t":"한 글자씩 뚝뚝 끊어 읽기","mis":"K2-1-u4-X13"}],"explanation":["밝고 들뜬 목소리가 「와아」의 신나는 느낌을 살려요.","작고 느리게 읽으면 신나는 느낌이 사라져요.","한 글자씩 끊으면 뜻도 분위기도 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#4','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',3,'error','auto','시를 읽는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C7","difficulty":3,"kind":"error","stem":"시를 읽는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도담 — 「봄볕 시는 크게 소리 지르며 읽을래.」","correct":true,"mis_target":"K2-1-u4-X11"},{"t":"현우 — 「공놀이 시는 밝고 빠르게 읽을래.」","mis":"K2-1-u4-X17"},{"t":"하준 — 「발맞춰 걸어요 시는 또렷하고 힘차게 읽을래.」","mis":"K2-1-u4-X17"}],"explanation":["「봄볕」은 포근한 시라 다정하고 따뜻하게 읽어요.","소리 지르면 포근한 느낌이 사라져요.","현우와 하준이는 알맞게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#5','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C8',3,'ox','auto','「아기가 / 새근새근 // 자요」는 「새근새근」 뒤에서 가장 길게 쉬어요.',ARRAY['K2-1-u4-X14']::text[],false,'{"seq":5,"concept":"K2-1-u4-C8","difficulty":3,"kind":"ox","stem":"「아기가 / 새근새근 // 자요」는 「새근새근」 뒤에서 가장 길게 쉬어요.","answer":"O","reason_options":[{"t":"「//」 표시가 있어 조금 더 쉬니까","correct":true},{"t":"「/」에서 더 길게 쉬니까","mis":"K2-1-u4-X14"}],"mis":"K2-1-u4-X14","explanation":["「//」가 있는 곳에서 조금 더 쉬어요.","「/」에서는 조금만 쉬어요.","표시를 따라 쉬는 길이를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#6','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C8',3,'mc','auto','뜻이 바르게 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":6,"concept":"K2-1-u4-C8","difficulty":3,"kind":"mc","stem":"뜻이 바르게 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「아버지가 / 방에 들어가신다」","correct":true},{"t":"「아버지가방에 / 들어가신다」","mis":"K2-1-u4-X13"},{"t":"「아 / 버지가 / 방에들 / 어가신다」","mis":"K2-1-u4-X13"}],"explanation":["「아버지가」와 「방에 들어가신다」로 묶어야 뜻이 바르게 드러나요.","「아버지가방에」로 붙이면 「가방에」로 잘못 들릴 수 있어요.","띄어 읽는 곳에 따라 뜻이 달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#7','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',3,'mc','auto','시를 읽고 답해 보세요. 이 시를 분위기를 살려 읽을 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":7,"concept":"K2-1-u4-C7","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 분위기를 살려 읽을 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"천천히, 부드럽고 차분한 목소리로","correct":true},{"t":"빠르고 큰 목소리로","mis":"K2-1-u4-X11"},{"t":"화난 목소리로 세게","mis":"K2-1-u4-X11"}],"explanation":["「첫눈」은 조용한 분위기의 시예요.","빠르고 크게 읽으면 조용한 느낌이 사라져요.","화난 목소리는 이 시와 어울리지 않아요."],"asset":{"type":"passage","lines":["소복소복 눈이","소리 없이 내려요","온 마을이","하얗게 잠들어요"],"title":"첫눈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#8','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',4,'mc','auto','「통통 공이 튀어요 / 쉿, 아기가 자요」처럼 한 시 안에서 분위기가 바뀌면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u4-X11','K2-1-u4-X12']::text[],false,'{"seq":8,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"「통통 공이 튀어요 / 쉿, 아기가 자요」처럼 한 시 안에서 분위기가 바뀌면 어떻게 읽으면 좋을까요?","options":[{"t":"앞줄은 밝고 빠르게, 뒷줄은 작고 천천히 바꾸어 읽어요","correct":true},{"t":"처음 목소리 그대로 끝까지 읽어요","mis":"K2-1-u4-X11"},{"t":"두 줄 모두 크고 빠르게 읽어요","mis":"K2-1-u4-X12"}],"explanation":["분위기가 바뀌는 곳에서 목소리도 바꾸어요.","한 가지 목소리로 읽으면 바뀐 분위기가 드러나지 않아요.","「쉿」부터는 작고 천천히 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#9','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',4,'essay','teacher','「비 오는 날」을 어떤 목소리와 빠르기로 읽으면 좋을지 쓰고, 그렇게 정한 까닭을 시의 말을 들어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C7","difficulty":4,"kind":"essay","stem":"「비 오는 날」을 어떤 목소리와 빠르기로 읽으면 좋을지 쓰고, 그렇게 정한 까닭을 시의 말을 들어 써 보세요.","answer_guide":{"answer":"예: 밝은 목소리로 조금 빠르게 읽을래요. 「톡톡」·「첨벙첨벙」·「랄랄라」가 신나는 느낌을 주기 때문이에요.","scoring_points":["목소리를 정해 썼는가","빠르기를 정해 썼는가","시의 말을 들어 까닭을 썼는가"]},"explanation":["목소리.","빠르기.","시의 말로 까닭."],"asset":{"type":"passage","lines":["톡톡 빗방울이","우산 위에서 춤을 춰요","첨벙첨벙 웅덩이","랄랄라 노래해요"],"title":"비 오는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#10','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C8',4,'essay','teacher','「작은 다람쥐가 도토리를 들고 나무 위로 올라가요」에 「/」와 「//」를 넣어 알맞게 띄어 읽기 표시를 하고, 그렇게 띄어 읽은 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C8","difficulty":4,"kind":"essay","stem":"「작은 다람쥐가 도토리를 들고 나무 위로 올라가요」에 「/」와 「//」를 넣어 알맞게 띄어 읽기 표시를 하고, 그렇게 띄어 읽은 까닭을 써 보세요.","answer_guide":{"answer":"예: 작은 다람쥐가 / 도토리를 들고 // 나무 위로 / 올라가요. — 뜻이 이어지는 말끼리 묶어 읽으면 뜻이 잘 드러나기 때문이에요.","scoring_points":["「/」와 「//」를 모두 넣었는가","낱말 가운데를 끊지 않고 뜻 덩어리로 묶었는가","뜻이 잘 드러난다는 까닭을 썼는가"]},"explanation":["표시 두 가지.","뜻 덩어리.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#1','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',1,'mc','auto','시를 낭송할 때 알맞은 태도는 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],true,'{"seq":1,"concept":"K2-1-u4-C9","difficulty":1,"kind":"mc","stem":"시를 낭송할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"분위기를 살려 또박또박 읽어요","correct":true},{"t":"장난치며 아무렇게나 읽어요","mis":"K2-1-u4-X15"},{"t":"작게 우물우물 읽어요","mis":"K2-1-u4-X15"}],"explanation":["분위기를 살려 또박또박 읽어야 시가 잘 전해져요.","장난치며 읽으면 시의 기분이 흐려져요.","작게 우물우물 읽으면 친구들이 알아듣기 어려워요."],"variant_rule":{"alt":[{"stem":"친구들 앞에서 시를 낭송할 때 목소리로 알맞은 것은 어느 것인가요?","options":[{"t":"모두가 잘 들리게 또렷하게","correct":true},{"t":"나만 들리게 작게","mis":"K2-1-u4-X15"},{"t":"웃음을 참지 못하고 킥킥거리며","mis":"K2-1-u4-X15"}],"explanation":["친구들이 모두 들을 수 있게 또렷하게 낭송해요.","작게 읽으면 들리지 않아요.","킥킥거리면 시의 분위기가 흐려져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#2','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',1,'mc','auto','친구가 시를 낭송할 때 좋은 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],true,'{"seq":2,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 시를 낭송할 때 좋은 듣기 태도는 어느 것인가요?","options":[{"t":"조용히 끝까지 들어요","correct":true},{"t":"옆 친구와 떠들어요","mis":"K2-1-u4-X16"},{"t":"다른 책을 읽어요","mis":"K2-1-u4-X16"}],"explanation":["조용히 끝까지 들어 주면 친구가 마음껏 낭송할 수 있어요.","떠들거나 딴짓하면 친구의 시를 놓쳐요.","내가 낭송할 때를 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"친구의 낭송이 끝났을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"박수를 쳐 주어요","correct":true},{"t":"고개를 돌리고 하품해요","mis":"K2-1-u4-X16"},{"t":"「틀렸다」고 놀려요","mis":"K2-1-u4-X16"}],"explanation":["박수는 잘 들었다는 마음을 전해요.","하품하거나 놀리면 친구가 속상해요.","내가 낭송할 때를 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#3','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',1,'mc','auto','낭송할 시를 고를 때 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],true,'{"seq":3,"concept":"K2-1-u4-C9","difficulty":1,"kind":"mc","stem":"낭송할 시를 고를 때 알맞은 것은 어느 것인가요?","options":[{"t":"읽었을 때 마음에 들고 분위기가 좋은 시","correct":true},{"t":"무조건 가장 긴 시","mis":"K2-1-u4-X15"},{"t":"읽어 보지 않고 아무거나 고른 시","mis":"K2-1-u4-X15"}],"explanation":["마음에 드는 시를 골라야 분위기를 살려 낭송할 수 있어요.","길이로 고르는 것이 아니에요.","먼저 읽어 보고 골라요."],"variant_rule":{"alt":[{"stem":"「시로 여는 우리 반」에서 맨 처음 할 일은 어느 것인가요?","options":[{"t":"마음에 드는 시 고르기","correct":true},{"t":"친구들 앞에서 낭송하기","mis":"K2-1-u4-X15"},{"t":"친구에게 박수 쳐 주기","mis":"K2-1-u4-X15"}],"explanation":["먼저 시를 골라야 연습하고 낭송할 수 있어요.","낭송은 연습을 한 뒤에 해요.","박수는 친구의 낭송이 끝난 뒤에 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#4','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',1,'ox','auto','친구가 낭송하는 도중에 「나도 할래!」 하고 끼어들어도 돼요.',ARRAY['K2-1-u4-X16']::text[],true,'{"seq":4,"concept":"K2-1-u4-C10","difficulty":1,"kind":"ox","stem":"친구가 낭송하는 도중에 「나도 할래!」 하고 끼어들어도 돼요.","answer":"X","reason_options":[{"t":"친구가 끝까지 낭송할 수 있게 기다려야 하니까","correct":true},{"t":"하고 싶은 말은 바로 해야 하니까","mis":"K2-1-u4-X16"}],"mis":"K2-1-u4-X16","explanation":["친구의 낭송이 끝날 때까지 기다려요.","끼어들면 친구가 시를 끝까지 들려줄 수 없어요.","내 차례를 기다리는 것도 좋은 태도예요."],"variant_rule":{"alt":[{"stem":"친구가 낭송하는 시를 잘 들으면 친구의 마음을 더 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"친구가 고른 시에 친구의 마음이 담겨 있으니까","correct":true},{"t":"듣는 것은 낭송과 아무 상관이 없으니까","mis":"K2-1-u4-X16"}],"explanation":["친구가 고른 시에는 친구의 마음이 담겨 있어요.","잘 들어야 그 마음이 전해져요.","시를 나누면 서로를 더 잘 알게 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#5','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',2,'match','auto','낭송 차례와 할 일을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C9","difficulty":2,"kind":"match","stem":"낭송 차례와 할 일을 알맞게 이어 보세요.","pairs":[{"l":"시 고르기","r":"마음에 드는 시 찾기"},{"l":"연습하기","r":"분위기 살려 읽어 보기"},{"l":"낭송하기","r":"친구들 앞에서 또렷하게 발표하기"}],"mis":"K2-1-u4-X15","explanation":["시 고르기는 마음에 드는 시를 찾는 일이에요.","연습하기는 분위기를 살려 읽어 보는 일이에요.","낭송하기는 친구들 앞에서 또렷하게 발표하는 일이에요."],"variant_rule":{"alt":[{"stem":"낭송 차례를 알맞게 이어 보세요.","pairs":[{"l":"첫째","r":"시 고르기"},{"l":"둘째","r":"분위기 살려 연습하기"},{"l":"셋째","r":"친구들 앞에서 낭송하기"}],"explanation":["첫째로 마음에 드는 시를 골라요.","둘째로 분위기를 살려 연습해요.","셋째로 친구들 앞에서 낭송해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#6','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',2,'mc','auto','시 낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],true,'{"seq":6,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"시 낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시 고르기 → 연습하기 → 낭송하기","correct":true},{"t":"낭송하기 → 시 고르기 → 연습하기","mis":"K2-1-u4-X15"},{"t":"연습하기 → 낭송하기 → 시 고르기","mis":"K2-1-u4-X15"}],"explanation":["시를 고르고, 연습한 뒤에, 낭송해요.","시를 고르기 전에 낭송할 수는 없어요.","연습 없이 낭송하면 분위기를 살리기 어려워요."],"variant_rule":{"alt":[{"stem":"연습을 하지 않고 바로 낭송하면 어떻게 될까요?","options":[{"t":"분위기를 살려 또박또박 읽기 어려워요","correct":true},{"t":"언제나 더 멋지게 낭송할 수 있어요","mis":"K2-1-u4-X15"},{"t":"시의 분위기가 저절로 살아나요","mis":"K2-1-u4-X15"}],"explanation":["연습을 해야 분위기에 맞는 목소리를 찾을 수 있어요.","연습 없이 바로 하면 더듬거리기 쉬워요.","분위기는 저절로 살아나지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#7','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',2,'mc','auto','시를 친구들과 나누면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],true,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":2,"kind":"mc","stem":"시를 친구들과 나누면 좋은 점은 어느 것인가요?","options":[{"t":"여러 가지 분위기의 시를 만날 수 있어요","correct":true},{"t":"낭송하는 친구만 즐거워요","mis":"K2-1-u4-X16"},{"t":"듣는 친구는 할 일이 없어요","mis":"K2-1-u4-X16"}],"explanation":["친구마다 고른 시가 달라 여러 분위기를 느낄 수 있어요.","듣는 친구도 함께 즐거워요.","잘 들어 주는 것이 듣는 친구가 할 일이에요."],"variant_rule":{"alt":[{"stem":"시를 나누면 우리 반이 어떻게 될까요?","options":[{"t":"서로의 마음을 알게 되어 따뜻해져요","correct":true},{"t":"서로 시끄럽게 떠들게 돼요","mis":"K2-1-u4-X16"},{"t":"친구의 시는 들을 필요가 없어져요","mis":"K2-1-u4-X16"}],"explanation":["시를 나누면 친구의 마음을 알게 돼요.","떠드는 것은 좋은 듣기 태도가 아니에요.","친구의 시도 잘 들어야 나눌 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#8','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',2,'blank','auto','낭송할 때는 시를 무조건 외우기보다 (     ) 낭송해요.',ARRAY['K2-1-u4-X12','K2-1-u4-X15']::text[],true,'{"seq":8,"concept":"K2-1-u4-C9","difficulty":2,"kind":"blank","stem":"낭송할 때는 시를 무조건 외우기보다 (     ) 낭송해요.","options":[{"t":"분위기를 느끼며","correct":true},{"t":"아무렇게나 빠르게","mis":"K2-1-u4-X12"},{"t":"작게 중얼거리며","mis":"K2-1-u4-X15"}],"explanation":["분위기를 느끼며 읽어야 듣는 사람에게 잘 전해져요.","빠르게만 읽으면 분위기가 살지 않아요.","작게 중얼거리면 들리지 않아요."],"variant_rule":{"alt":[{"stem":"낭송을 연습할 때는 고른 시의 (     )를 살펴 읽는 방법을 정해요.","options":[{"t":"분위기","correct":true},{"t":"글자 수","mis":"K2-1-u4-X08"},{"t":"쪽수","mis":"K2-1-u4-X08"}],"explanation":["시의 분위기를 살펴 목소리와 빠르기를 정해요.","글자 수나 쪽수는 읽는 방법을 정해 주지 않아요.","분위기에 맞게 연습해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#9','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',2,'sa','auto','친구의 낭송이 끝나면 두 손뼉을 마주쳐 소리를 내어 칭찬해요. 이것을 무엇이라고 하나요? 두 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u4-C10","difficulty":2,"kind":"sa","stem":"친구의 낭송이 끝나면 두 손뼉을 마주쳐 소리를 내어 칭찬해요. 이것을 무엇이라고 하나요? 두 글자로 써 보세요.","answer":["박수"],"explanation":["잘 들었다는 마음을 박수로 전해요.","박수를 받으면 낭송한 친구도 기뻐요.","듣는 사람이 할 수 있는 좋은 반응이에요."],"variant_rule":{"alt":[{"stem":"친구가 낭송할 때는 떠들지 않고 (     ) 들어요. 빈칸에 알맞은 말을 써 보세요.","answer":["조용히","가만히","귀 기울여"],"explanation":["조용히 들어야 친구의 시가 잘 들려요.","떠들면 친구도 다른 친구들도 시를 놓쳐요.","끝까지 조용히 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#10','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"시우 — 「몰래 짝에게 쪽지를 썼어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"다은 — 「낭송하는 친구를 바라보며 들었어요.」","mis":"K2-1-u4-X17"},{"t":"로아 — 「끝난 뒤 박수를 쳤어요.」","mis":"K2-1-u4-X17"}],"explanation":["낭송할 때 쪽지를 쓰는 것은 딴짓이에요.","친구를 바라보며 듣고 박수를 쳐 주는 것은 좋은 태도예요.","다은이와 로아는 알맞게 행동했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"준우 — 「낭송 도중에 크게 하품하며 엎드렸어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"지안 — 「시의 장면을 떠올리며 들었어요.」","mis":"K2-1-u4-X17"},{"t":"하린 — 「끝까지 조용히 들었어요.」","mis":"K2-1-u4-X17"}],"explanation":["크게 하품하며 엎드리면 낭송하는 친구가 속상해요.","장면을 떠올리며 끝까지 조용히 듣는 것은 좋은 태도예요.","지안이와 하린이는 알맞게 행동했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#1','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',2,'mc','auto','포근한 분위기의 시를 낭송하려고 해요. 연습할 때 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X15']::text[],false,'{"seq":1,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"포근한 분위기의 시를 낭송하려고 해요. 연습할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"다정하고 따뜻한 목소리로 읽어 봐요","correct":true},{"t":"크게 소리 지르며 읽어 봐요","mis":"K2-1-u4-X11"},{"t":"연습 없이 바로 낭송해요","mis":"K2-1-u4-X15"}],"explanation":["포근한 시는 다정하고 따뜻한 목소리가 어울려요.","소리 지르면 포근한 느낌이 사라져요.","연습해야 분위기를 살릴 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#2','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C10',2,'mc','auto','친구의 낭송을 듣고 해 주는 칭찬으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":2,"concept":"K2-1-u4-C10","difficulty":2,"kind":"mc","stem":"친구의 낭송을 듣고 해 주는 칭찬으로 알맞은 것은 어느 것인가요?","options":[{"t":"「조용한 시를 부드럽게 읽어서 달밤이 떠올랐어.」","correct":true},{"t":"「너무 길어서 지루했어.」","mis":"K2-1-u4-X16"},{"t":"「나는 안 들었어.」","mis":"K2-1-u4-X16"}],"explanation":["어떤 점이 좋았는지 구체적으로 말해 주면 좋아요.","지루했다는 말은 친구를 속상하게 해요.","듣지 않았다면 칭찬할 수도 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#3','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',3,'error','auto','시 낭송을 준비했어요. 알맞지 않게 준비한 친구는 누구인가요?',ARRAY['K2-1-u4-X15','K2-1-u4-X17']::text[],false,'{"seq":3,"concept":"K2-1-u4-C9","difficulty":3,"kind":"error","stem":"시 낭송을 준비했어요. 알맞지 않게 준비한 친구는 누구인가요?","options":[{"t":"은솔 — 「시를 고르자마자 연습 없이 낭송했어요.」","correct":true,"mis_target":"K2-1-u4-X15"},{"t":"태민 — 「시의 분위기를 살펴 읽는 방법을 정했어요.」","mis":"K2-1-u4-X17"},{"t":"아린 — 「여러 번 소리 내어 연습했어요.」","mis":"K2-1-u4-X17"}],"explanation":["연습 없이 낭송하면 분위기를 살리기 어려워요.","분위기를 살피고 여러 번 연습하는 것이 알맞은 준비예요.","태민이와 아린이는 알맞게 준비했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#4','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',3,'mc','auto','낭송하는 친구가 지켜야 할 것만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":4,"concept":"K2-1-u4-C9","difficulty":3,"kind":"mc","stem":"낭송하는 친구가 지켜야 할 것만 모은 것은 어느 것인가요?","options":[{"t":"또렷하게 · 분위기를 살려 · 듣는 친구를 바라보며","correct":true},{"t":"작게 · 우물우물 · 바닥만 보며","mis":"K2-1-u4-X15"},{"t":"장난스럽게 · 아무렇게나 · 빠르게만","mis":"K2-1-u4-X15"}],"explanation":["또렷하게, 분위기를 살려, 친구를 바라보며 낭송해요.","작게 우물우물 읽으면 들리지 않아요.","장난스럽게 빠르게만 읽으면 분위기가 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#5','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',3,'ox','auto','낭송은 시를 외우기만 하면 분위기를 느끼지 않아도 잘한 거예요.',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":5,"concept":"K2-1-u4-C9","difficulty":3,"kind":"ox","stem":"낭송은 시를 외우기만 하면 분위기를 느끼지 않아도 잘한 거예요.","answer":"X","reason_options":[{"t":"분위기를 느끼며 살려 읽어야 듣는 사람에게 잘 전해지니까","correct":true},{"t":"외우기만 하면 낭송은 끝이니까","mis":"K2-1-u4-X15"}],"mis":"K2-1-u4-X15","explanation":["외우는 것보다 분위기를 느끼며 읽는 것이 중요해요.","분위기가 살아야 듣는 사람도 시를 느껴요.","외우지 못해도 시를 보며 낭송할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#6','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C10',3,'mc','auto','친구의 낭송을 들을 때 함께 하면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":6,"concept":"K2-1-u4-C10","difficulty":3,"kind":"mc","stem":"친구의 낭송을 들을 때 함께 하면 좋은 것은 어느 것인가요?","options":[{"t":"시의 장면과 분위기를 떠올리며 들어요","correct":true},{"t":"내 차례에 읽을 시만 계속 연습해요","mis":"K2-1-u4-X16"},{"t":"친구 목소리를 흉내 내며 놀려요","mis":"K2-1-u4-X16"}],"explanation":["장면과 분위기를 떠올리며 들으면 시를 함께 느낄 수 있어요.","내 시만 연습하면 친구의 시를 놓쳐요.","흉내 내며 놀리면 친구가 속상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#7','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',3,'mc','auto','하람이가 「공놀이」를 낭송하려고 해요. 가장 알맞은 낭송 계획은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X15']::text[],false,'{"seq":7,"concept":"K2-1-u4-C9","difficulty":3,"kind":"mc","stem":"하람이가 「공놀이」를 낭송하려고 해요. 가장 알맞은 낭송 계획은 어느 것인가요?","options":[{"t":"밝고 신나는 목소리로, 친구들을 보며 또렷하게","correct":true},{"t":"작고 슬픈 목소리로, 고개를 숙이고","mis":"K2-1-u4-X11"},{"t":"장난스럽게 웃으며 아무렇게나","mis":"K2-1-u4-X15"}],"explanation":["「공놀이」는 신나는 시라 밝고 신나는 목소리가 어울려요.","작고 슬픈 목소리는 이 시와 맞지 않아요.","장난스럽게 읽으면 분위기가 흐려져요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#8','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C10',4,'mc','auto','친구들이 낭송한 시가 서로 달랐어요. 알맞은 생각은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":8,"concept":"K2-1-u4-C10","difficulty":4,"kind":"mc","stem":"친구들이 낭송한 시가 서로 달랐어요. 알맞은 생각은 어느 것인가요?","options":[{"t":"친구마다 마음에 드는 시가 달라 여러 분위기를 느낄 수 있어 좋아요","correct":true},{"t":"모두 같은 시를 낭송해야 해요","mis":"K2-1-u4-X16"},{"t":"내 시와 다른 시는 들을 필요가 없어요","mis":"K2-1-u4-X16"}],"explanation":["서로 다른 시를 나누면 여러 분위기를 만날 수 있어요.","같은 시만 낭송할 필요는 없어요.","다른 시도 잘 들어야 친구의 마음을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#9','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',4,'essay','teacher','내가 낭송하고 싶은 시(배운 시나 좋아하는 시)를 하나 정해 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지 계획을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"내가 낭송하고 싶은 시(배운 시나 좋아하는 시)를 하나 정해 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지 계획을 써 보세요.","answer_guide":{"answer":"예: 「첫눈」 — 조용한 분위기예요. 부드럽고 작은 목소리로, 천천히 낭송할 거예요.","scoring_points":["시와 그 분위기를 썼는가","분위기에 맞는 목소리를 정했는가","분위기에 맞는 빠르기를 정했는가"]},"explanation":["시와 분위기.","목소리.","빠르기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#10','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C10',4,'essay','teacher','친구가 시를 낭송할 때 지켜야 할 듣기 태도를 두 가지 쓰고, 그렇게 해야 하는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C10","difficulty":4,"kind":"essay","stem":"친구가 시를 낭송할 때 지켜야 할 듣기 태도를 두 가지 쓰고, 그렇게 해야 하는 까닭을 써 보세요.","answer_guide":{"answer":"예: 조용히 끝까지 들어요. 끝나면 박수를 쳐 줘요. — 친구가 마음 놓고 낭송할 수 있고, 친구 시에 담긴 마음을 잘 알 수 있기 때문이에요.","scoring_points":["좋은 듣기 태도를 두 가지 썼는가","두 가지가 서로 다른 태도인가","그렇게 해야 하는 까닭을 썼는가"]},"explanation":["듣기 태도 둘.","서로 다른 태도.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#1','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"산","mis":"K2-1-u4-X05"},{"t":"손","mis":"K2-1-u4-X05"}],"explanation":["「닭」의 받침 자리에는 ㄹ과 ㄱ, 두 글자가 있어요.","「산」·「손」은 받침이 하나이거나 없어요.","이런 받침을 겹받침이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#2','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C2',1,'mc','auto','「닭」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X02']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「닭」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[닥]","correct":true},{"t":"[달]","mis":"K2-1-u4-X03"},{"t":"[달ㄱ]","mis":"K2-1-u4-X02"}],"explanation":["ㄺ 받침은 [ㄱ] 소리가 나서 [닥]이에요.","겹받침은 두 글자 가운데 정해진 한 글자의 소리로 읽어요.","뒤 글자가 세게 나는 소리도 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#3','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C3',1,'mc','auto','[닥]이라고 소리 나는, 「꼬끼오」 하고 우는 동물을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[닥]이라고 소리 나는, 「꼬끼오」 하고 우는 동물을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"닥","mis":"K2-1-u4-X01"},{"t":"닯","mis":"K2-1-u4-X06"}],"explanation":["[닥]으로 들려도 받침 두 글자를 살려 「닭」이라고 써요.","「닥」은 소리 나는 대로 썼어요.","「닯」은 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#4','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C5',1,'mc','auto','글이나 시를 읽을 때 느껴지는 기분을 무엇이라고 하나요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":4,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"글이나 시를 읽을 때 느껴지는 기분을 무엇이라고 하나요?","options":[{"t":"분위기","correct":true},{"t":"제목","mis":"K2-1-u4-X08"},{"t":"겹받침","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시를 읽을 때 느껴지는 기분이에요.","「제목」·「겹받침」은 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#5','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"신나는","correct":true},{"t":"슬픈","mis":"K2-1-u4-X09"},{"t":"무서운","mis":"K2-1-u4-X09"}],"explanation":["시에 나오는 말과 장면에서 신나는 기분이 느껴져요.","슬픈·무서운 느낌을 주는 말은 시에 없어요.","시의 말에 동그라미를 치고 기분을 떠올려요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#6','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C7',1,'mc','auto','신나는 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"신나는 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"밝고 빠르게","correct":true},{"t":"작고 느릿느릿하게","mis":"K2-1-u4-X11"},{"t":"울먹이며 느리게","mis":"K2-1-u4-X11"}],"explanation":["신나는 분위기는 밝고 빠르게 읽으면 살아나요.","다른 방법은 이 분위기와 어울리지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#7','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C10',1,'mc','auto','친구가 시를 낭송할 때 좋은 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 시를 낭송할 때 좋은 듣기 태도는 어느 것인가요?","options":[{"t":"조용히 끝까지 들어요","correct":true},{"t":"옆 친구와 떠들어요","mis":"K2-1-u4-X16"},{"t":"다른 책을 읽어요","mis":"K2-1-u4-X16"}],"explanation":["조용히 끝까지 들어 주면 친구가 마음껏 낭송할 수 있어요.","다른 행동은 낭송하는 친구를 속상하게 해요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#8','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C8',1,'ox','auto','「//」 표시에서는 「/」 표시보다 조금 더 쉬어 읽어요.',ARRAY['K2-1-u4-X14']::text[],false,'{"seq":8,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"「//」 표시에서는 「/」 표시보다 조금 더 쉬어 읽어요.","answer":"O","reason_options":[{"t":"「//」는 조금 더 쉬라는 표시이니까","correct":true},{"t":"「//」는 붙여 읽으라는 표시이니까","mis":"K2-1-u4-X14"}],"mis":"K2-1-u4-X14","explanation":["「/」에서는 조금 쉬고, 「//」에서는 조금 더 쉬어요.","뜻이 이어지는 말끼리 묶어 읽어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#9','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"닭","r":"[닥]"},{"l":"값","r":"[갑]"},{"l":"흙","r":"[흑]"}],"mis":"K2-1-u4-X03","explanation":["「닭」은 [닥]이라고 읽어요.","「값」은 [갑]이라고 읽어요.","「흙」은 [흑]이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#10','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C3',2,'ox','auto','「값」은 [갑]으로 소리 나니까 「갑」이라고 써요.',ARRAY['K2-1-u4-X01']::text[],false,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":2,"kind":"ox","stem":"「값」은 [갑]으로 소리 나니까 「갑」이라고 써요.","answer":"X","reason_options":[{"t":"소리는 하나여도 받침 두 글자를 살려 쓰니까","correct":true},{"t":"들리는 소리대로 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「값」은 [갑]으로 읽지만 「값」이라고 써요.","겹받침은 쓸 때 받침 두 글자를 모두 살려요.","읽을 때와 쓸 때를 가려 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#11','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 할머니와 텃밭에 가서 고른 것은 무엇인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":11,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 할머니와 텃밭에 가서 고른 것은 무엇인가요?","options":[{"t":"흙","correct":true},{"t":"닭","mis":"K2-1-u4-X07"},{"t":"바구니","mis":"K2-1-u4-X07"}],"explanation":["「할머니와 텃밭에 가서 흙을 골랐어요.」라고 했어요.","다른 내용은 글에 없어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#12','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":12,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"맑은 · 닭 · 넓고","correct":true},{"t":"하늘이 · 닭 · 넓고","mis":"K2-1-u4-X05"},{"t":"텃밭에 · 상추 · 고추는","mis":"K2-1-u4-X05"}],"explanation":["「맑은 · 닭 · 넓고」에는 모두 겹받침이 있어요.","다른 묶음에는 겹받침이 없는 낱말이 섞여 있어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#13','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C6',2,'mc','auto','신나는 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":13,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"신나는 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"콩콩","correct":true},{"t":"살며시","mis":"K2-1-u4-X10"},{"t":"가만히","mis":"K2-1-u4-X10"}],"explanation":["「콩콩」은 신나는 느낌을 줘요.","「살며시」·「가만히」는 다른 분위기의 말이에요.","소리 내어 따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#14','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C7',2,'ox','auto','시는 빠르게 읽을수록 언제나 잘 읽은 거예요.',ARRAY['K2-1-u4-X12']::text[],false,'{"seq":14,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"시는 빠르게 읽을수록 언제나 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"분위기에 맞는 빠르기로 읽어야 하니까","correct":true},{"t":"빨리 읽으면 무조건 잘 읽은 것이니까","mis":"K2-1-u4-X12"}],"mis":"K2-1-u4-X12","explanation":["조용한 시는 천천히 읽어야 분위기가 살아나요.","분위기에 맞게 목소리와 빠르기를 정해요.","시마다 알맞은 읽기 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#15','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C9',2,'mc','auto','시 낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":15,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"시 낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시 고르기 → 연습하기 → 낭송하기","correct":true},{"t":"낭송하기 → 시 고르기 → 연습하기","mis":"K2-1-u4-X15"},{"t":"연습하기 → 낭송하기 → 시 고르기","mis":"K2-1-u4-X15"}],"explanation":["시를 고르고, 연습한 뒤에 낭송해요.","다른 것은 낭송을 잘하는 방법이 아니에요.","고르기 → 연습하기 → 낭송하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#16','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":16,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「달님이 / 살며시 // 창문을 / 들여다봐요」","correct":true},{"t":"「달 / 님이 / 살 / 며시 창문을 들여다봐요」","mis":"K2-1-u4-X13"},{"t":"「달님이살며시창문을들여다봐요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#17','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X17']::text[],false,'{"seq":17,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"시우 — 「흙 → [흘]」","correct":true,"mis_target":"K2-1-u4-X03"},{"t":"다은 — 「닭 → [닥]」","mis":"K2-1-u4-X17"},{"t":"로아 — 「값 → [갑]」","mis":"K2-1-u4-X17"}],"explanation":["「흙」은 [흑]이라고 읽어요.","겹받침은 정해진 한 글자의 소리로 읽어요.","다른 두 친구는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#18','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X17']::text[],false,'{"seq":18,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"하준 — 「흑 위에 꽃씨를 심었다.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"다은 — 「연필 값이 비싸다.」","mis":"K2-1-u4-X17"},{"t":"시우 — 「의자에 앉았다.」","mis":"K2-1-u4-X17"}],"explanation":["「흑」은 소리대로 썼어요. 「흙」이라고 써야 해요.","다른 두 친구는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#19','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C4',3,'error','auto','글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X07','K2-1-u4-X17']::text[],false,'{"seq":19,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"민호 — 「닭이 바구니에 들어갔어.」","correct":true,"mis_target":"K2-1-u4-X07"},{"t":"소율 — 「할머니와 흙을 골랐어.」","mis":"K2-1-u4-X17"},{"t":"지우 — 「상추 잎은 넓었어.」","mis":"K2-1-u4-X17"}],"explanation":["닭은 흙을 밟고 지나갔다고 했어요.","글에 없는 내용으로 말하면 안 돼요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#20','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":20,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"은솔 — 「쉿, 새근새근 잠든 아기 → 신나는」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"태민 — 「와아 와아 들썩이는 운동장 → 신나는」","mis":"K2-1-u4-X17"},{"t":"아린 — 「하나 둘 발맞추는 아이들 → 씩씩한」","mis":"K2-1-u4-X17"}],"explanation":["「쉿」·「새근새근」은 조용한 느낌이에요.","장면에 나오는 말에서 분위기를 느껴요.","다른 두 친구는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#21','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C1',3,'mc','auto','다음 문장에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#22','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],false,'{"seq":22,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"시우 — 「몰래 짝에게 쪽지를 썼어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"다은 — 「낭송하는 친구를 바라보며 들었어요.」","mis":"K2-1-u4-X17"},{"t":"로아 — 「끝난 뒤 박수를 쳤어요.」","mis":"K2-1-u4-X17"}],"explanation":["낭송할 때 쪽지를 쓰는 것은 딴짓이에요.","다른 두 친구는 좋은 듣기 태도를 보였어요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#23','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C7',4,'mc','auto','「통통 공이 튀어요 / 쉿, 아기가 자요」처럼 한 시 안에서 분위기가 바뀌면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u4-X11','K2-1-u4-X12']::text[],false,'{"seq":23,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"「통통 공이 튀어요 / 쉿, 아기가 자요」처럼 한 시 안에서 분위기가 바뀌면 어떻게 읽으면 좋을까요?","options":[{"t":"앞줄은 밝고 빠르게, 뒷줄은 작고 천천히 바꾸어 읽어요","correct":true},{"t":"처음 목소리 그대로 끝까지 읽어요","mis":"K2-1-u4-X11"},{"t":"두 줄 모두 크고 빠르게 읽어요","mis":"K2-1-u4-X12"}],"explanation":["「쉿」부터는 조용한 분위기라 목소리를 바꾸어요.","한 가지 방법으로만 읽으면 분위기가 살지 않아요.","분위기에 맞게 목소리와 빠르기를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#24','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C3',4,'essay','teacher','다음 문장에서 소리 나는 대로 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#25','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C9',4,'essay','teacher','시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.","answer_guide":{"answer":"예: 신나는 분위기예요. 밝고 빠르게 낭송하고, 친구들을 바라보며 바른 자세로 읽을 거예요.","scoring_points":["시의 분위기를 알맞게 썼는가","분위기에 맞는 목소리와 빠르기를 정했는가","또렷하게·친구를 바라보며 같은 낭송 태도를 썼는가"]},"explanation":["분위기.","목소리·빠르기.","낭송 태도."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#1','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"감","mis":"K2-1-u4-X05"},{"t":"강","mis":"K2-1-u4-X05"}],"explanation":["「값」의 받침 자리에는 ㅂ과 ㅅ, 두 글자가 있어요.","「감」·「강」은 받침이 하나이거나 없어요.","이런 받침을 겹받침이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#2','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C2',1,'mc','auto','「앉다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X04','K2-1-u4-X03']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「앉다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[안따]","correct":true},{"t":"[안다]","mis":"K2-1-u4-X04"},{"t":"[앚따]","mis":"K2-1-u4-X03"}],"explanation":["ㄵ 받침은 [ㄴ] 소리가 나고 「다」는 [따]로 나서 [안따]예요.","겹받침은 두 글자 가운데 정해진 한 글자의 소리로 읽어요.","뒤 글자가 세게 나는 소리도 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#3','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C3',1,'mc','auto','[갑]이라고 소리 나는, 물건을 살 때 치르는 돈을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[갑]이라고 소리 나는, 물건을 살 때 치르는 돈을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"갑","mis":"K2-1-u4-X01"},{"t":"갋","mis":"K2-1-u4-X06"}],"explanation":["[갑]으로 들려도 받침 두 글자를 살려 「값」이라고 써요.","「갑」은 소리 나는 대로 썼어요.","「갋」은 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#4','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C5',1,'mc','auto','「분위기」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":4,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"「분위기」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글이나 시를 읽을 때 느껴지는 기분","correct":true},{"t":"글에 나오는 사람의 이름","mis":"K2-1-u4-X08"},{"t":"글에 있는 글자의 수","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시를 읽을 때 느껴지는 기분이에요.","「글에 나오는 사람의 이름」·「글에 있는 글자의 수」는 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#5','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"조용한","correct":true},{"t":"시끄러운","mis":"K2-1-u4-X09"},{"t":"화난","mis":"K2-1-u4-X09"}],"explanation":["시에 나오는 말과 장면에서 조용한 기분이 느껴져요.","시끄러운·화난 느낌을 주는 말은 시에 없어요.","시의 말에 동그라미를 치고 기분을 떠올려요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#6','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C7',1,'mc','auto','조용한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"조용한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"천천히 부드럽게","correct":true},{"t":"빠르고 크게","mis":"K2-1-u4-X11"},{"t":"소리 지르며 세게","mis":"K2-1-u4-X11"}],"explanation":["조용한 분위기는 천천히 부드럽게 읽으면 살아나요.","다른 방법은 이 분위기와 어울리지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#7','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C10',1,'mc','auto','친구의 낭송이 끝났을 때 알맞은 행동은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구의 낭송이 끝났을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"박수를 쳐 주어요","correct":true},{"t":"고개를 돌리고 하품해요","mis":"K2-1-u4-X16"},{"t":"「틀렸다」고 놀려요","mis":"K2-1-u4-X16"}],"explanation":["박수는 잘 들었다는 마음을 전해요.","다른 행동은 낭송하는 친구를 속상하게 해요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#8','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C8',1,'ox','auto','「/」 표시에서는 쉬지 않고 붙여 읽어요.',ARRAY['K2-1-u4-X14']::text[],false,'{"seq":8,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"「/」 표시에서는 쉬지 않고 붙여 읽어요.","answer":"X","reason_options":[{"t":"「/」는 조금 쉬어 읽으라는 표시이니까","correct":true},{"t":"「/」는 빠르게 읽으라는 표시이니까","mis":"K2-1-u4-X14"}],"mis":"K2-1-u4-X14","explanation":["「/」에서는 조금 쉬어 읽어요.","뜻이 이어지는 말끼리 묶어 읽어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#9','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"앉다","r":"[안따]"},{"l":"넓다","r":"[널따]"},{"l":"맑다","r":"[막따]"}],"mis":"K2-1-u4-X03","explanation":["「앉다」는 [안따]라고 읽어요.","「넓다」는 [널따]라고 읽어요.","「맑다」는 [막따]라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#10','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C3',2,'ox','auto','「닭」은 [닥]으로 읽지만 쓸 때는 「닭」이라고 써요.',ARRAY['K2-1-u4-X01']::text[],false,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":2,"kind":"ox","stem":"「닭」은 [닥]으로 읽지만 쓸 때는 「닭」이라고 써요.","answer":"O","reason_options":[{"t":"읽는 소리와 쓰는 글자가 다를 수 있으니까","correct":true},{"t":"쓸 때도 소리대로 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「닭」은 [닥]으로 읽고 「닭」으로 써요.","겹받침은 쓸 때 받침 두 글자를 모두 살려요.","읽을 때와 쓸 때를 가려 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#11','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 「나」는 도서관 어디에 앉아 책을 읽었나요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":11,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「나」는 도서관 어디에 앉아 책을 읽었나요?","options":[{"t":"창가 의자","correct":true},{"t":"바닷가 모래밭","mis":"K2-1-u4-X07"},{"t":"언니 옆 바닥","mis":"K2-1-u4-X07"}],"explanation":["「창가 의자에 앉아 그림책을 읽었어요.」라고 했어요.","다른 내용은 글에 없어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#12','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":12,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"앉아 · 읽고 · 많아서","correct":true},{"t":"언니와 · 읽고 · 많아서","mis":"K2-1-u4-X05"},{"t":"의자에 · 바닷가는 · 두","mis":"K2-1-u4-X05"}],"explanation":["「앉아 · 읽고 · 많아서」에는 모두 겹받침이 있어요.","다른 묶음에는 겹받침이 없는 낱말이 섞여 있어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#13','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C6',2,'mc','auto','조용한 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":13,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"조용한 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"소복소복","correct":true},{"t":"와아","mis":"K2-1-u4-X10"},{"t":"들썩들썩","mis":"K2-1-u4-X10"}],"explanation":["「소복소복」은 조용한 느낌을 줘요.","「와아」·「들썩들썩」은 다른 분위기의 말이에요.","소리 내어 따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#14','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C7',2,'ox','auto','모든 시를 한 가지 목소리로 똑같이 읽어도 분위기가 잘 살아나요.',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":14,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"모든 시를 한 가지 목소리로 똑같이 읽어도 분위기가 잘 살아나요.","answer":"X","reason_options":[{"t":"시마다 분위기가 달라 목소리도 바꾸어야 하니까","correct":true},{"t":"목소리는 늘 같아야 하니까","mis":"K2-1-u4-X11"}],"mis":"K2-1-u4-X11","explanation":["같은 목소리로 읽으면 시마다 다른 분위기가 드러나지 않아요.","분위기에 맞게 목소리와 빠르기를 정해요.","시마다 알맞은 읽기 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#15','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C9',2,'mc','auto','시를 낭송할 때 알맞은 태도는 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":15,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"시를 낭송할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"분위기를 살려 또박또박 읽어요","correct":true},{"t":"장난치며 아무렇게나 읽어요","mis":"K2-1-u4-X15"},{"t":"작게 우물우물 읽어요","mis":"K2-1-u4-X15"}],"explanation":["분위기를 살려 또박또박 읽어야 시가 잘 전해져요.","다른 것은 낭송을 잘하는 방법이 아니에요.","고르기 → 연습하기 → 낭송하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#16','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":16,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「강아지가 / 꼬리를 // 흔들어요」","correct":true},{"t":"「강 / 아지가꼬 / 리를 흔들어요」","mis":"K2-1-u4-X13"},{"t":"「강아지가꼬리를흔들어요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#17','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X04','K2-1-u4-X17']::text[],false,'{"seq":17,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"은솔 — 「앉다 → [안다]」","correct":true,"mis_target":"K2-1-u4-X04"},{"t":"태민 — 「많다 → [만타]」","mis":"K2-1-u4-X17"},{"t":"아린 — 「맑다 → [막따]」","mis":"K2-1-u4-X17"}],"explanation":["「앉다」는 [안따]라고 읽어요.","겹받침은 정해진 한 글자의 소리로 읽어요.","다른 두 친구는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#18','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X17']::text[],false,'{"seq":18,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호 — 「사과가 여덜 개 있다.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"예린 — 「동화책을 읽었다.」","mis":"K2-1-u4-X17"},{"t":"소율 — 「운동장이 넓다.」","mis":"K2-1-u4-X17"}],"explanation":["「여덜」은 소리대로 썼어요. 「여덟」이라고 써야 해요.","다른 두 친구는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#19','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C4',3,'error','auto','글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X07','K2-1-u4-X17']::text[],false,'{"seq":19,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「책이 없어서 그냥 돌아왔어.」","correct":true,"mis_target":"K2-1-u4-X07"},{"t":"하늘 — 「창가 의자에 앉아 읽었어.」","mis":"K2-1-u4-X17"},{"t":"예린 — 「책을 두 권 빌렸어.」","mis":"K2-1-u4-X17"}],"explanation":["읽고 싶은 책이 많아서 두 권을 빌렸다고 했어요.","글에 없는 내용으로 말하면 안 돼요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#20','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":20,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"준우 — 「콩콩 뛰는 줄넘기 → 조용한」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"민지 — 「소복소복 눈 오는 밤 → 조용한」","mis":"K2-1-u4-X17"},{"t":"하준 — 「따스한 봄 햇살 → 포근한」","mis":"K2-1-u4-X17"}],"explanation":["「콩콩」은 신나는 느낌이에요.","장면에 나오는 말에서 분위기를 느껴요.","다른 두 친구는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#21','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C1',3,'mc','auto','다음 문장에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#22','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],false,'{"seq":22,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"준우 — 「낭송 도중에 크게 하품하며 엎드렸어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"지안 — 「시의 장면을 떠올리며 들었어요.」","mis":"K2-1-u4-X17"},{"t":"하린 — 「끝까지 조용히 들었어요.」","mis":"K2-1-u4-X17"}],"explanation":["크게 하품하며 엎드리면 낭송하는 친구가 속상해요.","다른 두 친구는 좋은 듣기 태도를 보였어요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#23','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C7',4,'mc','auto','친구가 「달밤」을 크고 빠르게 읽었어요. 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X12','K2-1-u4-X11']::text[],false,'{"seq":23,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"친구가 「달밤」을 크고 빠르게 읽었어요. 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「조용한 시니까 천천히 부드럽게 읽어 보자.」","correct":true},{"t":"「더 크고 더 빠르게 읽으면 좋겠어.」","mis":"K2-1-u4-X12"},{"t":"「소리치며 읽으면 더 잘 들려.」","mis":"K2-1-u4-X11"}],"explanation":["「달밤」은 조용한 시예요.","한 가지 방법으로만 읽으면 분위기가 살지 않아요.","분위기에 맞게 목소리와 빠르기를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#24','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C3',4,'essay','teacher','다음 문장에서 소리 나는 대로 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#25','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C9',4,'essay','teacher','시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.","answer_guide":{"answer":"예: 조용한 분위기예요. 천천히 부드럽게 낭송하고, 친구들을 바라보며 바른 자세로 읽을 거예요.","scoring_points":["시의 분위기를 알맞게 썼는가","분위기에 맞는 목소리와 빠르기를 정했는가","또렷하게·친구를 바라보며 같은 낭송 태도를 썼는가"]},"explanation":["분위기.","목소리·빠르기.","낭송 태도."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#1','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"흙","correct":true},{"t":"곰","mis":"K2-1-u4-X05"},{"t":"문","mis":"K2-1-u4-X05"}],"explanation":["「흙」의 받침 자리에는 ㄹ과 ㄱ, 두 글자가 있어요.","「곰」·「문」은 받침이 하나이거나 없어요.","이런 받침을 겹받침이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#2','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C2',1,'mc','auto','「넓다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X04']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「넓다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[널따]","correct":true},{"t":"[넙따]","mis":"K2-1-u4-X03"},{"t":"[널다]","mis":"K2-1-u4-X04"}],"explanation":["ㄼ 받침은 [ㄹ] 소리가 나고 「다」는 [따]로 나서 [널따]예요.","겹받침은 두 글자 가운데 정해진 한 글자의 소리로 읽어요.","뒤 글자가 세게 나는 소리도 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#3','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C3',1,'mc','auto','[여덜]이라고 소리 나는, 일곱 다음의 수를 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[여덜]이라고 소리 나는, 일곱 다음의 수를 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"여덟","correct":true},{"t":"여덜","mis":"K2-1-u4-X01"},{"t":"여덥","mis":"K2-1-u4-X06"}],"explanation":["[여덜]로 들려도 받침 두 글자를 살려 「여덟」이라고 써요.","「여덜」은 소리 나는 대로 썼어요.","「여덥」은 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#4','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C5',1,'mc','auto','「신나는」, 「조용한」, 「포근한」은 시의 무엇을 나타내는 말인가요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":4,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"「신나는」, 「조용한」, 「포근한」은 시의 무엇을 나타내는 말인가요?","options":[{"t":"시의 분위기","correct":true},{"t":"시의 제목","mis":"K2-1-u4-X08"},{"t":"시의 글자 수","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시를 읽을 때 느껴지는 기분이에요.","「시의 제목」·「시의 글자 수」는 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#5','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"포근한","correct":true},{"t":"무서운","mis":"K2-1-u4-X09"},{"t":"쓸쓸한","mis":"K2-1-u4-X09"}],"explanation":["시에 나오는 말과 장면에서 포근한 기분이 느껴져요.","무서운·쓸쓸한 느낌을 주는 말은 시에 없어요.","시의 말에 동그라미를 치고 기분을 떠올려요."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#6','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C7',1,'mc','auto','씩씩한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"씩씩한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"또렷하고 힘차게","correct":true},{"t":"졸린 듯 작게","mis":"K2-1-u4-X11"},{"t":"울먹이며 느리게","mis":"K2-1-u4-X11"}],"explanation":["씩씩한 분위기는 또렷하고 힘차게 읽으면 살아나요.","다른 방법은 이 분위기와 어울리지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#7','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C10',1,'mc','auto','친구가 낭송할 때 어디를 보며 들으면 좋을까요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 낭송할 때 어디를 보며 들으면 좋을까요?","options":[{"t":"낭송하는 친구","correct":true},{"t":"창밖","mis":"K2-1-u4-X16"},{"t":"내 공책","mis":"K2-1-u4-X16"}],"explanation":["낭송하는 친구를 바라보며 들으면 시가 더 잘 들려요.","다른 행동은 낭송하는 친구를 속상하게 해요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#8','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C8',1,'ox','auto','한 글자씩 끊어 읽으면 뜻이 가장 잘 드러나요.',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":8,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"한 글자씩 끊어 읽으면 뜻이 가장 잘 드러나요.","answer":"X","reason_options":[{"t":"뜻이 이어지는 말끼리 묶어 읽어야 뜻이 드러나니까","correct":true},{"t":"글자를 하나씩 읽어야 또박또박하니까","mis":"K2-1-u4-X13"}],"mis":"K2-1-u4-X13","explanation":["한 글자씩 끊으면 낱말의 뜻이 흐려져요.","뜻이 이어지는 말끼리 묶어 읽어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#9','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"많다","r":"[만타]"},{"l":"읽다","r":"[익따]"},{"l":"짧다","r":"[짤따]"}],"mis":"K2-1-u4-X03","explanation":["「많다」는 [만타]라고 읽어요.","「읽다」는 [익따]라고 읽어요.","「짧다」는 [짤따]라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#10','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C3',2,'ox','auto','「앉다」는 [안따]로 소리 나니까 「안따」라고 써요.',ARRAY['K2-1-u4-X01']::text[],false,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":2,"kind":"ox","stem":"「앉다」는 [안따]로 소리 나니까 「안따」라고 써요.","answer":"X","reason_options":[{"t":"소리는 [안따]여도 받침 ㄴ과 ㅈ을 살려 쓰니까","correct":true},{"t":"들리는 소리대로 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「앉다」는 [안따]로 읽지만 「앉다」라고 써요.","겹받침은 쓸 때 받침 두 글자를 모두 살려요.","읽을 때와 쓸 때를 가려 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#11','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 엄마가 물어보신 것은 무엇인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":11,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 엄마가 물어보신 것은 무엇인가요?","options":[{"t":"꿀떡 값","correct":true},{"t":"떡집 이름","mis":"K2-1-u4-X07"},{"t":"시장 가는 길","mis":"K2-1-u4-X07"}],"explanation":["「엄마가 꿀떡 값을 물어보셨어요.」라고 했어요.","다른 내용은 글에 없어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#12','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":12,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"많았어요 · 값 · 없었어요","correct":true},{"t":"많았어요 · 값 · 떡집","mis":"K2-1-u4-X05"},{"t":"시장에 · 값 · 없었어요","mis":"K2-1-u4-X05"}],"explanation":["「많았어요 · 값 · 없었어요」에는 모두 겹받침이 있어요.","다른 묶음에는 겹받침이 없는 낱말이 섞여 있어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#13','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C6',2,'mc','auto','씩씩한 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":13,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"씩씩한 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"힘차게","correct":true},{"t":"새근새근","mis":"K2-1-u4-X10"},{"t":"살금살금","mis":"K2-1-u4-X10"}],"explanation":["「힘차게」는 씩씩한 느낌을 줘요.","「새근새근」·「살금살금」은 다른 분위기의 말이에요.","소리 내어 따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#14','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C7',2,'ox','auto','조용한 시는 천천히, 신나는 시는 조금 빠르게 읽으면 분위기가 살아나요.',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":14,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"조용한 시는 천천히, 신나는 시는 조금 빠르게 읽으면 분위기가 살아나요.","answer":"O","reason_options":[{"t":"분위기에 따라 알맞은 빠르기가 다르니까","correct":true},{"t":"모든 시는 같은 빠르기로 읽어야 하니까","mis":"K2-1-u4-X11"}],"mis":"K2-1-u4-X11","explanation":["분위기에 따라 빠르기를 바꾸어 읽어요.","분위기에 맞게 목소리와 빠르기를 정해요.","시마다 알맞은 읽기 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#15','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C9',2,'mc','auto','낭송할 시를 고를 때 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":15,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"낭송할 시를 고를 때 알맞은 것은 어느 것인가요?","options":[{"t":"읽었을 때 마음에 들고 분위기가 좋은 시","correct":true},{"t":"무조건 가장 긴 시","mis":"K2-1-u4-X15"},{"t":"읽어 보지 않고 아무거나 고른 시","mis":"K2-1-u4-X15"}],"explanation":["마음에 드는 시를 골라야 분위기를 살려 낭송할 수 있어요.","다른 것은 낭송을 잘하는 방법이 아니에요.","고르기 → 연습하기 → 낭송하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#16','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":16,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「우리는 / 씩씩한 어린이」","correct":true},{"t":"「우 / 리는씩 / 씩한 어린이」","mis":"K2-1-u4-X13"},{"t":"「우리는씩씩한어린이」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#17','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X17']::text[],false,'{"seq":17,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"민호 — 「넓다 → [넙따]」","correct":true,"mis_target":"K2-1-u4-X03"},{"t":"하린 — 「없다 → [업따]」","mis":"K2-1-u4-X17"},{"t":"지후 — 「짧다 → [짤따]」","mis":"K2-1-u4-X17"}],"explanation":["「넓다」는 [널따]라고 읽어요.","겹받침은 정해진 한 글자의 소리로 읽어요.","다른 두 친구는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#18','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X06','K2-1-u4-X17']::text[],false,'{"seq":18,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"은솔 — 「의자에 않았다.」","correct":true,"mis_target":"K2-1-u4-X06"},{"t":"민지 — 「닭이 운다.」","mis":"K2-1-u4-X17"},{"t":"현우 — 「하늘이 맑다.」","mis":"K2-1-u4-X17"}],"explanation":["「않았다」는 받침 짝을 잘못 썼어요. 「앉았다」라고 써야 해요.","다른 두 친구는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#19','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C4',3,'error','auto','글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X07','K2-1-u4-X17']::text[],false,'{"seq":19,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「떡이 많이 남았어.」","correct":true,"mis_target":"K2-1-u4-X07"},{"t":"로아 — 「떡집 앞에 사람이 많았어.」","mis":"K2-1-u4-X17"},{"t":"하람 — 「엄마가 꿀떡 값을 물으셨어.」","mis":"K2-1-u4-X17"}],"explanation":["동생과 나누어 먹으니 남은 떡이 없었다고 했어요.","글에 없는 내용으로 말하면 안 돼요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#20','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":20,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"예린 — 「엄마 품처럼 폭신폭신 → 씩씩한」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"지호 — 「톡톡 춤추는 빗방울 → 신나는」","mis":"K2-1-u4-X17"},{"t":"다은 — 「살며시 들여다보는 달님 → 조용한」","mis":"K2-1-u4-X17"}],"explanation":["「엄마 품」·「폭신폭신」은 포근한 느낌이에요.","장면에 나오는 말에서 분위기를 느껴요.","다른 두 친구는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#21','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C1',3,'mc','auto','다음 문장에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#22','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],false,'{"seq":22,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"현우 — 「친구 목소리를 흉내 내며 놀렸어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"소율 — 「좋았던 점을 칭찬해 주었어요.」","mis":"K2-1-u4-X17"},{"t":"지우 — 「친구가 멈추었을 때 조용히 기다렸어요.」","mis":"K2-1-u4-X17"}],"explanation":["흉내 내며 놀리면 친구가 속상해요.","다른 두 친구는 좋은 듣기 태도를 보였어요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#23','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C7',4,'mc','auto','「와아, 눈이 온다」를 신나는 분위기가 더 잘 살아나게 읽는 방법은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X13']::text[],false,'{"seq":23,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"「와아, 눈이 온다」를 신나는 분위기가 더 잘 살아나게 읽는 방법은 어느 것인가요?","options":[{"t":"밝고 들뜬 목소리로 조금 빠르게 읽기","correct":true},{"t":"작고 낮은 목소리로 아주 느리게 읽기","mis":"K2-1-u4-X11"},{"t":"한 글자씩 뚝뚝 끊어 읽기","mis":"K2-1-u4-X13"}],"explanation":["밝고 들뜬 목소리가 「와아」의 신나는 느낌을 살려요.","한 가지 방법으로만 읽으면 분위기가 살지 않아요.","분위기에 맞게 목소리와 빠르기를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#24','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C3',4,'essay','teacher','다음 문장에서 소리 나는 대로 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#25','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C9',4,'essay','teacher','시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.","answer_guide":{"answer":"예: 포근한 분위기예요. 다정하고 따뜻하게 낭송하고, 친구들을 바라보며 바른 자세로 읽을 거예요.","scoring_points":["시의 분위기를 알맞게 썼는가","분위기에 맞는 목소리와 빠르기를 정했는가","또렷하게·친구를 바라보며 같은 낭송 태도를 썼는가"]},"explanation":["분위기.","목소리·빠르기.","낭송 태도."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#1','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"앉다","correct":true},{"t":"안다","mis":"K2-1-u4-X05"},{"t":"바다","mis":"K2-1-u4-X05"}],"explanation":["「앉」의 받침 자리에는 ㄴ과 ㅈ, 두 글자가 있어요.","「안다」·「바다」는 받침이 하나이거나 없어요.","이런 받침을 겹받침이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#2','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C2',1,'mc','auto','「값」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X02']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「값」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[갑]","correct":true},{"t":"[갓]","mis":"K2-1-u4-X03"},{"t":"[갑ㅅ]","mis":"K2-1-u4-X02"}],"explanation":["ㅄ 받침은 [ㅂ] 소리가 나서 [갑]이에요.","겹받침은 두 글자 가운데 정해진 한 글자의 소리로 읽어요.","뒤 글자가 세게 나는 소리도 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#3','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C3',1,'mc','auto','[안따]라고 소리 나는, 의자에 엉덩이를 대고 몸을 올려놓는 것을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[안따]라고 소리 나는, 의자에 엉덩이를 대고 몸을 올려놓는 것을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"앉다","correct":true},{"t":"안따","mis":"K2-1-u4-X01"},{"t":"않다","mis":"K2-1-u4-X06"}],"explanation":["[안따]로 들려도 받침 두 글자를 살려 「앉다」라고 써요.","「안따」는 소리 나는 대로 썼어요.","「않다」는 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#4','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C5',1,'mc','auto','시를 읽고 포근하다고 느꼈어요. 이렇게 느낀 기분을 무엇이라고 하나요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":4,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"시를 읽고 포근하다고 느꼈어요. 이렇게 느낀 기분을 무엇이라고 하나요?","options":[{"t":"분위기","correct":true},{"t":"받침","mis":"K2-1-u4-X08"},{"t":"줄거리","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시를 읽을 때 느껴지는 기분이에요.","「받침」·「줄거리」는 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#5','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"씩씩한","correct":true},{"t":"졸린","mis":"K2-1-u4-X09"},{"t":"슬픈","mis":"K2-1-u4-X09"}],"explanation":["시에 나오는 말과 장면에서 씩씩한 기분이 느껴져요.","졸린·슬픈 느낌을 주는 말은 시에 없어요.","시의 말에 동그라미를 치고 기분을 떠올려요."],"asset":{"type":"passage","lines":["하나 둘 하나 둘","발맞춰 걸어요","가슴 펴고 힘차게","우리는 씩씩해요"],"title":"발맞춰 걸어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#6','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C7',1,'mc','auto','포근한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"포근한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"다정하고 따뜻하게","correct":true},{"t":"크게 소리 지르며","mis":"K2-1-u4-X11"},{"t":"빠르고 거칠게","mis":"K2-1-u4-X11"}],"explanation":["포근한 분위기는 다정하고 따뜻하게 읽으면 살아나요.","다른 방법은 이 분위기와 어울리지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#7','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C10',1,'mc','auto','친구가 낭송하다가 잠깐 멈추었어요. 알맞은 행동은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 낭송하다가 잠깐 멈추었어요. 알맞은 행동은 어느 것인가요?","options":[{"t":"조용히 기다려 주어요","correct":true},{"t":"「빨리 해!」 하고 재촉해요","mis":"K2-1-u4-X16"},{"t":"깔깔 웃어요","mis":"K2-1-u4-X16"}],"explanation":["조용히 기다려 주면 친구가 다시 이어서 낭송할 수 있어요.","다른 행동은 낭송하는 친구를 속상하게 해요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#8','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C8',1,'ox','auto','뜻이 이어지는 말끼리 묶어 한 덩어리씩 띄어 읽어요.',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":8,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"뜻이 이어지는 말끼리 묶어 한 덩어리씩 띄어 읽어요.","answer":"O","reason_options":[{"t":"그래야 듣는 사람이 뜻을 잘 알아들으니까","correct":true},{"t":"덩어리로 묶으면 뜻이 흐려지니까","mis":"K2-1-u4-X13"}],"mis":"K2-1-u4-X13","explanation":["뜻 덩어리로 띄어 읽으면 뜻이 잘 전해져요.","뜻이 이어지는 말끼리 묶어 읽어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#9','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"없다","r":"[업따]"},{"l":"젊다","r":"[점따]"},{"l":"여덟","r":"[여덜]"}],"mis":"K2-1-u4-X03","explanation":["「없다」는 [업따]라고 읽어요.","「젊다」는 [점따]라고 읽어요.","「여덟」은 [여덜]이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#10','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C3',2,'ox','auto','「여덟」은 [여덜]로 읽지만 쓸 때는 「여덟」이라고 써요.',ARRAY['K2-1-u4-X01']::text[],false,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":2,"kind":"ox","stem":"「여덟」은 [여덜]로 읽지만 쓸 때는 「여덟」이라고 써요.","answer":"O","reason_options":[{"t":"읽는 소리와 쓰는 글자가 다를 수 있으니까","correct":true},{"t":"쓸 때도 소리대로 「여덜」이라고 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「여덟」은 [여덜]로 읽고 「여덟」으로 써요.","겹받침은 쓸 때 받침 두 글자를 모두 살려요.","읽을 때와 쓸 때를 가려 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#11','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 아빠와 돗자리를 깔고 앉은 곳은 어디인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":11,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 아빠와 돗자리를 깔고 앉은 곳은 어디인가요?","options":[{"t":"넓은 잔디밭","correct":true},{"t":"모래 놀이터","mis":"K2-1-u4-X07"},{"t":"나무 그늘 의자","mis":"K2-1-u4-X07"}],"explanation":["「넓은 잔디밭에 돗자리를 깔고 앉았어요.」라고 했어요.","다른 내용은 글에 없어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 날 아빠와 공원에 갔어요.","넓은 잔디밭에 돗자리를 깔고 앉았어요.","비둘기가 많아서 과자 부스러기를 조금 나누어 주었어요.","신나게 놀다 보니 하루가 짧게 느껴졌어요."],"title":"공원 소풍"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#12','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":12,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"맑은 · 넓은 · 앉았어요","correct":true},{"t":"공원에 · 넓은 · 앉았어요","mis":"K2-1-u4-X05"},{"t":"아빠와 · 돗자리를 · 과자","mis":"K2-1-u4-X05"}],"explanation":["「맑은 · 넓은 · 앉았어요」에는 모두 겹받침이 있어요.","다른 묶음에는 겹받침이 없는 낱말이 섞여 있어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 날 아빠와 공원에 갔어요.","넓은 잔디밭에 돗자리를 깔고 앉았어요.","비둘기가 많아서 과자 부스러기를 조금 나누어 주었어요.","신나게 놀다 보니 하루가 짧게 느껴졌어요."],"title":"공원 소풍"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#13','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C6',2,'mc','auto','포근한 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":13,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"포근한 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"폭신폭신","correct":true},{"t":"쿵쾅쿵쾅","mis":"K2-1-u4-X10"},{"t":"와글와글","mis":"K2-1-u4-X10"}],"explanation":["「폭신폭신」은 포근한 느낌을 줘요.","「쿵쾅쿵쾅」·「와글와글」은 다른 분위기의 말이에요.","소리 내어 따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#14','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C7',2,'ox','auto','크게 소리 지를수록 어떤 시든 분위기가 잘 살아나요.',ARRAY['K2-1-u4-X12']::text[],false,'{"seq":14,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"크게 소리 지를수록 어떤 시든 분위기가 잘 살아나요.","answer":"X","reason_options":[{"t":"조용하거나 포근한 시는 부드럽게 읽어야 하니까","correct":true},{"t":"목소리가 클수록 언제나 좋으니까","mis":"K2-1-u4-X12"}],"mis":"K2-1-u4-X12","explanation":["목소리 크기도 분위기에 맞추어요.","분위기에 맞게 목소리와 빠르기를 정해요.","시마다 알맞은 읽기 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#15','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C9',2,'mc','auto','연습을 하지 않고 바로 낭송하면 어떻게 될까요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":15,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"연습을 하지 않고 바로 낭송하면 어떻게 될까요?","options":[{"t":"분위기를 살려 또박또박 읽기 어려워요","correct":true},{"t":"언제나 더 멋지게 낭송할 수 있어요","mis":"K2-1-u4-X15"},{"t":"시의 분위기가 저절로 살아나요","mis":"K2-1-u4-X15"}],"explanation":["연습해야 분위기에 맞는 목소리를 찾을 수 있어요.","다른 것은 낭송을 잘하는 방법이 아니에요.","고르기 → 연습하기 → 낭송하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#16','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":16,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「톡톡 빗방울이 / 우산 위에서 // 춤을 춰요」","correct":true},{"t":"「톡 / 톡빗 / 방울이 우산 위에서 춤을 춰요」","mis":"K2-1-u4-X13"},{"t":"「톡톡빗방울이우산위에서춤을춰요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#17','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X02','K2-1-u4-X17']::text[],false,'{"seq":17,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"도담 — 「읽다 → [읽따]」","correct":true,"mis_target":"K2-1-u4-X02"},{"t":"서아 — 「젊다 → [점따]」","mis":"K2-1-u4-X17"},{"t":"하준 — 「여덟 → [여덜]」","mis":"K2-1-u4-X17"}],"explanation":["「읽다」는 [익따]라고 읽어요.","겹받침은 정해진 한 글자의 소리로 읽어요.","다른 두 친구는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#18','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X17']::text[],false,'{"seq":18,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"태민 — 「바지가 짤바요.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"하린 — 「모래가 많다.」","mis":"K2-1-u4-X17"},{"t":"지안 — 「물이 없다.」","mis":"K2-1-u4-X17"}],"explanation":["「짤바요」는 소리대로 썼어요. 「짧아요」라고 써야 해요.","다른 두 친구는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#19','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C4',3,'error','auto','글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X07','K2-1-u4-X17']::text[],false,'{"seq":19,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"지안 — 「비가 와서 공원에 못 갔어.」","correct":true,"mis_target":"K2-1-u4-X07"},{"t":"도담 — 「잔디밭이 넓었어.」","mis":"K2-1-u4-X17"},{"t":"시우 — 「비둘기에게 과자를 나누어 줬어.」","mis":"K2-1-u4-X17"}],"explanation":["하늘이 맑은 날 공원에 갔다고 했어요.","글에 없는 내용으로 말하면 안 돼요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["하늘이 맑은 날 아빠와 공원에 갔어요.","넓은 잔디밭에 돗자리를 깔고 앉았어요.","비둘기가 많아서 과자 부스러기를 조금 나누어 주었어요.","신나게 놀다 보니 하루가 짧게 느껴졌어요."],"title":"공원 소풍"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#20','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":20,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"하린 — 「가슴 펴고 힘차게 → 조용한」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"서아 — 「랄랄라 노래하는 웅덩이 → 신나는」","mis":"K2-1-u4-X17"},{"t":"도윤 — 「사뿐사뿐 내려앉는 낙엽 → 조용한」","mis":"K2-1-u4-X17"}],"explanation":["「가슴 펴고 힘차게」는 씩씩한 느낌이에요.","장면에 나오는 말에서 분위기를 느껴요.","다른 두 친구는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#21','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C1',3,'mc','auto','다음 문장에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#22','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],false,'{"seq":22,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"민호 — 「낭송 도중에 나도 하겠다며 끼어들었어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"예린 — 「친구 쪽으로 몸을 돌려 들었어요.」","mis":"K2-1-u4-X17"},{"t":"서윤 — 「끝까지 들은 뒤 손뼉을 쳤어요.」","mis":"K2-1-u4-X17"}],"explanation":["친구가 낭송하는 도중에 끼어들면 안 돼요.","다른 두 친구는 좋은 듣기 태도를 보였어요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#23','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C7',4,'mc','auto','「하나 둘 하나 둘 / 살금살금 고양이」처럼 씩씩하다가 조용해지는 시를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X12']::text[],false,'{"seq":23,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"「하나 둘 하나 둘 / 살금살금 고양이」처럼 씩씩하다가 조용해지는 시를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"앞줄은 또렷하고 힘차게, 뒷줄은 작고 살며시 읽어요","correct":true},{"t":"두 줄 모두 또렷하고 힘차게 읽어요","mis":"K2-1-u4-X11"},{"t":"두 줄 모두 아주 빠르게 읽어요","mis":"K2-1-u4-X12"}],"explanation":["「살금살금」부터는 조용한 분위기라 목소리를 바꾸어요.","한 가지 방법으로만 읽으면 분위기가 살지 않아요.","분위기에 맞게 목소리와 빠르기를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#24','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C3',4,'essay','teacher','다음 문장에서 소리 나는 대로 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#25','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C9',4,'essay','teacher','시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.","answer_guide":{"answer":"예: 씩씩한 분위기예요. 또렷하고 힘차게 낭송하고, 친구들을 바라보며 바른 자세로 읽을 거예요.","scoring_points":["시의 분위기를 알맞게 썼는가","분위기에 맞는 목소리와 빠르기를 정했는가","또렷하게·친구를 바라보며 같은 낭송 태도를 썼는가"]},"explanation":["분위기.","목소리·빠르기.","낭송 태도."],"asset":{"type":"passage","lines":["하나 둘 하나 둘","발맞춰 걸어요","가슴 펴고 힘차게","우리는 씩씩해요"],"title":"발맞춰 걸어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C1','kor',2,1,'u5',1,'마음 짐작의 뜻과 단서 — 다른 사람의 말·행동·표정·상황을 보고 어떤 마음인지 헤아리는 것이 마음 짐작이며, 마음을 헤아리면 친구를 더 잘 이해하고 배려할 수 있음을 알기',ARRAY['2국02-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C2','kor',2,1,'u5',1,'뜻이 드러나게 띄어 읽기 — 붙여 읽으면 뜻을 알기 어렵고, 「누가(무엇이)」에 해당하는 말 뒤처럼 뜻이 통하는 덩어리 사이에서 쉬어 읽으면 뜻이 잘 드러남을 알기(아빠가 / 방에 / 들어가신다)',ARRAY['2국02-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C3','kor',2,1,'u5',3,'말과 행동으로 인물의 마음 짐작하기 — 글 속 인물에게 일어난 일을 살피고, 마음이 드러난 말(「드디어 됐다!」)과 행동(두 손을 번쩍)을 찾아 까닭을 들어 마음을 짐작하기',ARRAY['2국02-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C4','kor',2,1,'u5',3,'상황으로 마음 짐작하고 나와 견주기 — 소풍 날 비가 오는 것처럼 인물이 놓인 상황으로 마음을 짐작하고, 「나라면 어떤 마음일까」 비슷한 경험과 견주며, 같은 일에도 사람마다 마음이 다를 수 있음을 알기',ARRAY['2국02-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C5','kor',2,1,'u5',3,'마음을 나타내는 말 — 기쁘다·설레다·뿌듯하다·고맙다·속상하다·서운하다·아쉽다·미안하다·억울하다·떨리다 같은 말의 뜻을 알고, 상황에 어울리는 마음 말을 고르기',ARRAY['2국02-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C6','kor',2,1,'u5',5,'시간에 따라 변하는 마음 따라 읽기 — 일이 일어난 차례를 따라가며 장면마다 인물의 마음을 짐작하고, 무엇 때문에 마음이 바뀌었는지 말하기(낯설고 떨림 → 고맙고 반가움 → 즐거움)',ARRAY['2국02-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C7','kor',2,1,'u5',7,'헷갈리기 쉬운 낱말 가려 쓰기 — 소리가 같거나 비슷해도 뜻이 다른 낱말(걸음·거름, 마치다·맞히다, 다치다·닫히다, 반듯이·반드시)과 뜻이 헷갈리는 낱말(가르치다·가리키다, 다르다·틀리다, 바라다·바래다, 잊다·잃다)을 문장의 뜻을 생각하며 바르게 골라 쓰기',ARRAY['2국04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C8','kor',2,1,'u5',9,'자연스럽게 띄어 읽기 — 낱말마다 뚝뚝 끊거나 쉬지 않고 붙여 읽지 않고, 의미가 통하는 덩어리로 쉬며, 문장과 문장 사이에서는 조금 더 길게 쉬어 물 흐르듯 읽기(띄어 읽을 곳에 빗금 표시)',ARRAY['2국02-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C9','kor',2,1,'u5',9,'인물의 마음을 살려 읽기 — 기쁜 장면은 밝고 가볍게, 슬픈 장면은 차분하고 느리게, 떨리는 장면은 작고 조심스럽게 — 알맞게 띄어 읽으면서 인물의 마음에 맞게 목소리를 바꾸어 읽기',ARRAY['2국02-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C10','kor',2,1,'u5',11,'마음을 나타내는 말로 전하고 헤아리기 — 마음 사전(마음 말 + 그 마음이 드는 상황)을 만들고, 「기분 나빠」 대신 「네 말에 서운했어」처럼 마음 말로 정확히 전하며, 친구의 마음 말에는 「속상했겠다」처럼 마음을 헤아린 맞장구로 반응하기',ARRAY['2국02-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X01','kor',2,'u5',ARRAY['K2-1-u5-C1','K2-1-u5-C3']::text[],'마음과 상관없는 것(생김새·옷·키·이름)으로 마음을 짐작하거나, 까닭 없이 「그냥」 짐작한다','말·행동·표정·상황 가운데 무엇을 보고 알았는지 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X02','kor',2,'u5',ARRAY['K2-1-u5-C1','K2-1-u5-C3']::text[],'말·행동·표정이 보여 주는 마음을 거꾸로 읽는다(고개를 푹 숙임 → 신남, 두 손을 번쩍 → 속상함)','그 행동을 직접 따라 해 보며 어떤 기분이 드는지 느끼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X03','kor',2,'u5',ARRAY['K2-1-u5-C4']::text[],'인물이 놓인 상황을 살피지 않고 엉뚱한 마음을 고른다(기다리던 소풍 날 비가 옴 → 신남)','「무슨 일이 있었지?」 먼저 말해 보고 마음 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X04','kor',2,'u5',ARRAY['K2-1-u5-C4','K2-1-u5-C1']::text[],'인물 대신 지금 내 기분대로 짐작하거나, 같은 일이면 누구나 똑같은 마음이라고 여긴다(형과 동생 마음을 바꿔 앎)','「그 자리에 있는 사람은 누구지? 그 사람이라면?」 하고 사람마다 나눠 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X05','kor',2,'u5',ARRAY['K2-1-u5-C5','K2-1-u5-C10']::text[],'마음을 나타내지 않는 낱말(책상·운동장·연필·달리다)을 마음 말로 여긴다','「나는 지금 ○○해.」에 넣어 말이 되는지 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X06','kor',2,'u5',ARRAY['K2-1-u5-C5','K2-1-u5-C10']::text[],'마음 말의 뜻을 바꿔 알거나 상황에 맞지 않는 마음 말을 쓴다(소풍 전날 → 서운하다, 약속을 어김 → 설레다)','그 마음 말이 드는 때를 하나 떠올려 보고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X07','kor',2,'u5',ARRAY['K2-1-u5-C6','K2-1-u5-C3']::text[],'인물의 마음이 처음부터 끝까지 그대로라고 여기거나, 마음이 바뀐 차례를 뒤바꾼다','「처음 → 무슨 일 → 나중」 세 칸에 마음을 하나씩 적어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X08','kor',2,'u5',ARRAY['K2-1-u5-C3','K2-1-u5-C6']::text[],'글에 없는 내용을 있다고 하거나 글의 내용을 놓친다','글에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X09','kor',2,'u5',ARRAY['K2-1-u5-C7']::text[],'소리가 같으면 뜻을 생각하지 않고 아무 낱말이나·소리 나는 대로 쓴다(텃밭에 걸음을 주다, 수업을 맞혔다, 무릎을 닫혔다, 반듯이 숙제를 하다)','문장의 뜻을 말로 풀어 보고(「꼭」이야? 「곧게」야?) 낱말 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X10','kor',2,'u5',ARRAY['K2-1-u5-C7']::text[],'뜻이 헷갈리는 낱말을 바꿔 쓴다(가르치다↔가리키다, 다르다↔틀리다, 잊다↔잃다, 바라다↔바래다)','낱말 짝의 뜻을 하나씩 말해 보고 문장에 넣어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X11','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C8']::text[],'낱말마다·한 글자씩 뚝뚝 끊어 읽어 뜻이 드러나지 않는다(토 / 끼 / 가 / 풀밭에서)','뜻이 이어지는 말끼리 손으로 묶어 보고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X12','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C8']::text[],'쉬지 않고 붙여 읽거나 빨리 읽기만 하면 잘 읽은 것이라 여긴다(숨이 차고 뜻을 알기 어려움)','「누가(무엇이)」 뒤에서 한 번 숨 쉬기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X13','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C8']::text[],'엉뚱한 곳에서 끊어 읽어 뜻이 바뀌게 한다(아빠가방에 / 들어가신다, 나물 / 좀 주세요 ↔ 나 / 물 좀 주세요)','끊어 읽은 대로 그림을 떠올려 보고 뜻이 맞는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X14','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C8']::text[],'쉬는 길이를 가리지 못한다(문장과 문장 사이에서 더 길게 쉬지 않음, 「/」에서 쉬지 않음)','「/」 한 번 숨, 문장이 끝나면 한 번 더 — 손뼉으로 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X15','kor',2,'u5',ARRAY['K2-1-u5-C9']::text[],'인물의 마음과 맞지 않는 목소리로 읽거나 모든 장면을 한 가지 목소리로 읽는다(슬픈 장면을 신나게)','「지금 인물은 어떤 마음이지?」 먼저 말하고 목소리 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X16','kor',2,'u5',ARRAY['K2-1-u5-C10']::text[],'마음을 뭉뚱그린 말·마음이 담기지 않은 말로 전하거나(「기분 나빠」·「몰라, 됐어」), 친구의 마음을 헤아리지 않고 대꾸한다(놀리기·탓하기·딴소리)','「내가 그 말을 들으면 어떤 마음일까?」 떠올리고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X17','kor',2,'u5',ARRAY['K2-1-u5-C1','K2-1-u5-C3','K2-1-u5-C4','K2-1-u5-C5','K2-1-u5-C6','K2-1-u5-C7','K2-1-u5-C8','K2-1-u5-C9','K2-1-u5-C10']::text[],'묻는 말을 거꾸로 읽는다 — 잘못↔바르게, 알맞지 않은↔알맞은, 어색한↔자연스러운','물음의 「잘못·않은·어색한」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#1','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',1,'mc','auto','다른 사람의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X01']::text[],true,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"다른 사람의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"말 · 행동 · 표정 · 상황","correct":true},{"t":"옷 색깔 · 키 · 신발","mis":"K2-1-u5-X01"},{"t":"이름 · 나이 · 머리 모양","mis":"K2-1-u5-X01"}],"explanation":["마음은 말·행동·표정·상황에서 드러나요.","옷 색깔이나 이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어 말해요."],"variant_rule":{"alt":[{"stem":"다른 사람의 마음을 짐작하는 것을 바르게 말한 것은 어느 것인가요?","options":[{"t":"말과 행동, 표정을 보고 어떤 마음인지 헤아리는 것","correct":true},{"t":"얼굴 생김새를 보고 이름을 맞히는 것","mis":"K2-1-u5-X01"},{"t":"그 사람의 키를 재어 보는 것","mis":"K2-1-u5-X01"}],"explanation":["마음 짐작은 말·행동·표정·상황을 보고 마음을 헤아리는 거예요.","생김새나 키는 마음과 상관없어요.","마음을 헤아리면 친구를 더 잘 이해할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#2','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',1,'mc','auto','친구가 활짝 웃으며 깡충깡충 뛰고 있어요. 친구는 어떤 마음일까요?',ARRAY['K2-1-u5-X02']::text[],true,'{"seq":2,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"친구가 활짝 웃으며 깡충깡충 뛰고 있어요. 친구는 어떤 마음일까요?","options":[{"t":"기쁜 마음","correct":true},{"t":"속상한 마음","mis":"K2-1-u5-X02"},{"t":"무서운 마음","mis":"K2-1-u5-X02"}],"explanation":["활짝 웃으며 뛰는 모습에서 기쁜 마음이 드러나요.","속상하거나 무서우면 웃으며 뛰지 않아요.","표정과 행동을 보고 마음을 짐작해요."],"variant_rule":{"alt":[{"stem":"친구가 넘어져서 고개를 푹 숙이고 있어요. 친구는 어떤 마음일까요?","options":[{"t":"아프고 속상한 마음","correct":true},{"t":"신나고 즐거운 마음","mis":"K2-1-u5-X02"},{"t":"뿌듯하고 자랑스러운 마음","mis":"K2-1-u5-X02"}],"explanation":["넘어져서 고개를 숙인 모습에서 아프고 속상한 마음이 드러나요.","신나거나 뿌듯하면 고개를 숙이지 않아요.","표정과 행동을 보고 마음을 짐작해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#3','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],true,'{"seq":3,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「동생이 / 우유를 / 마신다」","correct":true},{"t":"「동 / 생이우 / 유를 마신다」","mis":"K2-1-u5-X11"},{"t":"「동생이우유를마신다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「하늘에 / 무지개가 / 떴다」","correct":true},{"t":"「하 / 늘에무 / 지개가 떴다」","mis":"K2-1-u5-X11"},{"t":"「하늘에무지개가떴다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#4','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C2',1,'ox','auto','문장을 쉬지 않고 붙여 읽으면 뜻이 더 잘 드러나요.',ARRAY['K2-1-u5-X12']::text[],true,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"ox","stem":"문장을 쉬지 않고 붙여 읽으면 뜻이 더 잘 드러나요.","answer":"X","reason_options":[{"t":"뜻이 통하는 덩어리로 쉬어 읽어야 뜻이 잘 드러나니까","correct":true},{"t":"빨리 읽어야 잘 읽은 것이니까","mis":"K2-1-u5-X12"}],"mis":"K2-1-u5-X12","explanation":["붙여 읽으면 듣는 사람이 뜻을 알기 어려워요.","뜻이 통하는 덩어리로 쉬어 읽어요.","빨리 읽는 것과 잘 읽는 것은 달라요."],"variant_rule":{"alt":[{"stem":"「누가(무엇이)」에 해당하는 말 뒤에서 조금 쉬어 읽으면 뜻이 잘 드러나요.","answer":"O","reason_options":[{"t":"「동생이 / 우유를 마신다」처럼 뜻 덩어리가 나뉘니까","correct":true},{"t":"쉬지 않고 읽어야 뜻이 드러나니까","mis":"K2-1-u5-X12"}],"explanation":["「누가(무엇이)」 뒤에서 쉬면 뜻 덩어리가 나뉘어요.","듣는 사람이 뜻을 잘 알아들어요.","쉬지 않으면 숨이 차고 알아듣기 어려워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#5','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"생일 선물을 받았을 때","r":"기쁘다"},{"l":"아끼던 장난감이 부서졌을 때","r":"속상하다"},{"l":"내일 소풍을 가기로 했을 때","r":"설레다"}],"mis":"K2-1-u5-X03","explanation":["선물을 받으면 기쁜 마음이 들어요.","아끼던 장난감이 부서지면 속상해요.","내일 소풍을 간다면 설레는 마음이 들어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"친구가 넘어진 나를 일으켜 주었을 때","r":"고맙다"},{"l":"내가 친구 발을 밟았을 때","r":"미안하다"},{"l":"발표 차례를 기다릴 때","r":"떨리다"}],"explanation":["도움을 받으면 고마운 마음이 들어요.","친구 발을 밟으면 미안한 마음이 들어요.","발표 차례를 기다리면 떨리는 마음이 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#6','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C5',2,'mc','auto','마음을 나타내는 말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],true,'{"seq":6,"concept":"K2-1-u5-C5","difficulty":2,"kind":"mc","stem":"마음을 나타내는 말만 모은 것은 어느 것인가요?","options":[{"t":"기쁘다 · 설레다 · 고맙다","correct":true},{"t":"기쁘다 · 책상 · 고맙다","mis":"K2-1-u5-X05"},{"t":"운동장 · 연필 · 의자","mis":"K2-1-u5-X05"}],"explanation":["「기쁘다」·「설레다」·「고맙다」는 모두 마음을 나타내요.","「책상」·「운동장」·「연필」·「의자」는 물건이나 장소의 이름이에요.","「나는 지금 ○○해.」에 넣어 말이 되는지 해 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 마음을 나타내는 말만 모은 것은 어느 것인가요?","options":[{"t":"속상하다 · 뿌듯하다 · 미안하다","correct":true},{"t":"속상하다 · 달리다 · 미안하다","mis":"K2-1-u5-X05"},{"t":"가방 · 학교 · 칠판","mis":"K2-1-u5-X05"}],"explanation":["「속상하다」·「뿌듯하다」·「미안하다」는 모두 마음을 나타내요.","「달리다」는 움직임, 「가방」·「학교」·「칠판」은 물건이나 장소예요.","「나는 지금 ○○해.」에 넣어 말이 되는지 해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#7','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C4',2,'mc','auto','누나가 정성껏 그린 그림에 동생이 실수로 물을 엎질렀어요. 누나는 어떤 마음일까요?',ARRAY['K2-1-u5-X03']::text[],true,'{"seq":7,"concept":"K2-1-u5-C4","difficulty":2,"kind":"mc","stem":"누나가 정성껏 그린 그림에 동생이 실수로 물을 엎질렀어요. 누나는 어떤 마음일까요?","options":[{"t":"속상한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u5-X03"},{"t":"졸린 마음","mis":"K2-1-u5-X03"}],"explanation":["정성껏 그린 그림이 젖으면 속상한 마음이 들어요.","신나거나 졸린 마음은 이 상황과 맞지 않아요.","무슨 일이 있었는지 먼저 살펴요."],"variant_rule":{"alt":[{"stem":"기다리던 현장 체험학습 날 아침이에요. 가방을 메고 집을 나서는 친구는 어떤 마음일까요?","options":[{"t":"설레고 신나는 마음","correct":true},{"t":"서운하고 슬픈 마음","mis":"K2-1-u5-X03"},{"t":"미안하고 부끄러운 마음","mis":"K2-1-u5-X03"}],"explanation":["기다리던 날이 오면 설레고 신나는 마음이 들어요.","서운하거나 미안한 마음은 이 상황과 맞지 않아요.","무슨 일이 있었는지 먼저 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#8','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C2',2,'sa','auto','「아빠가방에들어가신다」를 「아빠가 / 방에 / 들어가신다」로 띄어 읽었어요. 아빠가 들어가신 곳은 어디인가요? 한 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C2","difficulty":2,"kind":"sa","stem":"「아빠가방에들어가신다」를 「아빠가 / 방에 / 들어가신다」로 띄어 읽었어요. 아빠가 들어가신 곳은 어디인가요? 한 글자로 써 보세요.","answer":["방"],"explanation":["「아빠가 / 방에」로 띄어 읽으면 아빠가 방에 들어가신 거예요.","「아빠 / 가방에」로 끊으면 가방에 들어가는 뜻이 돼요.","어디에서 쉬느냐에 따라 뜻이 달라져요."],"variant_rule":{"alt":[{"stem":"「나물 좀 주세요」를 「나물 / 좀 주세요」로 띄어 읽었어요. 달라고 한 것은 무엇인가요? 두 글자로 써 보세요.","answer":["나물"],"explanation":["「나물 / 좀 주세요」는 나물을 달라는 뜻이에요.","「나 / 물 좀 주세요」로 끊으면 물을 달라는 뜻이 돼요.","어디에서 쉬느냐에 따라 뜻이 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#9','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',2,'mc','auto','다른 사람의 마음을 짐작하면 어떤 점이 좋을까요?',ARRAY['K2-1-u5-X01','K2-1-u5-X04']::text[],true,'{"seq":9,"concept":"K2-1-u5-C1","difficulty":2,"kind":"mc","stem":"다른 사람의 마음을 짐작하면 어떤 점이 좋을까요?","options":[{"t":"친구를 더 잘 이해하고 배려할 수 있어요","correct":true},{"t":"친구의 키를 알 수 있어요","mis":"K2-1-u5-X01"},{"t":"친구 마음과 상관없이 내 마음대로 해도 돼요","mis":"K2-1-u5-X04"}],"explanation":["마음을 헤아리면 친구를 이해하고 배려할 수 있어요.","키는 마음과 상관없어요.","내 마음대로가 아니라 친구 마음을 생각해요."],"variant_rule":{"alt":[{"stem":"말하지 않아도 친구의 마음을 알 수 있는 까닭은 무엇인가요?","options":[{"t":"표정과 행동에 마음이 드러나니까","correct":true},{"t":"친구의 옷에 마음이 쓰여 있으니까","mis":"K2-1-u5-X01"},{"t":"누구나 언제나 나와 같은 마음이니까","mis":"K2-1-u5-X04"}],"explanation":["웃는 얼굴, 숙인 고개처럼 표정과 행동에 마음이 드러나요.","옷에 마음이 쓰여 있지 않아요.","사람마다 마음이 다를 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#10','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',3,'error','auto','「상을 받고 두 손을 번쩍 들었어요.」를 읽고 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C1","difficulty":3,"kind":"error","stem":"「상을 받고 두 손을 번쩍 들었어요.」를 읽고 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"시우 — 「부끄럽고 미안한 마음이야.」","correct":true,"mis_target":"K2-1-u5-X02"},{"t":"다은 — 「기쁜 마음이야.」","mis":"K2-1-u5-X17"},{"t":"로아 — 「뿌듯한 마음이야.」","mis":"K2-1-u5-X17"}],"explanation":["두 손을 번쩍 드는 행동은 기쁘고 뿌듯한 마음을 보여 줘요.","부끄럽고 미안하면 고개를 숙이거나 얼굴을 가려요.","다은이와 로아는 알맞게 짐작했어요."],"variant_rule":{"alt":[{"stem":"「친구가 다가오자 빙긋 웃었어요.」를 읽고 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"준우 — 「화가 나서 싫은 마음이야.」","correct":true,"mis_target":"K2-1-u5-X02"},{"t":"하린 — 「반가운 마음이야.」","mis":"K2-1-u5-X17"},{"t":"지안 — 「좋은 마음이야.」","mis":"K2-1-u5-X17"}],"explanation":["빙긋 웃는 표정은 반갑고 좋은 마음을 보여 줘요.","화가 나면 얼굴을 찡그리거나 돌아서요.","하린이와 지안이는 알맞게 짐작했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#1','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C4',2,'mc','auto','언니가 쌓은 블록 탑을 동생이 실수로 무너뜨렸어요. 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":1,"concept":"K2-1-u5-C4","difficulty":2,"kind":"mc","stem":"언니가 쌓은 블록 탑을 동생이 실수로 무너뜨렸어요. 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"언니는 속상하고, 동생은 미안해요","correct":true},{"t":"언니는 미안하고, 동생은 속상해요","mis":"K2-1-u5-X04"},{"t":"언니는 신나고, 동생은 뿌듯해요","mis":"K2-1-u5-X03"}],"explanation":["탑이 무너진 언니는 속상하고, 무너뜨린 동생은 미안할 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#2','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',2,'mc','auto','문장을 띄어 읽을 때 쉬어 읽기 좋은 곳은 어디인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":2,"concept":"K2-1-u5-C2","difficulty":2,"kind":"mc","stem":"문장을 띄어 읽을 때 쉬어 읽기 좋은 곳은 어디인가요?","options":[{"t":"「누가(무엇이)」에 해당하는 말 뒤","correct":true},{"t":"낱말의 한가운데","mis":"K2-1-u5-X11"},{"t":"아무 곳이나 숨이 찰 때","mis":"K2-1-u5-X13"}],"explanation":["「동생이 / 우유를 마신다」처럼 「누가」 뒤에서 쉬어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","아무 데서나 쉬면 뜻이 바뀔 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#3','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',3,'mc','auto','물을 달라는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X13','K2-1-u5-X12']::text[],false,'{"seq":3,"concept":"K2-1-u5-C2","difficulty":3,"kind":"mc","stem":"물을 달라는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「나 / 물 좀 주세요」","correct":true},{"t":"「나물 / 좀 주세요」","mis":"K2-1-u5-X13"},{"t":"「나물좀주세요」","mis":"K2-1-u5-X12"}],"explanation":["「나 / 물 좀 주세요」로 읽어야 물을 달라는 뜻이 돼요.","「나물 / 좀 주세요」는 나물을 달라는 뜻이에요.","띄어 읽는 곳에 따라 뜻이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#4','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C1',3,'error','auto','「친구가 다가오자 빙긋 웃었어요.」를 읽고 마음을 짐작한 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X01','K2-1-u5-X17']::text[],false,'{"seq":4,"concept":"K2-1-u5-C1","difficulty":3,"kind":"error","stem":"「친구가 다가오자 빙긋 웃었어요.」를 읽고 마음을 짐작한 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「그냥 화난 것 같아. 까닭은 없어.」","correct":true,"mis_target":"K2-1-u5-X01"},{"t":"예린 — 「빙긋 웃었으니 반가운 마음이야.」","mis":"K2-1-u5-X17"},{"t":"하늘 — 「친구가 다가와서 좋은 마음이야.」","mis":"K2-1-u5-X17"}],"explanation":["마음을 짐작할 때는 표정·행동 같은 까닭을 들어야 해요.","빙긋 웃는 표정은 화난 마음이 아니에요.","예린이와 하늘이는 까닭을 들어 알맞게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#5','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C4',3,'ox','auto','「소풍 가는 날 아침에 비가 내려 소풍이 미뤄졌어요.」 소풍을 기다리던 친구는 신나고 기쁜 마음일 거예요.',ARRAY['K2-1-u5-X03']::text[],false,'{"seq":5,"concept":"K2-1-u5-C4","difficulty":3,"kind":"ox","stem":"「소풍 가는 날 아침에 비가 내려 소풍이 미뤄졌어요.」 소풍을 기다리던 친구는 신나고 기쁜 마음일 거예요.","answer":"X","reason_options":[{"t":"기다리던 소풍을 못 가게 되어 아쉽고 속상할 테니까","correct":true},{"t":"비가 오면 누구나 신나니까","mis":"K2-1-u5-X03"}],"mis":"K2-1-u5-X03","explanation":["기다리던 소풍이 미뤄지면 아쉽고 속상해요.","상황을 살피면 마음을 짐작할 수 있어요.","무슨 일이 있었는지 먼저 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#6','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C5',3,'mc','auto','「아끼던 필통을 잃어버렸어요.」에 어울리는 마음 말은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":6,"concept":"K2-1-u5-C5","difficulty":3,"kind":"mc","stem":"「아끼던 필통을 잃어버렸어요.」에 어울리는 마음 말은 어느 것인가요?","options":[{"t":"속상하다","correct":true},{"t":"설레다","mis":"K2-1-u5-X06"},{"t":"뿌듯하다","mis":"K2-1-u5-X06"}],"explanation":["아끼던 물건을 잃어버리면 속상한 마음이 들어요.","「설레다」는 기대될 때, 「뿌듯하다」는 해냈을 때의 마음이에요.","그 마음 말이 드는 때를 떠올려 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#7','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',3,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X13','K2-1-u5-X11']::text[],false,'{"seq":7,"concept":"K2-1-u5-C2","difficulty":3,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「키가 큰 기린이 / 높은 나뭇잎을 / 먹어요」","correct":true},{"t":"「키가 큰기 / 린이높은 / 나뭇잎을 먹어요」","mis":"K2-1-u5-X13"},{"t":"「키 / 가 / 큰 / 기 / 린이 / 높은 / 나뭇잎을」","mis":"K2-1-u5-X11"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","「큰기 / 린이」처럼 끊으면 뜻이 흐려져요.","한 글자씩 끊으면 뜻이 드러나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#8','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C1',4,'mc','auto','다른 사람의 마음을 짐작하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X01','K2-1-u5-X04']::text[],false,'{"seq":8,"concept":"K2-1-u5-C1","difficulty":4,"kind":"mc","stem":"다른 사람의 마음을 짐작하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말·행동·상황을 살피고, 내가 그 자리라면 어떨지 떠올려요","correct":true},{"t":"그 사람의 생김새만 보고 정해요","mis":"K2-1-u5-X01"},{"t":"지금 내 기분과 똑같다고 정해요","mis":"K2-1-u5-X04"}],"explanation":["말·행동·상황을 살피고 나라면 어떨지 견주어 봐요.","생김새는 마음을 알려 주지 않아요.","내 기분이 아니라 그 사람의 자리에서 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#9','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C1',4,'essay','teacher','가족이나 친구의 마음을 짐작해 본 일을 떠올려, 무엇을 보고 어떤 마음이라고 짐작했는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C1","difficulty":4,"kind":"essay","stem":"가족이나 친구의 마음을 짐작해 본 일을 떠올려, 무엇을 보고 어떤 마음이라고 짐작했는지 써 보세요.","answer_guide":{"answer":"예: 동생이 받아쓰기 공책을 가방에 넣고 고개를 숙이고 있었어요. 그걸 보고 받아쓰기를 잘 못 봐서 속상한 마음이라고 짐작했어요.","scoring_points":["누구의 마음을 짐작했는지 썼는가","무엇(말·행동·표정·상황)을 보고 짐작했는지 썼는가","짐작한 마음을 마음 말로 썼는가"]},"explanation":["누구의 마음.","짐작한 까닭.","마음 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#10','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',4,'essay','teacher','「아기다람쥐가나무에올라가요」를 낱말을 띄어 바르게 옮겨 쓰고, 뜻이 잘 드러나게 띄어 읽을 곳에 「/」를 넣어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C2","difficulty":4,"kind":"essay","stem":"「아기다람쥐가나무에올라가요」를 낱말을 띄어 바르게 옮겨 쓰고, 뜻이 잘 드러나게 띄어 읽을 곳에 「/」를 넣어 써 보세요.","answer_guide":{"answer":"예: 아기 다람쥐가 나무에 올라가요. → 아기 다람쥐가 / 나무에 올라가요.","scoring_points":["낱말 사이를 띄어 바르게 옮겨 썼는가","「누가(무엇이)」 뒤처럼 알맞은 곳에 「/」를 넣었는가","낱말 가운데를 끊지 않았는가"]},"explanation":["바르게 옮겨 쓰기.","알맞은 곳에 「/」.","뜻 덩어리 지키기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#1','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',1,'mc','auto','글을 읽고 답해 보세요. 서준이가 「와, 해냈다!」 하며 손뼉을 쳤을 때의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],true,'{"seq":1,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이가 「와, 해냈다!」 하며 손뼉을 쳤을 때의 마음은 어느 것인가요?","options":[{"t":"기쁘고 뿌듯한 마음","correct":true},{"t":"슬프고 외로운 마음","mis":"K2-1-u5-X02"},{"t":"무섭고 떨리는 마음","mis":"K2-1-u5-X02"}],"explanation":["「와, 해냈다!」라는 말과 손뼉을 치는 행동에서 기쁘고 뿌듯한 마음이 드러나요.","슬프거나 무서우면 손뼉을 치지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 동생이 고개를 숙이고 「언니, 미안해.」 했을 때 동생의 마음은 어느 것인가요?","options":[{"t":"미안한 마음","correct":true},{"t":"뿌듯한 마음","mis":"K2-1-u5-X02"},{"t":"신나는 마음","mis":"K2-1-u5-X02"}],"explanation":["고개를 숙이고 「미안해.」라고 한 말과 행동에서 미안한 마음이 드러나요.","뿌듯하거나 신나면 고개를 숙이지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#2','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',1,'mc','auto','글을 읽고 답해 보세요. 비행기가 바닥에 툭 떨어지자 서준이는 입술을 삐죽 내밀었어요. 이때 서준이의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],true,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 비행기가 바닥에 툭 떨어지자 서준이는 입술을 삐죽 내밀었어요. 이때 서준이의 마음은 어느 것인가요?","options":[{"t":"속상한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u5-X02"},{"t":"고마운 마음","mis":"K2-1-u5-X02"}],"explanation":["입술을 삐죽 내미는 행동에서 속상한 마음이 드러나요.","신나거나 고마우면 입술을 삐죽 내밀지 않아요.","행동을 따라 해 보며 마음을 느껴요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 카드에 우유가 쏟아지자 지우는 눈물이 핑 돌았어요. 이때 지우의 마음은 어느 것인가요?","options":[{"t":"속상한 마음","correct":true},{"t":"설레는 마음","mis":"K2-1-u5-X02"},{"t":"뿌듯한 마음","mis":"K2-1-u5-X02"}],"explanation":["눈물이 핑 도는 모습에서 속상한 마음이 드러나요.","설레거나 뿌듯하면 눈물이 핑 돌지 않아요.","행동을 따라 해 보며 마음을 느껴요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#3','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',1,'ox','auto','글 속 인물의 마음은 인물의 말과 행동을 보고 짐작할 수 있어요.',ARRAY['K2-1-u5-X01']::text[],true,'{"seq":3,"concept":"K2-1-u5-C3","difficulty":1,"kind":"ox","stem":"글 속 인물의 마음은 인물의 말과 행동을 보고 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"마음이 말과 행동에 드러나니까","correct":true},{"t":"인물의 마음은 생김새로만 알 수 있으니까","mis":"K2-1-u5-X01"}],"mis":"K2-1-u5-X01","explanation":["「드디어 됐다!」 같은 말이나 두 손을 번쩍 드는 행동에 마음이 드러나요.","생김새는 마음을 알려 주지 않아요.","마음이 드러난 말과 행동을 찾아요."],"variant_rule":{"alt":[{"stem":"고개를 푹 숙이고 작은 목소리로 「미안해.」라고 했다면 신나는 마음이에요.","answer":"X","reason_options":[{"t":"고개를 숙이고 작게 말하는 것은 미안한 마음을 보여 주니까","correct":true},{"t":"작은 목소리는 언제나 신난다는 뜻이니까","mis":"K2-1-u5-X02"}],"explanation":["고개를 푹 숙이고 작게 「미안해.」 하면 미안한 마음이에요.","행동이 보여 주는 마음을 거꾸로 읽으면 안 돼요.","행동을 따라 해 보며 마음을 느껴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#4','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],true,'{"seq":4,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"연필","mis":"K2-1-u5-X05"},{"t":"운동장","mis":"K2-1-u5-X05"}],"explanation":["「설레다」는 기대되어 두근거리는 마음을 나타내요.","「연필」은 물건, 「운동장」은 장소예요.","「나는 지금 ○○해.」에 넣어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 마음을 나타내는 말은 어느 것인가요?","options":[{"t":"뿌듯하다","correct":true},{"t":"의자","mis":"K2-1-u5-X05"},{"t":"달리다","mis":"K2-1-u5-X05"}],"explanation":["「뿌듯하다」는 무언가를 해냈을 때의 마음을 나타내요.","「의자」는 물건, 「달리다」는 움직임이에요.","「나는 지금 ○○해.」에 넣어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#5','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',2,'match','auto','인물의 말이나 행동과 어울리는 마음을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C3","difficulty":2,"kind":"match","stem":"인물의 말이나 행동과 어울리는 마음을 이어 보세요.","pairs":[{"l":"「드디어 됐다!」 하며 두 손을 번쩍 들었어요","r":"기쁘다"},{"l":"고개를 푹 숙이고 「미안해.」 했어요","r":"미안하다"},{"l":"눈을 동그랗게 뜨고 「와, 진짜?」 했어요","r":"놀라다"}],"mis":"K2-1-u5-X02","explanation":["두 손을 번쩍 드는 행동은 기쁜 마음이에요.","고개를 숙이고 「미안해.」 하면 미안한 마음이에요.","눈을 동그랗게 뜨고 「와, 진짜?」 하면 놀란 마음이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 인물의 말이나 행동과 어울리는 마음을 이어 보세요.","pairs":[{"l":"「고마워!」 하며 친구를 꼭 안았어요","r":"고맙다"},{"l":"주먹을 꽉 쥐고 「나 아니야!」 했어요","r":"억울하다"},{"l":"혼자 앉아 창밖만 보았어요","r":"외롭다"}],"explanation":["「고마워!」 하며 안는 행동은 고마운 마음이에요.","「나 아니야!」 하며 주먹을 쥐면 억울한 마음이에요.","혼자 창밖만 보면 외로운 마음일 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#6','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C4',2,'mc','auto','「내일 현장 체험학습을 가요.」 이 상황에 어울리는 마음 말은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],true,'{"seq":6,"concept":"K2-1-u5-C4","difficulty":2,"kind":"mc","stem":"「내일 현장 체험학습을 가요.」 이 상황에 어울리는 마음 말은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"서운하다","mis":"K2-1-u5-X06"},{"t":"미안하다","mis":"K2-1-u5-X06"}],"explanation":["기다리던 일을 앞두면 설레는 마음이 들어요.","서운하거나 미안한 마음은 이 상황과 맞지 않아요.","그 마음이 드는 때를 떠올려 견주어요."],"variant_rule":{"alt":[{"stem":"「친구가 내 부탁을 들어주지 않았어요.」 이 상황에 어울리는 마음 말은 어느 것인가요?","options":[{"t":"서운하다","correct":true},{"t":"설레다","mis":"K2-1-u5-X06"},{"t":"뿌듯하다","mis":"K2-1-u5-X06"}],"explanation":["부탁을 들어주지 않으면 서운한 마음이 들어요.","설레거나 뿌듯한 마음은 이 상황과 맞지 않아요.","그 마음이 드는 때를 떠올려 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#7','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 서준이가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],true,'{"seq":7,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"입술을 삐죽 내밀었어요","correct":true},{"t":"「와, 해냈다!」 하며 손뼉을 쳤어요","mis":"K2-1-u5-X02"},{"t":"비행기가 교실 끝까지 날아갔어요","mis":"K2-1-u5-X08"}],"explanation":["입술을 삐죽 내미는 행동에 속상한 마음이 드러나요.","손뼉을 친 것은 기쁜 마음이 드러난 부분이에요.","비행기가 날아간 것은 일어난 일이지 마음이 드러난 행동이 아니에요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 지우가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"눈물이 핑 돌았어요","correct":true},{"t":"할머니가 활짝 웃으셨어요","mis":"K2-1-u5-X02"},{"t":"할머니 생신 선물로 카드를 만들었어요","mis":"K2-1-u5-X08"}],"explanation":["눈물이 핑 도는 모습에 속상한 마음이 드러나요.","할머니가 웃으신 것은 기쁜 장면이에요.","카드를 만든 것은 일어난 일이에요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#8','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C5',2,'sa','auto','「줄넘기를 처음으로 백 번 넘었어요. 두 팔을 번쩍 들었어요.」 이때의 마음을 나타내는 말을 하나 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C5","difficulty":2,"kind":"sa","stem":"「줄넘기를 처음으로 백 번 넘었어요. 두 팔을 번쩍 들었어요.」 이때의 마음을 나타내는 말을 하나 써 보세요.","answer":["기쁘다","기뻐요","기쁜","뿌듯하다","뿌듯해요","뿌듯한","신나다","신나요","신나는","자랑스럽다","자랑스러워요","자랑스러운"],"explanation":["처음 해낸 일에 두 팔을 번쩍 들었으니 기쁘고 뿌듯한 마음이에요.","「뿌듯하다」·「자랑스럽다」처럼 써도 좋아요.","행동을 보고 마음 말을 골라요."],"variant_rule":{"alt":[{"stem":"「아끼던 인형을 잃어버렸어요. 어깨가 축 처졌어요.」 이때의 마음을 나타내는 말을 하나 써 보세요.","answer":["속상하다","속상해요","속상한","슬프다","슬퍼요","슬픈","아쉽다","아쉬워요","서운하다","서운해요"],"explanation":["아끼던 인형을 잃어버리고 어깨가 처졌으니 속상하고 슬픈 마음이에요.","「슬프다」처럼 써도 좋아요.","상황과 행동을 보고 마음 말을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#9','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C4',2,'mc','auto','인물의 마음을 더 잘 짐작하려면 어떻게 하면 좋을까요?',ARRAY['K2-1-u5-X01','K2-1-u5-X04']::text[],true,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"mc","stem":"인물의 마음을 더 잘 짐작하려면 어떻게 하면 좋을까요?","options":[{"t":"「나라면 어떤 마음일까?」 비슷한 경험과 견주어 봐요","correct":true},{"t":"인물의 이름만 기억해요","mis":"K2-1-u5-X01"},{"t":"지금 내 기분대로 정해요","mis":"K2-1-u5-X04"}],"explanation":["비슷한 경험을 떠올리면 인물의 마음이 더 생생해져요.","이름만으로는 마음을 알 수 없어요.","지금 내 기분이 아니라 인물의 자리에서 생각해요."],"variant_rule":{"alt":[{"stem":"나도 무언가를 처음 해낸 적이 있다면, 인물의 마음을 짐작할 때 어떻게 하면 좋을까요?","options":[{"t":"그때 내 마음을 떠올려 인물의 마음과 견주어 봐요","correct":true},{"t":"내 경험은 생각하지 않아요","mis":"K2-1-u5-X04"},{"t":"인물의 옷차림을 살펴봐요","mis":"K2-1-u5-X01"}],"explanation":["비슷한 경험을 떠올리면 인물의 마음이 더 잘 느껴져요.","내 경험을 견주면 짐작이 쉬워요.","옷차림은 마음을 알려 주지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#10','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',3,'error','auto','글을 읽고 서준이의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C3","difficulty":3,"kind":"error","stem":"글을 읽고 서준이의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"민호 — 「비행기가 교실 끝까지 날아갔을 때 서준이는 속상했을 거야.」","correct":true,"mis_target":"K2-1-u5-X02"},{"t":"소율 — 「바닥에 떨어질 때는 속상했을 거야.」","mis":"K2-1-u5-X17"},{"t":"지후 — 「손뼉을 칠 때는 뿌듯했을 거야.」","mis":"K2-1-u5-X17"}],"explanation":["비행기가 끝까지 날아갔을 때 서준이는 「와, 해냈다!」 하며 기뻐했어요.","속상했던 것은 비행기가 바닥에 떨어질 때예요.","소율이와 지후는 알맞게 짐작했어요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"},"variant_rule":{"alt":[{"stem":"글을 읽고 지우의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"서아 — 「할머니가 활짝 웃으셨을 때 지우는 서운했을 거야.」","correct":true,"mis_target":"K2-1-u5-X02"},{"t":"하준 — 「우유가 쏟아졌을 때는 속상했을 거야.」","mis":"K2-1-u5-X17"},{"t":"아린 — 「마지막에는 마음이 따뜻했을 거야.」","mis":"K2-1-u5-X17"}],"explanation":["할머니가 웃으셨을 때 지우는 마음이 따뜻해졌어요.","서운한 마음은 글에 드러나지 않아요.","하준이와 아린이는 알맞게 짐작했어요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#1','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 할머니가 활짝 웃으셨을 때 지우의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":1,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 할머니가 활짝 웃으셨을 때 지우의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"따뜻하고 기쁜 마음","correct":true},{"t":"억울하고 화난 마음","mis":"K2-1-u5-X02"},{"t":"무섭고 떨리는 마음","mis":"K2-1-u5-X08"}],"explanation":["「지우는 마음이 따뜻해졌어요.」라고 했어요.","억울하거나 무서운 마음은 글에 없어요.","글에서 마음이 드러난 부분을 찾아요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#2','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C5',2,'mc','auto','「설레다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":2,"concept":"K2-1-u5-C5","difficulty":2,"kind":"mc","stem":"「설레다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞으로 일어날 일이 기대되어 가슴이 두근거리다","correct":true},{"t":"일이 뜻대로 되지 않아 마음이 상하다","mis":"K2-1-u5-X06"},{"t":"남에게 잘못하여 마음이 편하지 않다","mis":"K2-1-u5-X06"}],"explanation":["소풍 전날처럼 기대될 때 「설레다」를 써요.","마음이 상하는 것은 「속상하다」예요.","잘못해서 마음이 편하지 않은 것은 「미안하다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#3','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',3,'error','auto','상황과 마음을 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u5-X03','K2-1-u5-X17']::text[],false,'{"seq":3,"concept":"K2-1-u5-C4","difficulty":3,"kind":"error","stem":"상황과 마음을 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"태민 — 「친구가 약속을 잊어버렸어요 → 뿌듯하다」","correct":true,"mis_target":"K2-1-u5-X03"},{"t":"은솔 — 「오랫동안 기다린 일이 이루어졌어요 → 기쁘다」","mis":"K2-1-u5-X17"},{"t":"아린 — 「내일 좋아하는 곳에 가요 → 설레다」","mis":"K2-1-u5-X17"}],"explanation":["친구가 약속을 잊으면 서운한 마음이 들어요.","「뿌듯하다」는 무언가를 해냈을 때의 마음이에요.","은솔이와 아린이는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#4','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C3',3,'mc','auto','「괜찮아.」라고 말하면서 손으로 눈물을 훔쳤어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":4,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「괜찮아.」라고 말하면서 손으로 눈물을 훔쳤어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 괜찮다고 했지만 사실은 속상한 마음","correct":true},{"t":"말 그대로 정말 괜찮고 기쁜 마음","mis":"K2-1-u5-X02"},{"t":"졸리고 심심한 마음","mis":"K2-1-u5-X03"}],"explanation":["눈물을 훔치는 행동에서 속상한 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","졸리거나 심심한 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#5','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',3,'ox','auto','같은 일이 생겨도 사람마다 마음이 다를 수 있어요.',ARRAY['K2-1-u5-X04']::text[],false,'{"seq":5,"concept":"K2-1-u5-C4","difficulty":3,"kind":"ox","stem":"같은 일이 생겨도 사람마다 마음이 다를 수 있어요.","answer":"O","reason_options":[{"t":"겪은 일과 처지가 달라 느끼는 마음도 다를 수 있으니까","correct":true},{"t":"같은 일이면 누구나 똑같은 마음이니까","mis":"K2-1-u5-X04"}],"mis":"K2-1-u5-X04","explanation":["블록 탑이 무너지면 언니는 속상하고 동생은 미안할 수 있어요.","사람마다 처지가 달라요.","그래서 인물마다 나누어 마음을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#6','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C5',3,'mc','auto','서로 비슷한 마음을 나타내는 말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":6,"concept":"K2-1-u5-C5","difficulty":3,"kind":"mc","stem":"서로 비슷한 마음을 나타내는 말끼리 모은 것은 어느 것인가요?","options":[{"t":"기쁘다 · 즐겁다 · 신나다","correct":true},{"t":"기쁘다 · 속상하다 · 신나다","mis":"K2-1-u5-X06"},{"t":"슬프다 · 설레다 · 뿌듯하다","mis":"K2-1-u5-X06"}],"explanation":["「기쁘다」·「즐겁다」·「신나다」는 모두 좋은 일이 있을 때의 마음이에요.","「속상하다」·「슬프다」는 마음이 상할 때의 말이에요.","마음 말이 드는 때를 떠올려 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#7','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C3',3,'mc','auto','글을 읽고 답해 보세요. 서준이가 날개를 다시 반듯이 접어 힘껏 날린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X08']::text[],false,'{"seq":7,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이가 날개를 다시 반듯이 접어 힘껏 날린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"포기하지 않고 다시 해 보고 싶어서","correct":true},{"t":"종이비행기가 싫어져서","mis":"K2-1-u5-X08"},{"t":"친구가 시켜서","mis":"K2-1-u5-X08"}],"explanation":["비행기가 자꾸 떨어져도 다시 접어 날렸어요.","종이비행기가 싫었다면 다시 접지 않았을 거예요.","친구가 시켰다는 말은 글에 없어요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#8','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',4,'mc','auto','하윤이는 발표를 앞두고 손에 땀이 나고 목소리가 작아졌어요. 하윤이의 마음과 해 줄 말을 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":8,"concept":"K2-1-u5-C4","difficulty":4,"kind":"mc","stem":"하윤이는 발표를 앞두고 손에 땀이 나고 목소리가 작아졌어요. 하윤이의 마음과 해 줄 말을 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"떨리는 마음 — 「천천히 해도 괜찮아.」","correct":true},{"t":"신나는 마음 — 「더 크게 소리 질러!」","mis":"K2-1-u5-X02"},{"t":"화난 마음 — 「왜 화가 났어?」","mis":"K2-1-u5-X03"}],"explanation":["손에 땀이 나고 목소리가 작아지는 것은 떨리는 마음이에요.","떨리는 친구에게는 마음을 놓게 해 주는 말이 어울려요.","상황과 행동을 함께 살펴 마음을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#9','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C3',4,'essay','teacher','「종이비행기」에서 서준이의 마음을 두 가지 찾아 쓰고, 각각 어떤 말이나 행동을 보고 짐작했는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C3","difficulty":4,"kind":"essay","stem":"「종이비행기」에서 서준이의 마음을 두 가지 찾아 쓰고, 각각 어떤 말이나 행동을 보고 짐작했는지 써 보세요.","answer_guide":{"answer":"예: 속상한 마음 — 비행기가 떨어지자 입술을 삐죽 내밀었어요. 뿌듯한 마음 — 「와, 해냈다!」 하며 손뼉을 쳤어요.","scoring_points":["서준이의 마음을 두 가지 썼는가","마음마다 근거가 된 말이나 행동을 글에서 찾아 썼는가","마음을 마음 말로 알맞게 나타냈는가"]},"explanation":["마음 두 가지.","근거가 된 말·행동.","마음 말."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#10','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',4,'essay','teacher','무언가를 처음 해낸 경험을 떠올려 그때 내 마음을 마음 말로 쓰고, 서준이의 마음과 견주어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C4","difficulty":4,"kind":"essay","stem":"무언가를 처음 해낸 경험을 떠올려 그때 내 마음을 마음 말로 쓰고, 서준이의 마음과 견주어 써 보세요.","answer_guide":{"answer":"예: 처음으로 혼자 머리를 묶었을 때 정말 뿌듯했어요. 서준이도 비행기가 끝까지 날아갔을 때 나처럼 뿌듯했을 거예요.","scoring_points":["처음 해낸 경험을 썼는가","그때의 마음을 마음 말로 썼는가","서준이의 마음과 견주어 썼는가"]},"explanation":["나의 경험.","마음 말.","서준이와 견주기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#1','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'mc','auto','글을 읽고 답해 보세요. 처음 수영장 물을 보았을 때 지안이의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X02']::text[],true,'{"seq":1,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 처음 수영장 물을 보았을 때 지안이의 마음은 어느 것인가요?","options":[{"t":"무섭고 걱정되는 마음","correct":true},{"t":"신나고 들뜬 마음","mis":"K2-1-u5-X07"},{"t":"화나고 억울한 마음","mis":"K2-1-u5-X02"}],"explanation":["엄마 손을 꼭 잡고 「물이 너무 깊어 보여…….」라고 했어요.","신나는 마음은 나중에 물장구를 칠 때의 마음이에요.","장면마다 마음을 나누어 짐작해요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 무대 뒤에서 다리가 후들후들 떨릴 때 아기 곰의 마음은 어느 것인가요?","options":[{"t":"떨리고 걱정되는 마음","correct":true},{"t":"뿌듯하고 자랑스러운 마음","mis":"K2-1-u5-X07"},{"t":"졸리고 심심한 마음","mis":"K2-1-u5-X03"}],"explanation":["다리가 후들후들 떨리는 모습에서 떨리고 걱정되는 마음이 드러나요.","뿌듯한 마음은 나중에 북을 다 친 뒤의 마음이에요.","장면마다 마음을 나누어 짐작해요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#2','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'mc','auto','글을 읽고 답해 보세요. 첨벙첨벙 물장구를 치며 깔깔 웃을 때 지안이의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X02']::text[],true,'{"seq":2,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 첨벙첨벙 물장구를 치며 깔깔 웃을 때 지안이의 마음은 어느 것인가요?","options":[{"t":"즐겁고 신나는 마음","correct":true},{"t":"무섭고 걱정되는 마음","mis":"K2-1-u5-X07"},{"t":"서운하고 슬픈 마음","mis":"K2-1-u5-X02"}],"explanation":["깔깔 웃으며 물장구를 치는 모습에서 즐거운 마음이 드러나요.","무서운 마음은 처음 물을 보았을 때의 마음이에요.","마음은 시간이 지나며 바뀔 수 있어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 가슴을 쭉 펴고 환하게 웃을 때 아기 곰의 마음은 어느 것인가요?","options":[{"t":"뿌듯하고 기쁜 마음","correct":true},{"t":"떨리고 걱정되는 마음","mis":"K2-1-u5-X07"},{"t":"미안하고 부끄러운 마음","mis":"K2-1-u5-X02"}],"explanation":["가슴을 쭉 펴고 환하게 웃는 모습에서 뿌듯한 마음이 드러나요.","떨리는 마음은 무대 뒤에 있을 때의 마음이에요.","마음은 시간이 지나며 바뀔 수 있어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#3','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'ox','auto','글 속 인물의 마음은 처음부터 끝까지 늘 똑같아요.',ARRAY['K2-1-u5-X07']::text[],true,'{"seq":3,"concept":"K2-1-u5-C6","difficulty":1,"kind":"ox","stem":"글 속 인물의 마음은 처음부터 끝까지 늘 똑같아요.","answer":"X","reason_options":[{"t":"일이 일어나면 인물의 마음이 바뀔 수 있으니까","correct":true},{"t":"한 번 든 마음은 바뀌지 않으니까","mis":"K2-1-u5-X07"}],"mis":"K2-1-u5-X07","explanation":["지안이는 처음에 무서웠지만 나중에는 즐거워졌어요.","일이 일어난 차례에 따라 마음이 바뀌어요.","장면마다 마음을 짐작해요."],"variant_rule":{"alt":[{"stem":"시간이 지나며 일어난 일에 따라 인물의 마음이 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"친구가 다가와 주는 것 같은 일이 마음을 바꾸니까","correct":true},{"t":"인물의 마음은 처음 그대로이니까","mis":"K2-1-u5-X07"}],"explanation":["친구의 응원이나 도움 같은 일이 마음을 바꾸어요.","그래서 장면마다 마음을 살펴요.","처음 → 무슨 일 → 나중을 따라가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#4','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'mc','auto','글을 읽고 답해 보세요. 지안이의 마음을 바꾸어 준 일은 무엇인가요?',ARRAY['K2-1-u5-X08']::text[],true,'{"seq":4,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이의 마음을 바꾸어 준 일은 무엇인가요?","options":[{"t":"하람이가 같이 손잡고 들어가자고 한 일","correct":true},{"t":"엄마가 먼저 집에 간 일","mis":"K2-1-u5-X08"},{"t":"비가 내려 수영장이 문을 닫은 일","mis":"K2-1-u5-X08"}],"explanation":["하람이가 「같이 손잡고 들어가자!」 하고 웃은 뒤 지안이는 물에 발을 담갔어요.","엄마가 집에 갔다거나 비가 왔다는 말은 글에 없어요.","마음이 바뀐 까닭을 글에서 찾아요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 아기 곰의 마음을 바꾸어 준 일은 무엇인가요?","options":[{"t":"다람쥐가 어깨를 토닥이며 응원한 일","correct":true},{"t":"음악회가 취소된 일","mis":"K2-1-u5-X08"},{"t":"북이 부서진 일","mis":"K2-1-u5-X08"}],"explanation":["다람쥐가 「넌 잘할 수 있어!」 하고 토닥인 뒤 아기 곰은 북을 쳤어요.","음악회가 취소되거나 북이 부서졌다는 말은 글에 없어요.","마음이 바뀐 까닭을 글에서 찾아요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#5','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',2,'match','auto','글을 읽고 장면과 그때 지안이의 마음을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C6","difficulty":2,"kind":"match","stem":"글을 읽고 장면과 그때 지안이의 마음을 이어 보세요.","pairs":[{"l":"엄마 손을 꼭 잡았을 때","r":"무섭다"},{"l":"조심조심 발을 담갔을 때","r":"용기를 내다"},{"l":"물장구를 치며 깔깔 웃을 때","r":"신나다"}],"mis":"K2-1-u5-X07","explanation":["물을 처음 볼 때는 무서웠어요.","하람이 말을 듣고 용기를 내어 발을 담갔어요.","물장구를 칠 때는 신났어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 장면과 그때 아기 곰의 마음을 이어 보세요.","pairs":[{"l":"다리가 후들후들 떨릴 때","r":"떨리다"},{"l":"「넌 잘할 수 있어!」를 들었을 때","r":"고맙다"},{"l":"친구들이 손뼉을 칠 때","r":"뿌듯하다"}],"explanation":["무대 뒤에서는 떨렸어요.","다람쥐의 응원에 고마웠어요.","친구들의 손뼉에 뿌듯했어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#6','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 지안이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],true,'{"seq":6,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"무섭다 → 용기를 내다 → 신나다","correct":true},{"t":"신나다 → 무섭다 → 용기를 내다","mis":"K2-1-u5-X07"},{"t":"무섭다 → 무섭다 → 무섭다","mis":"K2-1-u5-X07"}],"explanation":["처음에는 무서웠고, 하람이 말에 용기를 내었고, 나중에는 신났어요.","차례를 뒤바꾸면 이야기가 달라져요.","마음은 처음 그대로 있지 않았어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 아기 곰의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"떨리다 → 힘이 나다 → 뿌듯하다","correct":true},{"t":"뿌듯하다 → 떨리다 → 힘이 나다","mis":"K2-1-u5-X07"},{"t":"떨리다 → 떨리다 → 떨리다","mis":"K2-1-u5-X07"}],"explanation":["처음에는 떨렸고, 다람쥐 응원에 힘이 났고, 나중에는 뿌듯했어요.","차례를 뒤바꾸면 이야기가 달라져요.","마음은 처음 그대로 있지 않았어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#7','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C9',2,'mc','auto','글을 읽고 답해 보세요. 「물이 너무 깊어 보여…….」를 지안이의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u5-X15']::text[],true,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「물이 너무 깊어 보여…….」를 지안이의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?","options":[{"t":"작고 걱정스러운 목소리로","correct":true},{"t":"크고 신나는 목소리로","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["지안이는 물이 무서워 걱정하고 있어요.","크고 신나게 읽으면 걱정하는 마음이 드러나지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 「넌 잘할 수 있어!」를 다람쥐의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?","options":[{"t":"다정하고 힘을 주는 목소리로","correct":true},{"t":"졸린 듯 작은 목소리로","mis":"K2-1-u5-X15"},{"t":"놀리는 듯한 목소리로","mis":"K2-1-u5-X15"}],"explanation":["다람쥐는 아기 곰을 응원하고 있어요.","졸리거나 놀리는 목소리는 응원하는 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#8','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',2,'sa','auto','글을 읽고 답해 보세요. 지안이에게 「같이 손잡고 들어가자!」 하고 말한 친구의 이름을 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C6","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 지안이에게 「같이 손잡고 들어가자!」 하고 말한 친구의 이름을 써 보세요.","answer":["하람","하람이"],"explanation":["「그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.」라고 했어요.","하람이의 말이 지안이의 마음을 바꾸었어요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 아기 곰에게 「넌 잘할 수 있어!」 하고 말한 동물을 써 보세요.","answer":["다람쥐"],"explanation":["「다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.」라고 했어요.","다람쥐의 말이 아기 곰의 마음을 바꾸었어요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#9','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',2,'mc','auto','인물의 마음이 어떻게 바뀌었는지 알려면 무엇을 살펴보면 좋을까요?',ARRAY['K2-1-u5-X01','K2-1-u5-X07']::text[],true,'{"seq":9,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"인물의 마음이 어떻게 바뀌었는지 알려면 무엇을 살펴보면 좋을까요?","options":[{"t":"일이 일어난 차례와 장면마다 인물의 말과 행동","correct":true},{"t":"글의 제목 글자 수","mis":"K2-1-u5-X01"},{"t":"글의 마지막 문장 하나만","mis":"K2-1-u5-X07"}],"explanation":["일이 일어난 차례를 따라가며 장면마다 마음을 짐작해요.","글자 수는 마음과 상관없어요.","마지막 문장만 보면 처음 마음을 놓쳐요."],"variant_rule":{"alt":[{"stem":"인물의 마음 변화를 정리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"「처음 → 무슨 일 → 나중」 차례로 마음을 적어요","correct":true},{"t":"마지막 마음 하나만 적어요","mis":"K2-1-u5-X07"},{"t":"인물의 이름만 적어요","mis":"K2-1-u5-X01"}],"explanation":["처음 마음, 마음을 바꾼 일, 나중 마음을 차례로 적어요.","마지막 마음만 적으면 변화가 보이지 않아요.","이름만으로는 마음을 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#10','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',3,'error','auto','글을 읽고 지안이의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 지안이의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「지안이는 처음부터 수영장이 하나도 무섭지 않았어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"예린 — 「처음에는 엄마 손을 꼭 잡을 만큼 무서웠어.」","mis":"K2-1-u5-X17"},{"t":"현우 — 「나중에는 물장구를 치며 신났어.」","mis":"K2-1-u5-X17"}],"explanation":["지안이는 처음에 물이 깊어 보여 무서워했어요.","마음이 처음부터 그대로였던 것이 아니에요.","예린이와 현우는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 아기 곰의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"지우 — 「아기 곰은 처음부터 하나도 떨리지 않았어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"도담 — 「무대 뒤에서는 다리가 떨렸어.」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「나중에는 가슴을 펴고 웃었어.」","mis":"K2-1-u5-X17"}],"explanation":["아기 곰은 무대 뒤에서 다리가 후들후들 떨렸어요.","마음이 처음부터 그대로였던 것이 아니에요.","도담이와 서윤이는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#1','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 동생이 카드에 우유를 쏟았을 때 지우의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":1,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 동생이 카드에 우유를 쏟았을 때 지우의 마음은 어느 것인가요?","options":[{"t":"속상한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u5-X02"},{"t":"고마운 마음","mis":"K2-1-u5-X02"}],"explanation":["정성껏 만든 카드가 젖어 눈물이 핑 돌았어요.","신나거나 고마운 마음은 이 장면과 맞지 않아요.","장면마다 마음을 짐작해요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#2','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 아기 곰이 가슴을 쭉 펼 수 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X08','K2-1-u5-X07']::text[],false,'{"seq":2,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 아기 곰이 가슴을 쭉 펼 수 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"다람쥐의 응원을 받고 북을 끝까지 쳐서 친구들이 손뼉을 쳐 주었으니까","correct":true},{"t":"무대에 오르지 않고 집에 갔으니까","mis":"K2-1-u5-X08"},{"t":"처음부터 하나도 떨리지 않았으니까","mis":"K2-1-u5-X07"}],"explanation":["응원을 받고 북을 쳤더니 친구들이 손뼉을 쳤어요.","집에 갔다는 말은 글에 없어요.","아기 곰은 처음에 떨렸어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#3','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',3,'mc','auto','글을 읽고 답해 보세요. 우유가 쏟아진 뒤부터 지우의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":3,"concept":"K2-1-u5-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 우유가 쏟아진 뒤부터 지우의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하다 → 따뜻하다","correct":true},{"t":"따뜻하다 → 속상하다","mis":"K2-1-u5-X07"},{"t":"속상하다 → 속상하다","mis":"K2-1-u5-X07"}],"explanation":["우유가 쏟아져 속상했다가, 할머니가 웃으셔서 마음이 따뜻해졌어요.","차례를 뒤바꾸면 이야기가 달라져요.","마음은 처음 그대로 있지 않았어요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#4','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',3,'error','auto','글을 읽고 아기 곰의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X08','K2-1-u5-X17']::text[],false,'{"seq":4,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 아기 곰의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"하람 — 「친구들이 손뼉을 칠 때 아기 곰은 부끄러워서 숨고 싶었어.」","correct":true,"mis_target":"K2-1-u5-X08"},{"t":"지호 — 「무대 뒤에서는 떨렸어.」","mis":"K2-1-u5-X17"},{"t":"민지 — 「다람쥐 덕분에 힘이 났어.」","mis":"K2-1-u5-X17"}],"explanation":["아기 곰은 손뼉 소리에 가슴을 펴고 환하게 웃었어요.","숨고 싶었다는 말은 글에 없어요.","지호와 민지는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#5','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C3',3,'ox','auto','글을 읽고 답해 보세요. 우유를 쏟은 동생은 미안한 마음이었어요.',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":5,"concept":"K2-1-u5-C3","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 우유를 쏟은 동생은 미안한 마음이었어요.","answer":"O","reason_options":[{"t":"고개를 숙이고 「언니, 미안해.」라고 했으니까","correct":true},{"t":"장난을 쳐서 신났으니까","mis":"K2-1-u5-X02"}],"mis":"K2-1-u5-X02","explanation":["고개를 숙이고 「미안해.」라고 한 말과 행동에서 미안한 마음이 드러나요.","장난을 쳤다는 말은 글에 없어요.","말과 행동을 함께 살펴요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#6','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C9',3,'mc','auto','「친구들과 함께 깔깔 웃으며 노는 장면」을 인물의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":6,"concept":"K2-1-u5-C9","difficulty":3,"kind":"mc","stem":"「친구들과 함께 깔깔 웃으며 노는 장면」을 인물의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?","options":[{"t":"밝고 즐거운 목소리로","correct":true},{"t":"작고 울먹이는 목소리로","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["함께 웃으며 노는 장면은 즐거운 마음이에요.","울먹이거나 화난 목소리는 즐거운 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#7','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',3,'mc','auto','글을 읽고 답해 보세요. 지안이가 조심조심 물에 발을 담글 때의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X03']::text[],false,'{"seq":7,"concept":"K2-1-u5-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이가 조심조심 물에 발을 담글 때의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아직 조금 무섭지만 용기를 내 보는 마음","correct":true},{"t":"물이 하나도 무섭지 않은 마음","mis":"K2-1-u5-X07"},{"t":"엄마에게 화가 난 마음","mis":"K2-1-u5-X03"}],"explanation":["「조심조심」에서 아직 조금 무서운 마음이, 발을 담그는 행동에서 용기가 보여요.","하나도 무섭지 않았다면 조심조심하지 않았을 거예요.","화가 났다는 단서는 글에 없어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#8','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',4,'mc','auto','인물의 마음 변화를 따라가며 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":8,"concept":"K2-1-u5-C6","difficulty":4,"kind":"mc","stem":"인물의 마음 변화를 따라가며 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무슨 일 때문에 마음이 바뀌었는지 알게 되어 글이 더 잘 이해돼요","correct":true},{"t":"마지막 마음만 알면 되어 빨리 읽을 수 있어요","mis":"K2-1-u5-X07"},{"t":"인물의 처음 마음만 기억하면 돼요","mis":"K2-1-u5-X07"}],"explanation":["마음이 바뀐 까닭을 알면 이야기가 더 잘 보여요.","마지막 마음만 보면 변화를 놓쳐요.","처음 마음만 기억해도 변화를 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#9','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',4,'essay','teacher','「숲속 음악회」에서 아기 곰의 마음이 처음·가운데·끝에 어떠했는지 쓰고, 마음이 바뀐 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"「숲속 음악회」에서 아기 곰의 마음이 처음·가운데·끝에 어떠했는지 쓰고, 마음이 바뀐 까닭을 써 보세요.","answer_guide":{"answer":"예: 처음에는 다리가 떨려 걱정되었어요. 다람쥐가 응원해 주어 힘이 났어요. 끝에는 친구들이 손뼉을 쳐 주어 뿌듯했어요. 다람쥐의 응원과 친구들의 손뼉 때문에 마음이 바뀌었어요.","scoring_points":["처음·가운데·끝의 마음을 차례대로 썼는가","마음을 마음 말로 알맞게 나타냈는가","마음이 바뀐 까닭을 글에서 찾아 썼는가"]},"explanation":["세 장면의 마음.","마음 말.","바뀐 까닭."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#10','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',4,'essay','teacher','처음 마음과 나중 마음이 달랐던 내 경험을 「처음에는 ~했는데, ~ 때문에 ~해졌어요.」의 꼴로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"처음 마음과 나중 마음이 달랐던 내 경험을 「처음에는 ~했는데, ~ 때문에 ~해졌어요.」의 꼴로 써 보세요.","answer_guide":{"answer":"예: 처음에는 새 반이 낯설어 떨렸는데, 짝이 먼저 말을 걸어 주어 편안해졌어요.","scoring_points":["처음 마음을 썼는가","마음을 바꾼 일을 썼는가","나중 마음을 마음 말로 썼는가"]},"explanation":["처음 마음.","마음을 바꾼 일.","나중 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#1','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',1,'blank','auto','「텃밭의 상추가 잘 자라도록 (     )을 주었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":1,"concept":"K2-1-u5-C7","difficulty":1,"kind":"blank","stem":"「텃밭의 상추가 잘 자라도록 (     )을 주었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"거름","correct":true},{"t":"걸음","mis":"K2-1-u5-X09"},{"t":"거럼","mis":"K2-1-u5-X09"}],"explanation":["식물을 잘 자라게 하려고 흙에 주는 것은 「거름」이에요.","「걸음」은 발을 옮겨 걷는 것이에요.","소리가 같아도 문장의 뜻을 보고 골라요."],"variant_rule":{"alt":[{"stem":"「아기가 한 (     )씩 천천히 걸었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"걸음","correct":true},{"t":"거름","mis":"K2-1-u5-X09"},{"t":"걸름","mis":"K2-1-u5-X09"}],"explanation":["발을 옮겨 걷는 것은 「걸음」이에요.","「거름」은 식물을 잘 자라게 하는 흙이에요.","소리가 같아도 문장의 뜻을 보고 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#2','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',1,'mc','auto','「다치다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":2,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「다치다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸에 상처를 입다","correct":true},{"t":"열려 있던 것이 막히다","mis":"K2-1-u5-X09"},{"t":"하던 일을 끝내다","mis":"K2-1-u5-X09"}],"explanation":["「무릎을 다치다」처럼 몸에 상처를 입는 것이 「다치다」예요.","열려 있던 것이 막히는 것은 「닫히다」예요.","일을 끝내는 것은 「마치다」예요."],"variant_rule":{"alt":[{"stem":"「닫히다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"열려 있던 것이 막히다","correct":true},{"t":"몸에 상처를 입다","mis":"K2-1-u5-X09"},{"t":"목표에 닿게 하다","mis":"K2-1-u5-X09"}],"explanation":["「문이 닫히다」처럼 열려 있던 것이 막히는 것이 「닫히다」예요.","몸에 상처를 입는 것은 「다치다」예요.","목표에 닿게 하는 것은 「맞히다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#3','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',1,'ox','auto','「종이 울려서 수업을 맞혔어요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":3,"concept":"K2-1-u5-C7","difficulty":1,"kind":"ox","stem":"「종이 울려서 수업을 맞혔어요.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"하던 일을 끝내는 것은 「마치다」라서 「마쳤어요」라고 써야 하니까","correct":true},{"t":"소리가 같으면 아무 낱말이나 써도 되니까","mis":"K2-1-u5-X09"}],"mis":"K2-1-u5-X09","explanation":["수업을 끝내는 것은 「마치다」예요.","「맞히다」는 과녁이나 답을 맞게 하는 거예요.","소리가 같아도 뜻을 보고 골라요."],"variant_rule":{"alt":[{"stem":"「공을 던져 과녁을 맞혔어요.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"목표에 닿게 하는 것은 「맞히다」니까","correct":true},{"t":"소리가 같으면 「마쳤어요」라고 써도 되니까","mis":"K2-1-u5-X09"}],"explanation":["과녁에 닿게 하는 것은 「맞히다」예요.","「마치다」는 하던 일을 끝내는 거예요.","소리가 같아도 뜻을 보고 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#4','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',1,'mc','auto','바르게 쓴 문장은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":4,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「넘어져서 무릎을 다쳤어요.」","correct":true},{"t":"「넘어져서 무릎을 닫혔어요.」","mis":"K2-1-u5-X09"},{"t":"「넘어져서 무릎을 맞혔어요.」","mis":"K2-1-u5-X09"}],"explanation":["몸에 상처를 입는 것은 「다치다」예요.","「닫히다」는 문 같은 것이 막히는 거예요.","「맞히다」는 목표에 닿게 하는 거예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「바람이 불어서 문이 닫혔어요.」","correct":true},{"t":"「바람이 불어서 문이 다쳤어요.」","mis":"K2-1-u5-X09"},{"t":"「바람이 불어서 문이 마쳤어요.」","mis":"K2-1-u5-X09"}],"explanation":["열려 있던 문이 막히는 것은 「닫히다」예요.","「다치다」는 몸에 상처를 입는 거예요.","「마치다」는 하던 일을 끝내는 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#5','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'match','auto','낱말과 뜻을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"가르치다","r":"모르는 것을 알려 주다"},{"l":"가리키다","r":"손가락으로 방향이나 물건을 짚어 보이다"},{"l":"반드시","r":"틀림없이 꼭"}],"mis":"K2-1-u5-X10","explanation":["「한글을 가르치다」처럼 알려 주는 것이 「가르치다」예요.","「손가락으로 가리키다」처럼 짚어 보이는 것이 「가리키다」예요.","「반드시」는 틀림없이 꼭이라는 뜻이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"잊다","r":"알던 것을 기억하지 못하다"},{"l":"잃다","r":"가졌던 물건이 없어지다"},{"l":"바라다","r":"어떤 일이 이루어지기를 원하다"}],"explanation":["「약속을 잊다」처럼 기억하지 못하는 것이 「잊다」예요.","「장갑을 잃다」처럼 물건이 없어지는 것이 「잃다」예요.","「소원이 이루어지기를 바라다」처럼 원하는 것이 「바라다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#6','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'blank','auto','「선생님께서 우리에게 한글을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],true,'{"seq":6,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「선생님께서 우리에게 한글을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"가르쳐 주셨어요","correct":true},{"t":"가리켜 주셨어요","mis":"K2-1-u5-X10"},{"t":"가르켜 주셨어요","mis":"K2-1-u5-X09"}],"explanation":["모르는 것을 알려 주는 것은 「가르치다」예요.","「가리키다」는 손가락으로 짚어 보이는 거예요.","「가르켜」는 없는 말이에요."],"variant_rule":{"alt":[{"stem":"「동생이 손가락으로 하늘의 무지개를 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"가리켰어요","correct":true},{"t":"가르쳤어요","mis":"K2-1-u5-X10"},{"t":"가르켰어요","mis":"K2-1-u5-X09"}],"explanation":["손가락으로 짚어 보이는 것은 「가리키다」예요.","「가르치다」는 모르는 것을 알려 주는 거예요.","「가르켰어요」는 없는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#7','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'mc','auto','「다르다」를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K2-1-u5-X10']::text[],true,'{"seq":7,"concept":"K2-1-u5-C7","difficulty":2,"kind":"mc","stem":"「다르다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「나와 동생은 좋아하는 과일이 달라요.」","correct":true},{"t":"「나와 동생은 좋아하는 과일이 틀려요.」","mis":"K2-1-u5-X10"},{"t":"「쌍둥이지만 키가 조금 틀려요.」","mis":"K2-1-u5-X10"}],"explanation":["같지 않은 것은 「다르다」예요.","「틀리다」는 맞지 않을 때 써요.","쌍둥이의 키가 같지 않은 것도 「다르다」로 써요."],"variant_rule":{"alt":[{"stem":"「틀리다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「셈을 잘못해서 답이 틀렸어요.」","correct":true},{"t":"「쌍둥이지만 얼굴이 조금 틀려요.」","mis":"K2-1-u5-X10"},{"t":"「내 신발과 네 신발은 크기가 틀려요.」","mis":"K2-1-u5-X10"}],"explanation":["맞지 않은 것은 「틀리다」예요.","얼굴이나 크기가 같지 않은 것은 「다르다」예요.","「다르다」와 「틀리다」는 뜻이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#8','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'sa','auto','「어떤 일이 이루어지기를 원하다」라는 뜻의 낱말을 「바라다」와 「바래다」 가운데 골라 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C7","difficulty":2,"kind":"sa","stem":"「어떤 일이 이루어지기를 원하다」라는 뜻의 낱말을 「바라다」와 「바래다」 가운데 골라 써 보세요.","answer":["바라다"],"explanation":["「소원이 이루어지기를 바라다」처럼 원하는 것은 「바라다」예요.","「바래다」는 색이 옅어지는 거예요.","그래서 「꼭 이기기를 바라요.」라고 써요."],"variant_rule":{"alt":[{"stem":"「가졌던 물건이 없어지다」라는 뜻의 낱말을 「잊다」와 「잃다」 가운데 골라 써 보세요.","answer":["잃다"],"explanation":["「장갑을 잃다」처럼 물건이 없어지는 것은 「잃다」예요.","「잊다」는 알던 것을 기억하지 못하는 거예요.","뜻을 말로 풀어 보고 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#9','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'mc','auto','헷갈리기 쉬운 낱말을 바르게 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":9,"concept":"K2-1-u5-C7","difficulty":2,"kind":"mc","stem":"헷갈리기 쉬운 낱말을 바르게 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"문장의 뜻을 생각하며 알맞은 낱말을 골라요","correct":true},{"t":"소리 나는 대로 아무 낱말이나 골라요","mis":"K2-1-u5-X09"},{"t":"글자 수가 더 많은 낱말을 골라요","mis":"K2-1-u5-X09"}],"explanation":["문장의 뜻을 생각해야 알맞은 낱말을 고를 수 있어요.","소리가 같아도 뜻이 다른 낱말이 있어요.","글자 수는 뜻과 상관없어요."],"variant_rule":{"alt":[{"stem":"헷갈리기 쉬운 낱말을 잘못 쓰면 어떻게 될까요?","options":[{"t":"전하고 싶은 뜻이 잘못 전해져요","correct":true},{"t":"뜻은 언제나 똑같이 전해져요","mis":"K2-1-u5-X09"},{"t":"글이 더 재미있어져요","mis":"K2-1-u5-X09"}],"explanation":["「걸음」을 「거름」으로 쓰면 뜻이 달라져요.","소리가 같아도 뜻이 같지 않아요.","그래서 뜻을 생각하며 골라 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#10','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X09','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"하준 — 「반듯이 숙제를 하고 놀 거예요.」","correct":true,"mis_target":"K2-1-u5-X09"},{"t":"예린 — 「의자에 반듯이 앉았어요.」","mis":"K2-1-u5-X17"},{"t":"소율 — 「숙제를 마치고 놀았어요.」","mis":"K2-1-u5-X17"}],"explanation":["「꼭」이라는 뜻은 「반드시」라고 써야 해요.","「반듯이」는 곧고 바르게라는 뜻이에요.","예린이와 소율이는 뜻에 맞게 바르게 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호 — 「놀이터에서 장갑을 잊어버렸어요.」","correct":true,"mis_target":"K2-1-u5-X10"},{"t":"다은 — 「친구 생일을 잊지 않았어요.」","mis":"K2-1-u5-X17"},{"t":"시우 — 「공원에서 모자를 잃어버렸어요.」","mis":"K2-1-u5-X17"}],"explanation":["물건이 없어진 것은 「잃어버렸어요」라고 써야 해요.","「잊다」는 알던 것을 기억하지 못하는 거예요.","다은이와 시우는 뜻에 맞게 바르게 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#1','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',2,'mc','auto','「반듯이」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":1,"concept":"K2-1-u5-C7","difficulty":2,"kind":"mc","stem":"「반듯이」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"비뚤어지지 않고 곧고 바르게","correct":true},{"t":"틀림없이 꼭","mis":"K2-1-u5-X09"},{"t":"아주 빠르게","mis":"K2-1-u5-X09"}],"explanation":["「반듯이 앉다」처럼 곧고 바르게라는 뜻이에요.","「틀림없이 꼭」은 「반드시」의 뜻이에요.","소리가 같아도 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#2','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',2,'blank','auto','「오래 입은 티셔츠의 색이 누렇게 (     ).」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],false,'{"seq":2,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「오래 입은 티셔츠의 색이 누렇게 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"바랬어요","correct":true},{"t":"바랐어요","mis":"K2-1-u5-X10"},{"t":"바렜어요","mis":"K2-1-u5-X09"}],"explanation":["색이 옅어지는 것은 「바래다」라서 「바랬어요」예요.","「바랐어요」는 원했다는 뜻이에요.","「바렜어요」는 없는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#3','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'error','auto','일기 한 줄씩을 읽었어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X09','K2-1-u5-X17']::text[],false,'{"seq":3,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"일기 한 줄씩을 읽었어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"태민 — 「계단에서 넘어져 무릎을 닫혀서 약을 발랐다.」","correct":true,"mis_target":"K2-1-u5-X09"},{"t":"은솔 — 「선생님께서 칠판의 글자를 가리키셨다.」","mis":"K2-1-u5-X17"},{"t":"아린 — 「친구와 나는 좋아하는 색이 다르다.」","mis":"K2-1-u5-X17"}],"explanation":["몸에 상처를 입은 것은 「다쳐서」라고 써야 해요.","「닫히다」는 문 같은 것이 막히는 거예요.","은솔이와 아린이는 뜻에 맞게 바르게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#4','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'mc','auto','소리가 똑같이 나는 낱말끼리 짝지은 것은 어느 것인가요?',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":4,"concept":"K2-1-u5-C7","difficulty":3,"kind":"mc","stem":"소리가 똑같이 나는 낱말끼리 짝지은 것은 어느 것인가요?","options":[{"t":"걸음 · 거름","correct":true},{"t":"가르치다 · 가리키다","mis":"K2-1-u5-X10"},{"t":"잊다 · 잃다","mis":"K2-1-u5-X10"}],"explanation":["「걸음」과 「거름」은 둘 다 [거름]으로 소리 나요.","「가르치다」와 「가리키다」는 소리가 비슷하지만 같지 않아요.","「잊다」와 「잃다」도 소리가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#5','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'ox','auto','「마치다」와 「맞히다」는 소리가 같지만 뜻이 서로 달라요.',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":3,"kind":"ox","stem":"「마치다」와 「맞히다」는 소리가 같지만 뜻이 서로 달라요.","answer":"O","reason_options":[{"t":"「마치다」는 일을 끝내다, 「맞히다」는 목표에 닿게 하다라는 뜻이니까","correct":true},{"t":"소리가 같으면 뜻도 같으니까","mis":"K2-1-u5-X09"}],"mis":"K2-1-u5-X09","explanation":["「수업을 마치다」, 「과녁을 맞히다」처럼 써요.","소리가 같아도 뜻이 다를 수 있어요.","문장의 뜻을 보고 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#6','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'mc','auto','「숙제를 (㉠) 친구와 공던지기를 했는데, 공으로 깡통을 (㉡).」 빈칸에 알맞은 말을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":6,"concept":"K2-1-u5-C7","difficulty":3,"kind":"mc","stem":"「숙제를 (㉠) 친구와 공던지기를 했는데, 공으로 깡통을 (㉡).」 빈칸에 알맞은 말을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉠ 마치고 · ㉡ 맞혔어요","correct":true},{"t":"㉠ 맞히고 · ㉡ 마쳤어요","mis":"K2-1-u5-X09"},{"t":"㉠ 마치고 · ㉡ 마쳤어요","mis":"K2-1-u5-X09"}],"explanation":["숙제를 끝내는 것은 「마치고」예요.","깡통에 공이 닿게 한 것은 「맞혔어요」예요.","두 빈칸의 뜻을 하나씩 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#7','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'mc','auto','「깜빡하고 준비물을 챙기지 못했어요.」를 알맞게 바꾸어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],false,'{"seq":7,"concept":"K2-1-u5-C7","difficulty":3,"kind":"mc","stem":"「깜빡하고 준비물을 챙기지 못했어요.」를 알맞게 바꾸어 쓴 것은 어느 것인가요?","options":[{"t":"「준비물 챙기는 것을 잊어버렸어요.」","correct":true},{"t":"「준비물 챙기는 것을 잃어버렸어요.」","mis":"K2-1-u5-X10"},{"t":"「준비물 챙기는 것을 잇어버렸어요.」","mis":"K2-1-u5-X09"}],"explanation":["깜빡하고 기억하지 못한 것은 「잊어버렸어요」예요.","「잃어버렸어요」는 물건이 없어졌을 때 써요.","「잇어버렸어요」는 없는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#8','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',4,'mc','auto','「선생님께서 칠판의 글자를 손으로 가르치며 읽는 방법을 가리켜 주셨어요.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":8,"concept":"K2-1-u5-C7","difficulty":4,"kind":"mc","stem":"「선생님께서 칠판의 글자를 손으로 가르치며 읽는 방법을 가리켜 주셨어요.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「선생님께서 칠판의 글자를 손으로 가리키며 읽는 방법을 가르쳐 주셨어요.」","correct":true},{"t":"「선생님께서 칠판의 글자를 손으로 가르치며 읽는 방법을 가르쳐 주셨어요.」","mis":"K2-1-u5-X10"},{"t":"「선생님께서 칠판의 글자를 손으로 가리키며 읽는 방법을 가리켜 주셨어요.」","mis":"K2-1-u5-X10"}],"explanation":["손으로 짚어 보이는 것은 「가리키며」예요.","읽는 방법을 알려 주신 것은 「가르쳐」예요.","두 낱말의 자리가 바뀌어 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#9','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',4,'essay','teacher','「다르다」와 「틀리다」의 뜻이 어떻게 다른지 쓰고, 두 낱말을 하나씩 넣어 문장을 만들어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"「다르다」와 「틀리다」의 뜻이 어떻게 다른지 쓰고, 두 낱말을 하나씩 넣어 문장을 만들어 보세요.","answer_guide":{"answer":"예: 「다르다」는 같지 않다, 「틀리다」는 맞지 않다라는 뜻이에요. 내 필통과 네 필통은 색이 달라. 받아쓰기에서 한 문제가 틀렸어.","scoring_points":["「다르다」의 뜻을 바르게 썼는가","「틀리다」의 뜻을 바르게 썼는가","두 낱말을 뜻에 맞게 넣어 문장을 만들었는가"]},"explanation":["「다르다」의 뜻.","「틀리다」의 뜻.","뜻에 맞는 문장 두 개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#10','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',4,'essay','teacher','헷갈리기 쉬운 낱말 짝(걸음·거름, 다치다·닫히다, 잊다·잃다 등) 하나를 골라 두 낱말의 뜻을 쓰고, 헷갈리지 않고 바르게 쓰는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"헷갈리기 쉬운 낱말 짝(걸음·거름, 다치다·닫히다, 잊다·잃다 등) 하나를 골라 두 낱말의 뜻을 쓰고, 헷갈리지 않고 바르게 쓰는 방법을 써 보세요.","answer_guide":{"answer":"예: 다치다는 몸에 상처를 입다, 닫히다는 열린 것이 막히다예요. 문장에서 몸 이야기인지 문 이야기인지 뜻을 생각하고 골라 써요.","scoring_points":["낱말 짝 하나를 골랐는가","두 낱말의 뜻을 바르게 썼는가","문장의 뜻을 생각하며 고른다는 방법을 썼는가"]},"explanation":["낱말 짝.","두 낱말의 뜻.","바르게 쓰는 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#1','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',1,'mc','auto','자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],true,'{"seq":1,"concept":"K2-1-u5-C8","difficulty":1,"kind":"mc","stem":"자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「고양이가 / 햇볕에서 / 졸아요」","correct":true},{"t":"「고 / 양 / 이 / 가 / 햇볕에서 졸아요」","mis":"K2-1-u5-X11"},{"t":"「고양이가햇볕에서졸아요」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","한 글자씩 끊으면 어색하고 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 숨이 차요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「작은 새가 / 나뭇가지에 / 앉았다」","correct":true},{"t":"「작은 / 새 / 가 / 나뭇 / 가지에 앉았다」","mis":"K2-1-u5-X11"},{"t":"「작은새가나뭇가지에앉았다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","낱말마다 뚝뚝 끊으면 어색해요.","쉬지 않고 붙여 읽으면 숨이 차요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#2','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',1,'mc','auto','한 문장이 끝나고 다음 문장으로 넘어갈 때는 어떻게 쉬어 읽나요?',ARRAY['K2-1-u5-X14','K2-1-u5-X11']::text[],true,'{"seq":2,"concept":"K2-1-u5-C8","difficulty":1,"kind":"mc","stem":"한 문장이 끝나고 다음 문장으로 넘어갈 때는 어떻게 쉬어 읽나요?","options":[{"t":"문장 안에서보다 조금 더 길게 쉬어요","correct":true},{"t":"쉬지 않고 바로 이어 읽어요","mis":"K2-1-u5-X14"},{"t":"낱말마다 쉬어요","mis":"K2-1-u5-X11"}],"explanation":["문장과 문장 사이에서는 조금 더 길게 쉬어요.","바로 이어 읽으면 두 문장이 섞여 들려요.","낱말마다 쉬면 어색해요."],"variant_rule":{"alt":[{"stem":"「누가(무엇이)」에 해당하는 말 뒤에서는 어떻게 읽나요?","options":[{"t":"조금 쉬어 읽어요","correct":true},{"t":"쉬지 않고 붙여 읽어요","mis":"K2-1-u5-X14"},{"t":"한 글자씩 끊어 읽어요","mis":"K2-1-u5-X11"}],"explanation":["「토끼가 / 풀밭에서 놀아요」처럼 「누가」 뒤에서 조금 쉬어요.","붙여 읽으면 뜻 덩어리가 나뉘지 않아요.","한 글자씩 끊으면 어색해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#3','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',1,'ox','auto','낱말마다 뚝뚝 끊어 읽으면 글이 자연스럽게 들려요.',ARRAY['K2-1-u5-X11']::text[],true,'{"seq":3,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"낱말마다 뚝뚝 끊어 읽으면 글이 자연스럽게 들려요.","answer":"X","reason_options":[{"t":"뜻이 통하는 덩어리로 묶어 읽어야 자연스러우니까","correct":true},{"t":"낱말마다 끊어야 또박또박 들리니까","mis":"K2-1-u5-X11"}],"mis":"K2-1-u5-X11","explanation":["낱말마다 끊으면 뜻이 끊겨 어색해요.","뜻이 이어지는 부분은 붙여 읽어요.","덩어리 사이에서만 쉬어요."],"variant_rule":{"alt":[{"stem":"긴 문장을 한 번도 쉬지 않고 읽으면 숨이 차고 뜻을 알기 어려워요.","answer":"O","reason_options":[{"t":"뜻 덩어리 사이에서 쉬어야 숨도 고르고 뜻도 드러나니까","correct":true},{"t":"쉬지 않고 빨리 읽을수록 잘 읽은 것이니까","mis":"K2-1-u5-X12"}],"explanation":["쉬지 않으면 숨이 차고 듣는 사람도 알아듣기 어려워요.","뜻 덩어리 사이에서 쉬어요.","빨리 읽는 것과 잘 읽는 것은 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#4','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C9',1,'mc','auto','인물이 기쁜 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],true,'{"seq":4,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 기쁜 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"밝고 가볍게","correct":true},{"t":"차분하고 느리게","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["기쁜 장면은 밝고 가볍게 읽으면 마음이 살아나요.","차분하고 느린 목소리는 슬픈 장면에 어울려요.","화난 목소리는 기쁜 마음과 맞지 않아요."],"variant_rule":{"alt":[{"stem":"인물이 슬픈 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"차분하고 느리게","correct":true},{"t":"밝고 빠르게","mis":"K2-1-u5-X15"},{"t":"크게 소리 지르며","mis":"K2-1-u5-X15"}],"explanation":["슬픈 장면은 차분하고 느리게 읽으면 마음이 살아나요.","밝고 빠른 목소리는 기쁜 장면에 어울려요.","소리 지르면 슬픈 마음이 드러나지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#5','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',2,'match','auto','띄어 읽는 자리와 읽는 방법을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C8","difficulty":2,"kind":"match","stem":"띄어 읽는 자리와 읽는 방법을 알맞게 이어 보세요.","pairs":[{"l":"「누가(무엇이)」에 해당하는 말 뒤","r":"조금 쉬기"},{"l":"문장과 문장 사이","r":"조금 더 길게 쉬기"},{"l":"뜻이 이어지는 낱말 사이","r":"붙여 읽기"}],"mis":"K2-1-u5-X14","explanation":["「누가」 뒤에서는 조금 쉬어요.","문장과 문장 사이에서는 조금 더 길게 쉬어요.","뜻이 이어지는 낱말은 붙여 읽어요."],"variant_rule":{"alt":[{"stem":"장면과 어울리는 읽는 방법을 이어 보세요.","pairs":[{"l":"기쁜 장면","r":"밝고 가볍게"},{"l":"슬픈 장면","r":"차분하고 느리게"},{"l":"떨리는 장면","r":"작고 조심스럽게"}],"explanation":["기쁜 장면은 밝고 가볍게 읽어요.","슬픈 장면은 차분하고 느리게 읽어요.","떨리는 장면은 작고 조심스럽게 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#6','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',2,'mc','auto','「나는 오늘 도서관에서 책을 읽었다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],true,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「나는 오늘 도서관에서 책을 읽었다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「나는 / 오늘 도서관에서 / 책을 읽었다」","correct":true},{"t":"「나 / 는 / 오늘 / 도서 / 관에서 / 책을 읽었다」","mis":"K2-1-u5-X11"},{"t":"「나는 오늘 도 / 서관에서 책을 / 읽었다」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","「도 / 서관」처럼 낱말 가운데에서 끊으면 뜻이 흐려져요."],"variant_rule":{"alt":[{"stem":"「비가 와서 우산을 썼다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「비가 와서 / 우산을 썼다」","correct":true},{"t":"「비가 / 와서우산을 / 썼다」","mis":"K2-1-u5-X13"},{"t":"「비 / 가 / 와 / 서 / 우산을 썼다」","mis":"K2-1-u5-X11"}],"explanation":["「비가 와서」와 「우산을 썼다」로 묶어 읽었어요.","「와서우산을」처럼 묶으면 뜻 덩어리가 흐트러져요.","한 글자씩 끊으면 어색해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#7','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C9',2,'blank','auto','「「엄마, 고마워요!」 하며 엄마를 꼭 안았어요.」를 인물의 마음을 살려 (     ) 목소리로 읽어요. 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],true,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":2,"kind":"blank","stem":"「「엄마, 고마워요!」 하며 엄마를 꼭 안았어요.」를 인물의 마음을 살려 (     ) 목소리로 읽어요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"따뜻하고 다정한","correct":true},{"t":"화나고 거친","mis":"K2-1-u5-X15"},{"t":"작고 졸린","mis":"K2-1-u5-X15"}],"explanation":["엄마를 꼭 안으며 고맙다고 하는 장면은 따뜻한 마음이에요.","화나고 거친 목소리는 고마운 마음과 맞지 않아요.","졸린 목소리로 읽으면 마음이 드러나지 않아요."],"variant_rule":{"alt":[{"stem":"「아끼던 화분이 깨져서 눈물이 났어요.」를 인물의 마음을 살려 (     ) 목소리로 읽어요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"차분하고 슬픈","correct":true},{"t":"밝고 신나는","mis":"K2-1-u5-X15"},{"t":"크고 씩씩한","mis":"K2-1-u5-X15"}],"explanation":["화분이 깨져 눈물이 나는 장면은 슬픈 마음이에요.","밝고 신나는 목소리는 슬픈 마음과 맞지 않아요.","크고 씩씩하게 읽으면 마음이 드러나지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#8','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',2,'sa','auto','띄어 읽을 곳을 표시할 때 긋는 「/」를 무엇이라고 하나요? 두 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C8","difficulty":2,"kind":"sa","stem":"띄어 읽을 곳을 표시할 때 긋는 「/」를 무엇이라고 하나요? 두 글자로 써 보세요.","answer":["빗금"],"explanation":["띄어 읽을 곳에 긋는 「/」를 빗금이라고 해요.","빗금이 있는 곳에서 조금 쉬어 읽어요.","빗금이 없는 곳은 붙여 읽어요."],"variant_rule":{"alt":[{"stem":"뜻이 통하는 덩어리로 띄어 읽으면 무엇이 잘 드러나나요? 한 글자로 써 보세요.","answer":["뜻"],"explanation":["알맞게 띄어 읽으면 뜻이 잘 드러나요.","듣는 사람도 뜻을 잘 알아들어요.","그래서 뜻 덩어리로 묶어 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#9','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C9',2,'mc','auto','알맞게 띄어 읽으면서 인물의 마음도 살려 읽으면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u5-X12','K2-1-u5-X15']::text[],true,'{"seq":9,"concept":"K2-1-u5-C9","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽으면서 인물의 마음도 살려 읽으면 좋은 점은 어느 것인가요?","options":[{"t":"듣는 사람이 뜻과 인물의 마음을 잘 느낄 수 있어요","correct":true},{"t":"글을 더 빨리 끝낼 수 있어요","mis":"K2-1-u5-X12"},{"t":"모든 장면을 같은 목소리로 읽을 수 있어요","mis":"K2-1-u5-X15"}],"explanation":["뜻도 마음도 잘 전해져 글이 살아나요.","빨리 끝내는 것이 목적이 아니에요.","장면마다 마음에 맞게 목소리를 바꾸어요."],"variant_rule":{"alt":[{"stem":"인물의 마음을 살려 읽기 전에 먼저 할 일은 무엇인가요?","options":[{"t":"장면 속 인물의 마음을 짐작해요","correct":true},{"t":"글자 수를 세어 봐요","mis":"K2-1-u5-X01"},{"t":"가장 큰 목소리를 정해요","mis":"K2-1-u5-X15"}],"explanation":["인물의 마음을 알아야 어울리는 목소리를 정할 수 있어요.","글자 수는 마음과 상관없어요.","큰 목소리가 언제나 어울리는 것은 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#10','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',3,'error','auto','「우리 반 친구들이 운동장에서 신나게 뛰어놀았다.」를 띄어 읽었어요. 어색하게 띄어 읽은 친구는 누구인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C8","difficulty":3,"kind":"error","stem":"「우리 반 친구들이 운동장에서 신나게 뛰어놀았다.」를 띄어 읽었어요. 어색하게 띄어 읽은 친구는 누구인가요?","options":[{"t":"지안 — 「우리 / 반 / 친 / 구들이 / 운동장에서 신나게 뛰어놀았다」","correct":true,"mis_target":"K2-1-u5-X11"},{"t":"도담 — 「우리 반 친구들이 / 운동장에서 / 신나게 뛰어놀았다」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「우리 반 친구들이 / 운동장에서 신나게 뛰어놀았다」","mis":"K2-1-u5-X17"}],"explanation":["지안이는 「친 / 구들이」처럼 낱말 가운데에서 끊어 어색해요.","도담이와 서윤이는 뜻 덩어리로 띄어 읽었어요.","띄어 읽는 곳이 조금 달라도 뜻이 드러나면 괜찮아요."],"variant_rule":{"alt":[{"stem":"「할머니께서 따뜻한 호박죽을 끓여 주셨다.」를 띄어 읽었어요. 어색하게 띄어 읽은 친구는 누구인가요?","options":[{"t":"현우 — 「할머니께서따뜻한호박죽을끓여주셨다」","correct":true,"mis_target":"K2-1-u5-X12"},{"t":"지우 — 「할머니께서 / 따뜻한 호박죽을 / 끓여 주셨다」","mis":"K2-1-u5-X17"},{"t":"하늘 — 「할머니께서 / 따뜻한 호박죽을 끓여 주셨다」","mis":"K2-1-u5-X17"}],"explanation":["현우는 한 번도 쉬지 않아 숨이 차고 뜻을 알기 어려워요.","지우와 하늘이는 뜻 덩어리로 띄어 읽었어요.","띄어 읽는 곳이 조금 달라도 뜻이 드러나면 괜찮아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#1','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',2,'mc','auto','「작은 / 새와 나무」로 띄어 읽으면 작은 것은 무엇인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":1,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「작은 / 새와 나무」로 띄어 읽으면 작은 것은 무엇인가요?","options":[{"t":"새와 나무 모두","correct":true},{"t":"새만","mis":"K2-1-u5-X13"},{"t":"나무만","mis":"K2-1-u5-X13"}],"explanation":["「작은 / 새와 나무」는 새와 나무가 모두 작다는 뜻이 돼요.","새만 작다면 「작은 새와 / 나무」로 읽어요.","어디에서 쉬느냐에 따라 뜻이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#2','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C9',2,'mc','auto','인물이 속상해서 「괜찮아…….」라고 말하는 장면은 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":2,"concept":"K2-1-u5-C9","difficulty":2,"kind":"mc","stem":"인물이 속상해서 「괜찮아…….」라고 말하는 장면은 어떻게 읽으면 좋을까요?","options":[{"t":"작고 느리게, 힘없는 목소리로","correct":true},{"t":"크고 밝은 목소리로","mis":"K2-1-u5-X15"},{"t":"빠르고 신나는 목소리로","mis":"K2-1-u5-X15"}],"explanation":["속상한 마음은 작고 힘없는 목소리에 잘 드러나요.","크고 밝게 읽으면 속상한 마음이 사라져요.","빠르고 신나게 읽으면 마음과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#3','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',3,'error','auto','자연스럽게 띄어 읽는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X12','K2-1-u5-X17']::text[],false,'{"seq":3,"concept":"K2-1-u5-C8","difficulty":3,"kind":"error","stem":"자연스럽게 띄어 읽는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"민호 — 「최대한 빠르게, 한 번도 쉬지 않고 읽어야 해.」","correct":true,"mis_target":"K2-1-u5-X12"},{"t":"하린 — 「뜻이 통하는 덩어리로 묶어 읽어.」","mis":"K2-1-u5-X17"},{"t":"지후 — 「문장과 문장 사이에서는 조금 더 길게 쉬어.」","mis":"K2-1-u5-X17"}],"explanation":["쉬지 않고 빨리 읽으면 숨이 차고 뜻을 알기 어려워요.","뜻 덩어리 사이에서 쉬어 읽어요.","하린이와 지후는 알맞게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#4','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',3,'mc','auto','「엄마가 시장에서 사과를 사 오셨어요.」를 가장 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"「엄마가 시장에서 사과를 사 오셨어요.」를 가장 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「엄마가 / 시장에서 / 사과를 사 오셨어요」","correct":true},{"t":"「엄 / 마가 / 시 / 장에서 / 사과를 사 오셨어요」","mis":"K2-1-u5-X11"},{"t":"「엄마가시장에서사과를사오셨어요」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 어색해요.","쉬지 않으면 숨이 차고 뜻을 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#5','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',3,'ox','auto','띄어 읽는 곳은 사람마다 조금 달라도 뜻이 잘 드러나면 괜찮아요.',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":5,"concept":"K2-1-u5-C8","difficulty":3,"kind":"ox","stem":"띄어 읽는 곳은 사람마다 조금 달라도 뜻이 잘 드러나면 괜찮아요.","answer":"O","reason_options":[{"t":"뜻 덩어리를 깨뜨리지 않으면 자연스럽게 들리니까","correct":true},{"t":"띄어 읽는 곳은 오직 한 가지뿐이니까","mis":"K2-1-u5-X13"}],"mis":"K2-1-u5-X13","explanation":["「우리 반 친구들이 / 운동장에서 / 놀았다」도, 「우리 반 친구들이 / 운동장에서 놀았다」도 괜찮아요.","낱말 가운데에서 끊거나 뜻이 바뀌게 끊으면 안 돼요.","뜻이 드러나는지가 가장 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#6','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C9',3,'mc','auto','글을 읽고 답해 보세요. 「무대 뒤에서 다리가 후들후들 떨렸어요.」를 아기 곰의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":6,"concept":"K2-1-u5-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「무대 뒤에서 다리가 후들후들 떨렸어요.」를 아기 곰의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?","options":[{"t":"작고 떨리는 목소리로 천천히","correct":true},{"t":"밝고 신나는 목소리로 빠르게","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["다리가 떨리는 장면은 떨리고 걱정되는 마음이에요.","밝고 신나게 읽으면 떨리는 마음이 드러나지 않아요.","화난 목소리는 이 장면과 맞지 않아요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#7','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',3,'mc','auto','「비가 그쳤어요. 하늘에 무지개가 떴어요.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X14','K2-1-u5-X11']::text[],false,'{"seq":7,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"「비가 그쳤어요. 하늘에 무지개가 떴어요.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「비가 그쳤어요. // 하늘에 / 무지개가 떴어요.」","correct":true},{"t":"「비가 그쳤어요. 하늘에무지개가 / 떴어요.」","mis":"K2-1-u5-X14"},{"t":"「비 / 가 / 그쳤어요. 하늘에 무지개가 떴어요.」","mis":"K2-1-u5-X11"}],"explanation":["두 문장 사이에서 조금 더 길게 쉬고, 뜻 덩어리로 묶어 읽었어요.","문장 사이에서 쉬지 않으면 두 문장이 섞여 들려요.","한 글자씩 끊으면 어색해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#8','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#9','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',4,'essay','teacher','「할머니께서 따뜻한 호박죽을 끓여 주셨어요.」에 「/」를 넣어 자연스럽게 띄어 읽을 곳을 표시하고, 그렇게 띄어 읽은 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C8","difficulty":4,"kind":"essay","stem":"「할머니께서 따뜻한 호박죽을 끓여 주셨어요.」에 「/」를 넣어 자연스럽게 띄어 읽을 곳을 표시하고, 그렇게 띄어 읽은 까닭을 써 보세요.","answer_guide":{"answer":"예: 할머니께서 / 따뜻한 호박죽을 / 끓여 주셨어요. — 뜻이 통하는 덩어리로 묶어 읽어야 뜻이 잘 드러나고 자연스럽기 때문이에요.","scoring_points":["「/」를 알맞은 곳에 넣었는가","낱말 가운데를 끊거나 너무 잘게 끊지 않았는가","뜻이 잘 드러난다는 까닭을 썼는가"]},"explanation":["알맞은 곳에 「/」.","뜻 덩어리 지키기.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#10','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C9',4,'essay','teacher','「숲속 음악회」를 소리 내어 읽으려고 해요. 앞부분(무대 뒤)과 끝부분(손뼉을 칠 때)을 각각 어떤 목소리로 읽을지 쓰고, 그렇게 정한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C9","difficulty":4,"kind":"essay","stem":"「숲속 음악회」를 소리 내어 읽으려고 해요. 앞부분(무대 뒤)과 끝부분(손뼉을 칠 때)을 각각 어떤 목소리로 읽을지 쓰고, 그렇게 정한 까닭을 써 보세요.","answer_guide":{"answer":"예: 무대 뒤 장면은 작고 떨리는 목소리로 읽을래요. 아기 곰이 떨렸으니까요. 끝부분은 밝고 힘찬 목소리로 읽을래요. 아기 곰이 뿌듯했으니까요.","scoring_points":["앞부분의 목소리를 정해 썼는가","끝부분의 목소리를 정해 썼는가","아기 곰의 마음을 까닭으로 들었는가"]},"explanation":["앞부분 목소리.","끝부분 목소리.","마음을 까닭으로."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#1','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',1,'mc','auto','마음 사전에 적을 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],true,'{"seq":1,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"마음 사전에 적을 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"마음을 나타내는 말과 그 마음이 드는 상황","correct":true},{"t":"친구들의 전화번호","mis":"K2-1-u5-X05"},{"t":"좋아하는 음식 이름","mis":"K2-1-u5-X05"}],"explanation":["마음 사전에는 「뿌듯하다 — 줄넘기를 처음 성공했을 때」처럼 적어요.","전화번호나 음식 이름은 마음 말이 아니에요.","마음 말과 상황을 함께 적어요."],"variant_rule":{"alt":[{"stem":"마음을 나타내는 말을 많이 알면 어떤 점이 좋을까요?","options":[{"t":"내 마음을 더 잘 표현할 수 있어요","correct":true},{"t":"글자를 더 빨리 쓸 수 있어요","mis":"K2-1-u5-X05"},{"t":"친구의 마음을 몰라도 돼요","mis":"K2-1-u5-X16"}],"explanation":["마음 말을 많이 알면 내 마음을 알맞게 나타낼 수 있어요.","빨리 쓰는 것과는 상관없어요.","친구의 마음을 헤아리는 데도 도움이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#2','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',1,'mc','auto','친구가 무거운 짐을 함께 들어 주었어요. 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],true,'{"seq":2,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 무거운 짐을 함께 들어 주었어요. 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「도와줘서 고마워.」","correct":true},{"t":"「몰라, 됐어.」","mis":"K2-1-u5-X16"},{"t":"「왜 이제 왔어?」","mis":"K2-1-u5-X16"}],"explanation":["도움을 받았을 때는 고마운 마음을 말로 전해요.","「몰라, 됐어.」에는 마음이 담겨 있지 않아요.","탓하는 말은 친구를 속상하게 해요."],"variant_rule":{"alt":[{"stem":"내가 실수로 친구의 발을 밟았어요. 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「미안해, 많이 아프지?」","correct":true},{"t":"「네가 거기 서 있었잖아.」","mis":"K2-1-u5-X16"},{"t":"「하하, 괜찮지?」","mis":"K2-1-u5-X16"}],"explanation":["잘못했을 때는 미안한 마음을 말로 전하고 친구 마음을 살펴요.","친구를 탓하면 마음이 전해지지 않아요.","웃어넘기면 친구가 속상해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#3','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',1,'ox','auto','「기분 나빠!」보다 「네가 내 말을 안 들어 줘서 서운했어.」라고 하면 마음이 더 잘 전해져요.',ARRAY['K2-1-u5-X16']::text[],true,'{"seq":3,"concept":"K2-1-u5-C10","difficulty":1,"kind":"ox","stem":"「기분 나빠!」보다 「네가 내 말을 안 들어 줘서 서운했어.」라고 하면 마음이 더 잘 전해져요.","answer":"O","reason_options":[{"t":"무슨 일 때문에 어떤 마음인지 정확히 알려 주니까","correct":true},{"t":"짧게 화를 내야 마음이 잘 전해지니까","mis":"K2-1-u5-X16"}],"mis":"K2-1-u5-X16","explanation":["「서운했어」처럼 마음 말로 정확히 말하면 친구가 잘 알아들어요.","무슨 일 때문인지도 함께 말해요.","화를 내면 마음이 잘 전해지지 않아요."],"variant_rule":{"alt":[{"stem":"친구가 「오늘 속상했어.」라고 할 때 「그게 뭐가 속상해?」라고 하면 친구의 마음을 헤아린 말이에요.","answer":"X","reason_options":[{"t":"「속상했겠다.」처럼 마음을 알아주는 말이 친구를 위로하니까","correct":true},{"t":"친구의 마음은 내가 정해 주어야 하니까","mis":"K2-1-u5-X16"}],"explanation":["「그게 뭐가 속상해?」는 친구의 마음을 무시하는 말이에요.","「속상했겠다.」처럼 마음을 알아주어요.","내가 그 말을 들으면 어떨지 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#4','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C5',1,'mc','auto','「소풍 가기 전날 밤」의 마음을 나타내는 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],true,'{"seq":4,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"「소풍 가기 전날 밤」의 마음을 나타내는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"서운하다","mis":"K2-1-u5-X06"},{"t":"미안하다","mis":"K2-1-u5-X06"}],"explanation":["기다리던 소풍을 앞두면 설레는 마음이 들어요.","「서운하다」는 섭섭할 때의 마음이에요.","「미안하다」는 잘못했을 때의 마음이에요."],"variant_rule":{"alt":[{"stem":"「상을 받았을 때」의 마음을 나타내는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"뿌듯하다","correct":true},{"t":"억울하다","mis":"K2-1-u5-X06"},{"t":"외롭다","mis":"K2-1-u5-X06"}],"explanation":["열심히 해서 상을 받으면 뿌듯한 마음이 들어요.","「억울하다」는 잘못 없이 혼날 때의 마음이에요.","「외롭다」는 혼자일 때의 마음이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#5','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',2,'match','auto','친구의 말과 마음을 헤아린 맞장구를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C10","difficulty":2,"kind":"match","stem":"친구의 말과 마음을 헤아린 맞장구를 알맞게 이어 보세요.","pairs":[{"l":"「할머니 댁에 못 가게 됐어.」","r":"「많이 아쉽겠다.」"},{"l":"「줄넘기 백 번 넘었어!」","r":"「우아, 정말 대단하다!」"},{"l":"「무서운 꿈을 꿨어.」","r":"「많이 놀랐겠다.」"}],"mis":"K2-1-u5-X16","explanation":["못 가게 된 친구에게는 아쉬운 마음을 알아주어요.","해낸 친구에게는 기쁨을 함께해요.","무서운 꿈을 꾼 친구에게는 놀란 마음을 알아주어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구의 말과 마음을 헤아린 맞장구를 알맞게 이어 보세요.","pairs":[{"l":"「강아지가 아파.」","r":"「많이 걱정되겠다.」"},{"l":"「상을 받았어!」","r":"「우아, 정말 축하해!」"},{"l":"「넘어져서 아파.」","r":"「많이 아팠겠다, 괜찮아?」"}],"explanation":["강아지가 아픈 친구에게는 걱정하는 마음을 알아주어요.","상을 받은 친구에게는 축하해요.","넘어진 친구에게는 아픈 마음을 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#6','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',2,'mc','auto','친구가 「동생이 내 그림을 찢었어.」라고 말했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],true,'{"seq":6,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「동생이 내 그림을 찢었어.」라고 말했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「정말 속상했겠다.」","correct":true},{"t":"「그림은 또 그리면 되잖아.」","mis":"K2-1-u5-X16"},{"t":"「하하, 재밌다!」","mis":"K2-1-u5-X16"}],"explanation":["친구의 속상한 마음을 알아주는 말이에요.","「또 그리면 되잖아」는 친구 마음을 가볍게 넘겨요.","웃으면 친구가 더 속상해요."],"variant_rule":{"alt":[{"stem":"친구가 「내일 이사 가서 전학 가.」라고 말했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「많이 섭섭하다. 가서도 꼭 연락하자.」","correct":true},{"t":"「잘됐네, 내 자리가 넓어지겠다.」","mis":"K2-1-u5-X16"},{"t":"「그래서 뭐?」","mis":"K2-1-u5-X16"}],"explanation":["헤어지는 섭섭한 마음을 함께 나누는 말이에요.","친구의 마음을 생각하지 않은 말은 속상하게 해요.","「그래서 뭐?」에는 마음이 담겨 있지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#7','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',2,'blank','auto','쪽지에 들어갈 마음 말로 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#8','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C5',2,'sa','auto','「앞으로 일어날 일이 기대되어 가슴이 두근거리다」라는 뜻의 마음 말을 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C5","difficulty":2,"kind":"sa","stem":"「앞으로 일어날 일이 기대되어 가슴이 두근거리다」라는 뜻의 마음 말을 세 글자로 써 보세요.","answer":["설레다"],"explanation":["소풍 전날처럼 기대될 때의 마음은 「설레다」예요.","「설레요」·「설레는」처럼 바꾸어 쓸 수 있어요.","마음 사전에 상황과 함께 적어 봐요."],"variant_rule":{"alt":[{"stem":"「일이 뜻대로 되지 않아 마음이 상하다」라는 뜻의 마음 말을 네 글자로 써 보세요.","answer":["속상하다"],"explanation":["아끼던 물건이 부서졌을 때처럼 마음이 상하는 것은 「속상하다」예요.","「속상해요」처럼 바꾸어 쓸 수 있어요.","마음 사전에 상황과 함께 적어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#9','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',2,'mc','auto','마음을 나타내는 말로 마음을 전하면 어떤 점이 좋을까요?',ARRAY['K2-1-u5-X16']::text[],true,'{"seq":9,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"마음을 나타내는 말로 마음을 전하면 어떤 점이 좋을까요?","options":[{"t":"서로의 마음을 잘 알아 더 가까워져요","correct":true},{"t":"친구가 내 말을 무조건 따라요","mis":"K2-1-u5-X16"},{"t":"마음은 말하지 않아야 더 잘 전해져요","mis":"K2-1-u5-X16"}],"explanation":["마음 말로 전하면 서로의 마음을 알게 돼요.","친구를 마음대로 하려는 것이 아니에요.","말하지 않으면 마음이 잘 전해지지 않아요."],"variant_rule":{"alt":[{"stem":"친구의 마음 말을 들었을 때 나는 어떻게 하면 좋을까요?","options":[{"t":"친구의 마음을 헤아려 알맞게 대답해요","correct":true},{"t":"못 들은 척하고 내 이야기만 해요","mis":"K2-1-u5-X16"},{"t":"친구의 마음이 틀렸다고 말해요","mis":"K2-1-u5-X16"}],"explanation":["친구의 마음을 헤아려 대답하면 친구가 위로받아요.","못 들은 척하면 친구가 서운해요.","마음은 맞고 틀린 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#10','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',3,'error','auto','서아의 말을 듣고 친구들이 대답했어요. 서아의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"서아의 말을 듣고 친구들이 대답했어요. 서아의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"민지 — 「그걸 왜 틀려? 쉬운 거잖아.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"로아 — 「많이 부끄러웠겠다. 나도 그런 적 있어.」","mis":"K2-1-u5-X17"},{"t":"지우 — 「괜찮아, 끝까지 발표한 게 멋졌어.」","mis":"K2-1-u5-X17"}],"explanation":["「그걸 왜 틀려?」는 서아를 더 부끄럽게 해요.","로아와 지우는 서아의 마음을 알아주었어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"오늘 발표하다가 틀려서 너무 부끄러웠어."}]},"variant_rule":{"alt":[{"stem":"하준이의 말을 듣고 친구들이 대답했어요. 하준이의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"시우 — 「강아지는 원래 자주 아파.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"예린 — 「많이 걱정되겠다.」","mis":"K2-1-u5-X17"},{"t":"도담 — 「강아지가 얼른 나으면 좋겠다.」","mis":"K2-1-u5-X17"}],"explanation":["「원래 자주 아파.」는 하준이의 걱정하는 마음을 알아주지 않아요.","예린이와 도담이는 하준이의 마음을 헤아렸어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"우리 강아지가 아파서 병원에 갔어."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#1','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',2,'mc','auto','마음 사전의 한 칸을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u5-X06','K2-1-u5-X05']::text[],false,'{"seq":1,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"마음 사전의 한 칸을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"「뿌듯하다 — 줄넘기를 처음 백 번 넘었을 때」","correct":true},{"t":"「뿌듯하다 — 친구가 약속을 어겼을 때」","mis":"K2-1-u5-X06"},{"t":"「연필 — 글씨를 쓸 때」","mis":"K2-1-u5-X05"}],"explanation":["「뿌듯하다」는 무언가를 해냈을 때의 마음이에요.","약속을 어겼을 때는 「서운하다」가 어울려요.","「연필」은 마음 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#2','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',2,'mc','auto','「기분 나빠!」를 마음이 더 잘 전해지게 바꾼 말은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":2,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"「기분 나빠!」를 마음이 더 잘 전해지게 바꾼 말은 어느 것인가요?","options":[{"t":"「네가 내 차례를 건너뛰어서 서운했어.」","correct":true},{"t":"「몰라, 됐어.」","mis":"K2-1-u5-X16"},{"t":"「너랑 다시는 안 놀아!」","mis":"K2-1-u5-X16"}],"explanation":["무슨 일 때문에 어떤 마음인지 마음 말로 정확히 말했어요.","「몰라, 됐어.」에는 마음이 담겨 있지 않아요.","화를 내는 말은 마음을 잘 전하지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#3','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C5',3,'error','auto','마음 말을 넣어 문장을 만들었어요. 마음 말을 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X06','K2-1-u5-X17']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":3,"kind":"error","stem":"마음 말을 넣어 문장을 만들었어요. 마음 말을 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"하람 — 「내일 놀이공원에 가서 너무 서운해.」","correct":true,"mis_target":"K2-1-u5-X06"},{"t":"현우 — 「친구가 도와줘서 고마웠어.」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「짝이 전학 가서 섭섭해.」","mis":"K2-1-u5-X17"}],"explanation":["놀이공원에 가기 전에는 「설레다」가 어울려요.","「서운하다」는 섭섭할 때의 마음이에요.","현우와 서윤이는 알맞게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#4','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',3,'mc','auto','대화를 읽고 답해 보세요. 도윤이에게 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":4,"concept":"K2-1-u5-C10","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이에게 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「많이 서운했겠다. 다음엔 나랑 같이 가자.」","correct":true},{"t":"「그런 일로 뭘 그래.」","mis":"K2-1-u5-X16"},{"t":"「나도 같이 갔었는데 정말 재밌었어!」","mis":"K2-1-u5-X16"}],"explanation":["도윤이의 서운한 마음을 알아주고 함께하자고 했어요.","「뭘 그래」는 도윤이의 마음을 무시하는 말이에요.","자랑하면 도윤이가 더 서운해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"나만 빼고 다 같이 놀러 갔대……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#5','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',3,'ox','auto','쪽지에 마음을 나타내는 말을 넣으면 받는 친구가 내 마음을 더 잘 알 수 있어요.',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":5,"concept":"K2-1-u5-C10","difficulty":3,"kind":"ox","stem":"쪽지에 마음을 나타내는 말을 넣으면 받는 친구가 내 마음을 더 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"「고마웠어」·「미안해」처럼 마음이 분명하게 드러나니까","correct":true},{"t":"마음 말은 쪽지에 쓰지 않는 것이 좋으니까","mis":"K2-1-u5-X16"}],"mis":"K2-1-u5-X16","explanation":["마음 말을 넣으면 마음이 분명해져요.","받는 친구가 내 마음을 잘 알 수 있어요.","있었던 일도 함께 쓰면 더 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#6','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C5',3,'mc','auto','뜻이 비슷한 마음 말끼리 짝지은 것은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":6,"concept":"K2-1-u5-C5","difficulty":3,"kind":"mc","stem":"뜻이 비슷한 마음 말끼리 짝지은 것은 어느 것인가요?","options":[{"t":"서운하다 · 섭섭하다","correct":true},{"t":"서운하다 · 설레다","mis":"K2-1-u5-X06"},{"t":"고맙다 · 미안하다","mis":"K2-1-u5-X06"}],"explanation":["「서운하다」와 「섭섭하다」는 비슷한 마음이에요.","「설레다」는 기대될 때의 마음이에요.","「고맙다」와 「미안하다」는 서로 다른 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#7','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',3,'mc','auto','친구가 「받아쓰기 백 점 받았어!」라고 했어요. 마음을 헤아린 대답으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":7,"concept":"K2-1-u5-C10","difficulty":3,"kind":"mc","stem":"친구가 「받아쓰기 백 점 받았어!」라고 했어요. 마음을 헤아린 대답으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「우아, 정말 기쁘겠다! 열심히 연습하더니 멋지다.」","correct":true},{"t":"「나도 전에 백 점 받았거든.」","mis":"K2-1-u5-X16"},{"t":"「이번 받아쓰기는 쉬웠잖아.」","mis":"K2-1-u5-X16"}],"explanation":["친구의 기쁜 마음을 함께 나누는 말이에요.","내 자랑만 하면 친구의 기쁨을 알아주지 못해요.","쉬웠다고 하면 친구가 서운해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#8','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',4,'mc','auto','마음을 담은 쪽지에 들어갈 것으로 모두 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X05']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":4,"kind":"mc","stem":"마음을 담은 쪽지에 들어갈 것으로 모두 알맞은 것은 어느 것인가요?","options":[{"t":"받는 사람 · 있었던 일 · 내 마음을 나타내는 말","correct":true},{"t":"받는 사람 · 친구 흉 · 내 마음","mis":"K2-1-u5-X16"},{"t":"오늘 날씨 · 급식 메뉴 · 시간표","mis":"K2-1-u5-X05"}],"explanation":["누구에게, 무슨 일로, 어떤 마음인지 써야 마음이 잘 전해져요.","친구 흉은 마음을 전하는 쪽지에 어울리지 않아요.","날씨나 급식 메뉴는 마음을 전하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#9','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',4,'essay','teacher','고마웠거나 미안했던 친구에게 마음을 담은 쪽지를 써 보세요. 받는 사람, 있었던 일, 마음을 나타내는 말이 들어가게 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C10","difficulty":4,"kind":"essay","stem":"고마웠거나 미안했던 친구에게 마음을 담은 쪽지를 써 보세요. 받는 사람, 있었던 일, 마음을 나타내는 말이 들어가게 써 보세요.","answer_guide":{"answer":"예: 하린아, 어제 내가 넘어졌을 때 일으켜 줘서 정말 고마웠어. 다음엔 내가 꼭 도와줄게.","scoring_points":["받는 사람을 썼는가","있었던 일을 썼는가","마음을 나타내는 말을 넣었는가"]},"explanation":["받는 사람.","있었던 일.","마음 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#10','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',4,'essay','teacher','친구가 「오늘 속상했어.」라고 말했어요. 친구의 마음을 헤아려 어떻게 대답할지 두 문장으로 쓰고, 그렇게 대답한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C10","difficulty":4,"kind":"essay","stem":"친구가 「오늘 속상했어.」라고 말했어요. 친구의 마음을 헤아려 어떻게 대답할지 두 문장으로 쓰고, 그렇게 대답한 까닭을 써 보세요.","answer_guide":{"answer":"예: 「많이 속상했겠다. 무슨 일 있었어?」 — 친구의 마음을 먼저 알아주면 친구가 위로받고 이야기를 꺼낼 수 있기 때문이에요.","scoring_points":["친구의 마음을 알아주는 맞장구를 썼는가","두 문장으로 썼는가","마음을 헤아려 대답한 까닭을 썼는가"]},"explanation":["맞장구.","두 문장.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#1','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C1',1,'mc','auto','다른 사람의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X01']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"다른 사람의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"말 · 행동 · 표정 · 상황","correct":true},{"t":"옷 색깔 · 키 · 신발","mis":"K2-1-u5-X01"},{"t":"이름 · 나이 · 머리 모양","mis":"K2-1-u5-X01"}],"explanation":["마음은 말·행동·표정·상황에서 드러나요.","생김새·옷·이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#2','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C3',1,'mc','auto','「드디어 됐다!」 하며 두 손을 번쩍 들었어요. 이 인물의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"「드디어 됐다!」 하며 두 손을 번쩍 들었어요. 이 인물의 마음은 어느 것인가요?","options":[{"t":"기쁜 마음","correct":true},{"t":"속상한 마음","mis":"K2-1-u5-X02"},{"t":"무서운 마음","mis":"K2-1-u5-X02"}],"explanation":["두 손을 번쩍 드는 행동에서 기쁜 마음이 드러나요.","다른 마음은 이 말·행동과 맞지 않아요.","행동을 따라 해 보며 마음을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#3','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"연필","mis":"K2-1-u5-X05"},{"t":"운동장","mis":"K2-1-u5-X05"}],"explanation":["「설레다」는 마음을 나타내는 말이에요.","「연필」·「운동장」은 물건·장소·움직임을 나타내요.","「나는 지금 ○○해.」에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#4','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「동생이 / 우유를 / 마신다」","correct":true},{"t":"「동 / 생이우 / 유를 마신다」","mis":"K2-1-u5-X11"},{"t":"「동생이우유를마신다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#5','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',1,'mc','auto','「걸음」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「걸음」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"발을 옮겨 걷는 것","correct":true},{"t":"식물을 잘 자라게 하는 흙","mis":"K2-1-u5-X09"},{"t":"하던 일을 끝내는 것","mis":"K2-1-u5-X09"}],"explanation":["「걸음」은 발을 옮겨 걷는 것는 뜻이에요.","다른 뜻은 소리가 같거나 비슷한 다른 낱말의 뜻이에요.","소리가 같아도 뜻을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#6','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C8',1,'ox','auto','낱말마다 뚝뚝 끊어 읽으면 글이 자연스럽게 들려요.',ARRAY['K2-1-u5-X11']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"낱말마다 뚝뚝 끊어 읽으면 글이 자연스럽게 들려요.","answer":"X","reason_options":[{"t":"뜻이 통하는 덩어리로 묶어 읽어야 자연스러우니까","correct":true},{"t":"낱말마다 끊어야 또박또박 들리니까","mis":"K2-1-u5-X11"}],"mis":"K2-1-u5-X11","explanation":["낱말마다 끊으면 뜻이 끊겨 어색해요.","뜻이 통하는 덩어리로 묶어 읽어요.","그러면 물 흐르듯 자연스럽게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#7','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C9',1,'mc','auto','인물이 기쁜 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 기쁜 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"밝고 가볍게","correct":true},{"t":"차분하고 느리게","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["인물이 기쁜 장면은 밝고 가볍게 읽으면 마음이 살아나요.","다른 목소리는 이 장면의 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#8','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C10',1,'mc','auto','친구가 무거운 짐을 함께 들어 주었어요. 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 무거운 짐을 함께 들어 주었어요. 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「도와줘서 고마워.」","correct":true},{"t":"「몰라, 됐어.」","mis":"K2-1-u5-X16"},{"t":"「왜 이제 왔어?」","mis":"K2-1-u5-X16"}],"explanation":["도움을 받았을 때는 고마운 마음을 전해요.","마음이 담기지 않은 말이나 탓하는 말은 친구를 속상하게 해요.","마음 말로 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#9','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"생일 선물을 받았을 때","r":"기쁘다"},{"l":"아끼던 장난감이 부서졌을 때","r":"속상하다"},{"l":"내일 소풍을 가기로 했을 때","r":"설레다"}],"mis":"K2-1-u5-X03","explanation":["「생일 선물을 받았을 때」 — 기쁘다","「아끼던 장난감이 부서졌을 때」 — 속상하다","「내일 소풍을 가기로 했을 때」 — 설레다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#10','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',2,'blank','auto','「텃밭의 상추가 잘 자라도록 (     )을 주었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「텃밭의 상추가 잘 자라도록 (     )을 주었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"거름","correct":true},{"t":"걸음","mis":"K2-1-u5-X09"},{"t":"거럼","mis":"K2-1-u5-X09"}],"explanation":["식물을 잘 자라게 하는 흙은 「거름」이에요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#11','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 지안이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":11,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"무섭다 → 용기를 내다 → 신나다","correct":true},{"t":"신나다 → 무섭다 → 용기를 내다","mis":"K2-1-u5-X07"},{"t":"무섭다 → 무섭다 → 무섭다","mis":"K2-1-u5-X07"}],"explanation":["처음에는 무서웠고, 하람이 말에 용기를 내었고, 나중에는 신났어요.","차례를 뒤바꾸거나 마음이 그대로라고 보면 안 돼요.","처음 → 무슨 일 → 나중을 따라가요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#12','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 서준이가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":12,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"입술을 삐죽 내밀었어요","correct":true},{"t":"「와, 해냈다!」 하며 손뼉을 쳤어요","mis":"K2-1-u5-X02"},{"t":"종이비행기를 접었어요","mis":"K2-1-u5-X08"}],"explanation":["입술을 삐죽 내미는 행동에 속상한 마음이 드러나요.","다른 마음이 드러난 부분이나 일어난 일과 헷갈리지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#13','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',2,'ox','auto','「종이 울려서 수업을 맞혔어요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":13,"concept":"K2-1-u5-C7","difficulty":2,"kind":"ox","stem":"「종이 울려서 수업을 맞혔어요.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"하던 일을 끝내는 것은 「마치다」라서 「마쳤어요」라고 써야 하니까","correct":true},{"t":"소리가 같으면 아무 낱말이나 써도 되니까","mis":"K2-1-u5-X09"}],"mis":"K2-1-u5-X09","explanation":["수업을 끝내는 것은 「마치다」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#14','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C8',2,'mc','auto','「나는 오늘 도서관에서 책을 읽었다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":14,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「나는 오늘 도서관에서 책을 읽었다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「나는 / 오늘 도서관에서 / 책을 읽었다」","correct":true},{"t":"「나 / 는 / 오늘 / 도서 / 관에서 / 책을 읽었다」","mis":"K2-1-u5-X11"},{"t":"「나는 오늘 도 / 서관에서 책을 / 읽었다」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","낱말 가운데에서 끊거나 덩어리를 흩뜨리면 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#15','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C10',2,'mc','auto','친구가 「동생이 내 그림을 찢었어.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":15,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「동생이 내 그림을 찢었어.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「정말 속상했겠다.」","correct":true},{"t":"「그림은 또 그리면 되잖아.」","mis":"K2-1-u5-X16"},{"t":"「하하, 재밌다!」","mis":"K2-1-u5-X16"}],"explanation":["친구의 속상한 마음을 알아주는 말이에요.","친구의 마음을 가볍게 넘기거나 놀리는 말은 친구를 더 속상하게 해요.","내가 그 말을 들으면 어떨지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#16','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C5',2,'match','auto','마음을 나타내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"마음을 나타내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"설레다","r":"앞으로 일어날 일이 기대되어 두근거리다"},{"l":"뿌듯하다","r":"해낸 일이 자랑스러워 마음이 꽉 차다"},{"l":"서운하다","r":"바라던 대로 되지 않아 섭섭하다"}],"mis":"K2-1-u5-X06","explanation":["「설레다」 — 앞으로 일어날 일이 기대되어 두근거리다","「뿌듯하다」 — 해낸 일이 자랑스러워 마음이 꽉 차다","「서운하다」 — 바라던 대로 되지 않아 섭섭하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#17','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X09','K2-1-u5-X17']::text[],false,'{"seq":17,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"하준 — 「반듯이 숙제를 하고 놀 거예요.」","correct":true,"mis_target":"K2-1-u5-X09"},{"t":"예린 — 「의자에 반듯이 앉았어요.」","mis":"K2-1-u5-X17"},{"t":"소율 — 「숙제를 마치고 놀았어요.」","mis":"K2-1-u5-X17"}],"explanation":["「꼭」이라는 뜻은 「반드시」라고 써야 해요.","다른 두 친구는 뜻에 맞게 바르게 썼어요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#18','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C6',3,'error','auto','글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],false,'{"seq":18,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「지안이는 처음부터 수영장이 하나도 무섭지 않았어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"예린 — 「처음에는 엄마 손을 꼭 잡을 만큼 무서웠어.」","mis":"K2-1-u5-X17"},{"t":"현우 — 「나중에는 물장구를 치며 신났어.」","mis":"K2-1-u5-X17"}],"explanation":["지안이는 처음에 물이 깊어 보여 무서워했어요.","마음은 처음 그대로 있지 않고 일에 따라 바뀌었어요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#19','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C8',3,'mc','auto','물을 달라는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":19,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"물을 달라는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「나 / 물 좀 주세요」","correct":true},{"t":"「나물 / 좀 주세요」","mis":"K2-1-u5-X13"},{"t":"「나물좀 / 주세요」","mis":"K2-1-u5-X13"}],"explanation":["「나 / 물 좀 주세요」로 읽어야 물을 달라는 뜻이 돼요.","어디에서 쉬느냐에 따라 뜻이 달라져요.","끊어 읽은 대로 그림을 떠올려 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#20','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C4',3,'mc','auto','「언니가 쌓은 블록 탑을 동생이 실수로 무너뜨렸어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":20,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"「언니가 쌓은 블록 탑을 동생이 실수로 무너뜨렸어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"언니는 속상하고, 동생은 미안해요","correct":true},{"t":"언니는 미안하고, 동생은 속상해요","mis":"K2-1-u5-X04"},{"t":"언니는 신나고, 동생은 뿌듯해요","mis":"K2-1-u5-X03"}],"explanation":["탑이 무너진 언니는 속상하고, 무너뜨린 동생은 미안할 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#21','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C10',3,'error','auto','친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],false,'{"seq":21,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"민지 — 「그걸 왜 틀려? 쉬운 거잖아.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"로아 — 「많이 부끄러웠겠다. 나도 그런 적 있어.」","mis":"K2-1-u5-X17"},{"t":"지우 — 「괜찮아, 끝까지 발표한 게 멋졌어.」","mis":"K2-1-u5-X17"}],"explanation":["「그걸 왜 틀려?」는 서아를 더 부끄럽게 해요.","다른 두 친구는 마음을 알아주는 맞장구를 쳤어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"오늘 발표하다가 틀려서 너무 부끄러웠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#22','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C3',3,'mc','auto','「괜찮아.」라고 말하면서 손으로 눈물을 훔쳤어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":22,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「괜찮아.」라고 말하면서 손으로 눈물을 훔쳤어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 괜찮다고 했지만 사실은 속상한 마음","correct":true},{"t":"말 그대로 정말 괜찮고 기쁜 마음","mis":"K2-1-u5-X02"},{"t":"졸리고 심심한 마음","mis":"K2-1-u5-X03"}],"explanation":["눈물을 훔치는 행동에서 속상한 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","다른 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#23','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#24','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',4,'essay','teacher','다음 문장에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 낱말의 뜻을 들어 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#25','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C6',4,'essay','teacher','글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.","answer_guide":{"answer":"예: 처음에는 무서웠어요(엄마 손을 꼭 잡음). 하람이가 같이 들어가자고 해서 용기를 냈고, 끝에는 신났어요(깔깔 웃으며 물장구).","scoring_points":["처음과 끝의 마음을 마음 말로 썼는가","마음이 바뀐 까닭을 글에서 찾아 썼는가","근거가 된 말이나 행동을 썼는가"]},"explanation":["처음과 끝의 마음.","바뀐 까닭.","근거."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#1','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C1',1,'mc','auto','「마음 짐작하기」를 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u5-X01']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"「마음 짐작하기」를 바르게 말한 것은 어느 것인가요?","options":[{"t":"말과 행동을 보고 어떤 마음인지 헤아리는 것","correct":true},{"t":"얼굴 생김새로 이름을 맞히는 것","mis":"K2-1-u5-X01"},{"t":"친구의 키를 재어 보는 것","mis":"K2-1-u5-X01"}],"explanation":["마음 짐작은 말·행동·표정·상황을 보고 마음을 헤아리는 거예요.","생김새·옷·이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#2','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C3',1,'mc','auto','고개를 푹 숙이고 작은 목소리로 「미안해.」 했어요. 이 인물의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"고개를 푹 숙이고 작은 목소리로 「미안해.」 했어요. 이 인물의 마음은 어느 것인가요?","options":[{"t":"미안한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u5-X02"},{"t":"뿌듯한 마음","mis":"K2-1-u5-X02"}],"explanation":["고개를 숙이고 「미안해.」 한 말과 행동에서 미안한 마음이 드러나요.","다른 마음은 이 말·행동과 맞지 않아요.","행동을 따라 해 보며 마음을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#3','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"뿌듯하다","correct":true},{"t":"의자","mis":"K2-1-u5-X05"},{"t":"달리다","mis":"K2-1-u5-X05"}],"explanation":["「뿌듯하다」는 마음을 나타내는 말이에요.","「의자」·「달리다」는 물건·장소·움직임을 나타내요.","「나는 지금 ○○해.」에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#4','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「하늘에 / 무지개가 / 떴다」","correct":true},{"t":"「하 / 늘에무 / 지개가 떴다」","mis":"K2-1-u5-X11"},{"t":"「하늘에무지개가떴다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#5','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',1,'mc','auto','「다치다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「다치다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸에 상처를 입다","correct":true},{"t":"열려 있던 것이 막히다","mis":"K2-1-u5-X09"},{"t":"목표에 닿게 하다","mis":"K2-1-u5-X09"}],"explanation":["「다치다」는 몸에 상처를 입다는 뜻이에요.","다른 뜻은 소리가 같거나 비슷한 다른 낱말의 뜻이에요.","소리가 같아도 뜻을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#6','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C8',1,'ox','auto','긴 문장을 한 번도 쉬지 않고 읽으면 숨이 차고 뜻을 알기 어려워요.',ARRAY['K2-1-u5-X12']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"긴 문장을 한 번도 쉬지 않고 읽으면 숨이 차고 뜻을 알기 어려워요.","answer":"O","reason_options":[{"t":"뜻 덩어리 사이에서 쉬어야 숨도 고르고 뜻도 드러나니까","correct":true},{"t":"쉬지 않고 빨리 읽을수록 잘 읽은 것이니까","mis":"K2-1-u5-X12"}],"mis":"K2-1-u5-X12","explanation":["쉬지 않으면 듣는 사람도 알아듣기 어려워요.","뜻이 통하는 덩어리로 묶어 읽어요.","그러면 물 흐르듯 자연스럽게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#7','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C9',1,'mc','auto','인물이 슬픈 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 슬픈 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"차분하고 느리게","correct":true},{"t":"밝고 빠르게","mis":"K2-1-u5-X15"},{"t":"크게 소리 지르며","mis":"K2-1-u5-X15"}],"explanation":["인물이 슬픈 장면은 차분하고 느리게 읽으면 마음이 살아나요.","다른 목소리는 이 장면의 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#8','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C10',1,'mc','auto','내가 실수로 친구의 발을 밟았어요. 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"내가 실수로 친구의 발을 밟았어요. 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「미안해, 많이 아프지?」","correct":true},{"t":"「네가 거기 서 있었잖아.」","mis":"K2-1-u5-X16"},{"t":"「하하, 괜찮지?」","mis":"K2-1-u5-X16"}],"explanation":["잘못했을 때는 미안한 마음을 전해요.","마음이 담기지 않은 말이나 탓하는 말은 친구를 속상하게 해요.","마음 말로 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#9','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"친구가 넘어진 나를 일으켜 주었을 때","r":"고맙다"},{"l":"내가 친구 발을 밟았을 때","r":"미안하다"},{"l":"발표 차례를 기다릴 때","r":"떨리다"}],"mis":"K2-1-u5-X03","explanation":["「친구가 넘어진 나를 일으켜 주었을 때」 — 고맙다","「내가 친구 발을 밟았을 때」 — 미안하다","「발표 차례를 기다릴 때」 — 떨리다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#10','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',2,'blank','auto','「선생님께서 우리에게 한글을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「선생님께서 우리에게 한글을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"가르쳐 주셨어요","correct":true},{"t":"가리켜 주셨어요","mis":"K2-1-u5-X10"},{"t":"가르켜 주셨어요","mis":"K2-1-u5-X09"}],"explanation":["모르는 것을 알려 주는 것은 「가르치다」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#11','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 아기 곰의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":11,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 아기 곰의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"떨리다 → 힘이 나다 → 뿌듯하다","correct":true},{"t":"뿌듯하다 → 떨리다 → 힘이 나다","mis":"K2-1-u5-X07"},{"t":"떨리다 → 떨리다 → 떨리다","mis":"K2-1-u5-X07"}],"explanation":["처음에는 떨렸고, 다람쥐 응원에 힘이 났고, 나중에는 뿌듯했어요.","차례를 뒤바꾸거나 마음이 그대로라고 보면 안 돼요.","처음 → 무슨 일 → 나중을 따라가요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#12','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 동생이 미안한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":12,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 동생이 미안한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"고개를 숙이고 「언니, 미안해.」 했어요","correct":true},{"t":"할머니가 활짝 웃으셨어요","mis":"K2-1-u5-X02"},{"t":"할머니 생신 선물로 카드를 만들었어요","mis":"K2-1-u5-X08"}],"explanation":["고개를 숙이고 「미안해.」 한 말과 행동에 미안한 마음이 드러나요.","다른 마음이 드러난 부분이나 일어난 일과 헷갈리지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#13','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',2,'ox','auto','「넘어져서 무릎을 다쳤어요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":13,"concept":"K2-1-u5-C7","difficulty":2,"kind":"ox","stem":"「넘어져서 무릎을 다쳤어요.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"몸에 상처를 입은 것은 「다치다」니까","correct":true},{"t":"소리가 같으면 「닫혔어요」라고 써도 되니까","mis":"K2-1-u5-X09"}],"mis":"K2-1-u5-X09","explanation":["몸에 상처를 입는 것은 「다치다」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#14','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C8',2,'mc','auto','「비가 와서 우산을 썼다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":14,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「비가 와서 우산을 썼다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「비가 와서 / 우산을 썼다」","correct":true},{"t":"「비 / 가 / 와 / 서 / 우산을 썼다」","mis":"K2-1-u5-X11"},{"t":"「비가 / 와서우산을 / 썼다」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","낱말 가운데에서 끊거나 덩어리를 흩뜨리면 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#15','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C10',2,'mc','auto','친구가 「우리 강아지가 아파.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":15,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「우리 강아지가 아파.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「많이 걱정되겠다.」","correct":true},{"t":"「강아지는 원래 자주 아파.」","mis":"K2-1-u5-X16"},{"t":"「나는 강아지 안 좋아해.」","mis":"K2-1-u5-X16"}],"explanation":["친구의 걱정하는 마음을 알아주는 말이에요.","친구의 마음을 가볍게 넘기거나 놀리는 말은 친구를 더 속상하게 해요.","내가 그 말을 들으면 어떨지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#16','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C5',2,'match','auto','마음을 나타내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"마음을 나타내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"미안하다","r":"남에게 잘못하여 마음이 편하지 않다"},{"l":"고맙다","r":"남이 베풀어 준 일에 마음이 흐뭇하다"},{"l":"속상하다","r":"일이 뜻대로 되지 않아 마음이 상하다"}],"mis":"K2-1-u5-X06","explanation":["「미안하다」 — 남에게 잘못하여 마음이 편하지 않다","「고맙다」 — 남이 베풀어 준 일에 마음이 흐뭇하다","「속상하다」 — 일이 뜻대로 되지 않아 마음이 상하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#17','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X17']::text[],false,'{"seq":17,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호 — 「놀이터에서 장갑을 잊어버렸어요.」","correct":true,"mis_target":"K2-1-u5-X10"},{"t":"다은 — 「친구 생일을 잊지 않았어요.」","mis":"K2-1-u5-X17"},{"t":"시우 — 「공원에서 모자를 잃어버렸어요.」","mis":"K2-1-u5-X17"}],"explanation":["물건이 없어진 것은 「잃어버렸어요」라고 써야 해요.","다른 두 친구는 뜻에 맞게 바르게 썼어요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#18','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C6',3,'error','auto','글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],false,'{"seq":18,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"지우 — 「아기 곰은 처음부터 하나도 떨리지 않았어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"도담 — 「무대 뒤에서는 다리가 떨렸어.」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「나중에는 가슴을 펴고 웃었어.」","mis":"K2-1-u5-X17"}],"explanation":["아기 곰은 무대 뒤에서 다리가 후들후들 떨렸어요.","마음은 처음 그대로 있지 않고 일에 따라 바뀌었어요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#19','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C8',3,'mc','auto','아빠가 방에 들어가신다는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":19,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"아빠가 방에 들어가신다는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「아빠가 / 방에 들어가신다」","correct":true},{"t":"「아빠 / 가방에 들어가신다」","mis":"K2-1-u5-X13"},{"t":"「아빠가방 / 에 들어가신다」","mis":"K2-1-u5-X13"}],"explanation":["「아빠가 / 방에」로 끊어야 아빠가 방에 들어가신다는 뜻이 돼요.","어디에서 쉬느냐에 따라 뜻이 달라져요.","끊어 읽은 대로 그림을 떠올려 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#20','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C4',3,'mc','auto','「동생이 꽃병을 깨뜨렸는데 형이 대신 혼났어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":20,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"「동생이 꽃병을 깨뜨렸는데 형이 대신 혼났어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"형은 억울하고, 동생은 미안해요","correct":true},{"t":"형은 미안하고, 동생은 억울해요","mis":"K2-1-u5-X04"},{"t":"형은 설레고, 동생은 신나요","mis":"K2-1-u5-X03"}],"explanation":["대신 혼난 형은 억울하고, 깨뜨린 동생은 미안할 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#21','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C10',3,'error','auto','친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],false,'{"seq":21,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"시우 — 「그런 일로 뭘 그래.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"하린 — 「많이 서운했겠다.」","mis":"K2-1-u5-X17"},{"t":"지안 — 「다음엔 나랑 같이 가자.」","mis":"K2-1-u5-X17"}],"explanation":["「뭘 그래」는 도윤이의 서운한 마음을 무시하는 말이에요.","다른 두 친구는 마음을 알아주는 맞장구를 쳤어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"나만 빼고 다 같이 놀러 갔대……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#22','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C3',3,'mc','auto','「하나도 안 무서워!」라고 말하면서 엄마 뒤에 꼭 숨었어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":22,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「하나도 안 무서워!」라고 말하면서 엄마 뒤에 꼭 숨었어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 안 무섭다고 했지만 사실은 무서운 마음","correct":true},{"t":"말 그대로 하나도 무섭지 않은 마음","mis":"K2-1-u5-X02"},{"t":"뿌듯하고 자랑스러운 마음","mis":"K2-1-u5-X03"}],"explanation":["엄마 뒤에 숨는 행동에서 무서운 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","다른 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#23','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#24','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',4,'essay','teacher','다음 문장에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 낱말의 뜻을 들어 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#25','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C6',4,'essay','teacher','글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.","answer_guide":{"answer":"예: 처음에는 떨렸어요(다리가 후들후들). 다람쥐의 응원과 친구들의 손뼉 덕분에 끝에는 뿌듯했어요(가슴을 쭉 펴고 웃음).","scoring_points":["처음과 끝의 마음을 마음 말로 썼는가","마음이 바뀐 까닭을 글에서 찾아 썼는가","근거가 된 말이나 행동을 썼는가"]},"explanation":["처음과 끝의 마음.","바뀐 까닭.","근거."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#1','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C1',1,'mc','auto','말하지 않아도 친구의 마음을 알 수 있는 까닭은 무엇인가요?',ARRAY['K2-1-u5-X01']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"말하지 않아도 친구의 마음을 알 수 있는 까닭은 무엇인가요?","options":[{"t":"표정과 행동에 마음이 드러나니까","correct":true},{"t":"친구의 옷에 마음이 쓰여 있으니까","mis":"K2-1-u5-X01"},{"t":"친구의 이름에 마음이 들어 있으니까","mis":"K2-1-u5-X01"}],"explanation":["웃는 얼굴, 숙인 고개처럼 표정과 행동에 마음이 드러나요.","생김새·옷·이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#2','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C3',1,'mc','auto','눈을 동그랗게 뜨고 「와, 진짜?」 했어요. 이 인물의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"눈을 동그랗게 뜨고 「와, 진짜?」 했어요. 이 인물의 마음은 어느 것인가요?","options":[{"t":"놀란 마음","correct":true},{"t":"졸린 마음","mis":"K2-1-u5-X02"},{"t":"서운한 마음","mis":"K2-1-u5-X02"}],"explanation":["눈을 동그랗게 뜨고 「와, 진짜?」 한 말과 행동에서 놀란 마음이 드러나요.","다른 마음은 이 말·행동과 맞지 않아요.","행동을 따라 해 보며 마음을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#3','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"서운하다","correct":true},{"t":"가방","mis":"K2-1-u5-X05"},{"t":"학교","mis":"K2-1-u5-X05"}],"explanation":["「서운하다」는 마음을 나타내는 말이에요.","「가방」·「학교」는 물건·장소·움직임을 나타내요.","「나는 지금 ○○해.」에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#4','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「아빠가 / 방에 / 들어가신다」","correct":true},{"t":"「아 / 빠가방 / 에 들어가신다」","mis":"K2-1-u5-X11"},{"t":"「아빠가방에들어가신다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#5','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',1,'mc','auto','「마치다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「마치다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"하던 일을 끝내다","correct":true},{"t":"목표에 닿게 하다","mis":"K2-1-u5-X09"},{"t":"몸에 상처를 입다","mis":"K2-1-u5-X09"}],"explanation":["「마치다」는 하던 일을 끝내다는 뜻이에요.","다른 뜻은 소리가 같거나 비슷한 다른 낱말의 뜻이에요.","소리가 같아도 뜻을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#6','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C8',1,'ox','auto','문장과 문장 사이에서는 문장 안에서보다 조금 더 길게 쉬어 읽어요.',ARRAY['K2-1-u5-X14']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"문장과 문장 사이에서는 문장 안에서보다 조금 더 길게 쉬어 읽어요.","answer":"O","reason_options":[{"t":"한 문장이 끝났다는 것을 듣는 사람이 알 수 있으니까","correct":true},{"t":"문장 사이에서는 쉬지 않고 이어 읽어야 하니까","mis":"K2-1-u5-X14"}],"mis":"K2-1-u5-X14","explanation":["문장이 끝나면 조금 더 길게 쉬어요.","뜻이 통하는 덩어리로 묶어 읽어요.","그러면 물 흐르듯 자연스럽게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#7','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C9',1,'mc','auto','인물이 떨리는 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 떨리는 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"작고 조심스럽게","correct":true},{"t":"크고 신나게","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["인물이 떨리는 장면은 작고 조심스럽게 읽으면 마음이 살아나요.","다른 목소리는 이 장면의 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#8','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C10',1,'mc','auto','친구가 그림 대회에서 상을 받았어요. 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 그림 대회에서 상을 받았어요. 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「우아, 정말 축하해!」","correct":true},{"t":"「그게 뭐 대단해?」","mis":"K2-1-u5-X16"},{"t":"「나도 받을 수 있었어.」","mis":"K2-1-u5-X16"}],"explanation":["좋은 일이 생긴 친구에게는 축하하는 마음을 전해요.","마음이 담기지 않은 말이나 탓하는 말은 친구를 속상하게 해요.","마음 말로 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#9','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"친구가 약속을 잊어버렸을 때","r":"서운하다"},{"l":"처음으로 줄넘기 백 번을 넘었을 때","r":"뿌듯하다"},{"l":"하지 않은 일로 혼났을 때","r":"억울하다"}],"mis":"K2-1-u5-X03","explanation":["「친구가 약속을 잊어버렸을 때」 — 서운하다","「처음으로 줄넘기 백 번을 넘었을 때」 — 뿌듯하다","「하지 않은 일로 혼났을 때」 — 억울하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#10','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',2,'blank','auto','「약속은 (     ) 지킬게.」 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「약속은 (     ) 지킬게.」 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"반드시","correct":true},{"t":"반듯이","mis":"K2-1-u5-X09"},{"t":"반드기","mis":"K2-1-u5-X09"}],"explanation":["「틀림없이 꼭」이라는 뜻은 「반드시」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#11','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 우유가 쏟아진 뒤부터 지우의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":11,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 우유가 쏟아진 뒤부터 지우의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하다 → 따뜻하다","correct":true},{"t":"따뜻하다 → 속상하다","mis":"K2-1-u5-X07"},{"t":"속상하다 → 속상하다","mis":"K2-1-u5-X07"}],"explanation":["우유가 쏟아져 속상했다가, 할머니가 웃으셔서 마음이 따뜻해졌어요.","차례를 뒤바꾸거나 마음이 그대로라고 보면 안 돼요.","처음 → 무슨 일 → 나중을 따라가요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#12','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 지안이가 무서운 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":12,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이가 무서운 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"엄마 손을 꼭 잡았어요","correct":true},{"t":"깔깔 웃었어요","mis":"K2-1-u5-X02"},{"t":"수영장에 갔어요","mis":"K2-1-u5-X08"}],"explanation":["엄마 손을 꼭 잡은 행동에 무서운 마음이 드러나요.","다른 마음이 드러난 부분이나 일어난 일과 헷갈리지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#13','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',2,'ox','auto','「쌍둥이 형제는 얼굴이 조금 틀려요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":13,"concept":"K2-1-u5-C7","difficulty":2,"kind":"ox","stem":"「쌍둥이 형제는 얼굴이 조금 틀려요.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"같지 않은 것은 「다르다」라서 「달라요」라고 써야 하니까","correct":true},{"t":"「틀리다」와 「다르다」는 뜻이 같으니까","mis":"K2-1-u5-X10"}],"mis":"K2-1-u5-X10","explanation":["같지 않은 것은 「다르다」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#14','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C8',2,'mc','auto','「작은 새가 나뭇가지에 앉았다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":14,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「작은 새가 나뭇가지에 앉았다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「작은 새가 / 나뭇가지에 / 앉았다」","correct":true},{"t":"「작은 / 새 / 가 / 나뭇 / 가지에 앉았다」","mis":"K2-1-u5-X11"},{"t":"「작은 새가 나뭇 / 가지에 앉 / 았다」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","낱말 가운데에서 끊거나 덩어리를 흩뜨리면 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#15','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C10',2,'mc','auto','친구가 「줄넘기 백 번 넘었어!」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":15,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「줄넘기 백 번 넘었어!」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「우아, 정말 대단하다!」","correct":true},{"t":"「나도 그 정도는 해.」","mis":"K2-1-u5-X16"},{"t":"「그게 뭐 어려워?」","mis":"K2-1-u5-X16"}],"explanation":["친구의 기쁜 마음을 함께 나누는 말이에요.","친구의 마음을 가볍게 넘기거나 놀리는 말은 친구를 더 속상하게 해요.","내가 그 말을 들으면 어떨지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#16','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C5',2,'match','auto','마음을 나타내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"마음을 나타내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"억울하다","r":"잘못이 없는데 탓을 들어 답답하다"},{"l":"아쉽다","r":"바라던 일이 안 되어 서운하고 안타깝다"},{"l":"떨리다","r":"긴장되어 가슴이 두근두근하다"}],"mis":"K2-1-u5-X06","explanation":["「억울하다」 — 잘못이 없는데 탓을 들어 답답하다","「아쉽다」 — 바라던 일이 안 되어 서운하고 안타깝다","「떨리다」 — 긴장되어 가슴이 두근두근하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#17','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X09','K2-1-u5-X17']::text[],false,'{"seq":17,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"태민 — 「계단에서 넘어져 무릎을 닫혔어요.」","correct":true,"mis_target":"K2-1-u5-X09"},{"t":"은솔 — 「바람에 창문이 닫혔어요.」","mis":"K2-1-u5-X17"},{"t":"아린 — 「공으로 깡통을 맞혔어요.」","mis":"K2-1-u5-X17"}],"explanation":["몸에 상처를 입은 것은 「다쳤어요」라고 써야 해요.","다른 두 친구는 뜻에 맞게 바르게 썼어요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#18','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C6',3,'error','auto','글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],false,'{"seq":18,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「지우는 끝까지 속상한 마음이 그대로였어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"민지 — 「우유가 쏟아져 눈물이 핑 돌았어.」","mis":"K2-1-u5-X17"},{"t":"지후 — 「할머니가 웃으셔서 마음이 따뜻해졌어.」","mis":"K2-1-u5-X17"}],"explanation":["지우의 마음은 할머니가 웃으시자 따뜻해졌어요.","마음은 처음 그대로 있지 않고 일에 따라 바뀌었어요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#19','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C8',3,'mc','auto','「작은 / 새와 나무」로 띄어 읽으면 작은 것은 무엇인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":19,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"「작은 / 새와 나무」로 띄어 읽으면 작은 것은 무엇인가요?","options":[{"t":"새와 나무 모두","correct":true},{"t":"새만","mis":"K2-1-u5-X13"},{"t":"나무만","mis":"K2-1-u5-X13"}],"explanation":["「작은 / 새와 나무」는 새와 나무가 모두 작다는 뜻이에요.","어디에서 쉬느냐에 따라 뜻이 달라져요.","끊어 읽은 대로 그림을 떠올려 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#20','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C4',3,'mc','auto','「달리기에서 하린이가 일 등, 준우가 꼴찌를 했어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":20,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"「달리기에서 하린이가 일 등, 준우가 꼴찌를 했어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"하린이는 기쁘고, 준우는 아쉬워요","correct":true},{"t":"하린이는 아쉽고, 준우는 기뻐요","mis":"K2-1-u5-X04"},{"t":"하린이는 미안하고, 준우는 설레요","mis":"K2-1-u5-X03"}],"explanation":["일 등을 한 하린이는 기쁘고, 꼴찌를 한 준우는 아쉬울 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#21','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C10',3,'error','auto','친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],false,'{"seq":21,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"현우 — 「강아지는 원래 자주 아파.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"예린 — 「많이 걱정되겠다.」","mis":"K2-1-u5-X17"},{"t":"도담 — 「강아지가 얼른 나으면 좋겠다.」","mis":"K2-1-u5-X17"}],"explanation":["「원래 자주 아파.」는 하준이의 걱정하는 마음을 알아주지 않아요.","다른 두 친구는 마음을 알아주는 맞장구를 쳤어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"우리 강아지가 아파서 병원에 갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#22','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C3',3,'mc','auto','「난 안 가도 돼.」라고 말하면서 친구들이 가는 쪽을 자꾸 돌아보았어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":22,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「난 안 가도 돼.」라고 말하면서 친구들이 가는 쪽을 자꾸 돌아보았어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 괜찮다고 했지만 사실은 같이 가고 싶은 마음","correct":true},{"t":"말 그대로 전혀 가고 싶지 않은 마음","mis":"K2-1-u5-X02"},{"t":"화가 나서 싸우고 싶은 마음","mis":"K2-1-u5-X03"}],"explanation":["자꾸 돌아보는 행동에서 같이 가고 싶은 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","다른 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#23','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#24','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',4,'essay','teacher','다음 문장에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 낱말의 뜻을 들어 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#25','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C6',4,'essay','teacher','글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.","answer_guide":{"answer":"예: 처음에는 속상했어요(눈물이 핑 돎). 동생과 카드를 다시 만들어 드렸더니 할머니가 웃으셔서 끝에는 마음이 따뜻했어요.","scoring_points":["처음과 끝의 마음을 마음 말로 썼는가","마음이 바뀐 까닭을 글에서 찾아 썼는가","근거가 된 말이나 행동을 썼는가"]},"explanation":["처음과 끝의 마음.","바뀐 까닭.","근거."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#1','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C1',1,'mc','auto','글 속 인물의 마음을 짐작할 때 찾아야 할 것은 무엇인가요?',ARRAY['K2-1-u5-X01']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"글 속 인물의 마음을 짐작할 때 찾아야 할 것은 무엇인가요?","options":[{"t":"마음이 드러난 말과 행동","correct":true},{"t":"인물의 옷차림","mis":"K2-1-u5-X01"},{"t":"글의 제목 글자 수","mis":"K2-1-u5-X01"}],"explanation":["「드디어 됐다!」 같은 말과 두 손을 번쩍 드는 행동에 마음이 드러나요.","생김새·옷·이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#2','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C3',1,'mc','auto','주먹을 꽉 쥐고 「내가 안 그랬어!」 했어요. 이 인물의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"주먹을 꽉 쥐고 「내가 안 그랬어!」 했어요. 이 인물의 마음은 어느 것인가요?","options":[{"t":"억울한 마음","correct":true},{"t":"고마운 마음","mis":"K2-1-u5-X02"},{"t":"설레는 마음","mis":"K2-1-u5-X02"}],"explanation":["주먹을 쥐고 「내가 안 그랬어!」 한 말과 행동에서 억울한 마음이 드러나요.","다른 마음은 이 말·행동과 맞지 않아요.","행동을 따라 해 보며 마음을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#3','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"고맙다","correct":true},{"t":"칠판","mis":"K2-1-u5-X05"},{"t":"걷다","mis":"K2-1-u5-X05"}],"explanation":["「고맙다」는 마음을 나타내는 말이에요.","「칠판」·「걷다」는 물건·장소·움직임을 나타내요.","「나는 지금 ○○해.」에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#4','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「토끼가 / 풀밭에서 / 놀아요」","correct":true},{"t":"「토 / 끼가풀 / 밭에서 놀아요」","mis":"K2-1-u5-X11"},{"t":"「토끼가풀밭에서놀아요」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#5','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',1,'mc','auto','「반드시」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「반드시」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"틀림없이 꼭","correct":true},{"t":"비뚤어지지 않고 곧게","mis":"K2-1-u5-X09"},{"t":"아주 천천히","mis":"K2-1-u5-X09"}],"explanation":["「반드시」는 틀림없이 꼭는 뜻이에요.","다른 뜻은 소리가 같거나 비슷한 다른 낱말의 뜻이에요.","소리가 같아도 뜻을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#6','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C8',1,'ox','auto','띄어 읽을 곳에 그은 빗금(/)에서는 쉬지 않고 붙여 읽어요.',ARRAY['K2-1-u5-X14']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"띄어 읽을 곳에 그은 빗금(/)에서는 쉬지 않고 붙여 읽어요.","answer":"X","reason_options":[{"t":"빗금은 조금 쉬어 읽으라는 표시이니까","correct":true},{"t":"빗금은 빠르게 읽으라는 표시이니까","mis":"K2-1-u5-X14"}],"mis":"K2-1-u5-X14","explanation":["빗금이 있는 곳에서 조금 쉬어 읽어요.","뜻이 통하는 덩어리로 묶어 읽어요.","그러면 물 흐르듯 자연스럽게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#7','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C9',1,'mc','auto','인물이 고마워하는 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 고마워하는 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"따뜻하고 다정하게","correct":true},{"t":"거칠고 퉁명스럽게","mis":"K2-1-u5-X15"},{"t":"졸린 듯 작게","mis":"K2-1-u5-X15"}],"explanation":["인물이 고마워하는 장면은 따뜻하고 다정하게 읽으면 마음이 살아나요.","다른 목소리는 이 장면의 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#8','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',1,'mc','auto','친구가 빌려 간 책을 돌려주지 않아 서운해요. 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 빌려 간 책을 돌려주지 않아 서운해요. 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「책을 안 돌려줘서 조금 서운했어.」","correct":true},{"t":"「너 정말 나빠!」","mis":"K2-1-u5-X16"},{"t":"「몰라, 됐어.」","mis":"K2-1-u5-X16"}],"explanation":["무슨 일 때문에 어떤 마음인지 마음 말로 전해요.","마음이 담기지 않은 말이나 탓하는 말은 친구를 속상하게 해요.","마음 말로 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#9','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"기다리던 소풍이 비로 미뤄졌을 때","r":"아쉽다"},{"l":"새 반에서 아는 친구가 하나도 없을 때","r":"어색하다"},{"l":"친구와 함께 깔깔 웃으며 놀 때","r":"즐겁다"}],"mis":"K2-1-u5-X03","explanation":["「기다리던 소풍이 비로 미뤄졌을 때」 — 아쉽다","「새 반에서 아는 친구가 하나도 없을 때」 — 어색하다","「친구와 함께 깔깔 웃으며 놀 때」 — 즐겁다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#10','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',2,'blank','auto','「놀이터에서 장갑을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「놀이터에서 장갑을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"잃어버렸어요","correct":true},{"t":"잊어버렸어요","mis":"K2-1-u5-X10"},{"t":"잇어버렸어요","mis":"K2-1-u5-X09"}],"explanation":["가졌던 물건이 없어진 것은 「잃어버렸어요」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#11','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 서준이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":11,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하다 → 뿌듯하다","correct":true},{"t":"뿌듯하다 → 속상하다","mis":"K2-1-u5-X07"},{"t":"속상하다 → 속상하다","mis":"K2-1-u5-X07"}],"explanation":["비행기가 떨어져 속상했다가, 끝까지 날아가자 뿌듯했어요.","차례를 뒤바꾸거나 마음이 그대로라고 보면 안 돼요.","처음 → 무슨 일 → 나중을 따라가요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#12','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 아기 곰이 뿌듯한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":12,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 아기 곰이 뿌듯한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"가슴을 쭉 펴고 환하게 웃었어요","correct":true},{"t":"다리가 후들후들 떨렸어요","mis":"K2-1-u5-X02"},{"t":"음악회에서 북을 치기로 했어요","mis":"K2-1-u5-X08"}],"explanation":["가슴을 쭉 펴고 웃는 행동에 뿌듯한 마음이 드러나요.","다른 마음이 드러난 부분이나 일어난 일과 헷갈리지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#13','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',2,'ox','auto','「꼭 이기기를 바라요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":13,"concept":"K2-1-u5-C7","difficulty":2,"kind":"ox","stem":"「꼭 이기기를 바라요.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"이루어지기를 원하는 것은 「바라다」니까","correct":true},{"t":"「바래요」라고 써야 맞으니까","mis":"K2-1-u5-X10"}],"mis":"K2-1-u5-X10","explanation":["원하는 것은 「바라다」라서 「바라요」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#14','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C8',2,'mc','auto','「엄마가 시장에서 사과를 사 오셨어요.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":14,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「엄마가 시장에서 사과를 사 오셨어요.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「엄마가 / 시장에서 / 사과를 사 오셨어요」","correct":true},{"t":"「엄 / 마가 / 시 / 장에서 / 사과를 사 오셨어요」","mis":"K2-1-u5-X11"},{"t":"「엄마가시 / 장에서사과를 / 사 오셨어요」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","낱말 가운데에서 끊거나 덩어리를 흩뜨리면 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#15','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',2,'mc','auto','친구가 「무서운 꿈을 꿨어.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":15,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「무서운 꿈을 꿨어.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「많이 놀랐겠다. 지금은 괜찮아?」","correct":true},{"t":"「겁쟁이네.」","mis":"K2-1-u5-X16"},{"t":"「꿈은 다 가짜야.」","mis":"K2-1-u5-X16"}],"explanation":["친구의 놀란 마음을 알아주는 말이에요.","친구의 마음을 가볍게 넘기거나 놀리는 말은 친구를 더 속상하게 해요.","내가 그 말을 들으면 어떨지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#16','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C5',2,'match','auto','마음을 나타내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"마음을 나타내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"외롭다","r":"혼자가 되어 쓸쓸하다"},{"l":"반갑다","r":"보고 싶던 사람을 만나 기쁘다"},{"l":"어색하다","r":"낯설어서 자연스럽지 못하다"}],"mis":"K2-1-u5-X06","explanation":["「외롭다」 — 혼자가 되어 쓸쓸하다","「반갑다」 — 보고 싶던 사람을 만나 기쁘다","「어색하다」 — 낯설어서 자연스럽지 못하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#17','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X17']::text[],false,'{"seq":17,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"현우 — 「동생이 손가락으로 별을 가르쳤어요.」","correct":true,"mis_target":"K2-1-u5-X10"},{"t":"지안 — 「언니가 나에게 줄넘기를 가르쳐 주었어요.」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「선생님께서 칠판을 가리키셨어요.」","mis":"K2-1-u5-X17"}],"explanation":["손가락으로 짚어 보인 것은 「가리켰어요」라고 써야 해요.","다른 두 친구는 뜻에 맞게 바르게 썼어요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#18','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C6',3,'error','auto','글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],false,'{"seq":18,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"준우 — 「서준이는 처음부터 끝까지 속상하기만 했어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"하린 — 「비행기가 떨어질 때는 입술을 삐죽 내밀었어.」","mis":"K2-1-u5-X17"},{"t":"로아 — 「끝에는 「와, 해냈다!」 하며 손뼉을 쳤어.」","mis":"K2-1-u5-X17"}],"explanation":["서준이는 비행기가 끝까지 날아가자 뿌듯해했어요.","마음은 처음 그대로 있지 않고 일에 따라 바뀌었어요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#19','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C8',3,'mc','auto','「작은 새와 / 나무」로 띄어 읽으면 작은 것은 무엇인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":19,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"「작은 새와 / 나무」로 띄어 읽으면 작은 것은 무엇인가요?","options":[{"t":"새만","correct":true},{"t":"새와 나무 모두","mis":"K2-1-u5-X13"},{"t":"나무만","mis":"K2-1-u5-X13"}],"explanation":["「작은 새와 / 나무」는 새만 작다는 뜻이에요.","어디에서 쉬느냐에 따라 뜻이 달라져요.","끊어 읽은 대로 그림을 떠올려 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#20','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C4',3,'mc','auto','「지호가 짝에게 연필을 빌려주었어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":20,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"「지호가 짝에게 연필을 빌려주었어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"짝은 고맙고, 지호는 뿌듯해요","correct":true},{"t":"짝은 뿌듯하고, 지호는 고마워요","mis":"K2-1-u5-X04"},{"t":"짝은 억울하고, 지호는 서운해요","mis":"K2-1-u5-X03"}],"explanation":["빌린 짝은 고맙고, 도와준 지호는 뿌듯할 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#21','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',3,'error','auto','친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],false,'{"seq":21,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"준우 — 「잘됐네, 내 자리가 넓어지겠다.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"서아 — 「많이 섭섭하다.」","mis":"K2-1-u5-X17"},{"t":"하늘 — 「가서도 꼭 연락하자.」","mis":"K2-1-u5-X17"}],"explanation":["「내 자리가 넓어지겠다」는 소율이의 섭섭한 마음을 생각하지 않은 말이에요.","다른 두 친구는 마음을 알아주는 맞장구를 쳤어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"내일 이사 가서 전학 가."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#22','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C3',3,'mc','auto','「별로 안 기뻐.」라고 말하면서 입가에 웃음이 번졌어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":22,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「별로 안 기뻐.」라고 말하면서 입가에 웃음이 번졌어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 안 기쁘다고 했지만 사실은 기쁜 마음","correct":true},{"t":"말 그대로 하나도 안 기쁜 마음","mis":"K2-1-u5-X02"},{"t":"무섭고 떨리는 마음","mis":"K2-1-u5-X03"}],"explanation":["입가에 웃음이 번지는 모습에서 기쁜 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","다른 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#23','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#24','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',4,'essay','teacher','다음 문장에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 낱말의 뜻을 들어 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#25','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C6',4,'essay','teacher','글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.","answer_guide":{"answer":"예: 처음에는 속상했어요(입술을 삐죽 내밂). 다시 접어 날린 비행기가 끝까지 날아가서 끝에는 뿌듯했어요(「와, 해냈다!」 하며 손뼉).","scoring_points":["처음과 끝의 마음을 마음 말로 썼는가","마음이 바뀐 까닭을 글에서 찾아 썼는가","근거가 된 말이나 행동을 썼는가"]},"explanation":["처음과 끝의 마음.","바뀐 까닭.","근거."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C1','kor',2,1,'u6',1,'매체와 중요한 내용 — 글·안내판·광고·책처럼 정보를 주고받는 도구를 매체라고 하며, 매체가 무엇을 알려 주려는지(이용 방법·주의할 점·전하고 싶은 말) 살펴 중요한 내용을 찾기',ARRAY['2국02-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C2','kor',2,1,'u6',1,'보고 든 생각을 까닭과 함께 말하기 — 매체나 글을 보고 든 생각·느낌을 「왜냐하면 ~」처럼 그렇게 생각한 까닭과 함께 말하면 듣는 사람에게 더 잘 전해짐을 알기',ARRAY['2국05-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C3','kor',2,1,'u6',3,'제목으로 중요한 내용 짐작하기 — 제목에는 글에서 가장 중요한 내용이 담겨 있으므로 제목을 보고 글이 무엇을 알려 줄지 짐작하고, 글의 내용에 어울리는 제목을 고르기',ARRAY['2국02-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C4','kor',2,1,'u6',3,'자주 나오는 낱말 찾기 — 글에 여러 번 나오고 제목과 관련 있는 낱말이 중요한 낱말임을 알고, 한 번만 나오거나 글과 상관없는 낱말과 가려 찾기',ARRAY['2국02-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C5','kor',2,1,'u6',3,'중심 문장 찾고 중요한 내용 정리하기 — 각 부분에서 가장 중요한 문장(중심 문장)을 찾고, 예를 들거나 까닭을 덧붙인 문장과 가려, 중심 문장을 모아 글의 중요한 내용을 정리하기',ARRAY['2국02-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C6','kor',2,1,'u6',7,'인물의 말에서 생각 찾기 — 글 속 인물이 한 말에서 무엇을 하고 싶은지·어떻게 하자고 하는지 인물의 생각을 찾고, 인물마다 생각이 다름을 알기',ARRAY['2국02-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C7','kor',2,1,'u6',7,'생각의 까닭 찾기 — 생각 뒤에 나오는 좋은 점·옳은 점(「~해서」·「~거든」·「~니까」)이 까닭임을 알고, 생각과 까닭을 한 쌍으로 짝지어 찾기',ARRAY['2국02-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C8','kor',2,1,'u6',9,'자신의 생각을 까닭과 함께 예의 바르게 표현하기 — 인물의 생각과 까닭을 먼저 파악한 뒤 「나는 ~라고 생각해. 왜냐하면 ~거든.」처럼 내 생각과 까닭을 예의 바르게 말하고 쓰며, 나와 다른 생각도 존중하기',ARRAY['2국05-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C9','kor',2,1,'u6',12,'책을 소개하며 생각 나누기 — 책 소개 상자의 여러 면에 제목·인상 깊은 장면·기억에 남는 문장·읽고 든 생각이나 느낌을 담아 소개하고, 같은 책에도 생각이 다를 수 있음을 알기',ARRAY['2국06-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u6-C10','kor',2,1,'u6',14,'토박이말 알기 — 까치밥·벗·여우비·단비·함박눈·나들이처럼 예부터 우리말로 써 온 정겨운 토박이말의 뜻을 알고 알맞게 쓰기',ARRAY['2국04-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X01','kor',2,'u6',ARRAY['K2-1-u6-C1']::text[],'정보를 주고받지 않는 물건(지우개·우산·의자)을 매체로 여긴다','「무엇을 알려 주지?」 물어서 대답이 나오는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X02','kor',2,'u6',ARRAY['K2-1-u6-C1']::text[],'매체마다 알려 주는 내용을 헷갈린다(안내판이 이야기를 들려준다, 광고가 이용 방법만 알려 준다)','그 매체를 어디서 보았는지 떠올리고 무엇이 적혀 있었는지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X03','kor',2,'u6',ARRAY['K2-1-u6-C1','K2-1-u6-C3','K2-1-u6-C5']::text[],'사소하거나 글과 상관없는 것(색깔·날씨·글자 모양)을 중요한 내용으로 고른다','「이 글은 무엇을 알려 주려고 썼지?」 먼저 말하고 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X04','kor',2,'u6',ARRAY['K2-1-u6-C3']::text[],'제목을 살피지 않고 내용을 짐작하거나, 글의 내용과 어울리지 않는 제목을 고른다','제목을 소리 내어 읽고 「무엇에 대한 글일까?」 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X05','kor',2,'u6',ARRAY['K2-1-u6-C4']::text[],'한 번만 나오거나 글과 상관없는 낱말을 자주 나오는 중요한 낱말로 고른다','낱말이 나올 때마다 손가락으로 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X06','kor',2,'u6',ARRAY['K2-1-u6-C5']::text[],'예를 들거나 까닭을 덧붙인 문장을 중심 문장으로 고르거나, 한 부분의 내용만 글 전체의 중요한 내용으로 여긴다','「이 부분에서 가장 하고 싶은 말은?」 한 문장으로 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X07','kor',2,'u6',ARRAY['K2-1-u6-C5','K2-1-u6-C6','K2-1-u6-C7']::text[],'글에 없는 내용을 있다고 하거나 글의 내용을 놓친다','글에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X08','kor',2,'u6',ARRAY['K2-1-u6-C6','K2-1-u6-C7']::text[],'인물을 뒤바꿔 다른 인물의 생각·까닭을 말한다','말한 사람 이름에 동그라미 치고 그 말만 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X09','kor',2,'u6',ARRAY['K2-1-u6-C7','K2-1-u6-C2']::text[],'생각과 까닭을 헷갈리거나, 까닭이 아닌 말(「오늘은 화요일」·「내 신발은 파란색」)을 까닭으로 여긴다','「왜?」 하고 물었을 때 대답이 되는 말인지 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X10','kor',2,'u6',ARRAY['K2-1-u6-C2','K2-1-u6-C8']::text[],'까닭 없이 생각만 말하거나 「그냥」·「좋으니까」처럼 까닭이 드러나지 않게 말한다','「왜냐하면 ~거든」을 꼭 붙여 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X11','kor',2,'u6',ARRAY['K2-1-u6-C8']::text[],'큰 소리로 우기거나 무례한 말로 생각을 전하고, 친구의 말을 끝까지 듣지 않는다','「나는 ~라고 생각해」로 시작하고 친구 말이 끝날 때까지 기다리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X12','kor',2,'u6',ARRAY['K2-1-u6-C8','K2-1-u6-C9']::text[],'나와 생각이 다르면 틀렸다고 여기거나 친구의 생각을 무시한다','「너는 그렇게 생각하는구나. 까닭이 뭐야?」 하고 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X13','kor',2,'u6',ARRAY['K2-1-u6-C9']::text[],'책 소개와 상관없는 내용(시험 점수·전화번호·비밀번호·날씨)을 책 소개 상자에 담는다','「이 내용이 책을 알려 주나?」 하나씩 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X14','kor',2,'u6',ARRAY['K2-1-u6-C9']::text[],'책 소개 상자의 면과 담을 내용을 헷갈리거나, 줄거리만 쓰고 읽고 든 생각·느낌을 빠뜨린다','앞면 → 문장 → 생각 차례로 상자를 돌려 가며 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X15','kor',2,'u6',ARRAY['K2-1-u6-C10']::text[],'토박이말의 뜻을 바꿔 알거나 글자 모양만 보고 짐작한다(여우비 → 여우가 오는 날, 까치밥 → 까치가 지은 밥)','토박이말이 쓰이는 때를 그림으로 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u6-X16','kor',2,'u6',ARRAY['K2-1-u6-C1','K2-1-u6-C2','K2-1-u6-C3','K2-1-u6-C4','K2-1-u6-C5','K2-1-u6-C6','K2-1-u6-C7','K2-1-u6-C8','K2-1-u6-C9','K2-1-u6-C10']::text[],'묻는 말을 거꾸로 읽는다 — 알맞지 않은↔알맞은, 잘못↔바르게, 아닌↔맞는','물음의 「않은·잘못·아닌」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#1','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],true,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"안내판","correct":true},{"t":"지우개","mis":"K2-1-u6-X01"},{"t":"우산","mis":"K2-1-u6-X01"}],"explanation":["안내판은 이용 방법과 주의할 점을 알려 주는 매체예요.","지우개와 우산은 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오면 매체예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"광고","correct":true},{"t":"의자","mis":"K2-1-u6-X01"},{"t":"신발","mis":"K2-1-u6-X01"}],"explanation":["광고는 사람들에게 전하고 싶은 말을 알려 주는 매체예요.","의자와 신발은 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오면 매체예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#2','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',1,'mc','auto','안내판을 읽고 답해 보세요. 이 안내판이 알려 주는 것은 무엇인가요?',ARRAY['K2-1-u6-X03']::text[],true,'{"seq":2,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"안내판을 읽고 답해 보세요. 이 안내판이 알려 주는 것은 무엇인가요?","options":[{"t":"놀이터를 이용할 때 지킬 일","correct":true},{"t":"놀이터 미끄럼틀의 색깔","mis":"K2-1-u6-X03"},{"t":"오늘의 날씨","mis":"K2-1-u6-X03"}],"explanation":["안내판에는 놀이터를 이용할 때 지킬 일이 적혀 있어요.","미끄럼틀 색깔이나 날씨는 안내판에 없어요.","매체가 무엇을 알려 주려는지 생각해요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"},"variant_rule":{"alt":[{"stem":"광고를 읽고 답해 보세요. 이 광고가 알려 주는 것은 무엇인가요?","options":[{"t":"도서관에서 책 잔치가 열린다는 것","correct":true},{"t":"도서관 건물의 색깔","mis":"K2-1-u6-X03"},{"t":"내일 비가 온다는 것","mis":"K2-1-u6-X03"}],"explanation":["광고는 도서관 책 잔치를 알리고 있어요.","건물 색깔이나 날씨는 광고에 없어요.","매체가 무엇을 알려 주려는지 생각해요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#3','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C2',1,'ox','auto','매체를 보고 든 생각을 말할 때 그렇게 생각한 까닭을 함께 말하면 더 잘 전해져요.',ARRAY['K2-1-u6-X10']::text[],true,'{"seq":3,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"매체를 보고 든 생각을 말할 때 그렇게 생각한 까닭을 함께 말하면 더 잘 전해져요.","answer":"O","reason_options":[{"t":"까닭을 들으면 듣는 사람이 내 생각을 더 잘 이해하니까","correct":true},{"t":"까닭은 말하지 않아야 더 멋지니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["「왜냐하면 ~」처럼 까닭을 붙이면 생각이 더 잘 전해져요.","까닭이 없으면 듣는 사람이 왜 그런지 알기 어려워요.","생각과 까닭을 함께 말해요."],"variant_rule":{"alt":[{"stem":"「이 안내판은 좋아.」라고만 말해도 내 생각이 충분히 전해져요.","answer":"X","reason_options":[{"t":"왜 좋은지 까닭을 덧붙여야 생각이 잘 전해지니까","correct":true},{"t":"생각은 짧을수록 언제나 잘 전해지니까","mis":"K2-1-u6-X10"}],"explanation":["「좋아.」만으로는 왜 좋은지 알 수 없어요.","「위험한 일을 알려 줘서 좋아.」처럼 까닭을 붙여요.","생각과 까닭을 함께 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#4','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',1,'mc','auto','안내판을 세워 두는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X02']::text[],true,'{"seq":4,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"안내판을 세워 두는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"이용 방법과 주의할 점을 알려 주려고","correct":true},{"t":"친구의 생일을 알려 주려고","mis":"K2-1-u6-X02"},{"t":"게임 점수를 보여 주려고","mis":"K2-1-u6-X02"}],"explanation":["안내판은 그곳을 이용하는 방법과 주의할 점을 알려 줘요.","생일이나 게임 점수는 안내판이 알려 주는 내용이 아니에요.","매체마다 알려 주는 것이 달라요."],"variant_rule":{"alt":[{"stem":"광고를 만드는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람들에게 전하고 싶은 말을 알리려고","correct":true},{"t":"인물의 긴 이야기를 들려주려고","mis":"K2-1-u6-X02"},{"t":"놀이 기구 타는 차례를 정하려고","mis":"K2-1-u6-X02"}],"explanation":["광고는 사람들에게 전하고 싶은 말을 알려요.","인물의 이야기는 이야기책이 들려줘요.","매체마다 알려 주는 것이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#5','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"안내판","r":"이용 방법과 주의할 점"},{"l":"광고","r":"전하고 싶은 말"},{"l":"이야기책","r":"인물의 이야기"}],"mis":"K2-1-u6-X02","explanation":["안내판은 이용 방법과 주의할 점을 알려 줘요.","광고는 전하고 싶은 말을 알려요.","이야기책은 인물의 이야기를 들려줘요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"식단표","r":"오늘 먹을 음식"},{"l":"일기 예보","r":"내일의 날씨"},{"l":"알림장","r":"준비물과 숙제"}],"explanation":["식단표는 오늘 먹을 음식을 알려 줘요.","일기 예보는 날씨를 알려 줘요.","알림장은 준비물과 숙제를 알려 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#6','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',2,'mc','auto','안내판을 읽고 답해 보세요. 그네와 관련하여 지킬 일은 무엇인가요?',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":6,"concept":"K2-1-u6-C1","difficulty":2,"kind":"mc","stem":"안내판을 읽고 답해 보세요. 그네와 관련하여 지킬 일은 무엇인가요?","options":[{"t":"그네가 움직일 때 그네 앞으로 지나가지 않아요","correct":true},{"t":"그네는 서서 타요","mis":"K2-1-u6-X07"},{"t":"그네는 차례 없이 먼저 타요","mis":"K2-1-u6-X07"}],"explanation":["안내판 2번에 그네 앞으로 지나가지 않는다고 했어요.","서서 타거나 차례 없이 타라는 말은 안내판에 없어요.","안내판에서 그 줄을 찾아 짚어요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"},"variant_rule":{"alt":[{"stem":"광고를 읽고 답해 보세요. 책갈피를 받으려면 어떻게 해야 하나요?","options":[{"t":"책을 세 권 읽고 와요","correct":true},{"t":"도서관 청소를 해요","mis":"K2-1-u6-X07"},{"t":"책을 한 권 사 와요","mis":"K2-1-u6-X07"}],"explanation":["광고에 책을 세 권 읽고 오면 책갈피를 준다고 했어요.","청소나 책을 사 오라는 말은 광고에 없어요.","광고에서 그 줄을 찾아 짚어요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#7','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C2',2,'blank','auto','안내판을 보고 생각을 말했어요. 「나는 이 안내판이 꼭 필요하다고 생각해. (     ) 놀이터에서 다치지 않게 도와주거든.」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u6-X10']::text[],true,'{"seq":7,"concept":"K2-1-u6-C2","difficulty":2,"kind":"blank","stem":"안내판을 보고 생각을 말했어요. 「나는 이 안내판이 꼭 필요하다고 생각해. (     ) 놀이터에서 다치지 않게 도와주거든.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그런데","mis":"K2-1-u6-X10"},{"t":"그리고 나서","mis":"K2-1-u6-X10"}],"explanation":["까닭을 말할 때는 「왜냐하면 ~거든」을 써요.","「그런데」·「그리고 나서」는 까닭을 이끄는 말이 아니에요.","생각 뒤에 까닭을 이어 말해요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"},"variant_rule":{"alt":[{"stem":"광고를 보고 생각을 말했어요. 「나는 도서관에 가 보고 싶어. (     ) 책갈피를 받고 싶거든.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그래서 마침내","mis":"K2-1-u6-X10"},{"t":"그런데","mis":"K2-1-u6-X10"}],"explanation":["까닭을 말할 때는 「왜냐하면 ~거든」을 써요.","「그래서 마침내」·「그런데」는 까닭을 이끄는 말이 아니에요.","생각 뒤에 까닭을 이어 말해요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#8','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C2',2,'mc','auto','안내판을 보고 든 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X03']::text[],true,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":2,"kind":"mc","stem":"안내판을 보고 든 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"「차례대로 타면 안 다치니까 꼭 지켜야겠어.」","correct":true},{"t":"「그냥 지켜야겠어.」","mis":"K2-1-u6-X10"},{"t":"「안내판이 네모 모양이야.」","mis":"K2-1-u6-X03"}],"explanation":["「차례대로 타면 안 다치니까」가 까닭이에요.","「그냥」은 까닭이 드러나지 않아요.","안내판 모양은 보고 든 생각이 아니에요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"},"variant_rule":{"alt":[{"stem":"광고를 보고 든 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"「책을 읽으면 책갈피도 받으니까 가 보고 싶어.」","correct":true},{"t":"「그냥 가 보고 싶어.」","mis":"K2-1-u6-X10"},{"t":"「광고 글씨가 파란색이야.」","mis":"K2-1-u6-X03"}],"explanation":["「책갈피도 받으니까」가 까닭이에요.","「그냥」은 까닭이 드러나지 않아요.","글씨 색깔은 보고 든 생각이 아니에요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#9','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',2,'mc','auto','매체에서 중요한 내용을 찾으면 좋은 점은 무엇인가요?',ARRAY['K2-1-u6-X03']::text[],true,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"mc","stem":"매체에서 중요한 내용을 찾으면 좋은 점은 무엇인가요?","options":[{"t":"알아야 할 정보를 빠르고 정확하게 알 수 있어요","correct":true},{"t":"글자 수를 셀 수 있어요","mis":"K2-1-u6-X03"},{"t":"그림 색깔을 외울 수 있어요","mis":"K2-1-u6-X03"}],"explanation":["중요한 내용을 찾으면 꼭 알아야 할 정보를 알 수 있어요.","글자 수나 그림 색깔은 중요한 내용이 아니에요.","무엇을 알려 주려는지 생각해요."],"variant_rule":{"alt":[{"stem":"매체를 볼 때 먼저 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 알려 주려는지","correct":true},{"t":"종이가 얼마나 두꺼운지","mis":"K2-1-u6-X03"},{"t":"글씨가 몇 줄인지","mis":"K2-1-u6-X03"}],"explanation":["매체가 무엇을 알려 주려는지 생각하면 중요한 내용이 보여요.","종이 두께나 줄 수는 중요한 내용이 아니에요.","무엇을 알려 주려는지 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_basic#10','kor',2,1,'u6','L01','g2_1_kor_u6_L01_basic','lesson_basic','K2-1-u6-C1',3,'error','auto','정보를 주고받는 매체를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X01','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C1","difficulty":3,"kind":"error","stem":"정보를 주고받는 매체를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「연필도 매체야. 글씨를 쓸 수 있으니까.」","correct":true,"mis_target":"K2-1-u6-X01"},{"t":"하준 — 「책은 매체야.」","mis":"K2-1-u6-X16"},{"t":"다은 — 「일기 예보는 매체야.」","mis":"K2-1-u6-X16"}],"explanation":["연필은 글씨를 쓰는 도구일 뿐 정보를 알려 주지 않아요.","책과 일기 예보는 정보를 알려 주는 매체예요.","「무엇을 알려 주지?」 물어 대답이 나오는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 정보를 주고받는 매체를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「가방도 매체야. 책을 넣을 수 있으니까.」","correct":true,"mis_target":"K2-1-u6-X01"},{"t":"로아 — 「안내판은 매체야.」","mis":"K2-1-u6-X16"},{"t":"시우 — 「광고는 매체야.」","mis":"K2-1-u6-X16"}],"explanation":["가방은 물건을 담는 도구일 뿐 정보를 알려 주지 않아요.","안내판과 광고는 정보를 알려 주는 매체예요.","「무엇을 알려 주지?」 물어 대답이 나오는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#1','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',2,'mc','auto','광고를 읽고 답해 보세요. 이 광고에서 가장 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X03']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":2,"kind":"mc","stem":"광고를 읽고 답해 보세요. 이 광고에서 가장 중요한 내용은 무엇인가요?","options":[{"t":"도서관에서 책 잔치가 열리니 오라는 것","correct":true},{"t":"책갈피가 예쁘다는 것","mis":"K2-1-u6-X06"},{"t":"가을이 왔다는 것","mis":"K2-1-u6-X03"}],"explanation":["광고는 도서관 책 잔치에 오라고 알리는 것이 가장 중요해요.","책갈피는 책 잔치에 덧붙인 내용이에요.","「가을」은 때를 말한 것일 뿐이에요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#2','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',2,'mc','auto','다음 가운데 매체가 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":2,"concept":"K2-1-u6-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 매체가 아닌 것은 어느 것인가요?","options":[{"t":"줄넘기 줄","correct":true},{"t":"알림장","mis":"K2-1-u6-X16"},{"t":"표지판","mis":"K2-1-u6-X16"}],"explanation":["줄넘기 줄은 운동하는 도구일 뿐 정보를 알려 주지 않아요.","알림장과 표지판은 정보를 알려 주는 매체예요.","물음의 「아닌」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#3','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',3,'mc','auto','안내판을 읽고 답해 보세요. 이 안내판이 세워진 곳으로 가장 알맞은 곳은 어디인가요?',ARRAY['K2-1-u6-X04','K2-1-u6-X07']::text[],false,'{"seq":3,"concept":"K2-1-u6-C1","difficulty":3,"kind":"mc","stem":"안내판을 읽고 답해 보세요. 이 안내판이 세워진 곳으로 가장 알맞은 곳은 어디인가요?","options":[{"t":"놀이터 입구","correct":true},{"t":"도서관 책상 위","mis":"K2-1-u6-X04"},{"t":"수영장 탈의실","mis":"K2-1-u6-X07"}],"explanation":["미끄럼틀과 그네를 이용할 때 지킬 일이니 놀이터 입구가 알맞아요.","도서관이나 수영장과 관련된 내용은 없어요.","안내판의 제목과 내용을 함께 살펴요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#4','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',3,'error','auto','안내판을 보고 생각을 말했어요. 까닭을 들어 말하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X16']::text[],false,'{"seq":4,"concept":"K2-1-u6-C2","difficulty":3,"kind":"error","stem":"안내판을 보고 생각을 말했어요. 까닭을 들어 말하지 않은 친구는 누구인가요?","options":[{"t":"민지 — 「안내판이 좋아. 그냥 좋아.」","correct":true,"mis_target":"K2-1-u6-X10"},{"t":"준우 — 「쓰레기를 넣으라는 말이 좋아. 놀이터가 깨끗해지니까.」","mis":"K2-1-u6-X16"},{"t":"서윤 — 「그네 조심 줄이 필요해. 부딪히면 다치거든.」","mis":"K2-1-u6-X16"}],"explanation":["「그냥 좋아.」에는 까닭이 없어요.","준우와 서윤이는 까닭을 들어 말했어요.","「왜냐하면 ~거든」을 붙여 말해요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#5','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',3,'ox','auto','광고는 이야기책처럼 인물이 겪은 일을 길게 들려주는 매체예요.',ARRAY['K2-1-u6-X02']::text[],false,'{"seq":5,"concept":"K2-1-u6-C1","difficulty":3,"kind":"ox","stem":"광고는 이야기책처럼 인물이 겪은 일을 길게 들려주는 매체예요.","answer":"X","reason_options":[{"t":"광고는 전하고 싶은 말을 짧게 알리는 매체니까","correct":true},{"t":"광고와 이야기책은 알려 주는 내용이 같으니까","mis":"K2-1-u6-X02"}],"mis":"K2-1-u6-X02","explanation":["광고는 사람들에게 알리고 싶은 말을 짧게 전해요.","인물이 겪은 일은 이야기책이 들려줘요.","매체마다 알려 주는 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#6','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',3,'mc','auto','광고를 보고 「한 달 동안 누구나 올 수 있다니 좋다.」라고 생각했어요. 그렇게 생각한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":6,"concept":"K2-1-u6-C2","difficulty":3,"kind":"mc","stem":"광고를 보고 「한 달 동안 누구나 올 수 있다니 좋다.」라고 생각했어요. 그렇게 생각한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"바쁜 날이 있어도 다른 날 갈 수 있으니까","correct":true},{"t":"도서관이 멀리 있으니까","mis":"K2-1-u6-X09"},{"t":"광고 글씨가 크니까","mis":"K2-1-u6-X09"}],"explanation":["한 달 동안 열리면 편한 날을 골라 갈 수 있어요.","도서관이 멀다는 것은 좋다는 생각의 까닭이 되지 않아요.","글씨 크기는 이 생각과 상관없어요."],"asset":{"type":"passage","lines":["책 읽는 가을, 도서관으로 오세요!","책을 세 권 읽고 오면 예쁜 책갈피를 드려요.","한 달 동안 누구나 올 수 있어요."],"title":"도서관 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#7','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',3,'mc','auto','학교 급식실 앞에 붙은 「식단표」를 보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X02']::text[],false,'{"seq":7,"concept":"K2-1-u6-C1","difficulty":3,"kind":"mc","stem":"학교 급식실 앞에 붙은 「식단표」를 보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"오늘 먹을 음식을 알려고","correct":true},{"t":"급식실 문 색깔을 알려고","mis":"K2-1-u6-X03"},{"t":"친구 이름을 외우려고","mis":"K2-1-u6-X02"}],"explanation":["식단표는 먹을 음식을 알려 주는 매체예요.","문 색깔은 식단표와 상관없어요.","친구 이름은 식단표가 알려 주는 내용이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#8','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',4,'mc','auto','안내판을 보고 생각을 가장 잘 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X11','K2-1-u6-X09']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":4,"kind":"mc","stem":"안내판을 보고 생각을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"「나는 3번이 가장 중요하다고 생각해. 왜냐하면 쓰레기가 없어야 모두가 깨끗한 놀이터에서 놀 수 있거든.」","correct":true},{"t":"「나는 3번이 가장 중요해. 무조건이야!」","mis":"K2-1-u6-X11"},{"t":"「나는 3번이 가장 중요해. 왜냐하면 오늘 비가 오거든.」","mis":"K2-1-u6-X09"}],"explanation":["생각과 그에 맞는 까닭을 예의 바르게 말했어요.","「무조건이야!」는 우기는 말이에요.","비가 오는 것은 이 생각의 까닭이 되지 않아요."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#9','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C2',4,'essay','teacher','학교나 동네에서 본 안내판이나 광고를 하나 떠올려, 무엇을 알려 주었는지 쓰고 그것을 보고 든 생각을 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C2","difficulty":4,"kind":"essay","stem":"학교나 동네에서 본 안내판이나 광고를 하나 떠올려, 무엇을 알려 주었는지 쓰고 그것을 보고 든 생각을 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 복도에 「뛰지 말고 걸어요」 안내판이 있어요. 복도에서 지킬 일을 알려 줘요. 나는 이 안내판이 꼭 필요하다고 생각해요. 왜냐하면 복도에서 뛰면 부딪혀 다칠 수 있기 때문이에요.","scoring_points":["어떤 매체를 보았는지 썼는가","그 매체가 알려 준 중요한 내용을 썼는가","보고 든 생각을 까닭과 함께 썼는가"]},"explanation":["어떤 매체인지.","중요한 내용.","생각과 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L01_challenge#10','kor',2,1,'u6','L01','g2_1_kor_u6_L01_challenge','lesson_challenge','K2-1-u6-C1',4,'essay','teacher','안내판을 읽고 이 안내판에 꼭 더 넣으면 좋을 지킬 일을 하나 써 보고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C1","difficulty":4,"kind":"essay","stem":"안내판을 읽고 이 안내판에 꼭 더 넣으면 좋을 지킬 일을 하나 써 보고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"예: 「4. 놀이 기구에서 친구를 밀지 않아요.」를 넣고 싶어요. 왜냐하면 밀면 떨어져서 크게 다칠 수 있기 때문이에요.","scoring_points":["놀이터에서 지킬 일을 알맞게 썼는가","안내판에 이미 있는 내용과 겹치지 않는가","그렇게 생각한 까닭을 썼는가"]},"explanation":["알맞은 지킬 일.","겹치지 않기.","까닭."],"asset":{"type":"passage","lines":["1. 미끄럼틀은 앉아서 차례대로 타요.","2. 그네가 움직일 때에는 그네 앞으로 지나가지 않아요.","3. 쓰레기는 쓰레기통에 넣어요."],"title":"놀이터 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#1','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],true,'{"seq":1,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"줄넘기를 하면 좋은 점","correct":true},{"t":"줄넘기 줄의 색깔","mis":"K2-1-u6-X03"},{"t":"운동장의 크기","mis":"K2-1-u6-X04"}],"explanation":["제목이 「줄넘기의 좋은 점」이니 줄넘기의 좋은 점을 알려 주는 글이에요.","줄 색깔은 글에 나오지 않아요.","운동장은 줄넘기를 할 수 있는 곳의 예일 뿐이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"손을 깨끗이 씻는 일","correct":true},{"t":"비누의 냄새","mis":"K2-1-u6-X03"},{"t":"감기에 걸린 친구 이름","mis":"K2-1-u6-X04"}],"explanation":["제목이 「손을 깨끗이 씻어요」이니 손 씻기를 알려 주는 글이에요.","비누 냄새는 글에 나오지 않아요.","친구 이름은 글에 없어요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#2','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],true,'{"seq":2,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"줄넘기","correct":true},{"t":"마당","mis":"K2-1-u6-X05"},{"t":"다리","mis":"K2-1-u6-X05"}],"explanation":["「줄넘기」가 문단마다 여러 번 나와요.","「마당」과 「다리」는 한 번씩만 나와요.","자주 나오는 낱말이 중요한 낱말이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"손","correct":true},{"t":"감기","mis":"K2-1-u6-X05"},{"t":"거품","mis":"K2-1-u6-X05"}],"explanation":["「손」이 글 곳곳에 여러 번 나와요.","「감기」와 「거품」은 한 번씩만 나와요.","자주 나오는 낱말이 중요한 낱말이에요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#3','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C3',1,'ox','auto','제목에는 글에서 가장 중요한 내용이 담겨 있는 경우가 많아요.',ARRAY['K2-1-u6-X04']::text[],true,'{"seq":3,"concept":"K2-1-u6-C3","difficulty":1,"kind":"ox","stem":"제목에는 글에서 가장 중요한 내용이 담겨 있는 경우가 많아요.","answer":"O","reason_options":[{"t":"제목을 보면 글이 무엇을 알려 줄지 알 수 있으니까","correct":true},{"t":"제목은 글과 상관없이 아무렇게나 붙이니까","mis":"K2-1-u6-X04"}],"mis":"K2-1-u6-X04","explanation":["제목은 글 전체의 중요한 내용을 알려 줘요.","그래서 글을 읽기 전에 제목부터 살펴요.","제목을 소리 내어 읽어 봐요."],"variant_rule":{"alt":[{"stem":"글에 한 번만 나오는 낱말이 그 글에서 가장 중요한 낱말이에요.","answer":"X","reason_options":[{"t":"여러 번 나오고 제목과 관련 있는 낱말이 중요한 낱말이니까","correct":true},{"t":"한 번만 나와야 눈에 잘 띄니까","mis":"K2-1-u6-X05"}],"explanation":["중요한 낱말은 글에 여러 번 나와요.","한 번만 나오는 낱말은 덧붙인 것일 때가 많아요.","나올 때마다 세어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#4','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',1,'mc','auto','각 부분에서 가장 중요한 문장을 무엇이라고 하나요?',ARRAY['K2-1-u6-X06']::text[],true,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"각 부분에서 가장 중요한 문장을 무엇이라고 하나요?","options":[{"t":"중심 문장","correct":true},{"t":"끝 문장","mis":"K2-1-u6-X06"},{"t":"긴 문장","mis":"K2-1-u6-X06"}],"explanation":["각 부분에서 가장 중요한 문장을 중심 문장이라고 해요.","끝에 있거나 길다고 중심 문장인 것은 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"variant_rule":{"alt":[{"stem":"글에서 중요한 내용을 찾는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글자 수 세기","correct":true},{"t":"제목 살펴보기","mis":"K2-1-u6-X16"},{"t":"중심 문장 찾기","mis":"K2-1-u6-X16"}],"explanation":["글자 수를 센다고 중요한 내용을 알 수는 없어요.","제목 살펴보기와 중심 문장 찾기는 알맞은 방법이에요.","물음의 「않은」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#5','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],true,'{"seq":5,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기를 하면 몸이 튼튼해집니다.","correct":true},{"t":"팔과 다리를 함께 움직이기 때문입니다.","mis":"K2-1-u6-X06"},{"t":"줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다.","mis":"K2-1-u6-X07"}],"explanation":["첫째 부분에서 가장 하고 싶은 말은 「몸이 튼튼해진다」예요.","「~때문입니다」는 까닭을 덧붙인 문장이에요.","「줄 하나만 있으면」은 셋째 부분의 문장이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"손을 깨끗이 씻으면 감기를 막을 수 있습니다.","correct":true},{"t":"손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","mis":"K2-1-u6-X06"},{"t":"손바닥과 손등, 손가락 사이까지 문지릅니다.","mis":"K2-1-u6-X07"}],"explanation":["첫째 부분에서 가장 하고 싶은 말은 「감기를 막을 수 있다」예요.","「~때문입니다」는 까닭을 덧붙인 문장이에요.","「손가락 사이까지」는 둘째 부분의 문장이에요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#6','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',2,'match','auto','글을 읽고 각 부분과 중요한 내용을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K2-1-u6-C5","difficulty":2,"kind":"match","stem":"글을 읽고 각 부분과 중요한 내용을 알맞게 이어 보세요.","pairs":[{"l":"첫째 부분","r":"몸이 튼튼해진다"},{"l":"둘째 부분","r":"친구와 즐겁게 할 수 있다"},{"l":"셋째 부분","r":"어디서나 할 수 있다"}],"mis":"K2-1-u6-X06","explanation":["첫째 부분은 몸이 튼튼해진다는 내용이에요.","둘째 부분은 친구와 즐겁게 할 수 있다는 내용이에요.","셋째 부분은 어디서나 할 수 있다는 내용이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 각 부분과 중요한 내용을 알맞게 이어 보세요.","pairs":[{"l":"첫째 부분","r":"손을 씻으면 감기를 막는다"},{"l":"둘째 부분","r":"비누로 구석구석 씻는다"},{"l":"셋째 부분","r":"씻어야 할 때가 있다"}],"explanation":["첫째 부분은 감기를 막는다는 내용이에요.","둘째 부분은 씻는 방법이에요.","셋째 부분은 꼭 씻어야 할 때예요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#7','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C4',2,'mc','auto','글을 읽고 답해 보세요. 이 글의 중요한 낱말을 바르게 모은 것은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],true,'{"seq":7,"concept":"K2-1-u6-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글의 중요한 낱말을 바르게 모은 것은 어느 것인가요?","options":[{"t":"줄넘기 · 좋은 점","correct":true},{"t":"줄넘기 · 마당","mis":"K2-1-u6-X05"},{"t":"운동장 · 마당","mis":"K2-1-u6-X05"}],"explanation":["「줄넘기」는 자주 나오고, 「좋은 점」은 제목에 있어요.","「마당」과 「운동장」은 한 번씩만 나온 예예요.","자주 나오고 제목과 관련 있는 낱말을 골라요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 이 글의 중요한 낱말을 바르게 모은 것은 어느 것인가요?","options":[{"t":"손 · 씻기","correct":true},{"t":"손 · 거품","mis":"K2-1-u6-X05"},{"t":"균 · 밥","mis":"K2-1-u6-X05"}],"explanation":["「손」과 「씻다」가 글에 여러 번 나오고 제목에도 있어요.","「거품」·「균」·「밥」은 한 번씩만 나와요.","자주 나오고 제목과 관련 있는 낱말을 골라요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#8','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C4',2,'sa','auto','「토끼는 귀가 깁니다. 토끼는 풀을 좋아합니다. 토끼는 깡충깡충 뜁니다.」 이 글에 자주 나오는 낱말을 두 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u6-C4","difficulty":2,"kind":"sa","stem":"「토끼는 귀가 깁니다. 토끼는 풀을 좋아합니다. 토끼는 깡충깡충 뜁니다.」 이 글에 자주 나오는 낱말을 두 글자로 써 보세요.","answer":["토끼"],"explanation":["「토끼」가 세 문장에 모두 나와요.","자주 나오는 낱말이 중요한 낱말이에요.","이 글은 토끼에 대해 알려 주는 글이에요."],"variant_rule":{"alt":[{"stem":"「기린은 목이 깁니다. 기린은 나뭇잎을 먹습니다. 기린은 키가 큽니다.」 이 글에 자주 나오는 낱말을 두 글자로 써 보세요.","answer":["기린"],"explanation":["「기린」이 세 문장에 모두 나와요.","자주 나오는 낱말이 중요한 낱말이에요.","이 글은 기린에 대해 알려 주는 글이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#9','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',2,'mc','auto','중심 문장을 찾을 때 생각하면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X03']::text[],true,'{"seq":9,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"중심 문장을 찾을 때 생각하면 좋은 것은 어느 것인가요?","options":[{"t":"이 부분에서 가장 하고 싶은 말이 무엇인지","correct":true},{"t":"어느 문장이 가장 긴지","mis":"K2-1-u6-X06"},{"t":"어느 문장에 그림이 있는지","mis":"K2-1-u6-X03"}],"explanation":["그 부분에서 가장 하고 싶은 말이 중심 문장이에요.","길다고 중심 문장은 아니에요.","그림이 있는지는 상관없어요."],"variant_rule":{"alt":[{"stem":"「~때문입니다」로 끝나는 문장은 주로 어떤 문장인가요?","options":[{"t":"앞 문장의 까닭을 덧붙인 문장","correct":true},{"t":"그 부분의 중심 문장","mis":"K2-1-u6-X06"},{"t":"글의 제목","mis":"K2-1-u6-X04"}],"explanation":["「~때문입니다」는 까닭을 덧붙일 때 써요.","중심 문장을 뒷받침하는 문장이에요.","제목은 글 맨 위에 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_basic#10','kor',2,1,'u6','L03','g2_1_kor_u6_L03_basic','lesson_basic','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"도윤 — 「줄넘기는 마당에서만 할 수 있다.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"하린 — 「줄넘기를 하면 몸이 튼튼해진다.」","mis":"K2-1-u6-X16"},{"t":"지후 — 「줄넘기는 친구와 즐겁게 할 수 있다.」","mis":"K2-1-u6-X16"}],"explanation":["글에는 줄넘기를 어디서나 할 수 있다고 했어요.","「마당에서만」은 글의 내용과 달라요.","하린이와 지후는 바르게 정리했어요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"예린 — 「손은 밥을 먹은 뒤에만 씻으면 된다.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"민호 — 「손을 씻으면 감기를 막을 수 있다.」","mis":"K2-1-u6-X16"},{"t":"서아 — 「비누로 거품을 내어 구석구석 씻는다.」","mis":"K2-1-u6-X16"}],"explanation":["글에는 밥을 먹기 전과 밖에서 돌아왔을 때 씻는다고 했어요.","「밥을 먹은 뒤에만」은 글과 달라요.","민호와 서아는 바르게 정리했어요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#1','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 셋째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":1,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 셋째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다.","correct":true},{"t":"운동장에서도, 집 앞 마당에서도 할 수 있습니다.","mis":"K2-1-u6-X06"},{"t":"긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","mis":"K2-1-u6-X07"}],"explanation":["셋째 부분에서 가장 하고 싶은 말은 「어디서나 할 수 있다」예요.","「운동장에서도, 마당에서도」는 예를 든 문장이에요.","「긴 줄」은 둘째 부분의 문장이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#2','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C4',2,'mc','auto','글을 읽고 답해 보세요. 자주 나오는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":2,"concept":"K2-1-u6-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 자주 나오는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"마당","correct":true},{"t":"줄넘기","mis":"K2-1-u6-X16"},{"t":"할 수 있습니다","mis":"K2-1-u6-X16"}],"explanation":["「마당」은 한 번만 나와요.","「줄넘기」와 「할 수 있습니다」는 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#3','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C3',3,'mc','auto','「꿀벌은 꽃에서 꿀을 모읍니다. 꽃가루를 옮겨 열매가 열리도록 돕습니다. 힘을 모아 벌집을 짓습니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":3,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「꿀벌은 꽃에서 꿀을 모읍니다. 꽃가루를 옮겨 열매가 열리도록 돕습니다. 힘을 모아 벌집을 짓습니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"꿀벌이 하는 일","correct":true},{"t":"꽃의 색깔","mis":"K2-1-u6-X04"},{"t":"맛있는 꿀 요리","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 꿀벌이 하는 일을 알려 줘요.","꽃 색깔은 글에 나오지 않아요.","꿀 요리는 글과 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#4','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',3,'error','auto','글의 중심 문장을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X16']::text[],false,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글의 중심 문장을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"소율 — 「둘째 부분: 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.」","correct":true,"mis_target":"K2-1-u6-X06"},{"t":"시우 — 「첫째 부분: 줄넘기를 하면 몸이 튼튼해집니다.」","mis":"K2-1-u6-X16"},{"t":"아린 — 「셋째 부분: 줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다.」","mis":"K2-1-u6-X16"}],"explanation":["둘째 부분의 중심 문장은 「줄넘기는 친구와 함께 즐겁게 할 수 있습니다.」예요.","「긴 줄을 여럿이 함께 넘으면」은 예를 든 문장이에요.","시우와 아린이는 바르게 찾았어요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#5','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',3,'ox','auto','글을 읽고 답해 보세요. 「팔과 다리를 함께 움직이기 때문입니다.」는 이 글 전체의 중요한 내용이에요.',ARRAY['K2-1-u6-X06']::text[],false,'{"seq":5,"concept":"K2-1-u6-C5","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 「팔과 다리를 함께 움직이기 때문입니다.」는 이 글 전체의 중요한 내용이에요.","answer":"X","reason_options":[{"t":"첫째 부분에서 까닭을 덧붙인 문장일 뿐이니까","correct":true},{"t":"글에 나온 문장은 모두 글 전체의 중요한 내용이니까","mis":"K2-1-u6-X06"}],"mis":"K2-1-u6-X06","explanation":["이 문장은 몸이 튼튼해지는 까닭을 덧붙였어요.","글 전체의 중요한 내용은 「줄넘기의 좋은 점」이에요.","중심 문장과 덧붙인 문장을 가려요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#6','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C3',3,'mc','auto','제목이 「겨울잠을 자는 동물」인 글에 나올 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":6,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"제목이 「겨울잠을 자는 동물」인 글에 나올 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"곰과 개구리가 겨울에 잠을 자는 까닭","correct":true},{"t":"여름 바닷가에서 노는 방법","mis":"K2-1-u6-X04"},{"t":"눈사람 만드는 방법","mis":"K2-1-u6-X04"}],"explanation":["제목을 보면 겨울잠을 자는 동물 이야기가 나올 거예요.","여름 바닷가는 제목과 맞지 않아요.","눈사람은 겨울과 관련 있지만 동물 이야기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#7','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C4',3,'mc','auto','「사과는 빨갛습니다. 사과는 새콤달콤합니다. 아침에 먹는 사과는 몸에 좋습니다.」 이 글에서 중요한 낱말과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":7,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"「사과는 빨갛습니다. 사과는 새콤달콤합니다. 아침에 먹는 사과는 몸에 좋습니다.」 이 글에서 중요한 낱말과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「사과」 — 세 문장에 모두 나오니까","correct":true},{"t":"「아침」 — 마지막 문장에 나오니까","mis":"K2-1-u6-X05"},{"t":"「빨갛다」 — 맨 처음에 나오니까","mis":"K2-1-u6-X05"}],"explanation":["「사과」가 세 문장에 모두 나와요.","「아침」과 「빨갛다」는 한 번씩만 나와요.","처음에 나온다고 중요한 낱말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#8','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',4,'mc','auto','글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['K2-1-u6-X06']::text[],false,'{"seq":8,"concept":"K2-1-u6-C5","difficulty":4,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"줄넘기를 하면 몸이 튼튼해지고, 친구와 즐겁게 할 수 있으며, 어디서나 할 수 있다.","correct":true},{"t":"줄넘기를 하면 몸이 튼튼해진다.","mis":"K2-1-u6-X06"},{"t":"줄넘기는 운동장과 마당에서 할 수 있다.","mis":"K2-1-u6-X06"}],"explanation":["세 부분의 중심 문장을 모두 모아 정리했어요.","한 부분의 내용만으로는 글 전체를 정리할 수 없어요.","운동장과 마당은 예를 든 내용이에요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#9','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 세 부분의 중심 문장을 찾아 쓰고, 그것을 모아 이 글의 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 세 부분의 중심 문장을 찾아 쓰고, 그것을 모아 이 글의 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 첫째 — 손을 깨끗이 씻으면 감기를 막을 수 있다. 둘째 — 비누로 거품을 내어 구석구석 씻는다. 셋째 — 밖에서 돌아왔을 때와 밥 먹기 전에 꼭 씻는다. 정리: 손을 깨끗이 씻으면 감기를 막을 수 있으니, 비누로 구석구석 씻고 씻어야 할 때를 꼭 지키자.","scoring_points":["세 부분의 중심 문장을 찾아 썼는가","까닭이나 예를 든 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["세 중심 문장.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L03_challenge#10','kor',2,1,'u6','L03','g2_1_kor_u6_L03_challenge','lesson_challenge','K2-1-u6-C4',4,'essay','teacher','좋아하는 동물이나 물건 하나를 골라, 그 낱말이 자주 나오도록 세 문장의 짧은 글을 쓰고 알맞은 제목을 붙여 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C4","difficulty":4,"kind":"essay","stem":"좋아하는 동물이나 물건 하나를 골라, 그 낱말이 자주 나오도록 세 문장의 짧은 글을 쓰고 알맞은 제목을 붙여 보세요.","answer_guide":{"answer":"예: 제목 — 우리 집 고양이. 우리 집 고양이는 털이 부드러워요. 고양이는 햇볕 아래에서 잠을 자요. 고양이는 공을 굴리며 놀아요.","scoring_points":["하나의 대상에 대해 세 문장을 썼는가","그 대상을 나타내는 낱말이 자주 나오는가","글 내용에 어울리는 제목을 붙였는가"]},"explanation":["세 문장.","자주 나오는 낱말.","어울리는 제목."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#1','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],true,'{"seq":1,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 내용은 무엇인가요?","options":[{"t":"꿀벌이 하는 일","correct":true},{"t":"꿀벌의 색깔","mis":"K2-1-u6-X03"},{"t":"꽃집에서 꽃 사는 법","mis":"K2-1-u6-X04"}],"explanation":["제목이 「꿀벌이 하는 일」이니 꿀벌이 하는 일을 알려 줄 거예요.","꿀벌 색깔은 글에 나오지 않아요.","꽃집 이야기는 제목과 맞지 않아요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 내용은 무엇인가요?","options":[{"t":"물을 아껴 쓰는 방법","correct":true},{"t":"수영을 잘하는 방법","mis":"K2-1-u6-X04"},{"t":"물의 색깔","mis":"K2-1-u6-X03"}],"explanation":["제목이 「물을 아껴 써요」이니 물을 아끼는 방법을 알려 줄 거예요.","수영은 제목과 맞지 않아요.","물의 색깔은 글에 나오지 않아요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#2','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',1,'mc','auto','글을 읽고 답해 보세요. 꿀벌이 하는 일로 글에 나온 것은 어느 것인가요?',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":2,"concept":"K2-1-u6-C5","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 꿀벌이 하는 일로 글에 나온 것은 어느 것인가요?","options":[{"t":"꽃에서 꿀을 모은다","correct":true},{"t":"노래를 부른다","mis":"K2-1-u6-X07"},{"t":"잠만 잔다","mis":"K2-1-u6-X07"}],"explanation":["글에 꿀벌이 꽃에서 꿀을 모은다고 했어요.","노래를 부르거나 잠만 잔다는 말은 글에 없어요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 물을 아끼는 방법으로 글에 나온 것은 어느 것인가요?","options":[{"t":"이를 닦을 때 컵에 물을 받아 쓴다","correct":true},{"t":"목욕물을 가득 받아 놓는다","mis":"K2-1-u6-X07"},{"t":"물을 틀어 놓고 이를 닦는다","mis":"K2-1-u6-X07"}],"explanation":["글에 컵에 물을 받아 쓴다고 했어요.","물을 가득 받거나 틀어 놓는 것은 물을 낭비하는 일이에요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#3','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',1,'ox','auto','글을 읽고 답해 보세요. 꿀벌은 혼자서만 벌집을 짓는다고 했어요.',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":3,"concept":"K2-1-u6-C5","difficulty":1,"kind":"ox","stem":"글을 읽고 답해 보세요. 꿀벌은 혼자서만 벌집을 짓는다고 했어요.","answer":"X","reason_options":[{"t":"글에 여럿이 힘을 모아 벌집을 짓는다고 했으니까","correct":true},{"t":"꿀벌은 언제나 혼자 다니니까","mis":"K2-1-u6-X07"}],"mis":"K2-1-u6-X07","explanation":["글에 「여럿이 힘을 모아」 벌집을 짓는다고 했어요.","「혼자서만」은 글과 달라요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 비누칠을 하는 동안에는 수도꼭지를 잠근다고 했어요.","answer":"O","reason_options":[{"t":"글에 그렇게 쓰여 있으니까","correct":true},{"t":"물은 계속 틀어 두어야 하니까","mis":"K2-1-u6-X07"}],"explanation":["글에 비누칠하는 동안 수도꼭지를 잠근다고 했어요.","그렇게 하면 물을 아낄 수 있어요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#4','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],true,'{"seq":4,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"꿀벌","correct":true},{"t":"열매","mis":"K2-1-u6-X05"},{"t":"벌집","mis":"K2-1-u6-X05"}],"explanation":["「꿀벌」이 세 문장에 모두 나와요.","「열매」와 「벌집」은 한 번씩만 나와요.","자주 나오는 낱말이 중요한 낱말이에요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"물","correct":true},{"t":"컵","mis":"K2-1-u6-X05"},{"t":"샤워","mis":"K2-1-u6-X05"}],"explanation":["「물」이 여러 번 나와요.","「컵」과 「샤워」는 한 번씩만 나와요.","자주 나오는 낱말이 중요한 낱말이에요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#5','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',2,'match','auto','글을 읽고 글의 문장과 꿀벌이 하는 일을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C5","difficulty":2,"kind":"match","stem":"글을 읽고 글의 문장과 꿀벌이 하는 일을 알맞게 이어 보세요.","pairs":[{"l":"꽃에서 꿀을 모읍니다","r":"꿀 모으기"},{"l":"꽃가루를 옮겨 줍니다","r":"열매 맺기 돕기"},{"l":"힘을 모아 짓습니다","r":"벌집 짓기"}],"mis":"K2-1-u6-X07","explanation":["꿀을 모으는 일이에요.","꽃가루를 옮겨 열매가 열리게 도와요.","여럿이 힘을 모아 벌집을 지어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"글을 읽고 물을 쓰는 때와 아끼는 방법을 알맞게 이어 보세요.","pairs":[{"l":"이를 닦을 때","r":"컵에 물을 받아 쓴다"},{"l":"비누칠을 할 때","r":"수도꼭지를 잠근다"},{"l":"샤워를 할 때","r":"짧게 한다"}],"explanation":["이를 닦을 때는 컵을 써요.","비누칠할 때는 물을 잠가요.","샤워는 짧게 해요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#6','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],true,'{"seq":6,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"꿀벌은 꿀을 모으고, 꽃가루를 옮기고, 함께 벌집을 짓는다.","correct":true},{"t":"꿀벌은 꽃에서 꿀을 모은다.","mis":"K2-1-u6-X06"},{"t":"꿀벌은 꽃을 좋아한다.","mis":"K2-1-u6-X07"}],"explanation":["꿀벌이 하는 일 세 가지를 모두 모았어요.","한 가지만으로는 글 전체를 정리할 수 없어요.","「꽃을 좋아한다」는 글에 없는 내용이에요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 이 글의 중요한 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"컵에 물을 받아 쓰고, 수도꼭지를 잠그고, 샤워를 짧게 해서 물을 아끼자.","correct":true},{"t":"샤워를 짧게 하자.","mis":"K2-1-u6-X06"},{"t":"물을 많이 마시자.","mis":"K2-1-u6-X07"}],"explanation":["물을 아끼는 방법 세 가지를 모두 모았어요.","한 가지만으로는 글 전체를 정리할 수 없어요.","물을 마시자는 말은 글에 없어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#7','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C3',2,'mc','auto','「강아지는 냄새를 잘 맡습니다. 강아지는 주인을 반기며 꼬리를 흔듭니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],true,'{"seq":7,"concept":"K2-1-u6-C3","difficulty":2,"kind":"mc","stem":"「강아지는 냄새를 잘 맡습니다. 강아지는 주인을 반기며 꼬리를 흔듭니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"강아지의 특징","correct":true},{"t":"고양이 기르는 법","mis":"K2-1-u6-X04"},{"t":"맛있는 간식","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 강아지에 대해 알려 줘요.","고양이는 글에 나오지 않아요.","간식은 글과 상관없어요."],"variant_rule":{"alt":[{"stem":"「해바라기는 해를 따라 고개를 돌립니다. 해바라기 씨는 먹을 수 있습니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"해바라기에 대해 알아봐요","correct":true},{"t":"장미꽃 키우기","mis":"K2-1-u6-X04"},{"t":"여름 방학 계획","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 해바라기에 대해 알려 줘요.","장미꽃은 글에 나오지 않아요.","방학 계획은 글과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#8','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',2,'sa','auto','글을 읽고 답해 보세요. 꿀벌은 무엇을 옮겨 열매가 열리도록 돕나요? 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u6-C5","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 꿀벌은 무엇을 옮겨 열매가 열리도록 돕나요? 세 글자로 써 보세요.","answer":["꽃가루"],"explanation":["글에 꿀벌이 꽃가루를 옮긴다고 했어요.","꽃가루가 옮겨져야 열매가 열려요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 이를 닦을 때 물을 받아 쓰라고 한 그릇은 무엇인가요? 한 글자로 써 보세요.","answer":["컵"],"explanation":["글에 컵에 물을 받아 쓴다고 했어요.","컵을 쓰면 물을 덜 쓰게 돼요.","글에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#9','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',2,'mc','auto','새로운 글을 읽고 중요한 내용을 찾는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X06']::text[],true,'{"seq":9,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"새로운 글을 읽고 중요한 내용을 찾는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"제목 살펴보기 → 자주 나오는 낱말 찾기 → 중심 문장 모아 정리하기","correct":true},{"t":"그림 색깔 보기 → 글자 수 세기 → 끝내기","mis":"K2-1-u6-X03"},{"t":"끝 문장만 읽기 → 끝내기","mis":"K2-1-u6-X06"}],"explanation":["제목, 자주 나오는 낱말, 중심 문장 차례로 살펴요.","그림 색깔이나 글자 수로는 중요한 내용을 알 수 없어요.","끝 문장만 읽으면 다른 부분을 놓쳐요."],"variant_rule":{"alt":[{"stem":"중요한 내용을 찾으며 글을 읽으면 좋은 점은 무엇인가요?","options":[{"t":"글이 알려 주는 핵심을 알고 새롭게 안 것을 나눌 수 있어요","correct":true},{"t":"글을 읽지 않아도 돼요","mis":"K2-1-u6-X07"},{"t":"글자를 빨리 쓸 수 있어요","mis":"K2-1-u6-X03"}],"explanation":["핵심을 알면 새롭게 안 것을 친구와 나눌 수 있어요.","글을 꼼꼼히 읽어야 중요한 내용을 찾아요.","글자 쓰기 빠르기와는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_basic#10','kor',2,1,'u6','L05','g2_1_kor_u6_L05_basic','lesson_basic','K2-1-u6-C5',3,'error','auto','글을 읽고 새롭게 안 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 새롭게 안 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"지안 — 「꿀벌은 꽃잎을 먹고 산대.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"하윤 — 「꿀벌이 꽃가루를 옮겨서 열매가 열린대.」","mis":"K2-1-u6-X16"},{"t":"준우 — 「꿀벌은 여럿이 함께 벌집을 짓는대.」","mis":"K2-1-u6-X16"}],"explanation":["꽃잎을 먹는다는 말은 글에 없어요.","글에 없는 내용을 있다고 하면 안 돼요.","하윤이와 준우는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 새롭게 안 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도담 — 「샤워는 오래 해야 물을 아낀대.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"서윤 — 「이를 닦을 때 컵을 쓰면 물을 아낀대.」","mis":"K2-1-u6-X16"},{"t":"현우 — 「비누칠할 때는 물을 잠가야 한대.」","mis":"K2-1-u6-X16"}],"explanation":["글에는 샤워를 짧게 한다고 했어요.","「오래」는 글과 반대예요.","서윤이와 현우는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#1','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 이 글의 첫 문장 「물을 아껴 쓰는 방법을 알아봅시다.」는 어떤 문장인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X03']::text[],false,'{"seq":1,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글의 첫 문장 「물을 아껴 쓰는 방법을 알아봅시다.」는 어떤 문장인가요?","options":[{"t":"글 전체가 무엇을 알려 줄지 밝힌 문장","correct":true},{"t":"이를 닦는 방법만 알려 주는 문장","mis":"K2-1-u6-X06"},{"t":"글과 상관없는 문장","mis":"K2-1-u6-X03"}],"explanation":["첫 문장이 물을 아끼는 방법을 알아보자고 밝혀요.","이를 닦는 방법은 그다음 문장의 내용이에요.","첫 문장은 글 전체와 관련 있어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#2','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 꿀벌이 하는 일이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":2,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 꿀벌이 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"꿀을 모아 사람에게 팔아요","correct":true},{"t":"벌집을 지어요","mis":"K2-1-u6-X16"},{"t":"꽃가루를 옮겨요","mis":"K2-1-u6-X16"}],"explanation":["꿀을 판다는 말은 글에 없어요.","벌집 짓기와 꽃가루 옮기기는 꿀벌이 하는 일이에요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#3','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C3',3,'mc','auto','글을 읽고 답해 보세요. 제목을 「꿀벌의 생김새」로 바꾼다면 어떤 점이 알맞지 않은가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":3,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 「꿀벌의 생김새」로 바꾼다면 어떤 점이 알맞지 않은가요?","options":[{"t":"글은 꿀벌의 생김새가 아니라 꿀벌이 하는 일을 알려 주니까","correct":true},{"t":"「꿀벌」이라는 낱말이 들어 있으니까","mis":"K2-1-u6-X04"},{"t":"제목이 짧아지니까","mis":"K2-1-u6-X04"}],"explanation":["글 내용은 꿀벌이 하는 일이에요.","제목은 글의 중요한 내용과 맞아야 해요.","낱말이 같거나 길이가 짧다고 알맞은 제목은 아니에요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#4','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 한 부분만 보고 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X16']::text[],false,'{"seq":4,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 한 부분만 보고 정리한 친구는 누구인가요?","options":[{"t":"민지 — 「이 글의 중요한 내용은 샤워를 짧게 하자는 것이다.」","correct":true,"mis_target":"K2-1-u6-X06"},{"t":"로아 — 「컵 쓰기, 수도꼭지 잠그기, 짧은 샤워로 물을 아끼자는 것이다.」","mis":"K2-1-u6-X16"},{"t":"태민 — 「여러 방법으로 물을 아껴 쓰자는 것이다.」","mis":"K2-1-u6-X16"}],"explanation":["샤워는 물을 아끼는 방법 가운데 하나일 뿐이에요.","글 전체의 중요한 내용은 물을 아끼는 여러 방법이에요.","로아와 태민이는 글 전체를 보고 정리했어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#5','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',3,'ox','auto','글을 읽고 답해 보세요. 「꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.」를 읽고 꿀벌이 없으면 열매가 잘 열리지 않을 수 있다는 것을 새롭게 알 수 있어요.',ARRAY['K2-1-u6-X07']::text[],false,'{"seq":5,"concept":"K2-1-u6-C5","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 「꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.」를 읽고 꿀벌이 없으면 열매가 잘 열리지 않을 수 있다는 것을 새롭게 알 수 있어요.","answer":"O","reason_options":[{"t":"꿀벌이 꽃가루를 옮겨야 열매가 열린다고 했으니까","correct":true},{"t":"글에 꿀벌이 열매를 먹는다고 했으니까","mis":"K2-1-u6-X07"}],"mis":"K2-1-u6-X07","explanation":["꽃가루를 옮겨 열매가 열리도록 돕는다고 했어요.","그러니 꿀벌이 없으면 열매가 잘 열리지 않을 수 있어요.","꿀벌이 열매를 먹는다는 말은 글에 없어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#6','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":6,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"샤워","correct":true},{"t":"물","mis":"K2-1-u6-X16"},{"t":"아껴","mis":"K2-1-u6-X16"}],"explanation":["「샤워」는 한 번만 나와요.","「물」과 「아껴」는 제목에도 있고 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#7','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',3,'mc','auto','「우리 몸에는 뼈가 있습니다. 뼈는 몸을 받쳐 줍니다. 그래서 우리는 똑바로 설 수 있습니다.」 이 글의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06']::text[],false,'{"seq":7,"concept":"K2-1-u6-C5","difficulty":3,"kind":"mc","stem":"「우리 몸에는 뼈가 있습니다. 뼈는 몸을 받쳐 줍니다. 그래서 우리는 똑바로 설 수 있습니다.」 이 글의 중심 문장은 어느 것인가요?","options":[{"t":"뼈는 몸을 받쳐 줍니다.","correct":true},{"t":"그래서 우리는 똑바로 설 수 있습니다.","mis":"K2-1-u6-X06"},{"t":"우리 몸에는 뼈가 있습니다.","mis":"K2-1-u6-X06"}],"explanation":["뼈가 몸을 받쳐 준다는 것이 가장 하고 싶은 말이에요.","「그래서 ~」는 그 결과를 덧붙인 문장이에요.","뼈가 있다는 것은 이야기를 시작하는 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#8','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',4,'mc','auto','글을 읽고 새롭게 안 내용과 더 알고 싶은 것을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X03']::text[],false,'{"seq":8,"concept":"K2-1-u6-C5","difficulty":4,"kind":"mc","stem":"글을 읽고 새롭게 안 내용과 더 알고 싶은 것을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「꿀벌이 열매가 열리게 돕는다는 것을 알았어. 꿀벌이 하루에 꽃을 얼마나 많이 찾아다니는지 더 알고 싶어.」","correct":true},{"t":"「꿀벌은 노래를 잘 부른다는 것을 알았어.」","mis":"K2-1-u6-X07"},{"t":"「꿀벌은 무섭다. 더 알고 싶은 것은 없어.」","mis":"K2-1-u6-X03"}],"explanation":["글에서 안 내용과 그와 이어지는 궁금한 점을 말했어요.","노래를 부른다는 것은 글에 없어요.","「무섭다」는 새롭게 안 내용이 아니에요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#9','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중요한 내용을 한 문장으로 정리하고, 글을 읽고 내가 실천할 일을 한 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중요한 내용을 한 문장으로 정리하고, 글을 읽고 내가 실천할 일을 한 가지 써 보세요.","answer_guide":{"answer":"예: 정리 — 컵 쓰기, 수도꼭지 잠그기, 짧은 샤워로 물을 아껴 쓰자. 실천 — 오늘부터 이를 닦을 때 꼭 컵에 물을 받아 쓰겠어요.","scoring_points":["물을 아끼는 여러 방법을 모아 한 문장으로 정리했는가","글에 없는 내용을 넣지 않았는가","실천할 일을 구체적으로 썼는가"]},"explanation":["한 문장 정리.","글에 있는 내용만.","실천할 일."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L05_challenge#10','kor',2,1,'u6','L05','g2_1_kor_u6_L05_challenge','lesson_challenge','K2-1-u6-C3',4,'essay','teacher','글을 읽고 답해 보세요. 이 글에 어울리는 새 제목을 하나 지어 쓰고, 그 제목이 알맞은 까닭을 글의 내용을 들어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C3","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글에 어울리는 새 제목을 하나 지어 쓰고, 그 제목이 알맞은 까닭을 글의 내용을 들어 써 보세요.","answer_guide":{"answer":"예: 「바쁜 꿀벌의 하루」 — 글에 꿀벌이 꿀을 모으고, 꽃가루를 옮기고, 벌집을 짓는 여러 가지 일이 나오기 때문이에요.","scoring_points":["글의 내용과 어울리는 제목을 지었는가","제목이 글 전체를 아우르는가","글의 내용을 들어 까닭을 썼는가"]},"explanation":["어울리는 제목.","글 전체 아우르기.","까닭."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#1','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 하린이가 기르고 싶어 하는 것은 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],true,'{"seq":1,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하린이가 기르고 싶어 하는 것은 무엇인가요?","options":[{"t":"강낭콩","correct":true},{"t":"물고기","mis":"K2-1-u6-X08"},{"t":"달팽이","mis":"K2-1-u6-X08"}],"explanation":["하린이는 「강낭콩을 기르자.」라고 했어요.","물고기는 도윤이, 달팽이는 지후의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 민호가 하고 싶어 하는 놀이는 무엇인가요?","options":[{"t":"줄넘기","correct":true},{"t":"피구","mis":"K2-1-u6-X08"},{"t":"숨바꼭질","mis":"K2-1-u6-X08"}],"explanation":["민호는 「줄넘기를 하자.」라고 했어요.","피구는 서아, 숨바꼭질은 예린이의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#2','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',1,'mc','auto','대화를 읽고 답해 보세요. 도윤이가 물고기를 기르자고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],true,'{"seq":2,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이가 물고기를 기르자고 한 까닭은 무엇인가요?","options":[{"t":"먹이만 잘 주면 되어서 돌보기 쉬우니까","correct":true},{"t":"자라는 모습을 날마다 볼 수 있으니까","mis":"K2-1-u6-X08"},{"t":"물고기 색깔이 파란색이니까","mis":"K2-1-u6-X09"}],"explanation":["도윤이는 물고기가 돌보기 쉽다고 했어요.","자라는 모습은 하린이가 말한 까닭이에요.","물고기 색깔은 대화에 나오지 않아요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 예린이가 숨바꼭질을 하자고 한 까닭은 무엇인가요?","options":[{"t":"규칙이 쉬워서 누구나 할 수 있으니까","correct":true},{"t":"모두가 함께 뛸 수 있으니까","mis":"K2-1-u6-X08"},{"t":"오늘은 화요일이니까","mis":"K2-1-u6-X09"}],"explanation":["예린이는 숨바꼭질의 규칙이 쉽다고 했어요.","모두가 함께 뛸 수 있다는 것은 서아가 말한 까닭이에요.","「화요일」은 까닭이 아니에요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#3','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C6',1,'ox','auto','인물의 생각은 인물이 한 말에서 찾을 수 있어요.',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"ox","stem":"인물의 생각은 인물이 한 말에서 찾을 수 있어요.","answer":"O","reason_options":[{"t":"인물이 무엇을 하자고 하는지 말에 드러나니까","correct":true},{"t":"인물의 생각은 이름에만 쓰여 있으니까","mis":"K2-1-u6-X07"}],"mis":"K2-1-u6-X07","explanation":["「~하자.」처럼 인물의 말에 생각이 들어 있어요.","이름만으로는 생각을 알 수 없어요.","인물의 말을 꼼꼼히 읽어요."],"variant_rule":{"alt":[{"stem":"인물의 생각을 찾을 때는 그 생각의 까닭도 함께 찾는 것이 좋아요.","answer":"O","reason_options":[{"t":"생각과 까닭은 한 쌍이니까","correct":true},{"t":"까닭은 찾지 않아도 생각만 알면 되니까","mis":"K2-1-u6-X10"}],"explanation":["생각과 까닭은 한 쌍으로 찾아요.","까닭을 알면 그 생각을 더 잘 이해해요.","「왜 그렇게 생각했지?」 물어봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#4','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',1,'mc','auto','인물의 생각에 대한 까닭을 찾을 때 살펴볼 곳은 어디인가요?',ARRAY['K2-1-u6-X01','K2-1-u6-X03']::text[],true,'{"seq":4,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"인물의 생각에 대한 까닭을 찾을 때 살펴볼 곳은 어디인가요?","options":[{"t":"생각 뒤에 나오는 좋은 점이나 옳은 점","correct":true},{"t":"인물의 이름","mis":"K2-1-u6-X01"},{"t":"글의 쪽수","mis":"K2-1-u6-X03"}],"explanation":["생각 뒤에 「~거든」·「~니까」로 나오는 말이 까닭이에요.","이름은 까닭이 아니에요.","쪽수는 글의 내용과 상관없어요."],"variant_rule":{"alt":[{"stem":"까닭을 말할 때 자주 쓰는 말끝은 어느 것인가요?","options":[{"t":"「~거든」, 「~니까」","correct":true},{"t":"「~하자」, 「~할래」","mis":"K2-1-u6-X09"},{"t":"「~안녕」, 「~잘 가」","mis":"K2-1-u6-X09"}],"explanation":["「~거든」·「~니까」는 까닭을 말할 때 써요.","「~하자」는 생각을 말할 때 써요.","인사말은 까닭이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#5','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 기르고 싶어 하는 것을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 기르고 싶어 하는 것을 알맞게 이어 보세요.","pairs":[{"l":"도윤","r":"물고기"},{"l":"하린","r":"강낭콩"},{"l":"지후","r":"달팽이"}],"mis":"K2-1-u6-X08","explanation":["도윤이는 물고기를 기르자고 했어요.","하린이는 강낭콩을 기르자고 했어요.","지후는 달팽이를 기르자고 했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 인물과 하고 싶은 놀이를 알맞게 이어 보세요.","pairs":[{"l":"서아","r":"피구"},{"l":"민호","r":"줄넘기"},{"l":"예린","r":"숨바꼭질"}],"explanation":["서아는 피구를 하자고 했어요.","민호는 줄넘기를 하자고 했어요.","예린이는 숨바꼭질을 하자고 했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#6','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 생각의 까닭이 드러난 말은 어느 것인가요?',ARRAY['K2-1-u6-X09']::text[],true,'{"seq":6,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 생각의 까닭이 드러난 말은 어느 것인가요?","options":[{"t":"「싹이 트고 자라는 모습을 날마다 볼 수 있거든.」","correct":true},{"t":"「강낭콩을 기르자.」","mis":"K2-1-u6-X09"},{"t":"「오늘 내 신발은 파란색이야.」","mis":"K2-1-u6-X09"}],"explanation":["「~볼 수 있거든」이 강낭콩을 기르자는 생각의 까닭이에요.","「기르자」는 생각이지 까닭이 아니에요.","신발 색깔은 까닭이 될 수 없어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대화를 읽고 답해 보세요. 생각의 까닭이 드러난 말은 어느 것인가요?","options":[{"t":"「우리 반 모두가 함께 뛸 수 있으니까.」","correct":true},{"t":"「피구를 하자.」","mis":"K2-1-u6-X09"},{"t":"「점심은 카레였어.」","mis":"K2-1-u6-X09"}],"explanation":["「~뛸 수 있으니까」가 피구를 하자는 생각의 까닭이에요.","「하자」는 생각이지 까닭이 아니에요.","점심 메뉴는 까닭이 될 수 없어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#7','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',2,'match','auto','대화를 읽고 인물과 그 생각의 까닭을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u6-C7","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각의 까닭을 알맞게 이어 보세요.","pairs":[{"l":"도윤","r":"돌보기 쉬워서"},{"l":"하린","r":"자라는 모습을 볼 수 있어서"},{"l":"지후","r":"귀엽고 만져 볼 수 있어서"}],"mis":"K2-1-u6-X08","explanation":["도윤이는 돌보기 쉽다고 했어요.","하린이는 자라는 모습을 볼 수 있다고 했어요.","지후는 귀엽고 만져 볼 수 있다고 했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대화를 읽고 인물과 그 생각의 까닭을 알맞게 이어 보세요.","pairs":[{"l":"서아","r":"모두가 함께 뛸 수 있어서"},{"l":"민호","r":"실력을 키울 수 있어서"},{"l":"예린","r":"규칙이 쉬워서"}],"explanation":["서아는 모두가 함께 뛸 수 있다고 했어요.","민호는 실력을 키울 수 있다고 했어요.","예린이는 규칙이 쉽다고 했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#8','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C6',2,'sa','auto','대화를 읽고 답해 보세요. 지후가 기르자고 한 것은 무엇인가요? 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u6-C6","difficulty":2,"kind":"sa","stem":"대화를 읽고 답해 보세요. 지후가 기르자고 한 것은 무엇인가요? 세 글자로 써 보세요.","answer":["달팽이"],"explanation":["지후는 「달팽이를 기르자.」라고 했어요.","지후의 생각은 달팽이를 기르자는 것이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 지호가 가고 싶어 한 곳은 어디인가요? 세 글자로 써 보세요.","answer":["과학관"],"explanation":["지호는 과학관에 가고 싶다고 했어요.","실험을 해 볼 수 있다는 까닭을 들었어요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#9','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 소율이가 동물원에 가고 싶은 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],true,'{"seq":9,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 소율이가 동물원에 가고 싶은 까닭은 무엇인가요?","options":[{"t":"책에서만 본 동물을 직접 볼 수 있어서","correct":true},{"t":"모래 놀이를 할 수 있어서","mis":"K2-1-u6-X08"},{"t":"실험을 해 볼 수 있어서","mis":"K2-1-u6-X08"}],"explanation":["소율이는 책에서만 본 동물을 직접 보고 싶다고 했어요.","모래 놀이는 하늘이가 말한 까닭이에요.","실험은 지호가 말한 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 하늘이가 바닷가에 가고 싶은 까닭은 무엇인가요?","options":[{"t":"모래 놀이도 하고 조개도 주울 수 있어서","correct":true},{"t":"동물을 직접 볼 수 있어서","mis":"K2-1-u6-X08"},{"t":"여러 가지 실험을 할 수 있어서","mis":"K2-1-u6-X08"}],"explanation":["하늘이는 모래 놀이와 조개 줍기를 까닭으로 들었어요.","동물은 소율이가 말한 까닭이에요.","실험은 지호가 말한 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_basic#10','kor',2,1,'u6','L07','g2_1_kor_u6_L07_basic','lesson_basic','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「지후는 돌보기 쉬워서 달팽이를 기르자고 했어.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"채원 — 「하린이는 자라는 모습을 보려고 강낭콩을 기르자고 했어.」","mis":"K2-1-u6-X16"},{"t":"건우 — 「도윤이는 돌보기 쉬워서 물고기를 기르자고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「돌보기 쉬워서」는 도윤이가 말한 까닭이에요.","지후는 달팽이가 귀엽고 만져 볼 수 있다고 했어요.","채원이와 건우는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수빈 — 「서아는 규칙이 쉬워서 피구를 하자고 했어.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"시우 — 「민호는 실력을 키우려고 줄넘기를 하자고 했어.」","mis":"K2-1-u6-X16"},{"t":"다은 — 「예린이는 규칙이 쉬워서 숨바꼭질을 하자고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「규칙이 쉬워서」는 예린이가 말한 까닭이에요.","서아는 모두가 함께 뛸 수 있다고 했어요.","시우와 다은이는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#1','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 까닭이 드러나지 않은 말은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":1,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 까닭이 드러나지 않은 말은 어느 것인가요?","options":[{"t":"「과학관에 가고 싶어.」","correct":true},{"t":"「여러 가지 실험을 해 볼 수 있어서.」","mis":"K2-1-u6-X16"},{"t":"「모래 놀이도 하고 조개도 주울 수 있어서.」","mis":"K2-1-u6-X16"}],"explanation":["「과학관에 가고 싶어.」는 생각만 말했어요.","나머지 두 말은 생각의 까닭이에요.","물음의 「않은」에 동그라미를 쳐요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#2','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C6',2,'mc','auto','대화를 읽고 답해 보세요. 세 친구의 생각이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X07']::text[],false,'{"seq":2,"concept":"K2-1-u6-C6","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 세 친구의 생각이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"저마다 좋다고 여기는 점이 다르니까","correct":true},{"t":"셋 가운데 한 명만 맞으니까","mis":"K2-1-u6-X12"},{"t":"대화를 듣지 않았으니까","mis":"K2-1-u6-X07"}],"explanation":["사람마다 좋다고 여기는 점이 달라 생각이 달라요.","생각이 다르다고 한 명만 맞는 것은 아니에요.","세 친구는 대화를 나누며 생각을 말했어요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#3','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',3,'error','auto','까닭을 찾았어요. 까닭이 아닌 것을 까닭이라고 한 친구는 누구인가요?',ARRAY['K2-1-u6-X09','K2-1-u6-X16']::text[],false,'{"seq":3,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"까닭을 찾았어요. 까닭이 아닌 것을 까닭이라고 한 친구는 누구인가요?","options":[{"t":"도담 — 「서아가 피구를 하자고 한 까닭은 서아가 키가 커서야.」","correct":true,"mis_target":"K2-1-u6-X09"},{"t":"지안 — 「모두가 함께 뛸 수 있어서야.」","mis":"K2-1-u6-X16"},{"t":"하준 — 「서아는 우리 반 모두가 뛰는 게 좋다고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「키가 커서」는 대화에 없고 까닭도 아니에요.","서아는 모두가 함께 뛸 수 있다고 했어요.","지안이와 하준이는 바르게 찾았어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#4','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',3,'ox','auto','대화를 읽고 답해 보세요. 「달팽이를 기르자.」는 지후가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":4,"concept":"K2-1-u6-C7","difficulty":3,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「달팽이를 기르자.」는 지후가 말한 까닭이에요.","answer":"X","reason_options":[{"t":"「달팽이를 기르자.」는 생각이고, 까닭은 「귀엽고 만져 볼 수 있다」니까","correct":true},{"t":"「~하자」로 끝나는 말은 모두 까닭이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["「~하자」는 무엇을 하자는 생각이에요.","까닭은 「귀엽고 만져 볼 수 있거든」이에요.","생각과 까닭을 가려요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#5','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',3,'mc','auto','「나는 우산을 챙겨야 한다고 생각해. 왜냐하면 ( ).」 빈칸에 들어갈 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":5,"concept":"K2-1-u6-C7","difficulty":3,"kind":"mc","stem":"「나는 우산을 챙겨야 한다고 생각해. 왜냐하면 ( ).」 빈칸에 들어갈 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"오후에 비가 온다고 했거든","correct":true},{"t":"내 우산은 노란색이거든","mis":"K2-1-u6-X09"},{"t":"우산을 챙겨야 하거든","mis":"K2-1-u6-X09"}],"explanation":["비가 온다는 것이 우산을 챙길 까닭이에요.","우산 색깔은 까닭이 되지 않아요.","생각을 그대로 되풀이하는 것은 까닭이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#6','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C6',3,'mc','auto','「채원: 나는 급식에 나물이 자주 나왔으면 좋겠어. 몸에 좋으니까.」 채원이의 생각은 무엇인가요?',ARRAY['K2-1-u6-X09','K2-1-u6-X07']::text[],false,'{"seq":6,"concept":"K2-1-u6-C6","difficulty":3,"kind":"mc","stem":"「채원: 나는 급식에 나물이 자주 나왔으면 좋겠어. 몸에 좋으니까.」 채원이의 생각은 무엇인가요?","options":[{"t":"급식에 나물이 자주 나오면 좋겠다","correct":true},{"t":"나물은 몸에 좋다","mis":"K2-1-u6-X09"},{"t":"급식이 맛이 없다","mis":"K2-1-u6-X07"}],"explanation":["채원이의 생각은 나물이 자주 나오면 좋겠다는 거예요.","「몸에 좋으니까」는 그 생각의 까닭이에요.","맛이 없다는 말은 하지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#7','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',3,'mc','auto','대화를 읽고 답해 보세요. 교실에서 기르기에 가장 쉽다는 까닭을 든 친구는 누구인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":7,"concept":"K2-1-u6-C7","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 교실에서 기르기에 가장 쉽다는 까닭을 든 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"하린","mis":"K2-1-u6-X08"},{"t":"지후","mis":"K2-1-u6-X08"}],"explanation":["도윤이는 먹이만 주면 되어 돌보기 쉽다고 했어요.","하린이는 자라는 모습을 까닭으로 들었어요.","지후는 귀엽고 만질 수 있다는 까닭을 들었어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#8','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',4,'mc','auto','대화를 읽고 답해 보세요. 비가 오는 날 교실 안에서 놀아야 한다면, 세 친구의 까닭 가운데 그대로 쓸 수 있는 놀이는 어느 것인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X09']::text[],false,'{"seq":8,"concept":"K2-1-u6-C7","difficulty":4,"kind":"mc","stem":"대화를 읽고 답해 보세요. 비가 오는 날 교실 안에서 놀아야 한다면, 세 친구의 까닭 가운데 그대로 쓸 수 있는 놀이는 어느 것인가요?","options":[{"t":"숨바꼭질 — 규칙이 쉬워 누구나 할 수 있으니까","correct":true},{"t":"피구 — 모두가 함께 뛸 수 있으니까","mis":"K2-1-u6-X07"},{"t":"줄넘기 — 날마다 해야 하니까","mis":"K2-1-u6-X09"}],"explanation":["교실에서는 뛰거나 줄을 돌리기 어려워요.","숨바꼭질은 규칙이 쉬워 교실에서도 할 수 있어요.","「날마다 해야 하니까」는 대화에 없는 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#9','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C7',4,'essay','teacher','대화를 읽고 답해 보세요. 세 친구의 생각과 까닭을 「누가 — 생각 — 까닭」 차례로 정리해 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C7","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 세 친구의 생각과 까닭을 「누가 — 생각 — 까닭」 차례로 정리해 써 보세요.","answer_guide":{"answer":"예: 소율 — 동물원에 가고 싶다 — 책에서만 본 동물을 직접 볼 수 있어서. 지호 — 과학관에 가고 싶다 — 여러 가지 실험을 해 볼 수 있어서. 하늘 — 바닷가에 가고 싶다 — 모래 놀이와 조개 줍기를 할 수 있어서.","scoring_points":["세 인물을 모두 썼는가","인물마다 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가"]},"explanation":["세 인물.","인물마다 생각.","짝이 되는 까닭."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L07_challenge#10','kor',2,1,'u6','L07','g2_1_kor_u6_L07_challenge','lesson_challenge','K2-1-u6-C6',4,'essay','teacher','가족이나 친구가 무언가를 하자고 말한 일을 떠올려, 그 사람의 생각과 까닭을 찾아 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"가족이나 친구가 무언가를 하자고 말한 일을 떠올려, 그 사람의 생각과 까닭을 찾아 써 보세요.","answer_guide":{"answer":"예: 엄마는 주말에 공원에 가자고 하셨어요(생각). 왜냐하면 날씨가 좋아서 산책하기 좋기 때문이에요(까닭).","scoring_points":["누구의 말인지 썼는가","그 사람의 생각을 찾아 썼는가","생각과 짝이 되는 까닭을 썼는가"]},"explanation":["누구의 말.","생각.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#1','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C7',1,'mc','auto','글을 읽고 답해 보세요. 개구리가 반장이 되겠다고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X07']::text[],true,'{"seq":1,"concept":"K2-1-u6-C7","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 개구리가 반장이 되겠다고 한 까닭은 무엇인가요?","options":[{"t":"목소리가 커서 알릴 일을 잘 전할 수 있어서","correct":true},{"t":"차분해서 꼼꼼하게 살필 수 있어서","mis":"K2-1-u6-X08"},{"t":"연못에서 가장 오래 살아서","mis":"K2-1-u6-X07"}],"explanation":["개구리는 목소리가 크다는 까닭을 들었어요.","차분하다는 것은 거북이 든 까닭이에요.","오래 살았다는 말은 글에 없어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 오리가 반장이 되겠다고 한 까닭은 무엇인가요?","options":[{"t":"헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어서","correct":true},{"t":"목소리가 커서","mis":"K2-1-u6-X08"},{"t":"깃털 색이 예뻐서","mis":"K2-1-u6-X07"}],"explanation":["오리는 헤엄치고 날 수 있다는 까닭을 들었어요.","목소리가 크다는 것은 개구리가 든 까닭이에요.","깃털 색은 글에 없어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#2','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11']::text[],true,'{"seq":2,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각과 그렇게 생각한 까닭","correct":true},{"t":"큰 소리로 우기기","mis":"K2-1-u6-X11"},{"t":"친구 말 무시하기","mis":"K2-1-u6-X11"}],"explanation":["내 생각과 까닭을 함께 말해야 잘 전해져요.","우기면 친구가 듣기 싫어해요.","친구 말을 무시하면 서로 생각을 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"예의 바른 말","correct":true},{"t":"친구 말 끊기","mis":"K2-1-u6-X11"},{"t":"화난 목소리","mis":"K2-1-u6-X11"}],"explanation":["예의 바르게 말하면 친구도 잘 들어 줘요.","친구 말을 끊으면 예의에 어긋나요.","화난 목소리로 말하면 생각이 잘 전해지지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#3','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',1,'ox','auto','내 생각을 말할 때는 「나는 ~라고 생각해. 왜냐하면 ~거든.」처럼 말하면 좋아요.',ARRAY['K2-1-u6-X10']::text[],true,'{"seq":3,"concept":"K2-1-u6-C8","difficulty":1,"kind":"ox","stem":"내 생각을 말할 때는 「나는 ~라고 생각해. 왜냐하면 ~거든.」처럼 말하면 좋아요.","answer":"O","reason_options":[{"t":"생각과 까닭이 함께 또렷하게 드러나니까","correct":true},{"t":"까닭은 마지막까지 숨겨야 하니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["이렇게 말하면 생각과 까닭이 함께 드러나요.","듣는 사람이 내 생각을 잘 이해해요.","생각 뒤에 까닭을 붙여요."],"variant_rule":{"alt":[{"stem":"친구의 생각이 나와 다르면 친구의 생각은 틀린 거예요.","answer":"X","reason_options":[{"t":"사람마다 좋다고 여기는 점이 달라 생각이 다를 수 있으니까","correct":true},{"t":"나와 같은 생각만 맞는 생각이니까","mis":"K2-1-u6-X12"}],"explanation":["생각은 사람마다 다를 수 있어요.","다르다고 틀린 것은 아니에요.","친구의 까닭을 들어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#4','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C6',1,'mc','auto','글을 읽고 답해 보세요. 반장이 되겠다고 말한 동물이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],true,'{"seq":4,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 반장이 되겠다고 말한 동물이 아닌 것은 어느 것인가요?","options":[{"t":"다람쥐","correct":true},{"t":"거북","mis":"K2-1-u6-X16"},{"t":"개구리","mis":"K2-1-u6-X16"}],"explanation":["글에는 개구리·거북·오리가 나와요.","다람쥐는 글에 나오지 않아요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 반장을 뽑으려는 곳은 어디인가요?","options":[{"t":"연못","correct":true},{"t":"숲속","mis":"K2-1-u6-X07"},{"t":"바닷가","mis":"K2-1-u6-X07"}],"explanation":["연못 동물들이 반장을 뽑기로 했어요.","숲속이나 바닷가는 글에 나오지 않아요.","글의 첫 문장을 살펴봐요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#5','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C7',2,'match','auto','글을 읽고 동물과 반장이 되려는 까닭을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C7","difficulty":2,"kind":"match","stem":"글을 읽고 동물과 반장이 되려는 까닭을 알맞게 이어 보세요.","pairs":[{"l":"개구리","r":"목소리가 커서"},{"l":"거북","r":"차분하고 꼼꼼해서"},{"l":"오리","r":"헤엄치고 날 수 있어서"}],"mis":"K2-1-u6-X08","explanation":["개구리는 목소리가 크다고 했어요.","거북은 차분하고 꼼꼼하다고 했어요.","오리는 헤엄치고 날 수 있다고 했어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"생각을 말하는 표현과 그 쓰임을 알맞게 이어 보세요.","pairs":[{"l":"나는 ~라고 생각해","r":"내 생각 말하기"},{"l":"왜냐하면 ~거든","r":"까닭 말하기"},{"l":"너는 어떻게 생각해?","r":"친구 생각 묻기"}],"explanation":["「나는 ~라고 생각해」로 내 생각을 말해요.","「왜냐하면 ~거든」으로 까닭을 말해요.","「너는 어떻게 생각해?」로 친구의 생각을 물어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#6','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',2,'mc','auto','글을 읽고 답해 보세요. 내 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],true,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 내 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 거북이 반장이 되면 좋겠어. 왜냐하면 꼼꼼하게 살펴서 실수가 적을 것 같거든.」","correct":true},{"t":"「나는 거북이 좋아. 그냥.」","mis":"K2-1-u6-X10"},{"t":"「거북이 무조건 반장이야. 다른 말 하지 마!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 예의 바르게 말했어요.","「그냥」은 까닭이 드러나지 않아요.","「다른 말 하지 마!」는 우기는 말이에요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 내 생각을 까닭과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 개구리가 반장이 되면 좋겠어. 왜냐하면 알릴 일을 모두에게 잘 들리게 전할 수 있거든.」","correct":true},{"t":"「개구리! 개구리! 개구리가 최고야!」","mis":"K2-1-u6-X11"},{"t":"「나는 개구리가 좋아. 왜냐하면 오늘 비가 오거든.」","mis":"K2-1-u6-X09"}],"explanation":["생각과 그에 맞는 까닭을 예의 바르게 말했어요.","이름만 외치는 것은 우기는 말이에요.","비가 오는 것은 이 생각의 까닭이 되지 않아요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#7','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',2,'mc','auto','친구가 나와 다른 생각을 말할 때 알맞은 태도는 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X11']::text[],true,'{"seq":7,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"친구가 나와 다른 생각을 말할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"끝까지 듣고 「그렇게 생각한 까닭이 뭐야?」 하고 물어봐요","correct":true},{"t":"「그건 틀렸어!」 하고 말을 끊어요","mis":"K2-1-u6-X12"},{"t":"못 들은 척하고 내 말만 해요","mis":"K2-1-u6-X11"}],"explanation":["끝까지 듣고 까닭을 물으면 친구 생각을 이해할 수 있어요.","다르다고 틀린 것은 아니에요.","내 말만 하면 생각을 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"생각을 나누면 좋은 점은 무엇인가요?","options":[{"t":"서로 다른 생각을 이해하고 존중하게 돼요","correct":true},{"t":"내 생각만 맞다는 것을 알게 돼요","mis":"K2-1-u6-X12"},{"t":"말을 크게 하는 연습이 돼요","mis":"K2-1-u6-X11"}],"explanation":["생각을 나누면 서로를 더 잘 이해해요.","내 생각만 맞는 것은 아니에요.","크게 말하는 것이 목적이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#8','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',2,'blank','auto','「나는 학급 문고에 만화책을 더 두면 좋겠다고 생각해. (     ) 책을 싫어하는 친구도 즐겁게 읽을 수 있거든.」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u6-X10']::text[],true,'{"seq":8,"concept":"K2-1-u6-C8","difficulty":2,"kind":"blank","stem":"「나는 학급 문고에 만화책을 더 두면 좋겠다고 생각해. (     ) 책을 싫어하는 친구도 즐겁게 읽을 수 있거든.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그러니까 이제","mis":"K2-1-u6-X10"},{"t":"하지만","mis":"K2-1-u6-X10"}],"explanation":["까닭을 이끌 때는 「왜냐하면」을 써요.","「그러니까 이제」·「하지만」은 까닭을 이끄는 말이 아니에요.","생각 뒤에 까닭을 이어 말해요."],"variant_rule":{"alt":[{"stem":"「나는 쉬는 시간이 조금 더 길면 좋겠다고 생각해. (     ) 화장실도 다녀오고 다음 시간 준비도 할 수 있거든.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왜냐하면","correct":true},{"t":"그래도","mis":"K2-1-u6-X10"},{"t":"그런데","mis":"K2-1-u6-X10"}],"explanation":["까닭을 이끌 때는 「왜냐하면」을 써요.","「그래도」·「그런데」는 까닭을 이끄는 말이 아니에요.","생각 뒤에 까닭을 이어 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#9','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',2,'mc','auto','내 생각을 표현하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],true,'{"seq":9,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"내 생각을 표현하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인물의 생각과 까닭 알기 → 내 생각 정하기 → 까닭과 함께 말하기","correct":true},{"t":"까닭 없이 말하기 → 끝내기","mis":"K2-1-u6-X10"},{"t":"친구 생각 무시하기 → 내 생각 우기기","mis":"K2-1-u6-X11"}],"explanation":["먼저 인물의 생각을 알고, 내 생각을 정하고, 까닭과 함께 말해요.","까닭 없이 말하면 생각이 잘 전해지지 않아요.","우기거나 무시하면 생각을 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"생각을 글과 그림으로 나타낼 때 함께 쓰면 좋은 것은 어느 것인가요?","options":[{"t":"그렇게 생각한 까닭","correct":true},{"t":"친구의 비밀","mis":"K2-1-u6-X13"},{"t":"그림의 크기 숫자","mis":"K2-1-u6-X03"}],"explanation":["그림과 함께 까닭을 쓰면 생각이 잘 전해져요.","친구의 비밀은 쓰면 안 돼요.","그림 크기는 생각과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_basic#10','kor',2,1,'u6','L09','g2_1_kor_u6_L09_basic','lesson_basic','K2-1-u6-C8',3,'error','auto','반장 뽑기에 대해 생각을 말했어요. 예의 바르지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X11','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"반장 뽑기에 대해 생각을 말했어요. 예의 바르지 않게 말한 친구는 누구인가요?","options":[{"t":"건우 — 「오리 말고 딴 거 고른 애들은 다 바보야.」","correct":true,"mis_target":"K2-1-u6-X11"},{"t":"수빈 — 「나는 오리가 좋다고 생각해. 연못을 두루 살필 수 있거든.」","mis":"K2-1-u6-X16"},{"t":"윤호 — 「나는 거북이 좋아. 꼼꼼하니까. 너는 어떻게 생각해?」","mis":"K2-1-u6-X16"}],"explanation":["친구를 바보라고 하는 것은 예의 바르지 않아요.","생각이 달라도 친구를 존중해요.","수빈이와 윤호는 까닭을 들어 예의 바르게 말했어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 반장 뽑기에 대해 생각을 말했어요. 예의 바르지 않게 말한 친구는 누구인가요?","options":[{"t":"채원 — 「개구리는 시끄럽기만 해. 너희 생각은 다 틀렸어!」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"지호 — 「나는 개구리가 좋다고 생각해. 알릴 일을 잘 전하거든.」","mis":"K2-1-u6-X16"},{"t":"하윤 — 「나는 오리가 좋아. 그런데 거북의 까닭도 일리가 있어.」","mis":"K2-1-u6-X16"}],"explanation":["친구들의 생각이 다 틀렸다는 말은 다른 생각을 존중하지 않아요.","생각이 달라도 까닭을 들어 봐요.","지호와 하윤이는 예의 바르게 말했어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#1','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',2,'mc','auto','글을 읽고 답해 보세요. 「나는 오리가 반장이 되면 좋겠어.」 다음에 이어 말할 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X09','K2-1-u6-X08']::text[],false,'{"seq":1,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「나는 오리가 반장이 되면 좋겠어.」 다음에 이어 말할 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「연못 구석구석을 둘러보며 친구들을 살필 수 있거든.」","correct":true},{"t":"「오리는 꽥꽥 울거든.」","mis":"K2-1-u6-X09"},{"t":"「개구리 목소리가 크거든.」","mis":"K2-1-u6-X08"}],"explanation":["오리가 반장이면 좋은 점을 까닭으로 들었어요.","꽥꽥 우는 것은 반장이 되면 좋은 까닭이 아니에요.","목소리는 개구리에 대한 까닭이에요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#2','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',2,'mc','auto','친구가 「나는 거북이 좋다고 생각해.」라고만 말했어요. 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X11']::text[],false,'{"seq":2,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"친구가 「나는 거북이 좋다고 생각해.」라고만 말했어요. 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「왜 그렇게 생각했는지 까닭도 말해 줄래?」","correct":true},{"t":"「그건 틀렸어.」","mis":"K2-1-u6-X12"},{"t":"「됐어, 내 말이나 들어.」","mis":"K2-1-u6-X11"}],"explanation":["까닭을 물으면 친구의 생각을 더 잘 알 수 있어요.","다른 생각을 틀렸다고 하면 안 돼요.","친구 말을 무시하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#3','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'error','auto','「교실 생물로 무엇을 기를까?」에 대해 생각을 말했어요. 까닭이 생각과 어울리지 않는 친구는 누구인가요?',ARRAY['K2-1-u6-X09','K2-1-u6-X16']::text[],false,'{"seq":3,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「교실 생물로 무엇을 기를까?」에 대해 생각을 말했어요. 까닭이 생각과 어울리지 않는 친구는 누구인가요?","options":[{"t":"태민 — 「나는 물고기를 기르면 좋겠어. 왜냐하면 나는 물고기 그림을 그렸거든.」","correct":true,"mis_target":"K2-1-u6-X09"},{"t":"아린 — 「나는 강낭콩이 좋아. 날마다 키를 재어 볼 수 있거든.」","mis":"K2-1-u6-X16"},{"t":"서윤 — 「나는 달팽이가 좋아. 조용해서 공부에 방해가 안 되거든.」","mis":"K2-1-u6-X16"}],"explanation":["물고기 그림을 그린 것은 물고기를 기를 까닭이 되지 않아요.","까닭은 생각을 뒷받침하는 좋은 점이어야 해요.","아린이와 서윤이는 어울리는 까닭을 들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#4','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'ox','auto','친구와 생각이 다를 때에는 내 생각이 맞다고 끝까지 큰 소리로 말해야 해요.',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":4,"concept":"K2-1-u6-C8","difficulty":3,"kind":"ox","stem":"친구와 생각이 다를 때에는 내 생각이 맞다고 끝까지 큰 소리로 말해야 해요.","answer":"X","reason_options":[{"t":"까닭을 들어 차분히 말하고 친구의 생각도 들어야 하니까","correct":true},{"t":"큰 소리로 말하는 사람의 생각이 맞으니까","mis":"K2-1-u6-X11"}],"mis":"K2-1-u6-X11","explanation":["큰 소리로 우기면 생각이 잘 전해지지 않아요.","까닭을 들어 차분히 말해요.","친구의 생각도 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#5','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'mc','auto','글을 읽고 답해 보세요. 세 동물의 까닭을 모두 들은 뒤 내 생각을 정하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X09']::text[],false,'{"seq":5,"concept":"K2-1-u6-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 세 동물의 까닭을 모두 들은 뒤 내 생각을 정하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"반장에게 가장 필요한 일이 무엇인지 생각하고, 그 일을 잘할 동물을 고른다","correct":true},{"t":"가장 먼저 말한 동물을 고른다","mis":"K2-1-u6-X10"},{"t":"내가 키우고 싶은 동물을 고른다","mis":"K2-1-u6-X09"}],"explanation":["반장이 할 일을 생각하면 까닭을 견주어 고를 수 있어요.","먼저 말했다고 좋은 반장은 아니에요.","키우고 싶은 것은 반장을 고르는 까닭이 아니에요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#6','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'mc','auto','친구의 생각에 찬성하지 않을 때 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X11']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":3,"kind":"mc","stem":"친구의 생각에 찬성하지 않을 때 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「네 생각도 좋아. 그런데 나는 조금 다르게 생각해. 왜냐하면 ~」","correct":true},{"t":"「그런 생각을 하다니 이상해.」","mis":"K2-1-u6-X12"},{"t":"「말도 안 돼. 내 말이 맞아.」","mis":"K2-1-u6-X11"}],"explanation":["친구 생각을 인정하고 내 생각과 까닭을 말했어요.","「이상해」는 친구 생각을 무시하는 말이에요.","「말도 안 돼」는 우기는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#7','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',3,'mc','auto','「우리 반 이름을 무엇으로 할까?」에 대한 생각을 가장 잘 표현한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":7,"concept":"K2-1-u6-C8","difficulty":3,"kind":"mc","stem":"「우리 반 이름을 무엇으로 할까?」에 대한 생각을 가장 잘 표현한 것은 어느 것인가요?","options":[{"t":"「나는 「햇살반」이 좋다고 생각해. 왜냐하면 우리 반이 늘 밝고 따뜻했으면 좋겠거든.」","correct":true},{"t":"「햇살반. 끝.」","mis":"K2-1-u6-X10"},{"t":"「햇살반 안 하면 나 안 놀 거야.」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","「끝.」은 까닭이 없어요.","안 놀겠다는 말은 우기는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#8','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',4,'mc','auto','글을 읽고 답해 보세요. 「거북은 느려서 반장이 될 수 없어.」라는 친구의 말에 예의 바르게 다른 생각을 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X07']::text[],false,'{"seq":8,"concept":"K2-1-u6-C8","difficulty":4,"kind":"mc","stem":"글을 읽고 답해 보세요. 「거북은 느려서 반장이 될 수 없어.」라는 친구의 말에 예의 바르게 다른 생각을 말한 것은 어느 것인가요?","options":[{"t":"「느린 건 맞아. 하지만 차분해서 꼼꼼하게 살피는 것도 반장에게 필요하다고 생각해.」","correct":true},{"t":"「너는 거북을 싫어하는구나. 나쁘다.」","mis":"K2-1-u6-X12"},{"t":"「거북은 빠르거든!」","mis":"K2-1-u6-X07"}],"explanation":["친구 말을 인정하면서 까닭을 들어 내 생각을 말했어요.","친구를 나쁘다고 하면 안 돼요.","거북이 빠르다는 것은 글과 달라요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#9','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',4,'essay','teacher','글을 읽고 답해 보세요. 연못 반장으로 누가 되면 좋을지 내 생각을 정하고, 그렇게 생각한 까닭을 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 연못 반장으로 누가 되면 좋을지 내 생각을 정하고, 그렇게 생각한 까닭을 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 써 보세요.","answer_guide":{"answer":"예: 나는 오리가 반장이 되면 좋겠다고 생각해요. 왜냐하면 헤엄도 치고 날 수도 있어서 연못 구석구석의 친구들을 빠짐없이 살필 수 있기 때문이에요.","scoring_points":["누가 되면 좋을지 내 생각을 썼는가","글의 내용을 바탕으로 까닭을 썼는가","「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","글을 바탕으로 한 까닭.","알맞은 꼴."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L09_challenge#10','kor',2,1,'u6','L09','g2_1_kor_u6_L09_challenge','lesson_challenge','K2-1-u6-C8',4,'essay','teacher','짝과 생각이 달랐던 일을 떠올려, 짝의 생각과 까닭, 내 생각과 까닭을 쓰고, 짝의 생각을 존중하는 말을 한 문장 덧붙여 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"짝과 생각이 달랐던 일을 떠올려, 짝의 생각과 까닭, 내 생각과 까닭을 쓰고, 짝의 생각을 존중하는 말을 한 문장 덧붙여 보세요.","answer_guide":{"answer":"예: 짝은 피구를 하자고 했어요. 모두 뛸 수 있어서래요. 나는 줄넘기가 좋다고 생각했어요. 실력을 키울 수 있어서요. 「네 말처럼 다 같이 뛰는 것도 정말 좋겠다.」","scoring_points":["짝의 생각과 까닭을 썼는가","내 생각과 까닭을 썼는가","짝의 생각을 존중하는 말을 썼는가"]},"explanation":["짝의 생각과 까닭.","내 생각과 까닭.","존중하는 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#1','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',1,'mc','auto','책 소개 상자의 앞면에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],true,'{"seq":1,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자의 앞면에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"책 제목과 인상 깊은 장면","correct":true},{"t":"시험 점수","mis":"K2-1-u6-X13"},{"t":"내일 날씨","mis":"K2-1-u6-X13"}],"explanation":["앞면에는 한눈에 어떤 책인지 알 수 있게 제목과 장면을 담아요.","시험 점수는 책과 상관없어요.","날씨는 책 소개와 상관없어요."],"variant_rule":{"alt":[{"stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"기억에 남는 문장","correct":true},{"t":"우리 집 전화번호","mis":"K2-1-u6-X13"},{"t":"게임 비밀번호","mis":"K2-1-u6-X13"}],"explanation":["책에서 기억에 남는 문장은 책을 소개하는 데 좋아요.","전화번호는 책과 상관없고 남에게 알리면 안 돼요.","비밀번호도 책과 상관없고 알리면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#2','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',1,'mc','auto','상자를 읽고 답해 보세요. 수빈이가 소개한 책의 제목은 무엇인가요?',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":2,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이가 소개한 책의 제목은 무엇인가요?","options":[{"t":"달팽이 우체부","correct":true},{"t":"비 오는 날","mis":"K2-1-u6-X07"},{"t":"숲속 편지","mis":"K2-1-u6-X07"}],"explanation":["앞면에 「제목: 달팽이 우체부」라고 썼어요.","「비 오는 날」은 그림의 내용이에요.","「숲속 편지」라는 제목은 상자에 없어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"},"variant_rule":{"alt":[{"stem":"상자를 읽고 답해 보세요. 수빈이가 기억에 남는 문장을 쓴 곳은 어디인가요?","options":[{"t":"왼쪽 면","correct":true},{"t":"앞면","mis":"K2-1-u6-X14"},{"t":"오른쪽 면","mis":"K2-1-u6-X14"}],"explanation":["왼쪽 면에 기억에 남는 문장을 썼어요.","앞면에는 제목과 그림을 담았어요.","오른쪽 면에는 생각을 썼어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#3','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',1,'ox','auto','같은 책을 읽어도 친구마다 생각이나 느낌이 다를 수 있어요.',ARRAY['K2-1-u6-X12']::text[],true,'{"seq":3,"concept":"K2-1-u6-C9","difficulty":1,"kind":"ox","stem":"같은 책을 읽어도 친구마다 생각이나 느낌이 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 인상 깊은 부분과 느낌이 다르니까","correct":true},{"t":"같은 책을 읽으면 모두 같은 생각을 해야 하니까","mis":"K2-1-u6-X12"}],"mis":"K2-1-u6-X12","explanation":["같은 책도 사람마다 다르게 느낄 수 있어요.","친구의 소개를 들으면 새로운 생각을 알게 돼요.","다른 생각도 존중해요."],"variant_rule":{"alt":[{"stem":"책 소개 상자에는 책의 줄거리만 쓰고 내 생각이나 느낌은 쓰지 않아요.","answer":"X","reason_options":[{"t":"읽고 든 생각이나 느낌도 함께 담아야 하니까","correct":true},{"t":"책 소개에는 내 생각이 필요 없으니까","mis":"K2-1-u6-X14"}],"explanation":["책 소개 상자의 한 면에는 생각이나 느낌을 써요.","내 생각을 담으면 친구가 책에 더 관심을 가져요.","줄거리와 생각을 함께 담아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#4','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',1,'mc','auto','책 소개 상자를 만든 뒤에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X14']::text[],true,'{"seq":4,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자를 만든 뒤에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"친구들에게 발표하고 교실에 전시해요","correct":true},{"t":"아무에게도 보여 주지 않아요","mis":"K2-1-u6-X14"},{"t":"상자를 바로 버려요","mis":"K2-1-u6-X14"}],"explanation":["완성한 상자를 발표하고 전시하면 서로의 책을 알 수 있어요.","혼자만 가지고 있으면 소개가 되지 않아요.","버리면 친구들이 볼 수 없어요."],"variant_rule":{"alt":[{"stem":"친구의 책 소개를 들을 때 알맞은 태도는 어느 것인가요?","options":[{"t":"끝까지 귀 기울여 듣고 궁금한 것을 물어봐요","correct":true},{"t":"다른 친구와 떠들어요","mis":"K2-1-u6-X11"},{"t":"「그 책 재미없어.」라고 끊어요","mis":"K2-1-u6-X12"}],"explanation":["끝까지 들으면 친구의 생각을 알 수 있어요.","떠들면 친구의 소개를 듣지 못해요.","친구의 생각을 무시하는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#5','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'match','auto','책 소개 상자의 면과 담을 내용을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u6-C9","difficulty":2,"kind":"match","stem":"책 소개 상자의 면과 담을 내용을 알맞게 이어 보세요.","pairs":[{"l":"앞면","r":"제목과 인상 깊은 장면"},{"l":"왼쪽 면","r":"기억에 남는 문장"},{"l":"오른쪽 면","r":"생각이나 느낌"}],"mis":"K2-1-u6-X14","explanation":["앞면에는 제목과 장면을 담아요.","왼쪽 면에는 기억에 남는 문장을 써요.","오른쪽 면에는 생각이나 느낌을 써요."],"variant_rule":{"alt":[{"stem":"책 소개에 담을 내용과 그 까닭을 알맞게 이어 보세요.","pairs":[{"l":"제목","r":"어떤 책인지 알려 주려고"},{"l":"기억에 남는 문장","r":"책의 말맛을 느끼게 하려고"},{"l":"생각이나 느낌","r":"내가 왜 좋았는지 전하려고"}],"explanation":["제목은 어떤 책인지 알려 줘요.","기억에 남는 문장은 책의 말맛을 느끼게 해요.","생각이나 느낌은 왜 좋았는지 전해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#6','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'mc','auto','상자를 읽고 답해 보세요. 수빈이가 이 책을 읽고 든 생각은 무엇인가요?',ARRAY['K2-1-u6-X07']::text[],true,'{"seq":6,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이가 이 책을 읽고 든 생각은 무엇인가요?","options":[{"t":"느려도 끝까지 해내는 달팽이가 멋지다","correct":true},{"t":"달팽이는 너무 느려서 답답하다","mis":"K2-1-u6-X07"},{"t":"편지는 빨리 보내야 한다","mis":"K2-1-u6-X07"}],"explanation":["오른쪽 면에 달팽이가 멋지다는 생각을 썼어요.","답답하다는 말은 상자에 없어요.","빨리 보내야 한다는 말도 상자에 없어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"},"variant_rule":{"alt":[{"stem":"상자를 읽고 답해 보세요. 수빈이가 달팽이를 멋지다고 생각한 까닭은 무엇인가요?","options":[{"t":"비가 와도 포기하지 않았기 때문에","correct":true},{"t":"달팽이 껍데기가 예뻐서","mis":"K2-1-u6-X09"},{"t":"편지를 쓸 줄 알아서","mis":"K2-1-u6-X09"}],"explanation":["「포기하지 않았기 때문」이 까닭이에요.","껍데기가 예쁘다는 말은 상자에 없어요.","편지를 쓴다는 것은 까닭으로 들지 않았어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#7','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'mc','auto','책 소개 상자에 담기에 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],true,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"책 소개 상자에 담기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 집 주소","correct":true},{"t":"인상 깊은 장면 그림","mis":"K2-1-u6-X16"},{"t":"책을 읽고 든 느낌","mis":"K2-1-u6-X16"}],"explanation":["친구의 집 주소는 책과 상관없고 알리면 안 돼요.","장면 그림과 느낌은 책 소개에 알맞아요.","물음의 「않은」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책 소개 상자에 담기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"받아쓰기 점수","correct":true},{"t":"책의 제목","mis":"K2-1-u6-X16"},{"t":"기억에 남는 문장","mis":"K2-1-u6-X16"}],"explanation":["받아쓰기 점수는 책과 상관없어요.","제목과 기억에 남는 문장은 책 소개에 알맞아요.","물음의 「않은」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#8','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'sa','auto','책을 소개하는 말이에요. 「제가 소개할 책은 「달팽이 우체부」이고, 달팽이가 포기하지 않는 점이 (     ).」 빈칸에 어울리는 말을 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u6-C9","difficulty":2,"kind":"sa","stem":"책을 소개하는 말이에요. 「제가 소개할 책은 「달팽이 우체부」이고, 달팽이가 포기하지 않는 점이 (     ).」 빈칸에 어울리는 말을 써 보세요.","answer":["좋았어요","좋았습니다","멋졌어요","인상 깊었어요","감동적이었어요","좋았다","멋졌다"],"explanation":["책의 좋은 점을 소개할 때 「좋았어요」처럼 말해요.","「멋졌어요」·「인상 깊었어요」도 좋아요.","책의 어떤 점이 좋았는지 함께 말해요."],"variant_rule":{"alt":[{"stem":"책을 소개하는 말이에요. 「이 책에서 가장 기억에 남는 (     )은 「늦어도 괜찮아.」예요.」 빈칸에 알맞은 낱말을 두 글자로 써 보세요.","answer":["문장"],"explanation":["「늦어도 괜찮아.」는 책 속의 문장이에요.","기억에 남는 문장을 소개하면 책의 말맛이 전해져요.","책 소개 상자의 한 면에 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#9','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',2,'mc','auto','책을 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X14','K2-1-u6-X11']::text[],true,'{"seq":9,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"책을 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「제가 소개할 책은 「달팽이 우체부」예요. 끝까지 해내는 달팽이가 멋져서 꼭 읽어 보면 좋겠어요.」","correct":true},{"t":"「책이 있어요. 끝.」","mis":"K2-1-u6-X14"},{"t":"「이 책 안 읽으면 바보야.」","mis":"K2-1-u6-X11"}],"explanation":["제목과 좋았던 점, 권하는 말을 함께 말했어요.","「끝.」만으로는 어떤 책인지 알 수 없어요.","바보라는 말은 예의 바르지 않아요."],"variant_rule":{"alt":[{"stem":"책을 소개할 때 함께 말하면 좋은 것은 어느 것인가요?","options":[{"t":"그 책이 좋았던 까닭","correct":true},{"t":"책을 산 가게 이름","mis":"K2-1-u6-X13"},{"t":"책의 무게","mis":"K2-1-u6-X13"}],"explanation":["좋았던 까닭을 말하면 친구가 책에 관심을 가져요.","가게 이름은 책 소개와 상관없어요.","책의 무게도 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_basic#10','kor',2,1,'u6','L12','g2_1_kor_u6_L12_basic','lesson_basic','K2-1-u6-C9',3,'error','auto','책 소개 상자를 만들었어요. 알맞지 않게 만든 친구는 누구인가요?',ARRAY['K2-1-u6-X13','K2-1-u6-X16']::text[],true,'{"seq":10,"concept":"K2-1-u6-C9","difficulty":3,"kind":"error","stem":"책 소개 상자를 만들었어요. 알맞지 않게 만든 친구는 누구인가요?","options":[{"t":"하준 — 「앞면에 제목 대신 내 비밀번호를 크게 썼어.」","correct":true,"mis_target":"K2-1-u6-X13"},{"t":"예린 — 「왼쪽 면에 기억에 남는 문장을 썼어.」","mis":"K2-1-u6-X16"},{"t":"소율 — 「오른쪽 면에 읽고 든 느낌을 썼어.」","mis":"K2-1-u6-X16"}],"explanation":["비밀번호는 책과 상관없고 남에게 알리면 안 돼요.","앞면에는 제목과 인상 깊은 장면을 담아요.","예린이와 소율이는 알맞게 만들었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책 소개 상자를 만들었어요. 알맞지 않게 만든 친구는 누구인가요?","options":[{"t":"지안 — 「세 면에 모두 줄거리만 썼어. 내 느낌은 안 썼어.」","correct":true,"mis_target":"K2-1-u6-X14"},{"t":"도윤 — 「앞면에 제목과 장면을 그렸어.」","mis":"K2-1-u6-X16"},{"t":"민지 — 「한 면에 「나는 이 책이 따뜻했다」라고 썼어.」","mis":"K2-1-u6-X16"}],"explanation":["줄거리만 쓰고 느낌을 빠뜨리면 내 생각이 전해지지 않아요.","한 면에는 생각이나 느낌을 써요.","도윤이와 민지는 알맞게 만들었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#1','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',2,'mc','auto','상자를 읽고 답해 보세요. 앞면 그림으로 「비 오는 날 달팽이가 편지를 들고 기어가는 그림」을 고른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":1,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"상자를 읽고 답해 보세요. 앞면 그림으로 「비 오는 날 달팽이가 편지를 들고 기어가는 그림」을 고른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"책의 인상 깊은 장면이라서","correct":true},{"t":"그리기 가장 쉬워서","mis":"K2-1-u6-X09"},{"t":"달팽이가 싫어서","mis":"K2-1-u6-X09"}],"explanation":["앞면에는 가장 인상 깊은 장면을 그려요.","그리기 쉬워서 고르는 것은 알맞은 까닭이 아니에요.","싫어서라는 말은 상자의 생각과 맞지 않아요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#2','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',2,'mc','auto','친구의 책 소개를 듣고 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X11']::text[],false,'{"seq":2,"concept":"K2-1-u6-C9","difficulty":2,"kind":"mc","stem":"친구의 책 소개를 듣고 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「달팽이가 어떻게 끝까지 해냈는지 궁금해. 나도 읽어 볼래.」","correct":true},{"t":"「달팽이 이야기는 다 똑같아.」","mis":"K2-1-u6-X12"},{"t":"「내 책이 더 재미있어.」","mis":"K2-1-u6-X11"}],"explanation":["궁금한 점을 말하고 관심을 보였어요.","다 똑같다는 말은 친구 소개를 무시해요.","내 책 자랑만 하면 친구가 서운해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#3','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'error','auto','같은 책을 읽고 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":3,"concept":"K2-1-u6-C9","difficulty":3,"kind":"error","stem":"같은 책을 읽고 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"시우 — 「달팽이가 답답하다고? 네 생각은 틀렸어.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"하늘 — 「나는 달팽이가 멋졌어. 너는 답답했구나. 왜 그랬어?」","mis":"K2-1-u6-X16"},{"t":"로아 — 「나도 처음엔 답답했는데 끝에는 멋졌어.」","mis":"K2-1-u6-X16"}],"explanation":["같은 책도 생각이 다를 수 있어요.","다른 생각을 틀렸다고 하면 안 돼요.","하늘이와 로아는 생각을 존중하며 나눴어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#4','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'ox','auto','상자를 읽고 답해 보세요. 수빈이는 오른쪽 면에 생각과 함께 그렇게 생각한 까닭도 썼어요.',ARRAY['K2-1-u6-X14']::text[],false,'{"seq":4,"concept":"K2-1-u6-C9","difficulty":3,"kind":"ox","stem":"상자를 읽고 답해 보세요. 수빈이는 오른쪽 면에 생각과 함께 그렇게 생각한 까닭도 썼어요.","answer":"O","reason_options":[{"t":"「왜냐하면 비가 와도 포기하지 않았기 때문」이라고 썼으니까","correct":true},{"t":"오른쪽 면에는 제목만 썼으니까","mis":"K2-1-u6-X14"}],"mis":"K2-1-u6-X14","explanation":["오른쪽 면에 생각과 까닭을 함께 썼어요.","까닭을 쓰면 생각이 더 잘 전해져요.","제목은 앞면에 있어요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#5','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'mc','auto','책 소개 상자의 왼쪽 면에 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」를 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X14']::text[],false,'{"seq":5,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"책 소개 상자의 왼쪽 면에 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」를 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"책의 주제가 잘 드러나 기억에 남는 문장이라서","correct":true},{"t":"가장 짧은 문장이라서","mis":"K2-1-u6-X14"},{"t":"책의 맨 처음 문장이라서","mis":"K2-1-u6-X14"}],"explanation":["이 문장은 달팽이의 마음이 잘 드러나 기억에 남아요.","짧다고 기억에 남는 문장은 아니에요.","맨 처음 문장이라고 고르는 것은 아니에요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#6','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'mc','auto','책 소개 상자의 뒷면을 더 채운다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":6,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"책 소개 상자의 뒷면을 더 채운다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이 책을 권하고 싶은 친구와 그 까닭","correct":true},{"t":"내가 좋아하는 게임 이름","mis":"K2-1-u6-X13"},{"t":"우리 집 강아지 사진","mis":"K2-1-u6-X13"}],"explanation":["책을 권하고 싶은 친구와 까닭은 책 소개에 어울려요.","게임 이름은 책과 상관없어요.","강아지 사진도 책 소개와 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#7','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',3,'mc','auto','「같은 책 다른 생각」 시간에 알게 될 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X14']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"「같은 책 다른 생각」 시간에 알게 될 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 책도 친구마다 인상 깊은 부분이 다르다는 것","correct":true},{"t":"모두가 같은 장면을 좋아해야 한다는 것","mis":"K2-1-u6-X12"},{"t":"책은 혼자 읽고 말하지 않는다는 것","mis":"K2-1-u6-X14"}],"explanation":["같은 책을 읽어도 인상 깊은 부분이 다를 수 있어요.","모두 같아야 하는 것은 아니에요.","생각을 나누면 책 읽는 즐거움이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#8','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',4,'mc','auto','상자를 읽고 답해 보세요. 수빈이의 상자를 보고 친구에게 더 잘 소개하려면 무엇을 더하면 가장 좋을까요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":8,"concept":"K2-1-u6-C9","difficulty":4,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이의 상자를 보고 친구에게 더 잘 소개하려면 무엇을 더하면 가장 좋을까요?","options":[{"t":"이 책을 누구에게 권하고 싶은지와 그 까닭","correct":true},{"t":"수빈이의 받아쓰기 점수","mis":"K2-1-u6-X13"},{"t":"달팽이 우체부의 가격","mis":"K2-1-u6-X13"}],"explanation":["권하고 싶은 사람과 까닭을 더하면 소개가 풍성해져요.","받아쓰기 점수는 책과 상관없어요.","가격은 책의 내용을 알려 주지 않아요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#9','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',4,'essay','teacher','최근에 읽은 책 한 권으로 책 소개 상자를 만든다고 생각하고, 앞면·왼쪽 면·오른쪽 면에 담을 내용을 각각 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C9","difficulty":4,"kind":"essay","stem":"최근에 읽은 책 한 권으로 책 소개 상자를 만든다고 생각하고, 앞면·왼쪽 면·오른쪽 면에 담을 내용을 각각 써 보세요.","answer_guide":{"answer":"예: 앞면 — 제목 「심심한 고양이」, 고양이가 창밖을 보는 장면. 왼쪽 면 — 「심심할 땐 친구를 찾아가 봐.」 오른쪽 면 — 친구를 찾아 나서는 고양이가 용감하다고 생각해요. 왜냐하면 처음 가는 길이 무서웠을 텐데 끝까지 갔기 때문이에요.","scoring_points":["앞면에 제목과 인상 깊은 장면을 썼는가","왼쪽 면에 기억에 남는 문장을 썼는가","오른쪽 면에 생각이나 느낌을 까닭과 함께 썼는가"]},"explanation":["앞면.","왼쪽 면.","오른쪽 면."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_L12_challenge#10','kor',2,1,'u6','L12','g2_1_kor_u6_L12_challenge','lesson_challenge','K2-1-u6-C9',4,'essay','teacher','친구가 같은 책을 읽고 나와 다른 느낌을 말했어요. 친구의 생각을 존중하면서 내 생각을 까닭과 함께 전하는 말을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u6-C9","difficulty":4,"kind":"essay","stem":"친구가 같은 책을 읽고 나와 다른 느낌을 말했어요. 친구의 생각을 존중하면서 내 생각을 까닭과 함께 전하는 말을 써 보세요.","answer_guide":{"answer":"예: 「너는 달팽이가 답답했구나. 그럴 수 있겠다. 나는 달팽이가 멋졌어. 왜냐하면 비가 와도 편지를 끝까지 전했기 때문이야.」","scoring_points":["친구의 생각을 인정하는 말을 썼는가","내 생각을 분명히 썼는가","내 생각의 까닭을 썼는가"]},"explanation":["친구 생각 인정.","내 생각.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#1','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"안내판","correct":true},{"t":"지우개","mis":"K2-1-u6-X01"},{"t":"우산","mis":"K2-1-u6-X01"}],"explanation":["「안내판」은 무언가를 알려 주는 매체예요.","다른 두 가지는 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#2','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"줄넘기를 하면 좋은 점","correct":true},{"t":"줄넘기 줄의 색깔","mis":"K2-1-u6-X03"},{"t":"수영하는 방법","mis":"K2-1-u6-X04"}],"explanation":["제목에 글의 가장 중요한 내용이 담겨 있어요.","다른 보기는 글에 없거나 제목과 맞지 않아요.","제목을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#3','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 도윤이가 기르자고 한 것은 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이가 기르자고 한 것은 무엇인가요?","options":[{"t":"물고기","correct":true},{"t":"강낭콩","mis":"K2-1-u6-X08"},{"t":"달팽이","mis":"K2-1-u6-X08"}],"explanation":["도윤이는 「물고기를 기르자.」라고 했어요.","다른 보기는 다른 친구의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#4','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C10',1,'mc','auto','토박이말 「까치밥」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":4,"concept":"K2-1-u6-C10","difficulty":1,"kind":"mc","stem":"토박이말 「까치밥」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"새가 먹으라고 나무에 남겨 둔 감","correct":true},{"t":"까치가 지은 밥","mis":"K2-1-u6-X15"},{"t":"까치집 모양의 떡","mis":"K2-1-u6-X15"}],"explanation":["「까치밥」은 「새가 먹으라고 나무에 남겨 둔 감」을 뜻해요.","다른 보기는 뜻이 다르거나 글자 모양만 보고 짐작한 것이에요.","토박이말이 쓰이는 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#5','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":5,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"줄넘기","correct":true},{"t":"마당","mis":"K2-1-u6-X05"},{"t":"다리","mis":"K2-1-u6-X05"}],"explanation":["「줄넘기」가 글에 여러 번 나와요.","다른 두 낱말은 한 번씩만 나와요.","나올 때마다 세어 봐요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#6','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"그렇게 생각한 까닭","correct":true},{"t":"큰 소리로 우기기","mis":"K2-1-u6-X11"},{"t":"친구 말 무시하기","mis":"K2-1-u6-X11"}],"explanation":["까닭을 함께 말하면 생각이 잘 전해져요.","다른 보기는 생각을 나누는 데 방해가 돼요.","생각과 까닭을 예의 바르게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#7','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C9',1,'mc','auto','책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"책 제목","correct":true},{"t":"전화번호","mis":"K2-1-u6-X13"},{"t":"비밀번호","mis":"K2-1-u6-X13"}],"explanation":["「책 제목」은 책을 소개하는 데 도움이 돼요.","다른 보기는 책과 상관없어요.","「이 내용이 책을 알려 주나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#8','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C2',1,'ox','auto','매체를 보고 든 생각을 말할 때 까닭을 함께 말하면 더 잘 전해져요.',ARRAY['K2-1-u6-X10']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"매체를 보고 든 생각을 말할 때 까닭을 함께 말하면 더 잘 전해져요.","answer":"O","reason_options":[{"t":"듣는 사람이 왜 그렇게 생각했는지 알 수 있으니까","correct":true},{"t":"까닭은 말하지 않아야 더 멋지니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["까닭을 들으면 생각을 더 잘 이해해요.","생각과 까닭을 함께 말해요.","「왜냐하면 ~거든」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#9','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"안내판","r":"이용 방법과 주의할 점"},{"l":"광고","r":"전하고 싶은 말"},{"l":"이야기책","r":"인물의 이야기"}],"mis":"K2-1-u6-X02","explanation":["「안내판」 — 이용 방법과 주의할 점","「광고」 — 전하고 싶은 말","「이야기책」 — 인물의 이야기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#10','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기를 하면 몸이 튼튼해집니다.","correct":true},{"t":"팔과 다리를 함께 움직이기 때문입니다.","mis":"K2-1-u6-X06"},{"t":"긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","mis":"K2-1-u6-X07"}],"explanation":["첫째 부분은 몸이 튼튼해진다는 것이 가장 하고 싶은 말이에요.","예를 들거나 까닭을 덧붙인 문장은 중심 문장이 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#11','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 하린이가 강낭콩을 기르자고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],false,'{"seq":11,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하린이가 강낭콩을 기르자고 한 까닭은 무엇인가요?","options":[{"t":"싹이 트고 자라는 모습을 날마다 볼 수 있어서","correct":true},{"t":"먹이만 주면 되어 돌보기 쉬워서","mis":"K2-1-u6-X08"},{"t":"강낭콩이 초록색이어서","mis":"K2-1-u6-X09"}],"explanation":["하린이는 자라는 모습을 볼 수 있다고 했어요.","다른 친구의 까닭이나 까닭이 아닌 말과 헷갈리지 않아요.","생각 뒤의 좋은 점을 찾아요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#12','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.","pairs":[{"l":"도윤","r":"물고기를 기르자"},{"l":"하린","r":"강낭콩을 기르자"},{"l":"지후","r":"달팽이를 기르자"}],"mis":"K2-1-u6-X08","explanation":["도윤 — 물고기를 기르자","하린 — 강낭콩을 기르자","지후 — 달팽이를 기르자"],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#13','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C10',2,'match','auto','토박이말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u6-C10","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"까치밥","r":"새가 먹으라고 남긴 감"},{"l":"벗","r":"친하게 사귀는 사람"},{"l":"여우비","r":"해 난 날 잠깐 오는 비"}],"mis":"K2-1-u6-X15","explanation":["「까치밥」 — 새가 먹으라고 남긴 감","「벗」 — 친하게 사귀는 사람","「여우비」 — 해 난 날 잠깐 오는 비"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#14','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',2,'mc','auto','「교실 생물로 무엇을 기를까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":14,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"「교실 생물로 무엇을 기를까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 강낭콩이 좋다고 생각해. 왜냐하면 날마다 자라는 걸 볼 수 있거든.」","correct":true},{"t":"「강낭콩. 그냥.」","mis":"K2-1-u6-X10"},{"t":"「강낭콩 아니면 안 기를 거야!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","까닭 없이 말하거나 우기는 말은 생각을 잘 전하지 못해요.","「나는 ~라고 생각해. 왜냐하면 ~거든.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#15','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C7',2,'ox','auto','대화를 읽고 답해 보세요. 「강낭콩을 기르자.」는 하린이가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C7","difficulty":2,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「강낭콩을 기르자.」는 하린이가 말한 까닭이에요.","answer":"X","reason_options":[{"t":"「기르자」는 생각이고, 까닭은 「자라는 모습을 볼 수 있다」니까","correct":true},{"t":"「~하자」로 끝나는 말은 모두 까닭이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["「강낭콩을 기르자.」는 하린이의 생각이에요.","까닭은 생각을 뒷받침하는 좋은 점이나 옳은 점이에요.","「왜?」에 대답이 되는지 넣어 봐요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#16','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C2',2,'sa','auto','「나는 이 안내판이 꼭 필요하다고 생각해. (     ) 놀이터에서 다치지 않게 도와주거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C2","difficulty":2,"kind":"sa","stem":"「나는 이 안내판이 꼭 필요하다고 생각해. (     ) 놀이터에서 다치지 않게 도와주거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.","answer":["왜냐하면"],"explanation":["까닭을 말할 때는 「왜냐하면」으로 시작해요.","「왜냐하면」 뒤에 그렇게 생각한 까닭을 말해요.","생각 → 왜냐하면 → 까닭 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#17','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X16']::text[],false,'{"seq":17,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"도윤 — 「줄넘기는 마당에서만 할 수 있다.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"하린 — 「줄넘기를 하면 몸이 튼튼해진다.」","mis":"K2-1-u6-X16"},{"t":"지후 — 「줄넘기는 친구와 즐겁게 할 수 있다.」","mis":"K2-1-u6-X16"}],"explanation":["글에는 줄넘기를 어디서나 할 수 있다고 했어요.","중요한 내용은 글 전체를 보고 정리해요.","다른 두 친구는 바르게 정리했어요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#18','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C3',3,'mc','auto','「꿀벌은 꽃에서 꿀을 모읍니다. 꽃가루를 옮겨 열매가 열리도록 돕습니다. 힘을 모아 벌집을 짓습니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":18,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「꿀벌은 꽃에서 꿀을 모읍니다. 꽃가루를 옮겨 열매가 열리도록 돕습니다. 힘을 모아 벌집을 짓습니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"꿀벌이 하는 일","correct":true},{"t":"꽃의 색깔","mis":"K2-1-u6-X04"},{"t":"맛있는 꿀 요리","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 꿀벌이 하는 일을 알려 줘요.","다른 보기는 글의 내용과 어울리지 않아요.","글 전체가 무엇을 알려 주는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#19','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],false,'{"seq":19,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「지후는 돌보기 쉬워서 달팽이를 기르자고 했어.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"채원 — 「하린이는 자라는 모습을 보려고 강낭콩을 기르자고 했어.」","mis":"K2-1-u6-X16"},{"t":"건우 — 「도윤이는 돌보기 쉬워서 물고기를 기르자고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「돌보기 쉬워서」는 도윤이가 말한 까닭이에요.","인물을 뒤바꾸지 않도록 말한 사람을 확인해요.","다른 두 친구는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#20','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',3,'error','auto','「교실 생물로 무엇을 기를까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":20,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「교실 생물로 무엇을 기를까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"민지 — 「물고기라니, 네 생각은 틀렸어.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"지후 — 「나는 달팽이가 좋아. 너는 왜 물고기가 좋아?」","mis":"K2-1-u6-X16"},{"t":"윤서 — 「물고기도 좋겠다. 나는 강낭콩이 더 좋지만.」","mis":"K2-1-u6-X16"}],"explanation":["다른 생각을 틀렸다고 하면 안 돼요.","생각이 달라도 친구의 까닭을 들어 봐요.","다른 두 친구는 예의 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#21','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C9',3,'mc','auto','상자를 읽고 답해 보세요. 수빈이가 이 책을 읽고 든 생각과 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X13']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이가 이 책을 읽고 든 생각과 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"달팽이가 멋지다 — 비가 와도 포기하지 않아서","correct":true},{"t":"달팽이가 답답하다 — 너무 느려서","mis":"K2-1-u6-X07"},{"t":"달팽이가 멋지다 — 수빈이 집에 달팽이가 있어서","mis":"K2-1-u6-X13"}],"explanation":["오른쪽 면에 생각과 까닭이 함께 쓰여 있어요.","다른 보기는 상자의 내용과 맞지 않거나 책과 상관없어요.","상자의 면을 돌려 가며 살펴요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#22','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":22,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"마당","correct":true},{"t":"줄넘기","mis":"K2-1-u6-X16"},{"t":"좋은 점","mis":"K2-1-u6-X16"}],"explanation":["「마당」은 한 번만 나와요.","다른 두 낱말은 제목에 있거나 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#23','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 몸이 튼튼해진다 · 친구와 즐겁게 할 수 있다 · 어디서나 할 수 있다 → 줄넘기는 몸을 튼튼하게 하고, 친구와 즐겁게, 어디서나 할 수 있는 좋은 운동이다.","scoring_points":["중심 문장을 빠짐없이 찾았는가","예나 까닭을 덧붙인 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["중심 문장 찾기.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#24','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C6',4,'essay','teacher','대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 도윤 — 물고기, 돌보기 쉬워서. 하린 — 강낭콩, 자라는 모습을 볼 수 있어서. 나는 하린이 생각에 찬성해요. 왜냐하면 날마다 키를 재며 관찰할 수 있기 때문이에요.","scoring_points":["두 인물의 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가","찬성하는 생각과 내 까닭을 썼는가"]},"explanation":["인물의 생각.","짝이 되는 까닭.","내 생각과 까닭."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_a#25','kor',2,1,'u6','','g2_1_kor_u6_review_a','unit_review','K2-1-u6-C8',4,'essay','teacher','「쉬는 시간을 조금 더 늘리면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"「쉬는 시간을 조금 더 늘리면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.","answer_guide":{"answer":"예: 나는 쉬는 시간을 조금 늘리면 좋겠다고 생각해. 왜냐하면 화장실도 여유 있게 다녀올 수 있고, 다음 시간 준비도 할 수 있기 때문이야.","scoring_points":["내 생각을 분명히 썼는가","생각을 뒷받침하는 까닭을 두 가지 썼는가","알맞은 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","까닭 두 가지.","예의 바른 꼴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#1','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"광고","correct":true},{"t":"의자","mis":"K2-1-u6-X01"},{"t":"신발","mis":"K2-1-u6-X01"}],"explanation":["「광고」는 무언가를 알려 주는 매체예요.","다른 두 가지는 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#2','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"꿀벌이 하는 일","correct":true},{"t":"꿀벌의 색깔","mis":"K2-1-u6-X03"},{"t":"꽃 파는 가게","mis":"K2-1-u6-X04"}],"explanation":["제목에 글의 가장 중요한 내용이 담겨 있어요.","다른 보기는 글에 없거나 제목과 맞지 않아요.","제목을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#3','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 서아가 하자고 한 놀이는 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 서아가 하자고 한 놀이는 무엇인가요?","options":[{"t":"피구","correct":true},{"t":"줄넘기","mis":"K2-1-u6-X08"},{"t":"숨바꼭질","mis":"K2-1-u6-X08"}],"explanation":["서아는 「피구를 하자.」라고 했어요.","다른 보기는 다른 친구의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#4','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C10',1,'mc','auto','토박이말 「벗」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":4,"concept":"K2-1-u6-C10","difficulty":1,"kind":"mc","stem":"토박이말 「벗」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"친하게 사귀는 사람","correct":true},{"t":"신발을 벗는 일","mis":"K2-1-u6-X15"},{"t":"처음 만난 사람","mis":"K2-1-u6-X15"}],"explanation":["「벗」은 「친하게 사귀는 사람」을 뜻해요.","다른 보기는 뜻이 다르거나 글자 모양만 보고 짐작한 것이에요.","토박이말이 쓰이는 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#5','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":5,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"꿀벌","correct":true},{"t":"열매","mis":"K2-1-u6-X05"},{"t":"벌집","mis":"K2-1-u6-X05"}],"explanation":["「꿀벌」이 글에 여러 번 나와요.","다른 두 낱말은 한 번씩만 나와요.","나올 때마다 세어 봐요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#6','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"예의 바른 말","correct":true},{"t":"친구 말 끊기","mis":"K2-1-u6-X11"},{"t":"화난 목소리","mis":"K2-1-u6-X11"}],"explanation":["예의 바르게 말하면 친구도 잘 들어 줘요.","다른 보기는 생각을 나누는 데 방해가 돼요.","생각과 까닭을 예의 바르게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#7','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C9',1,'mc','auto','책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"기억에 남는 문장","correct":true},{"t":"시험 점수","mis":"K2-1-u6-X13"},{"t":"내일 날씨","mis":"K2-1-u6-X13"}],"explanation":["「기억에 남는 문장」은 책을 소개하는 데 도움이 돼요.","다른 보기는 책과 상관없어요.","「이 내용이 책을 알려 주나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#8','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C2',1,'ox','auto','「이 광고는 좋아.」라고만 말해도 내 생각이 충분히 전해져요.',ARRAY['K2-1-u6-X10']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"「이 광고는 좋아.」라고만 말해도 내 생각이 충분히 전해져요.","answer":"X","reason_options":[{"t":"왜 좋은지 까닭을 덧붙여야 잘 전해지니까","correct":true},{"t":"생각은 짧을수록 언제나 잘 전해지니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["「좋아.」만으로는 왜 좋은지 알 수 없어요.","생각과 까닭을 함께 말해요.","「왜냐하면 ~거든」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#9','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"식단표","r":"먹을 음식"},{"l":"일기 예보","r":"날씨"},{"l":"알림장","r":"준비물과 숙제"}],"mis":"K2-1-u6-X02","explanation":["「식단표」 — 먹을 음식","「일기 예보」 — 날씨","「알림장」 — 준비물과 숙제"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#10','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 둘째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 둘째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기는 친구와 함께 즐겁게 할 수 있습니다.","correct":true},{"t":"긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","mis":"K2-1-u6-X06"},{"t":"줄넘기를 하면 몸이 튼튼해집니다.","mis":"K2-1-u6-X07"}],"explanation":["둘째 부분은 친구와 즐겁게 할 수 있다는 것이 가장 하고 싶은 말이에요.","예를 들거나 까닭을 덧붙인 문장은 중심 문장이 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#11','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 민호가 줄넘기를 하자고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],false,'{"seq":11,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 민호가 줄넘기를 하자고 한 까닭은 무엇인가요?","options":[{"t":"넘은 횟수를 세면서 실력을 키울 수 있어서","correct":true},{"t":"규칙이 쉬워서 누구나 할 수 있어서","mis":"K2-1-u6-X08"},{"t":"민호의 줄넘기 줄이 새것이어서","mis":"K2-1-u6-X09"}],"explanation":["민호는 실력을 키울 수 있다고 했어요.","다른 친구의 까닭이나 까닭이 아닌 말과 헷갈리지 않아요.","생각 뒤의 좋은 점을 찾아요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#12','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.","pairs":[{"l":"서아","r":"피구를 하자"},{"l":"민호","r":"줄넘기를 하자"},{"l":"예린","r":"숨바꼭질을 하자"}],"mis":"K2-1-u6-X08","explanation":["서아 — 피구를 하자","민호 — 줄넘기를 하자","예린 — 숨바꼭질을 하자"],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#13','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C10',2,'match','auto','토박이말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u6-C10","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"단비","r":"꼭 필요할 때 알맞게 오는 비"},{"l":"함박눈","r":"굵고 탐스럽게 내리는 눈"},{"l":"나들이","r":"가까운 곳에 잠깐 다녀오는 일"}],"mis":"K2-1-u6-X15","explanation":["「단비」 — 꼭 필요할 때 알맞게 오는 비","「함박눈」 — 굵고 탐스럽게 내리는 눈","「나들이」 — 가까운 곳에 잠깐 다녀오는 일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#14','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',2,'mc','auto','「체육 시간에 무슨 놀이를 할까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":14,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"「체육 시간에 무슨 놀이를 할까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 피구가 좋다고 생각해. 왜냐하면 모두 함께 뛸 수 있거든.」","correct":true},{"t":"「피구 하고 싶어. 끝.」","mis":"K2-1-u6-X10"},{"t":"「피구 싫은 사람은 빠져!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","까닭 없이 말하거나 우기는 말은 생각을 잘 전하지 못해요.","「나는 ~라고 생각해. 왜냐하면 ~거든.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#15','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C7',2,'ox','auto','대화를 읽고 답해 보세요. 「규칙이 쉬워서 누구나 할 수 있으니까.」는 예린이가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C7","difficulty":2,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「규칙이 쉬워서 누구나 할 수 있으니까.」는 예린이가 말한 까닭이에요.","answer":"O","reason_options":[{"t":"숨바꼭질을 하자는 생각을 뒷받침하는 말이니까","correct":true},{"t":"예린이가 하고 싶은 놀이 이름이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["이 말은 숨바꼭질을 하자는 생각의 까닭이에요.","까닭은 생각을 뒷받침하는 좋은 점이나 옳은 점이에요.","「왜?」에 대답이 되는지 넣어 봐요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#16','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C2',2,'sa','auto','「나는 도서관 책 잔치에 가 보고 싶어. (     ) 책을 읽으면 책갈피도 받을 수 있거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C2","difficulty":2,"kind":"sa","stem":"「나는 도서관 책 잔치에 가 보고 싶어. (     ) 책을 읽으면 책갈피도 받을 수 있거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.","answer":["왜냐하면"],"explanation":["까닭을 말할 때는 「왜냐하면」으로 시작해요.","「왜냐하면」 뒤에 그렇게 생각한 까닭을 말해요.","생각 → 왜냐하면 → 까닭 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#17','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X16']::text[],false,'{"seq":17,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"예린 — 「꿀벌은 꽃잎을 먹고 산다.」","correct":true,"mis_target":"K2-1-u6-X07"},{"t":"민호 — 「꿀벌은 꽃에서 꿀을 모은다.」","mis":"K2-1-u6-X16"},{"t":"서아 — 「꿀벌은 함께 벌집을 짓는다.」","mis":"K2-1-u6-X16"}],"explanation":["꽃잎을 먹는다는 말은 글에 없어요.","중요한 내용은 글 전체를 보고 정리해요.","다른 두 친구는 바르게 정리했어요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#18','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C3',3,'mc','auto','「강아지는 냄새를 잘 맡습니다. 강아지는 주인을 반기며 꼬리를 흔듭니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":18,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「강아지는 냄새를 잘 맡습니다. 강아지는 주인을 반기며 꼬리를 흔듭니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"강아지의 특징","correct":true},{"t":"고양이 기르는 법","mis":"K2-1-u6-X04"},{"t":"맛있는 간식","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 강아지에 대해 알려 줘요.","다른 보기는 글의 내용과 어울리지 않아요.","글 전체가 무엇을 알려 주는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#19','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],false,'{"seq":19,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수빈 — 「서아는 규칙이 쉬워서 피구를 하자고 했어.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"시우 — 「민호는 실력을 키우려고 줄넘기를 하자고 했어.」","mis":"K2-1-u6-X16"},{"t":"다은 — 「예린이는 규칙이 쉬워서 숨바꼭질을 하자고 했어.」","mis":"K2-1-u6-X16"}],"explanation":["「규칙이 쉬워서」는 예린이가 말한 까닭이에요.","인물을 뒤바꾸지 않도록 말한 사람을 확인해요.","다른 두 친구는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#20','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',3,'error','auto','「체육 시간에 무슨 놀이를 할까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":20,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「체육 시간에 무슨 놀이를 할까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"준우 — 「숨바꼭질은 시시해. 그런 걸 고르는 건 이상해.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"예린 — 「나는 피구가 좋은데, 숨바꼭질 까닭도 들어 볼게.」","mis":"K2-1-u6-X16"},{"t":"하린 — 「숨바꼭질도 재미있겠다. 나는 줄넘기가 좋아.」","mis":"K2-1-u6-X16"}],"explanation":["친구가 고른 것을 이상하다고 하면 안 돼요.","생각이 달라도 친구의 까닭을 들어 봐요.","다른 두 친구는 예의 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#21','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C9',3,'mc','auto','상자를 읽고 답해 보세요. 기억에 남는 문장이 쓰인 곳과 그 문장을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X14','K2-1-u6-X13']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"상자를 읽고 답해 보세요. 기억에 남는 문장이 쓰인 곳과 그 문장을 바르게 말한 것은 어느 것인가요?","options":[{"t":"왼쪽 면 — 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","correct":true},{"t":"앞면 — 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","mis":"K2-1-u6-X14"},{"t":"왼쪽 면 — 수빈이의 받아쓰기 점수","mis":"K2-1-u6-X13"}],"explanation":["왼쪽 면에 기억에 남는 문장을 썼어요.","다른 보기는 상자의 내용과 맞지 않거나 책과 상관없어요.","상자의 면을 돌려 가며 살펴요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#22','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":22,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"열매","correct":true},{"t":"꿀벌","mis":"K2-1-u6-X16"},{"t":"하는 일","mis":"K2-1-u6-X16"}],"explanation":["「열매」는 한 번만 나와요.","다른 두 낱말은 제목에 있거나 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#23','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 꿀을 모은다 · 꽃가루를 옮겨 열매를 돕는다 · 함께 벌집을 짓는다 → 꿀벌은 꿀을 모으고, 열매가 열리게 돕고, 힘을 모아 벌집을 짓는다.","scoring_points":["중심 문장을 빠짐없이 찾았는가","예나 까닭을 덧붙인 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["중심 문장 찾기.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["꿀벌은 꽃에서 꿀을 모읍니다.","꿀벌은 꽃가루를 옮겨 열매가 열리도록 돕습니다.","꿀벌은 여럿이 힘을 모아 벌집을 짓습니다."],"title":"꿀벌이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#24','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C6',4,'essay','teacher','대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 서아 — 피구, 모두가 함께 뛸 수 있어서. 예린 — 숨바꼭질, 규칙이 쉬워서. 나는 서아 생각에 찬성해요. 왜냐하면 반 친구 모두가 함께 놀 수 있기 때문이에요.","scoring_points":["두 인물의 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가","찬성하는 생각과 내 까닭을 썼는가"]},"explanation":["인물의 생각.","짝이 되는 까닭.","내 생각과 까닭."],"asset":{"type":"speech","turns":[{"who":"서아","text":"피구를 하자. 우리 반 모두가 함께 뛸 수 있으니까."},{"who":"민호","text":"줄넘기를 하자. 넘은 횟수를 세면서 실력을 키울 수 있으니까."},{"who":"예린","text":"숨바꼭질을 하자. 규칙이 쉬워서 누구나 할 수 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_b#25','kor',2,1,'u6','','g2_1_kor_u6_review_b','unit_review','K2-1-u6-C8',4,'essay','teacher','「학급 문고에 어떤 책을 더 두면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"「학급 문고에 어떤 책을 더 두면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.","answer_guide":{"answer":"예: 나는 과학 그림책을 더 두면 좋겠다고 생각해. 왜냐하면 궁금한 것을 바로 찾아볼 수 있고, 그림이 많아 누구나 쉽게 읽을 수 있기 때문이야.","scoring_points":["내 생각을 분명히 썼는가","생각을 뒷받침하는 까닭을 두 가지 썼는가","알맞은 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","까닭 두 가지.","예의 바른 꼴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#1','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"알림장","correct":true},{"t":"필통","mis":"K2-1-u6-X01"},{"t":"컵","mis":"K2-1-u6-X01"}],"explanation":["「알림장」은 무언가를 알려 주는 매체예요.","다른 두 가지는 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#2','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"손을 깨끗이 씻는 일","correct":true},{"t":"비누의 냄새","mis":"K2-1-u6-X03"},{"t":"발을 씻는 방법","mis":"K2-1-u6-X04"}],"explanation":["제목에 글의 가장 중요한 내용이 담겨 있어요.","다른 보기는 글에 없거나 제목과 맞지 않아요.","제목을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#3','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 하늘이가 가고 싶어 한 곳은 어디인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하늘이가 가고 싶어 한 곳은 어디인가요?","options":[{"t":"바닷가","correct":true},{"t":"동물원","mis":"K2-1-u6-X08"},{"t":"과학관","mis":"K2-1-u6-X08"}],"explanation":["하늘이는 바닷가에 가고 싶다고 했어요.","다른 보기는 다른 친구의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#4','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C10',1,'mc','auto','토박이말 「여우비」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":4,"concept":"K2-1-u6-C10","difficulty":1,"kind":"mc","stem":"토박이말 「여우비」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"해가 난 날 잠깐 오는 비","correct":true},{"t":"여우가 오는 날","mis":"K2-1-u6-X15"},{"t":"밤새 많이 오는 비","mis":"K2-1-u6-X15"}],"explanation":["「여우비」는 「해가 난 날 잠깐 오는 비」를 뜻해요.","다른 보기는 뜻이 다르거나 글자 모양만 보고 짐작한 것이에요.","토박이말이 쓰이는 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#5','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":5,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"손","correct":true},{"t":"감기","mis":"K2-1-u6-X05"},{"t":"거품","mis":"K2-1-u6-X05"}],"explanation":["「손」이 글에 여러 번 나와요.","다른 두 낱말은 한 번씩만 나와요.","나올 때마다 세어 봐요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#6','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11','K2-1-u6-X10']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각","correct":true},{"t":"친구 놀리기","mis":"K2-1-u6-X11"},{"t":"「그냥」이라고만 하기","mis":"K2-1-u6-X10"}],"explanation":["무엇을 생각하는지 분명히 말해요.","다른 보기는 생각을 나누는 데 방해가 돼요.","생각과 까닭을 예의 바르게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#7','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C9',1,'mc','auto','책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"인상 깊은 장면","correct":true},{"t":"집 주소","mis":"K2-1-u6-X13"},{"t":"게임 이름","mis":"K2-1-u6-X13"}],"explanation":["「인상 깊은 장면」은 책을 소개하는 데 도움이 돼요.","다른 보기는 책과 상관없어요.","「이 내용이 책을 알려 주나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#8','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C2',1,'ox','auto','「왜냐하면」 뒤에는 그렇게 생각한 까닭을 말해요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"「왜냐하면」 뒤에는 그렇게 생각한 까닭을 말해요.","answer":"O","reason_options":[{"t":"「왜냐하면」은 까닭을 이끄는 말이니까","correct":true},{"t":"「왜냐하면」 뒤에는 인사말을 하니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["「왜냐하면 ~거든」으로 까닭을 말해요.","생각과 까닭을 함께 말해요.","「왜냐하면 ~거든」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#9','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"표지판","r":"길과 지켜야 할 일"},{"l":"달력","r":"날짜"},{"l":"그림책","r":"그림과 이야기"}],"mis":"K2-1-u6-X02","explanation":["「표지판」 — 길과 지켜야 할 일","「달력」 — 날짜","「그림책」 — 그림과 이야기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#10','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 첫째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"손을 깨끗이 씻으면 감기를 막을 수 있습니다.","correct":true},{"t":"손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","mis":"K2-1-u6-X06"},{"t":"손바닥과 손등, 손가락 사이까지 문지릅니다.","mis":"K2-1-u6-X07"}],"explanation":["첫째 부분은 손을 씻으면 감기를 막는다는 것이 가장 하고 싶은 말이에요.","예를 들거나 까닭을 덧붙인 문장은 중심 문장이 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#11','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 지호가 과학관에 가고 싶은 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],false,'{"seq":11,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 지호가 과학관에 가고 싶은 까닭은 무엇인가요?","options":[{"t":"여러 가지 실험을 해 볼 수 있어서","correct":true},{"t":"책에서만 본 동물을 볼 수 있어서","mis":"K2-1-u6-X08"},{"t":"과학관 지붕이 둥글어서","mis":"K2-1-u6-X09"}],"explanation":["지호는 실험을 해 볼 수 있다고 했어요.","다른 친구의 까닭이나 까닭이 아닌 말과 헷갈리지 않아요.","생각 뒤의 좋은 점을 찾아요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#12','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.","pairs":[{"l":"소율","r":"동물원에 가고 싶다"},{"l":"지호","r":"과학관에 가고 싶다"},{"l":"하늘","r":"바닷가에 가고 싶다"}],"mis":"K2-1-u6-X08","explanation":["소율 — 동물원에 가고 싶다","지호 — 과학관에 가고 싶다","하늘 — 바닷가에 가고 싶다"],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#13','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C10',2,'match','auto','토박이말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u6-C10","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"벗","r":"친하게 사귀는 사람"},{"l":"단비","r":"꼭 필요할 때 알맞게 오는 비"},{"l":"까치밥","r":"새가 먹으라고 남긴 감"}],"mis":"K2-1-u6-X15","explanation":["「벗」 — 친하게 사귀는 사람","「단비」 — 꼭 필요할 때 알맞게 오는 비","「까치밥」 — 새가 먹으라고 남긴 감"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#14','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',2,'mc','auto','「연못 반장으로 누가 좋을까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":14,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"「연못 반장으로 누가 좋을까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 거북이 좋다고 생각해. 왜냐하면 차분하게 꼼꼼히 살필 수 있거든.」","correct":true},{"t":"「거북이 좋아. 이유는 없어.」","mis":"K2-1-u6-X10"},{"t":"「거북 말고 고르는 애는 이상해!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","까닭 없이 말하거나 우기는 말은 생각을 잘 전하지 못해요.","「나는 ~라고 생각해. 왜냐하면 ~거든.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#15','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',2,'ox','auto','대화를 읽고 답해 보세요. 「과학관에 가고 싶어.」는 지호가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C7","difficulty":2,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「과학관에 가고 싶어.」는 지호가 말한 까닭이에요.","answer":"X","reason_options":[{"t":"이 말은 생각이고, 까닭은 「실험을 해 볼 수 있어서」니까","correct":true},{"t":"「가고 싶어」는 언제나 까닭이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["「과학관에 가고 싶어.」는 지호의 생각이에요.","까닭은 생각을 뒷받침하는 좋은 점이나 옳은 점이에요.","「왜?」에 대답이 되는지 넣어 봐요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#16','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C2',2,'sa','auto','「나는 손 씻기 글이 도움이 되었어. (     ) 손을 씻어야 할 때를 새로 알았거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C2","difficulty":2,"kind":"sa","stem":"「나는 손 씻기 글이 도움이 되었어. (     ) 손을 씻어야 할 때를 새로 알았거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.","answer":["왜냐하면"],"explanation":["까닭을 말할 때는 「왜냐하면」으로 시작해요.","「왜냐하면」 뒤에 그렇게 생각한 까닭을 말해요.","생각 → 왜냐하면 → 까닭 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#17','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X16']::text[],false,'{"seq":17,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"태민 — 「이 글의 중요한 내용은 거품이 하얗다는 것이다.」","correct":true,"mis_target":"K2-1-u6-X03"},{"t":"아린 — 「손을 씻으면 감기를 막을 수 있다.」","mis":"K2-1-u6-X16"},{"t":"시우 — 「밥 먹기 전에는 꼭 손을 씻는다.」","mis":"K2-1-u6-X16"}],"explanation":["거품 색깔은 글에 없고 중요한 내용도 아니에요.","중요한 내용은 글 전체를 보고 정리해요.","다른 두 친구는 바르게 정리했어요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#18','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C3',3,'mc','auto','「해바라기는 해를 따라 고개를 돌립니다. 해바라기 씨는 먹을 수 있습니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":18,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「해바라기는 해를 따라 고개를 돌립니다. 해바라기 씨는 먹을 수 있습니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"해바라기에 대해 알아봐요","correct":true},{"t":"장미꽃 키우기","mis":"K2-1-u6-X04"},{"t":"여름 방학 계획","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 해바라기에 대해 알려 줘요.","다른 보기는 글의 내용과 어울리지 않아요.","글 전체가 무엇을 알려 주는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#19','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],false,'{"seq":19,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「소율이는 실험을 하려고 동물원에 가고 싶대.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"지안 — 「지호는 실험을 하려고 과학관에 가고 싶대.」","mis":"K2-1-u6-X16"},{"t":"현우 — 「하늘이는 조개를 주우려고 바닷가에 가고 싶대.」","mis":"K2-1-u6-X16"}],"explanation":["「실험」은 지호가 말한 까닭이에요.","인물을 뒤바꾸지 않도록 말한 사람을 확인해요.","다른 두 친구는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#20','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',3,'error','auto','「연못 반장으로 누가 좋을까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":20,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「연못 반장으로 누가 좋을까?」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"태민 — 「거북을 고른 애들은 생각이 없어.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"다은 — 「나는 오리가 좋아. 거북 까닭도 일리가 있네.」","mis":"K2-1-u6-X16"},{"t":"민호 — 「나는 개구리가 좋아. 너는 왜 거북이야?」","mis":"K2-1-u6-X16"}],"explanation":["친구를 생각이 없다고 하면 안 돼요.","생각이 달라도 친구의 까닭을 들어 봐요.","다른 두 친구는 예의 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#21','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C9',3,'mc','auto','상자를 읽고 답해 보세요. 수빈이의 상자에 더 넣으면 좋을 내용은 어느 것인가요?',ARRAY['K2-1-u6-X07','K2-1-u6-X13']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"상자를 읽고 답해 보세요. 수빈이의 상자에 더 넣으면 좋을 내용은 어느 것인가요?","options":[{"t":"이 책을 권하고 싶은 친구와 그 까닭","correct":true},{"t":"달팽이 껍데기를 깨는 방법","mis":"K2-1-u6-X07"},{"t":"수빈이의 집 주소","mis":"K2-1-u6-X13"}],"explanation":["책 소개를 풍성하게 하는 내용이 알맞아요.","다른 보기는 상자의 내용과 맞지 않거나 책과 상관없어요.","상자의 면을 돌려 가며 살펴요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#22','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":22,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"거품","correct":true},{"t":"손","mis":"K2-1-u6-X16"},{"t":"씻어요","mis":"K2-1-u6-X16"}],"explanation":["「거품」은 한 번만 나와요.","다른 두 낱말은 제목에 있거나 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#23','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 손을 씻으면 감기를 막는다 · 비누로 구석구석 씻는다 · 씻어야 할 때를 지킨다 → 감기를 막으려면 비누로 구석구석, 씻어야 할 때 꼭 손을 씻자.","scoring_points":["중심 문장을 빠짐없이 찾았는가","예나 까닭을 덧붙인 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["중심 문장 찾기.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["손을 깨끗이 씻으면 감기를 막을 수 있습니다. 손에 묻은 나쁜 균이 씻겨 나가기 때문입니다.","손을 씻을 때에는 비누로 거품을 냅니다. 손바닥과 손등, 손가락 사이까지 문지릅니다.","밖에서 돌아왔을 때와 밥을 먹기 전에는 꼭 손을 씻습니다."],"title":"손을 깨끗이 씻어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#24','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C6',4,'essay','teacher','대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 소율 — 동물원, 동물을 직접 볼 수 있어서. 지호 — 과학관, 실험을 해 볼 수 있어서. 나는 지호 생각에 찬성해요. 왜냐하면 직접 해 보면 더 오래 기억에 남기 때문이에요.","scoring_points":["두 인물의 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가","찬성하는 생각과 내 까닭을 썼는가"]},"explanation":["인물의 생각.","짝이 되는 까닭.","내 생각과 까닭."],"asset":{"type":"speech","turns":[{"who":"소율","text":"동물원에 가고 싶어. 책에서만 본 동물을 직접 볼 수 있어서."},{"who":"지호","text":"과학관에 가고 싶어. 여러 가지 실험을 해 볼 수 있어서."},{"who":"하늘","text":"바닷가에 가고 싶어. 모래 놀이도 하고 조개도 주울 수 있어서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_c#25','kor',2,1,'u6','','g2_1_kor_u6_review_c','unit_review','K2-1-u6-C8',4,'essay','teacher','「교실 생물로 무엇을 기르면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"「교실 생물로 무엇을 기르면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.","answer_guide":{"answer":"예: 나는 강낭콩을 기르면 좋겠다고 생각해. 왜냐하면 자라는 모습을 날마다 볼 수 있고, 돌보는 방법도 어렵지 않기 때문이야.","scoring_points":["내 생각을 분명히 썼는가","생각을 뒷받침하는 까닭을 두 가지 썼는가","알맞은 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","까닭 두 가지.","예의 바른 꼴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#1','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C1',1,'mc','auto','정보를 주고받는 매체는 어느 것인가요?',ARRAY['K2-1-u6-X01']::text[],false,'{"seq":1,"concept":"K2-1-u6-C1","difficulty":1,"kind":"mc","stem":"정보를 주고받는 매체는 어느 것인가요?","options":[{"t":"일기 예보","correct":true},{"t":"공","mis":"K2-1-u6-X01"},{"t":"숟가락","mis":"K2-1-u6-X01"}],"explanation":["「일기 예보」는 무언가를 알려 주는 매체예요.","다른 두 가지는 정보를 알려 주지 않는 물건이에요.","「무엇을 알려 주지?」 물어서 대답이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#2','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C3',1,'mc','auto','글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?',ARRAY['K2-1-u6-X03','K2-1-u6-X04']::text[],false,'{"seq":2,"concept":"K2-1-u6-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 제목을 보고 짐작할 수 있는 이 글의 중요한 내용은 무엇인가요?","options":[{"t":"물을 아껴 쓰는 방법","correct":true},{"t":"물의 색깔","mis":"K2-1-u6-X03"},{"t":"수영을 잘하는 방법","mis":"K2-1-u6-X04"}],"explanation":["제목에 글의 가장 중요한 내용이 담겨 있어요.","다른 보기는 글에 없거나 제목과 맞지 않아요.","제목을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#3','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C6',1,'mc','auto','대화를 읽고 답해 보세요. 지후가 기르자고 한 것은 무엇인가요?',ARRAY['K2-1-u6-X08']::text[],false,'{"seq":3,"concept":"K2-1-u6-C6","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 지후가 기르자고 한 것은 무엇인가요?","options":[{"t":"달팽이","correct":true},{"t":"물고기","mis":"K2-1-u6-X08"},{"t":"강낭콩","mis":"K2-1-u6-X08"}],"explanation":["지후는 「달팽이를 기르자.」라고 했어요.","다른 보기는 다른 친구의 생각이에요.","말한 사람 이름을 확인해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#4','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C10',1,'mc','auto','토박이말 「함박눈」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X15']::text[],false,'{"seq":4,"concept":"K2-1-u6-C10","difficulty":1,"kind":"mc","stem":"토박이말 「함박눈」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"굵고 탐스럽게 내리는 눈","correct":true},{"t":"함박꽃이 피는 날","mis":"K2-1-u6-X15"},{"t":"아주 가늘게 내리는 눈","mis":"K2-1-u6-X15"}],"explanation":["「함박눈」은 「굵고 탐스럽게 내리는 눈」을 뜻해요.","다른 보기는 뜻이 다르거나 글자 모양만 보고 짐작한 것이에요.","토박이말이 쓰이는 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#5','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C4',1,'mc','auto','글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?',ARRAY['K2-1-u6-X05']::text[],false,'{"seq":5,"concept":"K2-1-u6-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에 가장 자주 나오는 낱말은 어느 것인가요?","options":[{"t":"물","correct":true},{"t":"컵","mis":"K2-1-u6-X05"},{"t":"샤워","mis":"K2-1-u6-X05"}],"explanation":["「물」이 글에 여러 번 나와요.","다른 두 낱말은 한 번씩만 나와요.","나올 때마다 세어 봐요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#6','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C8',1,'mc','auto','자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X11','K2-1-u6-X12']::text[],false,'{"seq":6,"concept":"K2-1-u6-C8","difficulty":1,"kind":"mc","stem":"자신의 생각을 표현할 때 필요한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구의 생각도 들어 보기","correct":true},{"t":"내 말만 하기","mis":"K2-1-u6-X11"},{"t":"다른 생각은 틀렸다고 하기","mis":"K2-1-u6-X12"}],"explanation":["친구의 생각을 들으면 서로 이해할 수 있어요.","다른 보기는 생각을 나누는 데 방해가 돼요.","생각과 까닭을 예의 바르게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#7','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C9',1,'mc','auto','책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u6-X13']::text[],false,'{"seq":7,"concept":"K2-1-u6-C9","difficulty":1,"kind":"mc","stem":"책 소개 상자에 담을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 든 느낌","correct":true},{"t":"받아쓰기 점수","mis":"K2-1-u6-X13"},{"t":"좋아하는 반찬","mis":"K2-1-u6-X13"}],"explanation":["「읽고 든 느낌」은 책을 소개하는 데 도움이 돼요.","다른 보기는 책과 상관없어요.","「이 내용이 책을 알려 주나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#8','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C2',1,'ox','auto','생각을 말할 때 「그냥」이라고 하면 까닭이 잘 드러나요.',ARRAY['K2-1-u6-X10']::text[],false,'{"seq":8,"concept":"K2-1-u6-C2","difficulty":1,"kind":"ox","stem":"생각을 말할 때 「그냥」이라고 하면 까닭이 잘 드러나요.","answer":"X","reason_options":[{"t":"「그냥」에는 까닭이 담겨 있지 않으니까","correct":true},{"t":"「그냥」은 가장 좋은 까닭이니까","mis":"K2-1-u6-X10"}],"mis":"K2-1-u6-X10","explanation":["「그냥」 대신 좋은 점이나 옳은 점을 말해요.","생각과 까닭을 함께 말해요.","「왜냐하면 ~거든」을 붙여 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#9','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C1',2,'match','auto','매체와 알려 주는 내용을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u6-C1","difficulty":2,"kind":"match","stem":"매체와 알려 주는 내용을 알맞게 이어 보세요.","pairs":[{"l":"안내판","r":"이용 방법과 주의할 점"},{"l":"식단표","r":"먹을 음식"},{"l":"일기 예보","r":"날씨"}],"mis":"K2-1-u6-X02","explanation":["「안내판」 — 이용 방법과 주의할 점","「식단표」 — 먹을 음식","「일기 예보」 — 날씨"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#10','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C5',2,'mc','auto','글을 읽고 답해 보세요. 셋째 부분의 중심 문장은 어느 것인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X07']::text[],false,'{"seq":10,"concept":"K2-1-u6-C5","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 셋째 부분의 중심 문장은 어느 것인가요?","options":[{"t":"줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다.","correct":true},{"t":"운동장에서도, 집 앞 마당에서도 할 수 있습니다.","mis":"K2-1-u6-X06"},{"t":"줄넘기를 하면 몸이 튼튼해집니다.","mis":"K2-1-u6-X07"}],"explanation":["셋째 부분은 어디서나 할 수 있다는 것이 가장 하고 싶은 말이에요.","예를 들거나 까닭을 덧붙인 문장은 중심 문장이 아니에요.","그 부분에서 가장 하고 싶은 말을 찾아요."],"asset":{"type":"passage","lines":["줄넘기를 하면 몸이 튼튼해집니다. 팔과 다리를 함께 움직이기 때문입니다.","줄넘기는 친구와 함께 즐겁게 할 수 있습니다. 긴 줄을 여럿이 함께 넘으면 더 신이 납니다.","줄넘기는 줄 하나만 있으면 어디서나 할 수 있습니다. 운동장에서도, 집 앞 마당에서도 할 수 있습니다."],"title":"줄넘기의 좋은 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#11','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C7',2,'mc','auto','대화를 읽고 답해 보세요. 지후가 달팽이를 기르자고 한 까닭은 무엇인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X09']::text[],false,'{"seq":11,"concept":"K2-1-u6-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 지후가 달팽이를 기르자고 한 까닭은 무엇인가요?","options":[{"t":"천천히 기어가는 모습이 귀엽고 만져 볼 수 있어서","correct":true},{"t":"싹이 자라는 모습을 볼 수 있어서","mis":"K2-1-u6-X08"},{"t":"지후 집에 달팽이 그림이 있어서","mis":"K2-1-u6-X09"}],"explanation":["지후는 귀엽고 만져 볼 수 있다고 했어요.","다른 친구의 까닭이나 까닭이 아닌 말과 헷갈리지 않아요.","생각 뒤의 좋은 점을 찾아요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#12','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C6',2,'match','auto','대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u6-C6","difficulty":2,"kind":"match","stem":"대화를 읽고 인물과 그 생각을 알맞게 이어 보세요.","pairs":[{"l":"개구리","r":"목소리가 커서 반장이 되겠다"},{"l":"거북","r":"꼼꼼해서 반장이 되겠다"},{"l":"오리","r":"두루 살필 수 있어서 반장이 되겠다"}],"mis":"K2-1-u6-X08","explanation":["개구리 — 목소리가 커서 반장이 되겠다","거북 — 꼼꼼해서 반장이 되겠다","오리 — 두루 살필 수 있어서 반장이 되겠다"],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#13','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C10',2,'match','auto','토박이말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u6-C10","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"여우비","r":"해 난 날 잠깐 오는 비"},{"l":"나들이","r":"가까운 곳에 잠깐 다녀오는 일"},{"l":"함박눈","r":"굵고 탐스럽게 내리는 눈"}],"mis":"K2-1-u6-X15","explanation":["「여우비」 — 해 난 날 잠깐 오는 비","「나들이」 — 가까운 곳에 잠깐 다녀오는 일","「함박눈」 — 굵고 탐스럽게 내리는 눈"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#14','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C8',2,'mc','auto','「체험학습으로 어디에 갈까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X10','K2-1-u6-X11']::text[],false,'{"seq":14,"concept":"K2-1-u6-C8","difficulty":2,"kind":"mc","stem":"「체험학습으로 어디에 갈까?」에 대해 내 생각을 까닭과 함께 예의 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 과학관이 좋다고 생각해. 왜냐하면 직접 실험을 해 볼 수 있거든.」","correct":true},{"t":"「과학관. 그냥 좋아.」","mis":"K2-1-u6-X10"},{"t":"「무조건 과학관이야. 다른 데는 안 돼!」","mis":"K2-1-u6-X11"}],"explanation":["생각과 까닭을 함께 예의 바르게 말했어요.","까닭 없이 말하거나 우기는 말은 생각을 잘 전하지 못해요.","「나는 ~라고 생각해. 왜냐하면 ~거든.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#15','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C7',2,'ox','auto','대화를 읽고 답해 보세요. 「먹이만 잘 주면 되어서 돌보기 쉽거든.」은 도윤이가 말한 까닭이에요.',ARRAY['K2-1-u6-X09']::text[],false,'{"seq":15,"concept":"K2-1-u6-C7","difficulty":2,"kind":"ox","stem":"대화를 읽고 답해 보세요. 「먹이만 잘 주면 되어서 돌보기 쉽거든.」은 도윤이가 말한 까닭이에요.","answer":"O","reason_options":[{"t":"물고기를 기르자는 생각을 뒷받침하는 말이니까","correct":true},{"t":"도윤이가 기르고 싶은 동물 이름이니까","mis":"K2-1-u6-X09"}],"mis":"K2-1-u6-X09","explanation":["이 말은 물고기를 기르자는 생각의 까닭이에요.","까닭은 생각을 뒷받침하는 좋은 점이나 옳은 점이에요.","「왜?」에 대답이 되는지 넣어 봐요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"물고기를 기르자. 먹이만 잘 주면 되어서 돌보기 쉽거든."},{"who":"하린","text":"강낭콩을 기르자. 싹이 트고 자라는 모습을 날마다 볼 수 있거든."},{"who":"지후","text":"달팽이를 기르자. 천천히 기어가는 모습이 귀엽고 만져 볼 수도 있거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#16','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C2',2,'sa','auto','「나는 오리가 반장이 되면 좋겠어. (     ) 연못 구석구석을 살필 수 있거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u6-C2","difficulty":2,"kind":"sa","stem":"「나는 오리가 반장이 되면 좋겠어. (     ) 연못 구석구석을 살필 수 있거든.」 빈칸에 들어갈, 까닭을 이끄는 말을 네 글자로 써 보세요.","answer":["왜냐하면"],"explanation":["까닭을 말할 때는 「왜냐하면」으로 시작해요.","「왜냐하면」 뒤에 그렇게 생각한 까닭을 말해요.","생각 → 왜냐하면 → 까닭 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#17','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C5',3,'error','auto','글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u6-X06','K2-1-u6-X16']::text[],false,'{"seq":17,"concept":"K2-1-u6-C5","difficulty":3,"kind":"error","stem":"글을 읽고 중요한 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"로아 — 「이 글의 중요한 내용은 샤워를 짧게 하자는 것뿐이다.」","correct":true,"mis_target":"K2-1-u6-X06"},{"t":"채원 — 「컵에 물을 받아 이를 닦는다.」","mis":"K2-1-u6-X16"},{"t":"건우 — 「여러 방법으로 물을 아껴 쓰자.」","mis":"K2-1-u6-X16"}],"explanation":["샤워는 물을 아끼는 방법 가운데 하나일 뿐이에요.","중요한 내용은 글 전체를 보고 정리해요.","다른 두 친구는 바르게 정리했어요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#18','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C3',3,'mc','auto','「곰은 겨울에 굴속에서 잠을 잡니다. 개구리도 땅속에서 겨울잠을 잡니다.」 이 글에 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u6-X04']::text[],false,'{"seq":18,"concept":"K2-1-u6-C3","difficulty":3,"kind":"mc","stem":"「곰은 겨울에 굴속에서 잠을 잡니다. 개구리도 땅속에서 겨울잠을 잡니다.」 이 글에 어울리는 제목은 어느 것인가요?","options":[{"t":"겨울잠을 자는 동물","correct":true},{"t":"여름에 노는 동물","mis":"K2-1-u6-X04"},{"t":"동물원 가는 길","mis":"K2-1-u6-X04"}],"explanation":["글 전체가 겨울잠을 자는 동물을 알려 줘요.","다른 보기는 글의 내용과 어울리지 않아요.","글 전체가 무엇을 알려 주는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#19','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C7',3,'error','auto','대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u6-X08','K2-1-u6-X16']::text[],false,'{"seq":19,"concept":"K2-1-u6-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 인물의 생각과 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도담 — 「거북은 목소리가 커서 반장이 되겠대.」","correct":true,"mis_target":"K2-1-u6-X08"},{"t":"서윤 — 「개구리는 목소리가 커서 반장이 되겠대.」","mis":"K2-1-u6-X16"},{"t":"하준 — 「오리는 연못을 두루 살필 수 있어서 반장이 되겠대.」","mis":"K2-1-u6-X16"}],"explanation":["「목소리가 커서」는 개구리가 말한 까닭이에요.","인물을 뒤바꾸지 않도록 말한 사람을 확인해요.","다른 두 친구는 바르게 말했어요."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#20','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C8',3,'error','auto','「같은 책을 읽고 든 느낌」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?',ARRAY['K2-1-u6-X12','K2-1-u6-X16']::text[],false,'{"seq":20,"concept":"K2-1-u6-C8","difficulty":3,"kind":"error","stem":"「같은 책을 읽고 든 느낌」에 대해 생각을 나눴어요. 친구의 생각을 존중하지 않은 친구는 누구인가요?","options":[{"t":"현우 — 「달팽이가 답답하다고? 네 느낌은 틀렸어.」","correct":true,"mis_target":"K2-1-u6-X12"},{"t":"소율 — 「너는 답답했구나. 나는 멋졌어.」","mis":"K2-1-u6-X16"},{"t":"로아 — 「나도 처음엔 답답했는데 끝에는 멋졌어.」","mis":"K2-1-u6-X16"}],"explanation":["같은 책도 느낌이 다를 수 있어요.","생각이 달라도 친구의 까닭을 들어 봐요.","다른 두 친구는 예의 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#21','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C9',3,'mc','auto','상자를 읽고 답해 보세요. 앞면에 담긴 내용을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u6-X14','K2-1-u6-X13']::text[],false,'{"seq":21,"concept":"K2-1-u6-C9","difficulty":3,"kind":"mc","stem":"상자를 읽고 답해 보세요. 앞면에 담긴 내용을 바르게 말한 것은 어느 것인가요?","options":[{"t":"제목과 인상 깊은 장면 그림","correct":true},{"t":"수빈이의 생각과 까닭","mis":"K2-1-u6-X14"},{"t":"수빈이의 전화번호","mis":"K2-1-u6-X13"}],"explanation":["앞면에는 제목과 인상 깊은 장면을 담았어요.","다른 보기는 상자의 내용과 맞지 않거나 책과 상관없어요.","상자의 면을 돌려 가며 살펴요."],"asset":{"type":"passage","lines":["[앞면] 제목: 달팽이 우체부 — 비 오는 날 달팽이가 편지를 들고 기어가는 그림","[왼쪽 면] 기억에 남는 문장: 「늦어도 괜찮아. 마음은 꼭 전해질 거야.」","[오른쪽 면] 내 생각: 느려도 끝까지 해내는 달팽이가 멋지다고 생각해요.","왜냐하면 비가 와도 포기하지 않았기 때문이에요."],"title":"수빈이의 책 소개 상자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#22','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u6-X16']::text[],false,'{"seq":22,"concept":"K2-1-u6-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 중요한 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"샤워","correct":true},{"t":"물","mis":"K2-1-u6-X16"},{"t":"아껴","mis":"K2-1-u6-X16"}],"explanation":["「샤워」는 한 번만 나와요.","다른 두 낱말은 제목에 있거나 여러 번 나와요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#23','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C5',4,'essay','teacher','글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u6-C5","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 이 글의 중심 문장을 찾아 쓰고, 그것을 모아 중요한 내용을 한두 문장으로 정리해 보세요.","answer_guide":{"answer":"예: 컵에 물을 받아 이를 닦는다 · 비누칠할 때 수도꼭지를 잠근다 · 샤워는 짧게 한다 → 여러 방법으로 물을 아껴 쓰자.","scoring_points":["중심 문장을 빠짐없이 찾았는가","예나 까닭을 덧붙인 문장을 중심 문장으로 쓰지 않았는가","중심 문장을 모아 중요한 내용을 정리했는가"]},"explanation":["중심 문장 찾기.","뒷받침 문장과 가리기.","모아 정리하기."],"asset":{"type":"passage","lines":["물을 아껴 쓰는 방법을 알아봅시다.","이를 닦을 때에는 컵에 물을 받아 씁니다.","비누칠을 하는 동안에는 수도꼭지를 잠급니다.","샤워는 짧게 합니다."],"title":"물을 아껴 써요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#24','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C6',4,'essay','teacher','대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u6-C6","difficulty":4,"kind":"essay","stem":"대화나 글을 읽고 답해 보세요. 두 인물의 생각과 까닭을 정리하고, 내가 찬성하는 생각을 골라 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 개구리 — 목소리가 커서 잘 알린다. 거북 — 차분해서 꼼꼼히 살핀다. 나는 거북에게 찬성해요. 왜냐하면 반장은 실수 없이 살피는 것이 중요하기 때문이에요.","scoring_points":["두 인물의 생각을 바르게 썼는가","생각과 짝이 되는 까닭을 바르게 썼는가","찬성하는 생각과 내 까닭을 썼는가"]},"explanation":["인물의 생각.","짝이 되는 까닭.","내 생각과 까닭."],"asset":{"type":"passage","lines":["연못 동물들이 반장을 뽑기로 했어요.","개구리가 말했어요. 「내가 반장이 될래. 목소리가 커서 알릴 일을 잘 전할 수 있어.」","거북이 말했어요. 「내가 반장이 될래. 느리지만 차분해서 꼼꼼하게 살필 수 있어.」","오리가 말했어요. 「내가 반장이 될래. 헤엄도 치고 날 수도 있어서 연못 구석구석을 둘러볼 수 있어.」"],"title":"누가 연못 반장이 될까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u6_review_d#25','kor',2,1,'u6','','g2_1_kor_u6_review_d','unit_review','K2-1-u6-C8',4,'essay','teacher','「체험학습으로 어디에 가면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u6-C8","difficulty":4,"kind":"essay","stem":"「체험학습으로 어디에 가면 좋을까」에 대한 내 생각을 정하고, 「나는 ~라고 생각해. 왜냐하면 ~」 꼴로 까닭을 두 가지 들어 예의 바르게 써 보세요.","answer_guide":{"answer":"예: 나는 과학관에 가면 좋겠다고 생각해. 왜냐하면 직접 실험을 해 볼 수 있고, 비가 와도 안에서 볼 수 있기 때문이야.","scoring_points":["내 생각을 분명히 썼는가","생각을 뒷받침하는 까닭을 두 가지 썼는가","알맞은 꼴로 예의 바르게 썼는가"]},"explanation":["내 생각.","까닭 두 가지.","예의 바른 꼴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C1','kor',2,1,'u7',1,'고운 말이 필요한 까닭 — 같은 일이라도 어떻게 말하느냐에 따라 듣는 사람의 기분과 사이가 달라지며, 듣는 사람을 생각하며 하는 고운 말은 마음을 따뜻하게 하고 사이를 가깝게 함을 알기',ARRAY['2국01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C2','kor',2,1,'u7',1,'거친 말을 고운 말로 바꾸기 — 탓하거나 놀리거나 명령하는 거친 말을 같은 뜻을 곱게 전하는 말(부탁하는 말·마음을 헤아리는 말)로 바꾸어 상황에 맞게 말하기',ARRAY['2국01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C3','kor',2,1,'u7',3,'경험을 떠올리며 이야기 듣기 — 이야기를 들으며 누가·무슨 일을 했는지·왜 그랬는지 내용을 확인하고 비슷한 내 경험을 떠올려 더 잘 이해하기',ARRAY['2국01-05']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C4','kor',2,1,'u7',3,'인물의 경험과 내 경험 비교하기 — 인물이 겪은 일과 그때의 마음을 찾고, 겪은 일이 똑같지 않아도 비슷한 마음이 들었던 내 경험을 떠올려 같은 점·다른 점 말하기',ARRAY['2국01-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C5','kor',2,1,'u7',5,'발표할 경험 정리하기 — 한 일·본 일·들은 일 가운데 기억에 남는 경험을 골라 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌을 빠짐없이 정리하기',ARRAY['2국01-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C6','kor',2,1,'u7',5,'바른 자세로 발표하고 듣기 — 듣는 사람을 바라보며 알맞은 목소리 크기로 말끝까지 또박또박 발표하고, 듣는 사람은 발표하는 친구를 바라보며 끝까지 들은 뒤 궁금한 점을 묻기',ARRAY['2국01-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C7','kor',2,1,'u7',7,'상황 속 상대의 마음 짐작하기 — 대화나 상황에서 상대가 왜 그렇게 했는지(일부러인지 실수인지)와 지금 어떤 마음일지(속상함·억울함·당황함·미안함) 짐작하기',ARRAY['2국01-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C8','kor',2,1,'u7',7,'마음을 생각하며 고운 말로 대화하기 — 상대의 마음을 먼저 생각하고 상황에 맞게 「고마워」·「미안해」·「괜찮아?」·부탁하는 말 같은 고운 말로 대화하여 다툼을 풀기',ARRAY['2국01-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C9','kor',2,1,'u7',9,'인물의 마음을 생각하며 이야기 읽기 — 이야기 속 인물의 마음이 무엇 때문에 어떻게 바뀌는지 짐작하고, 흉내 내는 말(데굴데굴·엉금엉금·방긋·둥실둥실)이 인물의 모습과 마음을 생생하게 나타냄을 알기',ARRAY['2국01-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C10','kor',2,1,'u7',9,'고운 말로 마음 전하기 — 고마운 마음·미안한 마음·축하하는 마음을 받는 사람·전하고 싶은 마음·그 까닭이 드러나게 고운 말이나 마음 쪽지로 전하기',ARRAY['2국01-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C11','kor',2,1,'u7',12,'고운 말을 즐겁게 연습하고 실천하기 — 고운 말 맞추기 놀이로 고운 말을 익히고, 놀이에서 연습한 고운 말을 집과 학교 생활에서 상황에 맞게 실천하기',ARRAY['2국01-02']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C12','kor',2,1,'u7',14,'확실한 일은 또렷하게 말하기 — 내가 겪어서 확실히 아는 일은 「~것 같아요」 대신 「~했어요」·「~예요」처럼 또렷하게 말하고, 「~것 같아요」는 짐작할 때에 쓰기',ARRAY['2국01-04']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X01','kor',2,'u7',ARRAY['K2-1-u7-C1','K2-1-u7-C11']::text[],'말이 듣는 사람의 기분과 사이에 주는 영향을 생각하지 않는다(뜻만 같으면 기분도 같다, 어른 앞에서만 고운 말을 쓰면 된다)','그 말을 내가 들었다면 기분이 어땠을지 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X02','kor',2,'u7',ARRAY['K2-1-u7-C2','K2-1-u7-C8','K2-1-u7-C10','K2-1-u7-C11']::text[],'상황과 고운 말의 짝을 헷갈린다(도움을 받고 「미안해」, 잘못하고 「고마워」, 생일에 「미안해」)','「고마운 일인가, 미안한 일인가, 기쁜 일인가?」 먼저 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X03','kor',2,'u7',ARRAY['K2-1-u7-C1','K2-1-u7-C2','K2-1-u7-C8','K2-1-u7-C11']::text[],'놀리거나 탓하거나 비꼬는 말을 고운 말로 여기거나, 부탁하는 말 끝에 놀리는 말을 붙여도 괜찮다고 여긴다','말 끝까지 다 듣고 「듣는 사람 마음이 따뜻해질까?」 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X04','kor',2,'u7',ARRAY['K2-1-u7-C3','K2-1-u7-C5','K2-1-u7-C9','K2-1-u7-C11']::text[],'이야기·발표·맞추기판에 없는 내용을 있다고 하거나 내용을 놓친다','글에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X05','kor',2,'u7',ARRAY['K2-1-u7-C3','K2-1-u7-C4','K2-1-u7-C5','K2-1-u7-C7','K2-1-u7-C9']::text[],'인물을 뒤바꿔 다른 인물이 한 일·마음을 말한다','누가 한 일인지 이름에 동그라미 치고 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X06','kor',2,'u7',ARRAY['K2-1-u7-C4','K2-1-u7-C5']::text[],'있었던 일과 그때의 마음(생각이나 느낌)을 헷갈린다','「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X07','kor',2,'u7',ARRAY['K2-1-u7-C4']::text[],'이야기와 상관없는 일을 비슷한 경험으로 떠올리거나, 똑같은 일을 겪어야만 비슷한 경험이라고 여긴다','「그때 인물과 비슷한 마음이었나?」 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X08','kor',2,'u7',ARRAY['K2-1-u7-C5']::text[],'발표 내용에 언제·어디에서·생각이나 느낌을 빠뜨리거나 경험과 상관없는 내용을 넣는다','언제 · 어디서 · 무슨 일 · 느낌 네 손가락을 꼽으며 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X09','kor',2,'u7',ARRAY['K2-1-u7-C5']::text[],'발표 내용과 질문(언제?·어디에서?·무슨 일?)의 짝을 헷갈린다','질문을 붙여 「~에」 대답이 되는지 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X10','kor',2,'u7',ARRAY['K2-1-u7-C6']::text[],'바르지 않은 발표 자세(바닥 보기·말끝 흐리기·너무 작거나 큰 소리)를 바르다고 여긴다','맨 뒤 친구가 잘 듣고 내 얼굴을 볼 수 있는지 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X11','kor',2,'u7',ARRAY['K2-1-u7-C6']::text[],'바르지 않은 듣는 자세(끼어들기·딴짓·놀리기)를 괜찮다고 여긴다','발표가 끝날 때까지 기다렸다가 손 들고 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X12','kor',2,'u7',ARRAY['K2-1-u7-C2','K2-1-u7-C7','K2-1-u7-C8']::text[],'상대의 마음은 생각하지 않고 내 기분대로만 말하거나, 일부러 한 일이 아닌데도 상대를 탓한다','「일부러 그랬을까?」 먼저 생각하고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X13','kor',2,'u7',ARRAY['K2-1-u7-C7','K2-1-u7-C9']::text[],'상황에 맞지 않게 상대의 마음을 짐작한다(다친 친구가 기쁠 것이다, 도와준 사람이 싫었을 것이다)','내가 그 사람이라면 어떤 마음일지 바꿔 생각해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X14','kor',2,'u7',ARRAY['K2-1-u7-C9']::text[],'흉내 내는 말의 뜻을 헷갈린다(엉금엉금 → 빠르게, 둥실둥실 → 떨어지는 모양)','흉내 내는 말을 몸짓으로 따라 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X15','kor',2,'u7',ARRAY['K2-1-u7-C10']::text[],'마음은 말로 전하지 않아도 된다고 여기거나, 쪽지에 받는 사람·쓴 사람·무엇이 고마운지(미안한지)를 헷갈리거나 빠뜨린다','누구에게 · 어떤 마음 · 왜 — 세 가지가 있는지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X16','kor',2,'u7',ARRAY['K2-1-u7-C11']::text[],'고운 말 맞추기 놀이의 방법을 헷갈리거나, 고운 말은 놀이할 때만 쓰면 된다고 여긴다','놀이에서 쓴 고운 말을 오늘 누구에게 쓸지 정해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X17','kor',2,'u7',ARRAY['K2-1-u7-C12']::text[],'확실한 일인데도 「~것 같아요」를 버릇처럼 쓰거나, 짐작하는 일까지 단정해서 말한다','「내가 직접 겪었나?」 물어보고 겪었으면 「~했어요」로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X18','kor',2,'u7',ARRAY['K2-1-u7-C1','K2-1-u7-C2','K2-1-u7-C3','K2-1-u7-C4','K2-1-u7-C5','K2-1-u7-C6','K2-1-u7-C7','K2-1-u7-C8','K2-1-u7-C9','K2-1-u7-C10','K2-1-u7-C11','K2-1-u7-C12']::text[],'묻는 말을 거꾸로 읽는다 — 알맞지 않은↔알맞은, 잘못↔바르게, 아닌↔맞는','물음의 「않은·잘못·아닌」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#1','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],true,'{"seq":1,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「내가 도와줄게.」","correct":true},{"t":"「저리 비켜.」","mis":"K2-1-u7-X03"},{"t":"「그것도 못하니?」","mis":"K2-1-u7-X03"}],"explanation":["「내가 도와줄게.」는 듣는 사람을 생각하는 고운 말이에요.","「저리 비켜.」와 「그것도 못하니?」는 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「고마워.」","correct":true},{"t":"「시끄러워.」","mis":"K2-1-u7-X03"},{"t":"「바보야.」","mis":"K2-1-u7-X03"}],"explanation":["「고마워.」는 마음을 따뜻하게 하는 고운 말이에요.","「시끄러워.」와 「바보야.」는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#2','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C1',1,'ox','auto','같은 일이라도 어떻게 말하느냐에 따라 듣는 사람의 기분이 달라져요.',ARRAY['K2-1-u7-X01']::text[],true,'{"seq":2,"concept":"K2-1-u7-C1","difficulty":1,"kind":"ox","stem":"같은 일이라도 어떻게 말하느냐에 따라 듣는 사람의 기분이 달라져요.","answer":"O","reason_options":[{"t":"고운 말은 마음을 따뜻하게 하고 거친 말은 마음을 아프게 하니까","correct":true},{"t":"뜻만 같으면 듣는 사람의 기분은 늘 똑같으니까","mis":"K2-1-u7-X01"}],"mis":"K2-1-u7-X01","explanation":["같은 부탁도 곱게 말하면 기분 좋게 들어 줘요.","거칠게 말하면 뜻이 같아도 마음이 상해요.","말할 때 듣는 사람의 마음을 생각해요."],"variant_rule":{"alt":[{"stem":"친구에게 거친 말을 해도 친구 사이는 그대로예요.","answer":"X","reason_options":[{"t":"거친 말을 들으면 마음이 상해서 사이가 멀어질 수 있으니까","correct":true},{"t":"친구는 무슨 말을 들어도 마음이 상하지 않으니까","mis":"K2-1-u7-X01"}],"explanation":["거친 말은 친구의 마음을 아프게 해요.","마음이 상하면 사이가 멀어질 수 있어요.","고운 말은 사이를 가깝게 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#3','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',1,'mc','auto','그림을 그리다가 물감을 쏟아 속상한 친구에게 할 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],true,'{"seq":3,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"그림을 그리다가 물감을 쏟아 속상한 친구에게 할 고운 말은 어느 것인가요?","options":[{"t":"「괜찮아, 같이 닦자.」","correct":true},{"t":"「그러게 조심하랬잖아.」","mis":"K2-1-u7-X12"},{"t":"「하하, 다 망쳤네!」","mis":"K2-1-u7-X03"}],"explanation":["속상한 친구의 마음을 헤아려 돕는 말이에요.","「조심하랬잖아.」는 친구를 탓하는 말이에요.","친구의 실수를 웃음거리로 삼으면 안 돼요."],"variant_rule":{"alt":[{"stem":"받아쓰기에서 한 문제를 틀려 속상한 친구에게 할 고운 말은 어느 것인가요?","options":[{"t":"「다음에는 더 잘할 수 있을 거야.」","correct":true},{"t":"「그것도 틀렸어?」","mis":"K2-1-u7-X03"},{"t":"「나는 다 맞았는데.」","mis":"K2-1-u7-X12"}],"explanation":["속상한 친구에게 힘을 주는 말이에요.","「그것도 틀렸어?」는 친구를 놀리는 말이에요.","내 자랑만 하면 친구의 마음을 생각하지 않은 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#4','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C1',1,'mc','auto','고운 말을 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],true,'{"seq":4,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"고운 말을 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람의 마음을 따뜻하게 하고 사이를 가깝게 해 주니까","correct":true},{"t":"말을 빨리 끝낼 수 있으니까","mis":"K2-1-u7-X01"},{"t":"선생님이 계실 때만 지키면 되니까","mis":"K2-1-u7-X01"}],"explanation":["고운 말은 듣는 사람의 기분을 좋게 해요.","말이 빨리 끝나는 것은 고운 말을 쓰는 까닭이 아니에요.","고운 말은 언제 어디서나 써요."],"variant_rule":{"alt":[{"stem":"고운 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"듣는 사람을 생각하며 하는 말이에요","correct":true},{"t":"어른에게만 쓰는 말이에요","mis":"K2-1-u7-X01"},{"t":"크게 소리치는 말이에요","mis":"K2-1-u7-X03"}],"explanation":["고운 말은 듣는 사람의 마음을 생각하며 하는 말이에요.","친구와 동생에게도 고운 말을 써요.","소리를 크게 낸다고 고운 말이 되지는 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#5','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"너 때문에 늦었잖아!","r":"다음엔 조금 서둘러 줄래?"},{"l":"그것도 몰라?","r":"내가 같이 알아볼게."},{"l":"비켜!","r":"잠깐 지나가도 될까?"}],"mis":"K2-1-u7-X02","explanation":["탓하는 말은 부탁하는 말로 바꿔요.","모른다고 놀리지 말고 함께 알아보자고 해요.","「비켜!」 대신 지나가도 되는지 물어봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"시끄러워!","r":"조금만 작게 말해 줄래?"},{"l":"내 거 만지지 마!","r":"쓰기 전에 먼저 물어봐 줄래?"},{"l":"느림보야!","r":"천천히 해도 괜찮아."}],"explanation":["「시끄러워!」 대신 작게 말해 달라고 부탁해요.","만지지 말라고 소리치지 말고 먼저 물어봐 달라고 해요.","느리다고 놀리지 말고 기다려 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#6','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',2,'mc','auto','친구가 내 지우개를 말없이 가져가 썼어요. 내 마음을 고운 말로 전한 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],true,'{"seq":6,"concept":"K2-1-u7-C2","difficulty":2,"kind":"mc","stem":"친구가 내 지우개를 말없이 가져가 썼어요. 내 마음을 고운 말로 전한 것은 어느 것인가요?","options":[{"t":"「다음에는 쓰기 전에 말해 줄래?」","correct":true},{"t":"「왜 마음대로 가져가? 도둑이야?」","mis":"K2-1-u7-X12"},{"t":"「가져가 줘서 고마워.」","mis":"K2-1-u7-X02"}],"explanation":["바라는 것을 부탁하는 말로 전했어요.","친구를 도둑이라고 하면 마음이 크게 상해요.","고마운 일이 아니니 「고마워.」는 맞지 않아요."],"variant_rule":{"alt":[{"stem":"짝이 수업 시간에 자꾸 내 책상을 흔들어요. 내 마음을 고운 말로 전한 것은 어느 것인가요?","options":[{"t":"「책상이 흔들려서 글씨가 삐뚤어져. 조금만 조심해 줄래?」","correct":true},{"t":"「야, 그만 좀 해!」","mis":"K2-1-u7-X12"},{"t":"「축하해!」","mis":"K2-1-u7-X02"}],"explanation":["까닭을 말하고 부탁하는 말로 전했어요.","「그만 좀 해!」는 화난 내 기분만 쏟아 낸 말이에요.","축하할 일이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#7','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C1',2,'mc','auto','「또 늦었어? 맨날 굼벵이야.」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],true,'{"seq":7,"concept":"K2-1-u7-C1","difficulty":2,"kind":"mc","stem":"「또 늦었어? 맨날 굼벵이야.」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하고 서운하다","correct":true},{"t":"고맙고 기쁘다","mis":"K2-1-u7-X01"},{"t":"신나고 자랑스럽다","mis":"K2-1-u7-X01"}],"explanation":["놀리는 말을 들으면 속상하고 서운해요.","고맙거나 신날 까닭이 없어요.","내가 들었다면 어땠을지 떠올려요."],"variant_rule":{"alt":[{"stem":"「같이 하자. 내가 도와줄게.」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"든든하고 고맙다","correct":true},{"t":"창피하고 화난다","mis":"K2-1-u7-X01"},{"t":"슬프고 외롭다","mis":"K2-1-u7-X01"}],"explanation":["도와주겠다는 말을 들으면 든든하고 고마워요.","창피하거나 화날 까닭이 없어요.","고운 말은 마음을 따뜻하게 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#8','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',2,'error','auto','친구에게 한 말이에요. 고운 말이 아닌 말을 한 친구는 누구인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X18']::text[],true,'{"seq":8,"concept":"K2-1-u7-C2","difficulty":2,"kind":"error","stem":"친구에게 한 말이에요. 고운 말이 아닌 말을 한 친구는 누구인가요?","options":[{"t":"도담 — 「네 그림은 왜 이렇게 이상해?」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"하늘 — 「네 그림 색깔이 참 예쁘다.」","mis":"K2-1-u7-X18"},{"t":"윤서 — 「같이 그리니까 더 재미있다.」","mis":"K2-1-u7-X18"}],"explanation":["「왜 이렇게 이상해?」는 친구 그림을 깎아내리는 말이에요.","하늘이와 윤서는 고운 말을 했어요.","물음의 「아닌」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구에게 한 말이에요. 고운 말이 아닌 말을 한 친구는 누구인가요?","options":[{"t":"건우 — 「넌 달리기 꼴찌잖아.」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"채원 — 「끝까지 달린 게 멋졌어.」","mis":"K2-1-u7-X18"},{"t":"지우 — 「다음엔 같이 연습하자.」","mis":"K2-1-u7-X18"}],"explanation":["「꼴찌잖아.」는 친구를 놀리는 말이에요.","채원이와 지우는 고운 말을 했어요.","물음의 「아닌」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#9','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',2,'blank','auto','친구가 내 실내화를 찾아 주었어요. 「(     ) 덕분에 찾았어.」 빈칸에 알맞은 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],true,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"blank","stem":"친구가 내 실내화를 찾아 주었어요. 「(     ) 덕분에 찾았어.」 빈칸에 알맞은 고운 말은 어느 것인가요?","options":[{"t":"고마워.","correct":true},{"t":"미안해.","mis":"K2-1-u7-X02"},{"t":"축하해.","mis":"K2-1-u7-X02"}],"explanation":["도움을 받았으니 「고마워.」라고 해요.","「미안해.」는 잘못했을 때 하는 말이에요.","「축하해.」는 기쁜 일이 있을 때 하는 말이에요."],"variant_rule":{"alt":[{"stem":"내가 실수로 친구의 발을 밟았어요. 「(     ) 많이 아프지?」 빈칸에 알맞은 고운 말은 어느 것인가요?","options":[{"t":"미안해.","correct":true},{"t":"고마워.","mis":"K2-1-u7-X02"},{"t":"잘했어.","mis":"K2-1-u7-X02"}],"explanation":["잘못했으니 「미안해.」라고 해요.","「고마워.」는 도움을 받았을 때 하는 말이에요.","칭찬할 일이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#10','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C1',3,'mc','auto','하준이는 친구에게 「느림보!」라고 놀렸어요. 그 뒤로 친구가 하준이와 놀지 않으려고 해요. 이 일로 알 수 있는 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X01']::text[],true,'{"seq":10,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"하준이는 친구에게 「느림보!」라고 놀렸어요. 그 뒤로 친구가 하준이와 놀지 않으려고 해요. 이 일로 알 수 있는 것은 어느 것인가요?","options":[{"t":"거친 말은 친구 사이를 멀어지게 할 수 있어요","correct":true},{"t":"놀리는 말은 장난이라서 괜찮아요","mis":"K2-1-u7-X03"},{"t":"친구가 놀지 않는 것은 말과 상관없어요","mis":"K2-1-u7-X01"}],"explanation":["놀리는 말에 마음이 상해서 친구가 멀어졌어요.","장난이라도 듣는 사람이 아프면 거친 말이에요.","말은 친구 사이에 큰 힘을 가져요."],"variant_rule":{"alt":[{"stem":"서윤이가 친구에게 「힘내, 할 수 있어!」라고 말해 주었더니 친구가 끝까지 해냈어요. 이 일로 알 수 있는 것은 어느 것인가요?","options":[{"t":"고운 말은 친구에게 힘을 줄 수 있어요","correct":true},{"t":"말은 친구의 마음에 아무 힘이 없어요","mis":"K2-1-u7-X01"},{"t":"「힘내」는 거친 말이에요","mis":"K2-1-u7-X03"}],"explanation":["응원하는 고운 말이 친구에게 힘이 되었어요.","말은 마음에 큰 힘을 가져요.","「힘내」는 고운 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#1','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',2,'mc','auto','고운 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],false,'{"seq":1,"concept":"K2-1-u7-C2","difficulty":2,"kind":"mc","stem":"고운 말이 아닌 것은 어느 것인가요?","options":[{"t":"「넌 원래 그래.」","correct":true},{"t":"「괜찮아.」","mis":"K2-1-u7-X18"},{"t":"「같이 하자.」","mis":"K2-1-u7-X18"}],"explanation":["「넌 원래 그래.」는 친구를 깎아내리는 말이에요.","「괜찮아.」와 「같이 하자.」는 고운 말이에요.","물음의 「아닌」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#2','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',2,'mc','auto','말을 할 때 먼저 생각해야 할 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X01']::text[],false,'{"seq":2,"concept":"K2-1-u7-C1","difficulty":2,"kind":"mc","stem":"말을 할 때 먼저 생각해야 할 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이 말을 들을 사람의 마음","correct":true},{"t":"내가 지금 얼마나 화가 났는지","mis":"K2-1-u7-X12"},{"t":"말이 얼마나 긴지","mis":"K2-1-u7-X01"}],"explanation":["고운 말은 듣는 사람의 마음을 생각하는 데서 시작해요.","내 기분대로만 말하면 거친 말이 나오기 쉬워요.","말의 길이는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#3','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',3,'mc','auto','모둠 활동에서 한 친구가 자기 생각만 계속 말해요. 내 생각을 고운 말로 전한 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],false,'{"seq":3,"concept":"K2-1-u7-C2","difficulty":3,"kind":"mc","stem":"모둠 활동에서 한 친구가 자기 생각만 계속 말해요. 내 생각을 고운 말로 전한 것은 어느 것인가요?","options":[{"t":"「네 생각도 좋다. 이번에는 내 생각도 들어 줄래?」","correct":true},{"t":"「너만 떠들지 마!」","mis":"K2-1-u7-X12"},{"t":"「응, 네 마음대로 다 해.」 하고 짜증 내기","mis":"K2-1-u7-X03"}],"explanation":["친구 생각을 인정하고 내 바람을 부탁하는 말로 전했어요.","「떠들지 마!」는 친구를 탓하는 거친 말이에요.","짜증 내며 비꼬는 말도 고운 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#4','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',3,'error','auto','거친 말을 고운 말로 바꾸었어요. 잘못 바꾼 친구는 누구인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X18']::text[],false,'{"seq":4,"concept":"K2-1-u7-C2","difficulty":3,"kind":"error","stem":"거친 말을 고운 말로 바꾸었어요. 잘못 바꾼 친구는 누구인가요?","options":[{"t":"민준 — 「저리 비켜!」 → 「저리 좀 비켜 줄래, 느림보야?」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"아린 — 「시끄러워!」 → 「조금만 작게 말해 줄래?」","mis":"K2-1-u7-X18"},{"t":"지안 — 「내 거야!」 → 「이건 내 거라서 먼저 물어봐 줘.」","mis":"K2-1-u7-X18"}],"explanation":["부탁하는 말 끝에 「느림보야」를 붙이면 놀리는 말이 돼요.","아린이와 지안이는 바르게 바꾸었어요.","말 끝까지 다 고운지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#5','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',3,'ox','auto','친구에게 장난으로 한 놀리는 말은 친구가 웃고 있으면 괜찮아요.',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":5,"concept":"K2-1-u7-C1","difficulty":3,"kind":"ox","stem":"친구에게 장난으로 한 놀리는 말은 친구가 웃고 있으면 괜찮아요.","answer":"X","reason_options":[{"t":"겉으로 웃어도 속으로는 마음이 상했을 수 있으니까","correct":true},{"t":"웃고 있으면 마음도 언제나 기쁜 것이니까","mis":"K2-1-u7-X03"}],"mis":"K2-1-u7-X03","explanation":["웃는 얼굴 뒤에 속상한 마음이 있을 수 있어요.","장난이라도 놀리는 말은 거친 말이에요.","듣는 사람의 마음을 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#6','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',3,'mc','auto','동생이 내 책에 낙서를 했어요. 동생의 마음을 생각하며 고운 말로 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C2","difficulty":3,"kind":"mc","stem":"동생이 내 책에 낙서를 했어요. 동생의 마음을 생각하며 고운 말로 말한 것은 어느 것인가요?","options":[{"t":"「그림 그리고 싶었구나. 그래도 책 말고 이 종이에 그리자.」","correct":true},{"t":"「너 진짜 미워!」","mis":"K2-1-u7-X12"},{"t":"「낙서 잘했네!」","mis":"K2-1-u7-X02"}],"explanation":["동생의 마음을 알아주고 바라는 것을 부탁했어요.","「미워!」는 화난 기분만 쏟아 낸 말이에요.","칭찬할 일이 아니니 「잘했네!」는 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#7','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',3,'mc','auto','「문 닫아!」와 「문 좀 닫아 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":7,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「문 닫아!」와 「문 좀 닫아 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「문 좀 닫아 줄래?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「문 닫아!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 부탁하는 말이 더 고와요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#8','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',4,'mc','auto','친구가 내 자리에 앉아 있어서 수업 준비를 못 하고 있어요. 까닭과 바라는 것을 함께 담아 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],false,'{"seq":8,"concept":"K2-1-u7-C2","difficulty":4,"kind":"mc","stem":"친구가 내 자리에 앉아 있어서 수업 준비를 못 하고 있어요. 까닭과 바라는 것을 함께 담아 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「곧 수업이 시작돼서 준비해야 하거든. 자리를 비켜 줄 수 있니?」","correct":true},{"t":"「내 자리야, 당장 일어나!」","mis":"K2-1-u7-X12"},{"t":"「자리를 비켜 줄 수 있니? 넌 눈치도 없구나.」","mis":"K2-1-u7-X03"}],"explanation":["까닭을 말하고 부탁하는 말로 전했어요.","「당장 일어나!」는 명령하는 거친 말이에요.","부탁 뒤에 「눈치도 없구나」를 붙이면 비꼬는 말이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#9','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',4,'essay','teacher','내가 들었던 말 가운데 기분이 상했던 말을 하나 떠올려 쓰고, 그 말을 같은 뜻의 고운 말로 바꾸어 쓴 뒤 그렇게 바꾼 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":4,"kind":"essay","stem":"내가 들었던 말 가운데 기분이 상했던 말을 하나 떠올려 쓰고, 그 말을 같은 뜻의 고운 말로 바꾸어 쓴 뒤 그렇게 바꾼 까닭을 써 보세요.","answer_guide":{"answer":"예: 들었던 말 — 「너는 왜 맨날 늦어?」 바꾼 말 — 「무슨 일 있었니? 다음엔 같이 일찍 오자.」 까닭 — 늦은 까닭을 먼저 물어봐 주면 친구가 덜 속상하기 때문이에요.","scoring_points":["기분이 상했던 말을 썼는가","같은 뜻을 고운 말로 바꾸어 썼는가","듣는 사람의 마음을 생각해 바꾼 까닭을 썼는가"]},"explanation":["기분이 상했던 말.","고운 말로 바꾸기.","바꾼 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#10','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',4,'essay','teacher','고운 말을 들어서 기분이 좋아졌던 경험을 떠올려 누가 어떤 말을 해 주었는지와 그때의 내 마음을 쓰고, 고운 말이 왜 필요한지 내 생각을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C1","difficulty":4,"kind":"essay","stem":"고운 말을 들어서 기분이 좋아졌던 경험을 떠올려 누가 어떤 말을 해 주었는지와 그때의 내 마음을 쓰고, 고운 말이 왜 필요한지 내 생각을 써 보세요.","answer_guide":{"answer":"예: 줄넘기 시험 날 짝이 「너는 할 수 있어!」라고 말해 주었어요. 그 말을 듣고 떨리던 마음이 든든해졌어요. 고운 말은 듣는 사람에게 힘을 주고 사이를 가깝게 해 주기 때문에 필요하다고 생각해요.","scoring_points":["누가 어떤 고운 말을 해 주었는지 썼는가","그때의 내 마음을 썼는가","고운 말이 필요한 까닭을 내 생각으로 썼는가"]},"explanation":["누가 어떤 말.","그때의 마음.","필요한 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#1','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 서준이가 현관에 서 있던 까닭은 무엇인가요?',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":1,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이가 현관에 서 있던 까닭은 무엇인가요?","options":[{"t":"우산이 없어서","correct":true},{"t":"친구를 기다리려고","mis":"K2-1-u7-X04"},{"t":"신발을 잃어버려서","mis":"K2-1-u7-X04"}],"explanation":["서준이는 우산이 없어서 현관에 서 있었어요.","친구를 기다리거나 신발을 잃어버렸다는 말은 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우가 공원에서 연습한 것은 무엇인가요?","options":[{"t":"두발자전거 타기","correct":true},{"t":"줄넘기","mis":"K2-1-u7-X04"},{"t":"연날리기","mis":"K2-1-u7-X04"}],"explanation":["시우는 아빠와 두발자전거 타기를 연습했어요.","줄넘기와 연날리기는 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#2','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 서준이에게 우산을 같이 쓰자고 한 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],true,'{"seq":2,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이에게 우산을 같이 쓰자고 한 인물은 누구인가요?","options":[{"t":"아린","correct":true},{"t":"서준","mis":"K2-1-u7-X05"},{"t":"선생님","mis":"K2-1-u7-X04"}],"explanation":["아린이가 「내 우산 같이 쓰자.」라고 말했어요.","서준이는 우산이 없던 인물이에요.","선생님은 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우의 자전거를 뒤에서 잡아 주겠다고 한 인물은 누구인가요?","options":[{"t":"아빠","correct":true},{"t":"시우","mis":"K2-1-u7-X05"},{"t":"형","mis":"K2-1-u7-X04"}],"explanation":["아빠가 「뒤에서 잡아 줄게.」라고 말했어요.","시우는 자전거를 배우던 인물이에요.","형은 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#3','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',1,'ox','auto','이야기를 읽고 답해 보세요. 서준이와 아린이는 우산 하나를 같이 쓰고 집까지 걸어갔어요.',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"ox","stem":"이야기를 읽고 답해 보세요. 서준이와 아린이는 우산 하나를 같이 쓰고 집까지 걸어갔어요.","answer":"O","reason_options":[{"t":"이야기에 둘이 우산을 나란히 쓰고 걸어갔다고 했으니까","correct":true},{"t":"아린이는 우산을 빌려주고 혼자 비를 맞았으니까","mis":"K2-1-u7-X04"}],"mis":"K2-1-u7-X04","explanation":["이야기에 둘이 우산 하나를 나란히 썼다고 했어요.","아린이가 비를 맞았다는 말은 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우는 처음부터 넘어지지 않고 자전거를 잘 탔어요.","answer":"X","reason_options":[{"t":"처음에는 기우뚱거리다 넘어져 무릎이 까졌다고 했으니까","correct":true},{"t":"시우는 자전거를 한 번도 연습하지 않았으니까","mis":"K2-1-u7-X04"}],"explanation":["처음에는 넘어져 무릎이 까졌어요.","몇 번을 더 연습해서 혼자 타게 되었어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#4','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',1,'mc','auto','이야기를 들을 때 비슷한 내 경험을 떠올리면 좋은 점은 무엇인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X07']::text[],true,'{"seq":4,"concept":"K2-1-u7-C4","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 비슷한 내 경험을 떠올리면 좋은 점은 무엇인가요?","options":[{"t":"이야기가 더 잘 이해되고 재미있어져요","correct":true},{"t":"이야기를 끝까지 듣지 않아도 돼요","mis":"K2-1-u7-X04"},{"t":"인물의 이름을 바꿀 수 있어요","mis":"K2-1-u7-X07"}],"explanation":["내 경험과 이어 보면 인물의 마음이 더 잘 느껴져요.","이야기는 끝까지 잘 들어야 해요.","인물의 이름을 바꾸는 것과는 상관없어요."],"variant_rule":{"alt":[{"stem":"인물의 경험과 내 경험을 비교할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"인물과 내가 겪은 일과 그때의 마음","correct":true},{"t":"인물이 입은 옷의 색깔","mis":"K2-1-u7-X07"},{"t":"이야기의 글자 수","mis":"K2-1-u7-X07"}],"explanation":["겪은 일과 그때의 마음을 나란히 놓고 비교해요.","옷 색깔은 경험을 비교하는 데 필요 없어요.","글자 수는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#5','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',2,'match','auto','이야기를 읽고 있었던 일과 그때의 마음을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C4","difficulty":2,"kind":"match","stem":"이야기를 읽고 있었던 일과 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"서준이가 우산 없이 서 있었다","r":"걱정스러웠다"},{"l":"서준이가 비를 안 맞고 집에 왔다","r":"고마웠다"},{"l":"아린이가 친구를 도왔다","r":"뿌듯했다"}],"mis":"K2-1-u7-X06","explanation":["우산이 없을 때는 걱정스러웠을 거예요.","비를 안 맞게 되어 고마웠어요.","아린이는 친구를 도와 뿌듯했어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 있었던 일과 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"꽈당 넘어졌다","r":"아프고 속상했다"},{"l":"「나는 못 하겠어.」라고 했다","r":"그만두고 싶었다"},{"l":"혼자 자전거를 탔다","r":"하늘을 날 것처럼 기뻤다"}],"explanation":["넘어졌을 때는 아프고 속상했어요.","못 하겠다고 할 때는 그만두고 싶었어요.","혼자 탔을 때는 무척 기뻤어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#6','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 서준이와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],true,'{"seq":6,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"지우 — 「준비물을 안 가져왔을 때 짝이 빌려줘서 고마웠어.」","correct":true},{"t":"민호 — 「어제 저녁에 카레를 먹었어.」","mis":"K2-1-u7-X07"},{"t":"다은 — 「나는 비 오는 날을 좋아해.」","mis":"K2-1-u7-X07"}],"explanation":["서준이처럼 곤란할 때 친구의 도움을 받아 고마웠던 경험이에요.","저녁 반찬은 이야기와 상관없는 일이에요.","비를 좋아하는 것은 겪은 일이 아니라 좋아하는 것이에요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"하람 — 「수영을 처음 배울 때 무서웠는데 계속 연습해서 해냈어.」","correct":true},{"t":"채원 — 「내 자전거는 빨간색이야.」","mis":"K2-1-u7-X07"},{"t":"준우 — 「공원에는 비둘기가 많아.」","mis":"K2-1-u7-X07"}],"explanation":["처음엔 어려웠지만 연습해서 해낸 경험이 시우와 비슷해요.","자전거 색깔은 겪은 일이 아니에요.","공원의 비둘기는 이야기와 상관없어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#7','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',2,'mc','auto','이야기를 읽고 답해 보세요. 아린이가 우산을 같이 쓰자며 든 까닭은 무엇인가요?',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":7,"concept":"K2-1-u7-C3","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 아린이가 우산을 같이 쓰자며 든 까닭은 무엇인가요?","options":[{"t":"집이 같은 쪽이라서","correct":true},{"t":"우산이 두 개라서","mis":"K2-1-u7-X04"},{"t":"서준이가 빌려 달라고 부탁해서","mis":"K2-1-u7-X04"}],"explanation":["아린이는 「우리 집도 같은 쪽이야.」라고 했어요.","우산이 두 개라는 말은 없어요.","서준이가 부탁했다는 말도 없어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 아빠가 시우에게 해 준 말은 무엇인가요?","options":[{"t":"「괜찮아. 아빠가 뒤에서 잡아 줄게.」","correct":true},{"t":"「넘어지면 그만 타자.」","mis":"K2-1-u7-X04"},{"t":"「나는 못 하겠어.」","mis":"K2-1-u7-X05"}],"explanation":["아빠는 괜찮다며 뒤에서 잡아 주겠다고 했어요.","그만 타자는 말은 이야기에 없어요.","「나는 못 하겠어.」는 시우가 한 말이에요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#8','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',2,'sa','auto','이야기를 읽고 답해 보세요. 서준이가 아린이에게 한 고운 말을 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u7-C3","difficulty":2,"kind":"sa","stem":"이야기를 읽고 답해 보세요. 서준이가 아린이에게 한 고운 말을 세 글자로 써 보세요.","answer":["고마워"],"explanation":["서준이는 「고마워, 아린아.」라고 했어요.","도움을 받았을 때 하는 고운 말이에요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우가 넘어져서 다친 곳을 두 글자로 써 보세요.","answer":["무릎"],"explanation":["시우는 넘어져 무릎이 까졌어요.","처음에는 기우뚱거리다 넘어졌어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#9','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',2,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X18']::text[],true,'{"seq":9,"concept":"K2-1-u7-C4","difficulty":2,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"로아 — 「서준이처럼 나도 친구를 도와주고 뿌듯했어.」","correct":true,"mis_target":"K2-1-u7-X05"},{"t":"태민 — 「아린이처럼 나도 짐이 많은 할머니를 도와드리고 뿌듯했어.」","mis":"K2-1-u7-X18"},{"t":"윤호 — 「서준이처럼 나도 곤란할 때 친구가 도와줘서 고마웠어.」","mis":"K2-1-u7-X18"}],"explanation":["친구를 도와 뿌듯했던 인물은 서준이가 아니라 아린이에요.","태민이와 윤호는 인물을 바르게 짝 지었어요.","누가 한 일인지 이름에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"소율 — 「시우처럼 나도 처음부터 한 번에 줄넘기를 잘했어.」","correct":true,"mis_target":"K2-1-u7-X07"},{"t":"민준 — 「시우처럼 나도 줄넘기에 자꾸 걸렸지만 연습해서 해냈어.」","mis":"K2-1-u7-X18"},{"t":"서아 — 「시우 아빠처럼 언니도 내가 넘어졌을 때 괜찮다고 해 줬어.」","mis":"K2-1-u7-X18"}],"explanation":["시우는 처음에 넘어졌다가 연습해서 해냈어요.","처음부터 잘한 경험은 시우와 비슷하지 않아요.","민준이와 서아는 바르게 비교했어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#10','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',3,'mc','auto','이야기를 읽고 답해 보세요. 아린이의 마음과 가장 비슷한 마음이 들었을 경험은 어느 것인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X07']::text[],true,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 아린이의 마음과 가장 비슷한 마음이 들었을 경험은 어느 것인가요?","options":[{"t":"길을 묻는 할머니께 길을 알려 드렸을 때","correct":true},{"t":"비 오는 날 우산이 없어 곤란했을 때","mis":"K2-1-u7-X05"},{"t":"새 운동화를 샀을 때","mis":"K2-1-u7-X07"}],"explanation":["아린이는 친구를 도와 뿌듯했어요. 남을 도와드린 경험이 비슷해요.","우산이 없어 곤란했던 것은 서준이의 경험이에요.","새 운동화를 산 기쁨은 남을 도운 뿌듯함과 달라요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우가 마지막에 느낀 마음과 가장 비슷한 마음이 들었을 경험은 어느 것인가요?","options":[{"t":"몇 번 실패한 끝에 혼자 신발 끈을 묶었을 때","correct":true},{"t":"넘어져 무릎이 까졌을 때","mis":"K2-1-u7-X04"},{"t":"동생과 장난감을 나눠 가졌을 때","mis":"K2-1-u7-X07"}],"explanation":["시우는 연습 끝에 해내서 무척 기뻤어요.","넘어졌을 때는 기쁨이 아니라 속상한 마음이었어요.","장난감을 나눈 일은 해낸 기쁨과 달라요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#1','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',2,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":1,"concept":"K2-1-u7-C3","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"비가 쏟아졌다 → 아린이가 같이 쓰자고 했다 → 둘이 함께 걸어갔다","correct":true},{"t":"아린이가 같이 쓰자고 했다 → 비가 쏟아졌다 → 둘이 함께 걸어갔다","mis":"K2-1-u7-X04"},{"t":"둘이 함께 걸어갔다 → 비가 쏟아졌다 → 서준이가 고맙다고 했다","mis":"K2-1-u7-X04"}],"explanation":["비가 쏟아진 뒤 아린이가 다가왔어요.","그다음 둘이 우산을 쓰고 걸어갔어요.","이야기의 차례를 손가락으로 짚어 확인해요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#2','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',2,'mc','auto','이야기를 읽고 답해 보세요. 시우가 혼자 자전거를 탈 수 있게 된 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":2,"concept":"K2-1-u7-C3","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시우가 혼자 자전거를 탈 수 있게 된 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"넘어져도 포기하지 않고 몇 번을 더 연습해서","correct":true},{"t":"자전거를 새로 사서","mis":"K2-1-u7-X04"},{"t":"넘어진 뒤 바로 집에 가서","mis":"K2-1-u7-X04"}],"explanation":["몇 번을 더 연습하자 혼자 타게 되었어요.","자전거를 새로 샀다는 말은 없어요.","집에 갔다면 혼자 탈 수 없었을 거예요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#3','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',3,'mc','auto','이야기를 읽고 「나도 비슷한 경험이 있어.」라며 말했어요. 있었던 일과 그때의 마음을 모두 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X06','K2-1-u7-X07']::text[],false,'{"seq":3,"concept":"K2-1-u7-C4","difficulty":3,"kind":"mc","stem":"이야기를 읽고 「나도 비슷한 경험이 있어.」라며 말했어요. 있었던 일과 그때의 마음을 모두 말한 것은 어느 것인가요?","options":[{"t":"「나도 우산이 없을 때 짝이 같이 써 줘서 정말 고마웠어.」","correct":true},{"t":"「나도 우산이 없던 적이 있어.」","mis":"K2-1-u7-X06"},{"t":"「나는 비가 좋아.」","mis":"K2-1-u7-X07"}],"explanation":["있었던 일(짝이 우산을 같이 써 줌)과 마음(고마웠음)을 함께 말했어요.","있었던 일만 말하고 마음은 빠졌어요.","좋아하는 것은 겪은 일이 아니에요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#4','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',3,'error','auto','이야기를 읽고 내용을 말했어요. 이야기와 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X18']::text[],false,'{"seq":4,"concept":"K2-1-u7-C3","difficulty":3,"kind":"error","stem":"이야기를 읽고 내용을 말했어요. 이야기와 다르게 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「아빠가 자전거를 대신 타 주었어.」","correct":true,"mis_target":"K2-1-u7-X04"},{"t":"지호 — 「시우는 넘어져서 무릎이 까졌어.」","mis":"K2-1-u7-X18"},{"t":"예린 — 「아빠가 괜찮다고 하며 뒤에서 잡아 준다고 했어.」","mis":"K2-1-u7-X18"}],"explanation":["아빠가 자전거를 대신 탔다는 말은 이야기에 없어요.","지호와 예린이는 이야기와 같게 말했어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#5','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',3,'ox','auto','이야기 속 인물과 똑같은 일을 겪은 적이 없으면 비슷한 내 경험을 떠올릴 수 없어요.',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":5,"concept":"K2-1-u7-C4","difficulty":3,"kind":"ox","stem":"이야기 속 인물과 똑같은 일을 겪은 적이 없으면 비슷한 내 경험을 떠올릴 수 없어요.","answer":"X","reason_options":[{"t":"똑같은 일이 아니어도 비슷한 마음이 들었던 일을 떠올릴 수 있으니까","correct":true},{"t":"인물과 모든 것이 똑같아야 비슷한 경험이니까","mis":"K2-1-u7-X07"}],"mis":"K2-1-u7-X07","explanation":["우산을 같이 쓴 적이 없어도 도움을 받아 고마웠던 일은 떠올릴 수 있어요.","비슷한 마음이 들었던 일이면 비슷한 경험이에요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#6','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',3,'mc','auto','이야기를 읽고 답해 보세요. 「우두커니」는 서준이의 어떤 모습을 나타내나요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":6,"concept":"K2-1-u7-C3","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 「우두커니」는 서준이의 어떤 모습을 나타내나요?","options":[{"t":"어찌할 바를 몰라 가만히 서 있는 모습","correct":true},{"t":"신나게 뛰어다니는 모습","mis":"K2-1-u7-X04"},{"t":"친구와 웃으며 이야기하는 모습","mis":"K2-1-u7-X04"}],"explanation":["우산이 없어 어찌할 바를 몰라 가만히 서 있었어요.","뛰어다녔다는 말은 없어요.","이때는 아직 아린이가 오기 전이에요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#7','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',3,'mc','auto','시우의 이야기를 듣고 떠올린 내 경험이에요. 「나는 지난봄에 처음 수영을 배웠어. 물이 코로 들어가서 무서웠어. 그래도 계속 연습해서 이제는 앞으로 갈 수 있어.」 여기에서 그때의 마음에 해당하는 것은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":7,"concept":"K2-1-u7-C4","difficulty":3,"kind":"mc","stem":"시우의 이야기를 듣고 떠올린 내 경험이에요. 「나는 지난봄에 처음 수영을 배웠어. 물이 코로 들어가서 무서웠어. 그래도 계속 연습해서 이제는 앞으로 갈 수 있어.」 여기에서 그때의 마음에 해당하는 것은 어느 것인가요?","options":[{"t":"무서웠어","correct":true},{"t":"처음 수영을 배웠어","mis":"K2-1-u7-X06"},{"t":"계속 연습했어","mis":"K2-1-u7-X06"}],"explanation":["「무서웠어」가 그때의 마음이에요.","「처음 수영을 배웠어」는 있었던 일이에요.","「계속 연습했어」도 한 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#8','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',4,'mc','auto','이야기를 읽고 답해 보세요. 서준이와 아린이의 마음을 바르게 짐작하고 내 경험과 이어 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":8,"concept":"K2-1-u7-C4","difficulty":4,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이와 아린이의 마음을 바르게 짐작하고 내 경험과 이어 말한 것은 어느 것인가요?","options":[{"t":"「서준이는 고맙고 아린이는 뿌듯했을 거야. 나도 동생 숙제를 도와줬을 때 아린이처럼 뿌듯했어.」","correct":true},{"t":"「서준이는 뿌듯하고 아린이는 고마웠을 거야. 나도 그랬어.」","mis":"K2-1-u7-X05"},{"t":"「둘 다 비를 맞아서 슬펐을 거야. 나도 비 맞은 적 있어.」","mis":"K2-1-u7-X04"}],"explanation":["두 인물의 마음을 바르게 짐작하고 비슷한 내 경험을 이었어요.","두 인물의 마음이 뒤바뀌었어요.","둘은 비를 맞지 않았어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#9','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',4,'essay','teacher','시우처럼 처음에는 어려웠지만 끝까지 해낸 내 경험을 떠올려 있었던 일과 그때의 마음을 쓰고, 시우의 경험과 비교해 같은 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C4","difficulty":4,"kind":"essay","stem":"시우처럼 처음에는 어려웠지만 끝까지 해낸 내 경험을 떠올려 있었던 일과 그때의 마음을 쓰고, 시우의 경험과 비교해 같은 점을 써 보세요.","answer_guide":{"answer":"예: 처음 줄넘기 2단 뛰기를 할 때 자꾸 줄에 걸려서 속상했어요. 날마다 연습했더니 마침내 성공해서 정말 기뻤어요. 시우처럼 처음엔 그만두고 싶었지만 포기하지 않고 연습해서 해낸 점이 같아요.","scoring_points":["있었던 일을 썼는가","그때의 마음을 썼는가","시우의 경험과 같은 점을 썼는가"]},"explanation":["있었던 일.","그때의 마음.","같은 점."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#10','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',4,'essay','teacher','이야기를 읽고 답해 보세요. 내가 서준이라면 다음 날 아린이에게 어떤 고운 말을 더 해 주고 싶은지 쓰고, 그렇게 말하고 싶은 까닭을 이야기 내용을 들어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C3","difficulty":4,"kind":"essay","stem":"이야기를 읽고 답해 보세요. 내가 서준이라면 다음 날 아린이에게 어떤 고운 말을 더 해 주고 싶은지 쓰고, 그렇게 말하고 싶은 까닭을 이야기 내용을 들어 써 보세요.","answer_guide":{"answer":"예: 「어제 우산 같이 써 줘서 정말 고마웠어. 다음에 비 오면 이번엔 내가 같이 써 줄게.」 왜냐하면 아린이 덕분에 비를 하나도 안 맞고 집에 갈 수 있었기 때문이에요.","scoring_points":["아린이에게 할 고운 말을 썼는가","이야기 내용을 들어 까닭을 썼는가","이야기에 없는 내용을 지어내지 않았는가"]},"explanation":["고운 말.","이야기를 든 까닭.","이야기에 있는 내용."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#1','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 수빈이가 감자를 캔 때는 언제인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],true,'{"seq":1,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이가 감자를 캔 때는 언제인가요?","options":[{"t":"지난 토요일","correct":true},{"t":"어제 저녁","mis":"K2-1-u7-X05"},{"t":"다음 주 일요일","mis":"K2-1-u7-X04"}],"explanation":["수빈이는 「지난 토요일에」 감자를 캤다고 했어요.","어제 저녁은 준우가 연을 날린 때예요.","다음 주 일요일은 발표에 없어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"},"variant_rule":{"alt":[{"stem":"발표를 읽고 답해 보세요. 준우가 연을 날린 곳은 어디인가요?","options":[{"t":"동네 공원","correct":true},{"t":"할머니 댁 텃밭","mis":"K2-1-u7-X05"},{"t":"바닷가","mis":"K2-1-u7-X04"}],"explanation":["준우는 「동네 공원에서」 연을 날렸다고 했어요.","할머니 댁 텃밭은 수빈이가 감자를 캔 곳이에요.","바닷가는 발표에 없어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#2','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C6',1,'mc','auto','발표할 때 바른 자세로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X10']::text[],true,'{"seq":2,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"발표할 때 바른 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람을 골고루 바라보며 말해요","correct":true},{"t":"바닥만 보며 말해요","mis":"K2-1-u7-X10"},{"t":"몸을 이리저리 흔들며 말해요","mis":"K2-1-u7-X10"}],"explanation":["듣는 사람을 바라보면 내 말이 잘 전해져요.","바닥만 보면 목소리가 작아지고 마음이 전해지지 않아요.","몸을 흔들면 듣는 사람이 집중하기 어려워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표할 때 바른 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"말끝까지 또박또박 말해요","correct":true},{"t":"말끝을 흐리며 작게 말해요","mis":"K2-1-u7-X10"},{"t":"발표 종이로 얼굴을 가리고 말해요","mis":"K2-1-u7-X10"}],"explanation":["말끝까지 또박또박 말해야 잘 들려요.","말끝을 흐리면 무슨 말인지 알기 어려워요.","얼굴을 가리면 목소리가 막혀요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#3','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',1,'ox','auto','경험을 발표할 때에는 한 일만 말하고 그때의 생각이나 느낌은 말하지 않아요.',ARRAY['K2-1-u7-X08']::text[],true,'{"seq":3,"concept":"K2-1-u7-C5","difficulty":1,"kind":"ox","stem":"경험을 발표할 때에는 한 일만 말하고 그때의 생각이나 느낌은 말하지 않아요.","answer":"X","reason_options":[{"t":"생각이나 느낌을 함께 말해야 경험이 잘 전해지니까","correct":true},{"t":"느낌은 듣는 사람에게 필요 없으니까","mis":"K2-1-u7-X08"}],"mis":"K2-1-u7-X08","explanation":["경험에는 겪은 일과 그때의 생각이나 느낌이 함께 들어가요.","느낌을 말하면 듣는 사람이 내 마음을 알 수 있어요.","언제 · 어디서 · 무슨 일 · 느낌을 확인해요."],"variant_rule":{"alt":[{"stem":"경험에는 내가 한 일, 본 일, 들은 일이 모두 들어갈 수 있어요.","answer":"O","reason_options":[{"t":"겪은 일은 한 일·본 일·들은 일을 모두 말하니까","correct":true},{"t":"경험에는 내가 한 일만 들어가니까","mis":"K2-1-u7-X08"}],"explanation":["본 일과 들은 일도 내 경험이에요.","그때의 생각이나 느낌도 함께 말해요.","언제 · 어디서 · 무슨 일 · 느낌을 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#4','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C6',1,'mc','auto','친구의 발표를 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u7-X11']::text[],true,'{"seq":4,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"친구의 발표를 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"발표하는 친구를 바라보며 끝까지 들어요","correct":true},{"t":"짝과 이야기하며 들어요","mis":"K2-1-u7-X11"},{"t":"중간에 「틀렸어!」 하고 끼어들어요","mis":"K2-1-u7-X11"}],"explanation":["친구를 바라보며 끝까지 들으면 친구가 힘이 나요.","짝과 이야기하면 발표를 놓쳐요.","끼어들면 발표하는 친구가 당황해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구의 발표를 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"궁금한 것은 발표가 끝난 뒤 손을 들고 물어봐요","correct":true},{"t":"궁금하면 바로 소리쳐 물어봐요","mis":"K2-1-u7-X11"},{"t":"책상에 엎드려 들어요","mis":"K2-1-u7-X11"}],"explanation":["발표가 끝난 뒤 손을 들고 물어봐요.","중간에 소리치면 발표가 끊겨요.","엎드리면 친구가 잘 듣고 있는지 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#5','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',2,'match','auto','발표를 읽고 발표 내용과 그 내용을 묻는 질문을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C5","difficulty":2,"kind":"match","stem":"발표를 읽고 발표 내용과 그 내용을 묻는 질문을 알맞게 이어 보세요.","pairs":[{"l":"지난 토요일","r":"언제?"},{"l":"할머니 댁 텃밭","r":"어디에서?"},{"l":"감자를 캤다","r":"무슨 일?"},{"l":"깜짝 놀랐다","r":"어떤 느낌?"}],"mis":"K2-1-u7-X09","explanation":["「지난 토요일」은 언제, 「할머니 댁 텃밭」은 어디에서예요.","「감자를 캤다」는 무슨 일이에요.","「깜짝 놀랐다」는 그때의 느낌이에요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표를 읽고 발표 내용과 그 내용을 묻는 질문을 알맞게 이어 보세요.","pairs":[{"l":"어제 저녁","r":"언제?"},{"l":"동네 공원","r":"어디에서?"},{"l":"연을 날렸다","r":"무슨 일?"},{"l":"정말 신났다","r":"어떤 느낌?"}],"explanation":["「어제 저녁」은 언제, 「동네 공원」은 어디에서예요.","「연을 날렸다」는 무슨 일이에요.","「정말 신났다」는 그때의 느낌이에요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#6','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],true,'{"seq":6,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"생각보다 감자가 많이 나와서 깜짝 놀랐어요.","correct":true},{"t":"저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","mis":"K2-1-u7-X06"},{"t":"호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","mis":"K2-1-u7-X06"}],"explanation":["「깜짝 놀랐어요」에 수빈이의 느낌이 드러나요.","언제·어디서 무슨 일을 했는지 말한 문장이에요.","감자를 캔 모습을 말한 문장이에요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"},"variant_rule":{"alt":[{"stem":"발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","correct":true},{"t":"저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","mis":"K2-1-u7-X06"},{"t":"바람이 세게 불자 연이 하늘 높이 올라갔어요.","mis":"K2-1-u7-X06"}],"explanation":["「정말 신났어요」에 준우의 느낌이 드러나요.","언제·어디서 무슨 일을 했는지 말한 문장이에요.","연이 올라간 모습을 말한 문장이에요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#7','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C6',2,'error','auto','발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?',ARRAY['K2-1-u7-X10','K2-1-u7-X18']::text[],true,'{"seq":7,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?","options":[{"t":"지우 — 친구들을 보지 않고 창밖만 보며 말했어요.","correct":true,"mis_target":"K2-1-u7-X10"},{"t":"윤호 — 모두에게 들리게 알맞은 크기로 말했어요.","mis":"K2-1-u7-X18"},{"t":"채원 — 바르게 서서 듣는 사람을 보며 말했어요.","mis":"K2-1-u7-X18"}],"explanation":["창밖만 보면 듣는 사람과 마음이 이어지지 않아요.","윤호와 채원이는 바르게 발표했어요.","듣는 사람을 바라보며 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?","options":[{"t":"서준 — 너무 작은 목소리로 웅얼웅얼 말했어요.","correct":true,"mis_target":"K2-1-u7-X10"},{"t":"아린 — 말끝까지 또박또박 분명하게 말했어요.","mis":"K2-1-u7-X18"},{"t":"하람 — 발표 전에 짝과 마주 보며 연습했어요.","mis":"K2-1-u7-X18"}],"explanation":["웅얼웅얼 작게 말하면 친구들이 듣기 어려워요.","아린이와 하람이는 바르게 했어요.","맨 뒤 친구도 들리게 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#8','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',2,'mc','auto','경험을 발표하려고 내용을 정리할 때 들어갈 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],true,'{"seq":8,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"경험을 발표하려고 내용을 정리할 때 들어갈 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 전화번호","correct":true},{"t":"언제 있었던 일인지","mis":"K2-1-u7-X18"},{"t":"그때의 생각이나 느낌","mis":"K2-1-u7-X18"}],"explanation":["친구의 전화번호는 내 경험과 상관없어요.","언제와 그때의 느낌은 꼭 들어가야 해요.","물음의 「않은」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 경험을 발표하려고 내용을 정리할 때 들어갈 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"옆 반 친구의 받아쓰기 점수","correct":true},{"t":"어디에서 있었던 일인지","mis":"K2-1-u7-X18"},{"t":"무슨 일이 있었는지","mis":"K2-1-u7-X18"}],"explanation":["옆 반 친구의 점수는 내 경험과 상관없어요.","어디서·무슨 일은 꼭 들어가야 해요.","물음의 「않은」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#9','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',2,'blank','auto','발표를 읽고 답해 보세요. 준우의 발표를 짧게 정리했어요. 「준우는 (     ) 동네 공원에서 연을 날렸고, 정말 신났다.」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],true,'{"seq":9,"concept":"K2-1-u7-C5","difficulty":2,"kind":"blank","stem":"발표를 읽고 답해 보세요. 준우의 발표를 짧게 정리했어요. 「준우는 (     ) 동네 공원에서 연을 날렸고, 정말 신났다.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"어제 저녁에","correct":true},{"t":"지난 토요일에","mis":"K2-1-u7-X05"},{"t":"다음 주에","mis":"K2-1-u7-X04"}],"explanation":["준우는 어제 저녁에 연을 날렸어요.","지난 토요일은 수빈이의 발표에 나온 때예요.","다음 주는 발표에 없어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"},"variant_rule":{"alt":[{"stem":"발표를 읽고 답해 보세요. 수빈이의 발표를 짧게 정리했어요. 「수빈이는 지난 토요일에 할머니 댁 텃밭에서 (     ) 깜짝 놀랐다.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"감자를 캐다가","correct":true},{"t":"연을 날리다가","mis":"K2-1-u7-X05"},{"t":"고구마를 심다가","mis":"K2-1-u7-X04"}],"explanation":["수빈이는 감자를 캐다가 감자가 많아 놀랐어요.","연날리기는 준우의 경험이에요.","고구마를 심었다는 말은 없어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#10','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',3,'mc','auto','「나는 놀이터에서 그네를 탔다. 미끄럼틀도 탔다. 시소도 탔다.」 이 발표에 더 넣으면 좋을 내용은 어느 것인가요?',ARRAY['K2-1-u7-X08']::text[],true,'{"seq":10,"concept":"K2-1-u7-C5","difficulty":3,"kind":"mc","stem":"「나는 놀이터에서 그네를 탔다. 미끄럼틀도 탔다. 시소도 탔다.」 이 발표에 더 넣으면 좋을 내용은 어느 것인가요?","options":[{"t":"언제 탔는지와 그때의 느낌","correct":true},{"t":"그네·미끄럼틀·시소를 또 탄 이야기","mis":"K2-1-u7-X08"},{"t":"놀이터 옆 가게의 이름","mis":"K2-1-u7-X08"}],"explanation":["언제와 그때의 느낌이 빠져 있어요.","한 일만 더 늘어놓으면 발표가 자세해지지 않아요.","가게 이름은 경험과 상관없어요."],"variant_rule":{"alt":[{"stem":"「나는 할머니 댁에 갔다. 재미있었다.」 이 발표를 더 자세하게 하려면 무엇을 더 넣으면 좋을까요?","options":[{"t":"언제 갔는지와 할머니 댁에서 무슨 일을 했는지","correct":true},{"t":"「재미있었다」를 세 번 더 말하기","mis":"K2-1-u7-X08"},{"t":"할머니 댁 전화번호","mis":"K2-1-u7-X08"}],"explanation":["언제와 무슨 일이 빠져 있어요.","같은 말을 되풀이한다고 자세해지지 않아요.","전화번호는 경험과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#1','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',2,'mc','auto','발표하기 전에 하면 좋은 일은 어느 것인가요?',ARRAY['K2-1-u7-X08','K2-1-u7-X10']::text[],false,'{"seq":1,"concept":"K2-1-u7-C6","difficulty":2,"kind":"mc","stem":"발표하기 전에 하면 좋은 일은 어느 것인가요?","options":[{"t":"거울을 보거나 짝과 마주 보며 미리 연습해요","correct":true},{"t":"발표 내용을 하나도 정하지 않아요","mis":"K2-1-u7-X08"},{"t":"발표 종이로 얼굴을 가리는 연습을 해요","mis":"K2-1-u7-X10"}],"explanation":["미리 연습하면 자신 있게 발표할 수 있어요.","내용을 정하지 않으면 무엇을 말할지 몰라요.","얼굴을 가리면 목소리가 막혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#2','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 「다음에는 더 큰 연을 만들어 날리고 싶어요.」는 무엇을 말한 것인가요?',ARRAY['K2-1-u7-X09']::text[],false,'{"seq":2,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 「다음에는 더 큰 연을 만들어 날리고 싶어요.」는 무엇을 말한 것인가요?","options":[{"t":"앞으로 하고 싶은 생각","correct":true},{"t":"연을 날린 곳","mis":"K2-1-u7-X09"},{"t":"연을 날린 때","mis":"K2-1-u7-X09"}],"explanation":["앞으로 하고 싶은 생각을 말했어요.","연을 날린 곳은 「동네 공원」이에요.","연을 날린 때는 「어제 저녁」이에요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#3','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',3,'error','auto','발표를 읽고 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X18']::text[],false,'{"seq":3,"concept":"K2-1-u7-C5","difficulty":3,"kind":"error","stem":"발표를 읽고 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"민지 — 「어디에서: 수빈이네 집 마당」","correct":true,"mis_target":"K2-1-u7-X04"},{"t":"도담 — 「언제: 지난 토요일」","mis":"K2-1-u7-X18"},{"t":"현우 — 「느낌: 감자가 많이 나와 깜짝 놀랐다」","mis":"K2-1-u7-X18"}],"explanation":["수빈이는 할머니 댁 텃밭에서 감자를 캤어요.","도담이와 현우는 바르게 정리했어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#4','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',3,'mc','auto','발표할 때 알맞은 목소리 크기는 어느 것인가요?',ARRAY['K2-1-u7-X10']::text[],false,'{"seq":4,"concept":"K2-1-u7-C6","difficulty":3,"kind":"mc","stem":"발표할 때 알맞은 목소리 크기는 어느 것인가요?","options":[{"t":"교실 맨 뒤에 앉은 친구도 잘 들을 수 있는 크기","correct":true},{"t":"짝만 겨우 들을 수 있는 작은 소리","mis":"K2-1-u7-X10"},{"t":"옆 반까지 들릴 만큼 소리치는 소리","mis":"K2-1-u7-X10"}],"explanation":["맨 뒤 친구까지 들리면 모두가 들을 수 있어요.","너무 작으면 멀리 앉은 친구가 못 들어요.","소리치면 듣는 사람이 불편해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#5','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',3,'ox','auto','「저는 어제 학교에서 공부를 했어요.」만 말하면 경험을 자세하게 발표한 것이에요.',ARRAY['K2-1-u7-X08']::text[],false,'{"seq":5,"concept":"K2-1-u7-C5","difficulty":3,"kind":"ox","stem":"「저는 어제 학교에서 공부를 했어요.」만 말하면 경험을 자세하게 발표한 것이에요.","answer":"X","reason_options":[{"t":"무슨 공부를 했는지, 그때 어떤 느낌이었는지가 빠졌으니까","correct":true},{"t":"언제와 어디만 있으면 발표는 다 된 것이니까","mis":"K2-1-u7-X08"}],"mis":"K2-1-u7-X08","explanation":["무슨 일을 했는지 자세히 말하지 않았어요.","그때의 생각이나 느낌도 빠졌어요.","네 손가락을 꼽으며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#6','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',3,'mc','auto','경험 발표의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X08']::text[],false,'{"seq":6,"concept":"K2-1-u7-C5","difficulty":3,"kind":"mc","stem":"경험 발표의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「처음으로 혼자 버스를 타 본 날」","correct":true},{"t":"「공룡의 종류」","mis":"K2-1-u7-X08"},{"t":"「내가 좋아하는 색깔」","mis":"K2-1-u7-X08"}],"explanation":["내가 직접 겪은 일이라 경험 발표에 알맞아요.","공룡의 종류는 겪은 일이 아니라 알려 주는 내용이에요.","좋아하는 색깔은 겪은 일이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#7','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',3,'mc','auto','발표를 읽고 답해 보세요. 수빈이의 발표가 끝난 뒤 듣는 사람이 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X11']::text[],false,'{"seq":7,"concept":"K2-1-u7-C6","difficulty":3,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이의 발표가 끝난 뒤 듣는 사람이 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「감자가 줄줄이 나왔다니 신기하다. 캔 감자로 무엇을 해 먹었어?」","correct":true},{"t":"「그게 다야? 재미없어.」","mis":"K2-1-u7-X11"},{"t":"「나는 감자 싫어.」","mis":"K2-1-u7-X11"}],"explanation":["잘 들었다는 마음을 전하고 궁금한 점을 물었어요.","「재미없어」는 발표한 친구의 마음을 상하게 해요.","내가 싫어하는 것만 말하면 바르게 들은 게 아니에요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#8','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',4,'mc','auto','발표를 읽고 답해 보세요. 준우의 발표를 더 생생하게 고치려고 해요. 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K2-1-u7-X08']::text[],false,'{"seq":8,"concept":"K2-1-u7-C5","difficulty":4,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우의 발표를 더 생생하게 고치려고 해요. 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"연이 올라갈 때 무엇이 보였는지, 동생은 어떤 표정이었는지를 덧붙인다","correct":true},{"t":"「정말 신났어요」를 빼고 한 일만 남긴다","mis":"K2-1-u7-X08"},{"t":"연의 값이 얼마인지 덧붙인다","mis":"K2-1-u7-X08"}],"explanation":["본 일과 동생의 모습을 더하면 더 생생해져요.","느낌을 빼면 마음이 전해지지 않아요.","연의 값은 경험을 생생하게 하지 않아요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#9','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',4,'essay','teacher','기억에 남는 내 경험을 하나 골라, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"기억에 남는 내 경험을 하나 골라, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 저는 지난여름에 바닷가에서 가족과 모래성을 쌓았어요. 파도가 밀려와 모래성이 무너져서 아쉬웠지만 다시 쌓으니 더 크고 멋지게 되었어요. 다음에도 또 가고 싶어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#10','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',4,'essay','teacher','친구가 발표할 때 바닥만 보고 작은 목소리로 말끝을 흐렸어요. 친구에게 도움이 되도록 바른 발표 자세를 두 가지 이상 고운 말로 알려 주는 말을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C6","difficulty":4,"kind":"essay","stem":"친구가 발표할 때 바닥만 보고 작은 목소리로 말끝을 흐렸어요. 친구에게 도움이 되도록 바른 발표 자세를 두 가지 이상 고운 말로 알려 주는 말을 써 보세요.","answer_guide":{"answer":"예: 「네 이야기 정말 재미있었어. 다음엔 우리를 바라보면서 조금만 더 크게, 말끝까지 또박또박 말해 주면 더 잘 들릴 것 같아. 나도 같이 연습해 줄게.」","scoring_points":["바른 발표 자세를 두 가지 이상 썼는가","친구의 마음을 생각한 고운 말로 썼는가","칭찬이나 응원을 함께 썼는가"]},"explanation":["바른 자세 두 가지.","고운 말.","칭찬이나 응원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#1','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C7',1,'mc','auto','대화를 읽고 답해 보세요. 옷에 우유가 튀었을 때 태민이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],true,'{"seq":1,"concept":"K2-1-u7-C7","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 옷에 우유가 튀었을 때 태민이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"깜짝 놀라고 속상했다","correct":true},{"t":"신나고 즐거웠다","mis":"K2-1-u7-X13"},{"t":"고맙고 뿌듯했다","mis":"K2-1-u7-X13"}],"explanation":["「앗」 하며 놀랐고 옷이 더러워져 속상했을 거예요.","옷에 우유가 튀어 신날 까닭이 없어요.","고맙거나 뿌듯할 일도 아니에요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 「왜 내 앞에 끼어드는 거야?」라고 말할 때 하람이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"억울하고 화가 났다","correct":true},{"t":"기쁘고 설렜다","mis":"K2-1-u7-X13"},{"t":"미안하고 부끄러웠다","mis":"K2-1-u7-X05"}],"explanation":["줄을 서 있는데 누가 앞에 끼어들어 억울했어요.","기쁠 까닭이 없어요.","미안한 마음은 이때 지호에게 더 어울려요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#2','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',1,'mc','auto','대화를 읽고 답해 보세요. 은솔이가 자기 잘못을 알고 한 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],true,'{"seq":2,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 은솔이가 자기 잘못을 알고 한 고운 말은 어느 것인가요?","options":[{"t":"「미안해.」","correct":true},{"t":"「고마워.」","mis":"K2-1-u7-X02"},{"t":"「축하해.」","mis":"K2-1-u7-X02"}],"explanation":["잘못했을 때는 「미안해.」라고 해요.","「고마워.」는 도움을 받았을 때 하는 말이에요.","「축하해.」는 기쁜 일에 하는 말이에요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 민지가 도움을 받고 한 고운 말은 어느 것인가요?","options":[{"t":"「고마워, 현우야.」","correct":true},{"t":"「미안해, 현우야.」","mis":"K2-1-u7-X02"},{"t":"「저리 가, 현우야.」","mis":"K2-1-u7-X03"}],"explanation":["도움을 받았을 때는 「고마워.」라고 해요.","「미안해.」는 잘못했을 때 하는 말이에요.","「저리 가」는 거친 말이에요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"물뿌리개가 너무 무거워서 팔이 아파."},{"who":"현우","text":"내가 같이 들어 줄게. 한쪽을 잡을게."},{"who":"민지","text":"고마워, 현우야. 한결 가벼워졌어."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#3','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',1,'ox','auto','친구가 일부러 그런 것이 아닐 때에는 「괜찮아.」라고 말해 주면 좋아요.',ARRAY['K2-1-u7-X12']::text[],true,'{"seq":3,"concept":"K2-1-u7-C8","difficulty":1,"kind":"ox","stem":"친구가 일부러 그런 것이 아닐 때에는 「괜찮아.」라고 말해 주면 좋아요.","answer":"O","reason_options":[{"t":"친구의 미안한 마음을 헤아려 주는 말이니까","correct":true},{"t":"일부러 안 했어도 꼭 화를 내야 하니까","mis":"K2-1-u7-X12"}],"mis":"K2-1-u7-X12","explanation":["「괜찮아.」는 친구의 미안한 마음을 덜어 줘요.","일부러 한 일이 아니면 탓하지 않아요.","「일부러 그랬을까?」 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"내가 실수로 친구를 밀쳤을 때에는 모른 척하고 지나가요.","answer":"X","reason_options":[{"t":"「미안해. 괜찮아?」 하고 친구의 마음을 살펴야 하니까","correct":true},{"t":"일부러 민 게 아니면 말하지 않아도 되니까","mis":"K2-1-u7-X12"}],"explanation":["실수라도 친구는 아프고 놀랐을 수 있어요.","「미안해. 괜찮아?」 하고 살펴요.","친구의 마음을 먼저 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#4','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',1,'mc','auto','웃어른께 도움을 받았을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],true,'{"seq":4,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"웃어른께 도움을 받았을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「고맙습니다.」","correct":true},{"t":"「죄송합니다.」","mis":"K2-1-u7-X02"},{"t":"「안녕히 계세요.」","mis":"K2-1-u7-X02"}],"explanation":["도움을 받았을 때는 「고맙습니다.」라고 해요.","「죄송합니다.」는 잘못했을 때 하는 말이에요.","「안녕히 계세요.」는 헤어질 때 하는 인사예요."],"variant_rule":{"alt":[{"stem":"웃어른께 잘못을 했을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「죄송해요.」","correct":true},{"t":"「고맙습니다.」","mis":"K2-1-u7-X02"},{"t":"「축하해요.」","mis":"K2-1-u7-X02"}],"explanation":["잘못했을 때는 「죄송해요.」라고 해요.","「고맙습니다.」는 도움을 받았을 때 하는 말이에요.","「축하해요.」는 기쁜 일에 하는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#5','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',2,'match','auto','상황에 어울리는 고운 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C8","difficulty":2,"kind":"match","stem":"상황에 어울리는 고운 말을 알맞게 이어 보세요.","pairs":[{"l":"물뿌리개가 무거워 힘든 친구","r":"내가 같이 들어 줄게."},{"l":"줄에 잘못 끼어든 나","r":"미안해, 뒤로 갈게."},{"l":"우유를 쏟아 당황한 친구","r":"괜찮아, 같이 닦자."}],"mis":"K2-1-u7-X02","explanation":["힘든 친구에게는 돕겠다고 해요.","잘못한 나는 사과하고 바로잡아요.","당황한 친구에게는 괜찮다고 해 줘요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 어울리는 고운 말을 알맞게 이어 보세요.","pairs":[{"l":"생일을 맞은 친구","r":"생일 축하해!"},{"l":"준비물을 빌려준 친구","r":"빌려줘서 고마워."},{"l":"발표를 앞두고 떨리는 친구","r":"천천히 하면 돼. 힘내!"}],"explanation":["기쁜 날에는 축하해요.","도움을 받으면 고맙다고 해요.","떨리는 친구에게는 힘을 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#6','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 지호가 줄에 끼어든 까닭은 무엇인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X04']::text[],true,'{"seq":6,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 지호가 줄에 끼어든 까닭은 무엇인가요?","options":[{"t":"줄이 어디까지인지 몰라서","correct":true},{"t":"하람이를 골탕 먹이려고","mis":"K2-1-u7-X12"},{"t":"줄 서기가 싫어서","mis":"K2-1-u7-X04"}],"explanation":["지호는 「줄이 여기까지인 줄 몰랐어.」라고 했어요.","일부러 골탕 먹이려 한 것이 아니에요.","줄 서기가 싫다는 말은 없어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 은솔이가 우유를 튀긴 까닭은 무엇인가요?","options":[{"t":"손이 미끄러져서","correct":true},{"t":"태민이를 골탕 먹이려고","mis":"K2-1-u7-X12"},{"t":"우유가 맛이 없어서","mis":"K2-1-u7-X04"}],"explanation":["은솔이는 「손이 미끄러졌어.」라고 했어요.","일부러 한 일이 아니에요.","우유 맛 이야기는 없어요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#7','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',2,'mc','auto','대화를 읽고 답해 보세요. 하람이가 마지막에 한 말이 고운 말인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],true,'{"seq":7,"concept":"K2-1-u7-C8","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하람이가 마지막에 한 말이 고운 말인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"지호의 마음을 헤아리고 자기 잘못도 사과했으니까","correct":true},{"t":"지호를 이겨서 기분이 좋으니까","mis":"K2-1-u7-X12"},{"t":"목소리를 크게 냈으니까","mis":"K2-1-u7-X03"}],"explanation":["「헷갈렸겠다」며 지호의 마음을 헤아렸어요.","큰 소리 낸 자기 잘못도 사과했어요.","이기고 지는 일이 아니에요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 태민이가 「괜찮아. 일부러 그런 거 아니잖아.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"은솔이가 일부러 그런 게 아님을 알고 미안한 마음을 헤아려서","correct":true},{"t":"옷에 우유가 튀어서 기뻐서","mis":"K2-1-u7-X13"},{"t":"은솔이에게 화를 내고 싶어서","mis":"K2-1-u7-X12"}],"explanation":["실수라는 것을 알고 은솔이의 마음을 헤아렸어요.","옷에 우유가 튀어 기쁠 까닭은 없어요.","화를 내고 싶었다면 「괜찮아.」라고 하지 않았을 거예요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#8','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',2,'error','auto','모둠 친구가 실수로 내 색종이를 찢었어요. 친구의 마음을 생각하지 않고 말한 친구는 누구인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X18']::text[],true,'{"seq":8,"concept":"K2-1-u7-C8","difficulty":2,"kind":"error","stem":"모둠 친구가 실수로 내 색종이를 찢었어요. 친구의 마음을 생각하지 않고 말한 친구는 누구인가요?","options":[{"t":"민준 — 「너 때문에 다 망쳤어! 저리 가!」","correct":true,"mis_target":"K2-1-u7-X12"},{"t":"서아 — 「괜찮아, 새 색종이로 다시 하자.」","mis":"K2-1-u7-X18"},{"t":"하윤 — 「일부러 그런 거 아니지? 같이 붙여 보자.」","mis":"K2-1-u7-X18"}],"explanation":["실수한 친구를 탓하며 화난 기분만 쏟아 냈어요.","서아와 하윤이는 친구의 마음을 생각했어요.","「일부러 그랬을까?」 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"친구가 달리다 내 발에 걸려 넘어졌어요. 친구의 마음을 생각하지 않고 말한 친구는 누구인가요?","options":[{"t":"지후 — 「하하, 왜 넘어지고 그래?」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"도담 — 「많이 아프지? 일어날 수 있겠어?」","mis":"K2-1-u7-X18"},{"t":"소율 — 「내 발에 걸렸구나, 미안해.」","mis":"K2-1-u7-X18"}],"explanation":["넘어진 친구를 비웃으면 마음이 더 아파요.","도담이와 소율이는 친구의 마음을 살폈어요.","내가 넘어졌다면 어땠을지 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#9','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 예린이가 「일부러 그런 거 아닌데…….」라고 말할 때의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],true,'{"seq":9,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 예린이가 「일부러 그런 거 아닌데…….」라고 말할 때의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"미안하면서도 억울하다","correct":true},{"t":"신나고 자랑스럽다","mis":"K2-1-u7-X13"},{"t":"블록 탑이 무너져 기쁘다","mis":"K2-1-u7-X13"}],"explanation":["탑을 무너뜨려 미안하지만 일부러가 아니라 억울했을 거예요.","자랑스러울 일이 아니에요.","탑이 무너져 기쁠 까닭이 없어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 도윤이가 「몰라, 저리 가!」라고 했을 때 예린이의 마음은 어떠했을까요?","options":[{"t":"서운하고 슬펐을 것이다","correct":true},{"t":"기쁘고 고마웠을 것이다","mis":"K2-1-u7-X13"},{"t":"뿌듯하고 즐거웠을 것이다","mis":"K2-1-u7-X13"}],"explanation":["사과하려던 예린이는 「저리 가!」를 듣고 서운했을 거예요.","기쁘거나 고마울 까닭이 없어요.","내가 예린이라면 어땠을지 생각해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#10','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',3,'mc','auto','대화를 읽고 답해 보세요. 도윤이가 예린이의 마음을 생각하며 고운 말로 다시 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],true,'{"seq":10,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이가 예린이의 마음을 생각하며 고운 말로 다시 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「탑이 무너져서 속상해. 그래도 일부러 그런 건 아니지? 같이 다시 쌓자.」","correct":true},{"t":"「몰라, 다시는 내 근처에 오지 마.」","mis":"K2-1-u7-X12"},{"t":"「탑을 무너뜨려 줘서 고마워.」","mis":"K2-1-u7-X02"}],"explanation":["내 속상한 마음을 말하면서 예린이의 마음도 헤아렸어요.","더 거칠게 말하면 다툼이 커져요.","고마운 일이 아니니 「고마워.」는 맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 예린이가 도윤이의 마음을 생각하며 할 고운 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「열심히 쌓은 탑이 무너져서 속상하지? 미안해. 내가 같이 쌓아 줄게.」","correct":true},{"t":"「겨우 블록 가지고 왜 그래?」","mis":"K2-1-u7-X03"},{"t":"「축하해, 다시 쌓을 수 있겠다!」","mis":"K2-1-u7-X02"}],"explanation":["도윤이의 속상한 마음을 헤아리고 사과했어요.","「겨우 블록 가지고」는 도윤이의 마음을 무시하는 말이에요.","축하할 일이 아니에요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#1','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',2,'mc','auto','친구가 발표를 하다가 내용을 잊어버려 얼굴이 빨개졌어요. 친구의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":1,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"친구가 발표를 하다가 내용을 잊어버려 얼굴이 빨개졌어요. 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"당황스럽고 부끄럽다","correct":true},{"t":"자랑스럽고 신난다","mis":"K2-1-u7-X13"},{"t":"고맙고 뿌듯하다","mis":"K2-1-u7-X13"}],"explanation":["발표 중에 내용을 잊으면 당황스럽고 부끄러워요.","자랑스러울 상황이 아니에요.","내가 그 친구라면 어땠을지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#2','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',2,'mc','auto','친구의 마음을 생각하며 고운 말로 대화할 때 먼저 할 일은 어느 것인가요?',ARRAY['K2-1-u7-X12']::text[],false,'{"seq":2,"concept":"K2-1-u7-C8","difficulty":2,"kind":"mc","stem":"친구의 마음을 생각하며 고운 말로 대화할 때 먼저 할 일은 어느 것인가요?","options":[{"t":"친구가 지금 어떤 마음일지 생각해 본다","correct":true},{"t":"내가 하고 싶은 말을 바로 크게 말한다","mis":"K2-1-u7-X12"},{"t":"친구가 잘못한 점부터 찾는다","mis":"K2-1-u7-X12"}],"explanation":["마음을 먼저 생각하면 알맞은 고운 말이 떠올라요.","내 기분대로만 말하면 다투기 쉬워요.","잘못부터 따지면 친구가 속상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#3','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',3,'error','auto','대화를 읽고 친구들이 이야기를 나눴어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X18']::text[],false,'{"seq":3,"concept":"K2-1-u7-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 친구들이 이야기를 나눴어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「현우는 민지에게 미안해서 물뿌리개를 같이 들어 주었어.」","correct":true,"mis_target":"K2-1-u7-X04"},{"t":"채원 — 「민지는 물뿌리개가 무거워서 팔이 아팠어.」","mis":"K2-1-u7-X18"},{"t":"지안 — 「민지는 도움을 받고 고맙다고 말했어.」","mis":"K2-1-u7-X18"}],"explanation":["현우가 미안했다는 말은 대화에 없어요. 힘든 민지를 도와준 거예요.","채원이와 지안이는 대화와 같게 말했어요.","대화에서 그 말을 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"물뿌리개가 너무 무거워서 팔이 아파."},{"who":"현우","text":"내가 같이 들어 줄게. 한쪽을 잡을게."},{"who":"민지","text":"고마워, 현우야. 한결 가벼워졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#4','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',3,'mc','auto','쉬는 시간에 전학 온 친구가 혼자 앉아 있어요. 친구의 마음을 생각하며 한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X13']::text[],false,'{"seq":4,"concept":"K2-1-u7-C7","difficulty":3,"kind":"mc","stem":"쉬는 시간에 전학 온 친구가 혼자 앉아 있어요. 친구의 마음을 생각하며 한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「우리랑 같이 놀래? 놀이 방법 알려 줄게.」","correct":true},{"t":"「왜 혼자 있어? 친구 없어?」","mis":"K2-1-u7-X03"},{"t":"「혼자 있는 게 좋은가 보네.」 하고 지나간다","mis":"K2-1-u7-X13"}],"explanation":["낯설어 외로울 친구의 마음을 헤아려 함께하자고 했어요.","「친구 없어?」는 친구의 마음을 아프게 해요.","혼자가 좋을 거라고 멋대로 짐작하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#5','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',3,'ox','auto','「미안해.」라는 말은 크게 잘못했을 때에만 하는 말이에요.',ARRAY['K2-1-u7-X12']::text[],false,'{"seq":5,"concept":"K2-1-u7-C8","difficulty":3,"kind":"ox","stem":"「미안해.」라는 말은 크게 잘못했을 때에만 하는 말이에요.","answer":"X","reason_options":[{"t":"작은 실수라도 상대가 불편했다면 미안하다고 말해야 하니까","correct":true},{"t":"작은 실수는 상대의 마음과 상관없으니까","mis":"K2-1-u7-X12"}],"mis":"K2-1-u7-X12","explanation":["작은 실수도 상대는 불편할 수 있어요.","「미안해.」 한마디가 마음을 풀어 줘요.","상대의 마음을 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#6','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',3,'mc','auto','대화를 읽고 답해 보세요. 은솔이의 말 「내가 휴지 가져다줄게.」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 은솔이의 말 「내가 휴지 가져다줄게.」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"잘못을 바로잡으려는 마음","correct":true},{"t":"태민이를 놀리려는 마음","mis":"K2-1-u7-X13"},{"t":"자기를 자랑하려는 마음","mis":"K2-1-u7-X13"}],"explanation":["사과에 그치지 않고 잘못을 바로잡으려 했어요.","놀리려는 마음은 대화에 드러나지 않아요.","자랑하려는 말이 아니에요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#7','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',3,'mc','auto','친구가 「네 덕분에 숙제를 끝냈어. 고마워!」라고 했어요. 대답할 고운 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X02']::text[],false,'{"seq":7,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 「네 덕분에 숙제를 끝냈어. 고마워!」라고 했어요. 대답할 고운 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「도움이 되었다니 나도 기뻐.」","correct":true},{"t":"「다음엔 너 혼자 해.」","mis":"K2-1-u7-X03"},{"t":"「미안해.」","mis":"K2-1-u7-X02"}],"explanation":["고맙다는 말에 기쁜 마음으로 대답했어요.","「너 혼자 해.」는 친구의 마음을 서운하게 해요.","잘못한 일이 없으니 「미안해.」는 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#8','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',4,'mc','auto','대화를 읽고 답해 보세요. 하람이와 지호의 대화가 다투지 않고 끝날 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X04']::text[],false,'{"seq":8,"concept":"K2-1-u7-C7","difficulty":4,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하람이와 지호의 대화가 다투지 않고 끝날 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지호가 바로 사과하고, 하람이도 지호의 마음을 헤아려 자기 잘못을 사과해서","correct":true},{"t":"하람이가 큰 소리로 끝까지 따져서","mis":"K2-1-u7-X12"},{"t":"지호가 줄에서 빠져 집으로 가 버려서","mis":"K2-1-u7-X04"}],"explanation":["두 사람 모두 상대의 마음을 생각하며 고운 말로 대화했어요.","끝까지 따졌다면 다툼이 커졌을 거예요.","지호는 뒤로 가겠다고 했어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#9','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',4,'essay','teacher','친구와 다툴 뻔했던 일을 하나 떠올려 그때 친구의 마음을 짐작해 쓰고, 친구의 마음을 생각하며 고운 말로 대화하는 장면을 두세 줄의 대화로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"친구와 다툴 뻔했던 일을 하나 떠올려 그때 친구의 마음을 짐작해 쓰고, 친구의 마음을 생각하며 고운 말로 대화하는 장면을 두세 줄의 대화로 써 보세요.","answer_guide":{"answer":"예: 짝이 내 필통을 떨어뜨렸어요. 짝은 당황하고 미안했을 거예요. 짝 — 「앗, 미안해. 내가 주워 줄게.」 나 — 「괜찮아, 일부러 그런 거 아니잖아. 같이 줍자.」","scoring_points":["다툴 뻔했던 일을 썼는가","친구의 마음을 짐작해 썼는가","상황에 맞는 고운 말로 대화를 썼는가"]},"explanation":["있었던 일.","친구의 마음.","고운 말 대화."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#10','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',4,'essay','teacher','대화를 읽고 답해 보세요. 도윤이와 예린이의 마음을 각각 짐작해 쓰고, 두 사람이 고운 말로 다시 대화하도록 대화를 고쳐 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C7","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 도윤이와 예린이의 마음을 각각 짐작해 쓰고, 두 사람이 고운 말로 다시 대화하도록 대화를 고쳐 써 보세요.","answer_guide":{"answer":"예: 도윤이는 열심히 쌓은 탑이 무너져 속상했고, 예린이는 미안하면서도 억울했을 거예요. 도윤 — 「탑이 무너져서 속상해.」 예린 — 「미안해. 일부러 그런 건 아니야. 같이 다시 쌓자.」 도윤 — 「그래, 같이 쌓자.」","scoring_points":["도윤이의 마음을 짐작해 썼는가","예린이의 마음을 짐작해 썼는가","두 사람이 고운 말로 대화하도록 고쳐 썼는가"]},"explanation":["도윤이의 마음.","예린이의 마음.","고운 말 대화."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#1','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',1,'mc','auto','이야기를 읽고 답해 보세요. 웅덩이에 빠진 도토리를 건져 준 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],true,'{"seq":1,"concept":"K2-1-u7-C9","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 웅덩이에 빠진 도토리를 건져 준 인물은 누구인가요?","options":[{"t":"거북 할아버지","correct":true},{"t":"토리","mis":"K2-1-u7-X05"},{"t":"토끼 아주머니","mis":"K2-1-u7-X04"}],"explanation":["거북 할아버지가 엉금엉금 다가와 건져 주었어요.","토리는 도토리를 빠뜨린 인물이에요.","토끼 아주머니는 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 나뭇가지에 걸린 풍선 줄을 잡아 준 인물은 누구인가요?","options":[{"t":"건우 형","correct":true},{"t":"하윤","mis":"K2-1-u7-X05"},{"t":"놀이공원 아저씨","mis":"K2-1-u7-X04"}],"explanation":["건우 형이 깡충 뛰어올라 잡아 주었어요.","하윤이는 풍선을 놓친 인물이에요.","놀이공원 아저씨는 풍선을 잡아 주지 않았어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#2','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',1,'mc','auto','이야기를 읽고 답해 보세요. 도토리가 웅덩이에 빠졌을 때 토리의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],true,'{"seq":2,"concept":"K2-1-u7-C9","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 도토리가 웅덩이에 빠졌을 때 토리의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"슬프고 속상했다","correct":true},{"t":"기쁘고 신났다","mis":"K2-1-u7-X13"},{"t":"고맙고 뿌듯했다","mis":"K2-1-u7-X13"}],"explanation":["토리는 엉엉 울었어요.","겨울에 먹으려고 모은 도토리라 더 속상했어요.","고마운 마음은 할아버지가 건져 준 뒤에 들었어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 풍선이 나뭇가지에 걸렸을 때 하윤이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"시무룩하고 속상했다","correct":true},{"t":"기쁘고 설렜다","mis":"K2-1-u7-X13"},{"t":"자랑스러웠다","mis":"K2-1-u7-X13"}],"explanation":["하윤이는 시무룩해졌어요.","풍선을 놓쳐 속상했어요.","기쁘거나 자랑스러울 까닭이 없어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#3','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',1,'ox','auto','고마운 마음은 말로 전하지 않아도 상대가 저절로 알아요.',ARRAY['K2-1-u7-X15']::text[],true,'{"seq":3,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"고마운 마음은 말로 전하지 않아도 상대가 저절로 알아요.","answer":"X","reason_options":[{"t":"마음은 고운 말로 표현해야 상대에게 잘 전해지니까","correct":true},{"t":"마음은 말하지 않는 것이 더 고운 것이니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["말하지 않으면 상대는 내 마음을 모를 수 있어요.","「고마워.」 한마디로 마음이 전해져요.","누구에게 · 어떤 마음 · 왜를 담아 말해요."],"variant_rule":{"alt":[{"stem":"도움을 받으면 「고마워.」라고 말로 마음을 전하는 것이 좋아요.","answer":"O","reason_options":[{"t":"말로 전하면 도와준 사람의 마음도 따뜻해지니까","correct":true},{"t":"도와준 사람은 고맙다는 말을 싫어하니까","mis":"K2-1-u7-X15"}],"explanation":["고맙다는 말을 들으면 도와준 사람도 기뻐요.","마음은 말로 전해야 잘 알 수 있어요.","누구에게 · 어떤 마음 · 왜를 담아 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#4','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',1,'mc','auto','이야기를 읽고 답해 보세요. 거북 할아버지가 다가오는 모습을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u7-X14']::text[],true,'{"seq":4,"concept":"K2-1-u7-C9","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 거북 할아버지가 다가오는 모습을 흉내 낸 말은 어느 것인가요?","options":[{"t":"엉금엉금","correct":true},{"t":"데굴데굴","mis":"K2-1-u7-X14"},{"t":"퐁당","mis":"K2-1-u7-X14"}],"explanation":["「엉금엉금」은 느리게 기어가는 모양이에요.","「데굴데굴」은 도토리가 구르는 모양이에요.","「퐁당」은 물에 빠지는 소리예요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 풍선이 떠오르는 모습을 흉내 낸 말은 어느 것인가요?","options":[{"t":"둥실둥실","correct":true},{"t":"깡충","mis":"K2-1-u7-X14"},{"t":"생글생글","mis":"K2-1-u7-X14"}],"explanation":["「둥실둥실」은 가볍게 떠오르는 모양이에요.","「깡충」은 뛰어오르는 모양이에요.","「생글생글」은 웃는 모양이에요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#5','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"데굴데굴","r":"큰 물건이 계속 구르는 모양"},{"l":"퐁당","r":"작은 물건이 물에 떨어지는 소리"},{"l":"방긋","r":"소리 없이 살짝 웃는 모양"}],"mis":"K2-1-u7-X14","explanation":["도토리는 데굴데굴 굴렀어요.","도토리가 웅덩이에 퐁당 빠졌어요.","토리는 방긋 웃었어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"휙","r":"바람이 갑자기 세게 부는 소리"},{"l":"깡충","r":"가볍게 뛰어오르는 모양"},{"l":"생글생글","r":"눈과 입으로 귀엽게 웃는 모양"}],"explanation":["바람이 휙 불었어요.","건우 형이 깡충 뛰어올랐어요.","하윤이는 생글생글 웃었어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#6','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',2,'mc','auto','이야기를 읽고 답해 보세요. 토리가 거북 할아버지께 도토리 과자를 드린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X02']::text[],true,'{"seq":6,"concept":"K2-1-u7-C10","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 토리가 거북 할아버지께 도토리 과자를 드린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"도토리를 건져 주신 고마운 마음을 전하려고","correct":true},{"t":"도토리가 맛이 없어서","mis":"K2-1-u7-X04"},{"t":"할아버지께 잘못을 사과하려고","mis":"K2-1-u7-X02"}],"explanation":["도움을 받은 고마운 마음을 행동으로 전했어요.","도토리 맛 이야기는 없어요.","토리가 할아버지께 잘못한 일은 없어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 하윤이가 「이제 꼭 잡을게요.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"다시는 풍선을 놓치지 않겠다는 마음을 전하려고","correct":true},{"t":"건우 형에게 풍선을 주려고","mis":"K2-1-u7-X04"},{"t":"건우 형이 풍선을 놓쳤으니까","mis":"K2-1-u7-X05"}],"explanation":["도와준 형에게 고마움과 다짐을 함께 전했어요.","풍선을 준다는 말은 없어요.","풍선을 놓친 것은 하윤이예요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#7','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',2,'mc','auto','쪽지를 읽고 답해 보세요. 서아가 지호에게 고마운 까닭은 무엇인가요?',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":7,"concept":"K2-1-u7-C10","difficulty":2,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 서아가 지호에게 고마운 까닭은 무엇인가요?","options":[{"t":"필통을 놓고 왔을 때 연필을 빌려줘서","correct":true},{"t":"받아쓰기를 대신 해 줘서","mis":"K2-1-u7-X04"},{"t":"필통을 새로 사 줘서","mis":"K2-1-u7-X04"}],"explanation":["서아는 연필을 빌려준 일이 고마웠어요.","받아쓰기를 대신 했다는 말은 없어요.","필통을 사 줬다는 말도 없어요."],"asset":{"type":"passage","lines":["지호에게","지호야, 어제 내가 필통을 놓고 왔을 때 연필을 빌려줘서 고마워.","덕분에 받아쓰기를 끝까지 할 수 있었어.","다음에는 내가 너를 도와줄게.","— 서아가"],"title":"서아의 마음 쪽지"},"variant_rule":{"alt":[{"stem":"쪽지를 읽고 답해 보세요. 민호가 엄마께 죄송한 까닭은 무엇인가요?","options":[{"t":"아침에 짜증을 내서","correct":true},{"t":"학교에 가지 않아서","mis":"K2-1-u7-X04"},{"t":"엄마가 짜증을 내서","mis":"K2-1-u7-X05"}],"explanation":["민호는 아침에 짜증 낸 일이 죄송했어요.","학교에 가지 않았다는 말은 없어요.","짜증을 낸 사람은 엄마가 아니라 민호예요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#8','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',2,'error','auto','고운 말로 마음을 전했어요. 마음에 어울리지 않는 말을 한 친구는 누구인가요?',ARRAY['K2-1-u7-X02','K2-1-u7-X18']::text[],true,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":2,"kind":"error","stem":"고운 말로 마음을 전했어요. 마음에 어울리지 않는 말을 한 친구는 누구인가요?","options":[{"t":"지안 — 동생 생일에 「동생아, 미안해!」","correct":true,"mis_target":"K2-1-u7-X02"},{"t":"윤서 — 짝이 도와줬을 때 「도와줘서 고마워.」","mis":"K2-1-u7-X18"},{"t":"하준 — 친구 발을 밟았을 때 「밟아서 미안해.」","mis":"K2-1-u7-X18"}],"explanation":["생일에는 「축하해!」라고 해야 어울려요.","윤서와 하준이는 마음에 맞는 말을 했어요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 고운 말로 마음을 전했어요. 마음에 어울리지 않는 말을 한 친구는 누구인가요?","options":[{"t":"태민 — 친구가 상을 받았을 때 「고마워!」","correct":true,"mis_target":"K2-1-u7-X02"},{"t":"은솔 — 친구가 상을 받았을 때 「상 받은 거 축하해!」","mis":"K2-1-u7-X18"},{"t":"민지 — 할머니가 반찬을 해 주셨을 때 「고맙습니다.」","mis":"K2-1-u7-X18"}],"explanation":["친구가 상을 받으면 「축하해!」라고 해요.","은솔이와 민지는 마음에 맞는 말을 했어요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#9','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',2,'mc','auto','쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X15']::text[],true,'{"seq":9,"concept":"K2-1-u7-C10","difficulty":2,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?","options":[{"t":"받는 사람: 지호 · 쓴 사람: 서아","correct":true},{"t":"받는 사람: 서아 · 쓴 사람: 지호","mis":"K2-1-u7-X15"},{"t":"받는 사람: 선생님 · 쓴 사람: 서아","mis":"K2-1-u7-X15"}],"explanation":["「지호에게」로 시작하니 받는 사람은 지호예요.","「— 서아가」로 끝나니 쓴 사람은 서아예요.","첫 줄과 끝 줄을 살펴요."],"asset":{"type":"passage","lines":["지호에게","지호야, 어제 내가 필통을 놓고 왔을 때 연필을 빌려줘서 고마워.","덕분에 받아쓰기를 끝까지 할 수 있었어.","다음에는 내가 너를 도와줄게.","— 서아가"],"title":"서아의 마음 쪽지"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?","options":[{"t":"받는 사람: 엄마 · 쓴 사람: 민호","correct":true},{"t":"받는 사람: 민호 · 쓴 사람: 엄마","mis":"K2-1-u7-X15"},{"t":"받는 사람: 아빠 · 쓴 사람: 민호","mis":"K2-1-u7-X15"}],"explanation":["「엄마께」로 시작하니 받는 사람은 엄마예요.","「— 민호 올림」으로 끝나니 쓴 사람은 민호예요.","첫 줄과 끝 줄을 살펴요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#10','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 엉엉 울던 토리가 방긋 웃게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],true,'{"seq":10,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 엉엉 울던 토리가 방긋 웃게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"거북 할아버지가 도토리를 건져 주셔서","correct":true},{"t":"도토리를 웅덩이에 빠뜨려서","mis":"K2-1-u7-X04"},{"t":"할아버지께 도토리 과자를 받아서","mis":"K2-1-u7-X05"}],"explanation":["할아버지가 도토리를 건져 주자 토리가 웃었어요.","도토리를 빠뜨렸을 때는 울었어요.","과자는 토리가 할아버지께 드린 거예요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시무룩하던 하윤이가 생글생글 웃게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"건우 형이 풍선 줄을 잡아 주어서","correct":true},{"t":"바람이 휙 불어서","mis":"K2-1-u7-X04"},{"t":"놀이공원에서 풍선을 받아서","mis":"K2-1-u7-X04"}],"explanation":["건우 형이 풍선 줄을 잡아 주자 하윤이가 웃었어요.","바람이 불어서 풍선을 놓쳤어요.","풍선을 받은 일은 이야기 처음에 있던 일이에요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#1','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C10',2,'mc','auto','마음 쪽지에 담기에 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],false,'{"seq":1,"concept":"K2-1-u7-C10","difficulty":2,"kind":"mc","stem":"마음 쪽지에 담기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 실수를 놀리는 말","correct":true},{"t":"도와줘서 고마운 마음","mis":"K2-1-u7-X18"},{"t":"잘못해서 미안한 마음","mis":"K2-1-u7-X18"}],"explanation":["놀리는 말은 마음을 아프게 해요.","고마운 마음과 미안한 마음은 쪽지에 담기 좋아요.","물음의 「않은」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#2','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',2,'mc','auto','이야기를 읽고 답해 보세요. 풍선 줄이 하윤이의 손에서 빠져나간 까닭은 무엇인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":2,"concept":"K2-1-u7-C9","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 풍선 줄이 하윤이의 손에서 빠져나간 까닭은 무엇인가요?","options":[{"t":"바람이 휙 불어서","correct":true},{"t":"건우 형이 잡아당겨서","mis":"K2-1-u7-X05"},{"t":"하윤이가 풍선을 버려서","mis":"K2-1-u7-X04"}],"explanation":["바람이 휙 불자 줄이 쏙 빠져나갔어요.","건우 형은 풍선을 잡아 준 인물이에요.","풍선을 버렸다는 말은 없어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#3','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 토리의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 토리의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"즐겁다 → 슬프다 → 고맙다","correct":true},{"t":"슬프다 → 즐겁다 → 고맙다","mis":"K2-1-u7-X04"},{"t":"고맙다 → 슬프다 → 즐겁다","mis":"K2-1-u7-X04"}],"explanation":["도토리를 데굴데굴 굴리며 즐겁게 가다가 빠뜨려 슬펐어요.","할아버지가 건져 주자 고마웠어요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#4','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',3,'error','auto','이야기를 읽고 인물의 마음을 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?',ARRAY['K2-1-u7-X13','K2-1-u7-X18']::text[],false,'{"seq":4,"concept":"K2-1-u7-C9","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 마음을 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?","options":[{"t":"현우 — 「건우 형은 풍선을 잡아 주기 싫었을 거야.」","correct":true,"mis_target":"K2-1-u7-X13"},{"t":"소율 — 「하윤이는 풍선을 놓쳐서 속상했을 거야.」","mis":"K2-1-u7-X18"},{"t":"예린 — 「건우 형은 하윤이가 웃어서 흐뭇했을 거야.」","mis":"K2-1-u7-X18"}],"explanation":["스스로 뛰어올라 잡아 준 형이 싫었을 리 없어요.","소율이와 예린이는 알맞게 짐작했어요.","그 인물이 되어 생각해 봐요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#5','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',3,'ox','auto','이야기를 읽고 답해 보세요. 「엉금엉금」은 거북 할아버지가 매우 빠르게 달려오는 모습을 나타내요.',ARRAY['K2-1-u7-X14']::text[],false,'{"seq":5,"concept":"K2-1-u7-C9","difficulty":3,"kind":"ox","stem":"이야기를 읽고 답해 보세요. 「엉금엉금」은 거북 할아버지가 매우 빠르게 달려오는 모습을 나타내요.","answer":"X","reason_options":[{"t":"「엉금엉금」은 느리게 기어가는 모양을 나타내니까","correct":true},{"t":"흉내 내는 말은 모두 빠른 모습을 나타내니까","mis":"K2-1-u7-X14"}],"mis":"K2-1-u7-X14","explanation":["「엉금엉금」은 느릿느릿 기어가는 모양이에요.","흉내 내는 말마다 나타내는 모양이 달라요.","몸짓으로 따라 해 봐요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#6','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C10',3,'mc','auto','친구에게 고마운 마음을 전하는 쪽지예요. 가장 잘 쓴 것은 어느 것인가요?',ARRAY['K2-1-u7-X15','K2-1-u7-X03']::text[],false,'{"seq":6,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"친구에게 고마운 마음을 전하는 쪽지예요. 가장 잘 쓴 것은 어느 것인가요?","options":[{"t":"「다은아, 내가 아플 때 알림장을 집에 가져다줘서 고마워. 덕분에 준비물을 챙길 수 있었어.」","correct":true},{"t":"「다은아, 고마워.」","mis":"K2-1-u7-X15"},{"t":"「다은아, 알림장 고마워. 근데 글씨가 엉망이더라.」","mis":"K2-1-u7-X03"}],"explanation":["받는 사람·고마운 일·덕분에 좋았던 점이 모두 담겼어요.","무엇이 고마운지 빠졌어요.","고마운 마음 뒤에 흉을 보면 마음이 상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#7','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 민호가 쪽지에 담은 내용이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],false,'{"seq":7,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 민호가 쪽지에 담은 내용이 아닌 것은 어느 것인가요?","options":[{"t":"엄마께 선물을 사 드리겠다는 약속","correct":true},{"t":"짜증 낸 일에 대한 사과","mis":"K2-1-u7-X18"},{"t":"일찍 일어나겠다는 다짐","mis":"K2-1-u7-X18"}],"explanation":["선물 약속은 쪽지에 없어요.","사과와 다짐은 쪽지에 있어요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#8','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',4,'mc','auto','이야기를 읽고 답해 보세요. 이 이야기를 읽고 떠올린 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X13']::text[],false,'{"seq":8,"concept":"K2-1-u7-C9","difficulty":4,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 이 이야기를 읽고 떠올린 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「곤란한 이웃을 도우면 서로 마음이 따뜻해지고, 고마운 마음은 말과 행동으로 전하면 좋겠어.」","correct":true},{"t":"「도토리는 굴리면 안 되는 열매야.」","mis":"K2-1-u7-X04"},{"t":"「거북은 느려서 아무도 못 도와.」","mis":"K2-1-u7-X13"}],"explanation":["도움을 주고받은 일과 고마움을 전한 일을 모두 담았어요.","도토리 굴리기는 이야기가 전하려는 생각이 아니에요.","거북 할아버지는 느려도 토리를 도왔어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#9','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C10',4,'essay','teacher','고마운 마음이나 미안한 마음을 전하고 싶은 사람을 한 명 떠올려, 받는 사람·전하고 싶은 마음·그 까닭이 드러나게 고운 말로 마음 쪽지를 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"고마운 마음이나 미안한 마음을 전하고 싶은 사람을 한 명 떠올려, 받는 사람·전하고 싶은 마음·그 까닭이 드러나게 고운 말로 마음 쪽지를 써 보세요.","answer_guide":{"answer":"예: 할머니께 — 할머니, 제가 감기에 걸렸을 때 따뜻한 죽을 끓여 주셔서 고맙습니다. 덕분에 빨리 나았어요. 다음에 할머니 댁에 가면 어깨를 주물러 드릴게요. — 지우 올림","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#10','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',4,'essay','teacher','이야기를 읽고 답해 보세요. 하윤이의 마음이 어떻게 바뀌었는지 흉내 내는 말을 넣어 차례대로 쓰고, 내가 하윤이라면 건우 형에게 어떤 고운 말을 더 하고 싶은지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C9","difficulty":4,"kind":"essay","stem":"이야기를 읽고 답해 보세요. 하윤이의 마음이 어떻게 바뀌었는지 흉내 내는 말을 넣어 차례대로 쓰고, 내가 하윤이라면 건우 형에게 어떤 고운 말을 더 하고 싶은지 써 보세요.","answer_guide":{"answer":"예: 풍선을 놓쳐 시무룩했다가, 건우 형이 풍선을 잡아 주자 생글생글 웃을 만큼 기뻤어요. 「형 덕분에 풍선을 다시 찾았어요. 형도 놀이공원에서 즐겁게 놀아요!」","scoring_points":["마음이 바뀐 차례를 바르게 썼는가","흉내 내는 말을 알맞게 넣었는가","건우 형에게 할 고운 말을 썼는가"]},"explanation":["마음이 바뀐 차례.","흉내 내는 말.","고운 말."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#1','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',1,'mc','auto','맞추기판을 읽고 답해 보세요. 로아의 맞추기판에 있는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],true,'{"seq":1,"concept":"K2-1-u7-C11","difficulty":1,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 로아의 맞추기판에 있는 고운 말은 어느 것인가요?","options":[{"t":"걱정하지 마","correct":true},{"t":"시끄러워","mis":"K2-1-u7-X03"},{"t":"저리 가","mis":"K2-1-u7-X03"}],"explanation":["「걱정하지 마」는 셋째 줄에 있어요.","「시끄러워」와 「저리 가」는 거친 말이라 판에 없어요.","판에서 그 말을 찾아 짚어요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"},"variant_rule":{"alt":[{"stem":"맞추기판을 읽고 답해 보세요. 지안이의 맞추기판에 있는 고운 말은 어느 것인가요?","options":[{"t":"최고야","correct":true},{"t":"메롱","mis":"K2-1-u7-X03"},{"t":"비켜","mis":"K2-1-u7-X03"}],"explanation":["「최고야」는 셋째 줄에 있어요.","「메롱」과 「비켜」는 거친 말이라 판에 없어요.","판에서 그 말을 찾아 짚어요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#2','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',1,'mc','auto','고운 말 맞추기판에 적기에 알맞지 않은 말은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],true,'{"seq":2,"concept":"K2-1-u7-C11","difficulty":1,"kind":"mc","stem":"고운 말 맞추기판에 적기에 알맞지 않은 말은 어느 것인가요?","options":[{"t":"넌 안 돼","correct":true},{"t":"같이 하자","mis":"K2-1-u7-X18"},{"t":"힘내","mis":"K2-1-u7-X18"}],"explanation":["「넌 안 돼」는 친구의 마음을 꺾는 말이에요.","「같이 하자」와 「힘내」는 고운 말이에요.","물음의 「않은」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 고운 말 맞추기판에 적기에 알맞지 않은 말은 어느 것인가요?","options":[{"t":"바보야","correct":true},{"t":"잘했어","mis":"K2-1-u7-X18"},{"t":"고마워","mis":"K2-1-u7-X18"}],"explanation":["「바보야」는 친구를 놀리는 말이에요.","「잘했어」와 「고마워」는 고운 말이에요.","물음의 「않은」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#3','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',1,'ox','auto','고운 말 맞추기 놀이는 친구가 말한 고운 말이 내 판에 있으면 표시하는 놀이예요.',ARRAY['K2-1-u7-X16']::text[],true,'{"seq":3,"concept":"K2-1-u7-C11","difficulty":1,"kind":"ox","stem":"고운 말 맞추기 놀이는 친구가 말한 고운 말이 내 판에 있으면 표시하는 놀이예요.","answer":"O","reason_options":[{"t":"친구가 말한 말과 같은 칸에 표시하며 고운 말을 익히니까","correct":true},{"t":"친구가 말한 말은 내 판에서 지워 버리는 놀이니까","mis":"K2-1-u7-X16"}],"mis":"K2-1-u7-X16","explanation":["친구가 말한 고운 말이 내 판에 있으면 표시해요.","표시한 칸이 세 줄이 되면 「맞았어!」 하고 외쳐요.","놀이하며 고운 말을 소리 내어 익혀요."],"variant_rule":{"alt":[{"stem":"고운 말은 놀이를 할 때만 쓰고 평소에는 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"놀이로 익힌 고운 말을 생활에서도 써야 하니까","correct":true},{"t":"고운 말은 놀이 규칙일 뿐이니까","mis":"K2-1-u7-X16"}],"explanation":["놀이는 고운 말을 익히는 연습이에요.","익힌 고운 말은 집과 학교에서 써요.","오늘 누구에게 쓸지 정해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#4','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',1,'mc','auto','줄넘기 대회에 나가는 친구에게 해 줄 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X02']::text[],true,'{"seq":4,"concept":"K2-1-u7-C11","difficulty":1,"kind":"mc","stem":"줄넘기 대회에 나가는 친구에게 해 줄 고운 말은 어느 것인가요?","options":[{"t":"「연습한 만큼 잘할 거야. 응원할게!」","correct":true},{"t":"「너는 떨어질 거야.」","mis":"K2-1-u7-X03"},{"t":"「미안해.」","mis":"K2-1-u7-X02"}],"explanation":["친구에게 힘을 주는 응원하는 말이에요.","「떨어질 거야」는 친구의 마음을 꺾는 말이에요.","잘못한 일이 없으니 「미안해.」는 맞지 않아요."],"variant_rule":{"alt":[{"stem":"새 옷을 입고 온 친구에게 해 줄 고운 말은 어느 것인가요?","options":[{"t":"「옷이 참 잘 어울린다!」","correct":true},{"t":"「그 옷 이상해.」","mis":"K2-1-u7-X03"},{"t":"「미안해.」","mis":"K2-1-u7-X02"}],"explanation":["친구를 기분 좋게 하는 칭찬하는 말이에요.","「이상해」는 친구의 마음을 상하게 해요.","잘못한 일이 없으니 「미안해.」는 맞지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#5','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'match','auto','상황에 어울리는 고운 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C11","difficulty":2,"kind":"match","stem":"상황에 어울리는 고운 말을 알맞게 이어 보세요.","pairs":[{"l":"함께 청소를 끝낸 친구","r":"같이 해서 금방 끝났다. 수고했어!"},{"l":"그림을 멋지게 완성한 친구","r":"색깔이 정말 멋지다!"},{"l":"약속에 늦어 사과하는 친구","r":"괜찮아, 무슨 일 있었어?"}],"mis":"K2-1-u7-X02","explanation":["함께 일한 친구에게는 수고했다고 해요.","잘한 친구에게는 칭찬해요.","사과하는 친구에게는 괜찮다고 하며 마음을 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 어울리는 고운 말을 알맞게 이어 보세요.","pairs":[{"l":"처음 인사하는 전학생","r":"반가워, 앞으로 친하게 지내자."},{"l":"공을 주워 준 친구","r":"공 주워 줘서 고마워."},{"l":"달리기에서 넘어진 친구","r":"끝까지 달려서 멋졌어."}],"explanation":["처음 만난 친구에게는 반갑게 맞아요.","도와준 친구에게는 고맙다고 해요.","넘어진 친구에게는 힘을 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#6','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 친구들이 「고마워」, 「미안해」, 「걱정하지 마」를 말해서 로아가 칸에 표시했어요. 표시한 칸이 이루는 줄은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":6,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 친구들이 「고마워」, 「미안해」, 「걱정하지 마」를 말해서 로아가 칸에 표시했어요. 표시한 칸이 이루는 줄은 어느 것인가요?","options":[{"t":"왼쪽 위에서 오른쪽 아래로 가는 대각선 한 줄","correct":true},{"t":"첫째 줄 가로 한 줄","mis":"K2-1-u7-X04"},{"t":"표시한 칸이 줄을 이루지 않아요","mis":"K2-1-u7-X04"}],"explanation":["「고마워」는 첫째 줄 첫째 칸, 「미안해」는 가운데 칸이에요.","「걱정하지 마」는 셋째 줄 마지막 칸이라 대각선이 돼요.","판에서 세 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"},"variant_rule":{"alt":[{"stem":"맞추기판을 읽고 답해 보세요. 친구들이 「축하해」, 「괜찮아?」, 「미안해」를 말해서 지안이가 칸에 표시했어요. 표시한 칸이 이루는 줄은 어느 것인가요?","options":[{"t":"맨 왼쪽 세로 한 줄","correct":true},{"t":"첫째 줄 가로 한 줄","mis":"K2-1-u7-X04"},{"t":"대각선 한 줄","mis":"K2-1-u7-X04"}],"explanation":["세 말은 모두 각 줄의 첫째 칸에 있어요.","그래서 맨 왼쪽 세로 한 줄이 돼요.","판에서 세 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#7','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'error','auto','고운 말 맞추기 놀이를 했어요. 놀이에서 지켜야 할 일을 지키지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X18']::text[],true,'{"seq":7,"concept":"K2-1-u7-C11","difficulty":2,"kind":"error","stem":"고운 말 맞추기 놀이를 했어요. 놀이에서 지켜야 할 일을 지키지 않은 친구는 누구인가요?","options":[{"t":"건우 — 친구가 말한 말이 자기 판에 없자 「그건 고운 말도 아니야!」 하고 소리쳤어요.","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"하늘 — 차례를 기다렸다가 「같이 하자」를 크게 말했어요.","mis":"K2-1-u7-X18"},{"t":"수빈 — 표시한 칸이 세 줄이 되자 「맞았어!」 하고 외쳤어요.","mis":"K2-1-u7-X18"}],"explanation":["고운 말 놀이에서 거친 말로 소리치면 안 돼요.","하늘이와 수빈이는 놀이 방법을 잘 지켰어요.","놀이할 때에도 고운 말을 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 고운 말 맞추기 놀이를 했어요. 놀이에서 지켜야 할 일을 지키지 않은 친구는 누구인가요?","options":[{"t":"서윤 — 판에 「메롱」을 적어 넣고 친구가 보자 키득키득 웃었어요.","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"도윤 — 좋아하는 고운 말 아홉 개를 판에 적었어요.","mis":"K2-1-u7-X18"},{"t":"로아 — 친구가 말한 고운 말이 판에 있어서 표시했어요.","mis":"K2-1-u7-X18"}],"explanation":["판에는 고운 말만 적어요. 「메롱」은 놀리는 말이에요.","도윤이와 로아는 놀이 방법을 잘 지켰어요.","놀이할 때에도 고운 말을 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#8','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'mc','auto','고운 말을 생활에서 실천한 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X16']::text[],true,'{"seq":8,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"고운 말을 생활에서 실천한 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"급식 당번에게 「맛있게 먹을게. 고마워.」라고 말했어요","correct":true},{"t":"동생이 블록을 쓰러뜨리자 「바보야!」라고 했어요","mis":"K2-1-u7-X03"},{"t":"고운 말은 공책에만 적고 말로는 하지 않았어요","mis":"K2-1-u7-X16"}],"explanation":["생활 속에서 고마운 마음을 고운 말로 전했어요.","「바보야!」는 거친 말이에요.","고운 말은 소리 내어 써야 마음이 전해져요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 고운 말을 생활에서 실천한 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"버스에서 내릴 때 기사님께 「고맙습니다.」 하고 인사했어요","correct":true},{"t":"친구가 실수하자 「그럴 줄 알았어.」라고 했어요","mis":"K2-1-u7-X03"},{"t":"놀이가 끝나자 다시 거친 말을 썼어요","mis":"K2-1-u7-X16"}],"explanation":["생활 속에서 고운 말을 썼어요.","「그럴 줄 알았어.」는 친구를 깎아내리는 말이에요.","놀이에서 익힌 고운 말을 계속 써야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#9','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'blank','auto','친구가 내 이야기를 끝까지 들어 주었어요. 「내 이야기를 (     ) 고마워.」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],true,'{"seq":9,"concept":"K2-1-u7-C11","difficulty":2,"kind":"blank","stem":"친구가 내 이야기를 끝까지 들어 주었어요. 「내 이야기를 (     ) 고마워.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"들어 줘서","correct":true},{"t":"끊어 줘서","mis":"K2-1-u7-X03"},{"t":"놀려 줘서","mis":"K2-1-u7-X03"}],"explanation":["끝까지 들어 준 것이 고마운 일이에요.","이야기를 끊은 것은 고마운 일이 아니에요.","놀린 것도 고마운 일이 아니에요."],"variant_rule":{"alt":[{"stem":"친구가 다친 나를 보건실에 데려다주었어요. 「(     ) 덕분에 금방 나았어.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"걱정해 줘서 고마워.","correct":true},{"t":"미안해, 잘못했어.","mis":"K2-1-u7-X02"},{"t":"생일 축하해.","mis":"K2-1-u7-X02"}],"explanation":["도움을 받았으니 고맙다고 해요.","잘못한 일이 아니니 사과할 까닭이 없어요.","생일과는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#10','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',3,'mc','auto','고운 말 맞추기 놀이를 한 뒤 느낀 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X16','K2-1-u7-X03']::text[],true,'{"seq":10,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"고운 말 맞추기 놀이를 한 뒤 느낀 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「고운 말을 크게 말하니 나도 듣는 친구도 기분이 좋아졌어. 집에서도 써 봐야지.」","correct":true},{"t":"「고운 말은 놀이에서만 쓰는 말이라 이제 안 써도 돼.」","mis":"K2-1-u7-X16"},{"t":"「줄만 먼저 만들면 돼. 말은 아무거나 괜찮아.」","mis":"K2-1-u7-X03"}],"explanation":["고운 말의 힘을 느끼고 생활에서 쓰겠다고 다짐했어요.","놀이가 끝나도 고운 말은 계속 써요.","놀이에서도 말은 고와야 해요."],"variant_rule":{"alt":[{"stem":"고운 말 맞추기판을 만들 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"들으면 기분이 좋아지는 고운 말을 내가 정한 칸에 하나씩 적는다","correct":true},{"t":"친구를 놀리는 재미있는 말도 섞어 적는다","mis":"K2-1-u7-X03"},{"t":"아홉 칸에 같은 말을 모두 적는다","mis":"K2-1-u7-X16"}],"explanation":["좋아하는 고운 말을 칸마다 하나씩 적어요.","놀리는 말은 판에 적지 않아요.","같은 말만 적으면 놀이를 할 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#1','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 로아의 맞추기판 한가운데 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":1,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 로아의 맞추기판 한가운데 칸에 있는 말은 어느 것인가요?","options":[{"t":"미안해","correct":true},{"t":"괜찮아","mis":"K2-1-u7-X04"},{"t":"넌 소중해","mis":"K2-1-u7-X04"}],"explanation":["한가운데 칸은 둘째 줄 가운데예요. 「미안해」가 있어요.","「괜찮아」는 첫째 줄 가운데에 있어요.","「넌 소중해」는 셋째 줄 가운데에 있어요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#2','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',2,'mc','auto','고운 말 맞추기판에 적을 말을 고를 때 생각할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X16','K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"고운 말 맞추기판에 적을 말을 고를 때 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"들었을 때 마음이 따뜻해지는 말인가","correct":true},{"t":"글자 수가 가장 긴 말인가","mis":"K2-1-u7-X16"},{"t":"친구가 웃을 만큼 놀리는 말인가","mis":"K2-1-u7-X03"}],"explanation":["듣는 사람의 마음이 따뜻해지는 말을 골라요.","글자 수는 상관없어요.","놀리는 말은 고운 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#3','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'error','auto','같은 뜻을 고운 말로 바꾸었어요. 잘못 바꾼 친구는 누구인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X18']::text[],false,'{"seq":3,"concept":"K2-1-u7-C11","difficulty":3,"kind":"error","stem":"같은 뜻을 고운 말로 바꾸었어요. 잘못 바꾼 친구는 누구인가요?","options":[{"t":"아린 — 「빨리 해!」 → 「빨리 좀 해, 답답하게.」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"서준 — 「빨리 해!」 → 「조금만 서둘러 줄 수 있니?」","mis":"K2-1-u7-X18"},{"t":"지우 — 「이거 해!」 → 「이것 좀 도와줄래?」","mis":"K2-1-u7-X18"}],"explanation":["「답답하게」를 붙이면 여전히 탓하는 말이에요.","서준이와 지우는 부탁하는 말로 바르게 바꾸었어요.","말 끝까지 다 고운지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#4','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'mc','auto','친구가 「나는 그림을 못 그려.」 하며 풀이 죽어 있어요. 친구의 마음을 생각한 고운 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X12']::text[],false,'{"seq":4,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"친구가 「나는 그림을 못 그려.」 하며 풀이 죽어 있어요. 친구의 마음을 생각한 고운 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「색칠을 꼼꼼하게 했네. 같이 그려 보자.」","correct":true},{"t":"「맞아, 진짜 못 그리긴 해.」","mis":"K2-1-u7-X03"},{"t":"「나는 잘 그리는데.」","mis":"K2-1-u7-X12"}],"explanation":["잘한 점을 찾아 칭찬하고 함께하자고 했어요.","친구의 말에 맞장구치며 흉보면 더 속상해요.","내 자랑만 하면 친구의 마음을 생각하지 않은 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#5','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'ox','auto','고운 말을 하면 듣는 사람뿐 아니라 말하는 나의 기분도 좋아질 수 있어요.',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":5,"concept":"K2-1-u7-C11","difficulty":3,"kind":"ox","stem":"고운 말을 하면 듣는 사람뿐 아니라 말하는 나의 기분도 좋아질 수 있어요.","answer":"O","reason_options":[{"t":"고운 말을 주고받으면 서로의 마음이 따뜻해지니까","correct":true},{"t":"고운 말은 듣는 사람에게만 좋은 말이니까","mis":"K2-1-u7-X01"}],"mis":"K2-1-u7-X01","explanation":["고운 말을 하면 내 마음도 밝아져요.","고운 말을 주고받으면 사이도 가까워져요.","오늘 쓸 고운 말을 정해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#6','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'mc','auto','맞추기판을 읽고 답해 보세요. 지안이의 판에 있는 말 가운데 넘어져 다친 친구에게 하기에 가장 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 지안이의 판에 있는 말 가운데 넘어져 다친 친구에게 하기에 가장 알맞은 말은 어느 것인가요?","options":[{"t":"괜찮아?","correct":true},{"t":"축하해","mis":"K2-1-u7-X02"},{"t":"최고야","mis":"K2-1-u7-X02"}],"explanation":["「괜찮아?」는 다친 친구의 마음을 살피는 말이에요.","「축하해」는 기쁜 일에 하는 말이에요.","「최고야」는 잘한 일을 칭찬하는 말이에요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#7','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'mc','auto','고운 말을 실천하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],false,'{"seq":7,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"고운 말을 실천하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"거친 말을 들으면 더 거친 말로 되갚아 준다","correct":true},{"t":"하루에 한 번 가족에게 고마운 점을 말한다","mis":"K2-1-u7-X18"},{"t":"친구가 잘한 점을 찾아 칭찬한다","mis":"K2-1-u7-X18"}],"explanation":["거친 말을 되갚으면 다툼이 커져요.","고마운 점 말하기와 칭찬하기는 좋은 실천이에요.","물음의 「않은」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#8','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',4,'mc','auto','모둠 놀이에서 진 친구들이 「이건 반칙이야!」 하며 화를 냈어요. 이긴 모둠이 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],false,'{"seq":8,"concept":"K2-1-u7-C11","difficulty":4,"kind":"mc","stem":"모둠 놀이에서 진 친구들이 「이건 반칙이야!」 하며 화를 냈어요. 이긴 모둠이 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「다들 열심히 해서 재미있었어. 규칙이 헷갈렸다면 다음엔 같이 정해 보자.」","correct":true},{"t":"「졌으면서 왜 우겨? 너희가 못한 거야.」","mis":"K2-1-u7-X12"},{"t":"「우리가 이겼다! 메롱!」","mis":"K2-1-u7-X03"}],"explanation":["진 친구들의 속상한 마음을 헤아리고 함께 방법을 찾자고 했어요.","따지기만 하면 다툼이 커져요.","놀리면 진 친구들이 더 속상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#9','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',4,'essay','teacher','나만의 고운 말 맞추기판에 넣고 싶은 고운 말 세 가지를 쓰고, 각각 어떤 상황에서 누구에게 쓰면 좋을지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C11","difficulty":4,"kind":"essay","stem":"나만의 고운 말 맞추기판에 넣고 싶은 고운 말 세 가지를 쓰고, 각각 어떤 상황에서 누구에게 쓰면 좋을지 써 보세요.","answer_guide":{"answer":"예: 「고마워」 — 짝이 지우개를 빌려줄 때 짝에게. 「힘내」 — 동생이 받아쓰기를 걱정할 때 동생에게. 「같이 놀자」 — 혼자 있는 친구를 보았을 때 그 친구에게.","scoring_points":["고운 말을 세 가지 썼는가","각 말을 쓸 상황을 썼는가","상황에 어울리는 말을 골랐는가"]},"explanation":["고운 말 세 가지.","쓸 상황과 사람.","상황에 맞는 짝."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#10','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',4,'essay','teacher','일주일 동안 실천할 「고운 말 다짐」을 써 보세요. 누구에게, 어떤 상황에서, 어떤 고운 말을 쓸지와 그렇게 다짐한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C11","difficulty":4,"kind":"essay","stem":"일주일 동안 실천할 「고운 말 다짐」을 써 보세요. 누구에게, 어떤 상황에서, 어떤 고운 말을 쓸지와 그렇게 다짐한 까닭을 써 보세요.","answer_guide":{"answer":"예: 나는 동생이 내 물건을 만질 때 「저리 가!」 대신 「쓰고 싶으면 먼저 말해 줘.」라고 말하겠어요. 왜냐하면 소리를 지르면 동생이 울고 우리 둘 다 기분이 나빠지기 때문이에요.","scoring_points":["누구에게 어떤 상황에서 쓸지 썼는가","쓸 고운 말을 썼는가","다짐한 까닭을 썼는가"]},"explanation":["누구에게·어떤 상황.","고운 말.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#1','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C1',1,'mc','auto','고운 말을 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"고운 말을 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람의 마음을 따뜻하게 하니까","correct":true},{"t":"말을 빨리 끝낼 수 있으니까","mis":"K2-1-u7-X01"},{"t":"어른 앞에서만 지키면 되니까","mis":"K2-1-u7-X01"}],"explanation":["고운 말은 듣는 사람의 기분을 좋게 해요.","다른 보기는 말이 마음에 주는 힘을 생각하지 않았어요.","내가 들었다면 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#2','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「내가 도와줄게.」","correct":true},{"t":"「저리 비켜.」","mis":"K2-1-u7-X03"},{"t":"「그것도 못하니?」","mis":"K2-1-u7-X03"}],"explanation":["「내가 도와줄게.」는 듣는 사람을 생각하는 고운 말이에요.","다른 두 말은 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#3','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 서준이에게 우산을 같이 쓰자고 한 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이에게 우산을 같이 쓰자고 한 인물은 누구인가요?","options":[{"t":"아린","correct":true},{"t":"서준","mis":"K2-1-u7-X05"},{"t":"선생님","mis":"K2-1-u7-X04"}],"explanation":["아린이가 「내 우산 같이 쓰자.」라고 했어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#4','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 수빈이가 감자를 캔 때는 언제인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":4,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이가 감자를 캔 때는 언제인가요?","options":[{"t":"지난 토요일","correct":true},{"t":"어제 저녁","mis":"K2-1-u7-X05"},{"t":"다음 주 일요일","mis":"K2-1-u7-X04"}],"explanation":["「지난 토요일에」라고 했어요.","다른 보기는 다른 친구의 발표에 나오거나 발표에 없어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#5','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C6',1,'mc','auto','발표할 때 바른 자세로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X10']::text[],false,'{"seq":5,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"발표할 때 바른 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람을 바라보며 말해요","correct":true},{"t":"바닥만 보며 말해요","mis":"K2-1-u7-X10"},{"t":"몸을 이리저리 흔들며 말해요","mis":"K2-1-u7-X10"}],"explanation":["듣는 사람을 바라보면 마음이 잘 전해져요.","다른 보기는 바르지 않은 자세예요.","맨 뒤 친구가 잘 듣고 볼 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#6','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C8',1,'mc','auto','도움을 받았을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"도움을 받았을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「고마워.」","correct":true},{"t":"「미안해.」","mis":"K2-1-u7-X02"},{"t":"「축하해.」","mis":"K2-1-u7-X02"}],"explanation":["도움을 받으면 「고마워.」라고 해요.","다른 보기는 상황과 맞지 않는 말이에요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#7','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C12',1,'mc','auto','내가 직접 겪은 일을 말할 때 「어제 할머니 댁에 다녀온 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"내가 직접 겪은 일을 말할 때 「어제 할머니 댁에 다녀온 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"어제 할머니 댁에 다녀왔어요.","correct":true},{"t":"어제 할머니 댁에 다녀온 것 같은 것 같아요.","mis":"K2-1-u7-X17"},{"t":"어제 할머니 댁에 다녀왔던 것 같아요.","mis":"K2-1-u7-X17"}],"explanation":["직접 겪은 확실한 일은 「어제 할머니 댁에 다녀왔어요.」처럼 또렷하게 말해요.","「것 같아요」를 그대로 두거나 더 붙이면 또렷하지 않아요.","「내가 직접 겪었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#8','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C10',1,'ox','auto','고마운 마음은 말로 전하지 않아도 상대가 저절로 알아요.',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"고마운 마음은 말로 전하지 않아도 상대가 저절로 알아요.","answer":"X","reason_options":[{"t":"마음은 고운 말로 표현해야 상대에게 잘 전해지니까","correct":true},{"t":"마음은 말하지 않는 것이 더 고운 것이니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["말하지 않으면 상대는 내 마음을 모를 수 있어요.","마음은 고운 말로 표현해야 전해져요.","누구에게 · 어떤 마음 · 왜를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#9','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"비켜!","r":"잠깐 지나가도 될까?"},{"l":"시끄러워!","r":"조금만 작게 말해 줄래?"},{"l":"그것도 몰라?","r":"내가 같이 알아볼게."}],"mis":"K2-1-u7-X02","explanation":["「비켜!」 → 「잠깐 지나가도 될까?」","「시끄러워!」 → 「조금만 작게 말해 줄래?」","「그것도 몰라?」 → 「내가 같이 알아볼게.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#10','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 서준이와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"지우 — 「준비물을 안 가져왔을 때 짝이 빌려줘서 고마웠어.」","correct":true},{"t":"민호 — 「어제 저녁에 카레를 먹었어.」","mis":"K2-1-u7-X07"},{"t":"다은 — 「나는 비 오는 날을 좋아해.」","mis":"K2-1-u7-X07"}],"explanation":["곤란할 때 도움을 받아 고마웠던 경험이에요.","다른 보기는 겪은 일이 아니거나 이야기와 상관없어요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#11','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":11,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"생각보다 감자가 많이 나와서 깜짝 놀랐어요.","correct":true},{"t":"저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","mis":"K2-1-u7-X06"},{"t":"호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","mis":"K2-1-u7-X06"}],"explanation":["「깜짝 놀랐어요」에 느낌이 드러나요.","다른 두 문장은 있었던 일을 말한 문장이에요.","「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 물어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#12','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 옷에 우유가 튀었을 때 태민이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 옷에 우유가 튀었을 때 태민이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"깜짝 놀라고 속상했다","correct":true},{"t":"신나고 즐거웠다","mis":"K2-1-u7-X13"},{"t":"고맙고 뿌듯했다","mis":"K2-1-u7-X13"}],"explanation":["옷이 더러워져 놀라고 속상했을 거예요.","다른 보기는 상황에 맞지 않는 마음이에요.","내가 그 사람이라면 어떤 마음일지 생각해요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#13','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"데굴데굴","r":"큰 물건이 계속 구르는 모양"},{"l":"퐁당","r":"작은 물건이 물에 떨어지는 소리"},{"l":"엉금엉금","r":"느리게 기어가는 모양"}],"mis":"K2-1-u7-X14","explanation":["「데굴데굴」 — 큰 물건이 계속 구르는 모양","「퐁당」 — 작은 물건이 물에 떨어지는 소리","「엉금엉금」 — 느리게 기어가는 모양"],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#14','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C12',2,'match','auto','직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"match","stem":"직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.","pairs":[{"l":"다녀온 것 같아요","r":"다녀왔어요"},{"l":"맛있었던 것 같아요","r":"맛있었어요"},{"l":"재미있는 것 같아요","r":"재미있어요"}],"mis":"K2-1-u7-X17","explanation":["「다녀온 것 같아요」 → 「다녀왔어요」","「맛있었던 것 같아요」 → 「맛있었어요」","「재미있는 것 같아요」 → 「재미있어요」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#15','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 로아의 판 한가운데 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":15,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 로아의 판 한가운데 칸에 있는 말은 어느 것인가요?","options":[{"t":"미안해","correct":true},{"t":"괜찮아","mis":"K2-1-u7-X04"},{"t":"넌 소중해","mis":"K2-1-u7-X04"}],"explanation":["한가운데 칸은 둘째 줄 가운데예요.","다른 보기는 판의 그 자리에 없어요.","판에서 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#16','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C6',2,'error','auto','발표하는 모습이에요. 바르지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X10','K2-1-u7-X18']::text[],false,'{"seq":16,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표하는 모습이에요. 바르지 않은 친구는 누구인가요?","options":[{"t":"지우 — 친구들을 보지 않고 창밖만 보며 말했어요.","correct":true,"mis_target":"K2-1-u7-X10"},{"t":"윤호 — 모두에게 들리게 알맞은 크기로 말했어요.","mis":"K2-1-u7-X18"},{"t":"채원 — 바르게 서서 듣는 사람을 보며 말했어요.","mis":"K2-1-u7-X18"}],"explanation":["창밖만 보면 마음이 전해지지 않아요.","다른 두 친구는 바른 자세였어요.","맨 뒤 친구까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#17','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C8',3,'mc','auto','친구가 실수로 내 블록 탑을 무너뜨렸어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],false,'{"seq":17,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 실수로 내 블록 탑을 무너뜨렸어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「탑이 무너져서 속상해. 일부러 그런 건 아니지? 같이 다시 쌓자.」","correct":true},{"t":"「몰라, 저리 가!」","mis":"K2-1-u7-X12"},{"t":"「무너뜨려 줘서 고마워.」","mis":"K2-1-u7-X02"}],"explanation":["내 마음을 말하면서 친구의 마음도 헤아렸어요.","화난 기분만 쏟아 내면 다툼이 커져요.","「일부러 그랬을까?」 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#18','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 엉엉 울던 토리가 방긋 웃게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],false,'{"seq":18,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 엉엉 울던 토리가 방긋 웃게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"거북 할아버지가 도토리를 건져 주셔서","correct":true},{"t":"도토리를 웅덩이에 빠뜨려서","mis":"K2-1-u7-X04"},{"t":"할아버지께 과자를 받아서","mis":"K2-1-u7-X05"}],"explanation":["할아버지가 도토리를 건져 주자 웃었어요.","다른 보기는 이야기의 차례나 인물과 맞지 않아요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#19','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 서아가 쪽지에 담은 마음과 그 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X15','K2-1-u7-X04']::text[],false,'{"seq":19,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 서아가 쪽지에 담은 마음과 그 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"고마운 마음 — 연필을 빌려줘서","correct":true},{"t":"미안한 마음 — 연필을 빌려서","mis":"K2-1-u7-X15"},{"t":"고마운 마음 — 필통을 사 줘서","mis":"K2-1-u7-X04"}],"explanation":["연필을 빌려준 일이 고마웠어요.","다른 보기는 쪽지 내용과 맞지 않아요.","누구에게 · 어떤 마음 · 왜를 찾아요."],"asset":{"type":"passage","lines":["지호에게","지호야, 어제 내가 필통을 놓고 왔을 때 연필을 빌려줘서 고마워.","덕분에 받아쓰기를 끝까지 할 수 있었어.","다음에는 내가 너를 도와줄게.","— 서아가"],"title":"서아의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#20','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C4',3,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X18']::text[],false,'{"seq":20,"concept":"K2-1-u7-C4","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"로아 — 「서준이처럼 나도 친구를 도와주고 뿌듯했어.」","correct":true,"mis_target":"K2-1-u7-X05"},{"t":"태민 — 「아린이처럼 나도 할머니를 도와드리고 뿌듯했어.」","mis":"K2-1-u7-X18"},{"t":"윤호 — 「서준이처럼 나도 친구가 도와줘서 고마웠어.」","mis":"K2-1-u7-X18"}],"explanation":["친구를 도와 뿌듯했던 인물은 아린이에요.","다른 두 친구는 바르게 비교했어요.","누구의 일인지, 비슷한 마음인지 살펴요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#21','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C12',3,'ox','auto','「하늘에 먹구름이 끼어서 곧 비가 올 것 같아요.」는 알맞은 말이에요.',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":21,"concept":"K2-1-u7-C12","difficulty":3,"kind":"ox","stem":"「하늘에 먹구름이 끼어서 곧 비가 올 것 같아요.」는 알맞은 말이에요.","answer":"O","reason_options":[{"t":"아직 오지 않은 비를 짐작하는 말이니까","correct":true},{"t":"「것 같아요」는 언제나 틀린 말이니까","mis":"K2-1-u7-X17"}],"mis":"K2-1-u7-X17","explanation":["앞으로 일어날 일을 짐작할 때는 「것 같아요」를 써요.","직접 겪은 확실한 일은 또렷하게 말해요.","짐작하는 일에는 「것 같아요」를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#22','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C1',3,'mc','auto','「문 닫아!」와 「문 좀 닫아 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「문 닫아!」와 「문 좀 닫아 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「문 좀 닫아 줄래?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「문 닫아!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 고운 말이 듣는 사람의 기분을 좋게 해요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#23','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C5',4,'essay','teacher','가족과 함께한 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"가족과 함께한 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 지난 일요일에 집 앞 공원에서 가족과 배드민턴을 쳤어요. 아빠와 공을 스무 번 넘게 주고받아서 정말 신났어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#24','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C8',4,'essay','teacher','대화를 읽고 답해 보세요. 도윤이와 예린이의 마음을 짐작해 쓰고, 두 사람이 고운 말로 다시 대화하도록 고쳐 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 도윤이와 예린이의 마음을 짐작해 쓰고, 두 사람이 고운 말로 다시 대화하도록 고쳐 써 보세요.","answer_guide":{"answer":"예: 도윤이는 속상하고 예린이는 미안했을 거예요. 도윤 — 「탑이 무너져서 속상해.」 예린 — 「미안해. 일부러 그런 건 아니야. 같이 다시 쌓자.」","scoring_points":["인물의 마음을 짐작해 썼는가","상황에 맞는 고운 말을 썼는가","대화의 흐름에 맞게 썼는가"]},"explanation":["인물의 마음.","고운 말.","대화 흐름."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#25','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C10',4,'essay','teacher','도움을 준 친구에게 고마운 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"도움을 준 친구에게 고마운 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.","answer_guide":{"answer":"예: 하준이에게 — 하준아, 내가 줄넘기를 잃어버렸을 때 같이 찾아 줘서 고마워. 덕분에 체육 시간에 줄넘기를 할 수 있었어. — 서윤이가","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#1','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C1',1,'mc','auto','거친 말을 자주 들은 친구에게 생길 수 있는 일은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"거친 말을 자주 들은 친구에게 생길 수 있는 일은 어느 것인가요?","options":[{"t":"마음이 상해 말한 사람과 멀어진다","correct":true},{"t":"기분이 좋아져 더 친해진다","mis":"K2-1-u7-X01"},{"t":"아무 느낌이 없다","mis":"K2-1-u7-X01"}],"explanation":["거친 말은 마음을 아프게 하고 사이를 멀게 해요.","다른 보기는 말이 마음에 주는 힘을 생각하지 않았어요.","내가 들었다면 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#2','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「같이 하자.」","correct":true},{"t":"「시끄러워.」","mis":"K2-1-u7-X03"},{"t":"「바보야.」","mis":"K2-1-u7-X03"}],"explanation":["「같이 하자.」는 듣는 사람을 생각하는 고운 말이에요.","다른 두 말은 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#3','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 시우의 자전거를 뒤에서 잡아 주겠다고 한 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시우의 자전거를 뒤에서 잡아 주겠다고 한 인물은 누구인가요?","options":[{"t":"아빠","correct":true},{"t":"시우","mis":"K2-1-u7-X05"},{"t":"형","mis":"K2-1-u7-X04"}],"explanation":["아빠가 「뒤에서 잡아 줄게.」라고 했어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#4','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 준우가 연을 날린 곳은 어디인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":4,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우가 연을 날린 곳은 어디인가요?","options":[{"t":"동네 공원","correct":true},{"t":"할머니 댁 텃밭","mis":"K2-1-u7-X05"},{"t":"바닷가","mis":"K2-1-u7-X04"}],"explanation":["「동네 공원에서」라고 했어요.","다른 보기는 다른 친구의 발표에 나오거나 발표에 없어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#5','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C6',1,'mc','auto','발표할 때 바른 자세로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X10']::text[],false,'{"seq":5,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"발표할 때 바른 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"말끝까지 또박또박 말해요","correct":true},{"t":"말끝을 흐리며 말해요","mis":"K2-1-u7-X10"},{"t":"종이로 얼굴을 가리고 말해요","mis":"K2-1-u7-X10"}],"explanation":["말끝까지 또박또박 말해야 잘 들려요.","다른 보기는 바르지 않은 자세예요.","맨 뒤 친구가 잘 듣고 볼 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#6','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C8',1,'mc','auto','잘못했을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"잘못했을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「미안해.」","correct":true},{"t":"「고마워.」","mis":"K2-1-u7-X02"},{"t":"「잘했어.」","mis":"K2-1-u7-X02"}],"explanation":["잘못했을 때는 「미안해.」라고 해요.","다른 보기는 상황과 맞지 않는 말이에요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#7','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C12',1,'mc','auto','내가 직접 겪은 일을 말할 때 「오늘 아침에 밥을 먹은 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"내가 직접 겪은 일을 말할 때 「오늘 아침에 밥을 먹은 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"오늘 아침에 밥을 먹었어요.","correct":true},{"t":"오늘 아침에 밥을 먹었던 것 같아요.","mis":"K2-1-u7-X17"},{"t":"오늘 아침에 밥을 먹은 것도 같아요.","mis":"K2-1-u7-X17"}],"explanation":["직접 겪은 확실한 일은 「오늘 아침에 밥을 먹었어요.」처럼 또렷하게 말해요.","「것 같아요」를 그대로 두거나 더 붙이면 또렷하지 않아요.","「내가 직접 겪었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#8','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C10',1,'ox','auto','도움을 받으면 「고마워.」라고 말로 마음을 전하는 것이 좋아요.',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"도움을 받으면 「고마워.」라고 말로 마음을 전하는 것이 좋아요.","answer":"O","reason_options":[{"t":"말로 전하면 도와준 사람의 마음도 따뜻해지니까","correct":true},{"t":"도와준 사람은 고맙다는 말을 싫어하니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["고맙다는 말을 들으면 도와준 사람도 기뻐요.","마음은 고운 말로 표현해야 전해져요.","누구에게 · 어떤 마음 · 왜를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#9','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"내 거 만지지 마!","r":"쓰기 전에 먼저 물어봐 줄래?"},{"l":"느림보야!","r":"천천히 해도 괜찮아."},{"l":"너 때문이야!","r":"같이 방법을 찾아보자."}],"mis":"K2-1-u7-X02","explanation":["「내 거 만지지 마!」 → 「쓰기 전에 먼저 물어봐 줄래?」","「느림보야!」 → 「천천히 해도 괜찮아.」","「너 때문이야!」 → 「같이 방법을 찾아보자.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#10','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"하람 — 「수영을 처음 배울 때 무서웠는데 연습해서 해냈어.」","correct":true},{"t":"채원 — 「내 자전거는 빨간색이야.」","mis":"K2-1-u7-X07"},{"t":"준우 — 「공원에는 비둘기가 많아.」","mis":"K2-1-u7-X07"}],"explanation":["어려웠지만 연습해서 해낸 경험이에요.","다른 보기는 겪은 일이 아니거나 이야기와 상관없어요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#11','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":11,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","correct":true},{"t":"저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","mis":"K2-1-u7-X06"},{"t":"바람이 세게 불자 연이 하늘 높이 올라갔어요.","mis":"K2-1-u7-X06"}],"explanation":["「정말 신났어요」에 느낌이 드러나요.","다른 두 문장은 있었던 일을 말한 문장이에요.","「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 물어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#12','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 「왜 내 앞에 끼어드는 거야?」라고 말할 때 하람이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13','K2-1-u7-X05']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 「왜 내 앞에 끼어드는 거야?」라고 말할 때 하람이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"억울하고 화가 났다","correct":true},{"t":"기쁘고 설렜다","mis":"K2-1-u7-X13"},{"t":"미안하고 부끄러웠다","mis":"K2-1-u7-X05"}],"explanation":["줄을 서 있는데 누가 끼어들어 억울했어요.","다른 보기는 상황에 맞지 않는 마음이에요.","내가 그 사람이라면 어떤 마음일지 생각해요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#13','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"휙","r":"바람이 갑자기 세게 부는 소리"},{"l":"둥실둥실","r":"가볍게 떠오르는 모양"},{"l":"깡충","r":"가볍게 뛰어오르는 모양"}],"mis":"K2-1-u7-X14","explanation":["「휙」 — 바람이 갑자기 세게 부는 소리","「둥실둥실」 — 가볍게 떠오르는 모양","「깡충」 — 가볍게 뛰어오르는 모양"],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#14','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C12',2,'match','auto','직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"match","stem":"직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.","pairs":[{"l":"먹은 것 같아요","r":"먹었어요"},{"l":"신났던 것 같아요","r":"신났어요"},{"l":"예쁜 것 같아요","r":"예뻐요"}],"mis":"K2-1-u7-X17","explanation":["「먹은 것 같아요」 → 「먹었어요」","「신났던 것 같아요」 → 「신났어요」","「예쁜 것 같아요」 → 「예뻐요」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#15','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 지안이의 판 한가운데 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":15,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 지안이의 판 한가운데 칸에 있는 말은 어느 것인가요?","options":[{"t":"같이 놀자","correct":true},{"t":"멋지다","mis":"K2-1-u7-X04"},{"t":"힘내","mis":"K2-1-u7-X04"}],"explanation":["한가운데 칸은 둘째 줄 가운데예요.","다른 보기는 판의 그 자리에 없어요.","판에서 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#16','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C6',2,'error','auto','발표하는 모습이에요. 바르지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X10','K2-1-u7-X18']::text[],false,'{"seq":16,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표하는 모습이에요. 바르지 않은 친구는 누구인가요?","options":[{"t":"서준 — 너무 작은 목소리로 웅얼웅얼 말했어요.","correct":true,"mis_target":"K2-1-u7-X10"},{"t":"아린 — 말끝까지 또박또박 말했어요.","mis":"K2-1-u7-X18"},{"t":"하람 — 듣는 사람을 골고루 바라보며 말했어요.","mis":"K2-1-u7-X18"}],"explanation":["웅얼웅얼 말하면 듣기 어려워요.","다른 두 친구는 바른 자세였어요.","맨 뒤 친구까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#17','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C8',3,'mc','auto','친구가 실수로 내 옷에 우유를 튀겼어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],false,'{"seq":17,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 실수로 내 옷에 우유를 튀겼어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「괜찮아. 일부러 그런 거 아니잖아. 같이 닦자.」","correct":true},{"t":"「너 때문에 옷 다 버렸잖아!」","mis":"K2-1-u7-X12"},{"t":"「축하해!」","mis":"K2-1-u7-X02"}],"explanation":["실수한 친구의 미안한 마음을 헤아렸어요.","화난 기분만 쏟아 내면 다툼이 커져요.","「일부러 그랬을까?」 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#18','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 시무룩하던 하윤이가 생글생글 웃게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],false,'{"seq":18,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시무룩하던 하윤이가 생글생글 웃게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"건우 형이 풍선 줄을 잡아 주어서","correct":true},{"t":"바람이 휙 불어서","mis":"K2-1-u7-X04"},{"t":"건우 형에게 풍선을 주어서","mis":"K2-1-u7-X05"}],"explanation":["형이 풍선을 잡아 주자 웃었어요.","다른 보기는 이야기의 차례나 인물과 맞지 않아요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#19','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 민호가 쪽지에 담은 마음과 그 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X15','K2-1-u7-X04']::text[],false,'{"seq":19,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 민호가 쪽지에 담은 마음과 그 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"죄송한 마음 — 아침에 짜증을 내서","correct":true},{"t":"고마운 마음 — 아침에 짜증을 내서","mis":"K2-1-u7-X15"},{"t":"죄송한 마음 — 학교에 늦어서","mis":"K2-1-u7-X04"}],"explanation":["짜증 낸 일이 죄송했어요.","다른 보기는 쪽지 내용과 맞지 않아요.","누구에게 · 어떤 마음 · 왜를 찾아요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#20','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C4',3,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X07','K2-1-u7-X18']::text[],false,'{"seq":20,"concept":"K2-1-u7-C4","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"소율 — 「시우처럼 나도 처음부터 한 번에 줄넘기를 잘했어.」","correct":true,"mis_target":"K2-1-u7-X07"},{"t":"민준 — 「시우처럼 나도 자꾸 걸렸지만 연습해서 해냈어.」","mis":"K2-1-u7-X18"},{"t":"서아 — 「시우 아빠처럼 언니도 나를 응원해 줬어.」","mis":"K2-1-u7-X18"}],"explanation":["시우는 처음에 넘어졌다가 연습해서 해냈어요.","다른 두 친구는 바르게 비교했어요.","누구의 일인지, 비슷한 마음인지 살펴요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#21','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C12',3,'ox','auto','「오늘 급식에 나온 김치를 먹은 것 같아요.」는 또렷한 말이에요.',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":21,"concept":"K2-1-u7-C12","difficulty":3,"kind":"ox","stem":"「오늘 급식에 나온 김치를 먹은 것 같아요.」는 또렷한 말이에요.","answer":"X","reason_options":[{"t":"내가 직접 먹은 일이니 「먹었어요.」라고 해야 하니까","correct":true},{"t":"「것 같아요」를 붙여야 예의 바른 말이니까","mis":"K2-1-u7-X17"}],"mis":"K2-1-u7-X17","explanation":["직접 한 일은 「먹었어요.」처럼 또렷하게 말해요.","직접 겪은 확실한 일은 또렷하게 말해요.","짐작하는 일에는 「것 같아요」를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#22','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C1',3,'mc','auto','「비켜!」와 「잠깐 지나가도 될까?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「비켜!」와 「잠깐 지나가도 될까?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「잠깐 지나가도 될까?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「비켜!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 고운 말이 듣는 사람의 기분을 좋게 해요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#23','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C5',4,'essay','teacher','처음 해 본 일 가운데 기억에 남는 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"처음 해 본 일 가운데 기억에 남는 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 지난주 토요일에 우리 집 부엌에서 처음으로 달걀 프라이를 만들었어요. 기름이 튀어 무서웠지만 다 만들고 나니 뿌듯했어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#24','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C8',4,'essay','teacher','대화를 읽고 답해 보세요. 은솔이가 사과했을 때 태민이가 화를 냈다면 어떻게 되었을지 쓰고, 태민이의 고운 말이 왜 좋았는지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 은솔이가 사과했을 때 태민이가 화를 냈다면 어떻게 되었을지 쓰고, 태민이의 고운 말이 왜 좋았는지 써 보세요.","answer_guide":{"answer":"예: 태민이가 화를 냈다면 은솔이는 더 미안하고 속상해서 둘이 다투었을 거예요. 태민이가 「괜찮아. 같이 닦자.」라고 해서 은솔이의 마음이 풀리고 함께 문제를 해결할 수 있었어요.","scoring_points":["인물의 마음을 짐작해 썼는가","상황에 맞는 고운 말을 썼는가","대화의 흐름에 맞게 썼는가"]},"explanation":["인물의 마음.","고운 말.","대화 흐름."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#25','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C10',4,'essay','teacher','가족에게 고마운 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"가족에게 고마운 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.","answer_guide":{"answer":"예: 아빠께 — 아빠, 자전거 타는 법을 끝까지 가르쳐 주셔서 고맙습니다. 이제 혼자서도 탈 수 있어요. — 시우 올림","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#1','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C1',1,'mc','auto','고운 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01','K2-1-u7-X03']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"고운 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"듣는 사람을 생각하며 하는 말이에요","correct":true},{"t":"크게 소리치는 말이에요","mis":"K2-1-u7-X01"},{"t":"선생님께만 쓰는 말이에요","mis":"K2-1-u7-X03"}],"explanation":["고운 말은 듣는 사람을 생각하는 말이에요.","다른 보기는 말이 마음에 주는 힘을 생각하지 않았어요.","내가 들었다면 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#2','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「괜찮아, 다시 하면 돼.」","correct":true},{"t":"「또 틀렸어?」","mis":"K2-1-u7-X03"},{"t":"「느림보야.」","mis":"K2-1-u7-X03"}],"explanation":["「괜찮아, 다시 하면 돼.」는 듣는 사람을 생각하는 고운 말이에요.","다른 두 말은 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#3','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 우산이 없어서 현관에 서 있던 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 우산이 없어서 현관에 서 있던 인물은 누구인가요?","options":[{"t":"서준","correct":true},{"t":"아린","mis":"K2-1-u7-X05"},{"t":"엄마","mis":"K2-1-u7-X04"}],"explanation":["서준이가 우산이 없어서 현관에 서 있었어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#4','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 수빈이가 감자를 캔 곳은 어디인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":4,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이가 감자를 캔 곳은 어디인가요?","options":[{"t":"할머니 댁 텃밭","correct":true},{"t":"동네 공원","mis":"K2-1-u7-X05"},{"t":"학교 화단","mis":"K2-1-u7-X04"}],"explanation":["「할머니 댁 텃밭에서」라고 했어요.","다른 보기는 다른 친구의 발표에 나오거나 발표에 없어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#5','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C6',1,'mc','auto','친구의 발표를 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u7-X11']::text[],false,'{"seq":5,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"친구의 발표를 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"발표하는 친구를 바라보며 끝까지 들어요","correct":true},{"t":"짝과 이야기하며 들어요","mis":"K2-1-u7-X11"},{"t":"중간에 끼어들어요","mis":"K2-1-u7-X11"}],"explanation":["끝까지 바라보며 들으면 친구가 힘이 나요.","다른 보기는 바르지 않은 자세예요.","맨 뒤 친구가 잘 듣고 볼 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#6','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C8',1,'mc','auto','친구에게 기쁜 일이 생겼을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"친구에게 기쁜 일이 생겼을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「축하해.」","correct":true},{"t":"「미안해.」","mis":"K2-1-u7-X02"},{"t":"「괜찮아?」","mis":"K2-1-u7-X02"}],"explanation":["기쁜 일에는 「축하해.」라고 해요.","다른 보기는 상황과 맞지 않는 말이에요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#7','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C12',1,'mc','auto','내가 직접 겪은 일을 말할 때 「내 짝 필통은 파란색인 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"내가 직접 겪은 일을 말할 때 「내 짝 필통은 파란색인 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"내 짝 필통은 파란색이에요.","correct":true},{"t":"내 짝 필통은 파란색이었던 것 같아요.","mis":"K2-1-u7-X17"},{"t":"내 짝 필통은 파란색일 것 같아요.","mis":"K2-1-u7-X17"}],"explanation":["직접 겪은 확실한 일은 「내 짝 필통은 파란색이에요.」처럼 또렷하게 말해요.","「것 같아요」를 그대로 두거나 더 붙이면 또렷하지 않아요.","「내가 직접 겪었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#8','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C10',1,'ox','auto','마음 쪽지에는 무엇이 고마운지 까닭을 함께 쓰면 좋아요.',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"마음 쪽지에는 무엇이 고마운지 까닭을 함께 쓰면 좋아요.","answer":"O","reason_options":[{"t":"까닭을 쓰면 마음이 더 잘 전해지니까","correct":true},{"t":"까닭을 쓰면 쪽지가 길어져서 안 되니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["무엇이 고마운지 알면 받는 사람이 더 기뻐요.","마음은 고운 말로 표현해야 전해져요.","누구에게 · 어떤 마음 · 왜를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#9','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"빨리 해!","r":"조금만 서둘러 줄 수 있니?"},{"l":"저리 가!","r":"지금은 혼자 있고 싶어."},{"l":"또 틀렸어?","r":"다음엔 더 잘할 거야."}],"mis":"K2-1-u7-X02","explanation":["「빨리 해!」 → 「조금만 서둘러 줄 수 있니?」","「저리 가!」 → 「지금은 혼자 있고 싶어.」","「또 틀렸어?」 → 「다음엔 더 잘할 거야.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#10','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 아린이와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 아린이와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"태민 — 「짐이 많은 할머니를 도와드리고 뿌듯했어.」","correct":true},{"t":"소율 — 「나는 우산이 세 개 있어.」","mis":"K2-1-u7-X07"},{"t":"현우 — 「비가 오면 길이 미끄러워.」","mis":"K2-1-u7-X07"}],"explanation":["남을 도와 뿌듯했던 경험이에요.","다른 보기는 겪은 일이 아니거나 이야기와 상관없어요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#11','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":11,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"다음에도 할머니와 함께 감자를 캐고 싶어요.","correct":true},{"t":"저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","mis":"K2-1-u7-X06"},{"t":"호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","mis":"K2-1-u7-X06"}],"explanation":["「캐고 싶어요」에 수빈이의 생각이 드러나요.","다른 두 문장은 있었던 일을 말한 문장이에요.","「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 물어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#12','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 물뿌리개를 들 때 민지의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 물뿌리개를 들 때 민지의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"팔이 아프고 힘들었다","correct":true},{"t":"가볍고 신났다","mis":"K2-1-u7-X13"},{"t":"미안하고 부끄러웠다","mis":"K2-1-u7-X13"}],"explanation":["민지는 무거워서 팔이 아프다고 했어요.","다른 보기는 상황에 맞지 않는 마음이에요.","내가 그 사람이라면 어떤 마음일지 생각해요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"물뿌리개가 너무 무거워서 팔이 아파."},{"who":"현우","text":"내가 같이 들어 줄게. 한쪽을 잡을게."},{"who":"민지","text":"고마워, 현우야. 한결 가벼워졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#13','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"엉엉","r":"크게 소리 내어 우는 소리"},{"l":"방긋","r":"소리 없이 살짝 웃는 모양"},{"l":"데굴데굴","r":"큰 물건이 계속 구르는 모양"}],"mis":"K2-1-u7-X14","explanation":["「엉엉」 — 크게 소리 내어 우는 소리","「방긋」 — 소리 없이 살짝 웃는 모양","「데굴데굴」 — 큰 물건이 계속 구르는 모양"],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#14','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C12',2,'match','auto','직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"match","stem":"직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.","pairs":[{"l":"본 것 같아요","r":"봤어요"},{"l":"기뻤던 것 같아요","r":"기뻤어요"},{"l":"좋은 것 같아요","r":"좋아요"}],"mis":"K2-1-u7-X17","explanation":["「본 것 같아요」 → 「봤어요」","「기뻤던 것 같아요」 → 「기뻤어요」","「좋은 것 같아요」 → 「좋아요」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#15','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 로아의 판 첫째 줄 맨 끝 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":15,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 로아의 판 첫째 줄 맨 끝 칸에 있는 말은 어느 것인가요?","options":[{"t":"같이 하자","correct":true},{"t":"고마워","mis":"K2-1-u7-X04"},{"t":"잘했어","mis":"K2-1-u7-X04"}],"explanation":["첫째 줄은 고마워 · 괜찮아 · 같이 하자예요.","다른 보기는 판의 그 자리에 없어요.","판에서 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#16','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C6',2,'error','auto','발표를 듣는 모습이에요. 바르지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X11','K2-1-u7-X18']::text[],false,'{"seq":16,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표를 듣는 모습이에요. 바르지 않은 친구는 누구인가요?","options":[{"t":"건우 — 발표 중간에 「그거 아니야!」 하고 끼어들었어요.","correct":true,"mis_target":"K2-1-u7-X11"},{"t":"예린 — 발표하는 친구를 바라보며 끝까지 들었어요.","mis":"K2-1-u7-X18"},{"t":"도담 — 발표가 끝난 뒤 손을 들고 물어봤어요.","mis":"K2-1-u7-X18"}],"explanation":["중간에 끼어들면 발표가 끊겨요.","다른 두 친구는 바른 자세였어요.","맨 뒤 친구까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#17','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C8',3,'mc','auto','친구가 실수로 내 색종이를 찢었어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],false,'{"seq":17,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 실수로 내 색종이를 찢었어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「괜찮아, 새 색종이로 다시 하자.」","correct":true},{"t":"「너는 맨날 망쳐!」","mis":"K2-1-u7-X12"},{"t":"「찢어 줘서 고마워.」","mis":"K2-1-u7-X02"}],"explanation":["친구의 당황한 마음을 덜어 주었어요.","화난 기분만 쏟아 내면 다툼이 커져요.","「일부러 그랬을까?」 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#18','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 토리가 엉엉 울게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],false,'{"seq":18,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 토리가 엉엉 울게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"겨울에 먹으려고 모은 도토리가 웅덩이에 빠져서","correct":true},{"t":"거북 할아버지가 도토리를 가져가서","mis":"K2-1-u7-X04"},{"t":"도토리 과자가 맛이 없어서","mis":"K2-1-u7-X05"}],"explanation":["모아 둔 도토리가 빠져서 울었어요.","다른 보기는 이야기의 차례나 인물과 맞지 않아요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#19','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":19,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?","options":[{"t":"받는 사람: 지호 · 쓴 사람: 서아","correct":true},{"t":"받는 사람: 서아 · 쓴 사람: 지호","mis":"K2-1-u7-X15"},{"t":"받는 사람: 선생님 · 쓴 사람: 서아","mis":"K2-1-u7-X15"}],"explanation":["첫 줄에 받는 사람, 끝 줄에 쓴 사람이 있어요.","다른 보기는 쪽지 내용과 맞지 않아요.","누구에게 · 어떤 마음 · 왜를 찾아요."],"asset":{"type":"passage","lines":["지호에게","지호야, 어제 내가 필통을 놓고 왔을 때 연필을 빌려줘서 고마워.","덕분에 받아쓰기를 끝까지 할 수 있었어.","다음에는 내가 너를 도와줄게.","— 서아가"],"title":"서아의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#20','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C4',3,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X18']::text[],false,'{"seq":20,"concept":"K2-1-u7-C4","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"현우 — 「아린이처럼 나도 우산이 없어 곤란했어.」","correct":true,"mis_target":"K2-1-u7-X05"},{"t":"다은 — 「서준이처럼 나도 비 오는 날 우산을 빌려 써서 고마웠어.」","mis":"K2-1-u7-X18"},{"t":"지안 — 「아린이처럼 나도 동생 숙제를 도와주고 뿌듯했어.」","mis":"K2-1-u7-X18"}],"explanation":["우산이 없어 곤란했던 인물은 서준이에요.","다른 두 친구는 바르게 비교했어요.","누구의 일인지, 비슷한 마음인지 살펴요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#21','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C12',3,'ox','auto','「친구가 웃는 걸 보니 기분이 좋은 것 같아요.」는 알맞은 말이에요.',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":21,"concept":"K2-1-u7-C12","difficulty":3,"kind":"ox","stem":"「친구가 웃는 걸 보니 기분이 좋은 것 같아요.」는 알맞은 말이에요.","answer":"O","reason_options":[{"t":"친구의 마음은 짐작하는 것이니까","correct":true},{"t":"남의 마음도 언제나 확실히 알 수 있으니까","mis":"K2-1-u7-X17"}],"mis":"K2-1-u7-X17","explanation":["다른 사람의 마음을 짐작할 때는 「것 같아요」를 써요.","직접 겪은 확실한 일은 또렷하게 말해요.","짐작하는 일에는 「것 같아요」를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#22','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C1',3,'mc','auto','「조용히 해!」와 「조금만 작게 말해 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「조용히 해!」와 「조금만 작게 말해 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「조금만 작게 말해 줄래?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「조용히 해!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 고운 말이 듣는 사람의 기분을 좋게 해요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#23','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C5',4,'essay','teacher','친구와 함께한 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"친구와 함께한 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 어제 쉬는 시간에 운동장에서 친구들과 술래잡기를 했어요. 숨이 찰 만큼 뛰었지만 너무 즐거웠어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#24','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C8',4,'essay','teacher','대화를 읽고 답해 보세요. 하람이가 처음 한 말을 지호의 마음을 생각한 고운 말로 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 하람이가 처음 한 말을 지호의 마음을 생각한 고운 말로 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.","answer_guide":{"answer":"예: 「여기부터 줄이야. 뒤에 서 줄래?」 왜냐하면 지호는 줄이 어디까지인지 몰라서 그런 것이니 탓하지 않고 알려 주는 것이 좋기 때문이에요.","scoring_points":["인물의 마음을 짐작해 썼는가","상황에 맞는 고운 말을 썼는가","대화의 흐름에 맞게 썼는가"]},"explanation":["인물의 마음.","고운 말.","대화 흐름."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#25','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C10',4,'essay','teacher','내가 속상하게 한 친구에게 미안한 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"내가 속상하게 한 친구에게 미안한 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.","answer_guide":{"answer":"예: 다은이에게 — 다은아, 어제 네 그림을 보고 이상하다고 해서 미안해. 사실은 색깔이 참 예뻤어. — 지후가","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#1','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C1',1,'mc','auto','「힘내, 할 수 있어!」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"「힘내, 할 수 있어!」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"든든하고 힘이 난다","correct":true},{"t":"창피하고 화가 난다","mis":"K2-1-u7-X01"},{"t":"슬프고 외롭다","mis":"K2-1-u7-X01"}],"explanation":["응원하는 고운 말은 친구에게 힘을 줘요.","다른 보기는 말이 마음에 주는 힘을 생각하지 않았어요.","내가 들었다면 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#2','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「잘했어!」","correct":true},{"t":"「메롱.」","mis":"K2-1-u7-X03"},{"t":"「넌 원래 그래.」","mis":"K2-1-u7-X03"}],"explanation":["「잘했어!」는 듣는 사람을 생각하는 고운 말이에요.","다른 두 말은 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#3','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 「나는 못 하겠어.」라고 말한 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 「나는 못 하겠어.」라고 말한 인물은 누구인가요?","options":[{"t":"시우","correct":true},{"t":"아빠","mis":"K2-1-u7-X05"},{"t":"동생","mis":"K2-1-u7-X04"}],"explanation":["시우가 넘어진 뒤 그렇게 말했어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#4','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 준우가 연을 날린 때는 언제인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":4,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우가 연을 날린 때는 언제인가요?","options":[{"t":"어제 저녁","correct":true},{"t":"지난 토요일","mis":"K2-1-u7-X05"},{"t":"오늘 아침","mis":"K2-1-u7-X04"}],"explanation":["「어제 저녁에」라고 했어요.","다른 보기는 다른 친구의 발표에 나오거나 발표에 없어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#5','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C6',1,'mc','auto','친구의 발표를 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u7-X11']::text[],false,'{"seq":5,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"친구의 발표를 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"궁금한 것은 발표가 끝난 뒤 손을 들고 물어봐요","correct":true},{"t":"궁금하면 바로 소리쳐 물어봐요","mis":"K2-1-u7-X11"},{"t":"책상에 엎드려 들어요","mis":"K2-1-u7-X11"}],"explanation":["발표가 끝난 뒤 손을 들고 물어봐요.","다른 보기는 바르지 않은 자세예요.","맨 뒤 친구가 잘 듣고 볼 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#6','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C8',1,'mc','auto','친구가 넘어져 다쳤을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"친구가 넘어져 다쳤을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「괜찮아? 많이 아프지?」","correct":true},{"t":"「축하해.」","mis":"K2-1-u7-X02"},{"t":"「고마워.」","mis":"K2-1-u7-X02"}],"explanation":["다친 친구에게는 마음을 살피는 말을 해요.","다른 보기는 상황과 맞지 않는 말이에요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#7','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C12',1,'mc','auto','내가 직접 겪은 일을 말할 때 「숙제를 다 한 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"내가 직접 겪은 일을 말할 때 「숙제를 다 한 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"숙제를 다 했어요.","correct":true},{"t":"숙제를 다 했던 것 같아요.","mis":"K2-1-u7-X17"},{"t":"숙제를 다 한 것도 같아요.","mis":"K2-1-u7-X17"}],"explanation":["직접 겪은 확실한 일은 「숙제를 다 했어요.」처럼 또렷하게 말해요.","「것 같아요」를 그대로 두거나 더 붙이면 또렷하지 않아요.","「내가 직접 겪었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#8','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C10',1,'ox','auto','미안한 마음은 쪽지에 「미안해.」 한 마디만 쓰면 충분해요.',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"미안한 마음은 쪽지에 「미안해.」 한 마디만 쓰면 충분해요.","answer":"X","reason_options":[{"t":"무엇이 미안한지 함께 써야 마음이 잘 전해지니까","correct":true},{"t":"미안한 까닭은 숨겨야 하니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["무엇이 미안한지 쓰면 사과가 진심으로 전해져요.","마음은 고운 말로 표현해야 전해져요.","누구에게 · 어떤 마음 · 왜를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#9','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"문 닫아!","r":"문 좀 닫아 줄래?"},{"l":"그만해!","r":"조금만 조용히 해 줄래?"},{"l":"줘!","r":"나도 써 봐도 될까?"}],"mis":"K2-1-u7-X02","explanation":["「문 닫아!」 → 「문 좀 닫아 줄래?」","「그만해!」 → 「조금만 조용히 해 줄래?」","「줘!」 → 「나도 써 봐도 될까?」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#10','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"민준 — 「줄넘기에 자꾸 걸렸지만 계속 연습해서 성공했어.」","correct":true},{"t":"서아 — 「우리 아빠는 키가 커.」","mis":"K2-1-u7-X07"},{"t":"지호 — 「자전거 바퀴는 둥글어.」","mis":"K2-1-u7-X07"}],"explanation":["처음엔 실패했지만 끝내 해낸 경험이에요.","다른 보기는 겪은 일이 아니거나 이야기와 상관없어요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#11','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":11,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"다음에는 더 큰 연을 만들어 날리고 싶어요.","correct":true},{"t":"저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","mis":"K2-1-u7-X06"},{"t":"바람이 세게 불자 연이 하늘 높이 올라갔어요.","mis":"K2-1-u7-X06"}],"explanation":["「날리고 싶어요」에 준우의 생각이 드러나요.","다른 두 문장은 있었던 일을 말한 문장이에요.","「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 물어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#12','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 「일부러 그런 거 아닌데…….」라고 말할 때 예린이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 「일부러 그런 거 아닌데…….」라고 말할 때 예린이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"미안하면서도 억울하다","correct":true},{"t":"신나고 자랑스럽다","mis":"K2-1-u7-X13"},{"t":"블록 탑이 무너져 기쁘다","mis":"K2-1-u7-X13"}],"explanation":["일부러가 아니어서 억울하고, 탑이 무너져 미안했을 거예요.","다른 보기는 상황에 맞지 않는 마음이에요.","내가 그 사람이라면 어떤 마음일지 생각해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#13','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"쏙","r":"좁은 데서 쉽게 빠져나오는 모양"},{"l":"생글생글","r":"눈과 입으로 귀엽게 웃는 모양"},{"l":"둥실둥실","r":"가볍게 떠오르는 모양"}],"mis":"K2-1-u7-X14","explanation":["「쏙」 — 좁은 데서 쉽게 빠져나오는 모양","「생글생글」 — 눈과 입으로 귀엽게 웃는 모양","「둥실둥실」 — 가볍게 떠오르는 모양"],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#14','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C12',2,'match','auto','직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"match","stem":"직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.","pairs":[{"l":"읽은 것 같아요","r":"읽었어요"},{"l":"무서웠던 것 같아요","r":"무서웠어요"},{"l":"시원한 것 같아요","r":"시원해요"}],"mis":"K2-1-u7-X17","explanation":["「읽은 것 같아요」 → 「읽었어요」","「무서웠던 것 같아요」 → 「무서웠어요」","「시원한 것 같아요」 → 「시원해요」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#15','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 지안이의 판 셋째 줄 맨 끝 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":15,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 지안이의 판 셋째 줄 맨 끝 칸에 있는 말은 어느 것인가요?","options":[{"t":"최고야","correct":true},{"t":"미안해","mis":"K2-1-u7-X04"},{"t":"사랑해","mis":"K2-1-u7-X04"}],"explanation":["셋째 줄은 미안해 · 힘내 · 최고야예요.","다른 보기는 판의 그 자리에 없어요.","판에서 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#16','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C6',2,'error','auto','발표를 듣는 모습이에요. 바르지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X11','K2-1-u7-X18']::text[],false,'{"seq":16,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표를 듣는 모습이에요. 바르지 않은 친구는 누구인가요?","options":[{"t":"은솔 — 발표하는 동안 짝과 귓속말을 했어요.","correct":true,"mis_target":"K2-1-u7-X11"},{"t":"하늘 — 고개를 끄덕이며 끝까지 들었어요.","mis":"K2-1-u7-X18"},{"t":"민지 — 발표가 끝나자 박수를 쳤어요.","mis":"K2-1-u7-X18"}],"explanation":["귓속말을 하면 발표를 놓쳐요.","다른 두 친구는 바른 자세였어요.","맨 뒤 친구까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#17','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C8',3,'mc','auto','친구가 줄을 잘못 알고 내 앞에 섰어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],false,'{"seq":17,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 줄을 잘못 알고 내 앞에 섰어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여기부터 줄이야. 헷갈렸지? 뒤에 서 줄래?」","correct":true},{"t":"「왜 새치기해? 나쁜 애야!」","mis":"K2-1-u7-X12"},{"t":"「하하, 줄도 몰라?」","mis":"K2-1-u7-X03"}],"explanation":["헷갈린 친구의 마음을 헤아리며 부탁했어요.","화난 기분만 쏟아 내면 다툼이 커져요.","「일부러 그랬을까?」 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#18','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 하윤이가 시무룩해진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],false,'{"seq":18,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 하윤이가 시무룩해진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"풍선이 날아가 나뭇가지에 걸려서","correct":true},{"t":"건우 형이 풍선을 터뜨려서","mis":"K2-1-u7-X04"},{"t":"풍선을 하나 더 받아서","mis":"K2-1-u7-X05"}],"explanation":["풍선을 놓쳐 나뭇가지에 걸려서 시무룩했어요.","다른 보기는 이야기의 차례나 인물과 맞지 않아요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#19','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 민호가 앞으로 하겠다고 다짐한 일은 어느 것인가요?',ARRAY['K2-1-u7-X15','K2-1-u7-X04']::text[],false,'{"seq":19,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 민호가 앞으로 하겠다고 다짐한 일은 어느 것인가요?","options":[{"t":"내일부터 일찍 일어나기","correct":true},{"t":"엄마께 선물 사 드리기","mis":"K2-1-u7-X15"},{"t":"숙제 먼저 하기","mis":"K2-1-u7-X04"}],"explanation":["쪽지에 일찍 일어나겠다고 썼어요.","다른 보기는 쪽지 내용과 맞지 않아요.","누구에게 · 어떤 마음 · 왜를 찾아요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#20','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C4',3,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X07','K2-1-u7-X18']::text[],false,'{"seq":20,"concept":"K2-1-u7-C4","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"하준 — 「시우처럼 나도 아빠를 도와드리고 칭찬받았어.」","correct":true,"mis_target":"K2-1-u7-X07"},{"t":"채원 — 「시우처럼 나도 처음엔 무서웠지만 끝까지 해냈어.」","mis":"K2-1-u7-X18"},{"t":"지우 — 「시우처럼 나도 넘어져서 무릎이 까진 적이 있어.」","mis":"K2-1-u7-X18"}],"explanation":["시우는 도와드린 것이 아니라 어려운 일을 연습해서 해냈어요.","다른 두 친구는 바르게 비교했어요.","누구의 일인지, 비슷한 마음인지 살펴요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#21','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C12',3,'ox','auto','「내 생일은 오월인 것 같아요.」는 또렷한 말이에요.',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":21,"concept":"K2-1-u7-C12","difficulty":3,"kind":"ox","stem":"「내 생일은 오월인 것 같아요.」는 또렷한 말이에요.","answer":"X","reason_options":[{"t":"내 생일은 확실히 아는 일이니 「오월이에요.」라고 해야 하니까","correct":true},{"t":"「것 같아요」를 붙여야 겸손한 말이니까","mis":"K2-1-u7-X17"}],"mis":"K2-1-u7-X17","explanation":["확실히 아는 일은 「오월이에요.」처럼 또렷하게 말해요.","직접 겪은 확실한 일은 또렷하게 말해요.","짐작하는 일에는 「것 같아요」를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#22','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C1',3,'mc','auto','「빨리 와!」와 「조금만 서둘러 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「빨리 와!」와 「조금만 서둘러 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「조금만 서둘러 줄래?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「빨리 와!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 고운 말이 듣는 사람의 기분을 좋게 해요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#23','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C5',4,'essay','teacher','밖에 나가서 본 것이 기억에 남는 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"밖에 나가서 본 것이 기억에 남는 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 지난 방학에 수목원에서 커다란 연꽃을 보았어요. 접시보다 큰 꽃잎을 보고 깜짝 놀랐어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#24','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C8',4,'essay','teacher','대화를 읽고 답해 보세요. 내가 현우라면 민지에게 어떤 고운 말을 하며 도와줄지 쓰고, 민지가 고맙다고 할 때 대답할 고운 말도 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 내가 현우라면 민지에게 어떤 고운 말을 하며 도와줄지 쓰고, 민지가 고맙다고 할 때 대답할 고운 말도 써 보세요.","answer_guide":{"answer":"예: 「무겁지? 내가 같이 들어 줄게.」 민지가 고맙다고 하면 「도움이 되어서 나도 기뻐.」라고 대답하겠어요.","scoring_points":["인물의 마음을 짐작해 썼는가","상황에 맞는 고운 말을 썼는가","대화의 흐름에 맞게 썼는가"]},"explanation":["인물의 마음.","고운 말.","대화 흐름."],"asset":{"type":"speech","turns":[{"who":"민지","text":"물뿌리개가 너무 무거워서 팔이 아파."},{"who":"현우","text":"내가 같이 들어 줄게. 한쪽을 잡을게."},{"who":"민지","text":"고마워, 현우야. 한결 가벼워졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#25','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C10',4,'essay','teacher','기쁜 일이 생긴 친구에게 축하하는 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"기쁜 일이 생긴 친구에게 축하하는 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.","answer_guide":{"answer":"예: 로아에게 — 로아야, 받아쓰기에서 백 점 받은 거 축하해. 날마다 연습하더니 정말 멋지다. — 은솔이가","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C1','kor',2,1,'u8',1,'여러 가지 작품과 감상의 즐거움 — 시·이야기·인형극의 특징을 알고, 작품을 즐기며 떠오른 생각이나 느낌을 친구와 나누는 것이 감상임을 알기(느낌은 사람마다 다를 수 있음)',ARRAY['2국05-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C2','kor',2,1,'u8',1,'작품 속 인물의 마음 상상하기 — 마음이 글에 직접 나오지 않아도 인물이 처한 상황·말·행동을 근거로 마음을 상상하고 그렇게 생각한 까닭을 말하기',ARRAY['2국05-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C3','kor',2,1,'u8',3,'시를 여러 방법으로 낭송하기 — 시의 리듬과 분위기를 살려 소리 내어 읽고, 주고받기·몸짓 넣기·박자 넣기처럼 방법을 바꾸어 낭송하며 느낌이 달라짐을 즐기기',ARRAY['2국05-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C4','kor',2,1,'u8',3,'시 속 행동과 흉내 내는 말로 마음 짐작하기 — 「반갑다」 같은 말이 없어도 시 속 인물의 행동과 흉내 내는 말(흔들흔들·살금살금·새근새근)에서 마음을 짐작하기',ARRAY['2국05-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C5','kor',2,1,'u8',5,'이야기 속 인물의 마음과 그 변화 — 인물의 말과 행동에서 마음을 짐작하고, 일이 일어남에 따라 마음이 어떻게 바뀌는지와 무엇 때문에 바뀌었는지 알기',ARRAY['2국05-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C6','kor',2,1,'u8',5,'기억에 남는 장면과 까닭 표현하기 — 작품에서 기억에 남는 장면을 고르고 그 까닭과 비슷한 내 경험을 함께 글·그림·말로 표현하기',ARRAY['2국05-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C7','kor',2,1,'u8',7,'인형극의 특징과 인물의 마음 짐작하기 — 인형극(그림자·막대·손가락 인형극)은 인형의 말·움직임·목소리로 이야기를 보여 주며, 목소리의 크기·빠르기와 움직임에서 인물의 마음을 짐작할 수 있음을 알기',ARRAY['2국05-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C8','kor',2,1,'u8',7,'일이 일어난 차례 정리하기 — 장소가 바뀌는 곳을 기준으로 장소마다 일어난 일을 차례대로 정리하여 줄거리를 파악하기',ARRAY['2국05-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C9','kor',2,1,'u8',9,'인형극 속 인물의 말과 행동 찾으며 감상하기 — 「의좋은 형제」처럼 인형극을 보며 인물이 무엇을 왜 했는지 말과 행동을 찾고 인상 깊은 장면을 떠올리기',ARRAY['2국05-03']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C10','kor',2,1,'u8',9,'인물에게 편지 쓰기 — 작품 속 인물에게 하고 싶은 말과 그 까닭을 받는 인물·쓴 사람이 드러나게 솔직한 마음으로 편지에 담기',ARRAY['2국05-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C11','kor',2,1,'u8',9,'감상을 발표하고 견주어 듣기 — 감상을 또박또박 까닭과 함께 발표하고, 친구의 감상은 좋은 점을 찾으며 끝까지 듣고 내 감상과 비슷한 점·다른 점을 견주기',ARRAY['2국01-05']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C12','kor',2,1,'u8',12,'인형극 준비하고 공연·관람하기 — 보여 줄 장면과 역할을 정하고 막대 인형을 간단히 만들어(그리기→오리기→막대 붙이기) 인물의 마음을 살린 목소리·움직임으로 공연하며, 바른 자세로 관람하고 감상을 나누기',ARRAY['2국05-03']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C13','kor',2,1,'u8',14,'받침이 넘어가는 소리 — 받침 뒤에 「ㅇ」으로 시작하는 글자가 오면 받침이 뒤 글자의 첫소리로 넘어가 소리 남을 알고(구름이[구르미]) 자연스럽게 읽기',ARRAY['2국04-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X01','kor',2,'u8',ARRAY['K2-1-u8-C1','K2-1-u8-C7']::text[],'시·이야기·인형극의 특징을 헷갈리거나 작품을 감상한 경험이 아닌 일을 감상 경험으로 여긴다','「소리 내어 낭송? 겪은 일을 차례로? 인형이 나와 보여 줌?」 하나씩 맞춰 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X02','kor',2,'u8',ARRAY['K2-1-u8-C1','K2-1-u8-C3','K2-1-u8-C6','K2-1-u8-C8','K2-1-u8-C11']::text[],'감상에 정답이 하나뿐이라고 여기거나, 빨리 읽기·외우기·잘하기가 감상에서 가장 중요하다고 여긴다','「나는 어떤 느낌이었지?」 먼저 묻고 친구 느낌도 들어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X03','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C4','K2-1-u8-C5','K2-1-u8-C6','K2-1-u8-C8','K2-1-u8-C9','K2-1-u8-C10','K2-1-u8-C11']::text[],'작품에 없는 내용을 있다고 하거나 작품 내용을 놓친다','작품에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X04','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C5','K2-1-u8-C6','K2-1-u8-C8','K2-1-u8-C9','K2-1-u8-C12']::text[],'인물을 뒤바꿔 다른 인물이 한 말·행동·마음을 말한다','누가 한 말·행동인지 이름에 동그라미 치고 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X05','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C4','K2-1-u8-C5','K2-1-u8-C7','K2-1-u8-C9']::text[],'상황에 맞지 않게 인물의 마음을 짐작하거나, 마음이 글에 직접 쓰여 있지 않으면 짐작할 수 없다고 여긴다','내가 그 인물이라면 그때 어떤 마음일지 바꿔 생각해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X06','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C4','K2-1-u8-C5','K2-1-u8-C9']::text[],'마음을 짐작한 까닭이나 비슷한 경험으로 작품과 상관없는 것(옷 색깔·쪽수·마음이 드러나지 않는 부분)을 든다','「이 말·행동에 마음이 보이나?」 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X07','kor',2,'u8',ARRAY['K2-1-u8-C4']::text[],'흉내 내는 말의 뜻을 헷갈리거나 흉내 내는 말과 다른 낱말을 가리지 못한다','흉내 내는 말을 몸짓으로 따라 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X08','kor',2,'u8',ARRAY['K2-1-u8-C3']::text[],'낭송 방법(주고받기·몸짓·박자)을 헷갈리거나 시의 분위기와 맞지 않게 낭송한다','시가 조용한 시인지 신나는 시인지 먼저 정하고 목소리 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X09','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C5']::text[],'인물의 마음이 바뀌는 것을 놓치거나(처음 마음 = 끝 마음) 바뀐 차례를 거꾸로 짚는다','처음·가운데·끝 장면마다 마음을 따로 적어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X10','kor',2,'u8',ARRAY['K2-1-u8-C6','K2-1-u8-C11']::text[],'감상을 말할 때 장면만 말하고 까닭을 빠뜨리거나, 느낌 없이 줄거리만 옮긴다','「왜냐하면」을 붙여 한 번 더 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X11','kor',2,'u8',ARRAY['K2-1-u8-C7']::text[],'인형극의 특징(인형·움직임·목소리)과 종류(그림자·막대·손가락)를 헷갈린다','인형을 무엇으로 움직이는지 떠올려 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X12','kor',2,'u8',ARRAY['K2-1-u8-C7','K2-1-u8-C12']::text[],'목소리의 크기·빠르기·움직임과 인물의 마음의 짝을 헷갈린다(떨리는 작은 목소리 → 신남)','그 목소리로 직접 말해 보고 어떤 마음인지 느껴 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X13','kor',2,'u8',ARRAY['K2-1-u8-C8']::text[],'일이 일어난 차례나 장소가 바뀐 차례를 뒤섞는다','장소가 바뀌는 곳에 줄을 긋고 번호 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X14','kor',2,'u8',ARRAY['K2-1-u8-C10']::text[],'인물에게 쓰는 편지에서 받는 인물·하고 싶은 말·까닭·쓴 사람을 빠뜨리거나 헷갈리고, 작품과 상관없는 사람에게 쓴다','누구에게 · 하고 싶은 말 · 왜 · 누가 — 네 가지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X15','kor',2,'u8',ARRAY['K2-1-u8-C11']::text[],'바르지 않은 발표·듣기 자세를 괜찮다고 여기거나, 나와 다른 친구의 감상을 틀렸다고 여긴다','친구 감상에서 좋은 점 하나 먼저 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X16','kor',2,'u8',ARRAY['K2-1-u8-C12']::text[],'인형극을 준비·공연할 때 인형 꾸미기에만 매달리거나 역할을 나누지 않고, 인물의 마음을 살리지 않고 대사를 읽는다','「인형보다 놀이!」 — 장면·역할·마음 담은 대사 먼저 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X17','kor',2,'u8',ARRAY['K2-1-u8-C12']::text[],'인형극을 볼 때의 약속(조용히 바른 자세로 보기·끝난 뒤 좋았던 점 나누기)을 지키지 않아도 된다고 여긴다','내가 무대에 섰다면 관객이 어떻게 해 주면 좋을지 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X18','kor',2,'u8',ARRAY['K2-1-u8-C13']::text[],'받침이 넘어가는 소리를 헷갈린다 — 「ㅇ」 앞에서도 받침을 그대로 읽거나, 「ㅇ」이 아닌 글자 앞에서도 받침을 넘겨 읽는다','받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X19','kor',2,'u8',ARRAY['K2-1-u8-C1','K2-1-u8-C2','K2-1-u8-C3','K2-1-u8-C4','K2-1-u8-C5','K2-1-u8-C6','K2-1-u8-C7','K2-1-u8-C8','K2-1-u8-C9','K2-1-u8-C10','K2-1-u8-C11','K2-1-u8-C12','K2-1-u8-C13']::text[],'묻는 말을 거꾸로 읽는다 — 알맞지 않은↔알맞은, 잘못↔바르게, 아닌↔맞는','물음의 「않은·잘못·아닌」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#1','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C1',1,'mc','auto','소리 내어 낭송하며 말의 리듬을 즐기는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],true,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"소리 내어 낭송하며 말의 리듬을 즐기는 작품은 어느 것인가요?","options":[{"t":"시","correct":true},{"t":"이야기","mis":"K2-1-u8-X01"},{"t":"인형극","mis":"K2-1-u8-X01"}],"explanation":["시는 짧은 말에 리듬을 담아 소리 내어 낭송하며 즐겨요.","이야기는 인물이 겪은 일을 차례대로 들려주는 작품이에요.","인형극은 인형이 나와 말과 행동으로 보여 주는 작품이에요."],"variant_rule":{"alt":[{"stem":"인형이 나와 말과 행동으로 이야기를 보여 주는 작품은 어느 것인가요?","options":[{"t":"인형극","correct":true},{"t":"시","mis":"K2-1-u8-X01"},{"t":"일기","mis":"K2-1-u8-X01"}],"explanation":["인형이 나와 이야기를 보여 주는 것이 인형극이에요.","시는 리듬을 살려 낭송하는 작품이에요.","일기는 내가 겪은 일을 쓴 글이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#2','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C1',1,'ox','auto','같은 작품을 읽어도 친구와 내 느낌이 서로 다를 수 있어요.',ARRAY['K2-1-u8-X02']::text[],true,'{"seq":2,"concept":"K2-1-u8-C1","difficulty":1,"kind":"ox","stem":"같은 작품을 읽어도 친구와 내 느낌이 서로 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 겪은 일과 생각이 달라서 느낌도 다를 수 있으니까","correct":true},{"t":"작품을 읽은 느낌은 정답이 하나뿐이니까","mis":"K2-1-u8-X02"}],"mis":"K2-1-u8-X02","explanation":["같은 이야기도 누구는 슬프고 누구는 감동적일 수 있어요.","느낌이 다른 것은 자연스러운 일이에요.","친구의 느낌도 들어 보며 감상을 나눠요."],"variant_rule":{"alt":[{"stem":"작품을 감상할 때 가장 중요한 것은 빨리 다 읽는 것이에요.","answer":"X","reason_options":[{"t":"작품을 즐기고 떠오른 느낌을 나누는 것이 가장 중요하니까","correct":true},{"t":"빨리 읽어야 감상을 잘한 것이니까","mis":"K2-1-u8-X02"}],"explanation":["감상은 작품을 즐기는 것이에요.","빨리 읽는 것보다 느낌을 떠올리는 것이 중요해요.","느낀 점을 친구와 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#3','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',1,'mc','auto','글을 읽고 답해 보세요. 박에서 쌀과 보물이 쏟아져 나올 때 흥부의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],true,'{"seq":3,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 박에서 쌀과 보물이 쏟아져 나올 때 흥부의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"깜짝 놀라고 기쁘다","correct":true},{"t":"슬프고 외롭다","mis":"K2-1-u8-X05"},{"t":"화가 나고 억울하다","mis":"K2-1-u8-X05"}],"explanation":["배고프던 흥부네에 쌀과 보물이 쏟아졌으니 놀랍고 기뻤을 거예요.","슬프거나 화가 날 까닭이 없어요.","내가 흥부라면 어땠을지 떠올려요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 부어도 부어도 물이 줄줄 새어 나갈 때 콩쥐의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하고 막막하다","correct":true},{"t":"신나고 즐겁다","mis":"K2-1-u8-X05"},{"t":"자랑스럽다","mis":"K2-1-u8-X05"}],"explanation":["아무리 부어도 물이 차지 않으니 속상하고 막막했을 거예요.","신나거나 자랑스러울 까닭이 없어요.","내가 콩쥐라면 어땠을지 떠올려요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#4','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',1,'mc','auto','인물의 마음이 글에 직접 쓰여 있지 않을 때 무엇을 보고 마음을 상상하면 좋을까요?',ARRAY['K2-1-u8-X06']::text[],true,'{"seq":4,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"인물의 마음이 글에 직접 쓰여 있지 않을 때 무엇을 보고 마음을 상상하면 좋을까요?","options":[{"t":"인물이 처한 상황과 인물의 말·행동","correct":true},{"t":"인물이 입은 옷의 색깔","mis":"K2-1-u8-X06"},{"t":"책의 쪽수","mis":"K2-1-u8-X06"}],"explanation":["상황·말·행동에 인물의 마음이 담겨 있어요.","옷 색깔에는 마음이 드러나지 않아요.","쪽수는 마음과 상관없어요."],"variant_rule":{"alt":[{"stem":"작품 속 인물의 마음을 상상하며 읽으면 좋은 점은 무엇인가요?","options":[{"t":"작품이 더 실감 나고 재미있어져요","correct":true},{"t":"작품을 빨리 끝낼 수 있어요","mis":"K2-1-u8-X02"},{"t":"인물의 이름을 바꿀 수 있어요","mis":"K2-1-u8-X06"}],"explanation":["인물이 되어 보면 장면이 생생하게 느껴져요.","감상은 빨리 끝내는 것이 아니에요.","이름을 바꾸는 것과는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#5','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C1',2,'match','auto','작품과 그 특징을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C1","difficulty":2,"kind":"match","stem":"작품과 그 특징을 알맞게 이어 보세요.","pairs":[{"l":"시","r":"짧은 말에 리듬을 담아 쓴 글"},{"l":"이야기","r":"인물이 겪은 일을 차례대로 들려주는 글"},{"l":"인형극","r":"인형이 나와 말과 행동으로 보여 주는 극"}],"mis":"K2-1-u8-X01","explanation":["시는 리듬이 살아 있는 짧은 글이에요.","이야기에는 인물과 일어난 일이 있어요.","인형극은 인형이 움직이며 보여 줘요."],"variant_rule":{"alt":[{"stem":"작품과 그 작품을 즐기는 방법을 알맞게 이어 보세요.","pairs":[{"l":"시","r":"소리 내어 리듬을 살려 낭송하기"},{"l":"이야기","r":"인물의 마음을 상상하며 읽기"},{"l":"인형극","r":"인형의 움직임과 목소리를 보고 듣기"}],"explanation":["시는 소리 내어 낭송하면 더 즐거워요.","이야기는 인물이 되어 읽어 봐요.","인형극은 움직임과 목소리에 마음이 담겨 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#6','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',2,'mc','auto','글을 읽고 답해 보세요. 흥부가 무척 놀랐다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u8-X06','K2-1-u8-X04']::text[],true,'{"seq":6,"concept":"K2-1-u8-C2","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 흥부가 무척 놀랐다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"눈이 휘둥그레져 입을 다물지 못했어요","correct":true},{"t":"지붕 위에 커다란 박이 열렸어요","mis":"K2-1-u8-X06"},{"t":"아이들은 덩실덩실 춤을 추었어요","mis":"K2-1-u8-X04"}],"explanation":["눈이 휘둥그레지고 입을 다물지 못한 행동에 놀란 마음이 드러나요.","박이 열린 것은 일어난 일이지 흥부의 행동이 아니에요.","춤을 춘 것은 흥부가 아니라 아이들이에요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 콩쥐가 무척 속상했다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요","correct":true},{"t":"물이 찰랑찰랑 차올랐어요","mis":"K2-1-u8-X06"},{"t":"「내가 구멍을 막아 줄게.」라고 말했어요","mis":"K2-1-u8-X04"}],"explanation":["주저앉아 우는 행동에 속상한 마음이 드러나요.","물이 차오른 것은 마음이 드러나는 행동이 아니에요.","구멍을 막아 준다고 한 것은 두꺼비예요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#7','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',2,'mc','auto','글을 읽고 답해 보세요. 두꺼비를 꼭 끌어안으며 말할 때 콩쥐의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],true,'{"seq":7,"concept":"K2-1-u8-C2","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 두꺼비를 꼭 끌어안으며 말할 때 콩쥐의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"고맙고 기쁘다","correct":true},{"t":"무섭고 싫다","mis":"K2-1-u8-X05"},{"t":"미안하고 부끄럽다","mis":"K2-1-u8-X05"}],"explanation":["어려울 때 도와준 두꺼비가 고마웠을 거예요.","싫었다면 꼭 끌어안지 않았을 거예요.","콩쥐가 잘못한 일은 없어요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 서로 얼싸안고 덩실덩실 춤을 출 때 흥부네 아이들의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"기쁘고 신나다","correct":true},{"t":"무섭고 떨리다","mis":"K2-1-u8-X05"},{"t":"졸리고 심심하다","mis":"K2-1-u8-X05"}],"explanation":["배고프던 아이들에게 쌀이 생겨 기쁘고 신났을 거예요.","무서웠다면 춤을 추지 않았을 거예요.","졸리거나 심심할 까닭이 없어요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#8','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',2,'error','auto','글을 읽고 콩쥐의 마음을 상상했어요. 잘못 상상한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C2","difficulty":2,"kind":"error","stem":"글을 읽고 콩쥐의 마음을 상상했어요. 잘못 상상한 친구는 누구인가요?","options":[{"t":"하린 — 「물이 새어 나갈 때 콩쥐는 신이 났을 거야.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"지안 — 「물이 새어 나갈 때 콩쥐는 막막했을 거야.」","mis":"K2-1-u8-X19"},{"t":"윤호 — 「두꺼비가 나타났을 때 콩쥐는 안심이 됐을 거야.」","mis":"K2-1-u8-X19"}],"explanation":["물이 자꾸 새는데 신이 났을 리 없어요. 콩쥐는 울고 있었어요.","지안이와 윤호는 상황에 맞게 상상했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 흥부의 마음을 상상했어요. 잘못 상상한 친구는 누구인가요?","options":[{"t":"도담 — 「보물이 쏟아질 때 흥부는 실망했을 거야.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"소율 — 「보물이 쏟아질 때 흥부는 꿈인가 싶었을 거야.」","mis":"K2-1-u8-X19"},{"t":"민호 — 「박을 탈 때 흥부는 무엇이 나올지 설렜을 거야.」","mis":"K2-1-u8-X19"}],"explanation":["입을 다물지 못할 만큼 놀란 흥부가 실망했을 리 없어요.","소율이와 민호는 상황에 맞게 상상했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#9','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C1',2,'sa','auto','짧은 말에 리듬을 담아 쓰고 소리 내어 낭송하는 작품을 한 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C1","difficulty":2,"kind":"sa","stem":"짧은 말에 리듬을 담아 쓰고 소리 내어 낭송하는 작품을 한 글자로 써 보세요.","answer":["시"],"explanation":["시는 낭송하며 리듬을 즐기는 작품이에요.","짧은 말 속에 느낌이 담겨 있어요.","이 단원에서 「손 흔들기」 같은 시를 만나요."],"variant_rule":{"alt":[{"stem":"인형이 나와 말과 행동으로 이야기를 보여 주는 작품을 세 글자로 써 보세요.","answer":["인형극"],"explanation":["인형이 나와 보여 주는 극이 인형극이에요.","인형의 목소리와 움직임으로 이야기를 보여 줘요.","그림자·막대·손가락 인형극이 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#10','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',3,'mc','auto','글을 읽고 답해 보세요. 내가 흥부라면 박이 쩍 갈라지는 순간 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X03']::text[],true,'{"seq":10,"concept":"K2-1-u8-C2","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 내가 흥부라면 박이 쩍 갈라지는 순간 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「우아, 이게 다 뭐야! 꿈만 같아!」","correct":true},{"t":"「박이 무거워서 귀찮기만 하네.」","mis":"K2-1-u8-X05"},{"t":"「아이들아, 울지 마라. 다 괜찮다.」","mis":"K2-1-u8-X03"}],"explanation":["쌀과 보물이 쏟아지는 놀랍고 기쁜 순간에 어울리는 말이에요.","귀찮아하는 마음은 이 장면과 맞지 않아요.","아이들은 울지 않고 춤을 추었어요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 내가 콩쥐라면 두꺼비가 구멍을 막아 줄 때 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「두꺼비야, 덕분에 물을 채울 수 있겠어!」","correct":true},{"t":"「두꺼비는 무서우니까 저리 가!」","mis":"K2-1-u8-X05"},{"t":"「새어머니, 고맙습니다!」","mis":"K2-1-u8-X04"}],"explanation":["도와준 두꺼비에게 고마운 마음을 전하는 말이에요.","콩쥐는 두꺼비를 꼭 끌어안았으니 무서워하지 않았어요.","구멍을 막아 준 것은 새어머니가 아니라 두꺼비예요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#1','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C1',2,'mc','auto','작품을 감상한 경험을 말한 친구는 누구인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":2,"kind":"mc","stem":"작품을 감상한 경험을 말한 친구는 누구인가요?","options":[{"t":"서아 — 「도서관에서 이야기책을 읽고 주인공이 불쌍해서 눈물이 났어.」","correct":true},{"t":"준우 — 「어제 내 책상 서랍을 정리했어.」","mis":"K2-1-u8-X01"},{"t":"하늘 — 「문구점에서 인형을 하나 샀어.」","mis":"K2-1-u8-X01"}],"explanation":["작품을 읽고 느낌이 떠오른 경험이에요.","서랍 정리는 작품 감상이 아니에요.","인형을 산 일은 인형극을 본 경험이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#2','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',2,'mc','auto','글을 읽고 답해 보세요. 새어머니가 콩쥐에게 시킨 일은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 새어머니가 콩쥐에게 시킨 일은 무엇인가요?","options":[{"t":"밑 빠진 독에 물을 가득 채우기","correct":true},{"t":"볏단을 옮기기","mis":"K2-1-u8-X03"},{"t":"박을 타기","mis":"K2-1-u8-X03"}],"explanation":["새어머니는 밑 빠진 독에 물을 채우라고 했어요.","볏단을 옮기는 일은 다른 옛이야기에 나와요.","박을 탄 것은 흥부네예요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#3','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C1',3,'ox','auto','같은 작품을 보고 친구가 나와 다르게 느꼈다면 친구의 감상이 틀린 거예요.',ARRAY['K2-1-u8-X02']::text[],false,'{"seq":3,"concept":"K2-1-u8-C1","difficulty":3,"kind":"ox","stem":"같은 작품을 보고 친구가 나와 다르게 느꼈다면 친구의 감상이 틀린 거예요.","answer":"X","reason_options":[{"t":"겪은 일과 생각이 달라 느낌이 다를 수 있으니까","correct":true},{"t":"작품의 느낌은 하나로 정해져 있으니까","mis":"K2-1-u8-X02"}],"mis":"K2-1-u8-X02","explanation":["느낌이 다른 것은 틀린 것이 아니에요.","친구의 느낌을 들으면 작품을 더 넓게 볼 수 있어요.","서로의 감상을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#4','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',3,'mc','auto','글을 읽고 답해 보세요. 「슬근슬근 톱질하세!」 노래하며 박을 탈 때 흥부와 아내의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":4,"concept":"K2-1-u8-C2","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「슬근슬근 톱질하세!」 노래하며 박을 탈 때 흥부와 아내의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무엇이 나올지 설레고 즐겁다","correct":true},{"t":"지루하고 하기 싫다","mis":"K2-1-u8-X05"},{"t":"무섭고 걱정된다","mis":"K2-1-u8-X05"}],"explanation":["노래를 부르며 박을 탔으니 설레고 즐거웠을 거예요.","하기 싫었다면 노래하지 않았을 거예요.","노래하는 모습에서 무서운 마음은 보이지 않아요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#5','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',3,'error','auto','글을 읽고 흥부의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?',ARRAY['K2-1-u8-X06','K2-1-u8-X19']::text[],false,'{"seq":5,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 흥부의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?","options":[{"t":"채원 — 「흥부는 기뻤을 거야. 박이 지붕 위에 열렸으니까.」","correct":true,"mis_target":"K2-1-u8-X06"},{"t":"하준 — 「흥부는 놀랐을 거야. 눈이 휘둥그레졌으니까.」","mis":"K2-1-u8-X19"},{"t":"지우 — 「흥부는 기뻤을 거야. 배고프던 식구가 쌀을 얻었으니까.」","mis":"K2-1-u8-X19"}],"explanation":["박이 지붕에 열린 것만으로는 흥부의 기쁨이 드러나지 않아요.","하준이와 지우는 행동과 상황을 까닭으로 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#6','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',3,'mc','auto','글을 읽고 답해 보세요. 콩쥐의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":6,"concept":"K2-1-u8-C2","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 콩쥐의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하고 막막하다 → 고맙고 기쁘다","correct":true},{"t":"고맙고 기쁘다 → 속상하고 막막하다","mis":"K2-1-u8-X09"},{"t":"처음부터 끝까지 신나고 즐겁다","mis":"K2-1-u8-X09"}],"explanation":["물이 새어 나갈 때는 속상했고 두꺼비가 도와준 뒤에는 고마웠어요.","차례가 거꾸로 되었어요.","콩쥐의 마음은 도중에 바뀌었어요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#7','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C1',3,'mc','auto','이 단원에서 작품을 감상할 때 가장 중요한 것은 무엇인가요?',ARRAY['K2-1-u8-X02']::text[],false,'{"seq":7,"concept":"K2-1-u8-C1","difficulty":3,"kind":"mc","stem":"이 단원에서 작품을 감상할 때 가장 중요한 것은 무엇인가요?","options":[{"t":"작품을 즐기고 떠오른 느낌을 친구와 나누기","correct":true},{"t":"틀리지 않고 빠르게 읽기","mis":"K2-1-u8-X02"},{"t":"작품을 그대로 외워서 말하기","mis":"K2-1-u8-X02"}],"explanation":["감상의 핵심은 즐기고 나누는 것이에요.","빨리 읽는 것은 감상의 목표가 아니에요.","외우는 것보다 내 느낌을 말하는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#8','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',4,'mc','auto','글을 읽고 답해 보세요. 콩쥐의 마음을 알맞게 짐작하고 까닭도 바르게 든 것은 어느 것인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":8,"concept":"K2-1-u8-C2","difficulty":4,"kind":"mc","stem":"글을 읽고 답해 보세요. 콩쥐의 마음을 알맞게 짐작하고 까닭도 바르게 든 것은 어느 것인가요?","options":[{"t":"「고마웠을 거야. 어려울 때 도와준 두꺼비를 꼭 끌어안았으니까.」","correct":true},{"t":"「무서웠을 거야. 두꺼비가 커다랬으니까.」","mis":"K2-1-u8-X05"},{"t":"「심심했을 거야. 물을 다 채워서 할 일이 없었으니까.」","mis":"K2-1-u8-X06"}],"explanation":["끌어안는 행동과 고맙다는 말에 마음이 드러나요.","콩쥐는 두꺼비를 무서워하지 않고 끌어안았어요.","물을 다 채운 것과 심심한 마음은 이 장면에서 드러나지 않아요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#9','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',4,'essay','teacher','글을 읽고 답해 보세요. 내가 흥부라면 박에서 쌀과 보물이 쏟아질 때 어떤 마음이었을지 쓰고, 그렇게 생각한 까닭을 글 속 상황이나 말·행동을 들어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C2","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 내가 흥부라면 박에서 쌀과 보물이 쏟아질 때 어떤 마음이었을지 쓰고, 그렇게 생각한 까닭을 글 속 상황이나 말·행동을 들어 써 보세요.","answer_guide":{"answer":"예: 너무 놀라서 꿈인지 생시인지 몰랐을 것 같아요. 왜냐하면 흥부가 눈이 휘둥그레져 입을 다물지 못했고, 늘 배고프던 아이들이 이제 배불리 먹을 수 있게 되었기 때문이에요.","scoring_points":["흥부의 마음을 썼는가","글 속 상황이나 말·행동을 까닭으로 들었는가","글에 없는 내용을 지어내지 않았는가"]},"explanation":["흥부의 마음.","상황·말·행동을 든 까닭.","글에 있는 내용."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#10','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C1',4,'essay','teacher','시·이야기·인형극 가운데 내가 감상해 본 작품 하나를 떠올려 무엇을 어디에서 감상했는지와 그때 떠오른 느낌을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C1","difficulty":4,"kind":"essay","stem":"시·이야기·인형극 가운데 내가 감상해 본 작품 하나를 떠올려 무엇을 어디에서 감상했는지와 그때 떠오른 느낌을 써 보세요.","answer_guide":{"answer":"예: 지난 여름 도서관에서 그림자 인형극 「해와 달이 된 오누이」를 보았어요. 호랑이 그림자가 커다랗게 나타날 때 가슴이 콩닥콩닥 뛰었고, 오누이가 하늘로 올라갈 때는 안심이 되었어요.","scoring_points":["감상한 작품을 밝혔는가","어디에서 감상했는지 썼는가","그때 떠오른 느낌을 썼는가"]},"explanation":["감상한 작품.","감상한 곳.","떠오른 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#1','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',1,'mc','auto','시를 읽고 답해 보세요. 짝꿍이 학교 앞에서 한 행동은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":1,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 짝꿍이 학교 앞에서 한 행동은 무엇인가요?","options":[{"t":"손을 흔들었어요","correct":true},{"t":"노래를 불렀어요","mis":"K2-1-u8-X03"},{"t":"편지를 건넸어요","mis":"K2-1-u8-X03"}],"explanation":["「짝꿍이 손을 흔든다」라고 했어요.","노래를 불렀다는 말은 시에 없어요.","편지를 건넸다는 말도 없어요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 「나」가 잠든 동생에게 한 행동은 무엇인가요?","options":[{"t":"이불을 살며시 덮어 주었어요","correct":true},{"t":"책을 읽어 주었어요","mis":"K2-1-u8-X03"},{"t":"흔들어 깨웠어요","mis":"K2-1-u8-X03"}],"explanation":["「이불을 살며시 덮어 준다」라고 했어요.","책을 읽어 주었다는 말은 시에 없어요.","깰까 봐 조심했으니 깨우지 않았어요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#2','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',1,'mc','auto','시를 읽고 답해 보세요. 짝꿍을 본 「나」의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],true,'{"seq":2,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 짝꿍을 본 「나」의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"반갑다","correct":true},{"t":"무섭다","mis":"K2-1-u8-X05"},{"t":"졸리다","mis":"K2-1-u8-X05"}],"explanation":["두 팔을 번쩍 들어 손을 흔드는 행동에 반가운 마음이 담겨 있어요.","무서웠다면 손을 흔들지 않았을 거예요.","졸린 마음은 시에서 보이지 않아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 잠든 동생을 보는 「나」의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"동생을 아끼는 마음","correct":true},{"t":"동생이 귀찮은 마음","mis":"K2-1-u8-X05"},{"t":"동생에게 화난 마음","mis":"K2-1-u8-X05"}],"explanation":["이불을 덮어 주고 숨도 조용히 쉬는 행동에 아끼는 마음이 담겨 있어요.","귀찮았다면 이렇게 조심하지 않았을 거예요.","화난 모습은 시에 없어요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#3','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C3',1,'ox','auto','시를 낭송할 때는 시의 리듬과 느낌을 살려 소리 내어 읽어요.',ARRAY['K2-1-u8-X08']::text[],true,'{"seq":3,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"시를 낭송할 때는 시의 리듬과 느낌을 살려 소리 내어 읽어요.","answer":"O","reason_options":[{"t":"리듬과 느낌을 살리면 시가 더 생생하게 느껴지니까","correct":true},{"t":"시는 언제나 크고 빠르게만 읽어야 하니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["소리 내어 리듬을 살리면 시가 살아나요.","시마다 어울리는 목소리가 달라요.","느낌을 살려 즐겁게 낭송해요."],"variant_rule":{"alt":[{"stem":"시 낭송은 한 가지 방법으로만 해야 해요.","answer":"X","reason_options":[{"t":"주고받기·몸짓 넣기·박자 넣기처럼 여러 방법으로 낭송할 수 있으니까","correct":true},{"t":"다른 방법으로 읽으면 시가 틀리게 되니까","mis":"K2-1-u8-X08"}],"explanation":["시는 여러 방법으로 낭송할 수 있어요.","방법을 바꾸면 느낌이 새롭게 달라져요.","친구와 함께 여러 방법으로 즐겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#4','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',1,'mc','auto','시를 읽고 답해 보세요. 모양을 흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],true,'{"seq":4,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 모양을 흉내 내는 말은 어느 것인가요?","options":[{"t":"흔들흔들","correct":true},{"t":"짝꿍","mis":"K2-1-u8-X07"},{"t":"학교","mis":"K2-1-u8-X07"}],"explanation":["「흔들흔들」은 손이 이리저리 움직이는 모양을 흉내 낸 말이에요.","「짝꿍」은 사람을 나타내는 말이에요.","「학교」는 곳을 나타내는 말이에요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 모양을 흉내 내는 말은 어느 것인가요?","options":[{"t":"살금살금","correct":true},{"t":"동생","mis":"K2-1-u8-X07"},{"t":"이불","mis":"K2-1-u8-X07"}],"explanation":["「살금살금」은 남이 모르게 조용히 걷는 모양을 흉내 낸 말이에요.","「동생」은 사람을 나타내는 말이에요.","「이불」은 물건을 나타내는 말이에요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#5','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',2,'match','auto','흉내 내는 말과 그 뜻을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C4","difficulty":2,"kind":"match","stem":"흉내 내는 말과 그 뜻을 알맞게 이어 보세요.","pairs":[{"l":"살금살금","r":"남이 모르게 조용히 걷는 모양"},{"l":"새근새근","r":"곱게 잠들어 고르게 숨 쉬는 소리"},{"l":"번쩍","r":"팔을 높이 빠르게 드는 모양"}],"mis":"K2-1-u8-X07","explanation":["「살금살금」은 조용히 걷는 모양이에요.","「새근새근」은 곤히 자며 숨 쉬는 소리예요.","「번쩍」은 높이 빠르게 드는 모양이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 흉내 내는 말과 그 뜻을 알맞게 이어 보세요.","pairs":[{"l":"흔들흔들","r":"이리저리 자꾸 움직이는 모양"},{"l":"조용조용","r":"소리가 나지 않게 아주 조용한 모양"},{"l":"활짝","r":"웃음이 환하게 피어나는 모양"}],"explanation":["「흔들흔들」은 이리저리 움직이는 모양이에요.","「조용조용」은 소리 없이 조용한 모양이에요.","「활짝」은 환하게 웃는 모양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#6','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「말 한마디 안 했는데 / 우리 둘은 벌써 웃는다」에서 알 수 있는 것은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X03']::text[],true,'{"seq":6,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「말 한마디 안 했는데 / 우리 둘은 벌써 웃는다」에서 알 수 있는 것은 무엇인가요?","options":[{"t":"말하지 않아도 손 흔드는 행동으로 반가운 마음이 전해졌어요","correct":true},{"t":"둘은 서로 말다툼을 했어요","mis":"K2-1-u8-X05"},{"t":"둘은 서로 모르는 사이예요","mis":"K2-1-u8-X03"}],"explanation":["손을 흔드는 행동만으로 마음이 통했어요.","다툰 친구라면 웃지 않았을 거예요.","시에서 「짝꿍」이라고 했으니 아는 사이예요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 「혹시 깰까 봐 / 숨도 조용조용 쉰다」에서 알 수 있는 「나」의 마음은 무엇인가요?","options":[{"t":"동생이 푹 자기를 바라는 마음","correct":true},{"t":"동생을 깨우고 싶은 마음","mis":"K2-1-u8-X05"},{"t":"혼자 있어 무서운 마음","mis":"K2-1-u8-X05"}],"explanation":["깰까 봐 숨까지 조심하는 행동에 동생을 위하는 마음이 보여요.","깨우고 싶었다면 조심하지 않았을 거예요.","무서운 마음은 시에서 보이지 않아요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#7','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C3',2,'mc','auto','시 낭송 방법 가운데 「주고받기」는 어떻게 읽는 것인가요?',ARRAY['K2-1-u8-X08']::text[],true,'{"seq":7,"concept":"K2-1-u8-C3","difficulty":2,"kind":"mc","stem":"시 낭송 방법 가운데 「주고받기」는 어떻게 읽는 것인가요?","options":[{"t":"두 사람이나 두 모둠이 한 줄씩 번갈아 읽어요","correct":true},{"t":"혼자 속으로 조용히 읽어요","mis":"K2-1-u8-X08"},{"t":"모두가 한꺼번에 소리쳐 읽어요","mis":"K2-1-u8-X08"}],"explanation":["주고받기는 번갈아 가며 읽는 방법이에요.","속으로 읽으면 낭송이 아니에요.","한꺼번에 소리치면 주고받기가 아니에요."],"variant_rule":{"alt":[{"stem":"시 낭송 방법 가운데 「몸짓 넣기」는 어떻게 읽는 것인가요?","options":[{"t":"시 내용에 어울리는 몸짓을 하며 읽어요","correct":true},{"t":"눈을 감고 가만히 읽어요","mis":"K2-1-u8-X08"},{"t":"최대한 빠르게 읽어요","mis":"K2-1-u8-X08"}],"explanation":["몸짓을 넣으면 시의 장면이 눈에 보이듯 살아나요.","가만히 읽으면 몸짓 넣기가 아니에요.","빠르게 읽는 것은 몸짓 넣기와 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#8','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C3',2,'error','auto','시 「동생이 잠든 밤」을 낭송했어요. 시의 분위기와 어울리지 않게 낭송한 친구는 누구인가요?',ARRAY['K2-1-u8-X08','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":2,"kind":"error","stem":"시 「동생이 잠든 밤」을 낭송했어요. 시의 분위기와 어울리지 않게 낭송한 친구는 누구인가요?","options":[{"t":"하람 — 큰 소리로 외치듯 빠르게 읽었어요","correct":true,"mis_target":"K2-1-u8-X08"},{"t":"서아 — 속삭이듯 작은 목소리로 천천히 읽었어요","mis":"K2-1-u8-X19"},{"t":"윤서 — 「살금살금」에서 발끝으로 걷는 몸짓을 했어요","mis":"K2-1-u8-X19"}],"explanation":["동생이 잠든 조용한 밤의 시는 크게 외치면 분위기가 깨져요.","서아와 윤서는 시의 분위기를 살렸어요.","물음의 「어울리지 않게」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"},"variant_rule":{"alt":[{"stem":"시 「손 흔들기」를 낭송했어요. 시의 분위기와 어울리지 않게 낭송한 친구는 누구인가요?","options":[{"t":"민호 — 「번쩍」에서 팔을 아래로 축 늘어뜨렸어요","correct":true,"mis_target":"K2-1-u8-X08"},{"t":"지우 — 「흔들흔들」에서 손을 흔들며 밝게 읽었어요","mis":"K2-1-u8-X19"},{"t":"하늘 — 짝과 두 줄씩 주고받으며 읽었어요","mis":"K2-1-u8-X19"}],"explanation":["「번쩍」은 팔을 높이 드는 모양이라 축 늘어뜨리면 맞지 않아요.","지우와 하늘이는 시의 분위기를 살렸어요.","물음의 「어울리지 않게」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#9','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',2,'sa','auto','시를 읽고 답해 보세요. 「나」가 짝꿍을 보고 번쩍 든 것을 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"sa","stem":"시를 읽고 답해 보세요. 「나」가 짝꿍을 보고 번쩍 든 것을 써 보세요.","answer":["두 팔","두팔","팔"],"explanation":["「나도 두 팔을 번쩍 들어」라고 했어요.","두 팔을 들어 흔들며 반가움을 나타냈어요.","시에서 그 줄을 찾아 짚어요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 「나」가 동생에게 살며시 덮어 준 것을 두 글자로 써 보세요.","answer":["이불"],"explanation":["「이불을 살며시 덮어 준다」라고 했어요.","동생이 춥지 않게 덮어 주었어요.","시에서 그 줄을 찾아 짚어요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#10','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C3',3,'mc','auto','같은 시라도 낭송하는 방법을 바꾸면 어떻게 될까요?',ARRAY['K2-1-u8-X08']::text[],true,'{"seq":10,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"같은 시라도 낭송하는 방법을 바꾸면 어떻게 될까요?","options":[{"t":"느낌이 달라져서 시를 더 여러 가지로 즐길 수 있어요","correct":true},{"t":"시의 내용이 다른 이야기로 바뀌어요","mis":"K2-1-u8-X08"},{"t":"시가 틀린 시가 돼요","mis":"K2-1-u8-X08"}],"explanation":["낭송 방법을 바꾸면 같은 시도 새롭게 느껴져요.","읽는 방법이 바뀌어도 시의 내용은 그대로예요.","방법을 바꾼다고 시가 틀려지지 않아요."],"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 이 시를 더 실감 나게 낭송하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「흔들흔들」에서 손을 흔들며 밝은 목소리로 읽기","correct":true},{"t":"졸린 목소리로 작게 웅얼거리기","mis":"K2-1-u8-X08"},{"t":"고개를 숙인 채 아주 빠르게 읽기","mis":"K2-1-u8-X08"}],"explanation":["반가운 마음이 담긴 시라 밝은 목소리와 손 흔들기가 어울려요.","졸린 목소리는 반가운 분위기와 맞지 않아요.","고개를 숙이고 빠르게 읽으면 느낌이 살지 않아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#1','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「나」는 동생에게 어떻게 다가갔나요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":1,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「나」는 동생에게 어떻게 다가갔나요?","options":[{"t":"살금살금","correct":true},{"t":"깡충깡충","mis":"K2-1-u8-X07"},{"t":"쿵쾅쿵쾅","mis":"K2-1-u8-X07"}],"explanation":["「살금살금 다가가」라고 했어요.","「깡충깡충」은 뛰는 모양이에요.","「쿵쾅쿵쾅」은 시끄럽게 걷는 소리라 동생이 깰 거예요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#2','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C3',2,'mc','auto','시 낭송 방법 가운데 「박자 넣기」는 어떻게 읽는 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":2,"concept":"K2-1-u8-C3","difficulty":2,"kind":"mc","stem":"시 낭송 방법 가운데 「박자 넣기」는 어떻게 읽는 것인가요?","options":[{"t":"손뼉이나 발 구르기로 박자를 맞추며 읽어요","correct":true},{"t":"한 줄씩 번갈아 읽어요","mis":"K2-1-u8-X08"},{"t":"그림을 그리며 읽어요","mis":"K2-1-u8-X08"}],"explanation":["박자를 넣으면 시의 리듬이 또렷해져요.","번갈아 읽는 것은 주고받기예요.","그림 그리기는 박자 넣기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#3','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',3,'mc','auto','시를 읽고 답해 보세요. 「나도 두 팔을 번쩍 들어」의 「번쩍」은 「나」의 어떤 마음을 잘 나타내나요?',ARRAY['K2-1-u8-X07','K2-1-u8-X05']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 「나도 두 팔을 번쩍 들어」의 「번쩍」은 「나」의 어떤 마음을 잘 나타내나요?","options":[{"t":"무척 반가워서 힘차게 답하고 싶은 마음","correct":true},{"t":"귀찮아서 마지못해 답하는 마음","mis":"K2-1-u8-X07"},{"t":"겁이 나서 숨고 싶은 마음","mis":"K2-1-u8-X05"}],"explanation":["팔을 높이 빠르게 드는 모양에 큰 반가움이 담겨 있어요.","마지못해 한다면 팔을 번쩍 들지 않았을 거예요.","숨고 싶은 마음은 시에서 보이지 않아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#4','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',3,'error','auto','시를 읽고 「나」의 마음과 그렇게 짐작한 까닭을 말했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C4","difficulty":3,"kind":"error","stem":"시를 읽고 「나」의 마음과 그렇게 짐작한 까닭을 말했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"예린 — 「동생이 미웠을 거야. 숨도 조용조용 쉬었으니까.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"건우 — 「동생을 아꼈을 거야. 이불을 살며시 덮어 줬으니까.」","mis":"K2-1-u8-X19"},{"t":"채원 — 「동생이 깰까 봐 조심스러웠을 거야. 살금살금 다가갔으니까.」","mis":"K2-1-u8-X19"}],"explanation":["숨까지 조용히 쉰 것은 동생을 위해서지 미워서가 아니에요.","건우와 채원이는 행동에 맞게 짐작했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#5','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',3,'ox','auto','시에 「반갑다」라는 말이 없으면 「나」가 반가웠는지 알 수 없어요.',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":5,"concept":"K2-1-u8-C4","difficulty":3,"kind":"ox","stem":"시에 「반갑다」라는 말이 없으면 「나」가 반가웠는지 알 수 없어요.","answer":"X","reason_options":[{"t":"웃으며 손을 흔드는 행동에서 반가운 마음을 짐작할 수 있으니까","correct":true},{"t":"마음은 글에 쓰인 말로만 알 수 있으니까","mis":"K2-1-u8-X05"}],"mis":"K2-1-u8-X05","explanation":["행동 속에 마음이 담겨 있어요.","「번쩍」·「흔들흔들」·「웃는다」에서 반가움이 느껴져요.","말이 없어도 행동을 보고 마음을 짐작해요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#6','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":6,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 목소리는 어느 것인가요?","options":[{"t":"작고 부드러운 목소리로 천천히","correct":true},{"t":"크고 씩씩한 목소리로 빠르게","mis":"K2-1-u8-X08"},{"t":"화난 목소리로 또박또박 끊어서","mis":"K2-1-u8-X08"}],"explanation":["동생이 잠든 고요한 밤이라 작고 부드럽게 읽으면 어울려요.","크고 빠르게 읽으면 조용한 분위기가 깨져요.","화난 목소리는 동생을 아끼는 마음과 맞지 않아요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#7','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',3,'mc','auto','시를 읽고 답해 보세요. 「나」처럼 말없이 몸짓으로 마음을 주고받은 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":7,"concept":"K2-1-u8-C4","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 「나」처럼 말없이 몸짓으로 마음을 주고받은 경험을 떠올린 친구는 누구인가요?","options":[{"t":"다은 — 「달리기 때 멀리서 엄마가 엄지를 척 들어 줘서 힘이 났어.」","correct":true},{"t":"준우 — 「나는 어제 혼자 숙제를 했어.」","mis":"K2-1-u8-X06"},{"t":"소율 — 「우리 학교 앞에는 문구점이 있어.」","mis":"K2-1-u8-X06"}],"explanation":["말 대신 몸짓으로 마음이 전해진 경험이에요.","혼자 숙제한 일은 몸짓으로 마음을 주고받은 경험이 아니에요.","학교 앞 문구점은 시와 상관없는 이야기예요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#8','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C3',4,'mc','auto','시를 읽고 답해 보세요. 친구와 둘이 「주고받기」로 낭송하려고 해요. 가장 알맞게 나눈 것은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":4,"kind":"mc","stem":"시를 읽고 답해 보세요. 친구와 둘이 「주고받기」로 낭송하려고 해요. 가장 알맞게 나눈 것은 어느 것인가요?","options":[{"t":"짝꿍 역은 1·2행, 나 역은 3·4행을 읽고 마지막 두 행은 함께 읽어요","correct":true},{"t":"한 사람이 처음부터 끝까지 혼자 다 읽어요","mis":"K2-1-u8-X08"},{"t":"두 사람이 같은 행을 서로 먼저 읽으려고 겹쳐 읽어요","mis":"K2-1-u8-X08"}],"explanation":["짝꿍이 손 흔드는 줄과 내가 답하는 줄을 나누니 주고받는 느낌이 살아요.","혼자 다 읽으면 주고받기가 아니에요.","겹쳐 읽으면 무슨 말인지 들리지 않아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#9','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',4,'essay','teacher','시를 읽고 답해 보세요. 「나」의 마음을 짐작해 쓰고, 그렇게 짐작할 수 있는 행동이나 흉내 내는 말을 시에서 두 가지 찾아 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 「나」의 마음을 짐작해 쓰고, 그렇게 짐작할 수 있는 행동이나 흉내 내는 말을 시에서 두 가지 찾아 써 보세요.","answer_guide":{"answer":"예: 「나」는 동생을 아끼고 동생이 푹 자기를 바랐을 거예요. 「살금살금 다가가」와 「숨도 조용조용 쉰다」에서 동생이 깰까 봐 조심하는 마음을 알 수 있어요.","scoring_points":["「나」의 마음을 썼는가","시에서 행동이나 흉내 내는 말을 두 가지 찾았는가","찾은 부분과 마음이 서로 맞는가"]},"explanation":["「나」의 마음.","행동·흉내 내는 말 두 가지.","마음과 근거가 맞는지."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#10','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C3',4,'essay','teacher','시 「손 흔들기」처럼 말없이 몸짓으로 마음을 주고받고 싶은 사람을 떠올려, 누구와 어떤 몸짓 신호로 어떤 마음을 전하고 싶은지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C3","difficulty":4,"kind":"essay","stem":"시 「손 흔들기」처럼 말없이 몸짓으로 마음을 주고받고 싶은 사람을 떠올려, 누구와 어떤 몸짓 신호로 어떤 마음을 전하고 싶은지 써 보세요.","answer_guide":{"answer":"예: 할머니와 손가락 하트 신호를 주고받고 싶어요. 할머니 댁에서 돌아올 때 차 안에서 손가락 하트를 보내 「사랑해요, 또 올게요.」라는 마음을 전하고 싶어요.","scoring_points":["누구와 주고받고 싶은지 썼는가","어떤 몸짓 신호인지 썼는가","전하고 싶은 마음을 썼는가"]},"explanation":["누구와.","몸짓 신호.","전하고 싶은 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#1','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 보보가 도시락 뚜껑을 열다가 깜짝 놀란 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":1,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보가 도시락 뚜껑을 열다가 깜짝 놀란 까닭은 무엇인가요?","options":[{"t":"도시락이 텅 비어 있어서","correct":true},{"t":"소풍이 취소되어서","mis":"K2-1-u8-X03"},{"t":"친구들이 놀려서","mis":"K2-1-u8-X03"}],"explanation":["도시락이 텅 비어 있었다고 했어요.","소풍은 취소되지 않았어요.","친구들은 놀리지 않고 음식을 나눠 주었어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이가 발을 동동 구른 까닭은 무엇인가요?","options":[{"t":"종이배가 돌에 걸려 뒤집혀서","correct":true},{"t":"오빠가 종이배를 가져가서","mis":"K2-1-u8-X03"},{"t":"갑자기 비가 와서","mis":"K2-1-u8-X03"}],"explanation":["종이배가 돌에 걸려 뒤집혔다고 했어요.","오빠는 종이배를 가져가지 않았어요.","비가 왔다는 말은 없어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#2','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 보보에게 당근 김밥을 내밀며 같이 먹자고 한 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],true,'{"seq":2,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보에게 당근 김밥을 내밀며 같이 먹자고 한 인물은 누구인가요?","options":[{"t":"토토","correct":true},{"t":"다미","mis":"K2-1-u8-X04"},{"t":"엄마 곰","mis":"K2-1-u8-X03"}],"explanation":["토끼 토토가 김밥을 내밀었어요.","다미는 도토리 빵을 나누어 주었어요.","엄마 곰은 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 「이번엔 더 튼튼하게 같이 접어 보자.」라고 말한 인물은 누구인가요?","options":[{"t":"오빠","correct":true},{"t":"연이","mis":"K2-1-u8-X04"},{"t":"엄마","mis":"K2-1-u8-X03"}],"explanation":["오빠가 빙그레 웃으며 그렇게 말했어요.","연이는 발을 동동 구르던 인물이에요.","엄마는 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#3','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',1,'ox','auto','이야기를 읽고 답해 보세요. 보보는 소풍이 끝날 때까지 혼자 시무룩해 있었어요.',ARRAY['K2-1-u8-X09']::text[],true,'{"seq":3,"concept":"K2-1-u8-C5","difficulty":1,"kind":"ox","stem":"이야기를 읽고 답해 보세요. 보보는 소풍이 끝날 때까지 혼자 시무룩해 있었어요.","answer":"X","reason_options":[{"t":"친구들이 음식을 나눠 주자 활짝 웃었다고 했으니까","correct":true},{"t":"보보의 마음은 처음부터 끝까지 그대로였으니까","mis":"K2-1-u8-X09"}],"mis":"K2-1-u8-X09","explanation":["처음에는 시무룩했지만 친구들 덕분에 활짝 웃었어요.","인물의 마음은 일이 일어나며 바뀌어요.","처음·끝 장면의 마음을 따로 살펴요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이는 새 종이배가 멀리 떠내려가자 무척 기뻐했어요.","answer":"O","reason_options":[{"t":"손뼉을 치며 깡충깡충 뛰었다고 했으니까","correct":true},{"t":"연이는 끝까지 속상한 마음이었으니까","mis":"K2-1-u8-X09"}],"explanation":["손뼉 치고 깡충깡충 뛴 행동에 기쁨이 드러나요.","속상했던 마음이 기쁨으로 바뀌었어요.","처음·끝 장면의 마음을 따로 살펴요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#4','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C6',1,'mc','auto','이야기를 읽고 생각이나 느낌을 표현하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X10']::text[],true,'{"seq":4,"concept":"K2-1-u8-C6","difficulty":1,"kind":"mc","stem":"이야기를 읽고 생각이나 느낌을 표현하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"기억에 남는 장면을 그림으로 그리고 느낌을 한 줄 쓰기","correct":true},{"t":"이야기 글자 수를 세어 쓰기","mis":"K2-1-u8-X10"},{"t":"책 표지만 똑같이 따라 그리기","mis":"K2-1-u8-X10"}],"explanation":["장면과 느낌을 함께 담으면 감상이 잘 드러나요.","글자 수는 느낌과 상관없어요.","표지만 따라 그리면 내 느낌이 드러나지 않아요."],"variant_rule":{"alt":[{"stem":"기억에 남는 장면을 말할 때 함께 말하면 좋은 것은 무엇인가요?","options":[{"t":"그 장면이 기억에 남는 까닭","correct":true},{"t":"책을 산 가게 이름","mis":"K2-1-u8-X10"},{"t":"책의 무게","mis":"K2-1-u8-X10"}],"explanation":["까닭을 함께 말하면 내 느낌이 잘 전해져요.","가게 이름은 감상과 상관없어요.","책의 무게도 감상과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#5','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',2,'match','auto','이야기를 읽고 장면과 그때 보보의 마음을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C5","difficulty":2,"kind":"match","stem":"이야기를 읽고 장면과 그때 보보의 마음을 알맞게 이어 보세요.","pairs":[{"l":"도시락이 텅 비어 있었다","r":"깜짝 놀랐다"},{"l":"나무 뒤에 혼자 앉았다","r":"시무룩하고 외로웠다"},{"l":"친구들이 음식을 나누어 주었다","r":"고맙고 기뻤다"}],"mis":"K2-1-u8-X09","explanation":["빈 도시락을 보고 깜짝 놀랐어요.","혼자 앉아 있을 때는 시무룩했어요.","친구들 덕분에 고맙고 기뻤어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 장면과 그때 연이의 마음을 알맞게 이어 보세요.","pairs":[{"l":"종이배를 시냇물에 띄웠다","r":"설레고 즐거웠다"},{"l":"종이배가 뒤집혀 젖었다","r":"속상했다"},{"l":"새 종이배가 멀리 떠내려갔다","r":"신나고 기뻤다"}],"explanation":["배를 띄울 때는 설렜어요.","배가 뒤집히자 속상했어요.","새 배가 잘 떠가자 신났어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#6','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 보보가 시무룩했다는 것을 알 수 있는 행동은 어느 것인가요?',ARRAY['K2-1-u8-X09','K2-1-u8-X04']::text[],true,'{"seq":6,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보가 시무룩했다는 것을 알 수 있는 행동은 어느 것인가요?","options":[{"t":"고개를 푹 숙이고 나무 뒤에 혼자 앉았어요","correct":true},{"t":"눈이 동그래졌다가 활짝 웃었어요","mis":"K2-1-u8-X09"},{"t":"깡충깡충 다가와 김밥을 내밀었어요","mis":"K2-1-u8-X04"}],"explanation":["고개를 숙이고 혼자 앉은 행동에 시무룩한 마음이 보여요.","활짝 웃은 것은 기뻐진 뒤의 모습이에요.","김밥을 내민 것은 토토예요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이가 속상했다는 것을 알 수 있는 행동은 어느 것인가요?","options":[{"t":"발을 동동 굴렀어요","correct":true},{"t":"손뼉을 치며 깡충깡충 뛰었어요","mis":"K2-1-u8-X09"},{"t":"빙그레 웃으며 말했어요","mis":"K2-1-u8-X04"}],"explanation":["발을 동동 구른 행동에 속상한 마음이 보여요.","손뼉 친 것은 기뻐진 뒤의 모습이에요.","빙그레 웃은 것은 오빠예요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#7','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 보보의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],true,'{"seq":7,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"놀라고 시무룩하다 → 고맙고 기쁘다","correct":true},{"t":"고맙고 기쁘다 → 놀라고 시무룩하다","mis":"K2-1-u8-X09"},{"t":"처음부터 끝까지 고맙고 기쁘다","mis":"K2-1-u8-X09"}],"explanation":["빈 도시락에 시무룩했다가 친구들 덕분에 기뻐졌어요.","차례가 거꾸로 되었어요.","처음에는 기쁘지 않았어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"설렌다 → 속상하다 → 기쁘다","correct":true},{"t":"기쁘다 → 설렌다 → 속상하다","mis":"K2-1-u8-X09"},{"t":"속상하다 → 설렌다 → 속상하다","mis":"K2-1-u8-X09"}],"explanation":["배를 띄우며 설렜고, 뒤집히자 속상했고, 새 배가 떠가자 기뻤어요.","끝에 속상했다는 차례는 맞지 않아요.","처음부터 속상하지는 않았어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#8','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C6',2,'error','auto','「보보의 빈 도시락」에서 기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"「보보의 빈 도시락」에서 기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"지후 — 「나는 보보가 활짝 웃는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"아린 — 「다미가 빵을 나누는 장면이 기억에 남아. 자기 것도 반으로 나눠 준 게 따뜻했거든.」","mis":"K2-1-u8-X19"},{"t":"태민 — 「빈 도시락 장면이 기억에 남아. 내가 보보였으면 울었을 것 같아서.」","mis":"K2-1-u8-X19"}],"explanation":["지후는 장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","아린이와 태민이는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."],"variant_rule":{"alt":[{"stem":"「연이의 종이배」에서 기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"수빈 — 「나는 종이배가 뒤집히는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"현우 — 「오빠가 같이 접자고 하는 장면이 기억에 남아. 다정한 오빠가 부러웠거든.」","mis":"K2-1-u8-X19"},{"t":"다은 — 「새 배가 떠가는 장면이 기억에 남아. 다시 해서 해낸 게 멋졌거든.」","mis":"K2-1-u8-X19"}],"explanation":["수빈이는 장면만 말하고 까닭을 말하지 않았어요.","현우와 다은이는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#9','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',2,'sa','auto','이야기를 읽고 답해 보세요. 다람쥐 다미가 반으로 나누어 준 음식을 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C5","difficulty":2,"kind":"sa","stem":"이야기를 읽고 답해 보세요. 다람쥐 다미가 반으로 나누어 준 음식을 써 보세요.","answer":["도토리 빵","도토리빵"],"explanation":["다미는 도토리 빵을 반으로 나누어 주었어요.","토토는 당근 김밥을 내밀었어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이와 오빠가 접어 시냇물에 띄운 것을 세 글자로 써 보세요.","answer":["종이배"],"explanation":["둘은 종이배를 접어 띄웠어요.","처음 배는 뒤집혔지만 새 배는 멀리 떠갔어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#10','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C6',3,'mc','auto','이야기를 읽고 답해 보세요. 기억에 남는 장면과 까닭, 비슷한 내 경험을 모두 담아 감상을 말한 것은 어느 것인가요?',ARRAY['K2-1-u8-X10']::text[],true,'{"seq":10,"concept":"K2-1-u8-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 기억에 남는 장면과 까닭, 비슷한 내 경험을 모두 담아 감상을 말한 것은 어느 것인가요?","options":[{"t":"「토토가 김밥을 내미는 장면이 기억에 남아. 먼저 다가간 토토가 멋졌거든. 나도 짝이 먼저 말을 걸어 줘서 고마웠던 적이 있어.」","correct":true},{"t":"「보보는 아기 곰이고 토토는 토끼야.」","mis":"K2-1-u8-X10"},{"t":"「소풍을 가서 도시락을 먹는 이야기야.」","mis":"K2-1-u8-X10"}],"explanation":["장면·까닭·내 경험이 모두 들어 있어요.","인물 소개만 하고 느낌은 없어요.","줄거리만 말하고 느낌은 없어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 답해 보세요. 기억에 남는 장면과 까닭, 비슷한 내 경험을 모두 담아 감상을 말한 것은 어느 것인가요?","options":[{"t":"「새 종이배가 멀리 떠가는 장면이 기억에 남아. 포기하지 않고 다시 접어서 해낸 게 좋았거든. 나도 블록 성이 무너졌을 때 다시 쌓아서 완성한 적이 있어.」","correct":true},{"t":"「연이와 오빠가 종이배를 접는 이야기야.」","mis":"K2-1-u8-X10"},{"t":"「시냇물에는 돌이 있어.」","mis":"K2-1-u8-X10"}],"explanation":["장면·까닭·내 경험이 모두 들어 있어요.","줄거리만 말하고 느낌은 없어요.","이야기 속 물건만 말했어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#1','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 연이와 오빠가 새 종이배를 더 튼튼하게 만든 방법은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":1,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 연이와 오빠가 새 종이배를 더 튼튼하게 만든 방법은 무엇인가요?","options":[{"t":"종이를 두 겹으로 겹쳐서 접었어요","correct":true},{"t":"배 위에 돌을 실었어요","mis":"K2-1-u8-X03"},{"t":"비닐로 겉을 감쌌어요","mis":"K2-1-u8-X03"}],"explanation":["종이를 두 겹으로 겹쳐 새 배를 접었다고 했어요.","돌을 실었다는 말은 없어요.","비닐로 감쌌다는 말도 없어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#2','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',2,'mc','auto','감상 발표를 읽고 답해 보세요. 채원이가 가장 기억에 남는다고 한 장면은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X04']::text[],false,'{"seq":2,"concept":"K2-1-u8-C6","difficulty":2,"kind":"mc","stem":"감상 발표를 읽고 답해 보세요. 채원이가 가장 기억에 남는다고 한 장면은 무엇인가요?","options":[{"t":"토토가 김밥을 내미는 장면","correct":true},{"t":"도시락이 텅 비어 있는 장면","mis":"K2-1-u8-X03"},{"t":"다미가 빵을 나누어 주는 장면","mis":"K2-1-u8-X04"}],"explanation":["채원이는 토토가 김밥을 내미는 장면을 골랐어요.","빈 도시락 장면은 채원이가 고른 장면이 아니에요.","빵을 나눈 다미의 장면도 아니에요."],"asset":{"type":"passage","lines":["저는 「보보의 빈 도시락」에서 토토가 김밥을 내미는 장면이 가장 기억에 남아요.","왜냐하면 혼자 있던 보보에게 먼저 다가간 토토가 멋졌기 때문이에요.","저도 전학 왔을 때 짝이 먼저 말을 걸어 줘서 정말 고마웠어요."],"title":"채원이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#3','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 「보보는 눈이 동그래졌다가 이내 활짝 웃었어요.」에서 보보의 마음은 어떻게 바뀌었나요?',ARRAY['K2-1-u8-X09','K2-1-u8-X05']::text[],false,'{"seq":3,"concept":"K2-1-u8-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 「보보는 눈이 동그래졌다가 이내 활짝 웃었어요.」에서 보보의 마음은 어떻게 바뀌었나요?","options":[{"t":"놀랐다가 기뻐졌어요","correct":true},{"t":"기뻤다가 슬퍼졌어요","mis":"K2-1-u8-X09"},{"t":"화났다가 졸려졌어요","mis":"K2-1-u8-X05"}],"explanation":["눈이 동그래진 것은 놀람, 활짝 웃은 것은 기쁨이에요.","차례가 거꾸로 되었어요.","화나거나 졸린 마음은 보이지 않아요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#4','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',3,'error','auto','이야기를 읽고 인물의 마음과 그렇게 짐작한 까닭을 말했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 마음과 그렇게 짐작한 까닭을 말했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"도윤 — 「오빠는 연이 종이배가 뒤집혀서 고소했을 거야. 빙그레 웃었으니까.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"지안 — 「오빠는 연이를 달래 주고 싶었을 거야. 괜찮다고 했으니까.」","mis":"K2-1-u8-X19"},{"t":"하준 — 「연이는 속상했을 거야. 발을 동동 굴렀으니까.」","mis":"K2-1-u8-X19"}],"explanation":["오빠는 괜찮다며 같이 다시 접자고 했으니 달래려고 웃은 거예요.","지안이와 하준이는 말과 행동에 맞게 짐작했어요.","말과 행동을 함께 살펴요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#5','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',3,'ox','auto','같은 이야기를 읽어도 친구마다 기억에 남는 장면이 다를 수 있어요.',ARRAY['K2-1-u8-X02']::text[],false,'{"seq":5,"concept":"K2-1-u8-C6","difficulty":3,"kind":"ox","stem":"같은 이야기를 읽어도 친구마다 기억에 남는 장면이 다를 수 있어요.","answer":"O","reason_options":[{"t":"저마다 겪은 일과 느낀 점이 달라서","correct":true},{"t":"기억에 남는 장면은 모두 같아야 하니까","mis":"K2-1-u8-X02"}],"mis":"K2-1-u8-X02","explanation":["누구는 빈 도시락 장면이, 누구는 웃는 장면이 기억에 남을 수 있어요.","다른 장면을 고른 것은 틀린 것이 아니에요.","서로의 장면과 까닭을 들어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#6','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',3,'mc','auto','감상 발표를 읽고 답해 보세요. 채원이가 그 장면이 기억에 남는다고 한 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X04']::text[],false,'{"seq":6,"concept":"K2-1-u8-C6","difficulty":3,"kind":"mc","stem":"감상 발표를 읽고 답해 보세요. 채원이가 그 장면이 기억에 남는다고 한 까닭은 무엇인가요?","options":[{"t":"혼자 있던 보보에게 먼저 다가간 토토가 멋졌기 때문에","correct":true},{"t":"당근 김밥이 맛있어 보였기 때문에","mis":"K2-1-u8-X03"},{"t":"다미가 빵을 반으로 나누었기 때문에","mis":"K2-1-u8-X04"}],"explanation":["채원이는 「왜냐하면」 뒤에 까닭을 말했어요.","김밥이 맛있어 보였다는 말은 없어요.","다미 이야기는 채원이의 까닭이 아니에요."],"asset":{"type":"passage","lines":["저는 「보보의 빈 도시락」에서 토토가 김밥을 내미는 장면이 가장 기억에 남아요.","왜냐하면 혼자 있던 보보에게 먼저 다가간 토토가 멋졌기 때문이에요.","저도 전학 왔을 때 짝이 먼저 말을 걸어 줘서 정말 고마웠어요."],"title":"채원이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#7','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 토토와 다미가 보보에게 음식을 나누어 준 까닭으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":7,"concept":"K2-1-u8-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 토토와 다미가 보보에게 음식을 나누어 준 까닭으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"혼자 시무룩한 보보가 걱정되어서","correct":true},{"t":"남은 음식을 버리고 싶어서","mis":"K2-1-u8-X05"},{"t":"보보를 놀리고 싶어서","mis":"K2-1-u8-X05"}],"explanation":["혼자 있는 보보를 보고 걱정되어 다가갔을 거예요.","버리려 했다면 「같이 먹자」고 하지 않았을 거예요.","놀리는 말이나 행동은 없어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#8','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',4,'mc','auto','이야기를 읽고 생각이나 느낌을 표현하는 방법에 대해 바르게 말한 친구는 누구인가요?',ARRAY['K2-1-u8-X02','K2-1-u8-X10']::text[],false,'{"seq":8,"concept":"K2-1-u8-C6","difficulty":4,"kind":"mc","stem":"이야기를 읽고 생각이나 느낌을 표현하는 방법에 대해 바르게 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「글로 쓰기 어려우면 장면을 그림으로 그리고 느낌을 한 줄 덧붙여도 돼.」","correct":true},{"t":"민준 — 「감상은 꼭 긴 글로만 써야 해.」","mis":"K2-1-u8-X02"},{"t":"로아 — 「줄거리를 처음부터 끝까지 그대로 옮겨 쓰면 돼.」","mis":"K2-1-u8-X10"}],"explanation":["글·그림·말 등 여러 방법으로 표현할 수 있어요.","긴 글만 감상이 되는 것은 아니에요.","줄거리만 옮기면 내 느낌이 드러나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#9','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',4,'essay','teacher','이야기를 읽고 답해 보세요. 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"이야기를 읽고 답해 보세요. 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 오빠가 「같이 접어 보자.」라고 하는 장면이 가장 기억에 남아요. 왜냐하면 울상인 동생을 탓하지 않고 다정하게 도와준 오빠가 멋졌기 때문이에요. 저도 줄넘기가 안 될 때 언니가 같이 연습해 줘서 힘이 났던 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#10','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',4,'essay','teacher','이야기를 읽고 답해 보세요. 보보의 마음이 처음·가운데·끝에 어떻게 바뀌었는지 쓰고, 무엇 때문에 마음이 바뀌었는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":4,"kind":"essay","stem":"이야기를 읽고 답해 보세요. 보보의 마음이 처음·가운데·끝에 어떻게 바뀌었는지 쓰고, 무엇 때문에 마음이 바뀌었는지 써 보세요.","answer_guide":{"answer":"예: 처음에는 도시락이 비어 있어 깜짝 놀랐고, 가운데에서는 혼자 나무 뒤에 앉아 시무룩했고, 끝에는 활짝 웃으며 고마워했어요. 토토와 다미가 음식을 나누어 주어서 마음이 바뀌었어요.","scoring_points":["처음·가운데·끝의 마음을 차례대로 썼는가","마음이 바뀐 까닭을 썼는가","이야기 속 말·행동과 맞게 썼는가"]},"explanation":["처음·가운데·끝 마음.","바뀐 까닭.","말·행동과 맞는지."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#1','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',1,'mc','auto','인형극에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u8-X01','K2-1-u8-X11']::text[],true,'{"seq":1,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"인형극에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"인형이 나와 말과 움직임으로 이야기를 보여 주는 극이에요","correct":true},{"t":"소리 내어 낭송하는 짧은 글이에요","mis":"K2-1-u8-X01"},{"t":"혼자 조용히 읽는 이야기책이에요","mis":"K2-1-u8-X11"}],"explanation":["인형극은 인형이 움직이며 이야기를 보여 줘요.","짧은 글을 낭송하는 것은 시예요.","인형극은 보고 들으며 감상해요."],"variant_rule":{"alt":[{"stem":"빛을 비추어 생긴 그림자로 이야기를 보여 주는 인형극은 어느 것인가요?","options":[{"t":"그림자 인형극","correct":true},{"t":"손가락 인형극","mis":"K2-1-u8-X11"},{"t":"막대 인형극","mis":"K2-1-u8-X11"}],"explanation":["빛과 그림자로 보여 주는 것이 그림자 인형극이에요.","손가락 인형극은 손가락에 인형을 끼워요.","막대 인형극은 막대에 붙인 인형을 움직여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#2','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',1,'mc','auto','인형극 대본을 읽고 답해 보세요. 오빠가 작은 목소리로 속삭인 것에서 알 수 있는 오빠의 마음은 어느 것인가요?',ARRAY['K2-1-u8-X12']::text[],true,'{"seq":2,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 오빠가 작은 목소리로 속삭인 것에서 알 수 있는 오빠의 마음은 어느 것인가요?","options":[{"t":"호랑이에게 들킬까 봐 조심스럽고 무섭다","correct":true},{"t":"신나고 즐겁다","mis":"K2-1-u8-X12"},{"t":"졸리고 심심하다","mis":"K2-1-u8-X12"}],"explanation":["속삭이는 작은 목소리에 들킬까 봐 조심하는 마음이 담겨 있어요.","신이 났다면 크고 빠르게 말했을 거예요.","졸린 마음은 이 장면과 맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 흥부가 깜짝 놀라 커다란 목소리로 말한 것에서 알 수 있는 흥부의 마음은 어느 것인가요?","options":[{"t":"놀랍고 기쁘다","correct":true},{"t":"무섭고 슬프다","mis":"K2-1-u8-X12"},{"t":"지루하고 심심하다","mis":"K2-1-u8-X12"}],"explanation":["쌀이 쏟아져 놀라고 기뻐서 큰 목소리가 나왔어요.","무섭거나 슬픈 장면이 아니에요.","지루했다면 커다란 목소리가 나오지 않았을 거예요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#3','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',1,'ox','auto','인형극에서는 인물의 목소리 크기와 빠르기로도 마음을 짐작할 수 있어요.',ARRAY['K2-1-u8-X11']::text[],true,'{"seq":3,"concept":"K2-1-u8-C7","difficulty":1,"kind":"ox","stem":"인형극에서는 인물의 목소리 크기와 빠르기로도 마음을 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"신나면 크고 빠르게, 무서우면 작고 떨리게 말하니까","correct":true},{"t":"인형극에서 마음은 대사의 뜻으로만 알 수 있으니까","mis":"K2-1-u8-X11"}],"mis":"K2-1-u8-X11","explanation":["목소리에 인물의 마음이 묻어나요.","대사의 뜻과 함께 목소리·움직임도 살펴요.","말·행동·목소리를 모두 보고 들어요."],"variant_rule":{"alt":[{"stem":"인형극은 이야기책처럼 글만 읽으며 감상해요.","answer":"X","reason_options":[{"t":"인형의 움직임과 목소리를 보고 들으며 감상하니까","correct":true},{"t":"인형극에는 목소리와 움직임이 없으니까","mis":"K2-1-u8-X11"}],"explanation":["인형극은 눈과 귀로 함께 감상해요.","인형의 움직임과 목소리에 마음이 드러나요.","그래서 이야기책과 느낌이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#4','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C8',1,'mc','auto','줄거리를 읽고 답해 보세요. 엄마가 호랑이를 만난 곳은 어디인가요?',ARRAY['K2-1-u8-X13']::text[],true,'{"seq":4,"concept":"K2-1-u8-C8","difficulty":1,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 엄마가 호랑이를 만난 곳은 어디인가요?","options":[{"t":"고개","correct":true},{"t":"집","mis":"K2-1-u8-X13"},{"t":"나무 위","mis":"K2-1-u8-X13"}],"explanation":["떡을 팔고 고개를 넘어오다 호랑이를 만났어요.","집은 오누이가 기다리던 곳이에요.","나무 위는 오누이가 피한 곳이에요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"},"variant_rule":{"alt":[{"stem":"줄거리를 읽고 답해 보세요. 오누이가 호랑이를 피해 올라간 곳은 어디인가요?","options":[{"t":"우물가 나무 위","correct":true},{"t":"고개","mis":"K2-1-u8-X13"},{"t":"지붕 위","mis":"K2-1-u8-X03"}],"explanation":["오누이는 뒷문으로 나가 우물가 나무 위로 올라갔어요.","고개는 엄마가 호랑이를 만난 곳이에요.","지붕 위로 올라갔다는 말은 없어요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#5','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',2,'match','auto','인형극의 종류와 그 특징을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극의 종류와 그 특징을 알맞게 이어 보세요.","pairs":[{"l":"그림자 인형극","r":"빛을 비추어 생긴 그림자로 보여 줘요"},{"l":"막대 인형극","r":"막대에 붙인 인형을 움직여요"},{"l":"손가락 인형극","r":"손가락에 인형을 끼워 움직여요"}],"mis":"K2-1-u8-X11","explanation":["그림자 인형극은 빛과 그림자를 써요.","막대 인형극은 막대로 인형을 움직여요.","손가락 인형극은 손가락에 인형을 끼워요."],"variant_rule":{"alt":[{"stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"작고 떨리는 목소리","r":"무섭다"},{"l":"크고 빠른 목소리","r":"신난다"},{"l":"느리고 힘없는 목소리","r":"슬프다"}],"explanation":["무서우면 목소리가 작고 떨려요.","신나면 크고 빨라져요.","슬프면 느리고 힘이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#6','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 누이가 떨리는 목소리로 말한 것에서 알 수 있는 누이의 마음은 어느 것인가요?',ARRAY['K2-1-u8-X12']::text[],true,'{"seq":6,"concept":"K2-1-u8-C7","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 누이가 떨리는 목소리로 말한 것에서 알 수 있는 누이의 마음은 어느 것인가요?","options":[{"t":"무섭고 겁이 난다","correct":true},{"t":"반갑고 기쁘다","mis":"K2-1-u8-X12"},{"t":"화가 나서 따지고 싶다","mis":"K2-1-u8-X12"}],"explanation":["떨리는 목소리에 무서운 마음이 담겨 있어요.","엄마인지 의심하는 장면이라 반가운 마음이 아니에요.","화난 목소리라면 떨리지 않고 커졌을 거예요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 흥부 아내가 노래하듯 흥겹게 말한 것에서 알 수 있는 마음은 어느 것인가요?","options":[{"t":"박에서 무엇이 나올지 설레고 즐겁다","correct":true},{"t":"무섭고 걱정된다","mis":"K2-1-u8-X12"},{"t":"슬프고 서운하다","mis":"K2-1-u8-X12"}],"explanation":["흥겨운 노랫소리에 설레는 마음이 담겨 있어요.","무서웠다면 흥겹게 노래하지 않았을 거예요.","슬픈 마음은 이 장면과 맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#7','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C8',2,'mc','auto','줄거리를 읽고 답해 보세요. 장소가 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],true,'{"seq":7,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 장소가 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"집 → 고개 → 집 → 나무 위 → 하늘","correct":true},{"t":"고개 → 나무 위 → 집 → 하늘","mis":"K2-1-u8-X13"},{"t":"집 → 나무 위 → 고개 → 하늘","mis":"K2-1-u8-X13"}],"explanation":["엄마가 집을 나서 고개에서 호랑이를 만나고, 호랑이가 집으로 온 뒤 오누이는 나무 위를 거쳐 하늘로 올라갔어요.","나무 위는 호랑이가 집에 온 다음이에요.","고개는 나무 위보다 먼저예요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"박이 열린다 → 박을 탄다 → 쌀이 쏟아진다 → 아이들이 기뻐한다","correct":true},{"t":"쌀이 쏟아진다 → 박이 열린다 → 박을 탄다 → 아이들이 기뻐한다","mis":"K2-1-u8-X13"},{"t":"박을 탄다 → 아이들이 기뻐한다 → 박이 열린다 → 쌀이 쏟아진다","mis":"K2-1-u8-X13"}],"explanation":["박이 열리고, 박을 타자, 쌀이 쏟아졌고, 아이들이 기뻐했어요.","박이 열리기 전에 쌀이 쏟아질 수 없어요.","박을 타기 전에 박이 먼저 열려야 해요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#8','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',2,'error','auto','인형극 대본을 읽고 인물의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C7","difficulty":2,"kind":"error","stem":"인형극 대본을 읽고 인물의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"서준 — 「오빠는 신이 났을 거야. 누이 손을 꼭 잡았으니까.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"하윤 — 「누이는 무서웠을 거야. 목소리가 떨렸으니까.」","mis":"K2-1-u8-X19"},{"t":"윤호 — 「오빠는 누이를 지키고 싶었을 거야. 손을 꼭 잡고 뒷문으로 나갔으니까.」","mis":"K2-1-u8-X19"}],"explanation":["호랑이를 피해 달아나는 장면이라 신이 났을 리 없어요.","하윤이와 윤호는 목소리와 행동에 맞게 짐작했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 인형극 대본을 읽고 인물의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"지호 — 「아이들은 슬펐을 거야. 깡충깡충 뛰었으니까.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"채원 — 「흥부는 놀랐을 거야. 커다란 목소리로 말했으니까.」","mis":"K2-1-u8-X19"},{"t":"다은 — 「흥부 아내는 즐거웠을 거야. 노래하듯 흥겹게 말했으니까.」","mis":"K2-1-u8-X19"}],"explanation":["깡충깡충 뛰며 「배불리 먹을 수 있다!」고 했으니 기뻤어요.","채원이와 다은이는 목소리에 맞게 짐작했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#9','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C8',2,'sa','auto','줄거리를 읽고 답해 보세요. 오누이가 잡고 하늘로 올라간 것을 세 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C8","difficulty":2,"kind":"sa","stem":"줄거리를 읽고 답해 보세요. 오누이가 잡고 하늘로 올라간 것을 세 글자로 써 보세요.","answer":["동아줄"],"explanation":["하늘에서 내려온 튼튼한 동아줄을 잡았어요.","오누이는 하늘로 올라가 해와 달이 되었어요.","줄거리에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"},"variant_rule":{"alt":[{"stem":"줄거리를 읽고 답해 보세요. 엄마가 집을 나서 팔러 간 것을 한 글자로 써 보세요.","answer":["떡"],"explanation":["엄마는 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오다 호랑이를 만났어요.","줄거리에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#10','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C8',3,'mc','auto','장소가 바뀔 때마다 일어난 일을 나누어 정리하면 좋은 점은 무엇인가요?',ARRAY['K2-1-u8-X13','K2-1-u8-X02']::text[],true,'{"seq":10,"concept":"K2-1-u8-C8","difficulty":3,"kind":"mc","stem":"장소가 바뀔 때마다 일어난 일을 나누어 정리하면 좋은 점은 무엇인가요?","options":[{"t":"일이 일어난 차례와 줄거리를 한눈에 알 수 있어요","correct":true},{"t":"인물의 이름을 바꿀 수 있어요","mis":"K2-1-u8-X13"},{"t":"작품을 끝까지 보지 않아도 돼요","mis":"K2-1-u8-X02"}],"explanation":["장소마다 일어난 일을 정리하면 줄거리가 보여요.","이름을 바꾸는 것과는 상관없어요.","작품은 끝까지 감상해야 해요."],"variant_rule":{"alt":[{"stem":"줄거리를 읽고 답해 보세요. 「호랑이가 오누이가 기다리는 집으로 찾아갔어요.」 바로 다음에 일어난 일은 무엇인가요?","options":[{"t":"오누이가 뒷문으로 빠져나가 나무 위로 올라갔어요","correct":true},{"t":"엄마가 고개에서 호랑이를 만났어요","mis":"K2-1-u8-X13"},{"t":"오누이가 해와 달이 되었어요","mis":"K2-1-u8-X13"}],"explanation":["호랑이가 집에 오자 오누이는 나무 위로 피했어요.","엄마가 호랑이를 만난 일은 그보다 앞이에요.","해와 달이 된 것은 맨 마지막이에요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#1','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',2,'mc','auto','인형극과 이야기책의 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":1,"concept":"K2-1-u8-C7","difficulty":2,"kind":"mc","stem":"인형극과 이야기책의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"인형극은 인물의 움직임과 목소리를 직접 보고 들을 수 있어요","correct":true},{"t":"인형극에는 인물이 나오지 않아요","mis":"K2-1-u8-X11"},{"t":"인형극에는 이야기가 없어요","mis":"K2-1-u8-X11"}],"explanation":["인형극은 움직임과 목소리로 이야기를 보여 줘요.","인형극에도 인물이 나와요.","인형극도 이야기를 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#2','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C8',2,'mc','auto','줄거리를 읽고 답해 보세요. 엄마가 집을 나서며 오누이에게 이른 것은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X04']::text[],false,'{"seq":2,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 엄마가 집을 나서며 오누이에게 이른 것은 무엇인가요?","options":[{"t":"문을 꼭 잠그라고","correct":true},{"t":"나무 위로 올라가라고","mis":"K2-1-u8-X03"},{"t":"떡을 팔아 오라고","mis":"K2-1-u8-X04"}],"explanation":["엄마는 문을 꼭 잠그라고 일렀어요.","나무에 올라가라는 말은 없어요.","떡을 팔러 간 것은 엄마예요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#3','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 호랑이가 굵고 느린 목소리로 말하자 오빠가 알아챈 것은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":3,"concept":"K2-1-u8-C7","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 호랑이가 굵고 느린 목소리로 말하자 오빠가 알아챈 것은 무엇인가요?","options":[{"t":"엄마 목소리와 다르다는 것","correct":true},{"t":"엄마가 감기에 걸렸다는 것","mis":"K2-1-u8-X03"},{"t":"누이가 문을 열었다는 것","mis":"K2-1-u8-X03"}],"explanation":["오빠는 「목소리가 엄마랑 달라.」라고 했어요.","감기에 걸렸다는 말은 없어요.","누이는 문을 열지 않고 손을 보여 달라고 했어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#4','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C8',3,'error','auto','줄거리를 읽고 일이 일어난 차례를 말했어요. 차례를 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u8-X13','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C8","difficulty":3,"kind":"error","stem":"줄거리를 읽고 일이 일어난 차례를 말했어요. 차례를 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「오누이가 하늘로 올라간 뒤에 호랑이가 집에 찾아왔어.」","correct":true,"mis_target":"K2-1-u8-X13"},{"t":"민준 — 「엄마가 고개에서 호랑이를 만난 뒤에 호랑이가 집에 찾아왔어.」","mis":"K2-1-u8-X19"},{"t":"소율 — 「오누이는 나무 위로 올라간 뒤에 동아줄을 잡았어.」","mis":"K2-1-u8-X19"}],"explanation":["호랑이가 집에 온 뒤에 오누이가 나무 위를 거쳐 하늘로 올라갔어요.","민준이와 소율이는 차례를 바르게 말했어요.","장소가 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#5','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',3,'ox','auto','같은 대사라도 목소리의 크기와 빠르기를 바꾸면 전해지는 마음이 달라져요.',ARRAY['K2-1-u8-X12']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":3,"kind":"ox","stem":"같은 대사라도 목소리의 크기와 빠르기를 바꾸면 전해지는 마음이 달라져요.","answer":"O","reason_options":[{"t":"「문 열어라.」도 굵고 느리게 하면 무섭게, 작고 부드럽게 하면 다정하게 들리니까","correct":true},{"t":"대사가 같으면 전해지는 마음도 언제나 같으니까","mis":"K2-1-u8-X12"}],"mis":"K2-1-u8-X12","explanation":["목소리에 따라 같은 말도 다르게 들려요.","그래서 인형극에서는 목소리를 잘 들어야 해요.","직접 두 가지 목소리로 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#6','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 오빠가 누이 손을 꼭 잡고 뒷문으로 살금살금 나간 행동에서 알 수 있는 오빠의 마음은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":6,"concept":"K2-1-u8-C7","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 오빠가 누이 손을 꼭 잡고 뒷문으로 살금살금 나간 행동에서 알 수 있는 오빠의 마음은 어느 것인가요?","options":[{"t":"동생을 지키며 무사히 달아나고 싶은 마음","correct":true},{"t":"동생과 장난치고 싶은 마음","mis":"K2-1-u8-X05"},{"t":"호랑이와 친해지고 싶은 마음","mis":"K2-1-u8-X05"}],"explanation":["손을 꼭 잡고 몰래 나간 행동에 동생을 지키려는 마음이 보여요.","장난치는 장면이 아니에요.","호랑이를 피해 달아나는 장면이에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#7','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C8',3,'mc','auto','줄거리를 읽고 답해 보세요. 장소가 「집」일 때 일어난 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":7,"concept":"K2-1-u8-C8","difficulty":3,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 장소가 「집」일 때 일어난 일로 알맞은 것은 어느 것인가요?","options":[{"t":"호랑이가 엄마 옷을 입고 찾아왔어요","correct":true},{"t":"엄마가 떡을 팔고 오다 호랑이를 처음 만났어요","mis":"K2-1-u8-X13"},{"t":"오누이가 동아줄을 잡았어요","mis":"K2-1-u8-X13"}],"explanation":["호랑이는 엄마 옷을 입고 집으로 찾아왔어요.","호랑이를 처음 만난 곳은 고개예요.","동아줄은 나무 위에서 잡았어요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#8','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',4,'mc','auto','인형극 대본을 읽고 답해 보세요. 「얘들아, 엄마 왔다. 문 열어라.」를 엄마인 척 속이려는 호랑이의 마음이 드러나게 연기하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X12','K2-1-u8-X11']::text[],false,'{"seq":8,"concept":"K2-1-u8-C7","difficulty":4,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 「얘들아, 엄마 왔다. 문 열어라.」를 엄마인 척 속이려는 호랑이의 마음이 드러나게 연기하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"엄마 목소리를 흉내 내 부드럽게 말하면서 인형을 문 쪽으로 슬금슬금 다가가게 하기","correct":true},{"t":"울먹이는 목소리로 말하며 인형을 바닥에 눕히기","mis":"K2-1-u8-X12"},{"t":"아무 움직임 없이 대사만 빠르게 읽기","mis":"K2-1-u8-X11"}],"explanation":["속이려는 마음은 꾸민 목소리와 슬금슬금 다가가는 움직임으로 살아나요.","울먹이는 목소리는 속이려는 마음과 맞지 않아요.","움직임 없이 빠르게 읽으면 마음이 드러나지 않아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#9','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 오빠와 누이 가운데 한 인물을 골라 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 오빠와 누이 가운데 한 인물을 골라 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 누이는 무척 무서웠을 거예요. 왜냐하면 떨리는 목소리로 말했고, 문을 열기 전에 손을 먼저 보여 달라고 할 만큼 의심스러웠기 때문이에요.","scoring_points":["한 인물을 골라 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#10','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C8',4,'essay','teacher','줄거리를 읽고 답해 보세요. 장소가 바뀔 때마다 일어난 일을 차례대로 정리해 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C8","difficulty":4,"kind":"essay","stem":"줄거리를 읽고 답해 보세요. 장소가 바뀔 때마다 일어난 일을 차례대로 정리해 써 보세요.","answer_guide":{"answer":"예: 집 — 엄마가 떡을 팔러 나섰어요. 고개 — 엄마가 호랑이를 만났어요. 집 — 호랑이가 엄마 옷을 입고 찾아왔어요. 나무 위 — 오누이가 호랑이를 피해 올라갔어요. 하늘 — 동아줄을 잡고 올라가 해와 달이 되었어요.","scoring_points":["장소를 차례대로 썼는가","장소마다 일어난 일을 썼는가","줄거리와 다른 내용을 넣지 않았는가"]},"explanation":["장소의 차례.","장소마다 일어난 일.","줄거리와 같은지."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#1','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C9',1,'mc','auto','인형극 대본을 읽고 답해 보세요. 형이 밤에 몰래 볏단을 옮긴 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],true,'{"seq":1,"concept":"K2-1-u8-C9","difficulty":1,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 형이 밤에 몰래 볏단을 옮긴 까닭은 무엇인가요?","options":[{"t":"아우가 살림을 막 차려서 쌀이 더 필요할 것 같아서","correct":true},{"t":"볏단이 너무 무거워 치우고 싶어서","mis":"K2-1-u8-X03"},{"t":"아우를 골탕 먹이고 싶어서","mis":"K2-1-u8-X05"}],"explanation":["형은 「아우는 살림을 막 차려서 쌀이 더 필요할 거야.」라고 했어요.","볏단이 무거워 치우려 했다는 말은 없어요.","아우를 생각해서 한 일이지 골탕 먹이려던 것이 아니에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 아우가 밤에 몰래 볏단을 옮긴 까닭은 무엇인가요?","options":[{"t":"형님은 식구가 많아서 볏단이 더 있어야 할 것 같아서","correct":true},{"t":"형님 볏단을 빼앗고 싶어서","mis":"K2-1-u8-X05"},{"t":"잠이 오지 않아 심심해서","mis":"K2-1-u8-X03"}],"explanation":["아우는 「형님은 식구가 많으니 볏단이 더 있어야 해.」라고 했어요.","아우는 볏단을 빼앗은 것이 아니라 가져다주었어요.","심심했다는 말은 없어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#2','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C10',1,'mc','auto','작품 속 인물에게 쓰는 편지에 꼭 담으면 좋은 것은 무엇인가요?',ARRAY['K2-1-u8-X14']::text[],true,'{"seq":2,"concept":"K2-1-u8-C10","difficulty":1,"kind":"mc","stem":"작품 속 인물에게 쓰는 편지에 꼭 담으면 좋은 것은 무엇인가요?","options":[{"t":"인물에게 하고 싶은 말과 그 까닭","correct":true},{"t":"내 생일 날짜","mis":"K2-1-u8-X14"},{"t":"작품의 글자 수","mis":"K2-1-u8-X14"}],"explanation":["하고 싶은 말과 까닭을 담으면 내 생각과 느낌이 잘 전해져요.","생일 날짜는 인물에게 할 말과 상관없어요.","글자 수도 상관없어요."],"variant_rule":{"alt":[{"stem":"인물에게 쓴 편지 첫 줄에 「형님께」라고 썼어요. 이 부분은 무엇을 나타내나요?","options":[{"t":"편지를 받는 인물","correct":true},{"t":"편지를 쓴 사람","mis":"K2-1-u8-X14"},{"t":"편지를 쓴 날의 날씨","mis":"K2-1-u8-X14"}],"explanation":["「형님께」는 편지를 받는 인물이에요.","쓴 사람은 편지 끝에 밝혀요.","날씨를 나타낸 말이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#3','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C9',1,'ox','auto','인형극 대본을 읽고 답해 보세요. 형과 아우는 볏단을 옮기기 전에 서로에게 미리 알렸어요.',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":3,"concept":"K2-1-u8-C9","difficulty":1,"kind":"ox","stem":"인형극 대본을 읽고 답해 보세요. 형과 아우는 볏단을 옮기기 전에 서로에게 미리 알렸어요.","answer":"X","reason_options":[{"t":"둘 다 몰래 집을 나서서 볏단을 옮겼다고 했으니까","correct":true},{"t":"둘이 함께 의논해서 옮겼으니까","mis":"K2-1-u8-X03"}],"mis":"K2-1-u8-X03","explanation":["형은 살금살금, 아우는 몰래 볏단을 옮겼어요.","그래서 다음 날 볏단이 줄지 않아 둘 다 놀랐어요.","대본에서 「몰래」를 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 형과 아우는 달밤에 마주쳐 서로의 마음을 알게 되었어요.","answer":"O","reason_options":[{"t":"형이 「네가 나를 생각해 주었구나.」라고 했으니까","correct":true},{"t":"두 사람은 끝까지 서로의 마음을 몰랐으니까","mis":"K2-1-u8-X03"}],"explanation":["달밤에 마주쳐 서로를 위해 볏단을 옮긴 것을 알았어요.","형은 아우를 꼭 안았어요.","대본에서 그 말을 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#4','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C11',1,'mc','auto','감상을 발표할 때의 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],true,'{"seq":4,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"감상을 발표할 때의 바른 자세는 어느 것인가요?","options":[{"t":"또박또박 말하고 왜 그렇게 생각했는지 까닭도 함께 말해요","correct":true},{"t":"작은 목소리로 웅얼웅얼 말해요","mis":"K2-1-u8-X15"},{"t":"바닥만 보며 빨리 끝내요","mis":"K2-1-u8-X15"}],"explanation":["또박또박 까닭과 함께 말하면 감상이 잘 전해져요.","웅얼거리면 친구들이 듣기 어려워요.","바닥만 보면 마음이 잘 전해지지 않아요."],"variant_rule":{"alt":[{"stem":"친구의 감상 발표를 들을 때의 바른 자세는 어느 것인가요?","options":[{"t":"좋은 점을 찾으며 끝까지 들어요","correct":true},{"t":"나와 다르면 틀렸다고 말해요","mis":"K2-1-u8-X15"},{"t":"짝과 다른 이야기를 해요","mis":"K2-1-u8-X15"}],"explanation":["좋은 점을 찾으며 들으면 감상이 넓어져요.","나와 다른 감상도 틀린 것이 아니에요.","딴 이야기를 하면 발표를 들을 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#5','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C10',2,'match','auto','편지를 읽고 편지의 부분과 그 부분이 나타내는 것을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C10","difficulty":2,"kind":"match","stem":"편지를 읽고 편지의 부분과 그 부분이 나타내는 것을 알맞게 이어 보세요.","pairs":[{"l":"형님께","r":"받는 인물"},{"l":"형님처럼 동생을 먼저 생각해 볼게요","r":"하고 싶은 말"},{"l":"2학년 하준 올림","r":"쓴 사람"}],"mis":"K2-1-u8-X14","explanation":["「형님께」는 받는 인물이에요.","다짐하는 말은 하준이가 하고 싶은 말이에요.","「하준 올림」은 쓴 사람이에요."],"asset":{"type":"passage","lines":["형님께","형님, 아우를 위해 밤마다 무거운 볏단을 몰래 옮기신 장면을 보고 마음이 따뜻해졌어요.","저도 동생이 있는데 장난감을 잘 빌려주지 않았거든요.","이제는 형님처럼 동생을 먼저 생각해 볼게요.","— 2학년 하준 올림"],"title":"하준이가 형에게 쓴 편지"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 편지를 읽고 편지의 부분과 그 부분이 나타내는 것을 알맞게 이어 보세요.","pairs":[{"l":"보보에게","r":"받는 인물"},{"l":"다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라","r":"하고 싶은 말"},{"l":"서윤이가","r":"쓴 사람"}],"explanation":["「보보에게」는 받는 인물이에요.","바라는 말은 서윤이가 하고 싶은 말이에요.","「서윤이가」는 쓴 사람이에요."],"asset":{"type":"passage","lines":["보보에게","보보야, 도시락이 텅 비어 있을 때 많이 속상했지?","토토와 다미가 음식을 나눠 줄 때 나도 덩달아 기뻤어.","다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라.","— 서윤이가"],"title":"서윤이가 보보에게 쓴 편지"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#6','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C9',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 다음 날 아침 형과 아우가 고개를 갸웃한 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":6,"concept":"K2-1-u8-C9","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 다음 날 아침 형과 아우가 고개를 갸웃한 까닭은 무엇인가요?","options":[{"t":"볏단이 하나도 줄지 않아서","correct":true},{"t":"볏단이 모두 없어져서","mis":"K2-1-u8-X03"},{"t":"밤새 비가 와서","mis":"K2-1-u8-X03"}],"explanation":["서로 옮겼는데도 볏단이 줄지 않아 이상했어요.","볏단이 없어진 것이 아니라 그대로였어요.","비가 왔다는 말은 없어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 형이 볏단을 내려놓고 아우를 꼭 안은 까닭은 무엇인가요?","options":[{"t":"아우도 자기를 생각해 주었다는 것을 알게 되어서","correct":true},{"t":"볏단이 무거워서","mis":"K2-1-u8-X06"},{"t":"아우가 볏단을 훔쳐 가서","mis":"K2-1-u8-X05"}],"explanation":["형은 「네가 나를 생각해 주었구나.」라고 했어요.","볏단이 무거운 것은 아우를 안은 까닭이 아니에요.","아우는 훔친 것이 아니라 가져다주었어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#7','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 하준이가 형에게 다짐한 것은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":7,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 하준이가 형에게 다짐한 것은 무엇인가요?","options":[{"t":"형님처럼 동생을 먼저 생각하겠다","correct":true},{"t":"밤마다 볏단을 옮기겠다","mis":"K2-1-u8-X03"},{"t":"새 장난감을 사겠다","mis":"K2-1-u8-X03"}],"explanation":["하준이는 「형님처럼 동생을 먼저 생각해 볼게요.」라고 했어요.","볏단을 옮기겠다는 말은 없어요.","장난감을 사겠다는 말도 없어요."],"asset":{"type":"passage","lines":["형님께","형님, 아우를 위해 밤마다 무거운 볏단을 몰래 옮기신 장면을 보고 마음이 따뜻해졌어요.","저도 동생이 있는데 장난감을 잘 빌려주지 않았거든요.","이제는 형님처럼 동생을 먼저 생각해 볼게요.","— 2학년 하준 올림"],"title":"하준이가 형에게 쓴 편지"},"variant_rule":{"alt":[{"stem":"편지를 읽고 답해 보세요. 서윤이가 보보에게 바란 것은 무엇인가요?","options":[{"t":"다음 소풍에는 맛있는 도시락을 싸 가기를","correct":true},{"t":"토토와 다투지 않기를","mis":"K2-1-u8-X03"},{"t":"혼자 소풍을 가기를","mis":"K2-1-u8-X03"}],"explanation":["서윤이는 맛있는 도시락을 싸 가길 바랐어요.","토토와 다투었다는 내용은 없어요.","혼자 가라는 말은 없어요."],"asset":{"type":"passage","lines":["보보에게","보보야, 도시락이 텅 비어 있을 때 많이 속상했지?","토토와 다미가 음식을 나눠 줄 때 나도 덩달아 기뻤어.","다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라.","— 서윤이가"],"title":"서윤이가 보보에게 쓴 편지"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#8','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C11',2,'error','auto','친구의 감상 발표를 듣고 한 말이에요. 바르지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u8-X15','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C11","difficulty":2,"kind":"error","stem":"친구의 감상 발표를 듣고 한 말이에요. 바르지 않게 말한 친구는 누구인가요?","options":[{"t":"하람 — 「나는 다른 장면이 좋았으니까 네 감상은 틀렸어.」","correct":true,"mis_target":"K2-1-u8-X15"},{"t":"아린 — 「네 까닭을 들으니 나도 그 장면이 다시 떠올라.」","mis":"K2-1-u8-X19"},{"t":"지우 — 「나와 고른 장면은 다르지만 형제를 아끼는 마음에 감동한 점은 비슷하네.」","mis":"K2-1-u8-X19"}],"explanation":["나와 다른 감상도 틀린 것이 아니에요.","아린이와 지우는 좋은 점을 찾고 견주어 들었어요.","물음의 「바르지 않게」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"감상을 발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?","options":[{"t":"태민 — 친구들에게 등을 돌리고 작게 웅얼거렸어요","correct":true,"mis_target":"K2-1-u8-X15"},{"t":"하린 — 친구들을 바라보며 또박또박 말했어요","mis":"K2-1-u8-X19"},{"t":"건우 — 기억에 남는 장면과 까닭을 함께 말했어요","mis":"K2-1-u8-X19"}],"explanation":["등을 돌리고 웅얼거리면 감상이 전해지지 않아요.","하린이와 건우는 바르게 발표했어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#9','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C9',2,'sa','auto','인형극 대본을 읽고 답해 보세요. 형과 아우가 밤마다 몰래 옮긴 것을 두 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C9","difficulty":2,"kind":"sa","stem":"인형극 대본을 읽고 답해 보세요. 형과 아우가 밤마다 몰래 옮긴 것을 두 글자로 써 보세요.","answer":["볏단"],"explanation":["형과 아우는 볏단을 지고 몰래 옮겼어요.","서로를 위해 옮겼어요.","대본에서 그 말을 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 형과 아우가 마주친 날 밤하늘에 떠 있던 것을 한 글자로 써 보세요.","answer":["달"],"explanation":["사흘째 밤 하늘에 둥근 달이 떴어요.","달밤에 두 사람이 마주쳤어요.","대본에서 그 말을 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#10','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C10',3,'mc','auto','「의좋은 형제」의 인물에게 쓴 편지예요. 받는 인물·하고 싶은 말·까닭이 가장 잘 드러나게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u8-X14']::text[],true,'{"seq":10,"concept":"K2-1-u8-C10","difficulty":3,"kind":"mc","stem":"「의좋은 형제」의 인물에게 쓴 편지예요. 받는 인물·하고 싶은 말·까닭이 가장 잘 드러나게 쓴 것은 어느 것인가요?","options":[{"t":"「아우님께, 형님을 위해 몰래 볏단을 옮긴 마음이 멋져요. 저도 언니를 먼저 생각하는 동생이 될게요.」","correct":true},{"t":"「아우님께, 안녕. 잘 지내.」","mis":"K2-1-u8-X14"},{"t":"「엄마께, 오늘 저녁 반찬은 뭐예요?」","mis":"K2-1-u8-X14"}],"explanation":["받는 인물·하고 싶은 말·까닭이 모두 들어 있어요.","인사만 있고 하고 싶은 말과 까닭이 없어요.","작품 속 인물에게 쓴 편지가 아니에요."],"variant_rule":{"alt":[{"stem":"「보보의 빈 도시락」의 인물에게 쓴 편지예요. 받는 인물·하고 싶은 말·까닭이 가장 잘 드러나게 쓴 것은 어느 것인가요?","options":[{"t":"「토토에게, 혼자 있던 보보에게 먼저 다가가 줘서 멋졌어. 나도 외로운 친구에게 먼저 말을 걸어 볼게.」","correct":true},{"t":"「토토에게, 토토는 토끼구나.」","mis":"K2-1-u8-X14"},{"t":"「짝에게, 내일 같이 놀자.」","mis":"K2-1-u8-X14"}],"explanation":["받는 인물·하고 싶은 말·까닭이 모두 들어 있어요.","하고 싶은 말과 까닭이 없어요.","작품 속 인물에게 쓴 편지가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#1','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C9',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 형이 「아니, 저기 오는 사람은……?」 하고 멈칫할 때의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":1,"concept":"K2-1-u8-C9","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 형이 「아니, 저기 오는 사람은……?」 하고 멈칫할 때의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"누구일까 궁금하고 놀랍다","correct":true},{"t":"신나고 즐겁다","mis":"K2-1-u8-X05"},{"t":"졸리고 지루하다","mis":"K2-1-u8-X05"}],"explanation":["어두운 밤 누군가 다가오니 궁금하고 놀랐을 거예요.","멈칫하는 행동에서 신나는 마음은 보이지 않아요.","졸린 마음은 이 장면과 맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#2','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',2,'mc','auto','감상 발표를 읽고 답해 보세요. 민준이가 가장 기억에 남는다고 한 장면은 무엇인가요?',ARRAY['K2-1-u8-X10']::text[],false,'{"seq":2,"concept":"K2-1-u8-C11","difficulty":2,"kind":"mc","stem":"감상 발표를 읽고 답해 보세요. 민준이가 가장 기억에 남는다고 한 장면은 무엇인가요?","options":[{"t":"달밤에 형과 아우가 마주치는 장면","correct":true},{"t":"볏단이 줄지 않아 고개를 갸웃하는 장면","mis":"K2-1-u8-X10"},{"t":"형이 혼자 볏단을 지고 가는 장면","mis":"K2-1-u8-X10"}],"explanation":["민준이는 달밤에 마주치는 장면을 골랐어요.","고개를 갸웃하는 장면은 민준이가 고른 장면이 아니에요.","형이 혼자 가는 장면도 아니에요."],"asset":{"type":"passage","lines":["저는 「의좋은 형제」에서 달밤에 형과 아우가 마주치는 장면이 가장 기억에 남아요.","서로를 위해 몰래 볏단을 옮긴 것을 알게 되어 가슴이 찡했기 때문이에요.","저도 언니가 몰래 제 준비물을 챙겨 준 것을 알고 뭉클했던 적이 있어요."],"title":"민준이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#3','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 볏단이 하나도 줄지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":3,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 볏단이 하나도 줄지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"형이 옮긴 만큼 아우도 형에게 볏단을 옮겼기 때문에","correct":true},{"t":"볏단이 저절로 늘어났기 때문에","mis":"K2-1-u8-X03"},{"t":"이웃이 볏단을 가져다 놓았기 때문에","mis":"K2-1-u8-X03"}],"explanation":["두 사람이 서로에게 옮겨서 볏단 수가 그대로였어요.","볏단이 저절로 늘어나지는 않아요.","이웃 이야기는 대본에 없어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#4','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C10',3,'error','auto','「의좋은 형제」의 형에게 편지를 썼어요. 작품 내용과 맞지 않게 쓴 친구는 누구인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C10","difficulty":3,"kind":"error","stem":"「의좋은 형제」의 형에게 편지를 썼어요. 작품 내용과 맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"도담 — 「형님, 아우의 볏단을 몰래 빼앗아 가서 실망했어요.」","correct":true,"mis_target":"K2-1-u8-X03"},{"t":"서아 — 「형님, 식구가 많아 힘드실 텐데 아우를 먼저 생각하셔서 놀라웠어요.」","mis":"K2-1-u8-X19"},{"t":"준우 — 「형님, 달밤에 아우를 꼭 안아 주는 장면에서 저도 따뜻해졌어요.」","mis":"K2-1-u8-X19"}],"explanation":["형은 볏단을 빼앗지 않고 아우에게 가져다주었어요.","서아와 준우는 작품 내용에 맞게 썼어요.","작품에서 형이 한 일을 다시 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#5','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',3,'ox','auto','친구의 감상이 나와 다르면 견주어 들으며 비슷한 점과 다른 점을 찾아요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":5,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"친구의 감상이 나와 다르면 견주어 들으며 비슷한 점과 다른 점을 찾아요.","answer":"O","reason_options":[{"t":"견주어 들으면 작품을 더 넓고 깊게 감상할 수 있으니까","correct":true},{"t":"나와 다른 감상은 들을 필요가 없으니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["친구의 감상에서 내가 못 본 점을 발견할 수 있어요.","다른 감상도 존중하며 들어요.","비슷한 점·다른 점을 찾아 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#6','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',3,'mc','auto','감상 발표를 읽고 답해 보세요. 민준이가 말한 「비슷한 내 경험」에 해당하는 것은 어느 것인가요?',ARRAY['K2-1-u8-X10']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":3,"kind":"mc","stem":"감상 발표를 읽고 답해 보세요. 민준이가 말한 「비슷한 내 경험」에 해당하는 것은 어느 것인가요?","options":[{"t":"언니가 몰래 준비물을 챙겨 준 것을 알고 뭉클했던 일","correct":true},{"t":"달밤에 형과 아우가 마주친 일","mis":"K2-1-u8-X10"},{"t":"서로를 위해 볏단을 옮긴 것을 알게 된 일","mis":"K2-1-u8-X10"}],"explanation":["민준이는 마지막 문장에서 자기 경험을 말했어요.","달밤에 마주친 것은 작품 속 장면이에요.","볏단을 옮긴 것도 작품 속 일이에요."],"asset":{"type":"passage","lines":["저는 「의좋은 형제」에서 달밤에 형과 아우가 마주치는 장면이 가장 기억에 남아요.","서로를 위해 몰래 볏단을 옮긴 것을 알게 되어 가슴이 찡했기 때문이에요.","저도 언니가 몰래 제 준비물을 챙겨 준 것을 알고 뭉클했던 적이 있어요."],"title":"민준이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#7','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C10',3,'mc','auto','인물에게 편지를 쓸 때 가장 중요하게 생각해야 할 것은 무엇인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":7,"concept":"K2-1-u8-C10","difficulty":3,"kind":"mc","stem":"인물에게 편지를 쓸 때 가장 중요하게 생각해야 할 것은 무엇인가요?","options":[{"t":"인물에게 하고 싶은 말을 솔직한 내 마음으로 담는 것","correct":true},{"t":"날짜를 맨 위에 꼭 크게 쓰는 것","mis":"K2-1-u8-X14"},{"t":"편지지를 예쁘게 꾸미는 것","mis":"K2-1-u8-X14"}],"explanation":["편지는 인물에게 내 마음을 전하는 감상 활동이에요.","형식보다 마음을 담는 것이 더 중요해요.","꾸미기보다 하고 싶은 말이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#8','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',4,'mc','auto','채원이는 「보보의 빈 도시락」에서 토토가 먼저 다가간 장면을, 민준이는 「의좋은 형제」에서 형제가 마주친 장면을 골랐어요. 두 감상을 견주어 볼 때 비슷한 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X10']::text[],false,'{"seq":8,"concept":"K2-1-u8-C11","difficulty":4,"kind":"mc","stem":"채원이는 「보보의 빈 도시락」에서 토토가 먼저 다가간 장면을, 민준이는 「의좋은 형제」에서 형제가 마주친 장면을 골랐어요. 두 감상을 견주어 볼 때 비슷한 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 다른 이를 먼저 생각하는 인물의 마음에 감동했어요","correct":true},{"t":"둘 다 같은 작품을 골랐어요","mis":"K2-1-u8-X03"},{"t":"둘 다 까닭을 말하지 않았어요","mis":"K2-1-u8-X10"}],"explanation":["토토와 형제 모두 남을 먼저 생각했고, 두 친구는 그 마음에 감동했어요.","두 친구는 서로 다른 작품을 골랐어요.","두 친구 모두 까닭을 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#9','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C10',4,'essay','teacher','「의좋은 형제」의 형이나 아우 가운데 한 인물에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「의좋은 형제」의 형이나 아우 가운데 한 인물에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 아우님께 — 아우님, 식구가 많은 형님을 걱정해서 밤마다 볏단을 옮긴 마음이 정말 멋졌어요. 저는 동생과 간식을 나눌 때 큰 쪽을 먼저 집었거든요. 이제는 아우님처럼 동생 몫을 먼저 챙길게요. — 2학년 은솔 올림","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#10','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',4,'essay','teacher','감상 발표를 읽고 답해 보세요. 민준이의 감상과 내 감상을 견주어 비슷한 점과 다른 점을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C11","difficulty":4,"kind":"essay","stem":"감상 발표를 읽고 답해 보세요. 민준이의 감상과 내 감상을 견주어 비슷한 점과 다른 점을 써 보세요.","answer_guide":{"answer":"예: 민준이는 형제가 마주치는 장면이 기억에 남는다고 했고, 저는 볏단이 줄지 않아 고개를 갸웃하는 장면이 기억에 남아요. 고른 장면은 다르지만 서로를 아끼는 형제의 마음에 감동한 점은 비슷해요.","scoring_points":["민준이의 감상을 바르게 옮겼는가","내 감상을 썼는가","비슷한 점과 다른 점을 모두 썼는가"]},"explanation":["민준이의 감상.","내 감상.","비슷한 점·다른 점."],"asset":{"type":"passage","lines":["저는 「의좋은 형제」에서 달밤에 형과 아우가 마주치는 장면이 가장 기억에 남아요.","서로를 위해 몰래 볏단을 옮긴 것을 알게 되어 가슴이 찡했기 때문이에요.","저도 언니가 몰래 제 준비물을 챙겨 준 것을 알고 뭉클했던 적이 있어요."],"title":"민준이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#1','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',1,'mc','auto','막대 인형을 만들 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K2-1-u8-X16']::text[],true,'{"seq":1,"concept":"K2-1-u8-C12","difficulty":1,"kind":"mc","stem":"막대 인형을 만들 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"맡은 인물을 두꺼운 종이에 그려요","correct":true},{"t":"인형에 막대를 붙여요","mis":"K2-1-u8-X16"},{"t":"친구들 앞에서 공연해요","mis":"K2-1-u8-X16"}],"explanation":["먼저 인물을 그려야 오리고 막대를 붙일 수 있어요.","막대는 그리고 오린 다음에 붙여요.","공연은 인형을 다 만든 뒤에 해요."],"variant_rule":{"alt":[{"stem":"막대 인형 만드는 차례예요. 「인물 그리기 → 오리기 → (   )」 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"막대 붙이기","correct":true},{"t":"표 사기","mis":"K2-1-u8-X16"},{"t":"공연 끝내기","mis":"K2-1-u8-X16"}],"explanation":["그린 인물을 오린 뒤 막대를 붙여요.","표를 사는 것은 만드는 차례가 아니에요.","공연은 다 만든 뒤에 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#2','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',1,'mc','auto','모둠 계획을 읽고 답해 보세요. 호랑이 역할을 맡은 친구는 누구인가요?',ARRAY['K2-1-u8-X04']::text[],true,'{"seq":2,"concept":"K2-1-u8-C12","difficulty":1,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 호랑이 역할을 맡은 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"아린","mis":"K2-1-u8-X04"},{"t":"지호","mis":"K2-1-u8-X04"}],"explanation":["호랑이는 도윤이가 맡았어요.","아린이는 오빠 역이에요.","지호는 해설을 맡았어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"},"variant_rule":{"alt":[{"stem":"모둠 계획을 읽고 답해 보세요. 흥부 역할을 맡은 친구는 누구인가요?","options":[{"t":"현우","correct":true},{"t":"예린","mis":"K2-1-u8-X04"},{"t":"건우","mis":"K2-1-u8-X04"}],"explanation":["흥부는 현우가 맡았어요.","예린이는 흥부 아내 역이에요.","건우는 해설을 맡았어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#3','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',1,'ox','auto','막대 인형은 인물의 특징만 살려 간단하게 만들어요.',ARRAY['K2-1-u8-X16']::text[],true,'{"seq":3,"concept":"K2-1-u8-C12","difficulty":1,"kind":"ox","stem":"막대 인형은 인물의 특징만 살려 간단하게 만들어요.","answer":"O","reason_options":[{"t":"인형을 완성하는 것보다 인형극 놀이가 더 중요하니까","correct":true},{"t":"인형을 아주 정교하게 꾸미는 것이 가장 중요하니까","mis":"K2-1-u8-X16"}],"mis":"K2-1-u8-X16","explanation":["간단히 만들고 인형극 놀이에 시간을 써요.","인물의 특징만 드러나면 충분해요.","마음을 살린 대사와 움직임 연습이 더 중요해요."],"variant_rule":{"alt":[{"stem":"친구들의 인형극을 볼 때는 무대 앞으로 나가 인형을 만져 봐요.","answer":"X","reason_options":[{"t":"자리에 앉아 바른 자세로 봐야 공연을 방해하지 않으니까","correct":true},{"t":"가까이 가야 인형이 더 잘 보이니까","mis":"K2-1-u8-X17"}],"explanation":["무대 앞으로 나가면 공연이 멈춰요.","자리에서 조용히 바른 자세로 봐요.","끝난 뒤 좋았던 점을 이야기해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#4','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',1,'mc','auto','인형극을 발표하는 친구가 지킬 약속으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X16']::text[],true,'{"seq":4,"concept":"K2-1-u8-C12","difficulty":1,"kind":"mc","stem":"인형극을 발표하는 친구가 지킬 약속으로 알맞은 것은 어느 것인가요?","options":[{"t":"관객이 잘 듣도록 또박또박 천천히 대사를 말해요","correct":true},{"t":"관객에게 등을 돌리고 대사를 말해요","mis":"K2-1-u8-X16"},{"t":"대사를 아무 느낌 없이 빨리 읽어요","mis":"K2-1-u8-X16"}],"explanation":["또박또박 천천히 말해야 관객이 잘 들어요.","등을 돌리면 목소리가 잘 들리지 않아요.","느낌 없이 빨리 읽으면 인물의 마음이 전해지지 않아요."],"variant_rule":{"alt":[{"stem":"인형극을 보는 친구가 지킬 약속으로 알맞은 것은 어느 것인가요?","options":[{"t":"끝나면 박수를 치고 좋았던 점을 말해요","correct":true},{"t":"공연 중에 크게 떠들어요","mis":"K2-1-u8-X17"},{"t":"공연 중간에 일어나 돌아다녀요","mis":"K2-1-u8-X17"}],"explanation":["박수와 칭찬은 공연한 친구에게 힘이 돼요.","떠들면 대사가 들리지 않아요.","돌아다니면 공연을 방해해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#5','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'match','auto','인형극에서 맡는 역할과 하는 일을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C12","difficulty":2,"kind":"match","stem":"인형극에서 맡는 역할과 하는 일을 알맞게 이어 보세요.","pairs":[{"l":"인형 움직이기","r":"인물에 맞게 인형을 움직여요"},{"l":"대사 말하기","r":"인물의 마음을 살려 말을 해요"},{"l":"해설","r":"장면이나 상황을 설명해요"}],"mis":"K2-1-u8-X16","explanation":["인형을 움직이는 친구는 인물답게 움직여요.","대사는 마음을 살려 말해요.","해설은 장면을 알려 줘요."],"variant_rule":{"alt":[{"stem":"모둠 계획을 읽고 인물과 그 역할을 맡은 친구를 알맞게 이어 보세요.","pairs":[{"l":"호랑이","r":"도윤"},{"l":"오빠","r":"아린"},{"l":"해설","r":"지호"}],"explanation":["호랑이는 도윤이가 맡았어요.","오빠는 아린이가 맡았어요.","해설은 지호가 맡았어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#6','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'mc','auto','모둠 계획을 읽고 답해 보세요. 3모둠이 보여 줄 장면은 무엇인가요?',ARRAY['K2-1-u8-X04']::text[],true,'{"seq":6,"concept":"K2-1-u8-C12","difficulty":2,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 3모둠이 보여 줄 장면은 무엇인가요?","options":[{"t":"호랑이가 문을 두드리는 장면","correct":true},{"t":"오누이가 동아줄을 잡는 장면","mis":"K2-1-u8-X04"},{"t":"흥부네가 박을 타는 장면","mis":"K2-1-u8-X04"}],"explanation":["계획표에 호랑이가 문을 두드리는 장면이라고 했어요.","동아줄 장면은 3모둠이 고른 장면이 아니에요.","박을 타는 장면은 1모둠이 고른 장면이에요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"},"variant_rule":{"alt":[{"stem":"모둠 계획을 읽고 답해 보세요. 1모둠이 보여 줄 장면은 무엇인가요?","options":[{"t":"흥부네가 박을 타는 장면","correct":true},{"t":"호랑이가 문을 두드리는 장면","mis":"K2-1-u8-X04"},{"t":"형과 아우가 마주치는 장면","mis":"K2-1-u8-X04"}],"explanation":["계획표에 흥부네가 박을 타는 장면이라고 했어요.","호랑이 장면은 3모둠이 고른 장면이에요.","형과 아우 장면은 다른 작품이에요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#7','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'mc','auto','인형극에서 호랑이가 「얘들아, 엄마 왔다. 문 열어라.」라고 말할 때 무서운 느낌을 살리는 목소리는 어느 것인가요?',ARRAY['K2-1-u8-X12','K2-1-u8-X16']::text[],true,'{"seq":7,"concept":"K2-1-u8-C12","difficulty":2,"kind":"mc","stem":"인형극에서 호랑이가 「얘들아, 엄마 왔다. 문 열어라.」라고 말할 때 무서운 느낌을 살리는 목소리는 어느 것인가요?","options":[{"t":"굵고 느린 목소리","correct":true},{"t":"작고 귀여운 목소리","mis":"K2-1-u8-X12"},{"t":"아무 느낌 없이 빠르게 읽는 목소리","mis":"K2-1-u8-X16"}],"explanation":["굵고 느린 목소리가 호랑이의 무서운 느낌을 살려요.","작고 귀여운 목소리는 무서운 호랑이와 맞지 않아요.","느낌 없이 빨리 읽으면 인물이 살아나지 않아요."],"variant_rule":{"alt":[{"stem":"인형극에서 흥부가 「아이고, 이게 웬 쌀이오!」라고 말할 때 마음을 살리는 목소리는 어느 것인가요?","options":[{"t":"깜짝 놀라 들뜬 커다란 목소리","correct":true},{"t":"힘없이 축 처진 목소리","mis":"K2-1-u8-X12"},{"t":"아무 느낌 없이 빠르게 읽는 목소리","mis":"K2-1-u8-X16"}],"explanation":["놀랍고 기쁜 마음은 들뜬 큰 목소리로 살아나요.","축 처진 목소리는 슬플 때 어울려요.","느낌 없이 읽으면 마음이 전해지지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#8','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'error','auto','친구들이 인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?',ARRAY['K2-1-u8-X17','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"친구들이 인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?","options":[{"t":"하람 — 공연 중에 「저거 틀렸다!」 하고 크게 외쳤어요","correct":true,"mis_target":"K2-1-u8-X17"},{"t":"윤서 — 자리에 앉아 조용히 끝까지 보았어요","mis":"K2-1-u8-X19"},{"t":"민호 — 공연이 끝나자 박수를 치고 좋았던 점을 말했어요","mis":"K2-1-u8-X19"}],"explanation":["공연 중에 외치면 공연하는 친구가 당황해요.","윤서와 민호는 바른 자세로 보았어요.","물음의 「바르지 않게」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"모둠이 인형극을 준비하는 모습이에요. 바르지 않게 준비한 모둠은 어느 것인가요?","options":[{"t":"2모둠 — 인형을 꾸미느라 대사 연습을 한 번도 하지 않았어요","correct":true,"mis_target":"K2-1-u8-X16"},{"t":"4모둠 — 인형을 간단히 만들고 대사를 여러 번 연습했어요","mis":"K2-1-u8-X19"},{"t":"5모둠 — 모두가 한 가지씩 역할을 나누어 맡았어요","mis":"K2-1-u8-X19"}],"explanation":["인형 꾸미기보다 인형극 놀이와 연습이 더 중요해요.","4모둠과 5모둠은 바르게 준비했어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#9','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'sa','auto','모둠 계획을 읽고 답해 보세요. 준비물 가운데 종이 인형을 붙여 손으로 잡고 움직이는 것을 두 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C12","difficulty":2,"kind":"sa","stem":"모둠 계획을 읽고 답해 보세요. 준비물 가운데 종이 인형을 붙여 손으로 잡고 움직이는 것을 두 글자로 써 보세요.","answer":["막대"],"explanation":["막대에 인형을 붙여 잡고 움직여요.","그래서 막대 인형극이라고 해요.","계획표의 준비물을 짚어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"},"variant_rule":{"alt":[{"stem":"모둠 계획을 읽고 답해 보세요. 1모둠에서 해설을 맡은 친구의 이름을 써 보세요.","answer":["건우"],"explanation":["해설은 건우가 맡았어요.","해설은 장면이나 상황을 설명해요.","계획표의 역할을 짚어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#10','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',3,'mc','auto','인형극을 할 때 이야기 한 편을 다 보여 주기보다 한 장면을 충실히 보여 주면 좋은 까닭은 무엇인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X17']::text[],true,'{"seq":10,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"인형극을 할 때 이야기 한 편을 다 보여 주기보다 한 장면을 충실히 보여 주면 좋은 까닭은 무엇인가요?","options":[{"t":"짧은 장면이라도 인물의 마음을 살려 실감 나게 보여 줄 수 있어서","correct":true},{"t":"연습을 하지 않아도 되어서","mis":"K2-1-u8-X16"},{"t":"관객이 보지 않아도 되어서","mis":"K2-1-u8-X17"}],"explanation":["한 장면에 집중하면 목소리와 움직임을 더 살릴 수 있어요.","한 장면이라도 연습은 꼭 해야 해요.","관객도 바른 자세로 끝까지 봐요."],"variant_rule":{"alt":[{"stem":"인형극을 할 때 모둠 친구들이 역할을 골고루 나누어 맡는 까닭은 무엇인가요?","options":[{"t":"모두가 인형극에 함께 참여할 수 있어서","correct":true},{"t":"한 사람만 힘들게 하려고","mis":"K2-1-u8-X16"},{"t":"구경만 하는 친구가 많아지라고","mis":"K2-1-u8-X16"}],"explanation":["역할을 나누면 모두가 함께 즐길 수 있어요.","한 사람만 힘들면 함께하는 인형극이 아니에요.","모두가 맡은 일이 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#1','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',2,'mc','auto','모둠 계획을 읽고 답해 보세요. 흥부 아내 역할을 맡은 친구는 누구인가요?',ARRAY['K2-1-u8-X04']::text[],false,'{"seq":1,"concept":"K2-1-u8-C12","difficulty":2,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 흥부 아내 역할을 맡은 친구는 누구인가요?","options":[{"t":"예린","correct":true},{"t":"다은","mis":"K2-1-u8-X04"},{"t":"현우","mis":"K2-1-u8-X04"}],"explanation":["흥부 아내는 예린이가 맡았어요.","다은이는 아이들 역이에요.","현우는 흥부 역이에요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#2','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',2,'mc','auto','막대 인형을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X16']::text[],false,'{"seq":2,"concept":"K2-1-u8-C12","difficulty":2,"kind":"mc","stem":"막대 인형을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인물 그리기 → 오리기 → 막대 붙이기 → 움직여 보기","correct":true},{"t":"막대 붙이기 → 인물 그리기 → 오리기 → 움직여 보기","mis":"K2-1-u8-X16"},{"t":"오리기 → 움직여 보기 → 인물 그리기 → 막대 붙이기","mis":"K2-1-u8-X16"}],"explanation":["그리고, 오리고, 막대를 붙인 뒤 움직여 봐요.","그리기 전에 막대를 붙일 수 없어요.","그리지 않은 종이는 오릴 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#3','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'mc','auto','모둠 계획을 읽고 답해 보세요. 오빠 역을 맡은 아린이가 「얼른 나무 위로 올라가자!」라고 말할 때 인형을 움직이는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X17']::text[],false,'{"seq":3,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 오빠 역을 맡은 아린이가 「얼른 나무 위로 올라가자!」라고 말할 때 인형을 움직이는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"누이 인형 곁에 붙어 서둘러 무대 옆으로 빠져나가게 움직여요","correct":true},{"t":"인형을 가만히 세워 두어요","mis":"K2-1-u8-X16"},{"t":"인형을 관객 쪽으로 던져요","mis":"K2-1-u8-X17"}],"explanation":["달아나는 급한 마음이 서두르는 움직임으로 살아나요.","가만히 있으면 급한 마음이 드러나지 않아요.","인형을 던지면 위험하고 공연이 망가져요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#4','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'error','auto','모둠이 인형극 준비를 하며 낸 의견이에요. 바르지 않은 의견을 낸 친구는 누구인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C12","difficulty":3,"kind":"error","stem":"모둠이 인형극 준비를 하며 낸 의견이에요. 바르지 않은 의견을 낸 친구는 누구인가요?","options":[{"t":"소율 — 「대사는 외우기 어려우니까 아무 느낌 없이 빨리 읽고 끝내자.」","correct":true,"mis_target":"K2-1-u8-X16"},{"t":"지호 — 「해설은 장면을 천천히 알려 주면 좋겠어.」","mis":"K2-1-u8-X19"},{"t":"도윤 — 「호랑이는 굵고 느린 목소리로 하면 더 무섭겠다.」","mis":"K2-1-u8-X19"}],"explanation":["느낌 없이 빨리 읽으면 인물의 마음이 전해지지 않아요.","지호와 도윤이는 인물과 장면을 살리는 의견을 냈어요.","물음의 「바르지 않은」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#5','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'ox','auto','인형극을 보고 나면 좋았던 점과 인물의 마음이 잘 드러난 부분을 서로 이야기해요.',ARRAY['K2-1-u8-X17']::text[],false,'{"seq":5,"concept":"K2-1-u8-C12","difficulty":3,"kind":"ox","stem":"인형극을 보고 나면 좋았던 점과 인물의 마음이 잘 드러난 부분을 서로 이야기해요.","answer":"O","reason_options":[{"t":"감상을 나누면 작품을 더 깊이 느끼고 공연한 친구도 힘이 나니까","correct":true},{"t":"인형극은 보고 나면 그대로 끝나는 것이니까","mis":"K2-1-u8-X17"}],"mis":"K2-1-u8-X17","explanation":["보고 난 뒤 감상을 나누는 것도 중요한 활동이에요.","좋았던 점을 말해 주면 친구가 기뻐해요.","인물의 마음이 잘 드러난 부분을 찾아 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#6','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'mc','auto','「해와 달이 된 오누이」 인형극에서 해설이 하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X04']::text[],false,'{"seq":6,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"「해와 달이 된 오누이」 인형극에서 해설이 하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「엄마를 기다리던 깊은 밤, 누군가 문을 두드려요.」","correct":true},{"t":"「얘들아, 엄마 왔다. 문 열어라.」","mis":"K2-1-u8-X04"},{"t":"「얼른 나무 위로 올라가자!」","mis":"K2-1-u8-X04"}],"explanation":["해설은 장면과 상황을 알려 주는 말을 해요.","「문 열어라.」는 호랑이의 대사예요.","「올라가자!」는 오빠의 대사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#7','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'mc','auto','인형극 공연 중에 한 친구가 대사를 잊어버렸어요. 보는 친구들이 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X17']::text[],false,'{"seq":7,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"인형극 공연 중에 한 친구가 대사를 잊어버렸어요. 보는 친구들이 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"조용히 기다려 주고 끝나면 응원해 줘요","correct":true},{"t":"큰 소리로 웃어요","mis":"K2-1-u8-X17"},{"t":"대신 대사를 크게 외쳐 줘요","mis":"K2-1-u8-X17"}],"explanation":["기다려 주면 친구가 마음을 가다듬을 수 있어요.","웃으면 친구가 더 당황해요.","대신 외치면 공연이 엉켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#8','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',4,'mc','auto','모둠 계획을 읽고 답해 보세요. 1모둠이 흥부네의 기쁜 마음을 가장 잘 살리는 계획은 어느 것인가요?',ARRAY['K2-1-u8-X12','K2-1-u8-X16']::text[],false,'{"seq":8,"concept":"K2-1-u8-C12","difficulty":4,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 1모둠이 흥부네의 기쁜 마음을 가장 잘 살리는 계획은 어느 것인가요?","options":[{"t":"쌀이 쏟아질 때 흥부는 깜짝 놀란 큰 목소리로 말하고, 아이들 인형은 깡충깡충 뛰게 움직여요","correct":true},{"t":"모두 작은 목소리로 천천히 말하고 인형은 가만히 둬요","mis":"K2-1-u8-X12"},{"t":"인형 꾸미기에 시간을 다 쓰고 대사는 공연 때 처음 읽어요","mis":"K2-1-u8-X16"}],"explanation":["목소리와 움직임이 함께 기쁜 마음을 살려요.","작고 느린 목소리와 멈춘 인형은 기쁜 장면과 맞지 않아요.","연습 없이 처음 읽으면 마음이 살지 않아요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#9','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',4,'essay','teacher','우리 모둠이 인형극을 한다면 어떤 작품의 어떤 장면을 보여 주고 싶은지, 내가 맡고 싶은 역할과 그 인물의 마음을 살리는 목소리·움직임을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C12","difficulty":4,"kind":"essay","stem":"우리 모둠이 인형극을 한다면 어떤 작품의 어떤 장면을 보여 주고 싶은지, 내가 맡고 싶은 역할과 그 인물의 마음을 살리는 목소리·움직임을 써 보세요.","answer_guide":{"answer":"예: 「의좋은 형제」에서 달밤에 형과 아우가 마주치는 장면을 보여 주고 싶어요. 저는 아우 역을 맡아 처음에는 깜짝 놀란 목소리로, 나중에는 눈물을 글썽이는 떨리는 목소리로 말하고 형 인형 쪽으로 천천히 다가가게 움직이겠어요.","scoring_points":["보여 줄 작품과 장면을 썼는가","맡고 싶은 역할을 썼는가","인물의 마음을 살리는 목소리·움직임을 썼는가"]},"explanation":["작품과 장면.","맡고 싶은 역할.","마음을 살리는 목소리·움직임."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#10','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',4,'essay','teacher','친구 모둠의 인형극을 보았다고 생각하고, 좋았던 점과 인물의 마음이 잘 드러난 부분을 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C12","difficulty":4,"kind":"essay","stem":"친구 모둠의 인형극을 보았다고 생각하고, 좋았던 점과 인물의 마음이 잘 드러난 부분을 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 3모둠의 「해와 달이 된 오누이」가 좋았어요. 호랑이가 굵고 느린 목소리로 「문 열어라.」라고 할 때 정말 무서웠어요. 누이가 떨리는 목소리로 말할 때 무서워하는 마음이 잘 느껴졌어요.","scoring_points":["좋았던 점을 썼는가","인물의 마음이 잘 드러난 부분을 썼는가","목소리·움직임 등 까닭을 들었는가"]},"explanation":["좋았던 점.","마음이 잘 드러난 부분.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#1','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C1',1,'mc','auto','소리 내어 낭송하며 말의 리듬을 즐기는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"소리 내어 낭송하며 말의 리듬을 즐기는 작품은 어느 것인가요?","options":[{"t":"시","correct":true},{"t":"인형극","mis":"K2-1-u8-X01"},{"t":"이야기","mis":"K2-1-u8-X01"}],"explanation":["시는 리듬을 살려 낭송하며 즐겨요.","다른 보기는 그 특징과 맞지 않는 작품이에요.","특징을 하나씩 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#2','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C2',1,'mc','auto','인물의 마음이 글에 쓰여 있지 않을 때 무엇을 보고 상상하면 좋을까요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"인물의 마음이 글에 쓰여 있지 않을 때 무엇을 보고 상상하면 좋을까요?","options":[{"t":"인물의 상황과 말·행동","correct":true},{"t":"인물이 입은 옷의 색깔","mis":"K2-1-u8-X06"},{"t":"책의 쪽수","mis":"K2-1-u8-X06"}],"explanation":["상황과 말·행동에 마음이 담겨 있어요.","다른 보기에는 인물의 마음이 드러나지 않아요.","「이 부분에 마음이 보이나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#3','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C4',1,'mc','auto','흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"흉내 내는 말은 어느 것인가요?","options":[{"t":"살금살금","correct":true},{"t":"동생","mis":"K2-1-u8-X07"},{"t":"이불","mis":"K2-1-u8-X07"}],"explanation":["「살금살금」은 소리나 모양을 흉내 낸 말이에요.","다른 두 낱말은 무엇을 가리키는 이름이에요.","몸짓으로 따라 할 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#4','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 보보에게 당근 김밥을 내민 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보에게 당근 김밥을 내민 인물은 누구인가요?","options":[{"t":"토토","correct":true},{"t":"다미","mis":"K2-1-u8-X04"},{"t":"엄마 곰","mis":"K2-1-u8-X03"}],"explanation":["토토가 「우리 같이 먹자!」라며 김밥을 내밀었어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#5','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C7',1,'mc','auto','빛을 비추어 생긴 그림자로 보여 주는 인형극은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"빛을 비추어 생긴 그림자로 보여 주는 인형극은 어느 것인가요?","options":[{"t":"그림자 인형극","correct":true},{"t":"손가락 인형극","mis":"K2-1-u8-X11"},{"t":"막대 인형극","mis":"K2-1-u8-X11"}],"explanation":["빛과 그림자로 보여 주는 것이 그림자 인형극이에요.","다른 보기는 그 특징과 맞지 않아요.","인형을 무엇으로 움직이는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#6','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C11',1,'mc','auto','감상을 발표할 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"감상을 발표할 때 바른 자세는 어느 것인가요?","options":[{"t":"또박또박 말하고 까닭도 함께 말해요","correct":true},{"t":"작은 목소리로 웅얼거려요","mis":"K2-1-u8-X15"},{"t":"바닥만 보며 빨리 끝내요","mis":"K2-1-u8-X15"}],"explanation":["또박또박 까닭과 함께 말하면 잘 전해져요.","다른 보기는 바르지 않은 자세예요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#7','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C13',1,'mc','auto','「구름이」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":7,"concept":"K2-1-u8-C13","difficulty":1,"kind":"mc","stem":"「구름이」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?","options":[{"t":"[구르미]","correct":true},{"t":"[구름이]","mis":"K2-1-u8-X18"},{"t":"[구르니]","mis":"K2-1-u8-X18"}],"explanation":["받침 뒤에 「ㅇ」으로 시작하는 글자가 와서 받침이 뒤로 넘어가 [구르미]로 소리 나요.","글자 그대로 읽으면 자연스럽지 않아요.","받침 뒤 글자가 「ㅇ」인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#8','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C3',1,'ox','auto','시를 낭송할 때는 시의 리듬과 느낌을 살려 읽어요.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"시를 낭송할 때는 시의 리듬과 느낌을 살려 읽어요.","answer":"O","reason_options":[{"t":"리듬과 느낌을 살리면 시가 생생하게 느껴지니까","correct":true},{"t":"시는 언제나 크고 빠르게만 읽어야 하니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["리듬과 느낌을 살려 낭송해요.","시마다 어울리는 낭송 방법이 달라요.","시 분위기를 먼저 정하고 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#9','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「나도 두 팔을 번쩍 들어」에 담긴 「나」의 마음은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「나도 두 팔을 번쩍 들어」에 담긴 「나」의 마음은 무엇인가요?","options":[{"t":"무척 반가운 마음","correct":true},{"t":"짝꿍이 미운 마음","mis":"K2-1-u8-X05"},{"t":"학교에 가기 싫은 마음","mis":"K2-1-u8-X06"}],"explanation":["팔을 번쩍 드는 행동에 반가움이 담겨 있어요.","다른 보기는 행동과 맞지 않거나 마음이 드러나지 않는 것이에요.","행동 속에 담긴 마음을 찾아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#10','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 보보의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시무룩하다 → 고맙고 기쁘다","correct":true},{"t":"고맙고 기쁘다 → 시무룩하다","mis":"K2-1-u8-X09"},{"t":"처음부터 끝까지 기쁘다","mis":"K2-1-u8-X09"}],"explanation":["빈 도시락에 시무룩했다가 친구들 덕분에 기뻐졌어요.","다른 보기는 마음이 바뀐 차례가 맞지 않아요.","처음·가운데·끝 마음을 따로 적어 봐요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#11','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C6',2,'error','auto','기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],false,'{"seq":11,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"지후 — 「나는 보보가 활짝 웃는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"아린 — 「다미가 빵을 나누는 장면이 기억에 남아. 자기 것을 반으로 나눠 준 게 따뜻했거든.」","mis":"K2-1-u8-X19"},{"t":"태민 — 「빈 도시락 장면이 기억에 남아. 내가 보보였으면 울었을 것 같아서.」","mis":"K2-1-u8-X19"}],"explanation":["장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","다른 두 친구는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#12','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C7',2,'match','auto','인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"작고 떨리는 목소리","r":"무섭다"},{"l":"크고 빠른 목소리","r":"신난다"},{"l":"느리고 힘없는 목소리","r":"슬프다"}],"mis":"K2-1-u8-X12","explanation":["목소리의 크기와 빠르기에 마음이 묻어나요.","같은 말도 목소리에 따라 다르게 들려요.","그 목소리로 직접 말해 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#13','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C8',2,'mc','auto','줄거리를 읽고 답해 보세요. 장소가 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":13,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 장소가 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"집 → 고개 → 집 → 나무 위 → 하늘","correct":true},{"t":"고개 → 나무 위 → 집 → 하늘","mis":"K2-1-u8-X13"},{"t":"집 → 나무 위 → 고개 → 하늘","mis":"K2-1-u8-X13"}],"explanation":["엄마가 집을 나서 고개에서 호랑이를 만나고, 호랑이가 집에 온 뒤 오누이는 나무 위를 거쳐 하늘로 갔어요.","다른 보기는 차례가 뒤섞였어요.","장소나 일이 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#14','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C13',2,'mc','auto','받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"눈이 → [누니]","correct":true},{"t":"눈이 → [눈이]","mis":"K2-1-u8-X18"},{"t":"눈이 → [누이]","mis":"K2-1-u8-X18"}],"explanation":["받침 ㄴ이 뒤 글자로 넘어가 [누니]로 소리 나요.","다른 보기는 받침을 넘기지 않았거나 넘기지 않아야 할 곳에서 넘겼어요.","받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#15','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 이 편지를 받는 인물은 누구인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":15,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 이 편지를 받는 인물은 누구인가요?","options":[{"t":"형","correct":true},{"t":"하준","mis":"K2-1-u8-X14"},{"t":"아우","mis":"K2-1-u8-X14"}],"explanation":["「형님께」라고 썼으니 받는 인물은 형이에요.","다른 보기는 편지의 다른 부분이에요.","누구에게 · 하고 싶은 말 · 왜 · 누가를 나눠 짚어요."],"asset":{"type":"passage","lines":["형님께","형님, 아우를 위해 밤마다 무거운 볏단을 몰래 옮기신 장면을 보고 마음이 따뜻해졌어요.","저도 동생이 있는데 장난감을 잘 빌려주지 않았거든요.","이제는 형님처럼 동생을 먼저 생각해 볼게요.","— 2학년 하준 올림"],"title":"하준이가 형에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#16','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C12',2,'error','auto','인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?',ARRAY['K2-1-u8-X17','K2-1-u8-X19']::text[],false,'{"seq":16,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?","options":[{"t":"하람 — 공연 중에 「저거 틀렸다!」 하고 크게 외쳤어요","correct":true,"mis_target":"K2-1-u8-X17"},{"t":"윤서 — 자리에 앉아 조용히 끝까지 보았어요","mis":"K2-1-u8-X19"},{"t":"민호 — 끝나자 박수를 치고 좋았던 점을 말했어요","mis":"K2-1-u8-X19"}],"explanation":["공연 중에 외치면 공연하는 친구가 당황해요.","다른 두 친구는 약속을 바르게 지켰어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#17','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 볏단이 하나도 줄지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],false,'{"seq":17,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 볏단이 하나도 줄지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"형이 옮긴 만큼 아우도 형에게 옮겼기 때문에","correct":true},{"t":"이웃이 볏단을 가져다 놓았기 때문에","mis":"K2-1-u8-X03"},{"t":"형이 아우의 볏단을 빼앗았기 때문에","mis":"K2-1-u8-X05"}],"explanation":["서로에게 옮겨서 볏단 수가 그대로였어요.","다른 보기는 대본에 없거나 인물의 마음과 맞지 않아요.","대본에서 인물의 말과 행동을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#18','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C2',3,'error','auto','글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?',ARRAY['K2-1-u8-X06','K2-1-u8-X19']::text[],false,'{"seq":18,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?","options":[{"t":"채원 — 「흥부는 기뻤을 거야. 박이 지붕 위에 열렸으니까.」","correct":true,"mis_target":"K2-1-u8-X06"},{"t":"하준 — 「흥부는 놀랐을 거야. 눈이 휘둥그레졌으니까.」","mis":"K2-1-u8-X19"},{"t":"지우 — 「아이들은 신났을 거야. 덩실덩실 춤을 추었으니까.」","mis":"K2-1-u8-X19"}],"explanation":["박이 열린 것만으로는 흥부의 마음이 드러나지 않아요.","다른 두 친구는 말·행동·상황을 알맞게 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#19','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C11',3,'ox','auto','친구의 감상이 나와 다르면 비슷한 점과 다른 점을 견주며 들어요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":19,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"친구의 감상이 나와 다르면 비슷한 점과 다른 점을 견주며 들어요.","answer":"O","reason_options":[{"t":"견주어 들으면 작품을 더 넓게 감상할 수 있으니까","correct":true},{"t":"나와 다른 감상은 들을 필요가 없으니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["견주어 들으면 감상이 넓어져요.","나와 다른 감상도 존중하며 들어요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#20','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C13',3,'ox','auto','「구름이」는 받침 ㅁ이 뒤로 넘어가 [구르미]로 소리 나요.',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":20,"concept":"K2-1-u8-C13","difficulty":3,"kind":"ox","stem":"「구름이」는 받침 ㅁ이 뒤로 넘어가 [구르미]로 소리 나요.","answer":"O","reason_options":[{"t":"받침 뒤에 「ㅇ」으로 시작하는 글자 「이」가 왔으니까","correct":true},{"t":"받침은 언제나 글자 그대로 읽어야 하니까","mis":"K2-1-u8-X18"}],"mis":"K2-1-u8-X18","explanation":["「이」 앞에서 받침이 넘어가요.","받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가요.","받침 뒤 글자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#21','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":21,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"작고 부드러운 목소리로 천천히 읽기","correct":true},{"t":"크고 씩씩한 목소리로 빠르게 읽기","mis":"K2-1-u8-X08"},{"t":"화난 목소리로 또박또박 끊어 읽기","mis":"K2-1-u8-X08"}],"explanation":["동생이 잠든 고요한 밤이라 작고 부드럽게 읽어요.","다른 보기는 시의 분위기와 맞지 않거나 낭송 방법을 헷갈렸어요.","시 분위기를 먼저 정하고 목소리를 골라요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#22','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C12',3,'mc','auto','막대 인형을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X16']::text[],false,'{"seq":22,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"막대 인형을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인물 그리기 → 오리기 → 막대 붙이기 → 움직여 보기","correct":true},{"t":"막대 붙이기 → 인물 그리기 → 오리기 → 움직여 보기","mis":"K2-1-u8-X16"},{"t":"오리기 → 움직여 보기 → 인물 그리기 → 막대 붙이기","mis":"K2-1-u8-X16"}],"explanation":["그리고 오린 뒤 막대를 붙여 움직여 봐요.","다른 보기는 인형극을 준비하거나 공연하는 바른 방법이 아니에요.","「인형보다 놀이!」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#23','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C6',4,'essay','teacher','「보보의 빈 도시락」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"「보보의 빈 도시락」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 다미가 도토리 빵을 반으로 나누어 주는 장면이 가장 기억에 남아요. 자기 것도 아끼지 않고 나눠 준 마음이 따뜻했기 때문이에요. 저도 짝이 우유를 쏟았을 때 제 휴지를 나눠 준 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#24','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 누이의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 누이의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 누이는 무척 무서웠을 거예요. 떨리는 목소리로 말했고, 문을 열기 전에 손을 먼저 보여 달라고 할 만큼 의심스러웠기 때문이에요.","scoring_points":["인물의 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#25','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C10',4,'essay','teacher','「의좋은 형제」의 형에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「의좋은 형제」의 형에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 형님께 — 형님, 식구가 많아 힘드실 텐데 아우를 먼저 생각하신 마음이 멋져요. 저는 동생에게 양보를 잘 못 했는데 형님처럼 해 볼게요. — 2학년 지우 올림","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#1','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C1',1,'mc','auto','인형이 나와 말과 움직임으로 이야기를 보여 주는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"인형이 나와 말과 움직임으로 이야기를 보여 주는 작품은 어느 것인가요?","options":[{"t":"인형극","correct":true},{"t":"시","mis":"K2-1-u8-X01"},{"t":"일기","mis":"K2-1-u8-X01"}],"explanation":["인형이 나와 보여 주는 것이 인형극이에요.","다른 보기는 그 특징과 맞지 않는 작품이에요.","특징을 하나씩 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#2','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C2',1,'mc','auto','「콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.」에서 콩쥐의 마음을 짐작하게 하는 것은 무엇인가요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"「콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.」에서 콩쥐의 마음을 짐작하게 하는 것은 무엇인가요?","options":[{"t":"주저앉아 우는 행동","correct":true},{"t":"독이라는 물건 이름","mis":"K2-1-u8-X06"},{"t":"글자의 수","mis":"K2-1-u8-X06"}],"explanation":["주저앉아 우는 행동에서 속상한 마음이 보여요.","다른 보기에는 인물의 마음이 드러나지 않아요.","「이 부분에 마음이 보이나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#3','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C4',1,'mc','auto','흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"흉내 내는 말은 어느 것인가요?","options":[{"t":"흔들흔들","correct":true},{"t":"짝꿍","mis":"K2-1-u8-X07"},{"t":"학교","mis":"K2-1-u8-X07"}],"explanation":["「흔들흔들」은 소리나 모양을 흉내 낸 말이에요.","다른 두 낱말은 무엇을 가리키는 이름이에요.","몸짓으로 따라 할 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#4','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 연이에게 「같이 접어 보자.」라고 한 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 연이에게 「같이 접어 보자.」라고 한 인물은 누구인가요?","options":[{"t":"오빠","correct":true},{"t":"연이","mis":"K2-1-u8-X04"},{"t":"아빠","mis":"K2-1-u8-X03"}],"explanation":["오빠가 빙그레 웃으며 그렇게 말했어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#5','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C7',1,'mc','auto','손가락에 인형을 끼워 움직이는 인형극은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"손가락에 인형을 끼워 움직이는 인형극은 어느 것인가요?","options":[{"t":"손가락 인형극","correct":true},{"t":"그림자 인형극","mis":"K2-1-u8-X11"},{"t":"막대 인형극","mis":"K2-1-u8-X11"}],"explanation":["손가락에 끼우는 것이 손가락 인형극이에요.","다른 보기는 그 특징과 맞지 않아요.","인형을 무엇으로 움직이는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#6','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C11',1,'mc','auto','친구의 감상을 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"친구의 감상을 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"좋은 점을 찾으며 끝까지 들어요","correct":true},{"t":"나와 다르면 틀렸다고 말해요","mis":"K2-1-u8-X15"},{"t":"짝과 다른 이야기를 해요","mis":"K2-1-u8-X15"}],"explanation":["끝까지 좋은 점을 찾으며 들어요.","다른 보기는 바르지 않은 자세예요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#7','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C13',1,'mc','auto','「책이」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":7,"concept":"K2-1-u8-C13","difficulty":1,"kind":"mc","stem":"「책이」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?","options":[{"t":"[채기]","correct":true},{"t":"[책이]","mis":"K2-1-u8-X18"},{"t":"[채이]","mis":"K2-1-u8-X18"}],"explanation":["받침 뒤에 「ㅇ」으로 시작하는 글자가 와서 받침이 뒤로 넘어가 [채기]로 소리 나요.","글자 그대로 읽으면 자연스럽지 않아요.","받침 뒤 글자가 「ㅇ」인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#8','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C3',1,'ox','auto','시는 한 가지 방법으로만 낭송해야 해요.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"시는 한 가지 방법으로만 낭송해야 해요.","answer":"X","reason_options":[{"t":"주고받기·몸짓·박자 넣기처럼 여러 방법으로 낭송할 수 있으니까","correct":true},{"t":"다른 방법으로 읽으면 시가 틀리게 되니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["여러 방법으로 낭송할 수 있어요.","시마다 어울리는 낭송 방법이 달라요.","시 분위기를 먼저 정하고 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#9','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「이불을 살며시 덮어 준다」에 담긴 「나」의 마음은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「이불을 살며시 덮어 준다」에 담긴 「나」의 마음은 무엇인가요?","options":[{"t":"동생을 아끼는 마음","correct":true},{"t":"동생을 깨우고 싶은 마음","mis":"K2-1-u8-X05"},{"t":"이불이 무거운 마음","mis":"K2-1-u8-X06"}],"explanation":["살며시 덮어 주는 행동에 아끼는 마음이 담겨 있어요.","다른 보기는 행동과 맞지 않거나 마음이 드러나지 않는 것이에요.","행동 속에 담긴 마음을 찾아요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#10','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 연이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 연이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"설렌다 → 속상하다 → 기쁘다","correct":true},{"t":"기쁘다 → 설렌다 → 속상하다","mis":"K2-1-u8-X09"},{"t":"속상하다 → 속상하다 → 속상하다","mis":"K2-1-u8-X09"}],"explanation":["배를 띄울 때 설렜고 뒤집히자 속상했고 새 배가 떠가자 기뻤어요.","다른 보기는 마음이 바뀐 차례가 맞지 않아요.","처음·가운데·끝 마음을 따로 적어 봐요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#11','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C6',2,'error','auto','기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],false,'{"seq":11,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"수빈 — 「나는 종이배가 뒤집히는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"현우 — 「오빠가 같이 접자고 하는 장면이 기억에 남아. 다정한 오빠가 부러웠거든.」","mis":"K2-1-u8-X19"},{"t":"다은 — 「새 배가 떠가는 장면이 기억에 남아. 다시 해서 해낸 게 멋졌거든.」","mis":"K2-1-u8-X19"}],"explanation":["장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","다른 두 친구는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#12','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C7',2,'match','auto','인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"속삭이는 작은 목소리","r":"들킬까 봐 조심스럽다"},{"l":"깜짝 놀라 커다란 목소리","r":"놀랍다"},{"l":"노래하듯 흥겨운 목소리","r":"즐겁다"}],"mis":"K2-1-u8-X12","explanation":["목소리의 크기와 빠르기에 마음이 묻어나요.","같은 말도 목소리에 따라 다르게 들려요.","그 목소리로 직접 말해 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#13','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C8',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":13,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"박이 열린다 → 박을 탄다 → 쌀이 쏟아진다","correct":true},{"t":"쌀이 쏟아진다 → 박이 열린다 → 박을 탄다","mis":"K2-1-u8-X13"},{"t":"박을 탄다 → 박이 열린다 → 쌀이 쏟아진다","mis":"K2-1-u8-X13"}],"explanation":["박이 열리고, 박을 타자, 쌀이 쏟아졌어요.","다른 보기는 차례가 뒤섞였어요.","장소나 일이 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#14','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C13',2,'mc','auto','받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"집에 → [지베]","correct":true},{"t":"집에 → [집에]","mis":"K2-1-u8-X18"},{"t":"집에 → [지에]","mis":"K2-1-u8-X18"}],"explanation":["받침 ㅂ이 뒤 글자로 넘어가 [지베]로 소리 나요.","다른 보기는 받침을 넘기지 않았거나 넘기지 않아야 할 곳에서 넘겼어요.","받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#15','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 이 편지를 쓴 사람은 누구인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":15,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 이 편지를 쓴 사람은 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"보보","mis":"K2-1-u8-X14"},{"t":"토토","mis":"K2-1-u8-X14"}],"explanation":["끝에 「서윤이가」라고 썼어요.","다른 보기는 편지의 다른 부분이에요.","누구에게 · 하고 싶은 말 · 왜 · 누가를 나눠 짚어요."],"asset":{"type":"passage","lines":["보보에게","보보야, 도시락이 텅 비어 있을 때 많이 속상했지?","토토와 다미가 음식을 나눠 줄 때 나도 덩달아 기뻤어.","다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라.","— 서윤이가"],"title":"서윤이가 보보에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#16','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C12',2,'error','auto','인형극을 발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X19']::text[],false,'{"seq":16,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"인형극을 발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?","options":[{"t":"태민 — 관객에게 등을 돌리고 대사를 웅얼거렸어요","correct":true,"mis_target":"K2-1-u8-X16"},{"t":"채원 — 또박또박 천천히 대사를 말했어요","mis":"K2-1-u8-X19"},{"t":"지호 — 인물의 마음에 맞게 인형을 움직였어요","mis":"K2-1-u8-X19"}],"explanation":["등을 돌리고 웅얼거리면 관객이 들을 수 없어요.","다른 두 친구는 약속을 바르게 지켰어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#17','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 형이 볏단을 내려놓고 아우를 꼭 안은 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],false,'{"seq":17,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 형이 볏단을 내려놓고 아우를 꼭 안은 까닭은 무엇인가요?","options":[{"t":"아우도 자기를 생각해 주었다는 것을 알게 되어서","correct":true},{"t":"볏단을 대신 들어 달라고 하려고","mis":"K2-1-u8-X03"},{"t":"아우가 볏단을 훔쳐 가서 붙잡으려고","mis":"K2-1-u8-X05"}],"explanation":["형은 「네가 나를 생각해 주었구나.」라고 했어요.","다른 보기는 대본에 없거나 인물의 마음과 맞지 않아요.","대본에서 인물의 말과 행동을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#18','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C2',3,'error','auto','글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 잘못 상상한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],false,'{"seq":18,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 잘못 상상한 친구는 누구인가요?","options":[{"t":"하린 — 「물이 줄줄 새어 나갈 때 콩쥐는 신이 났을 거야.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"지안 — 「콩쥐는 막막했을 거야. 주저앉아 울었으니까.」","mis":"K2-1-u8-X19"},{"t":"윤호 — 「콩쥐는 고마웠을 거야. 두꺼비를 꼭 끌어안았으니까.」","mis":"K2-1-u8-X19"}],"explanation":["물이 새는데 신이 났을 리 없어요.","다른 두 친구는 말·행동·상황을 알맞게 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#19','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C11',3,'ox','auto','친구가 나와 다른 장면을 골랐다면 친구의 감상이 틀린 거예요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":19,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"친구가 나와 다른 장면을 골랐다면 친구의 감상이 틀린 거예요.","answer":"X","reason_options":[{"t":"저마다 겪은 일과 느낌이 달라 다른 장면을 고를 수 있으니까","correct":true},{"t":"기억에 남는 장면은 모두 같아야 하니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["다른 장면을 고른 것은 틀린 것이 아니에요.","나와 다른 감상도 존중하며 들어요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#20','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C13',3,'ox','auto','받침 뒤에 어떤 글자가 와도 받침은 늘 뒤로 넘어가 소리 나요.',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":20,"concept":"K2-1-u8-C13","difficulty":3,"kind":"ox","stem":"받침 뒤에 어떤 글자가 와도 받침은 늘 뒤로 넘어가 소리 나요.","answer":"X","reason_options":[{"t":"받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가니까","correct":true},{"t":"받침은 뒤에 무슨 글자가 오든 넘어가니까","mis":"K2-1-u8-X18"}],"mis":"K2-1-u8-X18","explanation":["「ㅇ」 앞에서만 넘어가요.","받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가요.","받침 뒤 글자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#21','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":21,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"「흔들흔들」에서 손을 흔들며 밝은 목소리로 읽기","correct":true},{"t":"졸린 목소리로 작게 웅얼거리기","mis":"K2-1-u8-X08"},{"t":"고개를 숙인 채 아주 빠르게 읽기","mis":"K2-1-u8-X08"}],"explanation":["반가운 시라 밝은 목소리와 손 흔들기가 어울려요.","다른 보기는 시의 분위기와 맞지 않거나 낭송 방법을 헷갈렸어요.","시 분위기를 먼저 정하고 목소리를 골라요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#22','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C12',3,'mc','auto','인형극을 할 때 한 편을 다 보여 주기보다 한 장면을 충실히 보여 주면 좋은 까닭은 무엇인가요?',ARRAY['K2-1-u8-X17','K2-1-u8-X16']::text[],false,'{"seq":22,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"인형극을 할 때 한 편을 다 보여 주기보다 한 장면을 충실히 보여 주면 좋은 까닭은 무엇인가요?","options":[{"t":"짧은 장면이라도 인물의 마음을 살려 실감 나게 보여 줄 수 있어서","correct":true},{"t":"관객이 보지 않아도 되어서","mis":"K2-1-u8-X17"},{"t":"연습을 하지 않아도 되어서","mis":"K2-1-u8-X16"}],"explanation":["한 장면에 집중하면 목소리와 움직임을 더 살릴 수 있어요.","다른 보기는 인형극을 준비하거나 공연하는 바른 방법이 아니에요.","「인형보다 놀이!」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#23','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C6',4,'essay','teacher','「연이의 종이배」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"「연이의 종이배」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 새 종이배가 돌 옆을 쓱 비켜 떠가는 장면이 가장 기억에 남아요. 실패해도 다시 해서 해낸 모습이 멋졌기 때문이에요. 저도 퍼즐을 여러 번 망쳤다가 끝내 완성해서 기뻤던 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#24','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 오빠의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 오빠의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 오빠는 무섭지만 동생을 지키고 싶었을 거예요. 작은 목소리로 속삭였고, 누이 손을 꼭 잡고 뒷문으로 살금살금 나갔기 때문이에요.","scoring_points":["인물의 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#25','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C10',4,'essay','teacher','「보보의 빈 도시락」의 토토에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「보보의 빈 도시락」의 토토에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 토토에게 — 토토야, 혼자 있던 보보에게 먼저 다가가 줘서 정말 멋졌어. 나도 쉬는 시간에 혼자 있는 친구에게 먼저 같이 놀자고 할게. — 하윤이가","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#1','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C1',1,'mc','auto','인물이 겪은 일을 차례대로 들려주는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"인물이 겪은 일을 차례대로 들려주는 작품은 어느 것인가요?","options":[{"t":"이야기","correct":true},{"t":"시","mis":"K2-1-u8-X01"},{"t":"인형극","mis":"K2-1-u8-X01"}],"explanation":["이야기에는 인물과 일어난 일이 차례대로 나와요.","다른 보기는 그 특징과 맞지 않는 작품이에요.","특징을 하나씩 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#2','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C2',1,'mc','auto','「흥부는 눈이 휘둥그레져 입을 다물지 못했어요.」에서 흥부의 마음을 짐작하게 하는 것은 무엇인가요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"「흥부는 눈이 휘둥그레져 입을 다물지 못했어요.」에서 흥부의 마음을 짐작하게 하는 것은 무엇인가요?","options":[{"t":"눈이 휘둥그레진 행동","correct":true},{"t":"흥부라는 이름","mis":"K2-1-u8-X06"},{"t":"문장의 길이","mis":"K2-1-u8-X06"}],"explanation":["휘둥그레진 눈에서 놀란 마음이 보여요.","다른 보기에는 인물의 마음이 드러나지 않아요.","「이 부분에 마음이 보이나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#3','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C4',1,'mc','auto','흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"흉내 내는 말은 어느 것인가요?","options":[{"t":"깡충깡충","correct":true},{"t":"토끼","mis":"K2-1-u8-X07"},{"t":"김밥","mis":"K2-1-u8-X07"}],"explanation":["「깡충깡충」은 소리나 모양을 흉내 낸 말이에요.","다른 두 낱말은 무엇을 가리키는 이름이에요.","몸짓으로 따라 할 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#4','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 도토리 빵을 반으로 나누어 준 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 도토리 빵을 반으로 나누어 준 인물은 누구인가요?","options":[{"t":"다미","correct":true},{"t":"토토","mis":"K2-1-u8-X04"},{"t":"보보","mis":"K2-1-u8-X03"}],"explanation":["다람쥐 다미가 빵을 나누어 주었어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#5','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C7',1,'mc','auto','막대에 붙인 인형을 잡고 움직이는 인형극은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"막대에 붙인 인형을 잡고 움직이는 인형극은 어느 것인가요?","options":[{"t":"막대 인형극","correct":true},{"t":"그림자 인형극","mis":"K2-1-u8-X11"},{"t":"손가락 인형극","mis":"K2-1-u8-X11"}],"explanation":["막대로 움직이는 것이 막대 인형극이에요.","다른 보기는 그 특징과 맞지 않아요.","인형을 무엇으로 움직이는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#6','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C11',1,'mc','auto','감상을 발표할 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"감상을 발표할 때 바른 자세는 어느 것인가요?","options":[{"t":"친구들을 바라보며 알맞은 목소리로 말해요","correct":true},{"t":"친구들에게 등을 돌리고 말해요","mis":"K2-1-u8-X15"},{"t":"종이로 얼굴을 가리고 말해요","mis":"K2-1-u8-X15"}],"explanation":["친구들을 바라보면 마음이 잘 전해져요.","다른 보기는 바르지 않은 자세예요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#7','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C13',1,'mc','auto','「손에」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":7,"concept":"K2-1-u8-C13","difficulty":1,"kind":"mc","stem":"「손에」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?","options":[{"t":"[소네]","correct":true},{"t":"[손에]","mis":"K2-1-u8-X18"},{"t":"[소에]","mis":"K2-1-u8-X18"}],"explanation":["받침 뒤에 「ㅇ」으로 시작하는 글자가 와서 받침이 뒤로 넘어가 [소네]로 소리 나요.","글자 그대로 읽으면 자연스럽지 않아요.","받침 뒤 글자가 「ㅇ」인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#8','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C3',1,'ox','auto','조용한 밤을 그린 시는 큰 소리로 외치듯 읽어야 어울려요.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"조용한 밤을 그린 시는 큰 소리로 외치듯 읽어야 어울려요.","answer":"X","reason_options":[{"t":"조용한 시는 작고 부드러운 목소리가 어울리니까","correct":true},{"t":"시는 무조건 크게 읽어야 잘 들리니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["시의 분위기에 맞는 목소리로 읽어요.","시마다 어울리는 낭송 방법이 달라요.","시 분위기를 먼저 정하고 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#9','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「우리 둘은 벌써 웃는다」에서 알 수 있는 두 사람의 마음은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「우리 둘은 벌써 웃는다」에서 알 수 있는 두 사람의 마음은 무엇인가요?","options":[{"t":"서로 반갑고 즐거운 마음","correct":true},{"t":"서로 화가 난 마음","mis":"K2-1-u8-X05"},{"t":"학교 앞이 낯선 마음","mis":"K2-1-u8-X06"}],"explanation":["말없이 웃는 모습에 반가운 마음이 보여요.","다른 보기는 행동과 맞지 않거나 마음이 드러나지 않는 것이에요.","행동 속에 담긴 마음을 찾아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#10','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 보보의 마음이 바뀌게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보의 마음이 바뀌게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"토토와 다미가 음식을 나누어 주어서","correct":true},{"t":"도시락이 텅 비어 있어서","mis":"K2-1-u8-X09"},{"t":"소풍이 일찍 끝나서","mis":"K2-1-u8-X09"}],"explanation":["친구들이 음식을 나눠 주어 시무룩하던 마음이 기뻐졌어요.","다른 보기는 마음이 바뀐 차례가 맞지 않아요.","처음·가운데·끝 마음을 따로 적어 봐요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#11','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C6',2,'error','auto','기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],false,'{"seq":11,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"예린 — 「나는 형과 아우가 마주치는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"하준 — 「볏단이 줄지 않는 장면이 기억에 남아. 왜 그런지 궁금해서 두근두근했거든.」","mis":"K2-1-u8-X19"},{"t":"소율 — 「형이 아우를 안는 장면이 기억에 남아. 내 마음까지 따뜻해졌거든.」","mis":"K2-1-u8-X19"}],"explanation":["장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","다른 두 친구는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#12','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C7',2,'match','auto','인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"굵고 느린 목소리","r":"무섭고 위협적이다"},{"l":"울먹이는 목소리","r":"서럽다"},{"l":"들뜬 큰 목소리","r":"기쁘다"}],"mis":"K2-1-u8-X12","explanation":["목소리의 크기와 빠르기에 마음이 묻어나요.","같은 말도 목소리에 따라 다르게 들려요.","그 목소리로 직접 말해 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#13','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C8',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":13,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"형이 볏단을 옮긴다 → 아우도 볏단을 옮긴다 → 다음 날 볏단이 줄지 않아 놀란다","correct":true},{"t":"다음 날 볏단이 줄지 않아 놀란다 → 형이 볏단을 옮긴다 → 아우도 볏단을 옮긴다","mis":"K2-1-u8-X13"},{"t":"아우가 볏단을 옮긴다 → 다음 날 볏단이 줄지 않아 놀란다 → 형이 볏단을 옮긴다","mis":"K2-1-u8-X13"}],"explanation":["두 사람이 밤에 옮긴 뒤 다음 날 아침 놀랐어요.","다른 보기는 차례가 뒤섞였어요.","장소나 일이 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#14','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C13',2,'mc','auto','받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"옷을 → [오슬]","correct":true},{"t":"옷을 → [옷을]","mis":"K2-1-u8-X18"},{"t":"옷을 → [오을]","mis":"K2-1-u8-X18"}],"explanation":["받침 ㅅ이 뒤 글자로 넘어가 [오슬]로 소리 나요.","다른 보기는 받침을 넘기지 않았거나 넘기지 않아야 할 곳에서 넘겼어요.","받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#15','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 하준이가 형에게 하고 싶은 말을 한 까닭으로 든 것은 무엇인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":15,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 하준이가 형에게 하고 싶은 말을 한 까닭으로 든 것은 무엇인가요?","options":[{"t":"동생에게 장난감을 잘 빌려주지 않았던 일","correct":true},{"t":"형님이 볏단을 빼앗은 일","mis":"K2-1-u8-X14"},{"t":"아우가 편지를 보낸 일","mis":"K2-1-u8-X14"}],"explanation":["하준이는 자기 경험을 까닭으로 들었어요.","다른 보기는 편지의 다른 부분이에요.","누구에게 · 하고 싶은 말 · 왜 · 누가를 나눠 짚어요."],"asset":{"type":"passage","lines":["형님께","형님, 아우를 위해 밤마다 무거운 볏단을 몰래 옮기신 장면을 보고 마음이 따뜻해졌어요.","저도 동생이 있는데 장난감을 잘 빌려주지 않았거든요.","이제는 형님처럼 동생을 먼저 생각해 볼게요.","— 2학년 하준 올림"],"title":"하준이가 형에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#16','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C12',2,'error','auto','인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?',ARRAY['K2-1-u8-X17','K2-1-u8-X19']::text[],false,'{"seq":16,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?","options":[{"t":"도담 — 공연 중에 무대 앞으로 나가 인형을 만졌어요","correct":true,"mis_target":"K2-1-u8-X17"},{"t":"다은 — 대사를 잊은 친구를 조용히 기다려 주었어요","mis":"K2-1-u8-X19"},{"t":"하늘 — 인물의 마음이 잘 드러난 부분을 기억해 두었어요","mis":"K2-1-u8-X19"}],"explanation":["무대 앞으로 나가면 공연이 멈춰요.","다른 두 친구는 약속을 바르게 지켰어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#17','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 형과 아우가 볏단을 「몰래」 옮긴 까닭으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],false,'{"seq":17,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 형과 아우가 볏단을 「몰래」 옮긴 까닭으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"미리 말하면 상대가 사양하고 받지 않을 것 같아서","correct":true},{"t":"볏단 옮기는 일이 부끄러워서","mis":"K2-1-u8-X03"},{"t":"상대를 놀라게 해 골탕 먹이려고","mis":"K2-1-u8-X05"}],"explanation":["상대를 위하는 마음을 부담 없이 전하려고 몰래 옮겼을 거예요.","다른 보기는 대본에 없거나 인물의 마음과 맞지 않아요.","대본에서 인물의 말과 행동을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#18','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C2',3,'error','auto','글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?',ARRAY['K2-1-u8-X06','K2-1-u8-X19']::text[],false,'{"seq":18,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?","options":[{"t":"민호 — 「콩쥐는 속상했을 거야. 독이 커다랬으니까.」","correct":true,"mis_target":"K2-1-u8-X06"},{"t":"서아 — 「콩쥐는 속상했을 거야. 훌쩍훌쩍 울었으니까.」","mis":"K2-1-u8-X19"},{"t":"도윤 — 「콩쥐는 안심했을 거야. 물이 찰랑찰랑 차올랐으니까.」","mis":"K2-1-u8-X19"}],"explanation":["독이 큰 것은 콩쥐의 마음이 드러나는 부분이 아니에요.","다른 두 친구는 말·행동·상황을 알맞게 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#19','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C11',3,'ox','auto','친구의 감상 발표를 들을 때는 좋은 점을 찾으며 끝까지 들어요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":19,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"친구의 감상 발표를 들을 때는 좋은 점을 찾으며 끝까지 들어요.","answer":"O","reason_options":[{"t":"좋은 점을 찾으면 친구의 생각을 배우고 친구도 힘이 나니까","correct":true},{"t":"듣는 동안 내가 할 말만 생각하면 되니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["끝까지 좋은 점을 찾으며 들어요.","나와 다른 감상도 존중하며 들어요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#20','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C13',3,'ox','auto','「꽃이」를 소리 나는 대로 쓰면 [꼬치]예요.',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":20,"concept":"K2-1-u8-C13","difficulty":3,"kind":"ox","stem":"「꽃이」를 소리 나는 대로 쓰면 [꼬치]예요.","answer":"O","reason_options":[{"t":"받침 ㅊ이 뒤 글자 「이」로 넘어가 소리 나니까","correct":true},{"t":"받침 ㅊ은 넘어가지 않고 사라지니까","mis":"K2-1-u8-X18"}],"mis":"K2-1-u8-X18","explanation":["받침 ㅊ도 「ㅇ」 앞에서 넘어가요.","받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가요.","받침 뒤 글자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#21','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 친구와 「주고받기」로 낭송하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":21,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 친구와 「주고받기」로 낭송하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"짝꿍 역은 1·2행, 나 역은 3·4행, 마지막 두 행은 함께 읽기","correct":true},{"t":"한 사람이 처음부터 끝까지 혼자 읽기","mis":"K2-1-u8-X08"},{"t":"두 사람이 같은 행을 겹쳐 읽기","mis":"K2-1-u8-X08"}],"explanation":["주고받으며 읽으면 손 인사를 주고받는 느낌이 살아요.","다른 보기는 시의 분위기와 맞지 않거나 낭송 방법을 헷갈렸어요.","시 분위기를 먼저 정하고 목소리를 골라요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#22','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C12',3,'mc','auto','「해와 달이 된 오누이」 인형극에서 해설이 하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X16']::text[],false,'{"seq":22,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"「해와 달이 된 오누이」 인형극에서 해설이 하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「엄마를 기다리던 깊은 밤, 누군가 문을 두드려요.」","correct":true},{"t":"「얘들아, 엄마 왔다. 문 열어라.」","mis":"K2-1-u8-X04"},{"t":"「얼른 나무 위로 올라가자!」","mis":"K2-1-u8-X16"}],"explanation":["해설은 장면과 상황을 알려 줘요.","다른 보기는 인형극을 준비하거나 공연하는 바른 방법이 아니에요.","「인형보다 놀이!」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#23','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C6',4,'essay','teacher','「의좋은 형제」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"「의좋은 형제」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 형이 아우를 꼭 안아 주는 장면이 가장 기억에 남아요. 서로를 몰래 도운 마음을 알게 되어 제 마음도 뭉클했기 때문이에요. 저도 동생이 제 생일 카드를 몰래 만든 것을 알고 감동한 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#24','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 흥부의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 흥부의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 흥부는 깜짝 놀라고 무척 기뻤을 거예요. 쌀이 쏟아지자 커다란 목소리로 「아이고, 이게 웬 쌀이오!」라고 말했기 때문이에요.","scoring_points":["인물의 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#25','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C10',4,'essay','teacher','「연이의 종이배」의 연이에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「연이의 종이배」의 연이에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 연이에게 — 연이야, 종이배가 뒤집혔을 때 많이 속상했지? 그래도 오빠와 다시 접어서 해낸 게 대단해. 나도 실패해도 다시 해 볼게. — 시우가","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#1','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C1',1,'mc','auto','막대에 붙인 인형을 움직여 보여 주는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"막대에 붙인 인형을 움직여 보여 주는 작품은 어느 것인가요?","options":[{"t":"인형극","correct":true},{"t":"시","mis":"K2-1-u8-X01"},{"t":"이야기","mis":"K2-1-u8-X01"}],"explanation":["막대 인형극도 인형극의 한 가지예요.","다른 보기는 그 특징과 맞지 않는 작품이에요.","특징을 하나씩 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#2','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C2',1,'mc','auto','「보보는 고개를 푹 숙이고 혼자 앉았어요.」에서 보보의 마음을 짐작하게 하는 것은 무엇인가요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"「보보는 고개를 푹 숙이고 혼자 앉았어요.」에서 보보의 마음을 짐작하게 하는 것은 무엇인가요?","options":[{"t":"고개를 푹 숙인 행동","correct":true},{"t":"나무의 크기","mis":"K2-1-u8-X06"},{"t":"보보라는 이름","mis":"K2-1-u8-X06"}],"explanation":["고개를 숙이고 혼자 앉은 행동에서 시무룩한 마음이 보여요.","다른 보기에는 인물의 마음이 드러나지 않아요.","「이 부분에 마음이 보이나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#3','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C4',1,'mc','auto','흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"흉내 내는 말은 어느 것인가요?","options":[{"t":"새근새근","correct":true},{"t":"잠","mis":"K2-1-u8-X07"},{"t":"밤","mis":"K2-1-u8-X07"}],"explanation":["「새근새근」은 소리나 모양을 흉내 낸 말이에요.","다른 두 낱말은 무엇을 가리키는 이름이에요.","몸짓으로 따라 할 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#4','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 종이배가 뒤집히자 발을 동동 구른 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 종이배가 뒤집히자 발을 동동 구른 인물은 누구인가요?","options":[{"t":"연이","correct":true},{"t":"오빠","mis":"K2-1-u8-X04"},{"t":"동생","mis":"K2-1-u8-X03"}],"explanation":["연이가 속상해서 발을 동동 굴렀어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#5','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C7',1,'mc','auto','인형극에서 인물의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"인형극에서 인물의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"인형의 말·움직임·목소리","correct":true},{"t":"무대 막의 색깔","mis":"K2-1-u8-X11"},{"t":"관객의 수","mis":"K2-1-u8-X11"}],"explanation":["말·움직임·목소리에 인물의 마음이 드러나요.","다른 보기는 그 특징과 맞지 않아요.","인형을 무엇으로 움직이는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#6','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C11',1,'mc','auto','친구의 감상을 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"친구의 감상을 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"내 감상과 비슷한 점·다른 점을 견주며 들어요","correct":true},{"t":"중간에 끼어들어 내 말을 해요","mis":"K2-1-u8-X15"},{"t":"엎드려서 들어요","mis":"K2-1-u8-X15"}],"explanation":["견주어 들으면 감상이 넓어져요.","다른 보기는 바르지 않은 자세예요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#7','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C13',1,'mc','auto','「밥을」을 소리 내어 읽을 때 나는 소리는 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":7,"concept":"K2-1-u8-C13","difficulty":1,"kind":"mc","stem":"「밥을」을 소리 내어 읽을 때 나는 소리는 어느 것인가요?","options":[{"t":"[바블]","correct":true},{"t":"[밥을]","mis":"K2-1-u8-X18"},{"t":"[바을]","mis":"K2-1-u8-X18"}],"explanation":["받침 뒤에 「ㅇ」으로 시작하는 글자가 와서 받침이 뒤로 넘어가 [바블]로 소리 나요.","글자 그대로 읽으면 자연스럽지 않아요.","받침 뒤 글자가 「ㅇ」인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#8','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C3',1,'ox','auto','「주고받기」는 두 사람이 한 줄씩 번갈아 읽는 낭송 방법이에요.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"「주고받기」는 두 사람이 한 줄씩 번갈아 읽는 낭송 방법이에요.","answer":"O","reason_options":[{"t":"번갈아 읽으면 주고받는 느낌이 살아나니까","correct":true},{"t":"주고받기는 모두가 한꺼번에 소리치는 것이니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["주고받기는 번갈아 읽는 방법이에요.","시마다 어울리는 낭송 방법이 달라요.","시 분위기를 먼저 정하고 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#9','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「숨도 조용조용 쉰다」에 담긴 「나」의 마음은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「숨도 조용조용 쉰다」에 담긴 「나」의 마음은 무엇인가요?","options":[{"t":"동생이 깰까 봐 조심하는 마음","correct":true},{"t":"동생과 싸우고 싶은 마음","mis":"K2-1-u8-X05"},{"t":"숨이 차서 힘든 마음","mis":"K2-1-u8-X06"}],"explanation":["숨까지 조용히 쉬는 행동에 조심하는 마음이 담겨 있어요.","다른 보기는 행동과 맞지 않거나 마음이 드러나지 않는 것이에요.","행동 속에 담긴 마음을 찾아요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#10','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 연이의 마음이 다시 기뻐지게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 연이의 마음이 다시 기뻐지게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"오빠와 튼튼하게 다시 접은 배가 멀리 떠가서","correct":true},{"t":"종이배가 돌에 걸려 뒤집혀서","mis":"K2-1-u8-X09"},{"t":"오빠가 배를 혼자 가져가서","mis":"K2-1-u8-X09"}],"explanation":["다시 접은 배가 잘 떠가자 기뻐졌어요.","다른 보기는 마음이 바뀐 차례가 맞지 않아요.","처음·가운데·끝 마음을 따로 적어 봐요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#11','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C6',2,'error','auto','기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],false,'{"seq":11,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"건우 — 「나는 흥부네 박이 갈라지는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"서아 — 「아이들이 춤추는 장면이 기억에 남아. 배고프던 아이들이 기뻐해서 나도 기뻤거든.」","mis":"K2-1-u8-X19"},{"t":"윤호 — 「박을 타며 노래하는 장면이 기억에 남아. 노랫소리가 신나서 따라 하고 싶었거든.」","mis":"K2-1-u8-X19"}],"explanation":["장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","다른 두 친구는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#12','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C7',2,'match','auto','인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"눈물을 글썽이는 목소리","r":"고맙고 뭉클하다"},{"l":"작고 떨리는 목소리","r":"겁이 난다"},{"l":"크고 빠른 목소리","r":"신이 난다"}],"mis":"K2-1-u8-X12","explanation":["목소리의 크기와 빠르기에 마음이 묻어나요.","같은 말도 목소리에 따라 다르게 들려요.","그 목소리로 직접 말해 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#13','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C8',2,'mc','auto','줄거리를 읽고 답해 보세요. 「엄마가 고개에서 호랑이를 만났어요.」 바로 다음에 일어난 일은 무엇인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":13,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 「엄마가 고개에서 호랑이를 만났어요.」 바로 다음에 일어난 일은 무엇인가요?","options":[{"t":"호랑이가 엄마 옷을 입고 집으로 찾아갔어요","correct":true},{"t":"오누이가 해와 달이 되었어요","mis":"K2-1-u8-X13"},{"t":"엄마가 떡을 팔러 집을 나섰어요","mis":"K2-1-u8-X13"}],"explanation":["고개 다음에는 호랑이가 집으로 찾아갔어요.","다른 보기는 차례가 뒤섞였어요.","장소나 일이 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#14','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C13',2,'mc','auto','받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"물이 → [무리]","correct":true},{"t":"물이 → [물이]","mis":"K2-1-u8-X18"},{"t":"물이 → [무이]","mis":"K2-1-u8-X18"}],"explanation":["받침 ㄹ이 뒤 글자로 넘어가 [무리]로 소리 나요.","다른 보기는 받침을 넘기지 않았거나 넘기지 않아야 할 곳에서 넘겼어요.","받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#15','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 서윤이가 보보에게 덩달아 기뻤다고 한 때는 언제인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":15,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 서윤이가 보보에게 덩달아 기뻤다고 한 때는 언제인가요?","options":[{"t":"토토와 다미가 음식을 나눠 줄 때","correct":true},{"t":"도시락이 텅 비어 있을 때","mis":"K2-1-u8-X14"},{"t":"보보가 나무 뒤에 혼자 앉았을 때","mis":"K2-1-u8-X14"}],"explanation":["친구들이 음식을 나눠 줄 때 덩달아 기뻤다고 했어요.","다른 보기는 편지의 다른 부분이에요.","누구에게 · 하고 싶은 말 · 왜 · 누가를 나눠 짚어요."],"asset":{"type":"passage","lines":["보보에게","보보야, 도시락이 텅 비어 있을 때 많이 속상했지?","토토와 다미가 음식을 나눠 줄 때 나도 덩달아 기뻤어.","다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라.","— 서윤이가"],"title":"서윤이가 보보에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#16','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C12',2,'error','auto','모둠이 인형극을 준비하는 모습이에요. 바르지 않게 준비한 친구는 누구인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X19']::text[],false,'{"seq":16,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"모둠이 인형극을 준비하는 모습이에요. 바르지 않게 준비한 친구는 누구인가요?","options":[{"t":"지안 — 인형 꾸미기에만 매달려 대사 연습을 하지 않았어요","correct":true,"mis_target":"K2-1-u8-X16"},{"t":"아린 — 맡은 인물의 마음을 생각하며 대사를 연습했어요","mis":"K2-1-u8-X19"},{"t":"준우 — 해설을 맡아 장면을 천천히 알려 주는 연습을 했어요","mis":"K2-1-u8-X19"}],"explanation":["인형 꾸미기보다 연습과 인형극 놀이가 더 중요해요.","다른 두 친구는 약속을 바르게 지켰어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#17','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 아우가 눈물을 글썽이며 「형님, 고맙습니다.」라고 한 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],false,'{"seq":17,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 아우가 눈물을 글썽이며 「형님, 고맙습니다.」라고 한 까닭은 무엇인가요?","options":[{"t":"형님도 자기를 위해 볏단을 옮겨 주었다는 것을 알게 되어서","correct":true},{"t":"볏단이 너무 무거워서","mis":"K2-1-u8-X03"},{"t":"형님에게 꾸중을 들어서","mis":"K2-1-u8-X05"}],"explanation":["서로를 위한 마음을 알고 뭉클했어요.","다른 보기는 대본에 없거나 인물의 마음과 맞지 않아요.","대본에서 인물의 말과 행동을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#18','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C2',3,'error','auto','글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 잘못 상상한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],false,'{"seq":18,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 잘못 상상한 친구는 누구인가요?","options":[{"t":"도담 — 「보물이 쏟아질 때 흥부는 실망했을 거야.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"소율 — 「흥부는 꿈인가 싶었을 거야. 입을 다물지 못했으니까.」","mis":"K2-1-u8-X19"},{"t":"민준 — 「흥부와 아내는 설렜을 거야. 노래하며 박을 탔으니까.」","mis":"K2-1-u8-X19"}],"explanation":["입을 다물지 못할 만큼 놀란 흥부가 실망했을 리 없어요.","다른 두 친구는 말·행동·상황을 알맞게 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#19','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C11',3,'ox','auto','감상을 발표할 때는 장면만 말하고 까닭은 말하지 않아도 돼요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":19,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"감상을 발표할 때는 장면만 말하고 까닭은 말하지 않아도 돼요.","answer":"X","reason_options":[{"t":"까닭을 함께 말해야 내 생각과 느낌이 잘 전해지니까","correct":true},{"t":"까닭을 말하면 친구들이 지루해하니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["장면과 까닭을 함께 말해요.","나와 다른 감상도 존중하며 들어요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#20','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C13',3,'ox','auto','「길이」는 글자 그대로 [길이]로 읽어야 자연스러워요.',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":20,"concept":"K2-1-u8-C13","difficulty":3,"kind":"ox","stem":"「길이」는 글자 그대로 [길이]로 읽어야 자연스러워요.","answer":"X","reason_options":[{"t":"받침 ㄹ이 뒤로 넘어가 [기리]로 읽어야 자연스러우니까","correct":true},{"t":"받침이 넘어가면 다른 낱말이 되니까","mis":"K2-1-u8-X18"}],"mis":"K2-1-u8-X18","explanation":["「이」 앞에서 받침 ㄹ이 넘어가요.","받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가요.","받침 뒤 글자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#21','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 「몸짓 넣기」로 낭송할 때 알맞은 몸짓은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":21,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 「몸짓 넣기」로 낭송할 때 알맞은 몸짓은 어느 것인가요?","options":[{"t":"「살금살금」에서 발끝으로 조용히 걷는 몸짓","correct":true},{"t":"「살금살금」에서 쿵쿵 뛰는 몸짓","mis":"K2-1-u8-X08"},{"t":"「새근새근」에서 크게 박수 치는 몸짓","mis":"K2-1-u8-X08"}],"explanation":["흉내 내는 말에 맞는 몸짓을 넣어요.","다른 보기는 시의 분위기와 맞지 않거나 낭송 방법을 헷갈렸어요.","시 분위기를 먼저 정하고 목소리를 골라요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#22','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C12',3,'mc','auto','흥부네의 기쁜 마음을 살리는 인형극 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X12','K2-1-u8-X16']::text[],false,'{"seq":22,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"흥부네의 기쁜 마음을 살리는 인형극 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쌀이 쏟아질 때 흥부는 놀란 큰 목소리, 아이들 인형은 깡충깡충 뛰게 움직이기","correct":true},{"t":"모두 작은 목소리로 천천히 말하고 인형은 가만히 두기","mis":"K2-1-u8-X12"},{"t":"인형 꾸미기에 시간을 다 쓰고 대사는 공연 때 처음 읽기","mis":"K2-1-u8-X16"}],"explanation":["목소리와 움직임이 함께 기쁜 마음을 살려요.","다른 보기는 인형극을 준비하거나 공연하는 바른 방법이 아니에요.","「인형보다 놀이!」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#23','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C6',4,'essay','teacher','「흥부와 놀부」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"「흥부와 놀부」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 아이들이 얼싸안고 덩실덩실 춤추는 장면이 가장 기억에 남아요. 늘 배고프던 아이들이 기뻐하는 모습에 저도 웃음이 났기 때문이에요. 저도 기다리던 선물을 받았을 때 동생과 껴안고 뛰었던 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#24','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 아우의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 아우의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 아우는 놀랍고 고마웠을 거예요. 형을 보고 눈이 동그래졌고, 눈물을 글썽이며 「형님, 고맙습니다.」라고 말했기 때문이에요.","scoring_points":["인물의 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#25','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C10',4,'essay','teacher','「콩쥐팥쥐」의 두꺼비에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「콩쥐팥쥐」의 두꺼비에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 두꺼비에게 — 두꺼비야, 울고 있던 콩쥐를 위해 독 구멍을 막아 줘서 고마워. 네 덕분에 콩쥐가 웃을 수 있었어. 나도 어려운 친구를 도와줄게. — 민지가","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C1','math',2,1,'u1',2,'백 알아보기 — 10이 10개인 수 100을 쓰고 「백」으로 읽으며, 99보다 1만큼·90보다 10만큼 더 큰 수로 나타내기',ARRAY['2수01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C2','math',2,1,'u1',3,'몇백 알아보기 — 100이 몇 개인지로 200~900을 쓰고 읽으며, 몇백이 100이 몇 개인지 거꾸로 알기',ARRAY['2수01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C3','math',2,1,'u1',4,'세 자리 수 쓰고 읽기 — 100·10·1의 개수(수 모형·동전)로 세 자리 수를 쓰고 읽으며, 없는 자리에는 0을 쓰고 0인 자리는 읽지 않기',ARRAY['2수01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C4','math',2,1,'u1',5,'각 자리의 숫자가 나타내는 값 — 백·십·일의 자리 숫자를 찾고, 같은 숫자라도 자리에 따라 값이 다름을 알며, 세 자리 수를 각 자리 값의 합으로 나타내기',ARRAY['2수01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C5','math',2,1,'u1',6,'뛰어 세기 — 100씩·10씩·1씩 뛰어 세고 거꾸로 세며, 몇씩 뛰었는지 찾고, 윗자리가 바뀌는 문턱(390→400, 999→1000) 넘기',ARRAY['2수01-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C6','math',2,1,'u1',7,'세 자리 수의 크기 비교 — 높은 자리부터 차례로 견주어 >·<로 나타내고, 셋 가운데 가장 큰/작은 수와 수 카드로 가장 큰/작은 수 찾기',ARRAY['2수01-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C7','math',2,1,'u1',9,'수를 여러 가지로 나타내기 — 한 수를 100·10·1의 여러 묶음(10이 몇 개, 동전 바꾸기)으로 나타내고, 한 자리에 10개가 넘게 모이면 윗자리로 바꾸어 세기',ARRAY['2수01-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X01','math',2,'u1',ARRAY['M2-1-u1-C1','M2-1-u1-C5']::text[],'9 다음에 윗자리가 바뀌는 것을 모르고 숫자를 이어 붙인다 — 99 다음을 910, 390에서 10 더를 3100, 999 다음을 9910','수 모형으로 9개 다음 1개를 더 놓고, 10개가 되면 윗자리 모형 1개로 바꾸는 장면을 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X02','math',2,'u1',ARRAY['M2-1-u1-C1','M2-1-u1-C7']::text[],'10이 10개를 1010이나 20처럼 늘어놓거나, 100 속에 10이 몇 개 있는지 모른다','십 모형 10개를 백 모형 1개 위에 겹쳐 놓아 크기가 같음을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X03','math',2,'u1',ARRAY['M2-1-u1-C2','M2-1-u1-C7']::text[],'100의 개수를 다른 자리에 쓴다 — 100이 5개를 105·50으로, 600을 100이 60개로','백·십·일 칸을 그려 놓고 「100이 몇 개」는 백의 칸에만 쓰게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X04','math',2,'u1',ARRAY['M2-1-u1-C3','M2-1-u1-C4']::text[],'없는 자리의 0을 빠뜨린다 — 백 5·일 3을 53으로, 「구백이」를 92로','세 칸을 먼저 그리고 빈 칸에 0을 채우는 습관 들이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X05','math',2,'u1',ARRAY['M2-1-u1-C3','M2-1-u1-C4']::text[],'읽은 소리나 각 자리 값을 그대로 이어 쓴다 — 이백오십사를 200504로, 300+40+7을 300407로','세 자리 수는 숫자 세 개 — 칸 하나에 숫자 하나만 들어간다는 것을 수 카드 세 장으로 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X06','math',2,'u1',ARRAY['M2-1-u1-C3']::text[],'자리 순서를 섞어 쓴다 — 백 3·십 4·일 7을 743으로','「백·십·일」을 왼쪽부터 손가락으로 짚으며 숫자를 놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X07','math',2,'u1',ARRAY['M2-1-u1-C1','M2-1-u1-C2','M2-1-u1-C3']::text[],'읽을 때 자리 이름을 빼먹거나 0을 읽는다 — 254를 「이오사」, 507을 「오백영칠」','숫자 뒤에 자리 이름(백·십)을 붙여 끊어 읽고, 0인 자리는 건너뛰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X08','math',2,'u1',ARRAY['M2-1-u1-C4']::text[],'자리 이름을 헷갈린다 — 오른쪽부터 세어 백의 자리와 일의 자리를 바꾸거나, 십의 자리 숫자를 다른 자리 값으로 읽는다','자릿값 표에 수를 써 넣고 「왼쪽이 백」을 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X09','math',2,'u1',ARRAY['M2-1-u1-C4']::text[],'숫자와 그 숫자가 나타내는 값을 같게 본다 — 382의 8을 8로, 323의 두 3을 같은 값으로','「숫자 × 자리」로 값을 말하게 하기 — 8은 십의 자리라서 80') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X10','math',2,'u1',ARRAY['M2-1-u1-C3','M2-1-u1-C7']::text[],'한 자리에 10개가 넘게 모여도 윗자리로 바꾸지 않는다 — 10이 13개·1이 2개를 1132나 32로','10개씩 묶어 윗자리 모형 하나로 바꾼 뒤 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X11','math',2,'u1',ARRAY['M2-1-u1-C5']::text[],'뛰어 셀 때 다른 자리 숫자를 바꾼다 — 10씩 뛰는데 일의 자리나 백의 자리를 1 바꿈','「10씩이면 십의 자리만 움직인다」 — 바뀌는 자리에 색칠하며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X12','math',2,'u1',ARRAY['M2-1-u1-C1','M2-1-u1-C5']::text[],'1·10·100 가운데 얼마만큼인지, 몇씩 뛰었는지를 헷갈리거나 방향을 거꾸로 한다','이웃한 두 수에서 바뀐 자리를 찾아 「그 자리만큼」이라고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X13','math',2,'u1',ARRAY['M2-1-u1-C6']::text[],'낮은 자리부터 견준다 — 일의 자리가 큰 169가 196보다 크다고 한다','두 수를 자릿값 표에 위아래로 써 놓고 백의 자리부터 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X14','math',2,'u1',ARRAY['M2-1-u1-C6']::text[],'>·< 기호의 방향을 거꾸로 쓴다','벌어진 입이 큰 수를 먹는다 — 큰 수 쪽이 벌어진 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X15','math',2,'u1',ARRAY['M2-1-u1-C6','M2-1-u1-C7']::text[],'묻는 말을 거꾸로 읽는다 — 가장 큰↔가장 작은, 더 필요한 수↔전체 수','물음의 「큰·작은·더」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X16','math',2,'u1',ARRAY['M2-1-u1-C6']::text[],'수 카드로 수를 만들 때 높은 자리부터 놓지 않거나 0을 맨 앞에 놓는다','백의 자리부터 차례로 — 가장 작은 수를 만들 때 0은 백의 자리에 못 온다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#1','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',1,'mc','auto','십 모형 10개가 있어요. 모두 얼마인가요?',ARRAY['M2-1-u1-X02']::text[],true,'{"seq":1,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"십 모형 10개가 있어요. 모두 얼마인가요?","options":[{"t":"100","correct":true},{"t":"1010","mis":"M2-1-u1-X02"},{"t":"10","mis":"M2-1-u1-X02"}],"explanation":["십 모형 하나는 10이에요.","10이 10개이면 100이에요.","십 모형 10개는 백 모형 1개와 같아요."],"asset":{"type":"blocks3","h":0,"t":10,"o":0},"variant_rule":{"alt":[{"stem":"10원짜리 동전 10개는 모두 얼마인가요?","options":[{"t":"100원","correct":true},{"t":"1010원","mis":"M2-1-u1-X02"},{"t":"10원","mis":"M2-1-u1-X02"}],"explanation":["10원짜리 하나는 10원이에요.","10원이 10개이면 100원이에요.","10원짜리 10개는 100원짜리 1개와 같아요."],"asset":{"type":"blocks3","h":0,"t":10,"o":0,"unit":"coin"}},{"stem":"구슬이 10개씩 10봉지 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"100","correct":true},{"t":"20","mis":"M2-1-u1-X02"},{"t":"1010","mis":"M2-1-u1-X02"}],"explanation":["한 봉지에 10개씩이에요.","10이 10개이면 100이에요.","봉지 수와 구슬 수를 헷갈리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#2','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',1,'sa','auto','10이 10개이면 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u1-C1","difficulty":1,"kind":"sa","stem":"10이 10개이면 얼마인가요?","answer":["100"],"explanation":["10씩 세어 보세요 — 10, 20, … 90, 100.","10이 10개이면 100이에요.","100은 「백」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"99보다 1만큼 더 큰 수는 얼마인가요?","answer":["100"],"explanation":["99 바로 다음 수를 찾아요.","99보다 1 큰 수는 100이에요.","99 다음은 910이 아니라 100이에요."]},{"stem":"90보다 10만큼 더 큰 수는 얼마인가요?","answer":["100"],"explanation":["90에서 10을 더 뛰어 세어요.","90보다 10 큰 수는 100이에요.","십 모형 9개에 1개를 더하면 10개 — 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#3','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',1,'mc','auto','100을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07','M2-1-u1-X02']::text[],true,'{"seq":3,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"100을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"백","correct":true},{"t":"일영영","mis":"M2-1-u1-X07"},{"t":"십십","mis":"M2-1-u1-X02"}],"explanation":["100은 백의 자리가 1인 수예요.","「백」이라고 읽어요.","숫자를 하나씩 따로 읽지 않아요."],"variant_rule":{"alt":[{"stem":"「백」을 수로 쓰면 무엇인가요?","options":[{"t":"100","correct":true},{"t":"1","mis":"M2-1-u1-X03"},{"t":"10","mis":"M2-1-u1-X02"}],"explanation":["「백」은 10이 10개인 수예요.","수로 쓰면 100이에요.","1 뒤에 0을 두 개 써요."]},{"stem":"100에 대한 설명으로 바른 것은 어느 것인가요?","options":[{"t":"99보다 1 큰 수예요.","correct":true},{"t":"90보다 1 큰 수예요.","mis":"M2-1-u1-X12"},{"t":"10이 1개인 수예요.","mis":"M2-1-u1-X02"}],"explanation":["100은 99 바로 다음 수예요.","90보다는 10 커요.","10이 10개 모여야 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#4','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',1,'mc','auto','99보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X12']::text[],true,'{"seq":4,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"99보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"98","mis":"M2-1-u1-X12"}],"explanation":["99 다음 수를 찾아요.","99보다 1 큰 수는 100이에요.","9 뒤에 10을 붙이지 않아요 — 십 모형이 10개가 되어 백 모형 1개가 돼요."],"variant_rule":{"alt":[{"stem":"98, 99 다음에 오는 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"990","mis":"M2-1-u1-X01"}],"explanation":["99 다음 수예요.","99보다 1 큰 수는 100이에요.","일의 자리·십의 자리가 모두 9이면 다음은 100이에요."]},{"stem":"100보다 1만큼 더 작은 수는 무엇인가요?","options":[{"t":"99","correct":true},{"t":"101","mis":"M2-1-u1-X12"},{"t":"90","mis":"M2-1-u1-X12"}],"explanation":["100 바로 앞의 수예요.","100보다 1 작은 수는 99예요.","1만큼은 바로 앞, 10만큼은 십 모형 하나 차이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#5','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'mc','auto','100은 90보다 얼마만큼 더 큰 수인가요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":5,"concept":"M2-1-u1-C1","difficulty":2,"kind":"mc","stem":"100은 90보다 얼마만큼 더 큰 수인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X12"},{"t":"100","mis":"M2-1-u1-X12"}],"explanation":["90에서 10씩 뛰어 세면 바로 100이에요.","그래서 100은 90보다 10 큰 수예요.","십 모형 9개에 1개를 더하면 10개예요."],"variant_rule":{"alt":[{"stem":"100은 99보다 얼마만큼 더 큰 수인가요?","options":[{"t":"1","correct":true},{"t":"10","mis":"M2-1-u1-X12"},{"t":"9","mis":"M2-1-u1-X12"}],"explanation":["99 바로 다음 수가 100이에요.","그래서 100은 99보다 1 커요.","바로 다음 수는 1 큰 수예요."]},{"stem":"100은 80보다 얼마만큼 더 큰 수인가요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-1-u1-X12"},{"t":"10","mis":"M2-1-u1-X12"}],"explanation":["80, 90, 100 — 10씩 두 번 뛰어요.","그래서 100은 80보다 20 커요.","10씩 몇 번 뛰었는지 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#6','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'mc','auto','100은 10이 몇 개인 수인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X09']::text[],true,'{"seq":6,"concept":"M2-1-u1-C1","difficulty":2,"kind":"mc","stem":"100은 10이 몇 개인 수인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X02"},{"t":"100","mis":"M2-1-u1-X09"}],"explanation":["10, 20, 30, … 100 — 10씩 세어 보세요.","10번 세면 100이에요.","그래서 100은 10이 10개예요."],"variant_rule":{"alt":[{"stem":"구슬 100개를 10개씩 묶으면 몇 묶음이 되나요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X02"},{"t":"100","mis":"M2-1-u1-X09"}],"explanation":["10개씩 묶어요.","100은 10이 10개 — 10묶음이에요.","묶음 수와 구슬 수를 헷갈리지 않아요."]},{"stem":"100원은 10원짜리 동전 몇 개와 같나요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M2-1-u1-X09"},{"t":"1","mis":"M2-1-u1-X02"}],"explanation":["10원씩 세어요 — 10, 20, … 100.","10원짜리 10개면 100원이에요.","그래서 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#7','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'ox','auto','구슬을 10개씩 10묶음 모으면 구슬은 100개예요.',ARRAY['M2-1-u1-X02']::text[],true,'{"seq":7,"concept":"M2-1-u1-C1","difficulty":2,"kind":"ox","stem":"구슬을 10개씩 10묶음 모으면 구슬은 100개예요.","answer":"O","reason_options":[{"t":"10이 10개이면 100이니까","correct":true},{"t":"10묶음이니까 구슬은 10개라서","mis":"M2-1-u1-X02"}],"mis":"M2-1-u1-X02","explanation":["한 묶음에 구슬이 10개예요.","10이 10개이면 100이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"99 다음 수는 910이에요.","answer":"X","reason_options":[{"t":"99보다 1 큰 수는 100이니까","correct":true},{"t":"9 뒤에 10을 붙이면 되니까","mis":"M2-1-u1-X01"}],"explanation":["99에 1을 더하면 일의 자리가 10이 돼요.","그래서 십의 자리, 백의 자리로 차례로 넘어가 100이에요.","숫자를 이어 붙이지 않아요."]},{"stem":"100은 10이 1개인 수예요.","answer":"X","reason_options":[{"t":"10이 10개 모여야 100이니까","correct":true},{"t":"100에 1이 있으니까 10이 1개라서","mis":"M2-1-u1-X02"}],"explanation":["10이 1개면 10이에요.","10이 10개 모여야 100이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#8','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'blank','auto','100은 99보다 (        )만큼 더 큰 수예요.',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":8,"concept":"M2-1-u1-C1","difficulty":2,"kind":"blank","stem":"100은 99보다 (        )만큼 더 큰 수예요.","options":[{"t":"1","correct":true},{"t":"10","mis":"M2-1-u1-X12"},{"t":"100","mis":"M2-1-u1-X12"}],"explanation":["99 바로 다음 수가 100이에요.","바로 다음 수는 1만큼 더 큰 수예요.","그래서 빈칸은 1이에요."],"variant_rule":{"alt":[{"stem":"100은 90보다 (        )만큼 더 큰 수예요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X12"},{"t":"9","mis":"M2-1-u1-X12"}],"explanation":["90 다음 10씩 뛰면 100이에요.","그래서 10만큼 커요.","십 모형 1개 차이예요."]},{"stem":"10이 (        )개이면 100이에요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X02"},{"t":"100","mis":"M2-1-u1-X09"}],"explanation":["10씩 세어 100까지 가요.","10번 세면 100이에요.","10이 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#9','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'match','auto','같은 수끼리 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u1-C1","difficulty":2,"kind":"match","stem":"같은 수끼리 이어 보세요.","pairs":[{"l":"99보다 1 큰 수","r":"100"},{"l":"90보다 1 큰 수","r":"91"},{"l":"10이 9개인 수","r":"90"}],"mis":"M2-1-u1-X12","explanation":["99보다 1 큰 수는 100이에요.","90보다 1 큰 수는 91, 10이 9개인 수는 90이에요.","1만큼과 10만큼을 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"90보다 10 큰 수","r":"100"},{"l":"80보다 10 큰 수","r":"90"},{"l":"99보다 1 작은 수","r":"98"}],"explanation":["90보다 10 큰 수는 100이에요.","80보다 10 큰 수는 90, 99보다 1 작은 수는 98이에요.","얼마만큼 큰지, 작은지 잘 읽어요."]},{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"10이 10개","r":"100"},{"l":"10이 8개","r":"80"},{"l":"10이 1개","r":"10"}],"explanation":["10이 10개이면 100이에요.","10이 8개면 80, 1개면 10이에요.","10이 몇 개인지로 수를 알아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#10','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',3,'sa','auto','60부터 10씩 뛰어 세었어요. 몇 번 뛰어 세면 100이 되나요?','{}'::text[],true,'{"seq":10,"concept":"M2-1-u1-C1","difficulty":3,"kind":"sa","stem":"60부터 10씩 뛰어 세었어요. 몇 번 뛰어 세면 100이 되나요?","answer":["4","4번"],"explanation":["60, 70, 80, 90, 100이에요.","70·80·90·100 — 4번 뛰었어요.","처음 수 60은 뛴 횟수에 넣지 않아요."],"variant_rule":{"alt":[{"stem":"70부터 10씩 뛰어 세었어요. 몇 번 뛰어 세면 100이 되나요?","answer":["3","3번"],"explanation":["70, 80, 90, 100이에요.","80·90·100 — 3번 뛰었어요.","처음 수는 뛴 횟수에 넣지 않아요."]},{"stem":"96부터 1씩 뛰어 세었어요. 몇 번 뛰어 세면 100이 되나요?","answer":["4","4번"],"explanation":["96, 97, 98, 99, 100이에요.","97·98·99·100 — 4번 뛰었어요.","처음 수는 뛴 횟수에 넣지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#1','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',2,'mc','auto','70과 어떤 수를 모으면 100이 돼요. 어떤 수는 무엇인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X12']::text[],true,'{"seq":1,"concept":"M2-1-u1-C1","difficulty":2,"kind":"mc","stem":"70과 어떤 수를 모으면 100이 돼요. 어떤 수는 무엇인가요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M2-1-u1-X02"},{"t":"40","mis":"M2-1-u1-X12"}],"explanation":["70에서 10씩 뛰어 세면 80, 90, 100이에요.","10씩 3번 — 30이에요.","70과 30을 모으면 100이에요."],"variant_rule":{"alt":[{"stem":"40과 어떤 수를 모으면 100이 돼요. 어떤 수는 무엇인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M2-1-u1-X02"},{"t":"50","mis":"M2-1-u1-X12"}],"explanation":["40에서 10씩 뛰면 50, 60, … 100이에요.","10씩 6번 — 60이에요.","40과 60을 모으면 100이에요."]},{"stem":"100을 똑같은 두 수로 가르면 한 수는 얼마인가요?","options":[{"t":"50","correct":true},{"t":"5","mis":"M2-1-u1-X02"},{"t":"10","mis":"M2-1-u1-X12"}],"explanation":["50과 50을 모으면 100이에요.","그래서 한 수는 50이에요.","십 모형 10개를 5개씩 나눈 것과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#2','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',2,'error','auto','친구들이 100에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X01','M2-1-u1-X12']::text[],true,'{"seq":2,"concept":"M2-1-u1-C1","difficulty":2,"kind":"error","stem":"친구들이 100에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호: 10이 10개니까 1010이라고 써.","correct":true,"mis_target":"M2-1-u1-X02"},{"t":"하린: 99보다 1 큰 수가 100이야.","mis":"M2-1-u1-X01"},{"t":"도윤: 100은 90보다 10 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["10이 10개 모이면 새로운 자리, 백의 자리가 생겨요.","그래서 1010이 아니라 100이라고 써요.","지호가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 100에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 100은 「일영영」이라고 읽어.","correct":true,"mis_target":"M2-1-u1-X07"},{"t":"준우: 100은 「백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"라희: 100은 99 다음 수야.","mis":"M2-1-u1-X01"}],"explanation":["100은 「백」이라고 읽어요.","숫자를 하나씩 따로 읽지 않아요.","서아가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#3','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'mc','auto','구슬이 10개씩 묶음 9개와 낱개 10개 있어요. 구슬은 모두 몇 개인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":3,"concept":"M2-1-u1-C1","difficulty":3,"kind":"mc","stem":"구슬이 10개씩 묶음 9개와 낱개 10개 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X10"},{"t":"91","mis":"M2-1-u1-X10"}],"explanation":["낱개 10개는 10개씩 묶음 1개로 바꿀 수 있어요.","그러면 10개씩 묶음이 10개 — 100이에요.","낱개가 10개면 묶음 하나로 바꿔 세요."],"variant_rule":{"alt":[{"stem":"10원짜리 동전 9개와 1원짜리 동전 10개는 모두 얼마인가요?","options":[{"t":"100원","correct":true},{"t":"910원","mis":"M2-1-u1-X10"},{"t":"91원","mis":"M2-1-u1-X10"}],"explanation":["1원짜리 10개는 10원짜리 1개와 같아요.","그러면 10원짜리가 10개 — 100원이에요.","한 자리에 10개가 모이면 윗자리로 바꿔요."]},{"stem":"10개씩 묶음 8개와 낱개 20개는 모두 몇 개인가요?","options":[{"t":"100","correct":true},{"t":"820","mis":"M2-1-u1-X10"},{"t":"82","mis":"M2-1-u1-X10"}],"explanation":["낱개 20개는 10개씩 묶음 2개예요.","묶음이 8개와 2개 — 10개이니 100이에요.","낱개가 10개 넘으면 묶음으로 바꿔 세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#4','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'sa','auto','사탕 100개를 한 봉지에 10개씩 담으면 몇 봉지가 되나요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u1-C1","difficulty":3,"kind":"sa","stem":"사탕 100개를 한 봉지에 10개씩 담으면 몇 봉지가 되나요?","answer":["10","10봉지"],"explanation":["100은 10이 10개예요.","그래서 10개씩 담으면 10봉지예요.","봉지 하나에 10개 — 10, 20, … 100으로 세어 보세요."],"variant_rule":{"alt":[{"stem":"색종이 100장을 10장씩 나누어 주면 몇 명에게 줄 수 있나요?","answer":["10","10명"],"explanation":["100은 10이 10개예요.","10장씩이면 10명에게 줄 수 있어요.","10씩 세어 100이 될 때까지 세어요."]},{"stem":"10원짜리 동전으로 100원을 만들려면 몇 개가 있어야 하나요?","answer":["10","10개"],"explanation":["10원씩 세어요.","10원짜리 10개면 100원이에요.","그래서 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#5','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'ox','auto','99 다음 수는 910이에요.',ARRAY['M2-1-u1-X01']::text[],true,'{"seq":5,"concept":"M2-1-u1-C1","difficulty":3,"kind":"ox","stem":"99 다음 수는 910이에요.","answer":"X","reason_options":[{"t":"99보다 1 큰 수는 100이니까","correct":true},{"t":"9 다음에 10을 붙이면 되니까","mis":"M2-1-u1-X01"}],"mis":"M2-1-u1-X01","explanation":["99에 1을 더하면 일의 자리가 10이 돼요.","10은 윗자리로 넘어가 다시 10이 되고, 결국 100이에요.","숫자를 이어 붙이지 않아요."],"variant_rule":{"alt":[{"stem":"90 다음에 10씩 뛰어 센 수는 100이에요.","answer":"O","reason_options":[{"t":"90보다 10 큰 수는 100이니까","correct":true},{"t":"90 다음은 910이니까","mis":"M2-1-u1-X01"}],"explanation":["90에서 10을 더 뛰어요.","십 모형이 10개가 되어 100이에요.","그래서 맞는 말이에요."]},{"stem":"100은 98보다 1 큰 수예요.","answer":"X","reason_options":[{"t":"98 다음은 99, 그다음이 100이라 2 크니까","correct":true},{"t":"100은 98 바로 다음 수니까","mis":"M2-1-u1-X12"}],"explanation":["98, 99, 100이에요.","100은 98보다 2 커요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#6','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'mc','auto','10씩 뛰어 세었어요. 70, 80, 90 다음에 오는 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X12']::text[],true,'{"seq":6,"concept":"M2-1-u1-C1","difficulty":3,"kind":"mc","stem":"10씩 뛰어 세었어요. 70, 80, 90 다음에 오는 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"91","mis":"M2-1-u1-X12"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","90에서 10을 더 뛰면 십 모형이 10개 — 100이에요.","9 다음에 10을 붙여 910으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"1씩 뛰어 세었어요. 97, 98, 99 다음에 오는 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"109","mis":"M2-1-u1-X12"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","99 다음은 100이에요.","숫자를 이어 붙이지 않아요."]},{"stem":"10씩 거꾸로 뛰어 세었어요. 100 다음에 오는 수는 무엇인가요?","options":[{"t":"90","correct":true},{"t":"99","mis":"M2-1-u1-X12"},{"t":"0","mis":"M2-1-u1-X12"}],"explanation":["10씩 거꾸로 뛰면 10만큼씩 작아져요.","100보다 10 작은 수는 90이에요.","1만큼 작은 99와 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#7','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'mc','auto','100이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X12']::text[],true,'{"seq":7,"concept":"M2-1-u1-C1","difficulty":3,"kind":"mc","stem":"100이 아닌 것은 어느 것인가요?","options":[{"t":"99보다 1 작은 수","correct":true},{"t":"10이 10개인 수","mis":"M2-1-u1-X02"},{"t":"90보다 10 큰 수","mis":"M2-1-u1-X12"}],"explanation":["10이 10개인 수, 90보다 10 큰 수는 모두 100이에요.","99보다 1 작은 수는 98이에요.","얼마만큼 「큰」지 「작은」지 잘 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 100이 아닌 것은 어느 것인가요?","options":[{"t":"10이 9개인 수","correct":true},{"t":"99보다 1 큰 수","mis":"M2-1-u1-X01"},{"t":"80보다 20 큰 수","mis":"M2-1-u1-X12"}],"explanation":["99보다 1 큰 수, 80보다 20 큰 수는 100이에요.","10이 9개인 수는 90이에요.","10이 10개여야 100이에요."]},{"stem":"이번에는 다른 보기예요. 100이 아닌 것은 어느 것인가요?","options":[{"t":"90보다 1 큰 수","correct":true},{"t":"50과 50을 모은 수","mis":"M2-1-u1-X02"},{"t":"10이 10개인 수","mis":"M2-1-u1-X02"}],"explanation":["50과 50을 모으면 100, 10이 10개도 100이에요.","90보다 1 큰 수는 91이에요.","90보다 「10」 커야 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#8','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',4,'mc','auto','어떤 수보다 10만큼 더 큰 수가 100이에요. 어떤 수보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X15','M2-1-u1-X12']::text[],true,'{"seq":8,"concept":"M2-1-u1-C1","difficulty":4,"kind":"mc","stem":"어떤 수보다 10만큼 더 큰 수가 100이에요. 어떤 수보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"91","correct":true},{"t":"101","mis":"M2-1-u1-X15"},{"t":"99","mis":"M2-1-u1-X12"}],"explanation":["100보다 10 작은 수가 어떤 수예요 — 90이에요.","90보다 1 큰 수는 91이에요.","먼저 어떤 수를 찾고 나서 묻는 말을 풀어요."],"variant_rule":{"alt":[{"stem":"어떤 수보다 1만큼 더 큰 수가 100이에요. 어떤 수보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"109","correct":true},{"t":"110","mis":"M2-1-u1-X15"},{"t":"100","mis":"M2-1-u1-X12"}],"explanation":["100보다 1 작은 수가 어떤 수예요 — 99예요.","99보다 10 큰 수는 109예요.","먼저 어떤 수를 찾고 나서 묻는 말을 풀어요."]},{"stem":"어떤 수보다 20만큼 더 큰 수가 100이에요. 어떤 수보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"90","correct":true},{"t":"110","mis":"M2-1-u1-X15"},{"t":"80","mis":"M2-1-u1-X12"}],"explanation":["100보다 20 작은 수가 어떤 수예요 — 80이에요.","80보다 10 큰 수는 90이에요.","먼저 어떤 수를 찾고 나서 묻는 말을 풀어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#9','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C7',4,'sa','auto','10원짜리 동전 7개와 1원짜리 동전 30개가 있어요. 모두 얼마인가요?','{}'::text[],true,'{"seq":9,"concept":"M2-1-u1-C7","difficulty":4,"kind":"sa","stem":"10원짜리 동전 7개와 1원짜리 동전 30개가 있어요. 모두 얼마인가요?","answer":["100","100원"],"explanation":["1원짜리 30개는 10원짜리 3개와 같아요.","10원짜리가 7개와 3개 — 10개이니 100원이에요.","10개씩 모이면 윗자리로 바꿔 세요."],"variant_rule":{"alt":[{"stem":"10원짜리 동전 6개와 1원짜리 동전 40개가 있어요. 모두 얼마인가요?","answer":["100","100원"],"explanation":["1원짜리 40개는 10원짜리 4개와 같아요.","10원짜리가 6개와 4개 — 10개이니 100원이에요.","10개씩 모이면 윗자리로 바꿔 세요."]},{"stem":"10원짜리 동전 5개와 1원짜리 동전 50개가 있어요. 모두 얼마인가요?","answer":["100","100원"],"explanation":["1원짜리 50개는 10원짜리 5개와 같아요.","10원짜리가 10개 — 100원이에요.","10개씩 모이면 윗자리로 바꿔 세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#10','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',4,'essay','teacher','100을 서로 다른 방법으로 두 가지 설명해 보세요. (예: ○○보다 ○만큼 더 큰 수)','{}'::text[],false,'{"seq":10,"concept":"M2-1-u1-C1","difficulty":4,"kind":"essay","stem":"100을 서로 다른 방법으로 두 가지 설명해 보세요. (예: ○○보다 ○만큼 더 큰 수)","answer_guide":{"answer":"예: 99보다 1 큰 수, 90보다 10 큰 수, 10이 10개인 수 가운데 두 가지","scoring_points":["서로 다른 설명 두 가지를 썼는가","설명한 수가 정말 100인가(얼마만큼 큰지 바른가)","1만큼과 10만큼을 구별해 썼는가"]},"explanation":["100은 여러 가지로 말할 수 있어요.","99보다 1 큰 수, 90보다 10 큰 수, 10이 10개인 수 모두 100이에요.","얼마만큼인지 바르게 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#1','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',1,'mc','auto','백 모형이 4개 있어요. 모두 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":1,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"백 모형이 4개 있어요. 모두 얼마인가요?","options":[{"t":"400","correct":true},{"t":"104","mis":"M2-1-u1-X03"},{"t":"40","mis":"M2-1-u1-X03"}],"explanation":["백 모형 하나는 100이에요.","100이 4개이면 400이에요.","개수 4는 백의 자리에 써요."],"asset":{"type":"blocks3","h":4,"t":0,"o":0},"variant_rule":{"alt":[{"stem":"백 모형이 6개 있어요. 모두 얼마인가요?","options":[{"t":"600","correct":true},{"t":"106","mis":"M2-1-u1-X03"},{"t":"60","mis":"M2-1-u1-X03"}],"explanation":["백 모형 하나는 100이에요.","100이 6개이면 600이에요.","개수 6은 백의 자리에 써요."],"asset":{"type":"blocks3","h":6,"t":0,"o":0}},{"stem":"백 모형이 3개 있어요. 모두 얼마인가요?","options":[{"t":"300","correct":true},{"t":"103","mis":"M2-1-u1-X03"},{"t":"30","mis":"M2-1-u1-X03"}],"explanation":["백 모형 하나는 100이에요.","100이 3개이면 300이에요.","개수 3은 백의 자리에 써요."],"asset":{"type":"blocks3","h":3,"t":0,"o":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#2','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',1,'mc','auto','100이 5개이면 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":2,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"100이 5개이면 얼마인가요?","options":[{"t":"500","correct":true},{"t":"105","mis":"M2-1-u1-X03"},{"t":"50","mis":"M2-1-u1-X03"}],"explanation":["100이 5개이면 500이에요.","「오백」이라고 읽어요.","개수는 백의 자리에 쓰고, 십·일의 자리는 0이에요."],"variant_rule":{"n3":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#3','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',1,'mc','auto','700을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07','M2-1-u1-X03']::text[],true,'{"seq":3,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"700을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"칠백","correct":true},{"t":"칠영영","mis":"M2-1-u1-X07"},{"t":"칠십","mis":"M2-1-u1-X03"}],"explanation":["700은 100이 7개예요.","「칠백」이라고 읽어요.","0인 자리는 읽지 않아요."],"variant_rule":{"alt":[{"stem":"300을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"삼백","correct":true},{"t":"삼영영","mis":"M2-1-u1-X07"},{"t":"삼십","mis":"M2-1-u1-X03"}],"explanation":["300은 100이 3개예요.","「삼백」이라고 읽어요.","0인 자리는 읽지 않아요."]},{"stem":"「구백」을 수로 쓰면 무엇인가요?","options":[{"t":"900","correct":true},{"t":"9100","mis":"M2-1-u1-X05"},{"t":"90","mis":"M2-1-u1-X03"}],"explanation":["「구백」은 100이 9개예요.","수로 쓰면 900이에요.","9 뒤에 0을 두 개 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#4','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',1,'sa','auto','800은 100이 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u1-C2","difficulty":1,"kind":"sa","stem":"800은 100이 몇 개인가요?","answer":["8","8개"],"explanation":["800은 백의 자리 숫자가 8이에요.","100이 8개예요.","백의 자리 숫자가 100의 개수예요."],"variant_rule":{"n3":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#5','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":5,"concept":"M2-1-u1-C2","difficulty":2,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"600원","correct":true},{"t":"106원","mis":"M2-1-u1-X03"},{"t":"60원","mis":"M2-1-u1-X03"}],"explanation":["100원짜리 동전 하나는 100원이에요.","100원짜리가 6개이면 600원이에요.","100씩 세어 보세요 — 100, 200, … 600."],"asset":{"type":"blocks3","h":6,"t":0,"o":0,"unit":"coin"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동전은 모두 얼마인가요?","options":[{"t":"400원","correct":true},{"t":"104원","mis":"M2-1-u1-X03"},{"t":"40원","mis":"M2-1-u1-X03"}],"explanation":["100원짜리 동전 하나는 100원이에요.","100원짜리가 4개이면 400원이에요.","100씩 세어 보세요 — 100, 200, 300, 400."],"asset":{"type":"blocks3","h":4,"t":0,"o":0,"unit":"coin"}},{"stem":"이번에는 다른 보기예요. 동전은 모두 얼마인가요?","options":[{"t":"800원","correct":true},{"t":"108원","mis":"M2-1-u1-X03"},{"t":"80원","mis":"M2-1-u1-X03"}],"explanation":["100원짜리 동전 하나는 100원이에요.","100원짜리가 8개이면 800원이에요.","100씩 세어 보세요."],"asset":{"type":"blocks3","h":8,"t":0,"o":0,"unit":"coin"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#6','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'match','auto','같은 수끼리 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u1-C2","difficulty":2,"kind":"match","stem":"같은 수끼리 이어 보세요.","pairs":[{"l":"100이 3개","r":"300"},{"l":"이백","r":"200"},{"l":"100이 9개","r":"900"}],"mis":"M2-1-u1-X03","explanation":["100이 3개는 300, 100이 9개는 900이에요.","「이백」은 200이에요.","100의 개수는 백의 자리 숫자예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"100이 5개","r":"500"},{"l":"칠백","r":"700"},{"l":"100이 4개","r":"400"}],"explanation":["100이 5개는 500, 100이 4개는 400이에요.","「칠백」은 700이에요.","100의 개수는 백의 자리 숫자예요."]},{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"육백","r":"600"},{"l":"100이 2개","r":"200"},{"l":"팔백","r":"800"}],"explanation":["「육백」은 600, 「팔백」은 800이에요.","100이 2개는 200이에요.","몇백은 백의 자리만 0이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#7','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'blank','auto','500은 100이 (        )개인 수예요.',ARRAY['M2-1-u1-X03','M2-1-u1-X09']::text[],true,'{"seq":7,"concept":"M2-1-u1-C2","difficulty":2,"kind":"blank","stem":"500은 100이 (        )개인 수예요.","options":[{"t":"5","correct":true},{"t":"50","mis":"M2-1-u1-X03"},{"t":"500","mis":"M2-1-u1-X09"}],"explanation":["500은 백의 자리 숫자가 5예요.","그래서 100이 5개예요.","백의 자리 숫자가 100의 개수예요."],"variant_rule":{"n3":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#8','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'ox','auto','100이 6개인 수는 106이에요.',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":8,"concept":"M2-1-u1-C2","difficulty":2,"kind":"ox","stem":"100이 6개인 수는 106이에요.","answer":"X","reason_options":[{"t":"100이 6개이면 600이니까","correct":true},{"t":"100 뒤에 6을 붙이면 되니까","mis":"M2-1-u1-X03"}],"mis":"M2-1-u1-X03","explanation":["100씩 6번 세면 100, 200, … 600이에요.","100이 6개인 수는 600이에요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"400은 100이 4개인 수예요.","answer":"O","reason_options":[{"t":"100씩 4번 세면 400이니까","correct":true},{"t":"400은 10이 4개라서","mis":"M2-1-u1-X03"}],"explanation":["100, 200, 300, 400이에요.","400은 100이 4개예요.","그래서 맞는 말이에요."]},{"stem":"100이 3개인 수는 30이에요.","answer":"X","reason_options":[{"t":"100이 3개이면 300이니까","correct":true},{"t":"개수 3 뒤에 0을 하나 붙이면 되니까","mis":"M2-1-u1-X03"}],"explanation":["100씩 3번 — 100, 200, 300이에요.","100이 3개인 수는 300이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#9','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'mc','auto','300보다 100만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":9,"concept":"M2-1-u1-C2","difficulty":2,"kind":"mc","stem":"300보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"400","correct":true},{"t":"310","mis":"M2-1-u1-X12"},{"t":"301","mis":"M2-1-u1-X12"}],"explanation":["100만큼 더 크면 백의 자리 숫자가 1 커져요.","300보다 100 큰 수는 400이에요.","10만큼·1만큼과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"700보다 100만큼 더 작은 수는 무엇인가요?","options":[{"t":"600","correct":true},{"t":"690","mis":"M2-1-u1-X12"},{"t":"800","mis":"M2-1-u1-X12"}],"explanation":["100만큼 작으면 백의 자리 숫자가 1 작아져요.","700보다 100 작은 수는 600이에요.","「작은」인지 「큰」인지 잘 읽어요."]},{"stem":"500보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"600","correct":true},{"t":"510","mis":"M2-1-u1-X12"},{"t":"501","mis":"M2-1-u1-X12"}],"explanation":["100만큼 더 크면 백의 자리 숫자가 1 커져요.","500보다 100 큰 수는 600이에요.","10만큼·1만큼과 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#10','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',3,'mc','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":10,"concept":"M2-1-u1-C2","difficulty":3,"kind":"mc","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"700","correct":true},{"t":"610","mis":"M2-1-u1-X11"},{"t":"601","mis":"M2-1-u1-X11"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","600에서 100만큼 뛰면 700이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[300,400,500,600,null],"step":100},"variant_rule":{"skip3":{"ask":"next","step":[100]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#1','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C7',2,'mc','auto','340은 10이 몇 개인가요?',ARRAY['M2-1-u1-X10','M2-1-u1-X03']::text[],true,'{"seq":1,"concept":"M2-1-u1-C7","difficulty":2,"kind":"mc","stem":"340은 10이 몇 개인가요?","options":[{"t":"34","correct":true},{"t":"4","mis":"M2-1-u1-X10"},{"t":"3","mis":"M2-1-u1-X03"}],"explanation":["340은 100이 3개, 10이 4개예요.","100 하나는 10이 10개 — 10이 30개와 4개, 모두 34개예요.","100 속에도 10이 10개 들어 있어요."],"variant_rule":{"n3":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#2','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',2,'error','auto','친구들이 600에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X03','M2-1-u1-X07','M2-1-u1-X12']::text[],true,'{"seq":2,"concept":"M2-1-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 600에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우: 600은 100이 60개야.","correct":true,"mis_target":"M2-1-u1-X03"},{"t":"하린: 600은 「육백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"도윤: 600은 500보다 100 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["600은 백의 자리 숫자가 6이에요.","그래서 100이 6개예요 — 60개가 아니에요.","은우가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"친구들이 300에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온: 300은 100이 3개니까 103이라고 써.","correct":true,"mis_target":"M2-1-u1-X03"},{"t":"서준: 300은 「삼백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"지아: 300은 200보다 100 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["100이 3개이면 300이에요.","개수를 일의 자리에 붙여 103으로 쓰지 않아요.","라온이 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#3','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C7',3,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":3,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"400원","correct":true},{"t":"3100원","mis":"M2-1-u1-X10"},{"t":"310원","mis":"M2-1-u1-X10"}],"explanation":["10원짜리 10개는 100원짜리 1개와 같아요.","100원짜리가 3개와 1개 — 400원이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":3,"t":10,"o":0,"unit":"coin"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동전은 모두 얼마인가요?","options":[{"t":"600원","correct":true},{"t":"5100원","mis":"M2-1-u1-X10"},{"t":"510원","mis":"M2-1-u1-X10"}],"explanation":["10원짜리 10개는 100원짜리 1개와 같아요.","100원짜리가 5개와 1개 — 600원이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":5,"t":10,"o":0,"unit":"coin"}},{"stem":"이번에는 다른 보기예요. 동전은 모두 얼마인가요?","options":[{"t":"290원","correct":true},{"t":"1190원","mis":"M2-1-u1-X10"},{"t":"190원","mis":"M2-1-u1-X10"}],"explanation":["10원짜리 19개는 100원짜리 1개와 10원짜리 9개로 바꿀 수 있어요.","100원짜리가 2개, 10원짜리가 9개 — 290원이에요.","10개씩 묶어 윗자리로 바꿔요."],"asset":{"type":"blocks3","h":1,"t":19,"o":0,"unit":"coin"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#4','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',3,'sa','auto','공책이 한 상자에 100권씩 들어 있어요. 7상자에는 공책이 모두 몇 권인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u1-C2","difficulty":3,"kind":"sa","stem":"공책이 한 상자에 100권씩 들어 있어요. 7상자에는 공책이 모두 몇 권인가요?","answer":["700","700권"],"explanation":["한 상자에 100권씩이에요.","100이 7개이면 700이에요.","100씩 세어 보세요 — 100, 200, … 700."],"variant_rule":{"alt":[{"stem":"귤이 한 상자에 100개씩 들어 있어요. 4상자에는 귤이 모두 몇 개인가요?","answer":["400","400개"],"explanation":["한 상자에 100개씩이에요.","100이 4개이면 400이에요.","100씩 세어 보세요."]},{"stem":"색종이가 한 묶음에 100장씩 있어요. 9묶음은 모두 몇 장인가요?","answer":["900","900장"],"explanation":["한 묶음에 100장씩이에요.","100이 9개이면 900이에요.","100씩 세어 보세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#5','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C7',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":5,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"300","correct":true},{"t":"2100","mis":"M2-1-u1-X10"},{"t":"210","mis":"M2-1-u1-X10"}],"explanation":["십 모형 10개는 백 모형 1개와 같아요.","백 모형이 2개와 1개 — 300이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":2,"t":10,"o":0},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#6','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',3,'mc','auto','800은 400보다 100이 몇 개 더 많은가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X03']::text[],true,'{"seq":6,"concept":"M2-1-u1-C2","difficulty":3,"kind":"mc","stem":"800은 400보다 100이 몇 개 더 많은가요?","options":[{"t":"4","correct":true},{"t":"400","mis":"M2-1-u1-X09"},{"t":"40","mis":"M2-1-u1-X03"}],"explanation":["800은 100이 8개, 400은 100이 4개예요.","8은 4보다 4 커요.","그래서 100이 4개 더 많아요."],"variant_rule":{"alt":[{"stem":"900은 600보다 100이 몇 개 더 많은가요?","options":[{"t":"3","correct":true},{"t":"300","mis":"M2-1-u1-X09"},{"t":"30","mis":"M2-1-u1-X03"}],"explanation":["900은 100이 9개, 600은 100이 6개예요.","9는 6보다 3 커요.","그래서 100이 3개 더 많아요."]},{"stem":"700은 200보다 100이 몇 개 더 많은가요?","options":[{"t":"5","correct":true},{"t":"500","mis":"M2-1-u1-X09"},{"t":"50","mis":"M2-1-u1-X03"}],"explanation":["700은 100이 7개, 200은 100이 2개예요.","7은 2보다 5 커요.","그래서 100이 5개 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#7','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',3,'ox','auto','100이 10개이면 1000이에요.',ARRAY['M2-1-u1-X02']::text[],true,'{"seq":7,"concept":"M2-1-u1-C2","difficulty":3,"kind":"ox","stem":"100이 10개이면 1000이에요.","answer":"O","reason_options":[{"t":"100이 10개 모이면 천이 되니까","correct":true},{"t":"100이 10개면 10010이니까","mis":"M2-1-u1-X02"}],"mis":"M2-1-u1-X02","explanation":["100씩 10번 세면 100, 200, … 900, 1000이에요.","100이 10개이면 1000(천)이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"900보다 100 큰 수는 9100이에요.","answer":"X","reason_options":[{"t":"900보다 100 큰 수는 1000이니까","correct":true},{"t":"9 다음에 100을 붙이면 되니까","mis":"M2-1-u1-X01"}],"explanation":["100이 9개에 1개를 더하면 10개예요.","100이 10개이면 1000이에요.","숫자를 이어 붙이지 않아요."]},{"stem":"1000은 100이 10개인 수예요.","answer":"O","reason_options":[{"t":"100씩 10번 세면 1000이니까","correct":true},{"t":"1000은 100이 1개라서","mis":"M2-1-u1-X02"}],"explanation":["100, 200, … 1000 — 10번이에요.","1000은 100이 10개예요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#8','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',4,'mc','auto','어떤 수는 100이 4개인 수보다 100이 3개 더 많아요. 어떤 수는 무엇인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":8,"concept":"M2-1-u1-C2","difficulty":4,"kind":"mc","stem":"어떤 수는 100이 4개인 수보다 100이 3개 더 많아요. 어떤 수는 무엇인가요?","options":[{"t":"700","correct":true},{"t":"430","mis":"M2-1-u1-X03"},{"t":"403","mis":"M2-1-u1-X03"}],"explanation":["100이 4개에 3개가 더 많으면 100이 7개예요.","100이 7개인 수는 700이에요.","100의 개수는 모두 백의 자리에 모여요."],"variant_rule":{"alt":[{"stem":"어떤 수는 100이 8개인 수보다 100이 2개 더 적어요. 어떤 수는 무엇인가요?","options":[{"t":"600","correct":true},{"t":"820","mis":"M2-1-u1-X03"},{"t":"1000","mis":"M2-1-u1-X15"}],"explanation":["100이 8개에서 2개가 적으면 100이 6개예요.","100이 6개인 수는 600이에요.","「적어요」를 잘 읽어요."]},{"stem":"어떤 수는 100이 2개인 수보다 100이 5개 더 많아요. 어떤 수는 무엇인가요?","options":[{"t":"700","correct":true},{"t":"250","mis":"M2-1-u1-X03"},{"t":"205","mis":"M2-1-u1-X03"}],"explanation":["100이 2개에 5개가 더 많으면 100이 7개예요.","100이 7개인 수는 700이에요.","100의 개수는 모두 백의 자리에 모여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#9','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',4,'mc','auto','100원짜리 동전으로 900원을 내려고 해요. 지금 100원짜리가 5개 있다면 몇 개가 더 있어야 하나요?',ARRAY['M2-1-u1-X09','M2-1-u1-X15']::text[],true,'{"seq":9,"concept":"M2-1-u1-C2","difficulty":4,"kind":"mc","stem":"100원짜리 동전으로 900원을 내려고 해요. 지금 100원짜리가 5개 있다면 몇 개가 더 있어야 하나요?","options":[{"t":"4","correct":true},{"t":"400","mis":"M2-1-u1-X09"},{"t":"9","mis":"M2-1-u1-X15"}],"explanation":["900원은 100원짜리 9개예요.","5개가 있으니 9개가 되려면 4개 더 — 6, 7, 8, 9로 세어요.","묻는 것은 동전 「개수」예요."],"variant_rule":{"alt":[{"stem":"100원짜리 동전으로 800원을 내려고 해요. 지금 100원짜리가 3개 있다면 몇 개가 더 있어야 하나요?","options":[{"t":"5","correct":true},{"t":"500","mis":"M2-1-u1-X09"},{"t":"8","mis":"M2-1-u1-X15"}],"explanation":["800원은 100원짜리 8개예요.","3개가 있으니 5개 더 있어야 해요.","묻는 것은 동전 「개수」예요."]},{"stem":"100원짜리 동전으로 700원을 내려고 해요. 지금 100원짜리가 6개 있다면 몇 개가 더 있어야 하나요?","options":[{"t":"1","correct":true},{"t":"100","mis":"M2-1-u1-X09"},{"t":"7","mis":"M2-1-u1-X15"}],"explanation":["700원은 100원짜리 7개예요.","6개가 있으니 1개 더 있어야 해요.","묻는 것은 동전 「개수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#10','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C7',4,'essay','teacher','500을 「100이 몇 개」와 「10이 몇 개」 두 가지로 나타내고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u1-C7","difficulty":4,"kind":"essay","stem":"500을 「100이 몇 개」와 「10이 몇 개」 두 가지로 나타내고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"100이 5개, 10이 50개. 100 하나는 10이 10개이므로 100이 5개는 10이 50개이다.","scoring_points":["100이 5개라고 썼는가","10이 50개라고 썼는가","100 하나가 10이 10개라는 까닭을 말했는가"]},"explanation":["500은 백의 자리 숫자가 5 — 100이 5개예요.","100 하나는 10이 10개이니 10이 50개예요.","한 수를 여러 묶음으로 나타낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#1','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X06','M2-1-u1-X05']::text[],true,'{"seq":1,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"254","correct":true},{"t":"452","mis":"M2-1-u1-X06"},{"t":"200504","mis":"M2-1-u1-X05"}],"explanation":["100이 2개, 10이 5개, 1이 4개예요.","백의 자리 2, 십의 자리 5, 일의 자리 4 — 254예요.","백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks3","h":2,"t":5,"o":4},"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#2','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',1,'sa','auto','100이 3개, 10이 4개, 1이 7개인 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u1-C3","difficulty":1,"kind":"sa","stem":"100이 3개, 10이 4개, 1이 7개인 수는 무엇인가요?","answer":["347"],"explanation":["100이 3개, 10이 4개, 1이 7개예요.","백의 자리 3, 십의 자리 4, 일의 자리 7 — 347이에요.","백·십·일 차례로 숫자를 써요."],"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#3','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',1,'mc','auto','254를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07']::text[],true,'{"seq":3,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"254를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"이백오십사","correct":true},{"t":"이오사","mis":"M2-1-u1-X07"},{"t":"이백오사","mis":"M2-1-u1-X07"}],"explanation":["254는 백의 자리 2, 십의 자리 5, 일의 자리 4예요.","「이백오십사」라고 읽어요.","숫자 뒤에 자리 이름(백·십)을 붙여 읽어요."],"variant_rule":{"n3":{"ask":"read"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#4','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',1,'mc','auto','「육백삼십오」를 수로 쓰면 무엇인가요?',ARRAY['M2-1-u1-X05','M2-1-u1-X06']::text[],true,'{"seq":4,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"「육백삼십오」를 수로 쓰면 무엇인가요?","options":[{"t":"635","correct":true},{"t":"600305","mis":"M2-1-u1-X05"},{"t":"536","mis":"M2-1-u1-X06"}],"explanation":["「육백삼십오」는 100이 6개, 10이 3개, 1이 5개예요.","수로 쓰면 635예요.","읽은 소리를 그대로 이어 쓰지 않아요 — 세 자리에 숫자 하나씩."],"variant_rule":{"n3":{"ask":"write"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#5','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'mc','auto','100이 5개, 1이 3개인 수는 무엇인가요?',ARRAY['M2-1-u1-X04','M2-1-u1-X05']::text[],true,'{"seq":5,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"100이 5개, 1이 3개인 수는 무엇인가요?","options":[{"t":"503","correct":true},{"t":"53","mis":"M2-1-u1-X04"},{"t":"5003","mis":"M2-1-u1-X05"}],"explanation":["100이 5개, 1이 3개예요 — 10은 없어요.","백의 자리 5, 십의 자리 0, 일의 자리 3 — 503이에요.","없는 자리에는 0을 써서 자리를 지켜요."],"variant_rule":{"n3":{"ask":"build","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#6','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'mc','auto','507을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07']::text[],true,'{"seq":6,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"507을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"오백칠","correct":true},{"t":"오백영칠","mis":"M2-1-u1-X07"},{"t":"오영칠","mis":"M2-1-u1-X07"}],"explanation":["507은 백의 자리 5, 십의 자리 0, 일의 자리 7이에요.","「오백칠」이라고 읽어요.","0이 있는 자리는 읽지 않아요."],"variant_rule":{"n3":{"ask":"read","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#7','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X06']::text[],true,'{"seq":7,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"236원","correct":true},{"t":"632원","mis":"M2-1-u1-X06"},{"t":"326원","mis":"M2-1-u1-X06"}],"explanation":["100원짜리가 2개, 10원짜리가 3개, 1원짜리가 6개예요.","백의 자리 2, 십의 자리 3, 일의 자리 6 — 236원이에요.","큰 동전부터 차례로 세어요."],"asset":{"type":"blocks3","h":2,"t":3,"o":6,"unit":"coin"},"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#8','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'ox','auto','「구백이」를 수로 쓰면 92예요.',ARRAY['M2-1-u1-X04']::text[],true,'{"seq":8,"concept":"M2-1-u1-C3","difficulty":2,"kind":"ox","stem":"「구백이」를 수로 쓰면 92예요.","answer":"X","reason_options":[{"t":"십의 자리에 0을 써서 902이니까","correct":true},{"t":"읽은 숫자만 쓰면 되니까","mis":"M2-1-u1-X04"}],"mis":"M2-1-u1-X04","explanation":["「구백이」는 100이 9개, 1이 2개예요.","십의 자리에 0을 써서 902예요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"「삼백사십」을 수로 쓰면 340이에요.","answer":"O","reason_options":[{"t":"일의 자리에 0을 써서 340이니까","correct":true},{"t":"읽지 않은 자리는 쓰지 않으니까 34라서","mis":"M2-1-u1-X04"}],"explanation":["「삼백사십」은 100이 3개, 10이 4개예요.","일의 자리에 0을 써서 340이에요.","그래서 맞는 말이에요."]},{"stem":"「육백팔」을 수로 쓰면 6008이에요.","answer":"X","reason_options":[{"t":"세 자리 수는 숫자가 세 개라 608이니까","correct":true},{"t":"육백은 600, 팔은 8이라 이어 쓰니까","mis":"M2-1-u1-X05"}],"explanation":["「육백팔」은 100이 6개, 1이 8개예요.","십의 자리에 0을 써서 608이에요.","읽은 소리를 이어 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#9','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u1-C3","difficulty":2,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"346","r":"삼백사십육"},{"l":"306","r":"삼백육"},{"l":"360","r":"삼백육십"}],"mis":"M2-1-u1-X04","explanation":["346은 삼백사십육, 306은 삼백육이에요.","360은 삼백육십이에요.","0인 자리는 읽지 않아요 — 어느 자리가 0인지 잘 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"815","r":"팔백십오"},{"l":"805","r":"팔백오"},{"l":"850","r":"팔백오십"}],"explanation":["815는 팔백십오, 805는 팔백오예요.","850은 팔백오십이에요.","0인 자리는 읽지 않아요."]},{"stem":"이번에는 다른 보기예요. 수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"472","r":"사백칠십이"},{"l":"427","r":"사백이십칠"},{"l":"742","r":"칠백사십이"}],"explanation":["472는 사백칠십이, 427은 사백이십칠이에요.","742는 칠백사십이예요.","자리 순서를 섞지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#10','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C7',3,'mc','auto','구슬이 100개씩 2상자, 10개씩 4봉지, 낱개 13개 있어요. 구슬은 모두 몇 개인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":10,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"구슬이 100개씩 2상자, 10개씩 4봉지, 낱개 13개 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"253","correct":true},{"t":"2413","mis":"M2-1-u1-X10"},{"t":"243","mis":"M2-1-u1-X10"}],"explanation":["낱개 13개는 10개씩 1봉지와 낱개 3개로 바꿀 수 있어요.","그러면 100이 2개, 10이 5개, 1이 3개 — 253이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."],"variant_rule":{"alt":[{"stem":"구슬이 100개씩 3상자, 10개씩 12봉지, 낱개 5개 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"425","correct":true},{"t":"3125","mis":"M2-1-u1-X10"},{"t":"325","mis":"M2-1-u1-X10"}],"explanation":["10개씩 12봉지는 100개 1상자와 10개씩 2봉지예요.","그러면 100이 4개, 10이 2개, 1이 5개 — 425예요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]},{"stem":"색종이가 100장씩 1묶음, 10장씩 6묶음, 낱장 14장 있어요. 모두 몇 장인가요?","options":[{"t":"174","correct":true},{"t":"1614","mis":"M2-1-u1-X10"},{"t":"164","mis":"M2-1-u1-X10"}],"explanation":["낱장 14장은 10장씩 1묶음과 낱장 4장이에요.","그러면 100이 1개, 10이 7개, 1이 4개 — 174예요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
